  let um='';if(!o.sea){um=`<line x1="-40" y1="-50" x2="-40" y2="100" ${st(C.navy,6)}/><path d="M-110 -34 Q-40 -120 30 -34 Z" fill="${C.red}" ${st()}/><path d="M-110 -34 Q-86 -92 -40 -80 Q-62 -62 -62 -34Z M-18 -34 Q-18 -62 -40 -80 Q-4 -88 30 -34Z" fill="${C.cream}" ${st(C.navy,3)}/>`}
