  if(k==='writer')front=`<g transform="translate(0,66)"><path d="M0 -26 Q-34 -40 -66 -28 V34 Q-34 22 0 38 Q34 22 66 34 V-28 Q34 -40 0 -26Z" fill="${C.paper}" ${st(C.navy,4)}/><line x1="0" y1="-26" x2="0" y2="38" ${st(C.navy,3)}/><path d="M-52 -8 h40 M-52 8 h40 M12 -8 h40 M12 8 h40" ${st('#9AA7B0',3)}/></g><g transform="translate(58,34) rotate(40)"><rect x="-6" y="-48" width="12" height="70" rx="3" fill="${C.gold}" ${st()}/><path d="M-6 22 L0 40 L6 22Z" fill="${C.cream}" ${st()}/></g>`;
