/* ---------- fish ---------- */
const _e11fish=(x,y,s,c1,c2,dir,T,ph)=>{const wg=Math.sin(T*9+ph)*7;
  return `<g transform="translate(${f(x)},${f(y)}) scale(${f(s*dir)},${f(s)})"><path d="M-28 0 L${f(-64)} ${f(-22+wg)} L${f(-64)} ${f(22+wg)}Z" fill="${c2}" ${st(C.navy,4)}/><path d="M-10 -18 Q6 -42 24 -18Z" fill="${c2}" ${st(C.navy,4)}/><ellipse rx="38" ry="23" fill="${c1}" ${st(C.navy,4)}/><path d="M12 -20 Q22 0 12 20" fill="none" ${st(c2,8)} opacity=".9"/><path d="M-12 8 Q4 26 14 12" fill="none" ${st(C.navy,3)} opacity=".35"/></g>`};
P.e11_fish=(o,T)=>{const n=o.n==null?3:o.n,F=[['#F2994A','#F6CE4B',0],['#F6CE4B','#F2994A',2.1],['#F2994A','#F6CE4B',4.2]];let fs='';
  const sw=(i)=>Math.sin(T*.9+F[i][2]),dr=(i)=>Math.cos(T*.9+F[i][2])>=0?1:-1;
  if(o.bowl===0){const pos=[[0,-70],[-20,0],[20,74]];let bb='';for(let i=0;i<3;i++){const ph=(T*.7+i/3)%1;bb+=`<circle cx="${f(-70+i*70)}" cy="${f(-60-ph*50)}" r="${4+i*2}" fill="none" ${st(C.blue,3)} opacity="${f(1-ph)}"/>`}
    for(let i=0;i<n;i++)fs+=_e11fish(pos[i][0]+sw(i)*40,pos[i][1],1.0,F[i][0],F[i][1],dr(i),T,F[i][2]);return `<g>${bb}${fs}</g>`}
  const pos=[[0,-24],[-8,16],[10,50]];
  for(let i=0;i<n;i++)fs+=_e11fish(pos[i][0]+sw(i)*16,pos[i][1]+Math.sin(T*1.3+i)*4,.62,F[i][0],F[i][1],dr(i),T,F[i][2]);
  let pl='';[[-52,1],[-34,2]].forEach(([x,ph])=>{pl+=`<path d="M${x} 80 q${f(Math.sin(T*2+ph)*8)} -30 0 -52 q${f(Math.sin(T*2+ph)*-8)} -18 6 -34" fill="none" ${st(C.leaf,7)}/>`});
  return `<g><clipPath id="e11bw"><circle cx="0" cy="6" r="88"/></clipPath><circle cx="0" cy="6" r="92" fill="#E3F4FB" ${st()}/><g clip-path="url(#e11bw)"><rect x="-96" y="-50" width="192" height="160" fill="#9ED3EC"/><path d="M-96 -50 q24 -8 48 0 t48 0 t48 0 t48 0" fill="none" ${st('#fff',3)} opacity=".8"/><ellipse cx="0" cy="92" rx="90" ry="22" fill="#D9C79A"/>${pl}${fs}</g><circle cx="0" cy="6" r="92" fill="none" ${st()}/><path d="M-68 -40 q10 -26 34 -34" fill="none" ${st('#fff',6)} opacity=".8"/></g>`};

/* ---------- aquarium: level, flow out / in, food flakes ---------- */
P.e11_tank=(o,T,k)=>{let lv=o.level==null?.82:o.level;const fl=o.flow;
  if(fl==='out')lv=.86-.4*ease(k/1.8);else if(fl==='in')lv=.46+.4*ease(k/1.8);
  const top=80-150*lv;let ex='';
  if(fl==='out'){for(let i=0;i<4;i++){const ph=(T*1.3+i/4)%1;ex+=`<path d="M${f(118+ph*8)} ${f(40+ph*50)} q-6 10 0 16 q6 -6 0 -16" fill="${C.blue}" opacity="${f(1-ph)}"/>`}
    ex+=`<g transform="translate(150,10)"><path d="M-10 -24 H14 V12 H28 L2 44 L-24 12 H-10Z" fill="${C.red}" ${st()}/></g><rect x="104" y="30" width="22" height="12" fill="#E3F4FB" ${st(C.navy,4)}/>`}
  if(fl==='in'){for(let i=0;i<4;i++){const ph=(T*1.6+i/4)%1;ex+=`<path d="M0 ${f(-120+ph*(top+120))} q-6 10 0 16 q6 -6 0 -16" fill="${C.blue}" opacity="${f(.5+.5*(1-ph))}"/>`}
    ex+=`<g transform="translate(0,-104)"><path d="M-12 -22 H12 V4 H28 L0 38 L-28 4 H-12Z" fill="${C.moss}" ${st()}/></g>`}
  if(o.food){for(let i=0;i<9;i++){const ph=(T*.5+i*.13)%1;ex+=`<circle cx="${f(-70+((i*53)%140)+Math.sin(T+i)*5)}" cy="${f(-100+ph*(top+100))}" r="5" fill="#E3A13B" ${st('#9A6A1E',2)}/>`}}
  if(o.mark!==0&&fl==='out')ex+=`<line x1="-110" y1="5" x2="110" y2="5" ${st(C.red,3)} stroke-dasharray="9 8" opacity=".8"/>`;
  const fish=lv>.1?_e11fish(Math.sin(T*.8)*34,Math.max(top+24,Math.min(60,10+Math.sin(T*1.1)*14)),.66,'#F2994A','#F6CE4B',Math.cos(T*.8)>=0?1:-1,T,0)+_e11fish(Math.sin(T*.8+2.4)*34,Math.max(top+24,Math.min(62,40+Math.sin(T+1)*10)),.56,'#F6CE4B','#F2994A',Math.cos(T*.8+2.4)>=0?1:-1,T,2):'';
  return `<g><clipPath id="e11tk"><rect x="-104" y="-70" width="208" height="150" rx="10"/></clipPath><rect x="-110" y="-76" width="220" height="162" rx="14" fill="#E3F4FB" ${st()}/><g clip-path="url(#e11tk)"><rect x="-104" y="${f(top)}" width="208" height="${f(80-top+10)}" fill="#9ED3EC"/>${lv>.05?`<path d="M-104 ${f(top)} q26 -6 52 0 t52 0 t52 0 t52 0" fill="none" ${st('#fff',3)} opacity=".85"/>`:''}<rect x="-104" y="62" width="208" height="20" fill="#D9C79A"/>${fish}</g><rect x="-110" y="-76" width="220" height="162" rx="14" fill="none" ${st()}/>${ex}${o.clean?P.sparkle({},T):''}</g>`};

