/* ---------- plants ---------- */
P.e11_plant=(o,T)=>{const sw=Math.sin(T*1.4)*2.5;const lv=[[-60,-34,-40,56,24],[0,-84,0,64,28],[62,-30,36,58,24],[-30,-70,-18,52,22],[34,-66,22,52,22]];let L='';
  const mask=o.bite?`<mask id="e11pm"><rect x="-140" y="-140" width="280" height="200" fill="#fff"/><circle cx="-84" cy="-48" r="22" fill="#000"/><circle cx="86" cy="-44" r="18" fill="#000"/><circle cx="-18" cy="-114" r="16" fill="#000"/></mask>`:'';
  lv.forEach(([x,y,rot,ry,rx],i)=>{L+=`<g transform="translate(${x},${y}) rotate(${f(rot+sw*(i%2?1:-1))})"><ellipse rx="${rx}" ry="${ry}" fill="${C.leaf}" ${st(C.navy,4)}/><line x1="0" y1="${ry-8}" x2="0" y2="${-ry+10}" ${st('#3F7A47',3)}/></g>`});
  const bird=o.bird?`<g transform="translate(46,-66) scale(.42)">${P.e11_bird({perch:0},T)}</g>`:'';
  return `<g>${mask}<g ${o.bite?'mask="url(#e11pm)"':''}><path d="M0 50 L0 10 M0 40 L-40 -10 M0 40 L40 -10" fill="none" ${st('#3F7A47',7)}/>${L}</g>${bird}<path d="M-56 44 H56 L44 106 Q0 118 -44 106Z" fill="#C9792E" ${st()}/><rect x="-62" y="36" width="124" height="18" rx="6" fill="#D98A3B" ${st()}/></g>`};
P.e11_highplant=(o,T)=>{const d=((T*1.2)%1)*10;
  return `<g><rect x="-100" y="-40" width="200" height="14" rx="4" fill="${C.brown}" ${st()}/><path d="M-76 -26 V-4 M76 -26 V-4" ${st(C.navy,5)}/><g transform="translate(0,-82) scale(.36)">${P.e11_plant({},T)}</g><g transform="translate(0,${f(14-d)}) scale(.46)"><path d="M-14 24 V-14 H-30 L0 -50 L30 -14 H14 V24Z" fill="${C.moss}" ${st()}/></g><g transform="translate(0,66) scale(.42)">${P.e11_cat({},T)}</g><line x1="-112" y1="108" x2="112" y2="108" ${st('#9AA7B0',5)}/></g>`};

/* ---------- bowls, cup ---------- */
P.e11_bowl=(o,T)=>{const w=o.k==='water';let c='';
  if(w){c=`<ellipse cx="0" cy="-6" rx="70" ry="16" fill="#9ED3EC" ${st(C.navy,3)}/><path d="M-36 -8 q12 -6 24 0 t24 0" fill="none" ${st('#fff',3)} opacity=".9"/>`}
  else{const kib=[[-46,-6],[-26,-14],[-6,-8],[16,-16],[36,-6],[52,-12],[-36,-20],[-12,-22],[10,-24],[30,-22],[-2,-30],[-22,-32],[20,-34]];c=kib.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="9" fill="${i%2?'#B5703A':'#9A5A2A'}" ${st(C.navy,2.5)}/>`).join('')+`<ellipse cx="0" cy="-2" rx="70" ry="14" fill="none"/>`}
  if(o.over&&!w){c+=[[-80,14],[84,20],[-98,4],[100,8]].map(([x,y])=>`<circle cx="${x}" cy="${y+30}" r="8" fill="#B5703A" ${st(C.navy,2.5)}/>`).join('')}
  return `<g><ellipse cx="0" cy="62" rx="84" ry="14" fill="#000" opacity=".12"/>${w?c:''}<path d="M-84 -4 H84 L66 60 Q0 76 -66 60Z" fill="${C.red}" ${st()}/>${w?'':c}<path d="M-84 -4 H84" ${st(C.navy,5)}/><ellipse cx="0" cy="34" rx="12" ry="9" fill="${C.cream}"/><circle cx="-18" cy="20" r="4.5" fill="${C.cream}"/><circle cx="0" cy="16" r="4.5" fill="${C.cream}"/><circle cx="18" cy="20" r="4.5" fill="${C.cream}"/></g>`};
P.e11_cup=(o,T)=>{const lv=o.f==null?.5:o.f,top=80-170*lv;let ticks='';for(let i=1;i<4;i++)ticks+=`<line x1="-48" y1="${f(80-i*42.5)}" x2="${i===2?-24:-34}" y2="${f(80-i*42.5)}" ${st(C.navy,3)}/>`;
  return `<g><clipPath id="e11cp"><path d="M-52 -92 H52 L46 84 H-46Z"/></clipPath><path d="M-52 -92 H52 L46 84 H-46Z" fill="#EAF6FB" ${st()}/><g clip-path="url(#e11cp)"><rect x="-60" y="${f(top)}" width="120" height="${f(100-top)}" fill="#E3B26B"/><path d="M-60 ${f(top)} h120" ${st('#9A6A1E',3)}/>${[[-26,8],[4,24],[24,0],[-8,40]].map(([x,y])=>`<circle cx="${x}" cy="${f(top+16+y)}" r="5" fill="#B5703A"/>`).join('')}</g><path d="M-52 -92 H52 L46 84 H-46Z" fill="none" ${st()}/>${ticks}<path d="M52 -62 q46 0 46 38 q0 38 -48 38" fill="none" ${st(C.navy,8)}/><text x="-62" y="${f(top+10)}" text-anchor="end" font-family="Fraunces" font-weight="800" font-size="30" fill="${C.navy}">${o.label==null?'1/2':o.label}</text></g>`};

/* ---------- hair on clothes, lint roller ---------- */
const _e11strand=(x,y,rot,c,s)=>`<g transform="translate(${x},${y}) rotate(${rot}) scale(${s})"><path d="M-22 0 C-12 -16 -2 14 8 -2 C14 -12 20 -4 24 -8" fill="none" ${st(C.navy,7)}/><path d="M-22 0 C-12 -16 -2 14 8 -2 C14 -12 20 -4 24 -8" fill="none" stroke="${c}" stroke-width="3.6" stroke-linecap="round"/></g>`;
P.e11_strands=(o,T)=>{const S=[[-60,-40,-20,_e11W],[10,-60,12,_e11Y],[60,-20,-30,_e11W],[-30,10,30,_e11Y],[34,24,-12,_e11W],[-70,50,8,_e11W],[70,64,24,_e11Y],[-8,66,-24,_e11W]];return `<g transform="translate(0,${f(Math.sin(T*1.5)*3)})">${S.map(([x,y,r,c])=>_e11strand(x,y,r,c,1.7)).join('')}</g>`};
P.e11_hair=(o,T)=>{const tee='M-44 -84 L-92 -52 L-72 -6 L-46 -22 L-46 88 L46 88 L46 -22 L72 -6 L92 -52 L44 -84 Q0 -58 -44 -84Z';
  const S=[[-30,-30,-20,_e11W],[10,-46,14,_e11Y],[26,6,-30,_e11W],[-18,34,26,_e11Y],[-62,-30,12,_e11W],[60,-34,-8,_e11Y],[-8,64,-18,_e11W],[40,56,22,_e11Y]];
  const roll=o.roller?`<g transform="translate(${f(30+Math.sin(T*2.4)*26)},${f(10)}) rotate(-24)"><rect x="-8" y="-40" width="16" height="66" rx="6" fill="${C.gold}" ${st()}/><path d="M0 26 V74" ${st(C.navy,8)}/><rect x="-14" y="74" width="28" height="32" rx="10" fill="${C.red}" ${st()}/><rect x="-44" y="-68" width="88" height="36" rx="14" fill="#fff" ${st()}/><path d="M-30 -50 h60" ${st('#E3B26B',5)}/></g>`:'';
  return `<g><path d="${tee}" fill="#2B3036" ${st()}/><path d="M-28 -78 Q0 -52 28 -78" fill="none" ${st('#4A5058',5)}/>${S.map(([x,y,r,c])=>_e11strand(x,y,r,c,1.15)).join('')}${roll}</g>`};

/* ---------- people and cats together ---------- */
P.e11_kidcat=(o,T)=>{return `<g><g transform="translate(-58,34) scale(.56)">${P.person({c:'#F2994A',hair:'short',hc:'#3A2A22',ph:1},T)}</g><g transform="translate(56,26) scale(.6)">${P.e11_cat({},T)}</g><g transform="translate(2,-70) scale(.5)">${P.heart({},T)}</g></g>`};
P.e11_catbed=(o,T)=>{const sl=o.sleep;const mouse=o.mouse?`<g transform="translate(-70,100) scale(.36)">${P.e11_mouse({flip:0},T)}</g>`:'';
  return `<g><g transform="translate(0,6) scale(.92)">${P.bed({},T)}</g>${sl?`<g transform="translate(14,-4) scale(.5)">${P.e11_cat({pose:'sleep'},T)}</g>`:`<g transform="translate(26,-18) scale(.5)">${P.e11_cat({},T)}</g>`}${mouse}</g>`};
P.e11_wave=(o,T)=>{const a=o.still?0:Math.sin(T*6)*14;let m='';if(!o.still)for(let i=0;i<2;i++){const ph=(T*1.6+i/2)%1;m+=`<path d="M${f(-70-ph*20)} -60 q-12 24 0 48" fill="none" ${st(C.blue,6)} opacity="${f(1-ph)}"/><path d="M${f(70+ph*20)} -60 q12 24 0 48" fill="none" ${st(C.blue,6)} opacity="${f(1-ph)}"/>`}
  const fin=[[-30,-12,-8],[-10,-28,-2],[10,-30,2],[30,-22,8]].map(([x,y,r])=>`<rect x="${x-9}" y="${y-48}" width="18" height="66" rx="9" fill="#E3AE82" ${st()} transform="rotate(${r} ${x} ${y+10})"/>`).join('');
  return `<g>${m}<g transform="rotate(${f(a)} 0 90)"><path d="M-40 100 L-34 52 L34 52 L40 100Z" fill="${C.red}" ${st()}/>${fin}<rect x="-44" y="-8" width="88" height="68" rx="26" fill="#E3AE82" ${st()}/><rect x="-62" y="12" width="20" height="46" rx="10" fill="#E3AE82" ${st()} transform="rotate(30 -52 34)"/></g></g>`};
P.e11_wash=(o,T)=>{let d='';for(let i=0;i<5;i++){const ph=(T*1.8+i/5)%1;d+=`<path d="M${-6+((i*5)%12)} ${f(-48+ph*88)} q-4 8 0 12 q4 -4 0 -12" fill="${C.blue}" opacity="${f(1-ph*.6)}"/>`}
  let b='';[[-70,-10,14],[64,-30,10],[80,20,16],[-84,40,10],[-50,-60,8],[44,-70,12]].forEach(([x,y,r],i)=>{const m=Math.sin(T*2.2+i)*5;b+=`<g transform="translate(${x},${f(y+m)})"><circle r="${r}" fill="#EAF6FB" ${st(C.cold,3)} opacity=".9"/><path d="M${-r*.5} ${-r*.2} q${r*.2} ${-r*.5} ${r*.6} ${-r*.5}" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round"/></g>`});
  const hand=(sx)=>`<g transform="translate(${sx*34},58) rotate(${sx*-12}) scale(${sx},1)"><rect x="-14" y="-46" width="14" height="52" rx="7" fill="#E3AE82" ${st()}/><rect x="2" y="-52" width="14" height="58" rx="7" fill="#E3AE82" ${st()}/><rect x="-30" y="-36" width="14" height="44" rx="7" fill="#E3AE82" ${st()} transform="rotate(-8 -23 -14)"/><rect x="-26" y="-6" width="52" height="46" rx="18" fill="#E3AE82" ${st()}/></g>`;
  return `<g><path d="M-70 -108 H10 Q30 -108 30 -88 V-72" fill="none" ${st(C.navy,18)}/><path d="M-70 -108 H10 Q30 -108 30 -88 V-72" fill="none" ${st('#B9C6CE',10)}/><rect x="14" y="-80" width="32" height="16" rx="5" fill="#B9C6CE" ${st()}/>${d}${hand(-1)}${hand(1)}${b}</g>`};

/* ---------- small icons ---------- */
P.e11_swatch=(o,T)=>{const t=o.l||'',fs=t.length>5?32:42;return `<g transform="scale(${f(1+.03*Math.sin(T*3))})"><circle cy="-14" r="84" fill="${o.c}" ${st(C.navy,6)}/><path d="M-56 -50 Q-40 -76 -14 -82" fill="none" stroke="#fff" stroke-width="9" stroke-linecap="round" opacity=".5"/><rect x="-104" y="80" width="208" height="42" rx="21" fill="${C.cream}" ${st()}/><text x="0" y="110" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${fs}" letter-spacing="3" fill="${C.navy}">${t}</text></g>`};
P.e11_expand=(o,T)=>{const big=o.k!=='small',p=.5+.5*Math.sin(T*3),inner=o.inner?P[o.inner](o.io||{},T,9):'';let ar='';
  [[-1,-1],[1,-1],[-1,1],[1,1]].forEach(([sx,sy])=>{const d=big?(100+p*10):(104-p*10);ar+=`<g transform="translate(${sx*d},${sy*(d-6)}) rotate(${(sx*sy>0?-45:45)+(sx<0?180:0)+(big?0:180)})"><path d="M-22 0 H12 M-2 -16 L16 0 L-2 16" fill="none" ${st(big?C.moss:C.red,10)}/></g>`});
  return `<g><g transform="scale(${big?(o.is||.78):(o.is||.4)})">${inner}</g>${ar}</g>`};
P.e11_quiet=(o,T)=>`<g><path d="M-90 -28 H-50 L-6 -72 V72 L-50 28 H-90Z" fill="${C.gold}" ${st()}/><path d="M26 -34 q26 34 0 68 M54 -58 q46 58 0 116" fill="none" ${st(C.navy,8)} opacity=".25"/><line x1="-100" y1="-100" x2="100" y2="100" ${st(C.red,14)}/></g>`;
P.e11_ball=(o,T)=>{const b=Math.abs(Math.sin(T*4))*-30;return `<g transform="translate(0,${f(b)})"><circle r="70" fill="#F2994A" ${st()}/><path d="M-70 0 H70 M0 -70 V70" fill="none" ${st(C.navy,4)}/><path d="M-50 -50 Q0 -20 50 -50 M-50 50 Q0 20 50 50" fill="none" ${st(C.navy,4)}/><path d="M-46 -34 Q-36 -52 -16 -58" fill="none" stroke="#fff" stroke-width="7" stroke-linecap="round" opacity=".6"/></g>`};
P.e11_look=(o,T)=>{const inner=o.inner?P[o.inner](o.io||{},T,9):'';const w=Math.sin(T*2)*4;
  return `<g transform="translate(${f(w)},0)"><clipPath id="e11lens"><circle cx="-14" cy="-20" r="74"/></clipPath><circle cx="-14" cy="-20" r="74" fill="#E8F6FC"/><g clip-path="url(#e11lens)"><g transform="translate(-14,-20) scale(${o.is||.6})">${inner}</g></g><circle cx="-14" cy="-20" r="74" fill="none" ${st(C.navy,12)}/><circle cx="-14" cy="-20" r="74" fill="none" ${st('#B9C6CE',6)}/><path d="M38 34 L104 98" ${st(C.navy,22)}/><path d="M38 34 L104 98" ${st(C.brown,12)}/><path d="M-52 -52 q14 -22 40 -26" fill="none" ${st('#fff',6)} opacity=".8"/></g>`};
P.e11_angry=(o,T)=>{let s='';for(let i=0;i<2;i++){const ph=(T*1.4+i/2)%1;s+=`<path d="M-58 ${f(-70-ph*30)} q-12 -14 0 -26 M58 ${f(-70-ph*30)} q12 -14 0 -26" fill="none" ${st(C.red,6)} opacity="${f(1-ph)}"/>`}
  return `<g>${s}<g transform="translate(0,30) scale(.9)">${P.person({c:C.red,hair:'short',hc:'#222'},T)}</g></g>`};
P.e11_neigh=(o,T)=>`<g><g transform="translate(-62,6) scale(.6)">${P.house({},T)}</g><g transform="translate(62,6) scale(.6)">${P.house({},T)}</g><g transform="translate(-22,70) scale(.32)">${P.person({c:'#D96C8B',hair:'long',hc:'#3A2A22'},T)}</g><g transform="translate(24,70) scale(.32)">${P.person({c:'#4F7A5A',hair:'short',hc:'#222'},T)}</g></g>`;

/* ---------- hero for the intro: cat and dog face to face with a question ---------- */
P.e11_hero=(o,T)=>{const b=Math.sin(T*2.4)*4,rays=[...Array(8)].map((_,i)=>`<line x1="0" y1="-118" x2="0" y2="${f(-134-Math.sin(T*4+i)*5)}" transform="rotate(${-70+i*20} 0 6)" ${st(C.gold,6)} opacity=".8"/>`).join('');
  return `<g transform="translate(0,${f(b)})"><g transform="translate(-80,16) scale(.66)">${P.e11_cat({},T)}</g><g transform="translate(72,34) scale(.6)">${P.e11_dog({flip:1},T)}</g><g transform="translate(0,-82) scale(.54)">${rays}${P.q({},T)}</g></g>`};

/* ---------- numbers, bad sign, loop arrows, hay ---------- */
P.e11_num=(o,T)=>{const t=String(o.n),fs=t.length>=3?62:t.length===2?88:112;return `<g transform="scale(${f(1+.04*Math.sin(T*4))})"><circle r="84" fill="${C.gold}" ${st()}/><circle r="68" fill="none" ${st(C.goldD,3)}/><text x="0" y="${f(fs*.36)}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${fs}" fill="${C.navy}">${t}</text></g>`};
P.e11_bad=(o,T,k)=>{const p=ease(k/.4);return `<g><circle r="82" fill="${C.red}" ${st()}/><path d="M-34 -34 L34 34 M34 -34 L-34 34" fill="none" stroke="#fff" stroke-width="16" stroke-linecap="round" opacity="${f(p)}"/></g>`};
P.e11_loop=(o,T)=>{const r=T*90;const arc=(a)=>`<g transform="rotate(${f(a)})"><path d="M0 -74 A74 74 0 0 1 70 -24" fill="none" ${st(C.cold,16)}/><path d="M70 -24 L48 -22 L66 -4 Z" fill="${C.cold}" ${st(C.cold,10)}/></g>`;return `<g>${arc(r)}${arc(r+120)}${arc(r+240)}</g>`};
P.e11_hay=(o,T)=>{let l='';for(let i=0;i<9;i++)l+=`<path d="M${-86+i*20} -52 q${i%2?8:-8} 52 ${i%3-1} 104" fill="none" stroke="#C99A2E" stroke-width="3.5" stroke-linecap="round"/>`;
  return `<g><rect x="-100" y="-62" width="200" height="124" rx="12" fill="#E7C65A" ${st()}/>${l}<path d="M-38 -62 V62 M38 -62 V62" ${st('#8B5E3C',7)}/><path d="M-120 -40 l24 -14 M104 -52 l22 -16 M-118 44 l22 12 M104 50 l22 14" ${st('#C99A2E',4)}/></g>`};

/* Episode 12 props: morning routine (window, shower, face wash, exercise, gym, breakfast, bus, list). Faceless. Uses C, st, f, ease, clamp, P from props.js. */
const _e12SK='#E3AE82';
/* ---------- window: open (air comes in) or view (street, trees, birds) ---------- */
P.e12_win=(o,T)=>{
  if(o.k==='view'){let b='';[[-50,-30,0],[10,-60,1.3],[50,-24,2.4]].forEach(([x,y,ph])=>{const a=Math.sin(T*8+ph)*8;b+=`<path d="M${x-16} ${y} Q${x-8} ${f(y-10-a)} ${x} ${y} Q${x+8} ${f(y-10-a)} ${x+16} ${y}" fill="none" ${st(C.navy,4)}/>`});
    return `<g><clipPath id="e12vw"><rect x="-96" y="-110" width="192" height="220" rx="6"/></clipPath><rect x="-108" y="-122" width="216" height="244" rx="12" fill="${C.cream}" ${st()}/><g clip-path="url(#e12vw)"><rect x="-96" y="-110" width="192" height="220" fill="${C.sky}"/><circle cx="52" cy="-72" r="20" fill="#F6CE4B"/><rect x="-96" y="50" width="192" height="60" fill="#5A6B76"/><rect x="-96" y="40" width="192" height="12" fill="#B9C6CE"/><g transform="translate(-52,10) scale(.5)">${P.tree({},T)}</g><g transform="translate(46,16) scale(.42)">${P.tree({},T)}</g>${b}</g><line x1="0" y1="-110" x2="0" y2="110" ${st(C.navy,6)}/><line x1="-96" y1="-4" x2="96" y2="-4" ${st(C.navy,6)}/><rect x="-116" y="112" width="232" height="14" rx="6" fill="${C.cream}" ${st()}/></g>`}
  let w='';for(let i=0;i<3;i++){const ph=(T*.9+i/3)%1;w+=`<path d="M${f(-130+ph*60)} ${-40+i*40} q14 -12 28 0 t28 0" fill="none" ${st('#7FB6D6',6)} opacity="${f(Math.sin(ph*Math.PI))}"/>`}
  const sw=Math.sin(T*1.3)*3;
  return `<g><rect x="-76" y="-100" width="152" height="200" rx="8" fill="${C.sky}" ${st()}/><g transform="translate(16,-44) scale(.42)">${P.sun({},T)}</g><line x1="0" y1="-100" x2="0" y2="100" ${st(C.navy,5)}/><line x1="-76" y1="0" x2="76" y2="0" ${st(C.navy,5)}/><path d="M-76 -100 L${f(-124+sw)} -80 L${f(-124+sw)} 80 L-76 100Z" fill="#CFE3EE" ${st()}/><path d="M76 -100 L${f(124-sw)} -80 L${f(124-sw)} 80 L76 100Z" fill="#CFE3EE" ${st()}/><rect x="-92" y="98" width="184" height="12" rx="5" fill="${C.cream}" ${st()}/>${w}</g>`};
/* ---------- shower ---------- */
P.e12_shower=(o,T)=>{let d='';for(let i=0;i<14;i++){const x=-44+(i%7)*15,ph=(T*1.6+i*.19)%1;d+=`<line x1="${x+(i<7?0:6)}" y1="${f(-28+ph*120)}" x2="${x+(i<7?0:6)-3}" y2="${f(-16+ph*120)}" ${st(o.hot?'#7FC3E8':C.blue,4)} opacity="${f(1-ph*.8)}"/>`}
  let sm='';if(o.hot)for(let i=0;i<3;i++){const ph=(T*.7+i/3)%1;sm+=`<path d="M${-60+i*60} ${f(40-ph*60)} q-10 -12 0 -24 t0 -24" fill="none" ${st('#C9D3D9',5)} opacity="${f(.9-ph)}"/>`}
  return `<g><rect x="-110" y="-110" width="220" height="220" rx="10" fill="#DDF0F4" ${st()}/><path d="M60 110 V-70 H-10 Q-30 -70 -30 -52" fill="none" ${st(C.navy,16)}/><path d="M60 110 V-70 H-10 Q-30 -70 -30 -52" fill="none" ${st('#B9C6CE',9)}/><path d="M-70 -50 H20 L6 -30 H-56Z" fill="#B9C6CE" ${st()}/>${d}${sm}<rect x="-110" y="86" width="220" height="24" fill="#B9C6CE" ${st()}/></g>`};
/* ---------- wash face: tap, water, faceless head ---------- */
P.e12_washface=(o,T)=>{let d='';for(let i=0;i<6;i++){const ph=(T*1.8+i/6)%1;d+=`<path d="M${-2+((i*7)%10)} ${f(-64+ph*62)} q-4 8 0 12 q4 -4 0 -12" fill="${C.blue}" opacity="${f(1-ph*.5)}"/>`}
  let b='';[[-52,20],[56,10],[64,52],[-60,64]].forEach(([x,y],i)=>{b+=`<circle cx="${x}" cy="${f(y+Math.sin(T*2.4+i)*4)}" r="${7+i%2*3}" fill="#EAF6FB" ${st(C.cold,3)}/>`});
  return `<g><path d="M-76 -108 H8 Q28 -108 28 -88 V-72" fill="none" ${st(C.navy,18)}/><path d="M-76 -108 H8 Q28 -108 28 -88 V-72" fill="none" ${st('#B9C6CE',10)}/><rect x="12" y="-76" width="32" height="14" rx="5" fill="#B9C6CE" ${st()}/>${d}<g transform="translate(0,52) scale(.78)">${P.person({c:C.blue,hair:'short',hc:'#222',ph:1},T)}</g>${b}</g>`};
/* ---------- exercise figure ---------- */
P.e12_workout=(o,T)=>{const k=o.k||'jack',s=Math.sin(T*5),sk=_e12SK,c=o.c||C.orange;
  const limb=(x1,y1,x2,y2,col,w)=>`<line x1="${f(x1)}" y1="${f(y1)}" x2="${f(x2)}" y2="${f(y2)}" ${st(C.navy,w+7)}/><line x1="${f(x1)}" y1="${f(y1)}" x2="${f(x2)}" y2="${f(y2)}" ${st(col,w)}/>`;
  if(k==='run'){const p=T*8;const leg=(ph)=>{const a1=Math.sin(p+ph)*.95,a2=a1-(.5+.5*Math.sin(p+ph+1.2))*1.2,kx=-6+Math.sin(a1)*42,ky=10+Math.cos(a1)*42;return limb(-6,10,kx,ky,sk,14)+limb(kx,ky,kx+Math.sin(a2)*44,ky+Math.cos(a2)*44,sk,14)};
    const arm=(ph)=>{const a1=-Math.sin(p+ph)*.9,kx=6+Math.sin(a1)*32,ky=-46+Math.cos(a1)*32;return limb(6,-46,kx,ky,sk,12)+limb(kx,ky,kx+Math.sin(a1+1.25)*28,ky+Math.cos(a1+1.25)*28,sk,12)};
    let sp='';for(let i=0;i<3;i++){const dx=((T*90+i*40)%90);sp+=`<line x1="${f(-96-dx)}" y1="${-50+i*38}" x2="${f(-134-dx)}" y2="${-50+i*38}" ${st('#9AA7B0',6)} opacity="${f(1-dx/90)}"/>`}
    return `<g>${sp}<g transform="translate(0,${f(Math.abs(Math.sin(p))*-7+4)}) rotate(9 0 10)">${leg(Math.PI)}${arm(0)}<path d="M8 -52 L-6 8" fill="none" ${st(C.navy,44)}/><path d="M8 -52 L-6 8" fill="none" ${st(c,37)}/>${leg(0)}${arm(Math.PI)}<rect x="2" y="-72" width="14" height="22" fill="${sk}" ${st(C.navy,4)}/><circle cx="14" cy="-88" r="25" fill="${sk}" ${st()}/><path d="M-10 -90 Q-8 -118 16 -116 Q40 -114 39 -92 Q22 -106 -10 -90Z" fill="#3A2A22" ${st(C.navy,3)}/></g></g>`}
  const head=`<rect x="-9" y="-76" width="18" height="22" fill="${sk}" ${st(C.navy,4)}/><circle cx="0" cy="-92" r="26" fill="${sk}" ${st()}/><path d="M-26 -94 Q-26 -122 0 -120 Q26 -122 26 -94 Q8 -108 -26 -94Z" fill="#3A2A22" ${st(C.navy,3)}/>`;
  if(k==='arms'){const a=(s+1)/2,ya=-8-a*60;const db=(x,y)=>`<g transform="translate(${f(x)},${f(y)})"><rect x="-26" y="-6" width="52" height="12" rx="5" fill="${C.navy}"/><rect x="-32" y="-16" width="14" height="32" rx="5" fill="${C.navy2}" ${st(C.navy,3)}/><rect x="18" y="-16" width="14" height="32" rx="5" fill="${C.navy2}" ${st(C.navy,3)}/></g>`;
    return `<g>${limb(-40,100,-26,20,'#33414B',20)}${limb(40,100,26,20,'#33414B',20)}<rect x="-44" y="-52" width="88" height="86" rx="26" fill="${c}" ${st()}/>${limb(-44,-30,-62,f(40+ya*.1),sk,14)}${limb(-62,40+ya*.1,-62,ya,sk,14)}${limb(44,-30,62,f(40+ya*.1),sk,14)}${limb(62,40+ya*.1,62,ya,sk,14)}${db(-62,ya-6)}${db(62,ya-6)}${head}</g>`}
  const u=(s+1)/2,ax=40+u*50,ay=-30-u*90,lx=24+u*34;
  return `<g transform="translate(0,${f(-u*10+6)})">${limb(-14,28,-lx,100,'#33414B',20)}${limb(14,28,lx,100,'#33414B',20)}${limb(-40,-34,-ax,ay,sk,14)}${limb(40,-34,ax,ay,sk,14)}<rect x="-44" y="-56" width="88" height="94" rx="26" fill="${c}" ${st()}/>${head}</g>`};
/* ---------- gym building ---------- */
P.e12_gym=(o,T)=>{const b=Math.sin(T*3)*3;return `<g><rect x="-110" y="-40" width="220" height="140" fill="#B9C6CE" ${st()}/><rect x="-120" y="-60" width="240" height="30" fill="${C.navy2}" ${st()}/><text x="0" y="-36" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="26" letter-spacing="8" fill="${C.gold}">GYM</text><rect x="-30" y="30" width="60" height="70" fill="${C.brown}" ${st()}/><g transform="translate(0,${f(-96+b)}) scale(.5)"><line x1="-90" y1="0" x2="90" y2="0" ${st(C.navy,12)}/>${[-1,1].map(s=>`<g transform="scale(${s},1)"><rect x="60" y="-46" width="20" height="92" rx="7" fill="${C.navy}" ${st()}/><rect x="36" y="-34" width="20" height="68" rx="7" fill="#33414B" ${st()}/></g>`).join('')}</g><rect x="-96" y="-10" width="52" height="40" fill="${C.sky}" ${st(C.navy,3)}/><rect x="44" y="-10" width="52" height="40" fill="${C.sky}" ${st(C.navy,3)}/></g>`};
/* ---------- food and drink ---------- */
const _e12egg=(x,y,s,rot,c)=>`<g transform="translate(${x},${y}) rotate(${rot}) scale(${s})"><path d="M0 -46 C-34 -46 -42 6 -38 24 C-34 48 -14 54 0 54 C14 54 34 48 38 24 C42 6 34 -46 0 -46Z" fill="${c}" ${st()}/><path d="M-22 -14 Q-24 -30 -10 -36" fill="none" stroke="#fff" stroke-width="7" stroke-linecap="round" opacity=".6"/></g>`;
P.e12_eggs=(o,T)=>`<g><ellipse cx="0" cy="72" rx="96" ry="14" fill="#000" opacity=".1"/>${_e12egg(-52,10,1.2,-8,'#B9814A')}${_e12egg(52,10,1.2,8,'#B9814A')}</g>`;
P.e12_loaf=(o,T)=>{const sl=[0,1,2].map(i=>`<g transform="translate(${-58+i*58},${i%2?4:-6}) rotate(${i*6-6})"><path d="M-34 52 V-14 Q-50 -34 -22 -58 Q0 -72 22 -58 Q50 -34 34 -14 V52Z" fill="#8B5A2B" ${st()}/><path d="M-24 42 V-8 Q-34 -26 -14 -44 Q0 -54 14 -44 Q34 -26 24 -8 V42Z" fill="#C79A63" ${st('#6F4520',3)}/></g>`).join('');return `<g>${sl}</g>`};
P.e12_cheese=(o,T)=>`<g transform="rotate(-6)"><path d="M-100 40 L100 40 L100 -4 Q-20 -30 -100 -64Z" fill="#F6CE4B" ${st()}/><path d="M100 40 L100 -4 L84 -10 L84 40Z" fill="#E3B22B" ${st(C.navy,3)}/><circle cx="-40" cy="10" r="14" fill="#E3B22B" ${st(C.navy,3)}/><circle cx="18" cy="16" r="10" fill="#E3B22B" ${st(C.navy,3)}/><circle cx="-62" cy="-20" r="8" fill="#E3B22B" ${st(C.navy,3)}/><circle cx="52" cy="2" r="9" fill="#E3B22B" ${st(C.navy,3)}/></g>`;
P.e12_glass=(o,T)=>{const col=o.k==='apple'?'#E8C44A':'#F5921E',dk=o.k==='apple'?'#B8922A':'#C46A0C';const deco=o.k==='apple'?`<g transform="translate(0,2) scale(.34)">${P.e12_apple()}</g>`:`<circle cx="0" cy="6" r="22" fill="#fff" ${st(C.navy,3)}/><circle cx="0" cy="6" r="14" fill="${col}" ${st(dk,3)}/>`;
  return `<g><path d="M-54 -86 L54 -86 L44 90 Q0 100 -44 90Z" fill="#EAF6FB" ${st()}/><path d="M-50 -36 L50 -36 L44 90 Q0 100 -44 90Z" fill="${col}" ${st(C.navy,0)}/><path d="M-50 -36 q25 -9 50 0 t50 0" fill="none" ${st(dk,4)}/>${deco}<path d="M-34 -70 L-28 40" fill="none" stroke="#fff" stroke-width="7" stroke-linecap="round" opacity=".6"/><path d="M24 -118 L24 -90" ${st(C.red,6)}/></g>`};
P.e12_apple=(o,T)=>`<g><path d="M0 -62 C-34 -84 -86 -56 -80 4 C-76 62 -34 92 0 76 C34 92 76 62 80 4 C86 -56 34 -84 0 -62Z" fill="${C.red}" ${st()}/><path d="M0 -62 Q0 -86 10 -100" fill="none" ${st(C.brown,9)}/><path d="M6 -86 Q40 -112 62 -88 Q34 -72 6 -86Z" fill="${C.leaf}" ${st()}/></g>`;
P.e12_plate=(o,T)=>`<g><ellipse cx="0" cy="8" rx="100" ry="38" fill="#fff" ${st()}/><ellipse cx="0" cy="6" rx="66" ry="22" fill="#F2F6F8" ${st(C.grey,3)}/><g transform="translate(-122,0)"><path d="M-6 -50 v44 M2 -50 v44 M10 -50 v44 M-6 -8 q8 8 16 0 M2 -6 v56" fill="none" ${st(C.navy2,5)}/></g><g transform="translate(122,0)"><path d="M0 -50 q18 0 14 36 v18 M0 -50 v100" fill="none" ${st(C.navy2,5)}/></g></g>`;
P.e12_table=(o,T)=>{const cups=(x)=>`<g transform="translate(${x},-18) scale(.5)">${P.tea({},T)}</g>`;
  let s=`<rect x="-120" y="30" width="240" height="18" rx="6" fill="${C.brown}" ${st()}/><line x1="-96" y1="48" x2="-96" y2="100" ${st(C.brown,10)}/><line x1="96" y1="48" x2="96" y2="100" ${st(C.brown,10)}/>`;
  s+=`<g transform="translate(-74,-4) scale(.3)">${P.tea({},T)}</g><g transform="translate(-10,6) scale(.36)">${P.e12_loaf({},T)}</g>`;
  if(o.full)s+=`<g transform="translate(50,14) scale(.3)">${P.e12_eggs({},T)}</g><g transform="translate(96,16) scale(.2)">${P.e12_cheese({},T)}</g><g transform="translate(100,-24) scale(.3)">${P.e12_glass({},T)}</g>`;
  else s+=`<g transform="translate(46,-4) scale(.3)">${P.tea({},T)}</g>`;
  return `<g>${s}</g>`};
P.e12_shirt=(o,T)=>`<g><path d="M-44 -84 L-92 -52 L-72 -6 L-46 -22 L-46 88 L46 88 L46 -22 L72 -6 L92 -52 L44 -84 Q0 -58 -44 -84Z" fill="${o.c||C.blue}" ${st()}/><path d="M-28 -78 Q0 -52 28 -78" fill="none" ${st(C.navy,4)} opacity=".5"/></g>`;
/* ---------- bus things ---------- */
P.e12_fullbus=(o,T)=>{const b=Math.sin(T*8)*1.2,hc=['#3A2A22','#222','#6A3F26','#8B5E3C','#3A2A22'],cs=[C.red,C.moss,C.orange,'#8E6BB5',C.cold];
  const win=[0,1,2,3,4].map(i=>`<rect x="${-112+i*44}" y="-38" width="34" height="38" rx="6" fill="${C.sky}" ${st(C.navy,3)}/><g transform="translate(${-95+i*44},-6)"><rect x="-11" y="-6" width="22" height="12" rx="5" fill="${cs[i]}"/><circle cy="-14" r="9" fill="${_e12SK}"/><path d="M-9 -16 Q0 -28 9 -16Z" fill="${hc[i]}"/></g>`).join('');
  return `<g transform="translate(0,${f(b)})"><rect x="-128" y="-52" width="256" height="112" rx="22" fill="${C.gold2}" ${st()}/>${win}<rect x="-128" y="14" width="256" height="10" fill="${C.goldD}"/><circle cx="-78" cy="64" r="22" fill="${C.navy}"/><circle cx="-78" cy="64" r="9" fill="${C.grey}"/><circle cx="78" cy="64" r="22" fill="${C.navy}"/><circle cx="78" cy="64" r="9" fill="${C.grey}"/></g>`};
P.e12_turtle=(o,T)=>{const w=Math.sin(T*1.6)*6;return `<g><ellipse cx="0" cy="90" rx="100" ry="10" fill="#000" opacity=".1"/><path d="M-82 54 Q-82 -34 0 -34 Q82 -34 82 54Z" fill="#6FAF74" ${st()}/><path d="M-44 54 Q-44 -20 0 -34 M44 54 Q44 -20 0 -34 M-82 54 H82" fill="none" ${st('#3F7A47',4)}/><path d="M-30 -2 l20 -14 l22 0 l18 14 l-10 22 h-40z" fill="#8FC794" ${st('#3F7A47',4)}/><ellipse cx="${f(98+w)}" cy="30" rx="26" ry="18" fill="#9BCB8A" ${st()}/><path d="M-82 40 L-100 52 L-84 58" fill="#9BCB8A" ${st()}/><rect x="-62" y="52" width="26" height="30" rx="10" fill="#9BCB8A" ${st()}/><rect x="30" y="52" width="26" height="30" rx="10" fill="#9BCB8A" ${st()}/></g>`};
P.e12_smokebus=(o,T)=>{let sm='';for(let i=0;i<4;i++){const ph=(T*.6+i/4)%1;sm+=`<circle cx="${f(-130-ph*60)}" cy="${f(30-ph*70)}" r="${f(14+ph*20)}" fill="#8F9BA3" opacity="${f(.9-ph)}"/>`}
  return `<g>${sm}<g transform="translate(20,0) scale(.82)">${P.bus({},T)}</g></g>`};
/* ---------- phone with time / article ---------- */
P.e12_phoneclock=(o,T)=>`<g><rect x="-62" y="-112" width="124" height="224" rx="24" fill="${C.navy}" ${st()}/><rect x="-52" y="-94" width="104" height="188" rx="12" fill="#2B3D48"/><text x="0" y="12" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${(o.t||'6:00').length>4?34:40}" fill="${C.cream}">${o.t||'6:00'}</text><circle cx="0" cy="-103" r="3" fill="#41525c"/><rect x="-22" y="78" width="44" height="6" rx="3" fill="#7B8F9B" opacity=".5"/></g>`;
P.e12_article=(o,T)=>{let l='';for(let i=0;i<4;i++)l+=`<line x1="-40" y1="${28+i*16}" x2="${i===3?10:40}" y2="${28+i*16}" ${st('#9AA7B0',4)}/>`;
  return `<g><rect x="-62" y="-112" width="124" height="224" rx="24" fill="${C.navy}" ${st()}/><rect x="-52" y="-94" width="104" height="188" rx="12" fill="${C.cream}"/><rect x="-44" y="-84" width="88" height="18" rx="4" fill="${C.navy}"/><rect x="-44" y="-58" width="88" height="70" fill="${C.sky}" ${st(C.navy,3)}/><g transform="translate(14,-30) scale(.26)">${P.sun({},T)}</g><polygon points="-44,12 -20,-22 -4,0 8,-12 44,12" fill="#8FA3B0"/>${l}</g>`};
/* ---------- list of five morning things ---------- */
P.e12_list5=(o,T,k)=>{const n=o.n==null?5:o.n;const ic=[
  `<g transform="scale(.26) translate(0,-8)">${P.bed({},T)}</g>`,
  `<rect x="-15" y="-15" width="30" height="30" rx="3" fill="${C.sky}" ${st(C.navy,3)}/><line x1="0" y1="-15" x2="0" y2="15" ${st(C.navy,3)}/><line x1="-15" y1="0" x2="15" y2="0" ${st(C.navy,3)}/>`,
  `<path d="M0 -16 C12 -2 16 4 16 10 a16 16 0 0 1 -32 0 C-16 4 -12 -2 0 -16Z" fill="${C.blue}" ${st(C.navy,3)}/>`,
  `<line x1="-14" y1="0" x2="14" y2="0" ${st(C.navy,5)}/><rect x="-18" y="-10" width="7" height="20" rx="2" fill="${C.navy2}"/><rect x="11" y="-10" width="7" height="20" rx="2" fill="${C.navy2}"/>`,
  `<g transform="scale(.2) translate(0,10)">${P.bread({rot:0},T)}</g>`];
  let r='';for(let i=0;i<5;i++){const y=-92+i*46,on=i<n,pp=ease((k-.3-i*.35)/.3);r+=`<rect x="-84" y="${y-20}" width="168" height="40" rx="10" fill="${C.white}" ${st(C.navy,3)}/><g transform="translate(-52,${y})">${ic[i]}</g><line x1="-22" y1="${y}" x2="${[48,56,40,52,60][i]}" y2="${y}" ${st('#C9D3D9',6)}/>`;if(on)r+=`<path d="M58 ${y} l8 9 l16 -20" fill="none" ${st(C.moss,6)} opacity="${f(o.still?1:pp)}"/>`}
  return `<g><rect x="-104" y="-122" width="208" height="248" rx="14" fill="${C.paper}" ${st()}/>${r}</g>`};
/* ---------- week with chosen days ---------- */
P.e12_week=(o,T)=>{const days=o.days||[1,4],L=['S','M','T','W','T','F','S'],N=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];let b='',lb='';
  L.forEach((l,i)=>{const on=days.includes(i),p=on?1+.07*Math.sin(T*5+i):1;b+=`<g transform="translate(${-108+i*36},${on?-4:0}) scale(${f(p)})"><rect x="-14" y="-32" width="28" height="64" rx="8" fill="${on?C.gold:C.white}" ${st()}/><text x="0" y="9" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="${C.navy}">${l}</text></g>`;if(on)lb+=`<text x="${-108+i*36}" y="52" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="18" fill="${C.navy}">${N[i]}</text>`});
  return `<g><rect x="-136" y="-60" width="272" height="124" rx="18" fill="${C.cream}" ${st()}/>${b}${lb}</g>`};
P.e12_num=(o,T)=>{const t=String(o.n),fs=t.length>=3?62:t.length===2?88:112;return `<g transform="scale(${f(1+.04*Math.sin(T*4))})"><circle r="84" fill="${C.gold}" ${st()}/><circle r="68" fill="none" ${st(C.goldD,3)}/><text x="0" y="${f(fs*.36)}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${fs}" fill="${C.navy}">${t}</text></g>`};
/* ---------- hot / cold tea or feeling icons ---------- */
P.e12_cold=(o,T)=>`<g><g transform="translate(-50,0) scale(.8)">${P.thermo({level:.12},T,3)}</g><g transform="translate(60,-6) scale(.62)">${P.snow({},T)}</g></g>`;
P.e12_hungry=(o,T)=>`<g>${P.e12_plate({},T)}</g>`;
P.e12_dark=(o,T)=>{let s='';[[-60,-50,0],[56,-62,1],[70,10,2],[-74,30,3]].forEach(([x,y,p])=>{s+=`<g transform="translate(${x},${y}) scale(${f(.7+.35*Math.sin(T*3+p))})"><polygon points="0,-12 3,-3 12,0 3,3 0,12 -3,3 -12,0 -3,-3" fill="${C.gold}"/></g>`});return `<g>${s}<g transform="translate(-6,0) scale(.8)">${P.moon({},T)}</g></g>`};
P.e12_sleepbed=(o,T)=>`<g><g transform="translate(0,12)">${P.bed({},T)}</g><g transform="translate(60,-56) scale(.7)">${P.zzz({},T)}</g></g>`;
/* ---------- hero: rising sun, hills, steaming cup, birds ---------- */
P.e12_hero=(o,T)=>{const up=.55+.45*ease(clamp(T/1.6)),sy=70-up*96;let r='';for(let i=0;i<11;i++)r+=`<line x1="0" y1="-88" x2="0" y2="${f(-110-Math.sin(T*4+i)*6)}" transform="translate(0,${f(sy)}) rotate(${-100+i*20})" ${st(C.gold2,7)}/>`;
  let st2='';for(let i=0;i<3;i++){const ph=(T*.9+i/3)%1;st2+=`<path d="M${-14+i*14} ${f(14-ph*30)} q-6 -10 0 -20 t0 -20" fill="none" ${st('#fff',5)} opacity="${f(1-ph)}"/>`}
  let b='';[[-70,-96,0],[-36,-118,1.3],[74,-92,2.4]].forEach(([x,y,ph])=>{const a=Math.sin(T*7+ph)*7;b+=`<path d="M${x-14} ${y} Q${x-7} ${f(y-9-a)} ${x} ${y} Q${x+7} ${f(y-9-a)} ${x+14} ${y}" fill="none" ${st(C.navy,4)}/>`});
  return `<g><clipPath id="e12hr"><circle r="116"/></clipPath><circle r="116" fill="#FFE6B0"/><g clip-path="url(#e12hr)"><g>${r}<circle cx="0" cy="${f(sy)}" r="62" fill="#F6B03B" ${st('#C9651B',6)}/></g><path d="M-120 50 Q-60 0 0 40 Q60 6 120 46 V120 H-120Z" fill="#6FAF74" ${st()}/><path d="M-120 78 Q-40 40 30 70 Q80 50 120 74 V120 H-120Z" fill="#4F7A5A" ${st()}/>${b}</g><circle r="116" fill="none" ${st(C.navy,6)}/><g transform="translate(0,64) scale(.52)">${st2}<path d="M-58 -18 L58 -18 L48 38 Q0 74 -48 38Z" fill="#fff" ${st()}/><path d="M58 -2 a24 24 0 1 1 -8 36" fill="none" ${st(C.navy,7)}/><ellipse cx="0" cy="-18" rx="58" ry="11" fill="#B36B2C" ${st()}/></g></g>`};
P.e12_book=(o,T)=>{let l='';for(let i=0;i<5;i++)l+=`<line x1="-86" y1="${-40+i*24}" x2="-22" y2="${-40+i*24}" ${st('#9AA7B0',5)}/><line x1="22" y1="${-40+i*24}" x2="86" y2="${-40+i*24}" ${st('#9AA7B0',5)}/>`;
  return `<g><path d="M-112 -72 Q-56 -90 0 -64 Q56 -90 112 -72 V84 Q56 66 0 92 Q-56 66 -112 84Z" fill="${C.moss}" ${st()}/><path d="M-100 -62 Q-52 -78 0 -54 Q52 -78 100 -62 V72 Q52 56 0 80 Q-52 56 -100 72Z" fill="${C.paper}" ${st(C.navy,3)}/><line x1="0" y1="-54" x2="0" y2="80" ${st(C.navy,3)}/>${l}</g>`};

/* Episode 13 props: city or village (village, river, sea, cafe, waiter, traffic, red doors, orange tree, meat, book, bridge, turn...). Faceless. Uses C, st, f, ease, clamp, P, blob from props.js. */
const _e13T=(x,y,s,inner)=>`<g transform="translate(${f(x)},${f(y)}) scale(${f(s)})">${inner}</g>`;
const _e13panel=(fill,id)=>`<clipPath id="${id}"><rect x="-120" y="-100" width="240" height="200" rx="22"/></clipPath><rect x="-120" y="-100" width="240" height="200" rx="22" fill="${fill}"/>`;
const _e13frame=()=>`<rect x="-120" y="-100" width="240" height="200" rx="22" fill="none" ${st(C.navy,6)}/>`;
const _e13house=(x,y,s,wall,roof,door)=>_e13T(x,y,s,`<rect x="-30" y="-24" width="60" height="50" fill="${wall}" ${st(C.navy,4)}/><polygon points="-40,-24 0,-64 40,-24" fill="${roof}" ${st(C.navy,4)}/><rect x="-8" y="2" width="16" height="24" fill="${door}" ${st(C.navy,3)}/><rect x="12" y="-12" width="12" height="12" fill="${C.sky}" ${st(C.navy,3)}/><rect x="-24" y="-12" width="12" height="12" fill="${C.sky}" ${st(C.navy,3)}/>`);
const _e13tree=(x,y,s,fruit)=>{let fr='';if(fruit)[[-20,-62],[22,-56],[-4,-38],[-34,-24],[36,-22],[10,-78]].forEach(([a,b])=>{fr+=`<circle cx="${a}" cy="${b}" r="9" fill="#F2994A" ${st('#C9651B',2.5)}/>`});
  return _e13T(x,y,s,`<rect x="-9" y="-6" width="18" height="60" fill="${C.brown}" ${st(C.navy,4)}/>${blob([[0,-56,40],[-30,-22,28],[30,-22,28],[0,-16,26]],C.leaf,4)}${fr}`)};
