/* steering wheel */
P.e14_wheel=(o,T)=>`<g transform="rotate(${f(Math.sin(T*1.5)*6)})"><circle r="92" fill="none" ${st(C.navy,22)}/><circle r="92" fill="none" ${st(C.navy2,14)}/><path d="M-90 8 H90 M0 8 V90" fill="none" ${st(C.navy2,18)}/><circle r="28" fill="${C.navy2}" ${st(C.navy,5)}/></g>`;
/* queue of cars = traffic */
P.e14_traffic=(o,T)=>{const bump=Math.sin(T*3)*2;return `<g><rect x="-132" y="-90" width="264" height="190" rx="22" fill="#6B7882" ${st()}/><line x1="-120" y1="6" x2="120" y2="6" stroke="${C.cream}" stroke-width="5" stroke-dasharray="22 16"/>${_e14car(C.red,-78,-36+bump,.3)}${_e14car(C.blue,12,-36-bump,.3)}${_e14car('#E2B653',92,-36+bump,.3)}${_e14car('#8E6BB5',-78,60-bump,.3)}${_e14car(C.moss,12,60+bump,.3)}${_e14car(C.orange,92,60-bump,.3)}</g>`};
P.e14_warning=(o,T)=>{const s=1+.05*Math.sin(T*6);return `<g transform="scale(${f(s)})"><polygon points="0,-104 112,88 -112,88" fill="${C.gold}" ${st(C.navy,9)}/><rect x="-9" y="-44" width="18" height="76" rx="9" fill="${C.navy}"/><circle cx="0" cy="62" r="11" fill="${C.navy}"/></g>`};
/* wrist watch */
P.e14_watch=(o,T)=>{let t='';for(let i=0;i<12;i++)t+=`<line x1="0" y1="-50" x2="0" y2="${i%3?-44:-38}" transform="rotate(${i*30})" ${st(C.navy,i%3?2:4)}/>`;
  return `<g><rect x="-34" y="-124" width="68" height="70" rx="12" fill="#6A4A32" ${st()}/><rect x="-34" y="54" width="68" height="70" rx="12" fill="#6A4A32" ${st()}/><circle r="66" fill="#B9C6CE" ${st()}/><circle r="56" fill="${C.cream}" ${st(C.navy,4)}/>${t}<line x1="0" y1="6" x2="0" y2="-42" transform="rotate(${f(T*60)})" ${st(C.navy,3)}/><line x1="0" y1="4" x2="0" y2="-28" transform="rotate(-50)" ${st(C.navy,5)}/><circle r="5" fill="${C.gold}"/></g>`};
/* airport: terminal and control tower */
P.e14_airport=(o,T)=>{const x=((T*40)%300)-150;return `<g>${_e14panel(C.sky,'e14ap')}<g clip-path="url(#e14ap)"><rect x="-130" y="56" width="260" height="60" fill="#6B7882" ${st(C.navy,3)}/><line x1="-120" y1="78" x2="120" y2="78" stroke="${C.cream}" stroke-width="4" stroke-dasharray="20 14"/><rect x="-96" y="0" width="150" height="58" fill="#E7EEF2" ${st()}/>${[0,1,2,3,4].map(i=>`<rect x="${-86+i*28}" y="12" width="20" height="22" fill="${C.cold}" ${st(C.navy,3)}/>`).join('')}<rect x="64" y="-60" width="22" height="118" fill="#CAD5DC" ${st()}/><path d="M48 -60 H102 L92 -84 H58Z" fill="${C.cold}" ${st(C.navy,4)}/><rect x="56" y="-96" width="38" height="14" fill="${C.navy2}" ${st(C.navy,3)}/><g transform="translate(${f(x)},-48) scale(.3)">${P.e14_plane({},T)}</g></g>${_e14frame()}</g>`};
/* countries: globe with three pins */
P.e14_countries=(o,T)=>{const pin=(x,y,c)=>`<g transform="translate(${x},${y}) scale(.7)"><path d="M0 0 C-22 -30 -24 -42 -16 -54 Q0 -70 16 -54 C24 -42 22 -30 0 0Z" fill="${c}" ${st(C.navy,5)}/><circle cx="0" cy="-44" r="7" fill="${C.white}"/></g>`;
  return `<g>${P.globe({},T)}${pin(-48,-30,C.red)}${pin(34,-6,C.gold)}${pin(-6,52,'#8E6BB5')}</g>`};
/* school */
P.e14_school=(o,T)=>{const w=Math.sin(T*3)*4;return `<g><line x1="-66" y1="-120" x2="-66" y2="-30" ${st(C.navy,5)}/><path d="M-66 -120 h${f(46+w)} l-8 14 l8 14 h-${f(46+w)}Z" fill="${C.red}" ${st(C.navy,3)}/><rect x="-100" y="-30" width="200" height="124" fill="#E7B98B" ${st()}/><polygon points="-110,-30 0,-76 110,-30" fill="#B5604A" ${st()}/><circle cx="0" cy="-44" r="14" fill="${C.cream}" ${st(C.navy,3)}/>${[0,1,2].map(i=>`<rect x="${[-84,50,-28][i]}" y="-8" width="34" height="34" fill="${C.sky}" ${st(C.navy,3)}/>`).join('')}<rect x="-22" y="30" width="44" height="64" fill="${C.brown}" ${st(C.navy,4)}/><rect x="-110" y="94" width="220" height="12" rx="5" fill="#9FB0BA" ${st()}/></g>`};
/* road in perspective, dashes moving */
P.e14_road=(o,T)=>{let d='';for(let i=0;i<5;i++){const ph=((T*.9+i/5)%1),y=-90+ph*190,w=3+ph*8,h=8+ph*22;d+=`<rect x="${-w/2}" y="${f(y)}" width="${f(w)}" height="${f(h)}" fill="${C.cream}"/>`}
  return `<g>${_e14panel('#9CCB9C','e14rd')}<g clip-path="url(#e14rd)"><polygon points="-10,-100 10,-100 120,100 -120,100" fill="#6B7882" ${st(C.navy,3)}/>${d}</g>${_e14frame()}</g>`};
/* river between green banks */
P.e14_river=(o,T)=>{const off=-(T*40)%60;const tr=(x,y,s)=>`<g transform="translate(${x},${y}) scale(${s})"><rect x="-9" y="-6" width="18" height="60" fill="${C.brown}" ${st(C.navy,4)}/>${blob([[0,-56,40],[-30,-22,28],[30,-22,28],[0,-16,26]],C.leaf,4)}</g>`;
  return `<g>${_e14panel('#8FC48F','e14rv')}<g clip-path="url(#e14rv)"><path d="M-140 -90 C-60 -70 -20 -20 -40 20 C-60 60 40 70 40 120" fill="none" ${st(C.navy,78)}/><path d="M-140 -90 C-60 -70 -20 -20 -40 20 C-60 60 40 70 40 120" fill="none" ${st(C.blue,70)}/><path d="M-140 -90 C-60 -70 -20 -20 -40 20 C-60 60 40 70 40 120" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round" stroke-dasharray="14 46" stroke-dashoffset="${f(off)}" opacity=".8"/>${tr(-84,50,.5)}${tr(86,-30,.55)}${tr(80,60,.45)}</g>${_e14frame()}</g>`};
/* book */
P.e14_book=(o,T)=>`<g transform="rotate(${f(Math.sin(T*1.4)*2)})"><rect x="-76" y="-108" width="152" height="204" rx="10" fill="#4F7A5A" ${st()}/><rect x="-76" y="-108" width="24" height="204" rx="8" fill="#3A5C43" ${st()}/><rect x="-36" y="-76" width="88" height="56" rx="6" fill="${C.cream}" ${st(C.navy,3)}/><line x1="-26" y1="-58" x2="42" y2="-58" ${st(C.navy,4)}/><line x1="-26" y1="-42" x2="30" y2="-42" ${st(C.navy,4)}/><path d="M-76 96 h152 v8 h-152Z" fill="${C.cream}" ${st()}/></g>`;
/* plus sign (add) */
P.e14_plus=(o,T)=>{const s=1+.06*Math.sin(T*5);return `<g transform="scale(${f(s)})"><circle r="88" fill="${C.gold}" ${st(C.goldD,7)}/><path d="M0 -50 V50 M-50 0 H50" fill="none" ${st(C.navy,22)}/></g>`};
/* route with stops */
P.e14_stops=(o,T)=>{const n=o.n||2;let s='';const x0=-92,dx=184/n;const tx=x0+((T*.5)%1)*184;
  for(let i=0;i<=n;i++){const x=x0+i*dx;s+=`<circle cx="${f(x)}" cy="40" r="${i===0?14:18}" fill="${i===0?C.moss:C.gold}" ${st(C.navy,5)}/>`}
  return `<g><line x1="-110" y1="40" x2="110" y2="40" ${st(C.navy,10)}/><line x1="${x0}" y1="40" x2="${f(x0+184)}" y2="40" ${st(C.cream,4)} stroke-dasharray="8 8"/>${s}<g transform="translate(${f(tx)},-30) scale(.42)"><rect x="-70" y="-44" width="140" height="80" rx="20" fill="${C.moss}" ${st()}/><rect x="-54" y="-30" width="40" height="30" rx="5" fill="${C.sky}" ${st(C.navy,3)}/><rect x="14" y="-30" width="40" height="30" rx="5" fill="${C.sky}" ${st(C.navy,3)}/><circle cx="-36" cy="44" r="14" fill="${C.navy}"/><circle cx="36" cy="44" r="14" fill="${C.navy}"/></g></g>`};
