P.e14_stop=(o,T)=>`<g><rect x="-8" y="30" width="16" height="90" fill="#9FB0BA" ${st()}/><polygon points="-40,-96 40,-96 96,-40 96,40 40,96 -40,96 -96,40 -96,-40" fill="${C.red}" ${st(C.navy,8)}/><polygon points="-34,-80 34,-80 80,-34 80,34 34,80 -34,80 -80,34 -80,-34" fill="none" stroke="${C.white}" stroke-width="4"/><text x="0" y="16" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="40" letter-spacing="1" fill="${C.white}">STOP</text></g>`;
