P.e18_soup=(o,T)=>`<g>${_e18steam(T,-40,3,-18)}<rect x="-38" y="78" width="76" height="14" rx="6" fill="${C.white}" ${st()}/><path d="M-96 0 H96 Q92 74 0 84 Q-92 74 -96 0Z" fill="${C.white}" ${st()}/><path d="M-72 44 Q0 62 72 44" fill="none" stroke="${C.blue}" stroke-width="6" opacity=".55"/><ellipse cx="0" cy="0" rx="96" ry="22" fill="${C.cream}" ${st()}/><ellipse cx="0" cy="3" rx="84" ry="16" fill="#E8803A"/><circle cx="-36" cy="2" r="6" fill="${C.leaf}"/><circle cx="26" cy="6" r="6" fill="#F6CE4B"/><circle cx="-4" cy="8" r="5" fill="${C.leaf}"/><circle cx="52" cy="0" r="5" fill="${C.leaf}"/></g>`;
P.e18_salad=(o,T)=>{const tm=(x,y,r)=>`<g transform="translate(${x},${y})"><circle r="${r}" fill="${C.red}" ${st(C.navy,4)}/><path d="M${-r*.5} ${-r*.8} l${r*.5} ${r*.25} l${r*.5} ${-r*.25} l${-r*.1} ${-r*.3} l${-r*.4} ${r*.2} l${-r*.4} ${-r*.2}Z" fill="${C.leaf}" ${st(C.navy,3)}/></g>`;
  return `<g>${blob([[-62,-4,30],[-20,-24,34],[28,-18,32],[0,0,32],[66,2,24],[-82,8,22]],C.leaf,5)}${tm(-34,-26,15)}${tm(24,-34,15)}${tm(52,-6,13)}<circle cx="-2" cy="-4" r="15" fill="#CFE8B4" ${st(C.navy,3)}/><rect x="-38" y="78" width="76" height="14" rx="6" fill="${C.white}" ${st()}/><path d="M-100 6 H100 Q94 76 0 86 Q-94 76 -100 6Z" fill="${C.white}" ${st()}/><path d="M-72 46 Q0 64 72 46" fill="none" stroke="${C.blue}" stroke-width="6" opacity=".55"/></g>`};

/* ---------- small things ---------- */
