/* ---------- hero: summer or winter ---------- */
P.e18_hero=(o,T)=>{const a=Math.max(0,Math.sin(T*2.2)),b=Math.max(0,-Math.sin(T*2.2));
  const med=(x,id,pp,inner)=>`<g transform="translate(${x},${f(-pp*12)}) scale(${f(1+.07*pp)})"><circle r="84" fill="${C.cream}" ${st(C.gold,0)}/>${_e18medal(`<g transform="scale(.64)">${inner}</g>`,id,78)}</g>`;
  return `<g>${med(-82,'e18hm1',a,_e18summerIn(T))}${med(82,'e18hm2',b,_e18winterIn(T))}<g transform="translate(0,0)"><rect x="-44" y="-26" width="88" height="52" rx="26" fill="${C.gold}" ${st()}/><text x="0" y="11" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" letter-spacing="2" fill="${C.navy}">OR</text></g></g>`};

/* ice cream cone (two scoops) */
P.e18_icecream=(o,T)=>{let cone='';for(let i=0;i<4;i++)cone+=`<line x1="${-30+i*14}" y1="0" x2="${-14+i*7}" y2="${40+i*18}" ${st('#B97A2C',3)}/>`;
  return `<g transform="translate(0,22) scale(.86)"><polygon points="-38,-4 38,-4 0,118" fill="#E3A857" ${st()}/>${cone}<circle cx="0" cy="-40" r="46" fill="#F7E7A8" ${st()}/><path d="M-46 -34 q-6 22 8 24 q8 -2 6 -14" fill="#F7E7A8" ${st()}/><circle cx="0" cy="-92" r="40" fill="#F4C6D2" ${st()}/><circle cx="2" cy="-140" r="9" fill="${C.red}" ${st(C.navy,3)}/></g>`};

/* Episode 19 props: being sick, soup, bath, tooth, grandmother's advice. Faceless. Uses C, st, f, ease, clamp, P. */
const _e19T=(x,y,s,inner)=>`<g transform="translate(${f(x)},${f(y)}) scale(${f(s)})">${inner}</g>`;
const _e19steam=(T,x0,y0,n,col)=>{let s='';for(let i=0;i<n;i++){const ph=(T*.8+i/n)%1;s+=`<path d="M${f(x0+i*26)} ${f(y0-ph*44)} q-9 -12 0 -24 t0 -24" fill="none" ${st(col||'#9AA7B0',5)} opacity="${f(1-ph)}"/>`}return s};
const _e19heat=(T,x0,y0,n)=>{let s='';for(let i=0;i<n;i++){const ph=(T*.9+i/n)%1;s+=`<path d="M${f(x0+i*30)} ${f(y0-ph*40)} q-9 -10 0 -20 t0 -20" fill="none" ${st('#E5604D',5)} opacity="${f(1-ph)}"/>`}return s};

/* ---------- a person lying sick in bed (faceless) ---------- */
P.e19_sickbed=(o,T)=>{const br=Math.sin(T*1.6)*2,skin=o.skin||'#E3AE82';let z='';
  if(o.zzz)for(let i=0;i<3;i++){const ph=(T*.6+i/3)%1;z+=`<text x="${f(-40+i*26+ph*16)}" y="${f(-60-i*22-ph*24)}" font-family="Fraunces" font-weight="800" font-size="${34+i*10}" fill="#7F93A0" opacity="${f(Math.sin(ph*Math.PI))}">z</text>`}
  const hot=o.hot?_e19heat(T,-86,-52,3):'';
  return `<g><rect x="-122" y="-62" width="24" height="168" rx="8" fill="${C.brown}" ${st()}/><rect x="108" y="10" width="16" height="96" rx="6" fill="${C.brown}" ${st()}/><rect x="-108" y="40" width="226" height="34" rx="10" fill="${C.cream}" ${st()}/><rect x="-100" y="-6" width="86" height="38" rx="18" fill="${C.white}" ${st()}/><circle cx="-58" cy="-20" r="27" fill="${skin}" ${st()}/><path d="M-84 -22 Q-84 -52 -58 -50 Q-30 -50 -32 -22 Q-48 -36 -84 -22Z" fill="${o.hc||'#3A2A22'}" ${st()}/><g transform="translate(0,${f(br)})"><path d="M-34 6 Q-20 -8 -4 6 L112 6 Q122 6 122 20 L122 56 L-34 56 Z" fill="${o.bc||C.blue}" ${st()}/><path d="M-34 24 H122 M-34 40 H122" fill="none" ${st('#fff',4)} opacity=".45"/><path d="M-34 6 Q-20 -8 -4 6" fill="none" ${st()}/></g><rect x="-122" y="74" width="20" height="30" fill="${C.brown}" ${st()}/>${hot}${z}</g>`};

/* ---------- person with a hot head (fever): faceless person + heat waves + sweat ---------- */
P.e19_hotperson=(o,T)=>{const dr=((T*.9)%1);
  return `<g>${_e19T(0,16,.92,P.person(o,T))}${_e19heat(T,-34,-96,3)}<path d="M72 ${f(-60+dr*50)} q-8 12 0 18 q8 -6 0 -18" fill="${C.blue}" opacity="${f(1-dr)}"/><path d="M-76 ${f(-70+((dr+.5)%1)*50)} q-8 12 0 18 q8 -6 0 -18" fill="${C.blue}" opacity="${f(1-((dr+.5)%1))}"/></g>`};

/* ---------- tissue box with tissue and used tissues ---------- */
P.e19_tissue=(o,T)=>{const sw=Math.sin(T*2.2)*6;
  return `<g><path d="M-36 -26 Q${f(-20+sw)} -100 ${f(0+sw)} -84 Q${f(20+sw)} -108 36 -26 Z" fill="${C.white}" ${st()}/><rect x="-92" y="-30" width="184" height="104" rx="16" fill="#7FC0DD" ${st()}/><ellipse cx="0" cy="-30" rx="52" ry="12" fill="${C.navy}" opacity=".85"/><rect x="-70" y="22" width="140" height="10" rx="5" fill="#fff" opacity=".5"/><circle cx="-108" cy="86" r="17" fill="${C.white}" ${st(C.navy,4)}/><circle cx="-80" cy="96" r="13" fill="${C.white}" ${st(C.navy,4)}/><circle cx="112" cy="90" r="16" fill="${C.white}" ${st(C.navy,4)}/></g>`};

