P.e19_soup=(o,T)=>{const ch=o.chicken;
  let bits='';[[-30,-8],[10,2],[-6,16],[36,-6]].forEach(([x,y],i)=>{bits+=`<ellipse cx="${x}" cy="${y}" rx="9" ry="5" fill="${i%2?'#F2994A':'#FFF6D8'}" ${st(C.navy,2)}/>`});
  return `<g>${_e19steam(T,-30,-26,3)}<ellipse cx="0" cy="76" rx="100" ry="15" fill="${C.cream}" ${st()}/><path d="M-84 0 H84 Q84 70 0 78 Q-84 70 -84 0 Z" fill="#fff" ${st()}/><ellipse cx="0" cy="0" rx="84" ry="18" fill="#F0C265" ${st()}/>${bits}${ch?`<g transform="translate(0,-12)"><ellipse cx="2" cy="0" rx="26" ry="14" fill="#C98A4B" ${st(C.navy,3)}/><circle cx="-26" cy="-4" r="7" fill="#fff" ${st(C.navy,3)}/></g>`:''}<g transform="translate(78,-34) rotate(35)"><rect x="-5" y="-30" width="10" height="64" rx="4" fill="#B9C6CE" ${st(C.navy,3)}/><ellipse cx="0" cy="-38" rx="13" ry="18" fill="#B9C6CE" ${st(C.navy,3)}/></g></g>`};

