/* ---------- swimming pool (optionally with a faceless swimmer) ---------- */
P.e20_pool=(o,T)=>{let w='';for(let r=0;r<3;r++){let d=`M-100 ${-4+r*34}`;for(let i=0;i<5;i++)d+=` q10 -10 20 0 t20 0`;w+=`<path d="${d}" fill="none" ${st('#fff',4)} opacity=".75" transform="translate(${f(Math.sin(T*1.6+r)*8)},0)"/>`}
  const sw=o.swim?`<g transform="translate(${f(Math.sin(T*1.2)*34)},4)"><path d="M-28 6 Q0 -10 28 6 Q0 20 -28 6Z" fill="${C.orange}" ${st(C.navy,4)}/><circle cx="34" cy="0" r="14" fill="#E3AE82" ${st(C.navy,4)}/><path d="M20 -8 Q34 -22 48 -6 Z" fill="${C.red}" ${st(C.navy,3)}/><path d="M-10 -2 q${f(18)} ${f(-26+Math.sin(T*6)*10)} 36 -10" fill="none" ${st('#E3AE82',9)}/></g>`:'';
  return `<g><rect x="-124" y="-60" width="248" height="150" rx="14" fill="#E8EEF1" ${st()}/><rect x="-104" y="-40" width="208" height="110" rx="6" fill="#7FC9E6" ${st(C.navy,4)}/><clipPath id="e20pc"><rect x="-100" y="-36" width="200" height="102"/></clipPath><g clip-path="url(#e20pc)" transform="translate(0,-6)">${w}</g><g transform="translate(0,-6)">${sw}</g><g transform="translate(86,-60)"><path d="M0 0 v-34 a14 14 0 0 1 28 0 M16 0 v-34" fill="none" ${st('#9FB0BA',6)} transform="translate(-8,0)"/></g></g>`};

/* ---------- pictures, easel, palette, pencil ---------- */
const _e20pic=(k,T)=>{
  if(k==='night'){let s='';[[-50,-30,.9],[-10,-38,.6],[30,-20,.8],[52,-36,1],[-30,-8,.5],[10,-10,.7]].forEach(([x,y,z],i)=>{s+=_e20star(x,y,z*(.8+.3*Math.sin(T*3+i)),'#fff')});return `<rect x="-70" y="-50" width="140" height="100" fill="#1E3A66"/><rect x="-70" y="6" width="140" height="44" fill="#15305A"/><path d="M-70 18 q17 -8 35 0 t35 0 t35 0 t35 0" fill="none" stroke="#2E5A94" stroke-width="3"/>${s}`}
  if(k==='flowers'){const fl=(x,y,c)=>{let p='';for(let i=0;i<6;i++)p+=`<circle cx="${f(Math.cos(i*1.047)*9)}" cy="${f(Math.sin(i*1.047)*9)}" r="7" fill="${c}"/>`;return `<line x1="${x}" y1="${y}" x2="${x}" y2="44" stroke="${C.leaf}" stroke-width="4"/><g transform="translate(${x},${y})">${p}<circle r="5" fill="${C.gold}"/></g>`};
    return `<rect x="-70" y="-50" width="140" height="100" fill="${C.sky}"/><rect x="-70" y="22" width="140" height="28" fill="${C.leaf}"/>${fl(-40,-4,'#F28CA6')}${fl(-2,-20,'#fff')}${fl(36,-2,'#F2994A')}`}
  if(k==='tree')return `<rect x="-70" y="-50" width="140" height="100" fill="${C.sky}"/><rect x="-70" y="24" width="140" height="26" fill="${C.leaf}"/><rect x="-6" y="-4" width="12" height="40" fill="${C.brown}"/><circle cx="0" cy="-18" r="30" fill="${C.leaf}"/>`;
  if(k==='cat')return `<rect x="-70" y="-50" width="140" height="100" fill="#F6EEDC"/><ellipse cx="-20" cy="-4" rx="34" ry="26" fill="#fff" transform="rotate(-20 -20 -4)"/><ellipse cx="26" cy="10" rx="30" ry="22" fill="#F3C94C" transform="rotate(25 26 10)"/><ellipse cx="4" cy="-22" rx="22" ry="14" fill="#fff"/><ellipse cx="-36" cy="26" rx="20" ry="12" fill="#F3C94C"/>`;
  if(k==='oldman')return `<rect x="-70" y="-50" width="140" height="100" fill="${C.sky}"/><rect x="-70" y="8" width="140" height="42" fill="${C.blue}"/><path d="M-70 14 q17 -8 35 0 t35 0 t35 0 t35 0" fill="none" stroke="#fff" stroke-width="3"/><rect x="-70" y="34" width="140" height="16" fill="#E7D3A6"/><path d="M-36 40 L-36 4 Q-36 -6 -22 -6 Q-8 -6 -8 4 L-8 40Z" fill="#8E6BB5"/><circle cx="-22" cy="-18" r="12" fill="#E3AE82"/><path d="M-34 -22 Q-22 -34 -10 -22 Q-22 -26 -34 -22Z" fill="#D5D8DB"/><ellipse cx="22" cy="36" rx="16" ry="10" fill="#E39B4B"/><circle cx="34" cy="26" r="8" fill="#E39B4B"/>`;
  if(k==='city'){let b='';[-52,-26,0,26,50].forEach((x,i)=>{const h=[40,64,48,72,44][i];b+=`<rect x="${x-11}" y="${50-h}" width="22" height="${h}" fill="${i%2?'#7F96A3':'#94A9B5'}"/>`});return `<rect x="-70" y="-50" width="140" height="100" fill="${C.sky}"/>${b}`}
  return `<rect x="-70" y="-50" width="140" height="100" fill="${C.sky}"/><circle cx="36" cy="-24" r="14" fill="#F6CE4B"/><rect x="-70" y="6" width="140" height="44" fill="${C.blue}"/><path d="M-70 18 q17 -8 35 0 t35 0 t35 0 t35 0" fill="none" stroke="#fff" stroke-width="3"/>`};
