/* ---------- games ---------- */
P.e20_wordgame=(o,T)=>{const L='WORD';let t='';for(let i=0;i<4;i++){const y=Math.sin(T*3+i)*3;t+=`<g transform="translate(${-90+i*60},${f(y)})"><rect x="-26" y="-30" width="52" height="60" rx="8" fill="#F4E5C2" ${st()}/><text x="0" y="16" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="40" fill="${C.navy}">${L[i]}</text></g>`}
  return `<g><rect x="-132" y="-48" width="264" height="96" rx="12" fill="${C.moss}" ${st()}/>${t}</g>`};
P.e20_cards=(o,T)=>{const card=(x,r,inner)=>`<g transform="translate(${x},0) rotate(${r})"><rect x="-48" y="-72" width="96" height="144" rx="12" fill="#fff" ${st()}/><g transform="translate(0,0) scale(.34)">${inner}</g></g>`;
  return `<g>${card(-72,-12,P.sun({},T))}${card(0,0,P.tree({},T))}${card(72,12,P.house({},T))}</g>`};
P.e20_names=(o,T)=>`<g><g transform="translate(-52,-34) scale(.62)">${P.bubble({side:'L',text:'Adam',fs:44,w:118},T)}</g><g transform="translate(52,44) scale(.62)">${P.bubble({side:'R',text:'Maya',fs:44,w:118},T)}</g></g>`;
P.e20_agree=(o,T)=>{const sh=Math.sin(T*4)*3;
  return `<g><g transform="translate(0,${f(sh)}) scale(1.25)"><path d="M-122 -34 H-40 L-4 -14 L-4 30 L-40 36 H-122Z" fill="${C.blue}" ${st()}/><path d="M122 -34 H40 L4 -14 L4 30 L40 36 H122Z" fill="${C.gold2}" ${st()}/><path d="M-44 -24 Q-8 -38 22 -22 L52 -18 Q64 -4 54 6 Q40 -2 30 6 Q42 14 34 24 Q22 18 14 24 Q18 36 6 38 Q-20 40 -40 32Z" fill="#E3AE82" ${st()}/><path d="M-20 -10 q30 -12 62 8" fill="none" ${st('#B9805A',4)}/></g><g transform="translate(0,-86) scale(.5)">${P.check({},T,9)}</g></g>`};

/* ---------- calendar strip with day name, flowers, hero ---------- */
P.e20_day=(o,T)=>{const days=['S','M','T','W','T','F','S'],N=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],on=o.day;let b='';
  days.forEach((l,i)=>{const hi=i===on,p=hi?1+.07*Math.sin(T*5):1;b+=`<g transform="translate(${-108+i*36},${hi?-4:0}) scale(${f(p)})"><rect x="-14" y="-32" width="28" height="64" rx="8" fill="${hi?C.gold:C.white}" ${st()}/><text x="0" y="9" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="${C.navy}">${l}</text></g>`});
  return `<g><rect x="-136" y="-60" width="272" height="120" rx="18" fill="${C.cream}" ${st()}/>${b}<text x="0" y="52" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="22" fill="${C.navy}" opacity="0"></text><rect x="-92" y="-108" width="184" height="40" rx="20" fill="${C.red}" ${st()}/><text x="0" y="-80" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="25" letter-spacing="2" fill="${C.cream}">${N[on].toUpperCase()}</text></g>`};
P.e20_flowers=(o,T)=>{const fl=(x,h,c,ph)=>{let p='';for(let i=0;i<6;i++)p+=`<circle cx="${f(Math.cos(i*1.047)*17)}" cy="${f(Math.sin(i*1.047)*17)}" r="13" fill="${c}" ${st(C.navy,3)}/>`;return `<path d="M${x} 96 L${x} ${-h}" ${st(C.leaf,7)} fill="none"/><g transform="translate(${x},${-h}) rotate(${f(Math.sin(T*1.4+ph)*5)})">${p}<circle r="9" fill="${C.gold}" ${st(C.navy,3)}/></g>`};
  return `<g>${fl(-64,10,'#F28CA6',0)}${fl(0,50,'#fff',1)}${fl(64,0,'#F2994A',2)}<path d="M-36 96 q-16 -30 -40 -34 q6 24 40 34Z M36 96 q16 -30 40 -34 q-6 24 -40 34Z" fill="${C.leaf}" ${st(C.navy,3)}/></g>`};
P.e20_hero=(o,T)=>{const b=(i,a)=>Math.sin(T*1.6+i)*a;
  return `<g><circle cx="0" cy="0" r="118" fill="#fff" opacity=".07"/><g transform="translate(-62,${f(-34+b(0,5))}) scale(.58) rotate(-8)">${P.e20_racket({},T)}</g><g transform="translate(62,${f(-36+b(1,5))}) scale(.6)">${P.e20_palette({},T)}</g><g transform="translate(0,${f(66+b(2,5))}) scale(.52)">${P.e20_camera({},T)}</g></g>`};

/* Episode 21 props: cooking at home (sandwich, cheese, vegetables, fruit salad, supermarket...). Faceless. Uses C, st, f, ease, clamp, P. */
const _e21D={};
const _e21steam=(T,n,x0,y0,sp)=>{let s='';for(let i=0;i<n;i++){const ph=(T*.8+i/n)%1;s+=`<path d="M${f(x0+i*(sp||26))} ${f(y0-ph*40)} q-9 -12 0 -24 t0 -24" fill="none" ${st('#9AA7B0',5)} opacity="${f(1-ph)}"/>`}return s};
const _e21drop=(x,y,s,o)=>`<path d="M${f(x)} ${f(y-14*s)} q${f(-9*s)} ${f(14*s)} 0 ${f(20*s)} q${f(9*s)} ${f(-6*s)} 0 ${f(-20*s)}" fill="${C.blue}" ${st(C.navy,2)} opacity="${f(o)}"/>`;

/* ---------- vegetables and fruit ---------- */
_e21D.potato=(o,T)=>`<g><path d="M-90 8 C-96 -34 -46 -62 0 -54 C52 -60 96 -30 90 14 C86 56 30 66 -6 62 C-50 64 -86 46 -90 8Z" fill="#C79A5B" ${st()}/>${[[-40,-8],[10,-26],[44,12],[-12,26],[-58,22],[66,-14]].map(([x,y])=>`<ellipse cx="${x}" cy="${y}" rx="6" ry="4" fill="#9C7238"/>`).join('')}<path d="M-56 -18 Q-40 -38 -14 -42" fill="none" stroke="#E2BE88" stroke-width="7" stroke-linecap="round"/></g>`;
_e21D.carrot=(o,T)=>`<g transform="rotate(${o.rot==null?28:o.rot})"><path d="M-34 -52 Q0 -64 34 -52 L8 98 Q0 108 -8 98Z" fill="#F28A22" ${st()}/><path d="M-22 -22 h18 M6 4 h18 M-12 30 h16 M-4 58 h12" fill="none" stroke="#C76512" stroke-width="5" stroke-linecap="round"/><path d="M0 -54 Q-26 -100 -40 -112 M0 -54 Q0 -108 0 -124 M0 -54 Q26 -100 40 -112" fill="none" ${st(C.leaf,12)}/></g>`;
_e21D.tomato=(o,T)=>`<g><path d="M-84 6 C-84 -52 -40 -68 0 -60 C40 -68 84 -52 84 6 C84 56 44 78 0 78 C-44 78 -84 56 -84 6Z" fill="#E4472F" ${st()}/><path d="M-50 -22 Q-48 -40 -28 -48" fill="none" stroke="#F58C7C" stroke-width="9" stroke-linecap="round"/><path d="M0 -62 L-30 -50 L-12 -44 L-24 -28 L0 -40 L24 -28 L12 -44 L30 -50Z" fill="${C.leaf}" ${st(C.navy,4)}/></g>`;
_e21D.apple=(o,T)=>{const g=o.green,c=g?'#7DBB4F':'#D9534F',h=g?'#B9E08C':'#F58B87';return `<g><path d="M0 -62 C-34 -84 -86 -56 -80 4 C-76 62 -34 92 0 76 C34 92 76 62 80 4 C86 -56 34 -84 0 -62Z" fill="${c}" ${st()}/><path d="M-52 -18 Q-54 -42 -30 -54" fill="none" stroke="${h}" stroke-width="9" stroke-linecap="round"/><path d="M0 -62 Q0 -86 10 -100" fill="none" ${st(C.brown,9)}/><path d="M6 -86 Q40 -112 62 -88 Q34 -72 6 -86Z" fill="${C.leaf}" ${st()}/></g>`};
_e21D.banana=(o,T)=>{const g=o.green,c=g?'#8DC34A':'#F7D547',h=g?'#B9DE84':'#FBEB94';return `<g transform="rotate(${o.rot==null?-62:o.rot})"><path d="M-104 -34 C-96 36 -30 90 52 66 C84 56 100 30 106 -4 L84 -10 C74 26 48 42 8 42 C-36 40 -62 8 -78 -44Z" fill="${c}" ${st()}/><path d="M-104 -34 L-92 -70 L-70 -66 L-78 -44Z" fill="${C.brown}" ${st()}/><path d="M106 -4 L100 -20 L84 -10Z" fill="${C.brown}" ${st()}/><path d="M-60 6 C-30 40 10 52 50 40" fill="none" stroke="${h}" stroke-width="7" stroke-linecap="round"/></g>`};
_e21D.orange=(o,T)=>`<g><circle r="80" fill="#F5921E" ${st('#C46A0C',5)}/>${[[-30,-26],[24,-34],[-4,10],[34,22],[-38,36],[10,52],[48,-8]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3.2" fill="#D9760F"/>`).join('')}<path d="M-6 -78 Q18 -108 46 -96 Q30 -68 -6 -78Z" fill="${C.leaf}" ${st()}/><path d="M-50 -34 Q-44 -52 -26 -60" fill="none" stroke="#FFC878" stroke-width="8" stroke-linecap="round"/></g>`;
_e21D.onion=(o,T)=>{
  if(o.cut){let d='';if(o.tears)for(let i=0;i<6;i++){const ph=(T*.9+i/6)%1;d+=_e21drop(-100+i*40,-70+ph*150,1.2,1-ph)}
    return `<g><circle r="76" fill="#FFF6DC" ${st()}/><circle r="67" fill="none" stroke="#D9A441" stroke-width="6"/><ellipse rx="50" ry="52" fill="none" stroke="#D8C48E" stroke-width="4"/><ellipse rx="32" ry="34" fill="none" stroke="#D8C48E" stroke-width="4"/><ellipse rx="14" ry="16" fill="none" stroke="#D8C48E" stroke-width="4"/>${d}</g>`}
  let d='';if(o.tears)for(let i=0;i<6;i++){const ph=(T*.9+i/6)%1;d+=_e21drop(-100+i*40,-40+ph*150,1.2,1-ph)}
  return `<g><path d="M-8 -90 Q0 -108 8 -90 Q10 -72 44 -50 Q88 -12 72 36 Q56 80 0 80 Q-56 80 -72 36 Q-88 -12 -44 -50 Q-10 -72 -8 -90Z" fill="#D9A441" ${st()}/><path d="M-30 -48 Q-58 10 -30 70 M0 -60 Q-18 10 0 78 M30 -48 Q58 10 30 70" fill="none" ${st('#B9822B',4)}/><path d="M-12 82 l-4 14 M0 82 v16 M12 82 l4 14" fill="none" ${st(C.navy,3)}/>${d}</g>`};
_e21D.shaker=(o,T)=>{const grain=o.salt?'#FFFFFF':'#2B2B2B',cap=o.salt?'#6FB1D6':'#B9C6CE';let g='';
  for(let i=0;i<7;i++){const ph=(T*.9+i/7)%1;g+=`<circle cx="${f(-22+i*7+Math.sin(i*3)*5)}" cy="${f(56+ph*60)}" r="${o.salt?4.5:4}" fill="${grain}" ${st(C.navy,o.salt?2:1)} opacity="${f(1-ph*.9)}"/>`}
  return `<g><g transform="translate(0,-34) rotate(180)"><rect x="-44" y="-48" width="88" height="130" rx="20" fill="#F4F1E8" ${st()}/><rect x="-34" y="-8" width="68" height="84" rx="12" fill="${grain}" ${st(C.navy,3)} opacity=".95"/><path d="M-48 -42 V-60 Q-48 -92 0 -92 Q48 -92 48 -60 V-42Z" fill="${cap}" ${st()}/><path d="M-30 -62 Q-28 -76 -12 -80" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round" opacity=".6"/></g>${g}</g>`};
for(const k of ['potato','carrot','tomato','apple','banana','orange','onion','shaker'])P['e21_'+k]=(o,T,kk)=>_e21D[k](o||{},T,kk);

/* ---------- cheese ---------- */
const _e21slice=(col,hc)=>`<rect x="-40" y="-40" width="80" height="80" rx="6" fill="${col}" ${st()}/><circle cx="-14" cy="-12" r="9" fill="${hc}" ${st(C.navy,2.5)}/><circle cx="16" cy="12" r="7" fill="${hc}" ${st(C.navy,2.5)}/><circle cx="18" cy="-22" r="5" fill="${hc}" ${st(C.navy,2.5)}/><circle cx="-20" cy="22" r="5" fill="${hc}" ${st(C.navy,2.5)}/>`;
P.e21_cheese=(o,T)=>{const col=o.white?'#F4EFE0':'#F6CE4B',hc=o.white?'#DCD3B8':'#E3B22B';
  if(o.n){const n=o.n;let s='';for(let i=0;i<n;i++){const a=n===1?0:(-26+i*52/(n-1));s+=`<g transform="translate(0,34) rotate(${f(a)}) translate(0,-46)">${_e21slice(col,hc)}</g>`}return `<g transform="translate(0,6)">${s}</g>`}
  return `<g transform="rotate(-6)"><path d="M-100 40 L100 40 L100 -4 Q-20 -30 -100 -64Z" fill="${col}" ${st()}/><path d="M100 40 L100 -4 L84 -10 L84 40Z" fill="${hc}" ${st(C.navy,3)}/><circle cx="-40" cy="10" r="14" fill="${hc}" ${st(C.navy,3)}/><circle cx="18" cy="16" r="10" fill="${hc}" ${st(C.navy,3)}/><circle cx="-62" cy="-20" r="8" fill="${hc}" ${st(C.navy,3)}/><circle cx="52" cy="2" r="9" fill="${hc}" ${st(C.navy,3)}/></g>`};

/* ---------- sandwich (side view, with chosen fillings) ---------- */
P.e21_sandwich=(o,T)=>{const nc=o.cheese==null?1:o.cheese;let layers=[];
  for(let i=0;i<nc;i++)layers.push(['cheese',i%2?'#F6CE4B':'#F2C23C']);
  if(o.tomato)layers.push(['tomato']);if(o.onion)layers.push(['onion']);
  const lh=l=>l[0]==='cheese'?15:l[0]==='tomato'?16:14;
  let total=40+layers.reduce((a,l)=>a+lh(l),0)+50;
  let y=total/2-40,s='';
  s+=`<path d="M-108 ${f(y+12)} Q-108 ${f(y+40)} -80 ${f(y+40)} H80 Q108 ${f(y+40)} 108 ${f(y+12)} V${f(y-14)} H-108Z" fill="#FBE6B8" ${st()}/><path d="M-108 ${f(y+14)} Q-108 ${f(y+40)} -80 ${f(y+40)} H80 Q108 ${f(y+40)} 108 ${f(y+14)}" fill="none" stroke="#C98842" stroke-width="7" stroke-linecap="round"/>`;
  let cy=y-14;
  for(const l of layers){const h=lh(l);cy-=h;
    if(l[0]==='cheese')s+=`<path d="M-112 ${f(cy+h)} V${f(cy+2)} Q-112 ${f(cy)} -108 ${f(cy)} H108 Q112 ${f(cy)} 112 ${f(cy+2)} V${f(cy+h)} L100 ${f(cy+h+7)} L84 ${f(cy+h)} H-112Z" fill="${l[1]}" ${st(C.navy,4)}/>`;
    if(l[0]==='tomato'){for(let i=0;i<4;i++)s+=`<ellipse cx="${-72+i*48}" cy="${f(cy+h/2)}" rx="28" ry="${h/2+2}" fill="#E4472F" ${st(C.navy,4)}/>`}
    if(l[0]==='onion'){s+=`<rect x="-104" y="${f(cy)}" width="208" height="${h}" rx="7" fill="#FFF6DC" ${st(C.navy,4)}/><path d="M-84 ${f(cy+4)} q10 6 20 0 M-24 ${f(cy+4)} q10 6 20 0 M36 ${f(cy+4)} q10 6 20 0" fill="none" ${st('#D8C48E',3)}/>`}}
  const ty=cy;
  s+=`<path d="M-108 ${f(ty)} Q-116 ${f(ty-50)} -60 ${f(ty-54)} Q0 ${f(ty-66)} 60 ${f(ty-54)} Q116 ${f(ty-50)} 108 ${f(ty)}Z" fill="#E1A25B" ${st()}/><path d="M-70 ${f(ty-26)} Q0 ${f(ty-40)} 70 ${f(ty-26)}" fill="none" stroke="#F0C48A" stroke-width="7" stroke-linecap="round"/>`;
  if(o.pepper){for(let i=0;i<9;i++){const ph=(T*.7+i/9)%1;s+=`<circle cx="${f(-60+i*15+Math.sin(i*5)*6)}" cy="${f(ty-100+ph*(70+(i%3)*8))}" r="3.6" fill="#2B2B2B" opacity="${f(1-ph*.6)}"/>`}}
  return `<g transform="translate(0,${f(o.pepper?18:6)})">${s}</g>`};

/* ---------- cutting ---------- */
P.e21_cut=(o,T,k)=>{const w=o.what||'carrot',pal={carrot:['#F28A22','#F8B766'],apple:['#D9534F','#FBE6B8'],banana:['#F7D547','#FBEB94'],onion:['#D9A441','#FFF6DC'],cheese:['#F6CE4B','#E3B22B'],potato:['#C79A5B','#F2DDA8']}[w];
  const g=4+ease(k/1.0)*14;let sl='';
  for(let i=0;i<5;i++){const x=(i-2)*(36+g);
    if(w==='cheese')sl+=`<rect x="${f(x-17)}" y="12" width="34" height="34" rx="5" fill="${pal[0]}" ${st(C.navy,4)}/><circle cx="${f(x-4)}" cy="26" r="5" fill="${pal[1]}"/>`;
    else sl+=`<circle cx="${f(x)}" cy="30" r="19" fill="${pal[0]}" ${st(C.navy,4)}/><circle cx="${f(x)}" cy="30" r="12" fill="${pal[1]}"/>`}
  const ky=-62+Math.abs(Math.sin(T*3.2))*56;
  return `<g><rect x="-126" y="52" width="252" height="40" rx="10" fill="#D9A86C" ${st()}/><path d="M-100 66 h60 M20 78 h80" ${st('#B98348',3)} fill="none"/>${sl}<g transform="translate(0,${f(ky)})"><path d="M-14 -60 H18 V-6 Q18 8 4 14 L-14 14Z" fill="#CAD5DC" ${st()}/><rect x="-10" y="-112" width="24" height="56" rx="9" fill="${C.brown}" ${st()}/><circle cx="2" cy="-96" r="3.2" fill="${C.gold}"/><circle cx="2" cy="-72" r="3.2" fill="${C.gold}"/></g></g>`};

/* ---------- fruit salad bowl and 100 pieces ---------- */
P.e21_bowl=(o,T)=>{let p='';
  for(let i=0;i<24;i++){const x=-88+(i%12)*16,y=-6-(1-Math.abs(x)/95)*(i<12?30:58)-(i%3)*5+Math.sin(T*2+i)*1.2,t=i%4,r=(i*37)%50-25;
    if(t===0)p+=`<rect x="${f(x-11)}" y="${f(y-11)}" width="22" height="22" rx="5" fill="#D9534F" ${st(C.navy,3)} transform="rotate(${r} ${f(x)} ${f(y)})"/>`;
    if(t===1)p+=`<rect x="${f(x-11)}" y="${f(y-11)}" width="22" height="22" rx="5" fill="#7DBB4F" ${st(C.navy,3)} transform="rotate(${r} ${f(x)} ${f(y)})"/>`;
    if(t===2)p+=`<circle cx="${f(x)}" cy="${f(y)}" r="12" fill="#F7D547" ${st(C.navy,3)}/><circle cx="${f(x)}" cy="${f(y)}" r="6" fill="#FBEB94"/>`;
    if(t===3)p+=`<path d="M${f(x-13)} ${f(y)} a13 13 0 0 0 26 0Z" fill="#F5921E" ${st(C.navy,3)} transform="rotate(${r} ${f(x)} ${f(y)})"/>`}
  return `<g transform="translate(0,6)">${p}<path d="M-112 -6 H112 Q104 76 0 84 Q-104 76 -112 -6Z" fill="${C.white}" ${st()}/><path d="M-108 20 H108" fill="none" ${st(C.blue,6)}/><path d="M-80 84 H80" ${st(C.navy,5)} fill="none"/></g>`};
P.e21_grid=(o,T,k)=>{const n=o.n||100,shown=Math.ceil(n*ease(k/1.8));let s='';
  for(let i=0;i<n;i++){if(i>=shown)break;const c=i%10,r=Math.floor(i/10),on=i%2;s+=`<rect x="${-100+c*20+1}" y="${-100+r*20+1}" width="17" height="17" rx="4" fill="${on?'#7DBB4F':'#D9534F'}" ${st(C.navy,2.5)}/>`}
  const rows=Math.ceil(n/10);return `<g transform="translate(0,${f((10-rows)*10)})">${s}</g>`};

/* ---------- supermarket, cart, bags ---------- */
P.e21_store=(o,T)=>{let aw='';for(let i=0;i<6;i++)aw+=`<path d="M${-120+i*40} -40 h40 v28 q-20 18 -40 0Z" fill="${i%2?C.white:C.red}" ${st(C.navy,3)}/>`;
  const prod=(x,y)=>`<circle cx="${x}" cy="${y}" r="9" fill="#E4472F" ${st(C.navy,2)}/><circle cx="${x+20}" cy="${y}" r="9" fill="#F5921E" ${st(C.navy,2)}/><circle cx="${x+10}" cy="${y-16}" r="9" fill="#7DBB4F" ${st(C.navy,2)}/>`;
  return `<g transform="translate(0,6)"><rect x="-118" y="-90" width="236" height="50" rx="8" fill="${C.blue}" ${st()}/><text x="0" y="-55" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="22" fill="${C.cream}" letter-spacing="2">${o.t||'SUPERMARKET'}</text>${aw}<rect x="-112" y="-14" width="224" height="104" fill="#F4E5C2" ${st()}/><rect x="-98" y="2" width="68" height="62" fill="${C.sky}" ${st(C.navy,3)}/>${prod(-82,52)}<rect x="30" y="2" width="68" height="62" fill="${C.sky}" ${st(C.navy,3)}/>${prod(46,52)}<rect x="-22" y="14" width="44" height="76" fill="${C.sky}" ${st(C.navy,4)}/><line x1="0" y1="14" x2="0" y2="90" ${st(C.navy,3)}/></g>`};
P.e21_cart=(o,T)=>{const full=o.full;const items=full?`<circle cx="-48" cy="-30" r="22" fill="#E4472F" ${st(C.navy,3)}/><circle cx="-6" cy="-36" r="20" fill="#F5921E" ${st(C.navy,3)}/><circle cx="36" cy="-30" r="22" fill="#7DBB4F" ${st(C.navy,3)}/><rect x="52" y="-76" width="30" height="46" rx="6" fill="#4DA3D8" ${st(C.navy,3)}/><path d="M-80 -60 l24 -30" ${st(C.leaf,10)} fill="none"/><path d="M-62 -58 l6 -34 M-20 -52 l8 -40" ${st(C.leaf,8)} fill="none"/>`:'';
  return `<g>${items}<path d="M-120 -44 H-96 L-70 52 H78 L108 -14 H-92" fill="${C.white}" fill-opacity=".55" ${st()}/>${[-40,-8,24,56].map(x=>`<line x1="${x}" y1="-20" x2="${x+4}" y2="52" ${st(C.navy,3)}/>`).join('')}<line x1="-90" y1="6" x2="100" y2="6" ${st(C.navy,3)}/><circle cx="-44" cy="78" r="14" fill="${C.navy}" ${st()}/><circle cx="56" cy="78" r="14" fill="${C.navy}" ${st()}/><rect x="-62" y="60" width="140" height="8" rx="3" fill="${C.navy2}" opacity="0"/></g>`};
P.e21_bags=(o,T)=>{const n=o.n||10,cols=[C.brown,'#C9A06A'];let s='';
  for(let i=0;i<n;i++){const few=n<=3,c=i%5,r=Math.floor(i/5),x=few?(i-(n-1)/2)*92:-96+c*48,y=few?10+Math.sin(T*2+i)*1.5:-34+r*86+Math.sin(T*2+i)*1.5;
    s+=`<g transform="translate(${x},${f(y)}) scale(${few?1.6:1})"><path d="M-12 -34 Q-12 -52 0 -52 Q12 -52 12 -34" fill="none" ${st(C.navy,4)}/><path d="M-20 -34 H20 L24 34 H-24Z" fill="${cols[(i+r)%2]}" ${st(C.navy,4)}/><path d="M-20 -16 H20" fill="none" ${st(C.navy,3)} opacity=".5"/></g>`}
  return `<g>${s}</g>`};

/* ---------- pots, rice, dish, kitchen ---------- */
P.e21_pot=(o,T)=>{const fill=o.fill||[],bub=Math.sin(T*6)*3;let c='';
  fill.forEach((col,i)=>{const x=-66+i*(132/Math.max(1,fill.length-1||1));c+=`<circle cx="${f(fill.length>1?x:0)}" cy="${f(-34-((i*7)%3)*6+bub*(i%2?1:-1))}" r="${f(18)}" fill="${col}" ${st(C.navy,3)}/>`});
  const fire=o.fire?[-52,0,52].map((x,i)=>{const sy=1+.18*Math.sin(T*9+i);return `<g transform="translate(${x},118) scale(${f(sy*.6)},${f(sy*.6)})"><path d="M0 -50 C18 -30 26 -12 14 12 C8 26 -8 26 -14 12 C-26 -12 -12 -30 0 -50Z" fill="${C.orange}" ${st('#C9651B',6)}/></g>`}).join(''):'';
  return `<g transform="translate(0,-4)">${_e21steam(T,3,-30,-52,30)}${c}<rect x="-110" y="-8" width="24" height="16" rx="8" fill="${C.navy2}" ${st()}/><rect x="86" y="-8" width="24" height="16" rx="8" fill="${C.navy2}" ${st()}/><path d="M-96 -20 H96 V58 Q96 92 62 92 H-62 Q-96 92 -96 58Z" fill="#8FA3AE" ${st()}/><rect x="-102" y="-30" width="204" height="20" rx="10" fill="#B9C6CE" ${st()}/><path d="M-70 14 V60" fill="none" stroke="#fff" stroke-width="8" stroke-linecap="round" opacity=".6"/>${fire}</g>`};
P.e21_rice=(o,T)=>{let g='',b='';
  for(let i=0;i<22;i++){const a=i*2.4,x=Math.sin(a)*(20+i*2.2)*.9,y=-30-(1-i/22)*38+Math.cos(a)*6;g+=`<ellipse cx="${f(x)}" cy="${f(y)}" rx="9" ry="5" transform="rotate(${(i*47)%180} ${f(x)} ${f(y)})" fill="#fff" ${st(C.navy,2)}/>`}
  if(!o.plain)for(let i=0;i<7;i++){const x=-60+i*20,y=-42+((i*5)%3)*6-Math.abs(i-3)*7;b+=i%2?`<rect x="${x-7}" y="${y-7}" width="14" height="14" rx="3" fill="#F28A22" ${st(C.navy,2.5)}/>`:`<rect x="${x-7}" y="${y-7}" width="14" height="14" rx="3" fill="#E4472F" ${st(C.navy,2.5)}/>`}
  return `<g transform="translate(0,8)">${_e21steam(T,3,-30,-70,30)}<path d="M-88 -22 Q-60 -92 0 -92 Q60 -92 88 -22Z" fill="#fff" ${st()}/>${g}${b}<path d="M-110 -22 H110 Q104 66 0 74 Q-104 66 -110 -22Z" fill="${C.white}" ${st()}/><path d="M-106 4 H106" fill="none" ${st(C.blue,6)}/></g>`};
P.e21_dish=(o,T)=>{let p='';
  const pos=[[-52,-22],[-18,-34],[20,-30],[54,-18],[-62,14],[-26,6],[10,10],[48,14],[-40,40],[-2,38],[34,42]];
  pos.forEach(([x,y],i)=>{p+=`<rect x="${x-14}" y="${y-13}" width="28" height="26" rx="7" fill="#E8C46A" ${st(C.navy,3.5)} transform="rotate(${(i*29)%40-20} ${x} ${y})"/>`});
  if(o.tomato)[[-30,-14],[44,-4],[-8,26]].forEach(([x,y])=>{p+=`<circle cx="${x}" cy="${y}" r="10" fill="#E4472F" ${st(C.navy,3)}/>`});
  if(o.onion)[[10,-22],[-48,8],[28,30]].forEach(([x,y])=>{p+=`<circle cx="${x}" cy="${y}" r="9" fill="#FFF6DC" ${st(C.navy,3)}/><circle cx="${x}" cy="${y}" r="4" fill="none" stroke="#D8C48E" stroke-width="2"/>`});
  if(o.cheese)p+=`<path d="M-66 -6 Q-30 -34 6 -14 Q40 -36 68 -4 Q40 14 20 6 Q-10 30 -40 12 Q-56 14 -66 -6Z" fill="#F6CE4B" ${st(C.navy,3.5)} opacity=".96"/><circle cx="-20" cy="-4" r="5" fill="#E3B22B"/><circle cx="34" cy="-6" r="4" fill="#E3B22B"/>`;
  if(o.pepper)for(let i=0;i<12;i++)p+=`<circle cx="${f(-60+i*11+Math.sin(i*4)*6)}" cy="${f(-30+((i*13)%60))}" r="2.8" fill="#2B2B2B"/>`;
  return `<g><circle r="108" fill="${C.white}" ${st()}/><circle r="84" fill="none" ${st('#CAD5DC',4)}/>${_e21steam(T,3,-30,-100,30)}<g transform="translate(0,4)">${p}</g></g>`};
P.e21_egg=(o,T)=>{let d='';if(o.pepper)for(let i=0;i<10;i++)d+=`<circle cx="${f(-44+i*10+Math.sin(i*4)*6)}" cy="${f(-34+((i*17)%64))}" r="2.8" fill="#2B2B2B"/>`;
  return `<g><circle r="108" fill="${C.white}" ${st()}/><circle r="84" fill="none" ${st('#CAD5DC',4)}/><path d="M-62 -6 Q-70 -56 -14 -62 Q40 -76 66 -34 Q86 8 44 40 Q10 68 -30 52 Q-66 42 -62 -6Z" fill="#fff" ${st(C.navy,4)}/><circle cx="2" cy="-4" r="30" fill="#F6B73C" ${st('#C9871F',4)}/><path d="M-12 -18 Q-6 -26 4 -26" fill="none" stroke="#FFE08A" stroke-width="6" stroke-linecap="round"/>${d}</g>`};
P.e21_kitchen=(o,T)=>`<g><rect x="-126" y="-110" width="252" height="226" rx="14" fill="#F4E5C2" ${st()}/>${[-84,-42,0,42,84].map(x=>`<line x1="${x}" y1="-110" x2="${x}" y2="-6" ${st('#E6D3A6',3)}/>`).join('')}<rect x="-114" y="-100" width="108" height="64" rx="6" fill="${C.brown}" ${st()}/><line x1="-60" y1="-100" x2="-60" y2="-36" ${st()}/><rect x="-66" y="-66" width="4" height="22" rx="2" fill="${C.gold}"/><rect x="-58" y="-66" width="4" height="22" rx="2" fill="${C.gold}"/><path d="M30 -96 v18 M60 -96 v26 M90 -96 v20" ${st(C.navy,4)} fill="none"/><path d="M22 -78 h16 v-8 h-16Z" fill="#B9C6CE" ${st(C.navy,3)}/><ellipse cx="60" cy="-52" rx="16" ry="20" fill="#B9C6CE" ${st(C.navy,3)}/><rect x="82" y="-70" width="16" height="48" rx="6" fill="${C.gold2}" ${st(C.navy,3)}/><rect x="-126" y="14" width="252" height="102" fill="${C.brown}" ${st()}/><rect x="-126" y="2" width="252" height="16" fill="#D9A86C" ${st()}/><rect x="-100" y="30" width="86" height="72" rx="6" fill="#A87449" ${st(C.navy,3)}/><rect x="10" y="-26" width="104" height="28" rx="6" fill="#8FA3AE" ${st()}/><rect x="14" y="30" width="96" height="72" rx="8" fill="#9AA7B0" ${st()}/><rect x="26" y="8" width="20" height="8" rx="4" fill="${C.navy}"/><rect x="76" y="8" width="20" height="8" rx="4" fill="${C.navy}"/><g transform="translate(62,-30) scale(.5)"><path d="M-96 -20 H96 V58 Q96 92 62 92 H-62 Q-96 92 -96 58Z" fill="${C.red}" ${st()}/><rect x="-102" y="-30" width="204" height="20" rx="10" fill="#E88A87" ${st()}/></g>${_e21steam(T,2,52,-60,18)}</g>`;

/* ---------- number, stars, week ---------- */
P.e21_num=(o,T)=>{const t=String(o.n);const fs=t.length>=3?64:t.length===2?88:112;return `<g transform="scale(${f(1+.04*Math.sin(T*4))})"><circle r="84" fill="${C.gold}" ${st()}/><circle r="68" fill="none" ${st(C.goldD,3)}/><text x="0" y="${f(fs*.36)}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${fs}" fill="${C.navy}">${t}</text></g>`};
P.e21_stars=(o,T,k)=>{const n=o.n==null?5:o.n;let s='';
  for(let i=0;i<5;i++){let pts='';for(let j=0;j<10;j++){const r=j%2?15:36,a=-Math.PI/2+j*Math.PI/5;pts+=`${f(Math.cos(a)*r)},${f(Math.sin(a)*r+3)} `}
    const on=i<n,pp=on?1+.08*Math.sin(T*5+i):1;s+=`<g transform="translate(${-96+i*48},0) scale(${f(pp)})"><polygon points="${pts}" fill="${on?C.gold:'#fff'}" ${st(on?C.navy:'#9AA7B0',on?4:4)}/></g>`}
  return `<g>${s}</g>`};
P.e21_week=(o,T)=>{const L=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'],hl=o.hl||[];let b='';
  L.forEach((l,i)=>{const on=hl.includes(i),pulse=on?1+.05*Math.sin(T*5):1;b+=`<g transform="translate(${-102+i*34},0) scale(${f(pulse)})"><rect x="-16" y="-44" width="32" height="88" rx="8" fill="${on?C.gold:C.white}" ${st(C.navy,4)}/><text x="0" y="-18" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="12.5" fill="${C.navy}">${l}</text>${on?`<path d="M-9 12 l7 8 l13 -17" fill="none" ${st(C.moss,5)}/>`:''}</g>`});
  return `<g><rect x="-128" y="-62" width="256" height="124" rx="18" fill="${C.cream}" ${st()}/><g transform="translate(0,0)">${b}</g></g>`};

/* ---------- misc ---------- */
P.e21_give=(o,T)=>{const t=(T*.6)%1,x=-70+ease(t)*140,y=-8-Math.sin(t*Math.PI)*34;
  return `<g><path d="M-76 40 Q0 -34 76 40" fill="none" ${st('#9AA7B0',5)} stroke-dasharray="4 14"/><path d="M62 28 l16 14 l-22 6" fill="none" ${st('#9AA7B0',6)}/><g transform="translate(${f(x)},${f(y)})"><rect x="-40" y="-26" width="80" height="62" rx="8" fill="${C.red}" ${st()}/><rect x="-6" y="-26" width="12" height="62" fill="${C.gold}" ${st(C.navy,3)}/><rect x="-40" y="-4" width="80" height="12" fill="${C.gold}" ${st(C.navy,3)}/><path d="M0 -26 Q-34 -64 -24 -34 Z M0 -26 Q34 -64 24 -34Z" fill="${C.gold}" ${st(C.navy,3)}/></g></g>`};
P.e21_taste=(o,T)=>{return `<g>${_e21steam(T,3,-14,-70,26)}<g transform="rotate(-38)"><path d="M-6 14 L-8 122 Q0 130 8 122 L6 14Z" fill="#B9C6CE" ${st()}/><ellipse cx="0" cy="-22" rx="32" ry="46" fill="#CAD5DC" ${st()}/><ellipse cx="0" cy="-22" rx="22" ry="35" fill="#C9702F" ${st(C.navy,3)}/><circle cx="-6" cy="-34" r="5" fill="#F28A22"/><circle cx="6" cy="-10" r="5" fill="#E4472F"/></g></g>`};
P.e21_balloons=(o,T)=>{const cols=[C.red,C.blue,C.gold];let s='';
  [[-62,-16],[0,-40],[62,-12]].forEach(([x,y],i)=>{const sw=Math.sin(T*1.6+i*1.7)*5;s+=`<g transform="translate(${f(x+sw)},${y})"><path d="M0 52 Q${f(-8+sw)} 84 ${f(-sw*2)} 118" fill="none" ${st(C.navy,3)}/><ellipse rx="40" ry="50" fill="${cols[i]}" ${st()}/><path d="M-4 52 l-8 10 h18Z" fill="${cols[i]}" ${st(C.navy,3)}/><path d="M-22 -22 Q-20 -36 -6 -40" fill="none" stroke="#fff" stroke-width="6" stroke-linecap="round" opacity=".7"/></g>`});return `<g transform="translate(0,-10)">${s}</g>`};
P.e21_bcake=(o,T)=>{let c='';[-34,0,34].forEach((x,i)=>{const fl=1+.18*Math.sin(T*9+i*2);c+=`<rect x="${x-5}" y="-52" width="10" height="30" fill="${[C.blue,C.red,C.moss][i]}" ${st(C.navy,3)}/><path d="M${x} -86 C${x+10} -74 ${x+10} -60 ${x} -58 C${x-10} -60 ${x-10} -74 ${x} -86Z" fill="${C.orange}" ${st('#C9651B',3)} transform="translate(0,${f(-58*(1-fl))}) scale(1,${f(fl)})"/>`});
  return `<g transform="translate(0,16)">${c}<path d="M-100 80 L-100 -6 L100 -6 L100 80 Z" fill="#F4C6D2" ${st()}/><path d="M-100 -6 Q-80 -32 -60 -6 Q-40 -32 -20 -6 Q0 -32 20 -6 Q40 -32 60 -6 Q80 -32 100 -6 L100 0 L-100 0Z" fill="${C.white}" ${st()}/><rect x="-100" y="42" width="200" height="12" fill="#E88CA2"/><ellipse cx="0" cy="84" rx="120" ry="12" fill="${C.cream}" ${st()}/></g>`};
P.e21_sugar=(o,T)=>{let q='';[[-26,10],[10,14],[-8,-12],[28,-16],[-30,-30]].forEach(([x,y],i)=>{q+=`<g transform="translate(${x},${y}) rotate(${(i*23)%30-15})"><rect x="-17" y="-17" width="34" height="34" rx="5" fill="#fff" ${st(C.navy,3.5)}/><path d="M-9 -9 h18" ${st('#CAD5DC',3)} fill="none"/></g>`});
  return `<g><rect x="-62" y="-60" width="124" height="150" rx="26" fill="${C.sky}" fill-opacity=".45" ${st()}/><g transform="translate(0,34)">${q}</g><rect x="-52" y="-84" width="104" height="22" rx="8" fill="${C.gold2}" ${st()}/></g>`};
P.e21_coldbowl=(o,T)=>{const w=Math.sin(T*2)*3;return `<g><g transform="translate(${f(w)},${f(Math.sin(T*2.4)*2)})"><g transform="translate(0,-24) scale(.6)">${_e21D.onion({},T)}</g></g><path d="M-112 -6 H112 Q104 76 0 84 Q-104 76 -112 -6Z" fill="#8CC9E8" ${st()}/><path d="M-100 8 q25 -10 50 0 t50 0 t50 0 t50 0" fill="none" ${st('#fff',4)}/><rect x="-60" y="30" width="30" height="26" rx="6" fill="#fff" ${st(C.navy,3)} transform="rotate(-10)"/><rect x="26" y="26" width="30" height="26" rx="6" fill="#fff" ${st(C.navy,3)} transform="rotate(12)"/><path d="M-116 -6 H116" ${st(C.navy,6)}/></g>`};
P.e21_ripen=(o,T)=>{const t=(Math.sin(T*1.2)+1)/2;return `<g><g transform="translate(-72,0) scale(.58)">${_e21D.banana({green:1,rot:-62},T)}</g><path d="M-8 0 H40 M24 -14 L40 0 L24 14" fill="none" ${st('#9AA7B0',7)}/><g transform="translate(86,0) scale(.58)">${_e21D.banana({rot:-62},T)}</g></g>`};
P.e21_hero=(o,T)=>{let fl='';[['carrot',-64,-30],['tomato',0,-60],['onion',64,-30]].forEach(([n,x,y],i)=>{const ph=(T*.7+i/3)%1,u=Math.sin(ph*Math.PI);fl+=`<g transform="translate(${x},${f(y-u*46-40)}) rotate(${f(Math.sin(T*3+i)*18)}) scale(${n==='carrot'?.3:.34})">${_e21D[n]({rot:20},T)}</g>`});
  return `<g transform="translate(0,6)">${fl}<g transform="translate(0,26)">${P.e21_pot({fire:1,fill:[C.orange,'#E4472F','#FFF6DC']},T)}</g></g>`};

/* Episode 22 props: clothes (T-shirt, jeans, trousers, skirt, hat, jacket), shop, website, money. Faceless. Uses C, st, f, ease, clamp, P. */
const _e22cat=(col)=>`<g><path d="M22 34 Q58 34 48 -4" fill="none" ${st(C.navy,9)}/><path d="M22 34 Q58 34 48 -4" fill="none" stroke="${col}" stroke-width="4" stroke-linecap="round"/><path d="M-20 -16 Q-32 20 -24 34 H24 Q32 20 20 -16Z" fill="${col}" ${st(C.navy,3.5)}/><polygon points="-17,-40 -15,-60 -2,-46" fill="${col}" ${st(C.navy,3.5)}/><polygon points="17,-40 15,-60 2,-46" fill="${col}" ${st(C.navy,3.5)}/><circle cx="0" cy="-30" r="19" fill="${col}" ${st(C.navy,3.5)}/></g>`;
const _e22car=()=>`<g><path d="M-46 16 V2 Q-46 -6 -38 -8 L-24 -26 Q-20 -30 -14 -30 H16 Q22 -30 26 -26 L38 -8 Q46 -6 46 2 V16Z" fill="${C.red}" ${st(C.navy,3.5)}/><path d="M-20 -8 L-12 -22 H-2 V-8Z M4 -8 V-22 H14 L22 -8Z" fill="${C.sky}" ${st(C.navy,2.5)}/><circle cx="-26" cy="16" r="10" fill="${C.navy}"/><circle cx="26" cy="16" r="10" fill="${C.navy}"/><circle cx="-26" cy="16" r="4" fill="#CAD5DC"/><circle cx="26" cy="16" r="4" fill="#CAD5DC"/></g>`;
const _e22flowers=(s)=>{let r='';[[-26,-14,'#F28CB1'],[10,-22,'#8E4FB5'],[30,6,'#F28CB1'],[-8,14,'#8E4FB5'],[-34,26,'#8E4FB5'],[20,34,'#F28CB1']].forEach(([x,y,c])=>{r+=`<g transform="translate(${x},${y}) scale(${s||1})">${[0,72,144,216,288].map(a=>`<circle cx="0" cy="-7" r="5.5" fill="${c}" transform="rotate(${a})"/>`).join('')}<circle r="3.6" fill="${C.gold}"/></g>`});return r};
const _e22front=(k)=>k==='cat'?`<g transform="translate(0,22) scale(1.15)">${_e22cat('#8D969C')}</g>`:k==='car'?`<g transform="translate(0,26) scale(1.3)">${_e22car()}</g>`:k==='flowers'?`<g transform="translate(0,24) scale(1.2)">${_e22flowers(1)}</g>`:'';

/* ---------- clothes ---------- */
P.e22_tee=(o,T)=>{const c=o.c||'#9AA3A9';
  return `<g><path d="M-40 -84 Q0 -62 40 -84 L96 -54 L74 -6 L52 -20 L52 92 H-52 V-20 L-74 -6 L-96 -54Z" fill="${c}" ${st()}/><path d="M-40 -84 Q0 -54 40 -84" fill="none" ${st(C.navy,5)}/><path d="M-30 -72 Q0 -46 30 -72" fill="none" stroke="#fff" stroke-width="3" opacity=".35"/>${_e22front(o.front)}</g>`};
P.e22_shirt=(o,T)=>{const c=o.c||'#FFFFFF';let b='';for(let i=0;i<4;i++)b+=`<circle cx="0" cy="${-34+i*30}" r="4.5" fill="${C.navy}" opacity=".75"/>`;
  return `<g><path d="M-38 -88 Q0 -70 38 -88 L88 -62 L112 36 L86 44 L66 -8 L50 -20 V92 H-50 V-20 L-66 -8 L-86 44 L-112 36 L-88 -62Z" fill="${c}" ${st()}/><path d="M-38 -88 L-4 -60 L-24 -48 L-48 -78Z M38 -88 L4 -60 L24 -48 L48 -78Z" fill="${c}" ${st(C.navy,4)}/><line x1="0" y1="-58" x2="0" y2="92" ${st(C.navy,3)} opacity=".6"/>${b}<path d="M-86 44 L-112 36 M86 44 L112 36" ${st(C.navy,3)}/></g>`};
P.e22_trousers=(o,T)=>{const c=o.c||'#4A5259',L=o.short?14:104,jeans=o.jeans;let d='';
  if(jeans)d=`<path d="M-44 -82 Q-30 -56 -12 -60 M44 -82 Q30 -56 12 -60" fill="none" stroke="${C.orange}" stroke-width="3" stroke-dasharray="6 4"/><rect x="-36" y="-20" width="22" height="26" rx="4" fill="none" stroke="${C.orange}" stroke-width="3" stroke-dasharray="6 4" opacity=".0"/>`;
  else d=`<line x1="-34" y1="-70" x2="-34" y2="${L-14}" stroke="#fff" stroke-width="3" opacity=".25"/><line x1="34" y1="-70" x2="34" y2="${L-14}" stroke="#fff" stroke-width="3" opacity=".25"/>`;
  return `<g transform="translate(0,${o.short?44:0})"><path d="M-52 -100 H52 L60 ${L} H10 L0 -22 L-10 ${L} H-60Z" fill="${c}" ${st()}/><rect x="-52" y="-100" width="104" height="16" fill="${c}" ${st()}/><line x1="-52" y1="-84" x2="52" y2="-84" ${st(C.navy,3)} opacity=".55"/>${d}<line x1="0" y1="-84" x2="0" y2="-22" ${st(C.navy,3)} opacity=".45"/>${jeans?`<path d="M-48 ${L-14} H-14 M14 ${L-14} H48" ${st(C.orange,3)} stroke-dasharray="6 4" fill="none"/>`:''}</g>`};
P.e22_jeans=(o,T)=>P.e22_trousers({c:o.c||'#3F6EA8',jeans:1,short:o.short},T);
P.e22_skirt=(o,T)=>{const c=o.c||'#8E4FB5',L=o.short?50:104;
  return `<g transform="translate(0,${o.short?30:0})"><path d="M-42 -78 H42 L${40+L*.42} ${L} Q0 ${L+16} ${-40-L*.42} ${L}Z" fill="${c}" ${st()}/><rect x="-44" y="-94" width="88" height="18" rx="6" fill="${c}" ${st()}/>${[-24,0,24].map(x=>`<path d="M${x} -74 L${x*2.2} ${L-4}" fill="none" stroke="#fff" stroke-width="3" opacity=".25"/>`).join('')}${o.flowers?`<g transform="translate(0,12) scale(1.1)">${_e22flowers(1)}</g>`:''}</g>`};
P.e22_hat=(o,T)=>{const c=o.c||'#F28CB1',ty=o.type||'round';
  if(ty==='beanie')return `<g transform="translate(0,6)"><circle cx="0" cy="-66" r="16" fill="#fff" ${st()}/><path d="M-62 40 Q-66 -40 0 -56 Q66 -40 62 40Z" fill="${c}" ${st()}/><rect x="-64" y="16" width="128" height="34" rx="10" fill="${c}" ${st()}/>${[-48,-32,-16,0,16,32,48].map(x=>`<line x1="${x}" y1="20" x2="${x}" y2="46" stroke="${C.navy}" stroke-width="3" opacity=".35"/>`).join('')}</g>`;
  if(ty==='cap')return `<g transform="translate(-8,10)"><path d="M-70 24 Q-70 -50 0 -52 Q70 -50 70 24Z" fill="${c}" ${st()}/><circle cx="0" cy="-52" r="7" fill="${c}" ${st(C.navy,4)}/><path d="M-70 24 H70" ${st(C.navy,4)}/><path d="M30 18 Q108 2 126 40 Q82 52 30 32Z" fill="${c}" ${st()}/><path d="M-20 -40 Q10 -50 36 -34" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round" opacity=".4"/></g>`;
  return `<g transform="translate(0,6)"><ellipse cx="0" cy="34" rx="108" ry="26" fill="${c}" ${st()}/><path d="M-58 32 Q-58 -52 0 -56 Q58 -52 58 32Z" fill="${c}" ${st()}/><path d="M-58 20 Q0 36 58 20 V34 Q0 48 -58 34Z" fill="${C.navy}" opacity=".75"/><path d="M-34 -30 Q-18 -46 6 -46" fill="none" stroke="#fff" stroke-width="6" stroke-linecap="round" opacity=".45"/></g>`};
P.e22_jacket=(o,T)=>{const c=o.c||'#2F6B4F',len=o.short?44:90;
  return `<g transform="translate(0,${o.short?20:0})"><path d="M-40 -86 L-96 -58 L-108 46 L-80 50 L-60 -8 L-54 -20 V${len} H54 V-20 L60 -8 L80 50 L108 46 L96 -58 L40 -86 L24 -66 H-24Z" fill="${c}" ${st()}/><path d="M-40 -86 L-24 -66 L-6 -92Z M40 -86 L24 -66 L6 -92Z" fill="${c}" ${st(C.navy,4)}/><line x1="0" y1="-66" x2="0" y2="${len}" ${st(C.navy,4)}/><rect x="-42" y="${len-34}" width="28" height="22" rx="5" fill="none" ${st(C.navy,3.5)} opacity=".6"/><rect x="14" y="${len-34}" width="28" height="22" rx="5" fill="none" ${st(C.navy,3.5)} opacity=".6"/><rect x="-5" y="-60" width="10" height="16" rx="3" fill="${C.gold}" ${st(C.navy,2.5)}/></g>`};

/* ---------- a whole (faceless) person wearing an outfit ---------- */
P.e22_wear=(o,T)=>{const skin='#E3AE82',bob=Math.sin(T*2)*2,top=o.top||'#9AA3A9',long=o.longsleeve,bot=o.bot||'#3F6EA8',kind=o.kind||'jeans',hc=o.hc||'#222',hair=o.hair||'short';
  let h=hair==='bun'?`<circle cx="0" cy="-124" r="10" fill="${hc}" ${st(C.navy,3)}/><path d="M-20 -106 Q-22 -128 0 -128 Q22 -128 20 -106 Q0 -116 -20 -106Z" fill="${hc}" ${st(C.navy,3)}/>`:`<path d="M-20 -106 Q-22 -128 0 -128 Q22 -128 20 -106 Q6 -116 -20 -106Z" fill="${hc}" ${st(C.navy,3)}/>`;
  let b;
  if(kind==='skirt')b=`<path d="M-30 2 H30 L46 66 Q0 76 -46 66Z" fill="${bot}" ${st(C.navy,4)}/><rect x="-22" y="66" width="16" height="30" fill="${skin}" ${st(C.navy,3.5)}/><rect x="6" y="66" width="16" height="30" fill="${skin}" ${st(C.navy,3.5)}/>`;
  else b=`<rect x="-30" y="0" width="28" height="98" rx="5" fill="${bot}" ${st(C.navy,4)}/><rect x="2" y="0" width="28" height="98" rx="5" fill="${bot}" ${st(C.navy,4)}/>`;
  const arms=long?`<rect x="-52" y="-80" width="17" height="80" rx="8" fill="${top}" ${st(C.navy,3.5)}/><rect x="35" y="-80" width="17" height="80" rx="8" fill="${top}" ${st(C.navy,3.5)}/>`:`<rect x="-50" y="-52" width="14" height="46" rx="7" fill="${skin}" ${st(C.navy,3.5)}/><rect x="36" y="-52" width="14" height="46" rx="7" fill="${skin}" ${st(C.navy,3.5)}/><rect x="-54" y="-82" width="20" height="38" rx="9" fill="${top}" ${st(C.navy,3.5)}/><rect x="34" y="-82" width="20" height="38" rx="9" fill="${top}" ${st(C.navy,3.5)}/>`;
  const hat=o.hat?`<g transform="translate(0,-122) scale(.34)">${P.e22_hat({c:o.hat},T)}</g>`:'';
  return `<g transform="translate(0,${f(bob+8)}) scale(.98)">${b}<ellipse cx="-16" cy="100" rx="17" ry="7" fill="${C.navy}"/><ellipse cx="16" cy="100" rx="17" ry="7" fill="${C.navy}"/>${arms}<rect x="-36" y="-84" width="72" height="92" rx="14" fill="${top}" ${st(C.navy,4)}/><rect x="-8" y="-92" width="16" height="12" fill="${skin}" ${st(C.navy,3)}/><circle cx="0" cy="-104" r="22" fill="${skin}" ${st()}/>${h}${hat}</g>`};

/* ---------- shop, rack, website ---------- */
const _e22hang=(x,item,s,T,i)=>`<g transform="translate(${x},-76) rotate(${f(Math.sin(T*1.6+i*1.4)*3)})"><path d="M0 0 q0 -14 10 -14" fill="none" ${st(C.navy,3.5)}/><path d="M-30 26 L0 6 L30 26Z" fill="none" ${st(C.brown,4)}/><g transform="translate(0,${f(26+s*84)}) scale(${s})">${item}</g></g>`;
P.e22_rack=(o,T)=>`<g><line x1="-118" y1="-84" x2="118" y2="-84" ${st(C.navy2,7)}/><line x1="-114" y1="-84" x2="-114" y2="112" ${st(C.navy2,7)}/><line x1="114" y1="-84" x2="114" y2="112" ${st(C.navy2,7)}/><line x1="-114" y1="112" x2="-134" y2="116" ${st(C.navy2,6)}/><line x1="114" y1="112" x2="134" y2="116" ${st(C.navy2,6)}/>${_e22hang(-82,P.e22_tee({c:'#F28CB1'},T),.36,T,0)}${_e22hang(-28,P.e22_shirt({},T),.36,T,1)}${_e22hang(28,P.e22_jacket({},T),.36,T,2)}${_e22hang(82,P.e22_skirt({},T),.36,T,3)}</g>`;
P.e22_shop=(o,T)=>{let aw='';for(let i=0;i<6;i++)aw+=`<path d="M${-120+i*40} -40 h40 v28 q-20 18 -40 0Z" fill="${i%2?C.white:C.moss}" ${st(C.navy,3)}/>`;
  return `<g transform="translate(0,6)"><rect x="-118" y="-90" width="236" height="50" rx="8" fill="${C.moss}" ${st()}/><text x="0" y="-52" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="34" fill="${C.cream}" letter-spacing="8">SHOP</text>${aw}<rect x="-112" y="-14" width="224" height="104" fill="#F4E5C2" ${st()}/><rect x="-98" y="2" width="68" height="62" fill="${C.sky}" ${st(C.navy,3)}/><g transform="translate(-64,32) scale(.26)">${P.e22_tee({c:'#F28CB1'},T)}</g><rect x="30" y="2" width="68" height="62" fill="${C.sky}" ${st(C.navy,3)}/><g transform="translate(64,32) scale(.26)">${P.e22_skirt({},T)}</g><rect x="-22" y="14" width="44" height="76" fill="${C.sky}" ${st(C.navy,4)}/><line x1="0" y1="14" x2="0" y2="90" ${st(C.navy,3)}/></g>`};
P.e22_web=(o,T)=>{const items=[P.e22_tee({c:'#F28CB1'},T),P.e22_jeans({},T),P.e22_hat({},T),P.e22_skirt({},T)];let g='';
  items.forEach((it,i)=>{const x=-52+(i%2)*104,y=-12+Math.floor(i/2)*84,pick=o.pick&&i===1;g+=`<g transform="translate(${x},${y})"><rect x="-44" y="-38" width="88" height="76" rx="8" fill="${C.white}" ${st(pick?C.gold:C.navy,pick?5:3)}/><g transform="translate(0,0) scale(.3)">${it}</g>${pick?`<circle cx="36" cy="-32" r="13" fill="${C.moss}" ${st(C.navy,3)}/><path d="M30 -32 l5 6 l9 -12" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round"/>`:''}</g>`});
  const cur=o.look?`<g transform="translate(${f(30+Math.sin(T*2)*14)},${f(30+Math.cos(T*2)*10)})"><path d="M0 0 V40 L11 30 L20 48 L28 44 L19 27 L34 26Z" fill="#fff" ${st(C.navy,3.5)}/></g>`:'';
  return `<g><rect x="-112" y="-110" width="224" height="228" rx="16" fill="#F4EFE0" ${st()}/><rect x="-112" y="-110" width="224" height="30" rx="16" fill="${C.blue}" ${st()}/><rect x="-112" y="-96" width="224" height="16" fill="${C.blue}"/><rect x="-96" y="-104" width="150" height="18" rx="9" fill="#fff" ${st(C.navy,2.5)}/><g transform="translate(0,6)">${g}</g>${cur}</g>`};

/* ---------- money, tags, parcels ---------- */
P.e22_card=(o,T)=>`<g transform="rotate(${f(-8+Math.sin(T*2)*3)})"><rect x="-108" y="-68" width="216" height="136" rx="18" fill="${C.blue}" ${st()}/><rect x="-108" y="-36" width="216" height="26" fill="${C.navy}"/><rect x="-86" y="6" width="44" height="34" rx="7" fill="${C.gold}" ${st(C.goldD,3)}/><line x1="-86" y1="23" x2="-42" y2="23" ${st(C.goldD,2.5)}/><rect x="-18" y="30" width="96" height="10" rx="5" fill="#fff" opacity=".6"/></g>`;
P.e22_note=(o,T)=>`<g transform="rotate(${f(-6+Math.sin(T*2)*2)})"><rect x="-106" y="-58" width="212" height="116" rx="10" fill="#7BB77B" ${st()}/><rect x="-92" y="-44" width="184" height="88" rx="6" fill="none" stroke="#2F6B4F" stroke-width="3"/><circle r="34" fill="#A9D6A0" ${st('#2F6B4F',3)}/><text x="0" y="14" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="44" fill="#2F6B4F">$</text></g>`;
P.e22_notes=(o,T,k)=>{const n=o.n||100,shown=Math.ceil(n*ease(k/1.8));let s='';
  for(let i=0;i<shown;i++){const c=i%10,r=Math.floor(i/10);s+=`<rect x="${-110+c*22+1}" y="${-80+r*16+1}" width="19" height="13" rx="3" fill="#7BB77B" ${st('#2F6B4F',2)}/><circle cx="${-110+c*22+10.5}" cy="${-80+r*16+7.5}" r="3" fill="#A9D6A0"/>`}
  return `<g transform="translate(0,${f((10-Math.ceil(n/10))*8)})">${s}</g>`};
P.e22_tag=(o,T)=>{const t=o.t||'$50',fs=t.length>3?42:52;return `<g transform="rotate(${f(-10+Math.sin(T*2)*4)})"><path d="M-90 -46 H40 L100 0 L40 46 H-90 Q-100 46 -100 36 V-36 Q-100 -46 -90 -46Z" fill="${C.white}" ${st()}/><circle cx="-72" cy="0" r="9" fill="${C.navy}" opacity=".85"/><path d="M-72 0 Q-100 -60 -60 -84" fill="none" ${st(C.navy,4)}/><text x="-12" y="${fs*.36}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${fs}" fill="${C.navy}">${t}</text></g>`};
P.e22_parcel=(o,T)=>`<g><g transform="translate(-10,16)"><path d="M-82 -52 L0 -78 L82 -52 V50 L0 78 L-82 50Z" fill="#C79A5B" ${st()}/><path d="M-82 -52 L0 -26 L82 -52 M0 -26 V78" fill="none" ${st(C.navy,4)}/><path d="M-30 -66 L-30 -14 L12 0 V-52Z" fill="#E2BE88" opacity=".9" ${st(C.navy,3)}/></g><path d="M62 -70 Q108 -70 108 -20 M108 -20 l-14 -12 M108 -20 l14 -12" fill="none" ${st(C.moss,8)} transform="translate(-6,0)"/></g>`;
P.e22_moneyback=(o,T)=>{const ph=(T*.7)%1;return `<g><g transform="translate(-16,36) scale(.62) rotate(-8)">${P.e22_card({},0).replace(/^<g transform="[^"]*">/,'<g>')}</g><g transform="translate(50,-58) scale(.8)">${P.coins({},T)}</g><path d="M30 -30 Q-30 -34 -52 8" fill="none" ${st(C.moss,8)}/><path d="M-64 -12 l12 22 l18 -16" fill="none" ${st(C.moss,8)}/></g>`};
P.e22_thankcard=(o,T)=>`<g transform="rotate(${f(-5+Math.sin(T*2)*2)})"><rect x="-86" y="-70" width="172" height="140" rx="12" fill="#F7B6CF" ${st()}/><text x="0" y="-14" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="34" fill="${C.navy}">Thank</text><text x="0" y="22" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="34" fill="${C.navy}">you</text><path d="M0 62 C-18 46 -26 36 -14 30 C-6 28 0 34 0 38 C0 34 6 28 14 30 C26 36 18 46 0 62Z" fill="${C.red}" transform="translate(0,22) scale(.55)"/></g>`;

/* ---------- colours, week, queue ---------- */
P.e22_colors=(o,T)=>{const l=o.l||['#F28CB1','#8E4FB5','#2F6B4F','#8D969C','#24406A','#F2994A'],n=l.length;let s='';
  l.forEach((c,i)=>{let x,y;if(n<=4){x=(i-(n-1)/2)*(n>2?64:90);y=0}else{const per=Math.ceil(n/2),r=i<per?0:1,j=r?i-per:i,cnt=r?n-per:per;x=(j-(cnt-1)/2)*70;y=r?44:-44}
    const sc=1+.05*Math.sin(T*3+i);s+=`<g transform="translate(${f(x)},${f(y)}) scale(${f(sc)})"><circle r="${n<=4?(n>2?30:44):32}" fill="${c}" ${st()}/><path d="M-14 -16 Q-6 -24 6 -24" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round" opacity=".45"/></g>`});
  return `<g>${s}</g>`};
P.e22_week=(o,T)=>{const L=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'],hl=o.hl||[];let b='';
  L.forEach((l,i)=>{const on=hl.includes(i),pulse=on?1+.05*Math.sin(T*5):1;b+=`<g transform="translate(${-102+i*34},0) scale(${f(pulse)})"><rect x="-16" y="-44" width="32" height="88" rx="8" fill="${on?C.gold:C.white}" ${st(C.navy,4)}/><text x="0" y="-18" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="12.5" fill="${C.navy}">${l}</text>${on?`<path d="M-9 12 l7 8 l13 -17" fill="none" ${st(C.moss,5)}/>`:''}</g>`});
  return `<g><rect x="-128" y="-62" width="256" height="124" rx="18" fill="${C.cream}" ${st()}/>${b}</g>`};
P.e22_queue=(o,T)=>{const cs=[C.red,C.blue,C.moss,C.orange,'#8E6BB5'],hs=['short','long','bun','short','long'];let s='';
  for(let i=4;i>=0;i--){const x=2+i*29,sc=.32-i*.01;s+=`<g transform="translate(${x},${f(48+i*-3)}) scale(${f(sc)})">${P.person({c:cs[i],hair:hs[i],hc:'#3A2A22',ph:i},T)}</g>`}
  return `<g><rect x="-126" y="30" width="96" height="62" rx="8" fill="${C.brown}" ${st()}/><rect x="-130" y="24" width="104" height="12" rx="5" fill="#D9A86C" ${st()}/><g transform="translate(-76,-34) scale(.56)">${P.person({c:'#8E6BB5',hair:'short',hc:'#222',bag:C.gold2},T)}</g>${s}</g>`};

/* ---------- hero: clothes rail with swinging clothes ---------- */
P.e22_hero=(o,T)=>`<g transform="translate(0,16)"><line x1="-124" y1="-100" x2="124" y2="-100" ${st(C.navy2,8)}/><line x1="-116" y1="-100" x2="-116" y2="110" ${st(C.navy2,8)}/><line x1="116" y1="-100" x2="116" y2="110" ${st(C.navy2,8)}/><g transform="translate(0,-24)">${_e22hang(-70,P.e22_tee({c:'#F28CB1'},T),.46,T,0)}${_e22hang(0,P.e22_jacket({},T),.46,T,1.4)}${_e22hang(70,P.e22_skirt({flowers:1},T),.46,T,2.8)}</g><line x1="-116" y1="110" x2="-136" y2="116" ${st(C.navy2,6)}/><line x1="116" y1="110" x2="136" y2="116" ${st(C.navy2,6)}/></g>`;
P.e22_num=(o,T)=>{const t=String(o.n),fs=t.length>=3?64:t.length===2?88:112;return `<g transform="scale(${f(1+.04*Math.sin(T*4))})"><circle r="84" fill="${C.gold}" ${st()}/><circle r="68" fill="none" ${st(C.goldD,3)}/><text x="0" y="${f(fs*.36)}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${fs}" fill="${C.navy}">${t}</text></g>`};
P.e22_bag=(o,T)=>`<g><g transform="translate(0,-34) scale(.4) rotate(${f(Math.sin(T*2)*4)})">${P.e22_tee({c:'#F28CB1'},T)}</g><path d="M-36 -44 Q-36 -92 0 -92 Q36 -92 36 -44" fill="none" ${st(C.navy,7)}/><path d="M-76 -40 H76 L88 104 H-88Z" fill="#C79A5B" ${st()}/><path d="M-76 -40 H76 L80 -16 H-80Z" fill="#E2BE88" ${st(C.navy,4)}/><path d="M-70 40 H70" fill="none" ${st(C.navy,3)} opacity=".35"/></g>`;

/* Episode 23 props: a day in a new city (museum, bicycle, directions, island, photos, centuries...). Faceless. Uses C, st, f, ease, clamp, P. */
const _e23star=(x,y,r,col)=>{let p='';for(let i=0;i<10;i++){const rr=i%2?r*.42:r,a=-Math.PI/2+i*Math.PI/5;p+=`${f(x+Math.cos(a)*rr)},${f(y+Math.sin(a)*rr)} `}return `<polygon points="${p}" fill="${col||C.gold}" ${st(C.goldD,3)}/>`};
const _e23pin=(x,y,s,col)=>`<g transform="translate(${f(x)},${f(y)}) scale(${f(s)})"><path d="M0 0 C-30 -34 -34 -50 -34 -62 a34 34 0 1 1 68 0 C34 -50 30 -34 0 0Z" fill="${col||C.red}" ${st()}/><circle cx="0" cy="-62" r="13" fill="${C.cream}" ${st(C.navy,3)}/></g>`;
const _e23letter=(x,y,r,t,col,tc)=>`<g transform="translate(${x},${y})"><circle r="${r}" fill="${col||C.gold}" ${st()}/><text x="0" y="${f(r*.38)}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${f(r*1.05)}" fill="${tc||C.navy}">${t}</text></g>`;
const _e23waves=(x0,x1,y,T,n,col)=>{let s='';for(let r=0;r<n;r++){let d=`M${x0} ${y+r*22}`;for(let i=0;i<Math.ceil((x1-x0)/40);i++)d+=` q10 -9 20 0 t20 0`;s+=`<path d="${d}" fill="none" ${st(col||'#fff',4)} opacity=".8" transform="translate(${f(Math.sin(T*1.5+r)*10)},0)"/>`}return s};

/* ---------- museum ---------- */
P.e23_museum=(o,T)=>{let cols='';for(let i=0;i<4;i++)cols+=`<rect x="${-78+i*52}" y="-30" width="22" height="92" fill="${C.cream}" ${st(C.navy,4)}/>`;
  let st2='';for(let i=0;i<3;i++)st2+=`<rect x="${-124+i*8}" y="${62+i*14}" width="${248-i*16}" height="14" fill="${i%2?'#DCD2B8':'#E8DFC8'}" ${st(C.navy,4)}/>`;
  return `<g><polygon points="-120,-30 0,-100 120,-30" fill="${C.gold2}" ${st()}/><rect x="-60" y="-52" width="120" height="22" rx="4" fill="${C.cream}" ${st(C.navy,3)}/><text x="0" y="-35" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="17" fill="${C.navy}" letter-spacing="2">MUSEUM</text><rect x="-112" y="-32" width="224" height="10" fill="#E8DFC8" ${st(C.navy,4)}/>${cols}${st2}</g>`};

/* ---------- bicycle ---------- */
P.e23_bike=(o,T)=>{const a=o.still?0:T*230,wob=o.still?0:Math.sin(T*6)*1.2;
  const wheel=(cx)=>{let s='';for(let i=0;i<6;i++)s+=`<line x1="0" y1="-38" x2="0" y2="38" transform="rotate(${f(a+i*30)})" ${st('#9AA7B0',2.5)}/>`;return `<g transform="translate(${cx},34)"><circle r="42" fill="#fff" fill-opacity=".3"/>${s}<circle r="42" fill="none" ${st(C.navy,8)}/><circle r="6" fill="${C.navy}"/></g>`};
  const px=-6+Math.cos(a*.0174*1.4)*14,py=34+Math.sin(a*.0174*1.4)*14;
  let tr='';if(o.tired)for(let i=0;i<3;i++){const ph=(T*.9+i/3)%1;tr+=`<path d="M${f(-30+i*38)} ${f(-76-ph*34)} q-9 12 0 20 q9 -8 0 -20" fill="${C.blue}" opacity="${f(1-ph)}"/>`}
  let sp='';if(o.go&&!o.still)for(let i=0;i<3;i++){const ph=(T*1.4+i/3)%1;sp+=`<line x1="${f(-120-ph*20)}" y1="${-10+i*26}" x2="${f(-100-ph*20)}" y2="${-10+i*26}" ${st(C.grey,5)} opacity="${f(1-ph)}"/>`}
  return `<g transform="translate(0,${f(wob)})">${sp}${wheel(-70)}${wheel(70)}<path d="M-70 34 L-6 34 L-22 -34 Z M-6 34 L42 -34 L70 34 M-22 -34 L42 -34" fill="none" ${st(C.red,9)}/><path d="M42 -34 L36 -62 M24 -64 L52 -66" fill="none" ${st(C.navy,7)}/><rect x="-40" y="-46" width="36" height="12" rx="6" fill="${C.navy}"/><line x1="-6" y1="34" x2="${f(px)}" y2="${f(py)}" ${st(C.navy,6)}/><rect x="${f(px-10)}" y="${f(py-3)}" width="20" height="7" rx="3" fill="${C.navy}"/>${tr}</g>`};

/* ---------- compass (N E S W) ---------- */
P.e23_compass=(o,T)=>{const dir=o.dir,ang={N:0,E:90,S:180,W:270}[dir],pos={N:[0,-76],E:[76,0],S:[0,76],W:[-76,0]};
  let l='';['N','E','S','W'].forEach(k=>{const on=k===dir,p=pos[k],pu=on?1+.1*Math.sin(T*6):1;l+=`<g transform="translate(${p[0]},${p[1]}) scale(${f(pu)})"><circle r="${on?27:22}" fill="${on?C.gold:C.white}" ${st()}/><text x="0" y="${on?11:9}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${on?32:26}" fill="${C.navy}">${k}</text></g>`});
  const na=dir?ang:Math.sin(T*1.3)*40;
  return `<g><circle r="112" fill="${C.cream}" ${st(C.navy,7)}/><circle r="96" fill="none" ${st(C.grey,3)}/><g transform="rotate(${f(na)})"><polygon points="0,-62 14,0 -14,0" fill="${C.red}" ${st(C.navy,3)}/><polygon points="0,62 14,0 -14,0" fill="${C.grey}" ${st(C.navy,3)}/></g><circle r="8" fill="${C.gold}" ${st(C.navy,3)}/>${l}</g>`};

/* ---------- route diagrams (top view): across / through / around ---------- */
P.e23_route=(o,T)=>{const k=o.k||'across',u=(T*.28)%1;let base='',path='',x,y,ax,ay,ar;
  if(k==='across'){let b='';[[-96,-66],[-30,-66],[40,-66],[-96,22],[-34,22],[44,22]].forEach(([bx,by],i)=>{b+=`<rect x="${bx}" y="${by}" width="${[50,56,60,56,60,52][i]}" height="${[44,44,44,40,40,40][i]}" rx="6" fill="${i%2?'#C9B58A':'#D9C9A2'}" ${st(C.navy,3)}/>`});
    base=`<rect x="-120" y="-90" width="240" height="180" rx="16" fill="#EFE6CF" ${st()}/>${b}<rect x="-120" y="-12" width="240" height="26" fill="#9FA9AF"/>`;
    path=`M-120 1 H100`;x=-110+u*210;y=1;ax=106;ay=1;ar=0}
  else if(k==='through'&&!o.park){let b='';[[-100,-84,46,34],[-40,-84,50,34],[26,-84,40,34],[80,-84,36,34],[-100,26,36,58],[-56,26,52,58],[16,26,44,58],[70,-24,46,24],[70,26,46,58]].forEach(([bx,by,bw,bh],i)=>{b+=`<rect x="${bx}" y="${by}" width="${bw}" height="${bh}" rx="5" fill="${i%2?'#C9B58A':'#D9C9A2'}" ${st(C.navy,3)}/>`});
    base=`<rect x="-120" y="-90" width="240" height="180" rx="16" fill="#EFE6CF" ${st()}/>${b}`;
    path=`M-120 -42 H-66 V8 H4 V-44 H64 V6 H120`;const pts=[[-120,-42],[-66,-42],[-66,8],[4,8],[4,-44],[64,-44],[64,6],[120,6]];const L=[54,50,70,52,60,50,56];const tot=L.reduce((a,c)=>a+c,0);let dd=u*tot,i=0;while(i<L.length-1&&dd>L[i]){dd-=L[i];i++}const pa=pts[i],pb=pts[i+1],r=dd/L[i];x=pa[0]+(pb[0]-pa[0])*r;y=pa[1]+(pb[1]-pa[1])*r;ax=112;ay=6;ar=0}
  else if(k==='through'){let t='';[[-84,-52],[-46,-66],[-8,-56],[34,-64],[78,-50],[-76,52],[-36,66],[8,58],[50,66],[88,52]].forEach(([tx,ty],i)=>{t+=`<g transform="translate(${tx},${ty}) scale(.34)"><circle r="46" cy="-20" fill="${C.leaf}" ${st(C.navy,8)}/><rect x="-8" y="20" width="16" height="30" fill="${C.brown}"/></g>`});
    base=`<rect x="-120" y="-90" width="240" height="180" rx="16" fill="#8EBE7E" ${st()}/><ellipse cx="0" cy="0" rx="96" ry="56" fill="#A8D294"/>${t}`;
    path=`M-120 14 Q-60 -26 0 6 T100 -8`;const uu=u;x=-110+uu*205;y=14-Math.sin(uu*Math.PI*2)*20+(uu*(-22));ax=106;ay=-8;ar=-8}
  else{const fill=o.fill||C.blue;base=`<rect x="-120" y="-90" width="240" height="180" rx="16" fill="#EFE6CF" ${st()}/><ellipse cx="0" cy="0" rx="58" ry="36" fill="${fill}" ${st()}/>`;
    path=`M0 -66 A98 66 0 1 1 -1 -66`;const a=-Math.PI/2+u*Math.PI*2;x=Math.cos(a)*98;y=Math.sin(a)*66;ax=0;ay=0;ar=0}
  const arrow=k==='around'?'':`<polygon points="0,-13 24,0 0,13" transform="translate(${ax},${ay}) rotate(${ar})" fill="${C.red}" ${st(C.navy,3)}/>`;
  return `<g>${base}<path d="${path}" fill="none" ${st('#fff',16)} opacity=".55"/><path d="${path}" fill="none" ${st(C.red,6)} stroke-dasharray="14 12" stroke-dashoffset="${f(-T*30)}"/>${arrow}<circle cx="${f(x)}" cy="${f(y)}" r="13" fill="${C.gold}" ${st(C.navy,4)}/></g>`};

/* ---------- island ---------- */
P.e23_island=(o,T)=>{const tr=(x,y,s)=>`<g transform="translate(${x},${y}) scale(${s}) rotate(${f(Math.sin(T*1.3+x)*2)})"><rect x="-8" y="-4" width="16" height="64" fill="${C.brown}" ${st(C.navy,5)}/><circle cx="0" cy="-30" r="40" fill="${C.leaf}" ${st(C.navy,6)}/><circle cx="-14" cy="-36" r="6" fill="#7DB77F"/></g>`;
  return `<g><clipPath id="e23ic"><rect x="-126" y="-100" width="252" height="200" rx="18"/></clipPath><g clip-path="url(#e23ic)"><rect x="-126" y="-100" width="252" height="200" fill="${C.sky}"/><g transform="translate(70,-62) scale(.34)">${P.sun({},T)}</g><rect x="-126" y="14" width="252" height="90" fill="${C.blue}"/>${_e23waves(-130,130,40,T,3,'#fff')}<path d="M-96 36 Q-84 -4 -40 -2 Q-10 -30 30 -4 Q84 -8 96 36 Q0 56 -96 36Z" fill="#EBD59C" ${st()}/><path d="M-72 26 Q-60 4 -34 6 Q-6 -16 28 6 Q66 4 76 26 Q0 40 -72 26Z" fill="#8EBE7E"/>${tr(-48,-4,.8)}${tr(2,-14,1)}${tr(52,-2,.8)}</g><rect x="-126" y="-100" width="252" height="200" rx="18" fill="none" ${st()}/></g>`};

/* ---------- photo frame with a picture ---------- */
const _e23pic=(k,T)=>{
  const sky=`<rect x="-70" y="-50" width="140" height="100" fill="${C.sky}"/>`;
  if(k==='river')return `${sky}<rect x="-70" y="14" width="140" height="36" fill="${C.blue}"/><rect x="-70" y="2" width="140" height="12" fill="${C.leaf}"/><path d="M-70 28 q17 -7 35 0 t35 0 t35 0 t35 0" fill="none" stroke="#fff" stroke-width="3"/><circle cx="40" cy="-28" r="12" fill="#F6CE4B"/>`;
  if(k==='tall')return `${sky}<rect x="-64" y="-8" width="30" height="58" fill="#94A9B5"/><rect x="-22" y="-44" width="40" height="94" fill="#7F96A3" stroke="${C.navy}" stroke-width="2"/><line x1="-2" y1="-44" x2="-2" y2="-56" stroke="${C.navy}" stroke-width="3"/><rect x="26" y="-18" width="34" height="68" fill="#94A9B5"/>${[0,1,2,3,4].map(i=>`<rect x="-14" y="${-36+i*16}" width="8" height="8" fill="#FFE08A"/><rect x="2" y="${-36+i*16}" width="8" height="8" fill="#FFE08A"/>`).join('')}`;
  if(k==='wall'){let m='',b='';for(let i=0;i<7;i++)m+=`<rect x="${-70+i*20}" y="-30" width="12" height="14" fill="#B58B6B" stroke="${C.navy}" stroke-width="2"/>`;for(let r=0;r<5;r++)b+=`<line x1="-70" y1="${-16+r*12}" x2="70" y2="${-16+r*12}" stroke="#8E6A4E" stroke-width="2"/>`;return `${sky}${m}<rect x="-70" y="-16" width="140" height="66" fill="#B58B6B"/>${b}`}
  if(k==='island')return `${sky}<rect x="-70" y="10" width="140" height="40" fill="${C.blue}"/><path d="M-44 16 Q-30 -6 0 -4 Q34 -6 48 16 Z" fill="#8EBE7E"/><circle cx="-4" cy="-12" r="11" fill="${C.leaf}"/><rect x="-6" y="-4" width="4" height="10" fill="${C.brown}"/><circle cx="44" cy="-30" r="10" fill="#F6CE4B"/>`;
  if(k==='food')return `<rect x="-70" y="-50" width="140" height="100" fill="#F6EEDC"/><ellipse cx="0" cy="8" rx="52" ry="34" fill="#fff" stroke="${C.navy}" stroke-width="3"/><ellipse cx="0" cy="4" rx="36" ry="22" fill="#E8A04A"/><circle cx="-12" cy="0" r="7" fill="#C0504D"/><circle cx="12" cy="8" r="7" fill="${C.leaf}"/>`;
  if(k==='street'){return `${sky}<polygon points="-70,50 -16,-6 16,-6 70,50" fill="#9FA9AF"/><rect x="-70" y="-30" width="44" height="80" fill="#C9B58A"/><rect x="26" y="-30" width="44" height="80" fill="#D9C9A2"/><rect x="-62" y="-16" width="12" height="14" fill="#FFE08A"/><rect x="48" y="-16" width="12" height="14" fill="#FFE08A"/>`}
  let b='';[-52,-26,0,26,50].forEach((x,i)=>{const h=[40,64,48,72,44][i];b+=`<rect x="${x-11}" y="${50-h}" width="22" height="${h}" fill="${i%2?'#7F96A3':'#94A9B5'}"/>`});return `${sky}${b}`};
P.e23_photo=(o,T,k)=>{const kk=o.k||'city',old=o.old,fl=ease(1-k/.4);
  const pic=_e23pic(kk,T);
  return `<g transform="rotate(${f(Math.sin(T*1.4)*1.8)}) scale(1.22)"><clipPath id="e23pc"><rect x="-70" y="-50" width="140" height="100"/></clipPath><rect x="-90" y="-76" width="180" height="152" rx="6" fill="${C.white}" ${st()}/><g clip-path="url(#e23pc)" transform="translate(0,-10)">${pic}${old?`<rect x="-70" y="-50" width="140" height="100" fill="#8B6A3E" opacity=".62"/>`:''}</g><rect x="-70" y="-60" width="140" height="100" fill="none" ${st(C.navy,3)}/>${k<.4?`<rect x="-90" y="-76" width="180" height="152" rx="6" fill="#fff" opacity="${f(fl*.85)}"/>`:''}</g>`};
P.e23_photos=(o,T)=>{const n=o.n;let s='';[[-62,-20,-12],[-22,6,6],[30,-12,-4],[64,12,10]].forEach(([x,y,r],i)=>{s+=`<g transform="translate(${x},${y}) rotate(${r}) scale(.6)"><rect x="-90" y="-76" width="180" height="152" rx="6" fill="${C.white}" ${st(C.navy,8)}/><g transform="translate(0,-10)" clip-path="url(#e23pc2)">${_e23pic(['city','river','tall','food'][i],T)}</g></g>`});
  return `<g><clipPath id="e23pc2"><rect x="-70" y="-50" width="140" height="100"/></clipPath>${s}${n?`<g transform="translate(0,88)"><rect x="-60" y="-34" width="120" height="58" rx="29" fill="${C.gold}" ${st()}/><text x="0" y="14" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="46" fill="${C.navy}">${n}</text></g>`:''}</g>`};

/* ---------- old city wall ---------- */
P.e23_wall=(o,T)=>{
  if(o.ring){let houses='',tw='';[[-26,-14],[16,-18],[-8,22],[30,16],[-38,26]].forEach(([x,y],i)=>{houses+=`<rect x="${x-9}" y="${y-8}" width="18" height="16" fill="${['#E7B8A0','#F4E5C2','#E7D3A6'][i%3]}" ${st(C.navy,2.5)}/>`});
    for(let i=0;i<8;i++){const a=i*Math.PI/4;tw+=`<rect x="${f(Math.cos(a)*92-9)}" y="${f(Math.sin(a)*70-9)}" width="18" height="18" rx="3" fill="#B58B6B" ${st(C.navy,3)}/>`}
    return `<g><rect x="-122" y="-96" width="244" height="192" rx="18" fill="#8EBE7E" ${st()}/><ellipse rx="92" ry="70" fill="#E9DDB8" stroke="#B58B6B" stroke-width="16"/><ellipse rx="92" ry="70" fill="none" ${st(C.navy,3)}/>${houses}${tw}</g>`}
  let m='',b='';for(let i=0;i<7;i++)m+=`<rect x="${-112+i*34}" y="-82" width="22" height="26" fill="#B58B6B" ${st(C.navy,4)}/>`;for(let r=0;r<6;r++){b+=`<line x1="-112" y1="${-52+r*22}" x2="112" y2="${-52+r*22}" ${st('#8E6A4E',3)}/>`;for(let c=0;c<6;c++){const bx=-92+c*40+(r%2)*20;if(bx>-108&&bx<108)b+=`<line x1="${bx}" y1="${-52+r*22}" x2="${bx}" y2="${-30+r*22}" ${st('#8E6A4E',3)}/>`}}
  return `<g><rect x="-112" y="-56" width="224" height="148" fill="#B58B6B" ${st()}/>${m}${b}<rect x="-30" y="22" width="60" height="70" rx="30" fill="${C.brown}" ${st()}/><line x1="-128" y1="-80" x2="-128" y2="90" ${st(C.red,5)}/><polygon points="-128,-98 -142,-76 -114,-76" fill="${C.red}" ${st(C.navy,3)}/><polygon points="-128,106 -142,84 -114,84" fill="${C.red}" ${st(C.navy,3)}/></g>`};

/* ---------- tall / high building with a measuring arrow ---------- */
P.e23_tall=(o,T)=>{let w='';for(let r=0;r<9;r++)for(let c=0;c<3;c++){const lit=((r*3+c)*5)%7!==0;w+=`<rect x="${-34+c*24}" y="${-86+r*20}" width="14" height="12" fill="${lit?'#FFE08A':'#8DA3B0'}" ${st(C.navy,2)}/>`}
  const m=((T*1.1)%1)*14;
  return `<g><line x1="0" y1="-132" x2="0" y2="-108" ${st(C.navy,5)}/><circle cx="0" cy="-134" r="5" fill="${C.red}"/><rect x="-44" y="-108" width="88" height="204" fill="#9FC3D6" ${st()}/>${w}<rect x="-14" y="64" width="28" height="32" fill="${C.brown}" ${st(C.navy,3)}/><line x1="76" y1="-96" x2="76" y2="94" ${st(C.red,5)}/><polygon points="76,-112 60,-88 92,-88" fill="${C.red}" ${st(C.navy,3)}/><polygon points="76,110 60,86 92,86" fill="${C.red}" ${st(C.navy,3)}/></g>`};

/* ---------- aeroplane / boat / road sign ---------- */
P.e23_plane=(o,T)=>{const dx=Math.sin(T*1.2)*16,dy=Math.sin(T*2)*5;let tr='';for(let i=0;i<4;i++){tr+=`<line x1="${-124-i*0}" y1="${14+i*0}" x2="${-124}" y2="14" opacity="0"/>`}
  let d='';for(let i=0;i<4;i++){const ph=(T*.8+i/4)%1;d+=`<line x1="${f(-60-ph*60)}" y1="${f(8+0)}" x2="${f(-84-ph*60)}" y2="8" ${st('#fff',6)} opacity="${f(1-ph)}"/>`}
  return `<g transform="translate(${f(dx)},${f(dy)}) rotate(-8)">${d}<path d="M-92 -8 L-110 -40 L-84 -40 L-52 -8Z" fill="${C.blue}" ${st()}/><path d="M-96 0 Q-96 -24 -56 -26 L56 -26 Q104 -22 116 4 Q104 24 60 24 L-60 24 Q-96 24 -96 0Z" fill="${C.white}" ${st()}/><path d="M-6 8 L-46 62 L-18 62 L38 8Z" fill="#DCE5EA" ${st()}/><path d="M-6 -22 L-40 -70 L-14 -70 L32 -22Z" fill="#DCE5EA" ${st()}/>${[0,1,2,3,4].map(i=>`<circle cx="${-48+i*24}" cy="-6" r="7" fill="${C.sky}" ${st(C.navy,3)}/>`).join('')}<path d="M84 -18 Q108 -14 114 4 L82 4Z" fill="${C.sky}" ${st(C.navy,3)}/></g>`};
P.e23_boat=(o,T)=>{const b=Math.sin(T*1.8)*5,r=Math.sin(T*1.8)*2.5;
  return `<g><rect x="-128" y="40" width="256" height="64" rx="14" fill="${C.blue}" ${st()}/><g transform="translate(0,${f(b)}) rotate(${f(r)})"><line x1="0" y1="-96" x2="0" y2="10" ${st(C.navy,6)}/><path d="M6 -96 L58 -80 L6 -64Z" fill="${C.red}" ${st(C.navy,3)}/><rect x="-44" y="-30" width="50" height="40" rx="5" fill="${C.cream}" ${st()}/><rect x="-34" y="-20" width="12" height="14" fill="${C.sky}" ${st(C.navy,2.5)}/><rect x="-16" y="-20" width="12" height="14" fill="${C.sky}" ${st(C.navy,2.5)}/><path d="M-108 10 L108 10 L80 56 L-80 56Z" fill="${C.moss}" ${st()}/><path d="M-100 24 H100" ${st(C.cream,4)}/></g>${_e23waves(-110,110,58,T,2,'#fff')}</g>`};
P.e23_milesign=(o,T)=>`<g><rect x="-8" y="30" width="16" height="84" fill="#9FB0BA" ${st()}/><rect x="-106" y="-112" width="212" height="148" rx="18" fill="${C.blue}" ${st()}/><rect x="-94" y="-100" width="188" height="124" rx="10" fill="none" stroke="${C.cream}" stroke-width="4"/><text x="0" y="-32" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${String(o.n).length>2?64:72}" fill="${C.cream}">${o.n}</text><text x="0" y="8" text-anchor="middle" font-family="Fraunces" font-weight="700" font-size="34" fill="${C.cream}">${o.n==1?'mile':'miles'}</text></g>`;

/* ---------- 100 years blocks (centuries) ---------- */
P.e23_years=(o,T,k)=>{const n=o.n||1;let s='';const w=Math.min(110,224/n);
  for(let i=0;i<n;i++){const p=ease((k-.15-i*.3)/.35),x=-112+i*w;s+=`<g opacity="${f(p)}" transform="translate(${f((1-p)*-20)},0)"><rect x="${f(x+3)}" y="-22" width="${f(w-6)}" height="70" rx="12" fill="${[C.gold,C.orange,'#E2B653'][i%3]}" ${st()}/><text x="${f(x+w/2)}" y="14" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${w>100?36:30}" fill="${C.navy}">100</text></g>`}
  const lab=n===1?'1 century = 100 years':n*100+' years';
  return `<g><rect x="-124" y="-96" width="248" height="190" rx="18" fill="${C.cream}" ${st()}/><text x="0" y="-60" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${n===1?22:34}" fill="${C.navy}">${n===1?lab:n+' centuries'}</text><g transform="translate(0,6)">${s}</g><text x="0" y="76" text-anchor="middle" font-family="Fraunces" font-weight="700" font-size="30" fill="${C.navy2}">${n===1?'':lab}</text></g>`};

/* ---------- tourist (faceless) ---------- */
P.e23_tourist=(o,T)=>{const bob=Math.sin(T*2)*2,cap=o.cap;
  const hat=cap?`<path d="M-36 -86 Q-36 -118 0 -118 Q36 -118 36 -86Z" fill="${C.red}" ${st()}/><path d="M-4 -86 H56 Q56 -78 44 -78 H-4Z" fill="${C.red}" ${st()}/>`:`<ellipse cx="0" cy="-84" rx="62" ry="12" fill="#EBD59C" ${st()}/><path d="M-34 -84 Q-34 -118 0 -118 Q34 -118 34 -84Z" fill="#EBD59C" ${st()}/><rect x="-34" y="-96" width="68" height="9" fill="${C.red}"/>`;
  return `<g transform="translate(-24,${f(bob)})">${P.person({c:o.c||C.orange,hair:cap?'short':'bun',hc:cap?'#222':'#2A1D18',ph:1},T)}${hat}<g transform="translate(0,44)"><rect x="-30" y="-18" width="60" height="38" rx="8" fill="${C.navy2}" ${st()}/><circle cx="0" cy="2" r="14" fill="#B9C6CE" ${st(C.navy,4)}/><circle cx="0" cy="2" r="6" fill="${C.navy}"/></g><g transform="translate(96,46)"><path d="M-14 -50 v-14 h28 v14" fill="none" ${st(C.navy,6)}/><rect x="-34" y="-50" width="68" height="100" rx="10" fill="${o.bagc||C.blue}" ${st()}/><line x1="-34" y1="0" x2="34" y2="0" ${st(C.navy,3)}/><rect x="-22" y="50" width="12" height="8" fill="${C.navy}"/><rect x="10" y="50" width="12" height="8" fill="${C.navy}"/></g></g>`};
P.e23_muscle=(o,T)=>{const p=1+.04*Math.sin(T*5),sk='#E3AE82';
  return `<g transform="scale(${f(p)})"><rect x="-124" y="14" width="40" height="92" rx="8" fill="${C.blue}" ${st()}/><path d="M-92 62 H0 L40 -46" fill="none" ${st(C.navy,64)}/><path d="M-92 62 H0 L40 -46" fill="none" stroke="${sk}" stroke-width="54" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="-40" cy="22" rx="52" ry="38" fill="${sk}" ${st()}/><path d="M-62 22 Q-40 4 -16 22" fill="none" ${st('#C48B63',4)}/><rect x="14" y="-104" width="64" height="58" rx="22" fill="${sk}" ${st()}/><path d="M32 -88 v22 M46 -90 v26 M60 -88 v22" ${st('#C48B63',3)} fill="none"/><path d="M96 -90 l16 -10 M100 -66 l20 0 M96 -42 l16 10" ${st(C.gold2,5)} fill="none"/></g>`};
P.e23_road=(o,T)=>`<g><clipPath id="e23rc"><rect x="-122" y="-100" width="244" height="200" rx="18"/></clipPath><g clip-path="url(#e23rc)"><rect x="-122" y="-100" width="244" height="200" fill="#8EBE7E"/><path d="M-50 120 C-50 40 70 60 60 -10 S -50 -60 10 -120" fill="none" stroke="#6F7C84" stroke-width="58"/><path d="M-50 120 C-50 40 70 60 60 -10 S -50 -60 10 -120" fill="none" stroke="#9FA9AF" stroke-width="46"/><path d="M-50 120 C-50 40 70 60 60 -10 S -50 -60 10 -120" fill="none" stroke="#fff" stroke-width="5" stroke-dasharray="16 14" stroke-dashoffset="${f(-T*26)}"/></g><rect x="-122" y="-100" width="244" height="200" rx="18" fill="none" ${st()}/></g>`;

/* ---------- welcome banner ---------- */
P.e23_welcome=(o,T)=>{let fl='';const cs=[C.red,C.gold,C.blue,C.moss,C.orange,'#8E6BB5'];for(let i=0;i<6;i++){const t=(i+.5)/6,x=-112+t*224,y=-86+Math.sin(t*Math.PI)*34+Math.sin(T*2.4+i)*2;fl+=`<polygon points="${f(x-15)},${f(y)} ${f(x+15)},${f(y)} ${f(x)},${f(y+34)}" fill="${cs[i]}" ${st(C.navy,3)}/>`}
  return `<g><path d="M-122 -92 Q0 -24 122 -92" fill="none" ${st(C.navy,4)}/>${fl}<rect x="-114" y="-12" width="228" height="86" rx="16" fill="${C.brown}" ${st()}/><rect x="-102" y="-2" width="204" height="66" rx="8" fill="#A9743F" ${st(C.navy,3)}/><text x="0" y="45" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="33" fill="${C.cream}" letter-spacing="1">WELCOME</text></g>`};

/* ---------- capital: skyline with a star over the tallest tower ---------- */
P.e23_capital=(o,T)=>{const p=1+.08*Math.sin(T*4);
  return `<g><g transform="translate(0,16)">${P.city({},T)}</g><g transform="translate(5,${f(-70+Math.sin(T*2.2)*3)}) scale(${f(p)})">${_e23star(0,0,34)}</g></g>`};
/* country outline with a star for the capital (star at north/east/south/centre) */
P.e23_country=(o,T)=>{const pos={north:[6,-62],east:[78,0],south:[-8,70],center:[0,0]}[o.star||'center'];
  return `<g><path d="M-70 -58 L-14 -90 L40 -80 L82 -48 L100 4 L70 40 L40 84 L-24 96 L-62 62 L-94 14 L-86 -26Z" fill="#E7D3A6" ${st()}/><path d="M-40 -20 L10 -34 M-30 24 L40 12 M-60 -4 L-36 56" fill="none" ${st('#C9B58A',3)}/>${_e23star(pos[0],pos[1]+0,24)}<g transform="translate(-100,-86)"><circle r="20" fill="${C.cream}" ${st(C.navy,3)}/><path d="M0 -14 L8 8 L0 3 L-8 8Z" fill="${C.red}" ${st(C.navy,2)}/></g></g>`};

/* ---------- culture: food / clothes / art / people / all ---------- */
const _e23cul={
 food:(T)=>{let s='';for(let i=0;i<3;i++){const ph=(T*.8+i/3)%1;s+=`<path d="M${-24+i*24} ${f(-30-ph*34)} q-8 -10 0 -20 t0 -20" fill="none" ${st('#9AA7B0',5)} opacity="${f(1-ph)}"/>`}return `${s}<path d="M-84 -10 H84 Q84 70 0 78 Q-84 70 -84 -10Z" fill="${C.white}" ${st()}/><ellipse cx="0" cy="-10" rx="84" ry="14" fill="#E8A04A" ${st()}/><circle cx="-26" cy="-14" r="8" fill="#C0504D"/><circle cx="14" cy="-8" r="8" fill="${C.leaf}"/><circle cx="40" cy="-14" r="7" fill="#C0504D"/><rect x="-60" y="78" width="120" height="10" rx="5" fill="${C.cream}" ${st(C.navy,3)}/>`},
 clothes:(T)=>`<path d="M-30 -92 Q0 -70 30 -92 L90 -62 L70 -24 L48 -36 L52 96 H-52 L-48 -36 L-70 -24 L-90 -62Z" fill="${C.moss}" ${st()}/><path d="M-52 78 H52 M-51 62 H51" ${st(C.gold,6)} fill="none"/>${[-30,-10,10,30].map(x=>`<polygon points="${x},-40 ${x+8},-30 ${x},-20 ${x-8},-30" fill="${C.gold}" ${st(C.navy,2)}/>`).join('')}<path d="M-30 -92 Q0 -70 30 -92" fill="none" ${st(C.gold,6)}`+'/>',
 art:(T)=>`<rect x="-92" y="-84" width="184" height="152" rx="6" fill="${C.gold2}" ${st()}/><rect x="-76" y="-68" width="152" height="120" fill="${C.sky}" ${st(C.navy,3)}/><polygon points="-76,52 -30,-14 8,34 34,2 76,52" fill="#8FA3B0" ${st(C.navy,3)}/><circle cx="40" cy="-38" r="15" fill="#F6CE4B"/><rect x="-76" y="30" width="152" height="22" fill="${C.leaf}"/><circle cx="0" cy="-92" r="6" fill="${C.navy}"/>`,
 people:(T)=>P.crowd({n:5},T),
 people2:(T)=>`<g transform="translate(-34,10) scale(.8)">${P.person({c:C.red,hair:'short',hc:'#3A2A22',bag:C.moss},T)}</g><g transform="translate(40,-6) scale(.8)">${P.person({c:C.blue,hair:'long',hc:'#1E2B33',bag:C.orange,ph:2},T)}</g>`
};
P.e23_culture=(o,T)=>{const k=o.k||'all';
  if(k!=='all')return `<g>${_e23cul[k](T)}</g>`;
  const cells=[['food',-66,-62],['clothes',66,-62],['art',-66,68],['people2',66,68]];let s='';
  cells.forEach(([n,x,y])=>{s+=`<g transform="translate(${x},${y}) scale(.62)">${_e23cul[n](T)}</g>`});
  return `<g>${s}</g>`};

/* ---------- local shops (and a park) ---------- */
P.e23_shops=(o,T)=>{let s='';[[-76,C.red],[0,C.blue],[76,C.moss]].forEach(([x,c],i)=>{let aw='';for(let j=0;j<3;j++)aw+=`<path d="M${x-34+j*23} -14 h23 v16 q-11.5 12 -23 0Z" fill="${j%2?'#fff':c}" ${st(C.navy,3)}/>`;
    s+=`<rect x="${x-36}" y="-30" width="72" height="116" fill="${['#F4E5C2','#E7D3A6','#F4E5C2'][i]}" ${st()}/><rect x="${x-36}" y="-44" width="72" height="18" fill="${c}" ${st()}/>${aw}<rect x="${x-28}" y="22" width="34" height="30" fill="#FFE08A" ${st(C.navy,3)}/><rect x="${x+12}" y="28" width="18" height="58" fill="${C.brown}" ${st(C.navy,3)}/>`});
  return `<g>${s}<rect x="-122" y="86" width="244" height="12" fill="#9FA9AF" ${st(C.navy,3)}/></g>`};
P.e23_parkview=(o,T)=>{const tr=(x,y,s)=>`<g transform="translate(${x},${y}) scale(${s}) rotate(${f(Math.sin(T*1.2+x)*2)} 0 40)"><rect x="-8" y="-4" width="16" height="64" fill="${C.brown}" ${st(C.navy,5)}/><circle cx="0" cy="-32" r="42" fill="${C.leaf}" ${st(C.navy,6)}/><circle cx="-14" cy="-38" r="6" fill="#7DB77F"/></g>`;
  return `<g><clipPath id="e23pk"><rect x="-122" y="-100" width="244" height="200" rx="18"/></clipPath><g clip-path="url(#e23pk)"><rect x="-122" y="-100" width="244" height="200" fill="${C.sky}"/><rect x="-122" y="10" width="244" height="90" fill="#8EBE7E"/><path d="M-122 80 Q-30 30 20 10 Q50 0 60 -10" fill="none" ${st('#E7D3A6',26)}/>${tr(-78,0,1)}${tr(70,4,.9)}${tr(-20,-8,.7)}</g><rect x="-122" y="-100" width="244" height="200" rx="18" fill="none" ${st()}/></g>`};

/* ---------- three left turns: path drawn on a map ---------- */
P.e23_left=(o,T,k)=>{const n=o.n==null?3:o.n;const pts=[[50,60],[50,-60],[-50,-60],[-50,60],[50,60]];
  let d=`M${pts[0][0]} ${pts[0][1]}`;const segs=Math.min(4,n+1);
  let road='';for(let i=0;i<4;i++){road+=`<line x1="${pts[i][0]}" y1="${pts[i][1]}" x2="${pts[i+1][0]}" y2="${pts[i+1][1]}" ${st('#9FA9AF',26)}/>`}
  let rt='';for(let i=0;i<segs;i++){const a=pts[i],b=pts[i+1],pr=o.still?1:clamp((k-.2-i*.55)/.55);rt+=`<line x1="${a[0]}" y1="${a[1]}" x2="${f(a[0]+(b[0]-a[0])*pr)}" y2="${f(a[1]+(b[1]-a[1])*pr)}" ${st(C.red,7)}/>`}
  let bd='';for(let i=1;i<=Math.min(3,n);i++){const p=pts[i],pr=o.still?1:ease((k-.2-i*.55+.2)/.25);bd+=`<g transform="translate(${p[0]},${p[1]}) scale(${f(pr)})"><circle r="19" fill="${C.gold}" ${st()}/><text x="0" y="8" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="${C.navy}">${i}</text></g>`}
  return `<g><rect x="-122" y="-100" width="244" height="200" rx="18" fill="#EFE6CF" ${st()}/><rect x="-26" y="-34" width="52" height="68" rx="8" fill="#D9C9A2" ${st(C.navy,3)}/>${road}${rt}${bd}${_e23pin(50,76,.5,C.blue)}</g>`};

/* ---------- direction arrows: go left / go right ---------- */
P.e23_dir=(o,T)=>{const L=o.dir==='L',s=L?-1:1,m=Math.sin(T*4)*5;
  return `<g transform="translate(${f(s*m)},0)"><path d="M${s*100} 0 L${s*-10} -84 V-36 H${s*-100} V36 H${s*-10} V84 Z" fill="${L?C.red:C.moss}" ${st()}/></g>`};

/* ---------- sunrise in the east / sunset in the west ---------- */
P.e23_sunside=(o,T,k)=>{const e=o.side==='E';
  return `<g>${P.sunrise({set:e?0:1},T,k)}${_e23letter(e?96:-96,-96,30,e?'E':'W',C.white)}</g>`};

/* ---------- beach (east) and green mountains (west) ---------- */
P.e23_beach=(o,T)=>{
  return `<g><clipPath id="e23bc"><rect x="-122" y="-100" width="244" height="200" rx="18"/></clipPath><g clip-path="url(#e23bc)"><rect x="-122" y="-100" width="244" height="200" fill="${C.sky}"/><g transform="translate(46,-58) scale(.38)">${P.sun({},T)}</g><rect x="-122" y="-20" width="244" height="60" fill="${C.blue}"/>${_e23waves(-130,130,-2,T,2,'#fff')}<path d="M-122 100 V40 Q0 20 122 44 V100Z" fill="#EBD59C"/><g transform="translate(50,40)"><line x1="0" y1="-8" x2="0" y2="60" ${st(C.brown,6)}/><path d="M-50 -8 Q0 -64 50 -8Z" fill="${C.red}" ${st()}/></g></g><rect x="-122" y="-100" width="244" height="200" rx="18" fill="none" ${st()}/>${o.tag?_e23letter(-92,-72,26,o.tag,C.white):''}</g>`};
P.e23_greenmount=(o,T)=>{
  const tr=(x,y,s)=>`<g transform="translate(${x},${y}) scale(${s})"><rect x="-5" y="-2" width="10" height="30" fill="${C.brown}"/><polygon points="0,-48 -26,6 26,6" fill="#3F7F4F" ${st(C.navy,3)}/></g>`;
  return `<g><clipPath id="e23gc"><rect x="-122" y="-100" width="244" height="200" rx="18"/></clipPath><g clip-path="url(#e23gc)"><rect x="-122" y="-100" width="244" height="200" fill="${C.sky}"/><polygon points="-150,100 -50,-72 40,100" fill="#5E9B63" ${st()}/><polygon points="-10,100 70,-40 150,100" fill="#78B07A" ${st()}/><polygon points="-50,-72 -64,-48 -52,-54 -42,-44 -34,-54 -30,-48" fill="#fff" ${st(C.navy,2)}/>${tr(-70,60,.9)}${tr(-20,76,1)}${tr(86,66,.9)}${tr(40,84,.8)}</g><rect x="-122" y="-100" width="244" height="200" rx="18" fill="none" ${st()}/>${o.tag?_e23letter(92,-72,26,o.tag,C.white):''}</g>`};

P.e23_talltrees=(o,T)=>{let s='';[[-76,.9,120],[0,1.1,150],[76,.85,110]].forEach(([x,sc,h],i)=>{const sw=Math.sin(T*1.2+i)*2;s+=`<g transform="translate(${x},100) rotate(${f(sw)}) scale(${sc})"><rect x="-9" y="${-h}" width="18" height="${h}" fill="${C.brown}" ${st()}/><ellipse cx="0" cy="${-h-30}" rx="40" ry="58" fill="${C.leaf}" ${st()}/><ellipse cx="-12" cy="${-h-46}" rx="8" ry="12" fill="#7DB77F"/></g>`});return `<g><line x1="-120" y1="100" x2="120" y2="100" ${st(C.navy,5)}/>${s}</g>`};

/* ---------- map on a phone, paper map ---------- */
const _e23map=(w,h,T,pin)=>`<rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" fill="#EFE6CF"/><rect x="${-w/2}" y="${-h*.12}" width="${w}" height="${h*.16}" fill="${C.blue}" opacity=".85" transform="rotate(-8)"/><rect x="${-w*.38}" y="${-h*.42}" width="${w*.28}" height="${h*.2}" rx="6" fill="#9CCB8A"/><path d="M${-w/2} ${h*.28} H${w/2} M${-w*.1} ${-h/2} V${h/2} M${w*.28} ${-h/2} V${h/2}" fill="none" ${st('#fff',9)}/>${pin?_e23pin(w*.2,h*.12+Math.sin(T*4)*-3,Math.min(w,h)/150,C.red):''}`;
P.e23_citymap=(o,T)=>`<g transform="rotate(${f(Math.sin(T*1.3)*1.5)})"><rect x="-116" y="-96" width="232" height="192" rx="12" fill="#EFE6CF" ${st()}/><g clip-path="url(#e23mc)">${_e23map(220,180,T,true)}</g><clipPath id="e23mc"><rect x="-110" y="-90" width="220" height="180"/></clipPath><rect x="-110" y="-90" width="220" height="180" fill="none" ${st(C.navy,3)}/></g>`;
P.e23_phonemap=(o,T)=>`<g><clipPath id="e23mp"><rect x="-52" y="-94" width="104" height="188" rx="12"/></clipPath><rect x="-62" y="-112" width="124" height="224" rx="24" fill="${C.navy}" ${st()}/><g clip-path="url(#e23mp)">${_e23map(104,188,T,true)}</g><circle cx="0" cy="-103" r="3" fill="#41525c"/></g>`;

P.e23_phonefull=(o,T)=>{let g='';const ks=['city','river','tall','food','street','wall','island','city','river','tall','food','street'];ks.forEach((kk,i)=>{const c=i%3,r=Math.floor(i/3);g+=`<g transform="translate(${-33+c*33},${-72+r*46}) scale(.215)"><clipPath id="e23fp${i}"><rect x="-70" y="-50" width="140" height="100"/></clipPath><g clip-path="url(#e23fp${i})">${_e23pic(kk,T)}</g></g>`});
  return `<g><rect x="-62" y="-112" width="124" height="224" rx="24" fill="${C.navy}" ${st()}/><rect x="-52" y="-94" width="104" height="188" rx="12" fill="${C.cream}"/>${g}<circle cx="0" cy="-103" r="3" fill="#41525c"/></g>`};

/* ---------- gallery room with old photos ---------- */
P.e23_gallery=(o,T)=>{let s='';[[-76,-6],[0,-6],[76,-6]].forEach(([x,y],i)=>{s+=`<g transform="translate(${x},${y}) scale(.42)"><rect x="-90" y="-76" width="180" height="152" rx="6" fill="#7A5230" ${st()}/><g clip-path="url(#e23gp)" transform="translate(0,-4)">${_e23pic(['city','street','tall'][i],T)}<rect x="-70" y="-50" width="140" height="100" fill="#8B6A3E" opacity=".5"/></g></g>`});
  return `<g><clipPath id="e23gp"><rect x="-70" y="-50" width="140" height="100"/></clipPath><rect x="-122" y="-90" width="244" height="150" rx="10" fill="#E9DDB8" ${st()}/>${s}<rect x="-122" y="60" width="244" height="36" fill="#B58B6B" ${st()}/><rect x="-50" y="26" width="100" height="14" rx="4" fill="${C.brown}" ${st()}/></g>`};

/* ---------- hero for the intro ---------- */
P.e23_hero=(o,T)=>{const b=Math.abs(Math.sin(T*2.6))*16,u=(T*.3)%1,P0=[-128,30],P1=[-150,-120],P2=[-70,-118];
  const x=(1-u)*(1-u)*P0[0]+2*(1-u)*u*P1[0]+u*u*P2[0],y=(1-u)*(1-u)*P0[1]+2*(1-u)*u*P1[1]+u*u*P2[1],dx=2*(1-u)*(P1[0]-P0[0])+2*u*(P2[0]-P1[0]),dy=2*(1-u)*(P1[1]-P0[1])+2*u*(P2[1]-P1[1]),ang=Math.atan2(dy,dx)*180/Math.PI;
  return `<g><path d="M${P0[0]} ${P0[1]} Q${P1[0]} ${P1[1]} ${P2[0]} ${P2[1]}" fill="none" ${st(C.gold,5)} stroke-dasharray="4 14" opacity=".8"/><g transform="translate(0,52) scale(1.1)">${P.city({},T)}</g>${_e23pin(2,f(-24-b),1.5)}<g transform="translate(${f(x)},${f(y)}) rotate(${f(ang)}) scale(.34)">${P.e23_plane({},T)}</g></g>`};

/* Episode 24 props: helping at home (floor, chair, dirty, machine, light, above/behind/under, baby, shoes in a line...). Faceless. Uses C, st, f, ease, clamp, P. */
const _e24spark=(x,y,s,col)=>`<polygon points="0,-12 3,-3 12,0 3,3 0,12 -3,3 -12,0 -3,-3" transform="translate(${f(x)},${f(y)}) scale(${f(s)})" fill="${col||C.gold}"/>`;
const _e24shoe=(x,y,s,rot,c)=>`<g transform="translate(${x},${y}) rotate(${rot||0}) scale(${s})"><path d="M-30 14 L-30 -14 Q-30 -26 -18 -26 L-6 -26 Q2 -8 20 -4 Q34 -2 36 14 Z" fill="${c||C.red}" ${st(C.navy,4)}/><rect x="-32" y="12" width="70" height="10" rx="5" fill="${C.white}" ${st(C.navy,4)}/></g>`;
const _e24cup=(x,y,s)=>`<g transform="translate(${x},${y}) scale(${s})"><path d="M-22 -16 H22 L18 18 Q0 30 -18 18Z" fill="${C.white}" ${st(C.navy,4)}/><path d="M22 -8 a12 12 0 1 1 -3 18" fill="none" ${st(C.navy,4)}/><ellipse cx="0" cy="-16" rx="22" ry="5" fill="#B36B2C" ${st(C.navy,3)}/></g>`;

/* ---------- ceiling light (on / off) and wall switch ---------- */
P.e24_lamp=(o,T)=>{const on=o.on!==0;let r='';if(on)for(let i=0;i<9;i++){const a=-70+i*17.5;r+=`<line x1="0" y1="${60+0}" x2="0" y2="${f(96+Math.sin(T*5+i)*5)}" transform="rotate(${a} 0 0) translate(0,0)" ${st(C.gold2,6)} opacity=".9"/>`}
  return `<g transform="translate(0,-20)"><line x1="0" y1="-100" x2="0" y2="-30" ${st(C.navy,5)}/><g transform="translate(0,20)">${on?`<circle cx="0" cy="26" r="44" fill="#FFE27A" opacity=".5"/>`:''}${on?r.replace(/y1="60"/g,'y1="30"'):''}<path d="M-56 24 L-30 -26 H30 L56 24 Z" fill="${on?C.gold:'#8F9BA3'}" ${st()}/><circle cx="0" cy="26" r="18" fill="${on?'#FFF3B0':'#B8C2C8'}" ${st(C.navy,4)}/></g></g>`};
P.e24_switch=(o,T)=>{const on=o.on!==0;
  return `<g><rect x="-70" y="-100" width="140" height="200" rx="22" fill="${C.cream}" ${st()}/><rect x="-26" y="-56" width="52" height="112" rx="14" fill="${C.grey}" ${st()}/><rect x="-20" y="${on?-50:-6}" width="40" height="52" rx="10" fill="${on?C.moss:C.red}" ${st(C.navy,4)}/><circle cx="0" cy="${on?-24:20}" r="6" fill="${C.white}" opacity=".8"/></g>`};

/* ---------- baby (faceless) and children ---------- */
P.e24_baby=(o,T)=>{const b=Math.sin(T*2)*2,c=o.c||'#9ED0E8',sk='#EBBB92';
  return `<g transform="translate(0,${f(b)})"><ellipse cx="-34" cy="80" rx="30" ry="16" fill="${sk}" ${st()}/><ellipse cx="34" cy="80" rx="30" ry="16" fill="${sk}" ${st()}/><path d="M-50 70 Q-52 6 0 4 Q52 6 50 70 Q0 88 -50 70Z" fill="${c}" ${st()}/><circle cx="-48" cy="38" r="13" fill="${sk}" ${st()}/><circle cx="48" cy="38" r="13" fill="${sk}" ${st()}/><circle cx="0" cy="-34" r="44" fill="${sk}" ${st()}/><path d="M-6 -78 q10 -20 22 -6 q-10 4 -8 12" fill="none" ${st(C.brown,6)}/></g>`};
P.e24_kid=(o,T)=>`<g transform="translate(0,38) scale(${o.s||.76})">${P.person({c:o.c||C.blue,hair:o.hair||'short',hc:o.hc||'#3A2A22',ph:o.ph||0},T)}</g>`;

/* ---------- shop, floor, broom, bucket ---------- */
P.e24_shop=(o,T)=>{let aw='';for(let j=0;j<6;j++)aw+=`<path d="M${-100+j*33} -44 h33 v22 q-16.5 14 -33 0Z" fill="${j%2?'#fff':C.red}" ${st(C.navy,3)}/>`;
  return `<g><rect x="-100" y="-86" width="200" height="40" rx="6" fill="${C.navy2}" ${st()}/><rect x="-84" y="-74" width="168" height="16" rx="4" fill="${C.gold2}"/>${aw}<rect x="-96" y="-22" width="192" height="112" fill="#F4E5C2" ${st()}/><rect x="-84" y="-6" width="102" height="64" fill="#CFE8F2" ${st(C.navy,4)}/><rect x="32" y="-6" width="46" height="96" fill="${C.brown}" ${st(C.navy,4)}/><circle cx="44" cy="44" r="4" fill="${C.gold}"/></g>`};
P.e24_floor=(o,T,k)=>{let pl='',d='',sp='';
  for(let i=-5;i<=5;i++)pl+=`<line x1="${i*14}" y1="-40" x2="${i*30}" y2="100" ${st('#A9743F',3)}/>`;
  for(let j=0;j<5;j++){const y=-40+Math.pow((j+1)/5,1.6)*140;pl+=`<line x1="-130" y1="${f(y)}" x2="130" y2="${f(y)}" ${st('#A9743F',3)}/>`}
  if(o.dirty)[[-60,20,16],[-12,50,20],[44,6,12],[64,64,18],[-56,76,13],[10,-12,9]].forEach(([x,y,r])=>{d+=`<ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r*.45}" fill="#5B4636" opacity=".9"/>`});
  if(o.clean)[[-60,20],[0,56],[56,16],[-30,80],[40,76]].forEach(([x,y],i)=>{sp+=`<g transform="translate(${x},${y}) scale(${f(.7+.4*Math.sin(T*4+i))})"><polygon points="0,-14 4,-4 14,0 4,4 0,14 -4,4 -14,0 -4,-4" fill="#fff" ${st(C.goldD,2)}/></g>`});
  return `<g><clipPath id="e24fc"><polygon points="-124,100 -70,-40 70,-40 124,100"/></clipPath><rect x="-90" y="-100" width="180" height="62" fill="#F6EEDC" ${st()}/><rect x="-90" y="-52" width="180" height="14" fill="#E8DFC8" ${st(C.navy,3)}/><polygon points="-124,100 -70,-40 70,-40 124,100" fill="#D9A25B"/><g clip-path="url(#e24fc)">${pl}${d}${sp}</g><polygon points="-124,100 -70,-40 70,-40 124,100" fill="none" ${st()}/></g>`};
P.e24_broom=(o,T)=>{const sw=Math.sin(T*3)*14;
  return `<g transform="translate(${f(sw)},0) rotate(${f(-22+sw*.4)})"><rect x="-6" y="-120" width="12" height="150" rx="5" fill="${C.brown}" ${st()}/><path d="M-34 30 H34 L52 104 H-52Z" fill="${C.gold2}" ${st()}/><path d="M-22 40 L-30 100 M-8 40 L-10 100 M8 40 L10 100 M22 40 L30 100" ${st(C.goldD,3)} fill="none"/><rect x="-36" y="26" width="72" height="14" rx="5" fill="${C.red}" ${st()}/></g>`};
P.e24_bucket=(o,T)=>{let b='';for(let i=0;i<4;i++){const ph=(T*.7+i/4)%1;b+=`<circle cx="${f(-30+i*20+Math.sin(T*2+i)*6)}" cy="${f(-14-ph*50)}" r="${f(8+ph*6)}" fill="#fff" ${st('#9FC3D6',3)} opacity="${f(1-ph)}"/>`}
  return `<g><path d="M-50 -30 Q0 -120 50 -30" fill="none" ${st(C.navy,6)}/><path d="M-64 -30 H64 L50 90 Q0 104 -50 90Z" fill="${C.blue}" ${st()}/><ellipse cx="0" cy="-30" rx="64" ry="12" fill="#BFE3F2" ${st()}/>${b}</g>`};

/* ---------- chair, sitting, corner with window + light + tea ---------- */
P.e24_chair=(o,T)=>`<g><rect x="-52" y="-104" width="16" height="104" rx="6" fill="${C.brown}" ${st()}/><rect x="-52" y="-104" width="94" height="14" rx="6" fill="${C.brown}" ${st()}/><rect x="-36" y="-84" width="76" height="12" rx="4" fill="#A9743F" ${st(C.navy,3)}/><rect x="-36" y="-56" width="76" height="12" rx="4" fill="#A9743F" ${st(C.navy,3)}/><rect x="-56" y="-6" width="116" height="24" rx="8" fill="#A9743F" ${st()}/><rect x="-50" y="18" width="16" height="84" rx="5" fill="${C.brown}" ${st()}/><rect x="36" y="18" width="16" height="84" rx="5" fill="${C.brown}" ${st()}/></g>`;
P.e24_sit=(o,T)=>{const b=Math.sin(T*2)*1.5;
  return `<g><rect x="-62" y="-70" width="16" height="170" rx="6" fill="${C.brown}" ${st()}/><g transform="translate(6,${f(-6+b)}) scale(.78)">${P.person({c:o.c||C.blue,hair:'short',hc:'#222'},T)}</g><rect x="-66" y="38" width="130" height="22" rx="8" fill="#A9743F" ${st()}/><rect x="-58" y="60" width="16" height="44" rx="5" fill="${C.brown}" ${st()}/><rect x="38" y="60" width="16" height="44" rx="5" fill="${C.brown}" ${st()}/></g>`};
P.e24_corner=(o,T)=>{let st1='';for(let i=0;i<3;i++){const ph=(T*.8+i/3)%1;st1+=`<path d="M${f(-8+i*8)} ${f(-36-ph*30)} q-6 -9 0 -18 t0 -18" fill="none" ${st('#9AA7B0',3)} opacity="${f(1-ph)}"/>`}
  return `<g><rect x="-124" y="-100" width="248" height="200" rx="14" fill="#F6EBD2" ${st()}/><rect x="-108" y="-72" width="84" height="104" fill="${C.sky}" ${st(C.navy,5)}/><line x1="-66" y1="-72" x2="-66" y2="32" ${st(C.navy,4)}/><line x1="-108" y1="-20" x2="-24" y2="-20" ${st(C.navy,4)}/><line x1="30" y1="-100" x2="30" y2="-70" ${st(C.navy,4)}/><path d="M8 -42 L20 -70 H40 L52 -42Z" fill="${C.gold}" ${st(C.navy,4)}/><circle cx="30" cy="-40" r="9" fill="#FFF3B0" ${st(C.navy,3)}/><g transform="translate(12,36) scale(.44)">${P.e24_chair({},T)}</g><g transform="translate(88,48)"><rect x="-22" y="0" width="44" height="6" fill="${C.brown}" ${st(C.navy,3)}/><rect x="-4" y="6" width="8" height="26" fill="${C.brown}"/>${_e24cup(0,-18,.7)}${st1}</g><rect x="-124" y="84" width="248" height="16" fill="#B58B6B" ${st()}/></g>`};

/* ---------- books ---------- */
P.e24_books=(o,T)=>{let s='';const cs=[C.red,C.blue,C.moss,C.gold2,'#8E6BB5',C.orange];for(let i=0;i<5;i++)s+=`<rect x="${-80+(i%2)*10}" y="${54-i*30}" width="${160-(i%3)*14}" height="26" rx="4" fill="${cs[i]}" ${st()}/><rect x="${-60+(i%2)*10}" y="${60-i*30}" width="50" height="5" fill="${C.cream}" opacity=".8"/>`;
  return `<g>${s}${o.n?`<g transform="translate(60,-76)"><circle r="40" fill="${C.gold}" ${st()}/><text x="0" y="12" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${String(o.n).length>2?32:42}" fill="${C.navy}">${o.n}</text></g>`:''}</g>`};
P.e24_bookbag=(o,T)=>{let b='';[[-40,-110,C.red,-10],[0,-118,C.moss,4],[38,-108,C.gold2,12]].forEach(([x,y,c,r])=>{b+=`<rect x="${x-16}" y="${y}" width="32" height="56" rx="3" fill="${c}" ${st()} transform="rotate(${r} ${x} ${y+56})"/>`});
  return `<g>${b}<path d="M-34 -50 Q-34 -80 0 -80 Q34 -80 34 -50" fill="none" ${st(C.navy,8)}/><rect x="-88" y="-60" width="176" height="170" rx="46" fill="${C.blue}" ${st()}/><rect x="-62" y="10" width="124" height="70" rx="20" fill="${C.cold}" ${st()}/><circle cx="0" cy="40" r="8" fill="${C.gold}" ${st(C.navy,3)}/></g>`};

/* ---------- two people carrying a chair / a bag ---------- */
P.e24_carry=(o,T)=>{const b=Math.sin(T*3)*3,w=o.what||'chair';
  const obj=w==='bag'?`<g transform="translate(0,${f(30+b)}) scale(.5)">${P.e24_bookbag({},T)}</g>`:`<g transform="translate(0,${f(14+b)}) scale(.56)">${P.e24_chair({},T)}</g>`;
  return `<g><g transform="translate(-100,20) scale(.74)">${P.person({c:C.blue,hair:'short',hc:'#222',ph:0},T)}</g><g transform="translate(100,20) scale(.8)">${P.person({c:'#8E6BB5',hair:'short',hc:'#8A8F94',ph:1},T)}</g>${obj}</g>`};

/* ---------- under the bed ---------- */
const _e24item=(k,T)=>{
  if(k==='pen')return `<g transform="rotate(-20)"><rect x="-34" y="-5" width="60" height="10" rx="4" fill="${C.blue}" ${st(C.navy,3)}/><polygon points="26,-5 40,0 26,5" fill="${C.cream}" ${st(C.navy,3)}/><rect x="-34" y="-5" width="14" height="10" rx="3" fill="${C.red}"/></g>`;
  if(k==='tshirt')return `<path d="M-14 -34 Q0 -24 14 -34 L40 -22 L32 -2 L22 -8 L24 34 H-24 L-22 -8 L-32 -2 L-40 -22Z" fill="${C.orange}" ${st(C.navy,3.5)}/>`;
  if(k==='sandwich')return `<path d="M-36 8 L0 -26 L36 8Z" fill="#E1A25B" ${st(C.navy,3.5)}/><path d="M-30 6 L0 -20 L30 6Z" fill="#B7D27A"/><path d="M-36 8 H36 L30 22 H-30Z" fill="#E1A25B" ${st(C.navy,3.5)}/><circle cx="-8" cy="-2" r="5" fill="#6FA05A"/><circle cx="12" cy="4" r="4" fill="#6FA05A"/>`;
  if(k==='key')return `<circle cx="-22" cy="0" r="14" fill="none" ${st(C.goldD,8)}/><line x1="-8" y1="0" x2="34" y2="0" ${st(C.goldD,8)}/><line x1="26" y1="0" x2="26" y2="14" ${st(C.goldD,7)}/><line x1="14" y1="0" x2="14" y2="12" ${st(C.goldD,7)}/>`;
  if(k==='phone')return `<rect x="-14" y="-28" width="28" height="56" rx="6" fill="${C.navy}" ${st(C.navy,3)}/><rect x="-10" y="-22" width="20" height="40" rx="3" fill="${C.cream}"/>`;
  if(k==='shoe')return _e24shoe(0,0,.8,0,C.navy2);
  return '';};
P.e24_item=(o,T)=>`<g transform="scale(${o.s||2.4})">${_e24item(o.k,T)}</g>`;
P.e24_underbed=(o,T)=>{const k=o.item||'',sh=Math.sin(T*3)*2;
  return `<g><rect x="-124" y="-8" width="248" height="26" rx="10" fill="${C.cream}" ${st()}/><rect x="-124" y="-8" width="248" height="14" rx="8" fill="${C.blue}" ${st()}/><rect x="-118" y="-26" width="70" height="22" rx="10" fill="${C.white}" ${st()}/><rect x="-124" y="-44" width="14" height="140" rx="5" fill="${C.brown}" ${st()}/><rect x="110" y="18" width="14" height="78" rx="5" fill="${C.brown}" ${st()}/><rect x="-108" y="20" width="216" height="76" fill="#262A44" opacity=".92"/><line x1="-124" y1="96" x2="124" y2="96" ${st(C.navy,5)}/><g transform="translate(0,${f(60+sh)}) scale(1.6)">${k?_e24item(k,T):`<circle r="0"/>`}</g>${k?'':`<g transform="translate(0,64)"><circle r="26" fill="${C.gold}" ${st()}/><text x="0" y="14" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="40" fill="${C.navy}">?</text></g>`}</g>`};

/* ---------- washing machine: front and behind (side view with wall) ---------- */
P.e24_machine=(o,T)=>{const a=T*200;let lg='';[[-22,-6,C.red],[20,10,C.gold2],[0,-22,C.blue],[-8,22,'#8E6BB5']].forEach(([x,y,c],i)=>{const r=a*.0174+i*1.6;lg+=`<circle cx="${f(x+Math.cos(r)*8)}" cy="${f(y+Math.sin(r)*8)}" r="14" fill="${c}" opacity=".9"/>`});
  return `<g><rect x="-90" y="-110" width="180" height="214" rx="18" fill="${C.white}" ${st()}/><line x1="-90" y1="-70" x2="90" y2="-70" ${st(C.navy,4)}/><circle cx="-56" cy="-90" r="8" fill="${C.blue}" ${st(C.navy,3)}/><circle cx="-30" cy="-90" r="8" fill="${C.gold}" ${st(C.navy,3)}/><rect x="20" y="-98" width="52" height="16" rx="5" fill="${C.navy}"/><circle cx="0" cy="16" r="60" fill="#B9C6CE" ${st(C.navy,6)}/><clipPath id="e24mc"><circle cx="0" cy="16" r="50"/></clipPath><g clip-path="url(#e24mc)"><circle cx="0" cy="16" r="50" fill="#7FB6D6"/><g transform="translate(0,16)">${lg}</g></g></g>`};
P.e24_machinegap=(o,T)=>{const k=o.item||'';let dust='';[[0,-30],[18,10],[6,50],[22,86],[8,-70]].forEach(([x,y],i)=>{dust+=`<circle cx="${x+10}" cy="${y}" r="${7+i%2*3}" fill="#8A8F94" opacity=".85"/>`});
  return `<g><rect x="50" y="-110" width="64" height="214" fill="#C9A98B" ${st()}/>${[-70,-30,10,50,90].map(y=>`<line x1="50" y1="${y}" x2="114" y2="${y}" ${st('#A3846A',3)}/>`).join('')}<rect x="-114" y="-96" width="90" height="200" rx="12" fill="${C.white}" ${st()}/><circle cx="-70" cy="16" r="32" fill="#B9C6CE" ${st(C.navy,5)}/><rect x="-24" y="-110" width="74" height="214" fill="#2B3140"/>${dust}<g transform="translate(26,34) scale(.8) rotate(90)">${k==='shoe'?_e24shoe(0,0,.8,0,C.orange):k?_e24item(k,T):''}</g><line x1="-124" y1="104" x2="124" y2="104" ${st(C.navy,5)}/></g>`};

/* ---------- baby on the floor with things under chairs; baby on chair at door ---------- */
P.e24_babyfloor=(o,T)=>{const ch=(x)=>`<g transform="translate(${x},28) scale(.52)">${P.e24_chair({},T)}</g>`;
  return `<g><rect x="-124" y="62" width="248" height="38" fill="#D9A25B" ${st()}/><line x1="-124" y1="82" x2="124" y2="82" ${st('#A9743F',3)}/>${ch(-86)}${ch(86)}<g transform="translate(-86,72) scale(.6)">${_e24item('pen',T)}</g><g transform="translate(86,72) scale(.6)">${_e24item('key',T)}</g><g transform="translate(0,26) scale(.62)">${P.e24_baby({},T)}</g><g transform="translate(42,76) scale(.55) rotate(70)">${_e24item('phone',T)}</g></g>`};
P.e24_babychair=(o,T)=>{
  return `<g><rect x="-124" y="-104" width="100" height="204" rx="8" fill="${C.brown}" ${st()}/><rect x="-110" y="-90" width="72" height="80" rx="6" fill="#A9743F" ${st(C.navy,3)}/><circle cx="-42" cy="20" r="7" fill="${C.gold}" ${st(C.navy,3)}/><g transform="translate(36,36) scale(.8)">${P.e24_chair({},T)}</g><g transform="translate(36,-30) scale(.62)">${P.e24_baby({c:'#F2B6B6'},T)}</g><g transform="translate(-74,-122) scale(.5) rotate(-20)">${_e24item('pen',T)}</g></g>`};

/* ---------- wall with crayon lines ---------- */
P.e24_walldraw=(o,T,k)=>{const p1=clamp((k-.2)/.7),p2=clamp((k-.6)/.7);
  return `<g><rect x="-124" y="-100" width="248" height="200" rx="10" fill="#F6EEDC" ${st()}/><rect x="-124" y="72" width="248" height="28" fill="#B58B6B" ${st()}/><path d="M-90 -20 Q-40 -60 10 -30 T96 -50" fill="none" ${st(C.red,9)} stroke-dasharray="260" stroke-dashoffset="${f(260*(1-p1))}"/><path d="M-96 30 Q-30 0 20 40 T90 10" fill="none" ${st(C.blue,9)} stroke-dasharray="260" stroke-dashoffset="${f(260*(1-p2))}"/></g>`};

/* ---------- door with something above (phone/pen) ---------- */
P.e24_doortop=(o,T)=>{const b=Math.sin(T*3)*3;
  return `<g><rect x="-124" y="-104" width="248" height="14" fill="#E8DFC8" ${st()}/><g transform="translate(0,${f(-64+b)}) scale(.7)">${_e24item(o.item||'phone',T)}</g><rect x="-48" y="-34" width="96" height="138" rx="6" fill="${C.brown}" ${st()}/><rect x="-34" y="-20" width="68" height="56" rx="5" fill="#A9743F" ${st(C.navy,3)}/><circle cx="30" cy="40" r="7" fill="${C.gold}" ${st(C.navy,3)}/><g transform="translate(90,-30)"><path d="M0 40 V-30" ${st(C.moss,9)} fill="none"/><polygon points="0,-48 -18,-22 18,-22" fill="${C.moss}" ${st(C.navy,3)}/></g></g>`};

/* ---------- relations: above / under / behind / close ---------- */
P.e24_prep=(o,T)=>{const k=o.k,it=_e24item(o.item||'phone',T),b=Math.sin(T*3)*3;
  const table=`<rect x="-80" y="20" width="160" height="22" rx="6" fill="#A9743F" ${st()}/><rect x="-70" y="42" width="14" height="56" fill="${C.brown}" ${st()}/><rect x="56" y="42" width="14" height="56" fill="${C.brown}" ${st()}/>`;
  const floor=`<line x1="-124" y1="98" x2="124" y2="98" ${st(C.navy,5)}/>`;
  if(k==='above')return `<g>${floor}${table}<g transform="translate(0,${f(-50+b)}) scale(1.3)">${it}</g><path d="M96 10 V-70" ${st(C.moss,9)} fill="none"/><polygon points="96,-90 78,-62 114,-62" fill="${C.moss}" ${st(C.navy,3)}/></g>`;
  if(k==='under')return `<g>${floor}${table}<g transform="translate(0,${f(68)}) scale(1.1)">${it}</g></g>`;
  if(k==='behind')return `<g>${floor}<g transform="translate(26,56) scale(1.3)">${it}</g><rect x="-70" y="-20" width="100" height="118" rx="10" fill="${C.cold}" ${st()}/></g>`;
  return `<g>${floor}<rect x="48" y="-90" width="40" height="188" fill="#C9A98B" ${st()}/><g transform="translate(14,60) scale(1.3)">${it}</g><path d="M-30 80 H-10 M44 80 H34" ${st(C.red,5)} fill="none"/></g>`};

/* ---------- shoes: neat line / scattered ---------- */
P.e24_shoeline=(o,T)=>{let s='';const cs=[C.red,C.blue,C.moss,C.orange,'#8E6BB5'],bad=o.bad;
  if(!bad){for(let i=0;i<4;i++)s+=_e24shoe(-96+i*64,34,.86,0,cs[i]);return `<g><rect x="-124" y="-104" width="100" height="150" rx="6" fill="${C.brown}" ${st()}/><rect x="-124" y="-104" width="248" height="24" rx="4" fill="${C.brown}" opacity="0"/><line x1="-124" y1="64" x2="124" y2="64" ${st(C.moss,5)} stroke-dasharray="14 8"/>${s}</g>`}
  [[-86,20,-30],[-20,64,12],[50,10,50],[84,60,-20]].forEach(([x,y,r],i)=>{s+=_e24shoe(x,y,.86,r,cs[i])});return `<g>${s}</g>`};
P.e24_shoeone=(o,T)=>`<g transform="scale(1.6)">${_e24shoe(0,0,1.2,0,o.c||C.red)}</g>`;

/* ---------- flat above: two floors in section ---------- */
P.e24_stack=(o,T)=>{const top=o.top;let who='';
  if(top==='baby')who=`<g transform="translate(0,-58) scale(.5)">${P.e24_baby({},T)}</g>`;else if(top==='oldman')who=`<g transform="translate(0,-60) scale(.45)">${P.person({c:'#6A8FA8',hair:'short',hc:'#CFD3D6'},T)}</g>`;
  let snd='';if(o.sound)for(let i=0;i<3;i++){const ph=(T*1.2+i/3)%1;snd+=`<path d="M${f(54+ph*20)} ${f(-64)} q10 8 0 16 M${f(70+ph*20)} -72 q14 16 0 32" fill="none" ${st(C.red,4)} opacity="${f(1-ph)}"/>`}
  return `<g><rect x="-116" y="-108" width="232" height="92" rx="6" fill="#FBF3DC" ${st()}/><rect x="-116" y="-16" width="232" height="14" fill="#B58B6B" ${st()}/><rect x="-116" y="-2" width="232" height="104" rx="6" fill="#F6EBD2" ${st()}/><rect x="-116" y="96" width="232" height="14" fill="#B58B6B" ${st()}/>${who}${snd}<g transform="translate(0,48) scale(.44)">${P.person({c:C.blue,hair:'short',hc:'#222'},T)}</g></g>`};

/* ---------- cooking pot, rules ---------- */
P.e24_pot=(o,T)=>{let s='';for(let i=0;i<3;i++){const ph=(T*.8+i/3)%1;s+=`<path d="M${-30+i*30} ${f(-34-ph*44)} q-9 -12 0 -24 t0 -24" fill="none" ${st('#9AA7B0',5)} opacity="${f(1-ph)}"/>`}
  return `<g>${s}<path d="M-84 -14 H84 L74 70 Q0 90 -74 70Z" fill="#B9C6CE" ${st()}/><rect x="-92" y="-26" width="184" height="16" rx="8" fill="#9FB0BA" ${st()}/><path d="M84 6 h28 M-84 6 h-28" ${st(C.navy,8)}/></g>`};
P.e24_bags=(o,T)=>`<g><g transform="translate(-44,10) scale(.7)">${P.bag({c:C.moss},T)}</g><g transform="translate(46,0) scale(.8)">${P.bag({c:C.orange},T)}</g></g>`;

/* ---------- hero: broom, bucket, sparkles ---------- */
P.e24_hero=(o,T)=>{let sp='';[[-30,30,0],[40,60,1],[84,10,2],[-80,70,3],[10,-30,4]].forEach(([x,y,p])=>{sp+=_e24spark(x,y,.8+.5*Math.sin(T*3+p),p%2?C.white:C.gold)});
  return `<g><g transform="translate(10,0)"><polygon points="-120,106 -100,50 120,50 130,106" fill="#D9A25B" ${st()}/>${sp}</g><g transform="translate(-30,-6) scale(1.1)">${P.e24_broom({},T)}</g><g transform="translate(86,22) scale(.62)">${P.e24_bucket({},T)}</g></g>`};
P.e24_wall=(o,T)=>{let b='';for(let r=0;r<4;r++)b+=`<line x1="-124" y1="${-60+r*40}" x2="124" y2="${-60+r*40}" ${st('#E3DCCB',2)}/>`;
  return `<g><rect x="-124" y="-104" width="248" height="208" rx="10" fill="${o.col||'#FFFFFF'}" ${st()}/>${b}<rect x="-124" y="72" width="248" height="32" fill="#E8DFC8" ${st()}/><rect x="-40" y="-60" width="80" height="60" rx="4" fill="${C.gold2}" ${st()}/><rect x="-30" y="-50" width="60" height="40" fill="${C.sky}" ${st(C.navy,2)}/><polygon points="-30,-10 -8,-36 6,-22 16,-30 30,-10" fill="#8FA3B0"/></g>`};

/* Episode 25 props: the past, childhood, farm animals, old telephone, CD/DVD, post. Faceless. Uses C, st, f, ease, clamp, P. */
const _e25kid=(o,T)=>{const teen=o.teen,sc=teen?.92:.74,y=teen?0:26;return `<g transform="translate(0,${y}) scale(${sc})">${P.person({c:o.c||C.orange,hair:o.hair||'bun',hc:o.hc||'#6A3F26',ph:o.ph||0},T)}</g>`};
P.e25_kid=(o,T)=>`<g>${_e25kid(o,T)}</g>`;
P.e25_ages=(o,T)=>`<g><g transform="translate(-92,10) scale(.8)">${_e25kid({c:C.orange,hair:'bun'},T)}</g><g transform="translate(0,-10) scale(.9)">${_e25kid({teen:1,c:C.blue,hair:'short',hc:'#222'},T)}</g><g transform="translate(96,-30) scale(.95)">${P.person({c:C.moss,hair:'long',hc:'#2A1D18'},T)}</g></g>`;
const _e25wool=(x,y,r,ph)=>{let s='';for(let i=0;i<8;i++){const a=i*Math.PI/4;s+=`<circle cx="${f(x+Math.cos(a)*r*.62)}" cy="${f(y+Math.sin(a)*r*.62)}" r="${f(r*.5)}" fill="#FFFDF4" ${st(C.navy,4)}/>`}return s+`<circle cx="${x}" cy="${y}" r="${f(r*.7)}" fill="#FFFDF4"/>`};
P.e25_sheep=(o,T)=>{const hop=o.run?-Math.abs(Math.sin(T*7))*10:0;return `<g transform="translate(0,${f(hop)})"><rect x="-52" y="40" width="14" height="52" rx="6" fill="#3A3F44" ${st()}/><rect x="-18" y="44" width="14" height="48" rx="6" fill="#3A3F44" ${st()}/><rect x="20" y="44" width="14" height="48" rx="6" fill="#3A3F44" ${st()}/><rect x="50" y="40" width="14" height="52" rx="6" fill="#3A3F44" ${st()}/>${_e25wool(-20,12,64)}${_e25wool(24,8,58)}${_e25wool(-2,-14,48)}<ellipse cx="86" cy="-8" rx="24" ry="30" fill="#3A3F44" ${st()}/></g>`};
P.e25_pig=(o,T)=>{const sc=o.little?.6:1,hop=o.run?-Math.abs(Math.sin(T*8))*10:0,pk='#F2A7B5';return `<g transform="translate(0,${f(hop+(o.little?40:0))}) scale(${sc})"><path d="M-92 -4 q-26 -8 -14 -30 q14 6 8 20" fill="none" ${st('#E58AA0',7)}/><rect x="-62" y="40" width="20" height="50" rx="8" fill="${pk}" ${st()}/><rect x="-22" y="44" width="20" height="46" rx="8" fill="${pk}" ${st()}/><rect x="22" y="44" width="20" height="46" rx="8" fill="${pk}" ${st()}/><rect x="56" y="40" width="20" height="50" rx="8" fill="${pk}" ${st()}/><ellipse cx="-4" cy="14" rx="92" ry="54" fill="${pk}" ${st()}/><polygon points="52,-44 70,-76 86,-40" fill="#E58AA0" ${st()}/><circle cx="82" cy="-2" r="40" fill="${pk}" ${st()}/><ellipse cx="112" cy="8" rx="20" ry="16" fill="#E58AA0" ${st()}/></g>`};
P.e25_wallphone=(o,T)=>{let w='';if(o.ring)for(let i=0;i<3;i++){const ph=(T*2+i/3)%1;w+=`<path d="M${f(-84-ph*24)} -50 q-14 24 0 48 M${f(84+ph*24)} -50 q14 24 0 48" fill="none" ${st(C.red,6)} opacity="${f(1-ph)}"/>`}const sh=o.ring?Math.sin(T*40)*2:0;let k='';for(let r=0;r<3;r++)for(let c=0;c<3;c++)k+=`<circle cx="${-18+c*18}" cy="${14+r*18}" r="5" fill="${C.cream}"/>`;
return `<g transform="rotate(${f(sh)})">${w}<rect x="-62" y="-104" width="124" height="190" rx="22" fill="#B9C6CE" ${st()}/><rect x="-40" y="-84" width="80" height="22" rx="8" fill="${C.navy}" ${st(C.navy,3)}/>${k}<path d="M-62 -40 q-40 40 -20 100 q18 40 20 10" fill="none" ${st(C.navy,5)}/><g transform="translate(-86,-38)"><rect x="-10" y="-30" width="20" height="130" rx="10" fill="${C.navy}" ${st()}/></g></g>`};
