P.e28_books=(o,T)=>{let s='';const cs=[C.red,C.blue,C.moss],w=[170,150,160];for(let i=0;i<3;i++)s+=`<rect x="${-w[i]/2+(i-1)*8}" y="${40-i*50}" width="${w[i]}" height="46" rx="6" fill="${cs[i]}" ${st()}/><rect x="${-w[i]/2+(i-1)*8+16}" y="${50-i*50}" width="64" height="8" rx="4" fill="#fff" opacity=".6"/><rect x="${-w[i]/2+(i-1)*8+w[i]-18}" y="${40-i*50}" width="8" height="46" fill="${C.cream}" opacity=".7"/>`;return `<g>${s}</g>`};
P.e28_slow=(o,T)=>`<g transform="rotate(${f(Math.sin(T*2)*1.5)})"><rect x="-8" y="0" width="16" height="110" fill="#9FB0BA" ${st()}/><rect x="-100" y="-104" width="200" height="110" rx="18" fill="#F6CE4B" ${st()}/><rect x="-88" y="-92" width="176" height="86" rx="10" fill="none" stroke="${C.navy}" stroke-width="5"/><text x="0" y="-33" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="50" fill="${C.navy}" letter-spacing="1">SLOW</text></g>`;
P.e28_fast=(o,T)=>{let ml='';for(let i=0;i<4;i++){const ph=(T*2.4+i/4)%1;ml+=`<path d="M${f(-70-ph*40)} ${-50+i*26} h${f(-60)}" ${st('#9AA7B0',6)} opacity="${f(1-ph)}"/>`}
  return `<g><g transform="translate(${f(34+Math.sin(T*12)*2)},4) scale(.74)">${P.car({},T)}</g>${ml}</g>`};
P.e28_carsound=(o,T)=>{let w='';for(let i=0;i<3;i++){const a=(T*1.3+i/3)%1;w+=`<path d="M${f(86+a*14)} ${f(-50-a*14)} q${f(20+a*14)} ${f(30+a*14)} 0 ${f(60+a*28)}" fill="none" ${st(C.goldD,7)} opacity="${f(1-a)}"/>`}
  return `<g><g transform="translate(-26,16) scale(.7)">${P.car({},T)}</g>${w}</g>`};
P.e28_sound=(o,T)=>{let w='',z='';for(let i=0;i<3;i++){const a=(T*1.3+i/3)%1;w+=`<circle r="${f(30+a*78)}" fill="none" ${st(C.red,7)} opacity="${f(1-a)}"/>`}
  const pts=[];for(let i=0;i<16;i++){const r=i%2?34:62;pts.push(`${f(Math.cos(i*Math.PI/8)*r)},${f(Math.sin(i*Math.PI/8)*r)}`)}
  return `<g>${w}<polygon points="${pts.join(' ')}" fill="${C.gold}" ${st(C.goldD,5)} transform="scale(${f(1+.08*Math.sin(T*12))})"/></g>`};
P.e28_wall=(o,T)=>{let tl='';for(let r=0;r<5;r++)for(let c=0;c<7;c++)tl+=`<rect x="${-110+c*32}" y="${-100+r*28}" width="32" height="28" fill="#fff" ${st('#DCE5EA',2)}/>`;
  return `<g><rect x="-110" y="-100" width="224" height="200" rx="8" fill="#F4E5C2" ${st()}/>${tl}<g transform="translate(0,-4) scale(.62) rotate(-5)">${P.e28_paper({rot:0},T)}<circle cx="0" cy="-104" r="10" fill="${C.red}" ${st(C.navy,3)}/></g><rect x="-110" y="84" width="224" height="16" fill="#B58A5A" ${st()}/></g>`};
P.e28_run=(o,T)=>{const b=Math.abs(Math.sin(T*9))*10;let ml='';for(let i=0;i<3;i++){const ph=(T*2.6+i/3)%1;ml+=`<path d="M${f(-70-ph*30)} ${-20+i*34} h${f(-50)}" ${st('#9AA7B0',6)} opacity="${f(1-ph)}"/>`}
  return `<g>${ml}<g transform="translate(14,${f(14-b)}) rotate(12)">${P.person({c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g></g>`};
P.e28_busy=(o,T)=>{const items=['clk','bag','brief'];let s='';items.forEach((nm,i)=>{const a=T*1.6+i*2.094;s+=`<g transform="translate(${f(Math.cos(a)*92)},${f(-10+Math.sin(a)*76)}) scale(.3)">${P[nm]({h:3,m:0},T,9)}</g>`});
  return `<g><g transform="translate(0,16) scale(.9)">${P.person({c:'#D96C8B',hair:'long',hc:'#3A2A22'},T)}</g>${s}</g>`};
P.e28_streets=(o,T)=>`<g><path d="M-120 -90 L0 20 L120 -90" fill="none" ${st('#7F8E96',44)}/><path d="M0 20 V110" fill="none" ${st('#7F8E96',44)}/><path d="M-120 -90 L0 20 L120 -90 M0 20 V110" fill="none" ${st('#fff',4)} stroke-dasharray="14 12"/><circle cx="0" cy="20" r="26" fill="${C.gold}" ${st()}/></g>`;
P.e28_hero=(o,T)=>{const w=Math.sin(T*5)*16,q=Math.sin(T*2.4)*3;
  const lit=(Math.sin(T*1.6)>-.2);
  return `<g><g transform="translate(-72,18) scale(.74)">${_e28house('#CFE3F2','#4DA3D8',T,{lit:lit})}</g><g transform="translate(76,18) scale(.74)">${_e28house('#F8DDB0',C.red,T)}</g><path d="M-14 90 H14" ${st(C.navy,3)} fill="none"/><g transform="translate(0,46) scale(.62)">${P.person({c:'#4F7A5A',hair:'bun',hc:'#2A1D18'},T)}<g transform="translate(46,6) rotate(${f(-40+w)})"><rect x="-8" y="-52" width="16" height="56" rx="8" fill="#E3AE82" ${st()}/></g></g><g transform="translate(0,${f(-112+q)}) scale(.46)">${P.q({},T)}</g><rect x="-124" y="92" width="248" height="10" rx="5" fill="#9FB0BA" ${st(C.navy,3)}/></g>`};

/* Episode 29 props: fears, animals (snake, lion, elephant), body parts, airport, passport, space, negative/positive. Faceless. Uses C, st, f, ease, clamp, P. */
const _e29T=(x,y,s,inner)=>`<g transform="translate(${f(x)},${f(y)}) scale(${f(s)})">${inner}</g>`;
/* tapering chain of circles = snake body */
const _e29chain=(pts,rf,fill,line,ow)=>{let a='',b='';pts.forEach((p,i)=>{const r=rf(i/(pts.length-1));a+=`<circle cx="${f(p[0])}" cy="${f(p[1])}" r="${f(r+ow)}" fill="${line}"/>`;b+=`<circle cx="${f(p[0])}" cy="${f(p[1])}" r="${f(r)}" fill="${fill}"/>`});return a+b};
const _e29snakeBody=(o,T,big)=>{const n=44,pts=[];
  if(o.coil){const m=80;for(let i=0;i<m;i++){const u=i/(m-1),a=u*Math.PI*2*2.1+Math.PI*.2,r=92-u*30;pts.push([Math.cos(a)*r,78-u*34+Math.sin(a)*r*.3])}
    const e=pts[m-1],sw=Math.sin(T*2)*6;for(let i=1;i<=12;i++){const u=i/12;pts.push([e[0]+(-6-e[0])*u*.9+Math.sin(u*Math.PI)*-26+sw*u,e[1]-u*u*10-u*118+sw*0])}
    const L=pts.length;pts.push([pts[L-1][0]+14,pts[L-1][1]-6])}
  else{for(let i=0;i<n;i++){const u=i/(n-1);pts.push([-112+u*210,Math.sin(u*Math.PI*3.2-T*3.2)*(18+u*14)])}}
  const rf=o.coil?(u=>13.5-u*3):(u=>5+Math.sin(Math.min(1,u*1.15)*Math.PI*.5)*11);
  const NN=pts.length,hp=pts[NN-1],pp=pts[NN-3],ang=Math.atan2(hp[1]-pp[1],hp[0]-pp[0])*180/Math.PI;
  let dots='';for(let i=3;i<NN-4;i+=o.coil?5:3){const p=pts[i];dots+=`<circle cx="${f(p[0])}" cy="${f(p[1])}" r="${f(rf(i/(NN-1))*.42)}" fill="#C9E7A0"/>`}
  return `<g>${_e29chain(pts,rf,'#5FA05A',C.navy,3.4)}${dots}<g transform="translate(${f(hp[0])},${f(hp[1])}) rotate(${f(ang)})"><ellipse cx="8" cy="0" rx="25" ry="16" fill="#5FA05A" ${st(C.navy,4.5)}/><ellipse cx="2" cy="0" rx="9" ry="7" fill="#C9E7A0" opacity=".9"/></g></g>`};
P.e29_snake=(o,T)=>{let sp='';if(o.fast){for(let i=0;i<3;i++){const ph=(T*2+i/3)%1;sp+=`<line x1="${f(-130-ph*30)}" y1="${-30+i*30}" x2="${f(-170-ph*30)}" y2="${-30+i*30}" ${st('#8FB9D0',6)} opacity="${f(1-ph)}"/>`}}
  return `<g transform="translate(${o.coil?0:-4},${o.coil?0:6})">${sp}${_e29snakeBody(o,o.fast?T*2.2:T)}</g>`};

/* lion: side view, mane around a plain head disc (no facial features) */
P.e29_lion=(o,T)=>{const tan='#E3A94F',tan2='#F1C77B',mane='#A5601F',mane2='#7E4513',sl=o.sleep,br=Math.sin(T*2)*(sl?2.5:1.2);
  let m='';for(let i=0;i<14;i++){const a=i/14*Math.PI*2;m+=`<circle cx="${f(Math.cos(a)*40)}" cy="${f(Math.sin(a)*40)}" r="21" fill="${mane}" ${st(C.navy,4)}/>`}
  let m2='';for(let i=0;i<14;i++){const a=i/14*Math.PI*2;m2+=`<circle cx="${f(Math.cos(a)*40)}" cy="${f(Math.sin(a)*40)}" r="19" fill="${i%2?mane:mane2}"/>`}
  const head=`<g>${m}${m2}<circle r="44" fill="${tan2}" ${st(C.navy,4)}/><circle cx="-30" cy="-34" r="11" fill="${tan}" ${st(C.navy,3.5)}/><circle cx="30" cy="-34" r="11" fill="${tan}" ${st(C.navy,3.5)}/></g>`;
  const tail=`<path d="M-92 ${sl?36:8} Q-126 ${sl?20:-10} -118 ${sl?-6:-44}" fill="none" ${st(C.navy,13)}/><path d="M-92 ${sl?36:8} Q-126 ${sl?20:-10} -118 ${sl?-6:-44}" fill="none" ${st(tan,7)}/><circle cx="-118" cy="${sl?-10:-48}" r="12" fill="${mane2}" ${st(C.navy,3.5)}/>`;
  if(sl)return `<g transform="translate(0,${f(br)})">${tail}<path d="M-96 86 Q-102 30 -50 22 L40 22 Q94 24 98 60 L98 86Z" fill="${tan}" ${st()}/><rect x="40" y="62" width="64" height="26" rx="13" fill="${tan2}" ${st()}/><rect x="-96" y="62" width="64" height="26" rx="13" fill="${tan2}" ${st()}/><g transform="translate(70,10) scale(.78)">${head}</g></g>`;
  return `<g transform="translate(0,${f(br)})">${tail}<rect x="-84" y="34" width="22" height="64" rx="9" fill="${tan}" ${st()}/><rect x="-36" y="34" width="22" height="64" rx="9" fill="${tan2}" ${st()}/><path d="M-100 -2 Q-102 -34 -60 -34 L36 -34 Q70 -34 70 4 Q70 52 30 52 L-66 52 Q-100 52 -100 -2Z" fill="${tan}" ${st()}/><rect x="14" y="34" width="22" height="64" rx="9" fill="${tan2}" ${st()}/><rect x="42" y="34" width="22" height="64" rx="9" fill="${tan}" ${st()}/><g transform="translate(66,-30) scale(.88)">${head}</g></g>`};

/* elephant: side view facing right, long trunk (the "nose"), tusk, ear; no eye */
const _e29eleph=(o,T)=>{const sw=Math.sin(T*2)*(o.fruit?5:7),g='#9AA9B4',g2='#7F909C';
  const tx=118,ty=-2;
  const trunk=`M108 -6 Q${f(136+sw*.4)} 22 ${f(128+sw)} 66 Q${f(124+sw)} 86 ${f(104+sw*1.3)} ${f(88-sw*.3)}`;
  return `<g><path d="M-92 2 Q-112 14 -106 52" fill="none" ${st(C.navy,6)}/>
  <rect x="-76" y="46" width="30" height="58" rx="10" fill="${g2}" ${st()}/><rect x="-14" y="46" width="30" height="58" rx="10" fill="${g2}" ${st()}/>
  <path d="M-102 -10 Q-102 -62 -40 -64 L34 -64 Q82 -60 82 -4 Q82 56 36 58 L-56 58 Q-102 58 -102 -10Z" fill="${g}" ${st()}/>
  <rect x="-48" y="46" width="30" height="58" rx="10" fill="${g}" ${st()}/><rect x="22" y="46" width="30" height="58" rx="10" fill="${g}" ${st()}/>
  <circle cx="74" cy="-22" r="44" fill="${g}" ${st()}/>
  <path d="M104 18 Q132 18 134 -2 Q112 -6 98 8Z" fill="${C.white}" ${st(C.navy,4)}/>
  <path d="${trunk}" fill="none" ${st(C.navy,34)}/><path d="${trunk}" fill="none" ${st(g,26)}/>
  <ellipse cx="46" cy="-14" rx="26" ry="40" fill="${g2}" ${st()}/><path d="M38 -36 Q50 -14 40 10" fill="none" ${st(C.navy,3)} opacity=".35"/>
  ${o.fruit?`<g transform="translate(${f(104+sw*1.3)},${f(98-sw*.3)}) scale(.34)"><circle r="46" cy="6" fill="${C.red}" ${st(C.navy,8)}/><path d="M0 -38 q4 -26 24 -32" fill="none" ${st(C.navy,8)}/><ellipse cx="24" cy="-60" rx="22" ry="10" transform="rotate(-25 24 -60)" fill="${C.leaf}" ${st(C.navy,5)}/></g>`:''}</g>`};
P.e29_elephant=(o,T)=>`<g transform="translate(-6,6) scale(.92)">${_e29eleph(o,T)}</g>`;

/* arm with hand (cuff at left). o.cold tints blue, o.pass holds a passport */
const _e29arm=(o,T)=>{const sk=o.cold?'#C4DAEA':'#E3AE82',sh=o.cold?Math.sin(T*40)*2:0;
  let fng='';for(let i=0;i<4;i++)fng+=`<rect x="${42+i*0}" y="${-26+i*15}" width="${60-Math.abs(i-1.5)*6}" height="15" rx="7.5" fill="${sk}" ${st(C.navy,4)}/>`;
  const fr=o.cold?`<g stroke="#fff" stroke-width="3" opacity=".9"><path d="M-30 -52 l8 -10 M-4 -56 l6 -12 M22 -52 l8 -10"/></g>`:'';
  return `<g transform="translate(${f(sh)},0)"><rect x="-122" y="-34" width="64" height="68" rx="12" fill="${C.blue}" ${st()}/><path d="M-66 -34 v68" ${st(C.navy,3.5)} fill="none"/><rect x="-62" y="-26" width="116" height="52" rx="22" fill="${sk}" ${st()}/>${fng}<ellipse cx="40" cy="4" rx="34" ry="32" fill="${sk}" ${st()}/><path d="M34 -30 q-4 -28 14 -34 q16 -2 14 20" fill="${sk}" ${st(C.navy,4)} transform="translate(-8,40) rotate(-62 38 -30)"/>${fr}${o.apple?`<g transform="translate(70,2) scale(.5)"><circle r="46" cy="6" fill="${C.red}" ${st(C.navy,8)}/><path d="M0 -38 q4 -26 24 -32" fill="none" ${st(C.navy,8)}/><ellipse cx="24" cy="-60" rx="22" ry="10" transform="rotate(-25 24 -60)" fill="${C.leaf}" ${st(C.navy,5)}/></g>`:''}${o.pass?`<g transform="translate(66,-6) rotate(14) scale(.5)">${P.e29_passport({},T)}</g>`:''}</g>`};
P.e29_arm=(o,T)=>`<g>${_e29arm(o,T)}</g>`;

P.e29_foot=(o,T)=>{const sk=o.cold?'#C4DAEA':'#E3AE82',sh=o.cold?Math.sin(T*40)*2:0;let toes='';[[104,50,13],[91,40,11],[78,34,10],[64,31,9.5]].forEach(([x,y,r])=>{toes+=`<circle cx="${x}" cy="${y}" r="${r}" fill="${sk}" ${st(C.navy,3.5)}/>`});
  return `<g transform="translate(${f(sh)},0)"><rect x="-64" y="-108" width="48" height="108" rx="12" fill="${sk}" ${st()}/><rect x="-68" y="-124" width="56" height="44" rx="10" fill="${C.blue}" ${st()}/><path d="M-70 -4 L-14 -4 Q36 6 84 34 Q112 48 112 66 Q112 82 94 82 L-74 82 Q-86 82 -86 68 Q-86 20 -70 -4Z" fill="${sk}" ${st()}/><path d="M-86 84 L112 84" ${st(C.navy,5)} fill="none"/>${toes}${o.cold?`<g stroke="#fff" stroke-width="3" opacity=".9"><path d="M-8 -20 l8 -12 M30 -4 l10 -10"/></g>`:''}</g>`};

/* trunk touching an arm or a foot */
P.e29_trunkarm=(o,T)=>{const foot=o.part==='foot',tap=Math.abs(Math.sin(T*3))*10,g='#9AA9B4';
  const tr=`M96 -128 Q104 -64 70 ${f(-22+tap)} Q54 ${f(8+tap)} 30 ${f(20+tap)}`;
  return `<g><g transform="translate(-4,56) scale(${foot?.78:.9})">${foot?P.e29_foot({},T):_e29arm({},T)}</g><path d="${tr}" fill="none" ${st(C.navy,40)}/><path d="${tr}" fill="none" ${st(g,32)}/><path d="M94 -128 Q100 -86 90 -52" fill="none" ${st('#7F909C',8)} opacity=".6"/></g>`};

/* passport (correct English text) */
P.e29_passport=(o,T)=>{const cov='#1F4E8C',gl=C.gold;
  return `<g transform="rotate(${f(Math.sin(T*1.6)*2)})"><rect x="-76" y="-108" width="152" height="212" rx="12" fill="${cov}" ${st()}/><rect x="-66" y="-98" width="132" height="192" rx="8" fill="none" stroke="${gl}" stroke-width="3"/><text x="0" y="-64" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="19" fill="${gl}" letter-spacing="1.5">PASSPORT</text><g transform="translate(0,16)"><circle r="40" fill="none" stroke="${gl}" stroke-width="5"/><ellipse rx="17" ry="40" fill="none" stroke="${gl}" stroke-width="4"/><line x1="-40" y1="0" x2="40" y2="0" stroke="${gl}" stroke-width="4"/><path d="M-34 -20 H34 M-34 20 H34" stroke="${gl}" stroke-width="3" fill="none"/></g></g>`};

/* plane + airport */
P.e29_plane=(o,T)=>{const fly=o.fly,sw=Math.sin(T*2.2),rot=fly?-10+sw*2:0,by=fly?sw*5:0;let tr='';
  if(fly)for(let i=0;i<3;i++){const ph=(T*1.4+i/3)%1;tr+=`<line x1="${f(-122-ph*60)}" y1="${-18+i*20}" x2="${f(-156-ph*60)}" y2="${-18+i*20}" ${st('#8FB9D0',6)} opacity="${f(1-ph)}"/>`}
  let w='';for(let i=0;i<6;i++)w+=`<circle cx="${-70+i*24}" cy="-10" r="6" fill="${C.sky}" ${st(C.navy,2.5)}/>`;
  return `<g transform="translate(0,${f(by)}) rotate(${f(rot)})">${tr}<path d="M-108 -8 L-134 -66 L-92 -66 L-56 -34Z" fill="${C.red}" ${st()}/><path d="M-14 8 L-70 76 L-30 76 L56 8Z" fill="#B9C6CE" ${st()}/><path d="M-112 -6 Q-112 -34 -80 -36 L70 -36 Q124 -30 124 -2 Q124 20 70 22 L-80 22 Q-112 22 -112 -6Z" fill="${C.white}" ${st()}/><clipPath id="e29pl"><path d="M-112 -6 Q-112 -34 -80 -36 L70 -36 Q124 -30 124 -2 Q124 20 70 22 L-80 22 Q-112 22 -112 -6Z"/></clipPath><rect x="-120" y="6" width="250" height="9" fill="${C.blue}" clip-path="url(#e29pl)"/>${w}<path d="M88 -26 Q112 -24 118 -8 L88 -8Z" fill="${C.sky}" ${st(C.navy,3)}/><ellipse cx="14" cy="34" rx="30" ry="12" fill="#8FA3B0" ${st(C.navy,4)}/></g>`};
P.e29_airport=(o,T)=>{let w='';for(let i=0;i<6;i++)w+=`<rect x="${-100+i*34}" y="22" width="26" height="22" fill="${C.sky}" ${st(C.navy,3)}/>`;
  const px=((T*40)%300)-170;
  return `<g><rect x="-128" y="84" width="256" height="30" fill="#8FA3B0" ${st()}/><line x1="-110" y1="99" x2="110" y2="99" stroke="#fff" stroke-width="4" stroke-dasharray="18 14"/><rect x="-116" y="14" width="190" height="70" fill="#E7D3A6" ${st()}/><rect x="-124" y="6" width="206" height="12" fill="${C.goldD}" ${st()}/>${w}<rect x="92" y="-70" width="22" height="154" fill="#D9C9A2" ${st()}/><rect x="76" y="-110" width="54" height="44" rx="8" fill="${C.sky}" ${st()}/><rect x="70" y="-70" width="66" height="10" rx="4" fill="${C.navy}"/><g transform="translate(${f(px)},-40) scale(.34)">${P.e29_plane({fly:1},T)}</g></g>`};

/* space: night panel, stars, earth, rocket */
P.e29_space=(o,T)=>{let s='';for(let i=0;i<16;i++){const x=-96+((i*61)%192),y=-110+((i*47)%190);s+=`<circle cx="${x}" cy="${y}" r="${1.6+(i%3)}" fill="#FFF3C4" opacity="${f(.5+.5*Math.sin(T*2.4+i))}"/>`}
  const earth=`<g transform="translate(${o.rocket?-44:0},${o.rocket?44:10})"><circle r="${o.rocket?50:62}" fill="#3F86C8" ${st('#9CC8EA',4)}/><g fill="#5FA05A" transform="scale(${o.rocket?.8:1})"><path d="M-30 -20 q16 -22 36 -8 q8 14 -6 24 q-14 8 -22 -2 q-14 4 -8 -14Z"/><path d="M14 22 q16 -8 24 6 q-6 16 -22 12Z"/></g></g>`;
  const rk=o.rocket?`<g transform="translate(${f(34+Math.sin(T*2)*3)},${f(-34+Math.cos(T*2)*3)}) rotate(38)"><path d="M0 -62 Q26 -34 22 22 L-22 22 Q-26 -34 0 -62Z" fill="${C.white}" ${st(C.navy,4)}/><path d="M-22 4 L-42 34 L-22 22Z M22 4 L42 34 L22 22Z" fill="${C.red}" ${st(C.navy,4)}/><circle cy="-20" r="9" fill="${C.sky}" ${st(C.navy,3.5)}/><path d="M-12 22 L0 52 L12 22Z" fill="${C.orange}" ${st(C.navy,3)}/></g>`:'';
  return `<g><rect x="-110" y="-124" width="220" height="248" rx="26" fill="#131C38" ${st()}/>${s}${earth}${rk}</g>`};

/* negative / positive */
P.e29_neg=(o,T)=>{const sh=Math.sin(T*3)*3;return `<g><g transform="translate(${f(-34+sh)},-58) scale(.9)">${cloudShape('#8E9AA3')}</g><path d="M-8 -8 L-34 36 L-8 34 L-22 72 L24 18 L-2 20 L16 -8Z" fill="${C.gold}" ${st(C.navy,3.5)} transform="translate(-16,-12)"/><circle cx="50" cy="52" r="52" fill="${C.red}" ${st()}/><line x1="26" y1="52" x2="74" y2="52" stroke="#fff" stroke-width="16" stroke-linecap="round"/></g>`};
P.e29_pos=(o,T)=>{const pu=1+.05*Math.sin(T*4);let r='';for(let i=0;i<10;i++)r+=`<line x1="0" y1="-52" x2="0" y2="-70" transform="rotate(${i*36+T*18})" ${st('#C9971F',6)}/>`;
  return `<g><g transform="translate(-24,-36) scale(${f(.9*pu)})"><g>${r}</g><circle r="44" fill="#F6CE4B" ${st('#C9971F',5)}/></g><circle cx="46" cy="52" r="52" fill="${C.moss}" ${st()}/><line x1="22" y1="52" x2="70" y2="52" stroke="#fff" stroke-width="16" stroke-linecap="round"/><line x1="46" y1="28" x2="46" y2="76" stroke="#fff" stroke-width="16" stroke-linecap="round"/></g>`};

/* ruler with length label, and bed-vs-snake comparison */
P.e29_tape=(o,T,k)=>{const t=o.t||'3 m',p=ease(k/.6);let tk='';for(let i=0;i<=10;i++)tk+=`<line x1="${-110+i*22}" y1="-8" x2="${-110+i*22}" y2="${i%5?8:20}" ${st(C.navy,3.5)}/>`;
  return `<g><rect x="-120" y="-20" width="240" height="64" rx="8" fill="${C.gold}" ${st()}/><g transform="translate(0,6)">${tk}</g><g opacity="${f(p)}"><line x1="-120" y1="-52" x2="120" y2="-52" ${st(C.red,6)}/><path d="M-102 -68 L-120 -52 L-102 -36 M102 -68 L120 -52 L102 -36" fill="none" ${st(C.red,6)}/></g><text x="0" y="-80" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="62" fill="${C.navy}">${t}</text></g>`};
P.e29_compare=(o,T,k)=>{const a=ease(k/.7),b=ease((k-.3)/.7);
  return `<g><g transform="translate(-78,-62) scale(.4)">${P.e29_snake({},T)}</g><rect x="-26" y="-84" width="${f(150*a)}" height="40" rx="12" fill="#5FA05A" ${st()}/><text x="${f(-26+150*a-14)}" y="-54" text-anchor="end" font-family="Fraunces" font-weight="800" font-size="32" fill="#fff" opacity="${f(a)}">3 m</text><g transform="translate(-76,52) scale(.38)">${P.bed({},T)}</g><rect x="-26" y="30" width="${f(100*b)}" height="40" rx="12" fill="${C.brown}" ${st()}/><text x="${f(-26+100*b-14)}" y="60" text-anchor="end" font-family="Fraunces" font-weight="800" font-size="32" fill="#fff" opacity="${f(b)}">2 m</text></g>`};
/* big number badge that fits 1-3 digits */
P.e29_num=(o,T)=>{const s=String(o.n),fs=s.length>=3?64:s.length==2?84:112;return `<g transform="scale(${f(1+.04*Math.sin(T*4))})"><circle r="84" fill="${C.gold}" ${st()}/><circle r="68" fill="none" ${st(C.goldD,3)}/><text x="0" y="${f(fs*.36)}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${fs}" fill="${C.navy}">${s}</text></g>`};
/* three people following each other */
P.e29_follow=(o,T)=>{const cs=[['#4DA3D8','short','#222'],['#D96C8B','long','#3A2A22'],['#8E6BB5','short','#222']];let s='';
  cs.forEach((c,i)=>{s+=`<g transform="translate(${-96+i*96},${f(10+Math.abs(Math.sin(T*4+i*.6))*-6)}) scale(.5)">${P.person({c:c[0],hair:c[1],hc:c[2],ph:i},T)}</g>`});
  let a='';for(let i=0;i<3;i++){const ph=(T*.9+i/3)%1;a+=`<path d="M${f(-130+ph*60+i*0)} 100 l16 -12 v24Z" fill="${C.gold}" ${st(C.navy,3)} opacity="${f(1-Math.abs(ph-.5)*1.2)}" transform="translate(${i*84},0)"/>`}
  return `<g>${s}<line x1="-120" y1="104" x2="120" y2="104" ${st('#9AA7B0',5)}/>${a}</g>`};
/* glass window with a snake behind it */
P.e29_glass=(o,T)=>`<g><rect x="-112" y="-100" width="224" height="200" rx="14" fill="#E3EEF2" ${st()}/><rect x="-112" y="-100" width="224" height="200" rx="14" fill="#B9D6E0" opacity=".55"/><g transform="translate(0,12) scale(.64)">${P.e29_snake({coil:1},T)}</g><rect x="-112" y="-100" width="224" height="200" rx="14" fill="#BFE3F2" opacity=".28"/><path d="M-84 -80 L-24 -80 L-84 -20Z M-8 -80 L24 -80 L-62 6Z" fill="#fff" opacity=".6"/><rect x="-124" y="-112" width="248" height="14" rx="6" fill="${C.brown}" ${st()}/><rect x="-124" y="98" width="248" height="14" rx="6" fill="${C.brown}" ${st()}/></g>`;
/* animal park gate */
P.e29_gate=(o,T)=>`<g><rect x="-112" y="-26" width="26" height="130" fill="${C.brown}" ${st()}/><rect x="86" y="-26" width="26" height="130" fill="${C.brown}" ${st()}/><rect x="-120" y="-92" width="240" height="70" rx="14" fill="#2F6B55" ${st()}/><text x="0" y="-45" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="27" fill="${C.cream}" letter-spacing="1">ANIMAL PARK</text><g transform="translate(-50,76) scale(.4)">${P.tree({},T)}</g><g transform="translate(52,76) scale(.4)">${P.tree({},T)}</g><path d="M-86 104 H86" ${st(C.navy,5)}/></g>`;
/* fruit */
P.e29_fruit=(o,T)=>{const w=Math.sin(T*2)*2;return `<g transform="rotate(${f(w)})"><path d="M10 -96 Q104 -92 112 8 Q98 -6 74 -28 Q44 -56 10 -64Z" fill="#F2D24B" ${st()}/><path d="M10 -96 l-6 -16" ${st(C.brown,8)}/><circle cx="62" cy="40" r="46" fill="${C.orange}" ${st()}/><circle cx="-34" cy="14" r="52" fill="${C.red}" ${st()}/><path d="M-34 -36 q4 -26 24 -32" fill="none" ${st(C.navy,6)}/><ellipse cx="-12" cy="-64" rx="22" ry="10" transform="rotate(-25 -12 -64)" fill="${C.leaf}" ${st(C.navy,4)}/></g>`};
/* airplane seat */
P.e29_seat=(o,T)=>`<g><rect x="-84" y="-112" width="168" height="166" rx="40" fill="${C.blue}" ${st()}/><rect x="-54" y="-136" width="108" height="46" rx="20" fill="#7DB9E0" ${st()}/><rect x="-104" y="-6" width="34" height="96" rx="14" fill="#2F6F9F" ${st()}/><rect x="70" y="-6" width="34" height="96" rx="14" fill="#2F6F9F" ${st()}/><rect x="-84" y="40" width="168" height="48" rx="20" fill="#3E8CC2" ${st()}/><path d="M-60 6 L60 6" ${st(C.gold,8)} fill="none"/><rect x="-14" y="-6" width="28" height="24" rx="6" fill="${C.gold}" ${st(C.navy,3.5)}/><rect x="-60" y="88" width="14" height="24" fill="${C.navy2}"/><rect x="46" y="88" width="14" height="24" fill="${C.navy2}"/></g>`;
/* coat on the back of a door; dark = the night room */
P.e29_coatdoor=(o,T)=>{const d=o.dark;const bg=d?`<rect x="-120" y="-124" width="240" height="250" rx="18" fill="#161E36" ${st()}/><g transform="translate(78,-84) scale(.34)">${P.moon({},T)}</g>`:`<rect x="-120" y="-124" width="240" height="250" rx="18" fill="#F4E5C2" ${st()}/>`;
  return `<g>${bg}<rect x="-62" y="-108" width="124" height="226" rx="8" fill="${d?'#3A2A22':C.brown}" ${st()}/><circle cx="40" cy="30" r="7" fill="${C.gold}" ${st(C.navy,3)}/><circle cy="-92" r="8" fill="${C.gold}" ${st(C.navy,3)}/><g transform="translate(0,6) scale(.74)">${P.coat({c:d?'#3B3F4A':'#C0504D'},T)}</g></g>`};
/* night light */
P.e29_lamp=(o,T)=>{const on=o.on!==0,g=1+.05*Math.sin(T*3);let r='';if(on)for(let i=0;i<8;i++)r+=`<line x1="0" y1="-98" x2="0" y2="-122" transform="rotate(${-70+i*20} 0 -30)" ${st(C.gold,6)} opacity=".85"/>`;
  return `<g>${on?`<circle cy="-30" r="${f(86*g)}" fill="#FFE9A0" opacity=".45"/>`:''}${r}<path d="M-44 -34 L-26 -92 L26 -92 L44 -34Z" fill="${on?'#FFE08A':'#8A8F99'}" ${st()}/><rect x="-6" y="-34" width="12" height="96" fill="${C.navy2}" ${st(C.navy,3)}/><ellipse cx="0" cy="68" rx="50" ry="14" fill="${C.navy2}" ${st()}/></g>`};
/* bathroom: tub + tap */
P.e29_bathroom=(o,T)=>{let t='';for(let i=0;i<4;i++)for(let j=0;j<3;j++)t+=`<rect x="${-110+i*56}" y="${-112+j*40}" width="52" height="36" fill="#CFE7F0" stroke="#fff" stroke-width="3"/>`;const ph=(T*1.2)%1;
  return `<g><rect x="-114" y="-116" width="228" height="124" rx="10" fill="#CFE7F0" ${st()}/>${t}<path d="M-40 -34 h16 q22 0 22 22 v6" fill="none" ${st(C.navy,8)}/><rect x="-52" y="-44" width="30" height="14" rx="5" fill="#B9C6CE" ${st()}/><path d="M-4 ${f(-6+ph*40)} q-6 10 0 16 q6 -6 0 -16" fill="${C.blue}" opacity="${f(1-ph)}"/><path d="M-118 10 H118 V56 Q118 98 76 98 H-76 Q-118 98 -118 56Z" fill="${C.white}" ${st()}/><rect x="-86" y="96" width="22" height="16" rx="5" fill="#B9C6CE" ${st()}/><rect x="64" y="96" width="22" height="16" rx="5" fill="#B9C6CE" ${st()}/></g>`};
/* beach holiday */
P.e29_holiday=(o,T)=>{const sw=Math.sin(T*1.6)*3;let lv='';for(let i=0;i<5;i++){const a=-150+i*34;lv+=`<path d="M0 -70 Q${f(Math.cos(a*Math.PI/180)*50)} ${f(-70+Math.sin(a*Math.PI/180)*44-10)} ${f(Math.cos(a*Math.PI/180)*84)} ${f(-70+Math.sin(a*Math.PI/180)*60+16+sw)}" fill="none" ${st(C.navy,16)}/><path d="M0 -70 Q${f(Math.cos(a*Math.PI/180)*50)} ${f(-70+Math.sin(a*Math.PI/180)*44-10)} ${f(Math.cos(a*Math.PI/180)*84)} ${f(-70+Math.sin(a*Math.PI/180)*60+16+sw)}" fill="none" ${st(C.leaf,10)}/>`}
  return `<g><g transform="translate(70,-70) scale(.5)">${P.sun({},T)}</g><path d="M-124 70 Q-40 40 0 62 T124 54 V108 H-124Z" fill="${C.blue}" ${st()}/><path d="M-120 100 Q-60 70 0 94 T120 90 V110 H-120Z" fill="#E9CB92" opacity="0"/><path d="M-14 100 Q-4 20 -2 -70" fill="none" ${st(C.navy,22)}/><path d="M-14 100 Q-4 20 -2 -70" fill="none" ${st(C.brown,14)}/><g transform="translate(-2,0)">${lv}</g></g>`};
/* the dark: black room with a small moon */
P.e29_dark=(o,T)=>{let s='';for(let i=0;i<8;i++){s+=`<circle cx="${-90+((i*53)%180)}" cy="${-100+((i*37)%120)}" r="2.4" fill="#FFF3C4" opacity="${f(.4+.4*Math.sin(T*2+i))}"/>`}
  return `<g><rect x="-110" y="-124" width="220" height="248" rx="26" fill="#0B1022" ${st()}/>${s}<g transform="translate(46,-76) scale(.4)"><circle r="60" fill="#FFF3C4"/><circle cx="26" cy="-10" r="52" fill="#0B1022"/></g></g>`};
/* afraid: trembling person with sweat drops (faceless) */
P.e29_afraid=(o,T)=>{const sh=Math.sin(T*38)*2.6,ph=(T*.9)%1;return `<g><g transform="translate(${f(sh)},24) scale(.85)">${P.person({c:o.c||'#4DA3D8',hair:o.hair||'short',hc:o.hc||'#222'},T)}</g><path d="M${f(70)} ${f(-56+ph*14)} C82 -38 90 -28 90 -16 a20 20 0 0 1 -40 0 C50 -28 58 -38 70 -56Z" fill="${C.blue}" ${st(C.navy,4)} transform="translate(0,${f(ph*8)})"/><path d="M-72 -56 l-22 -12 M-76 -30 l-26 0 M-72 -4 l-22 12" ${st(C.navy,5)} fill="none" opacity="${f(.5+.5*Math.sin(T*20))}"/></g>`};
/* hero: trembling person, sweat, and a snake nearby */
P.e29_hero=(o,T)=>{const sh=Math.sin(T*30)*2.4,ph=(T*.9)%1;return `<g><g transform="translate(${f(-14+sh)},-6) scale(.92)">${P.person({c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g><g transform="translate(70,72) scale(.5)">${P.e29_snake({coil:1},T)}</g><path d="M52 ${f(-70+ph*10)} C64 -52 72 -42 72 -30 a20 20 0 0 1 -40 0 C32 -42 40 -52 52 -70Z" fill="${C.blue}" ${st(C.navy,4)}/><path d="M-100 -84 l-18 -14 M-108 -50 l-24 0 M-100 -16 l-18 14" ${st(C.gold,6)} fill="none" opacity="${f(.5+.5*Math.sin(T*18))}"/><g transform="translate(86,-96) scale(.4)">${P.bubble({side:'L',text:'!',fs:96,w:70},T)}</g></g>`};

/* strong: flexed arm */
P.e29_muscle=(o,T)=>{const p=1+.04*Math.sin(T*4),sk='#E3AE82';return `<g transform="scale(${f(p)})"><rect x="-116" y="14" width="150" height="56" rx="26" fill="${sk}" ${st()}/><rect x="-124" y="6" width="50" height="72" rx="12" fill="${C.blue}" ${st()}/><path d="M-6 56 L-14 -60 Q-12 -80 14 -80 Q40 -80 42 -60 L40 56Z" fill="${sk}" ${st()}/><circle cx="14" cy="-92" r="34" fill="${sk}" ${st()}/><path d="M-6 -78 h40 M-4 -96 h36" ${st(C.navy,4)} fill="none" opacity=".5"/><ellipse cx="-34" cy="10" rx="40" ry="34" fill="${sk}" ${st()}/><path d="M-52 4 Q-34 -12 -16 4" fill="none" ${st('#C48A5E',5)}/></g>`};

/* Episode 30 props: plans, language, driving, career, forms/interviews, presents, planes landing. Faceless. Uses C, st, f, ease, clamp, P. */
const _e30pencil=(rot)=>`<g transform="rotate(${rot})"><rect x="-8" y="-62" width="16" height="92" rx="3" fill="${C.gold}" ${st()}/><rect x="-8" y="-62" width="16" height="18" fill="${C.red}" ${st()}/><path d="M-8 30 L0 54 L8 30Z" fill="${C.cream}" ${st()}/><path d="M-3 46 L0 54 L3 46Z" fill="${C.navy}"/></g>`;
const _e30check=(x,y,s)=>`<path d="M${x-8*s} ${y} l${7*s} ${8*s} l${14*s} ${-16*s}" fill="none" stroke="${C.moss}" stroke-width="${5*s}" stroke-linecap="round" stroke-linejoin="round"/>`;
/* notebook with ticked plans; o.checks = number ticked, o.write = pencil moves */
P.e30_notebook=(o,T,k)=>{const n=o.checks==null?3:o.checks;let r='';for(let i=0;i<4;i++){const y=-52+i*38,on=i<n,pp=ease((k-.3-i*.3)/.3);r+=`<rect x="-62" y="${y-12}" width="24" height="24" rx="5" fill="${C.white}" ${st(C.navy,3.5)}/><line x1="-24" y1="${y}" x2="${[62,48,66,40][i]}" y2="${y}" ${st('#9AA7B0',5)}/>`;if(on)r+=`<g opacity="${f(o.still?1:pp)}">${_e30check(-50,y,1.1)}</g>`}
  let rings='';for(let i=0;i<6;i++)rings+=`<rect x="${-76+i*30}" y="-126" width="12" height="26" rx="6" fill="#B9C6CE" ${st(C.navy,3.5)}/>`;
  const wx=o.write?Math.sin(T*5)*10:0;
  return `<g><rect x="-96" y="-112" width="192" height="236" rx="14" fill="${C.paper}" ${st()}/><rect x="-96" y="-112" width="192" height="26" rx="14" fill="${C.blue}" ${st()}/>${rings}${r}<g transform="translate(${f(60+wx)},${f(70+(o.write?Math.sin(T*10)*3:0))})">${_e30pencil(40)}</g></g>`};
P.e30_book=(o,T)=>`<g><path d="M0 -84 Q-56 -108 -118 -86 L-118 78 Q-56 56 0 82Z" fill="${C.cream}" ${st()}/><path d="M0 -84 Q56 -108 118 -86 L118 78 Q56 56 0 82Z" fill="${C.cream}" ${st()}/><path d="M-100 -52 Q-56 -66 -14 -50 M-100 -24 Q-56 -38 -14 -22 M-100 4 Q-56 -10 -14 6 M14 -50 Q56 -66 100 -52 M14 -22 Q56 -38 100 -24 M14 6 Q56 -10 100 4" fill="none" ${st('#9AA7B0',4)}/><path d="M-124 -80 L-124 90 Q-56 66 0 96 Q56 66 124 90 L124 -80" fill="none" ${st(C.brown,9)}/><line x1="0" y1="-84" x2="0" y2="96" ${st(C.navy,4)}/></g>`;
/* new language: globe with speech bubbles */
P.e30_lang=(o,T)=>{const b=Math.sin(T*2)*4;return `<g><g transform="translate(0,22) scale(.82)">${P.globe({},T)}</g><g transform="translate(-72,${f(-78+b)}) scale(.5)">${P.bubble({side:'R',text:'Hi!',fs:46,w:90},T)}</g><g transform="translate(76,${f(-86-b)}) scale(.5)">${P.bubble({side:'L',text:'...',fs:60,w:90},T)}</g></g>`};
/* laptop: o.screen = code | text | web | photo */
P.e30_laptop=(o,T,k)=>{const sc=o.screen||'code';let s='';
  if(sc==='code'){for(let i=0;i<5;i++){const w=30+((i*47+Math.floor(T*1.5)*13)%70),x=-70+(i%2)*18;s+=`<rect x="${x}" y="${-62+i*20}" width="${w}" height="9" rx="4" fill="${[C.gold,C.cold,C.moss,C.orange,C.gold][i]}"/>`}}
  else if(sc==='web'){s+=`<rect x="-76" y="-72" width="152" height="124" rx="6" fill="${C.cream}"/><rect x="-76" y="-72" width="152" height="16" fill="${C.blue}"/><rect x="-62" y="-44" width="52" height="40" rx="5" fill="${C.sky}"/><path d="M-62 -4 L-46 -28 L-34 -14 L-24 -22 L-10 -4Z" fill="${C.leaf}"/><line x1="6" y1="-40" x2="64" y2="-40" ${st('#9AA7B0',5)}/><line x1="6" y1="-26" x2="56" y2="-26" ${st('#9AA7B0',5)}/><line x1="6" y1="-12" x2="64" y2="-12" ${st('#9AA7B0',5)}/><rect x="-62" y="8" width="124" height="14" rx="5" fill="${C.gold}"/><rect x="-62" y="30" width="124" height="10" rx="4" fill="#E8DFC8"/>`}
  else if(sc==='photo'){s+=`<rect x="-70" y="-70" width="140" height="110" rx="6" fill="${C.sky}"/><circle cx="34" cy="-38" r="14" fill="${C.gold}"/><path d="M-70 40 L-30 -20 L-4 14 L18 -8 L70 40Z" fill="${C.leaf}"/>`}
  else{const n=o.lines==null?4:o.lines;for(let i=0;i<n;i++){const pp=ease((k-i*.25)/.3);s+=`<line x1="-70" y1="${-58+i*20}" x2="${f(-70+(120-(i%3)*22)*pp)}" y2="${-58+i*20}" ${st(C.cream,5)}/>`}}
  return `<g><rect x="-100" y="-96" width="200" height="140" rx="12" fill="${C.navy2}" ${st()}/><rect x="-86" y="-82" width="172" height="112" rx="6" fill="#16222A"/><g transform="translate(0,-8)">${s}</g><path d="M-124 50 L124 50 L110 70 Q0 84 -110 70Z" fill="#B9C6CE" ${st()}/><rect x="-24" y="52" width="48" height="8" rx="4" fill="#8FA3B0"/></g>`};
P.e30_wheel=(o,T)=>{const r=Math.sin(T*1.6)*10;return `<g transform="rotate(${f(r)})"><circle r="98" fill="none" ${st(C.navy,30)}/><circle r="98" fill="none" ${st(C.navy2,20)}/><path d="M-96 8 H96 M0 8 V92" fill="none" ${st(C.navy,16)}/><path d="M-96 8 H96 M0 8 V92" fill="none" ${st(C.navy2,8)}/><circle r="30" fill="${C.navy2}" ${st()}/><circle r="14" fill="${C.gold}" ${st(C.navy,3.5)}/></g>`};
/* 12-month grid; o.hi = highlighted month number, o.lab = label */
P.e30_months=(o,T,k)=>{let g='';for(let i=0;i<12;i++){const r=Math.floor(i/4),c=i%4,on=(i+1)===o.hi,pp=on?1+.07*Math.sin(T*5):1,x=-78+c*52,y=-34+r*52;g+=`<g transform="translate(${x},${y}) scale(${f(pp)})"><rect x="-22" y="-22" width="44" height="44" rx="8" fill="${on?C.gold:C.white}" ${st(on?C.goldD:C.navy,on?5:3)}/><text y="8" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="22" fill="${C.navy}">${i+1}</text></g>`}
  return `<g><rect x="-114" y="-112" width="228" height="224" rx="18" fill="${C.cream}" ${st()}/><path d="M-114 -66 V-94 Q-114 -112 -96 -112 H96 Q114 -112 114 -94 V-66Z" fill="${C.red}" ${st()}/><text y="-76" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${(o.lab||'').length>6?24:30}" fill="${C.cream}" letter-spacing="1">${o.lab||''}</text><g transform="translate(0,8)">${g}</g></g>`};
P.e30_stop=(o,T)=>{let p='';for(let i=0;i<8;i++){const a=(i*45+22.5)*Math.PI/180;p+=`${f(Math.cos(a)*92)},${f(Math.sin(a)*92)} `}return `<g><rect x="-8" y="60" width="16" height="64" fill="#9FB0BA" ${st()}/><polygon points="${p}" fill="${C.red}" ${st()}/><polygon points="${p}" fill="none" stroke="#fff" stroke-width="5" transform="scale(.86)"/><text y="14" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="40" fill="#fff" letter-spacing="2">STOP</text></g>`};
P.e30_test=(o,T,k)=>{const p=ease((k-.5)/.4);return `<g><rect x="-86" y="-114" width="172" height="228" rx="12" fill="${C.paper}" ${st()}/><rect x="-36" y="-126" width="72" height="26" rx="8" fill="${C.navy2}" ${st()}/><g transform="translate(0,-34) scale(.5)">${P.e30_wheel({},0)}</g><line x1="-60" y1="34" x2="40" y2="34" ${st('#9AA7B0',5)}/><line x1="-60" y1="62" x2="20" y2="62" ${st('#9AA7B0',5)}/><g opacity="${f(p)}"><circle cx="50" cy="34" r="0" /><path d="M42 34 l8 9 l16 -20" fill="none" ${st(C.moss,7)}/></g></g>`};
P.e30_form=(o,T,k)=>{const n=o.fill==null?0:o.fill;let r='';for(let i=0;i<4;i++){const y=-44+i*36,pp=ease((k-.3-i*.35)/.4);r+=`<rect x="-60" y="${y-11}" width="22" height="22" rx="4" fill="${C.white}" ${st(C.navy,3.5)}/><line x1="-26" y1="${y}" x2="60" y2="${y}" ${st('#9AA7B0',4)}/>${n?`<line x1="-26" y1="${y-3}" x2="${f(-26+(70-(i%2)*24)*pp)}" y2="${y-3}" ${st(C.blue,5)}/>`:''}`}
  return `<g><rect x="-84" y="-112" width="168" height="224" rx="10" fill="${C.cream}" ${st()}/><rect x="-84" y="-112" width="168" height="34" rx="10" fill="${C.blue}" ${st()}/><text y="-86" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="${C.cream}" letter-spacing="4">FORM</text>${r}<path d="M-60 92 q12 -22 22 -4 t22 -4 t22 2" fill="none" ${st(C.navy,3.5)}/></g>`};
P.e30_interview=(o,T)=>{const b=1+.05*Math.sin(T*4);return `<g><g transform="translate(-72,0) scale(.5)">${P.person({c:'#4F7A5A',hair:'long',hc:'#2A1D18'},T)}</g><g transform="translate(76,0) scale(.5)">${P.person({c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g><rect x="-122" y="40" width="244" height="22" rx="8" fill="${C.brown}" ${st()}/><rect x="-100" y="62" width="14" height="52" fill="${C.brown}" ${st()}/><rect x="86" y="62" width="14" height="52" fill="${C.brown}" ${st()}/><rect x="-26" y="26" width="52" height="14" fill="${C.cream}" ${st(C.navy,3)}/><g transform="translate(0,-92) scale(${f(.42*b)})">${P.bubble({side:'L',text:'?',fs:92,w:70},T)}</g></g>`};
P.e30_career=(o,T,k)=>{let s='';for(let i=0;i<4;i++)s+=`<rect x="${-112+i*52}" y="${64-i*40}" width="52" height="${40*(i+1)+40}" fill="${i%2?'#D9C9A2':'#E7D3A6'}" ${st(C.navy,4)}/>`;
  const ph=(T*.5)%1,px=-86+ph*150,py=40-ph*118;return `<g>${s}<g transform="translate(${f(px)},${f(py)}) scale(.3)">${P.person({c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g><g transform="translate(58,-92) scale(.38)">${P.brief({},T)}</g><g transform="translate(6,-116) scale(.3)">${P.star({},T)}</g></g>`};
P.e30_boring=(o,T)=>{let w='';for(let i=0;i<3;i++){const ph=(T*.5+i/3)%1;w+=`<text x="${f(-18+ph*40)}" y="${f(-96-ph*40)}" font-family="Fraunces" font-weight="800" font-size="${34+i*10}" fill="#7C8790" opacity="${f(Math.sin(ph*Math.PI))}">z</text>`}
  return `<g>${w}<rect x="-64" y="-56" width="128" height="92" rx="10" fill="#8A949C" ${st()}/><rect x="-52" y="-44" width="104" height="68" rx="4" fill="#C9D1D7"/>${[0,1,2].map(i=>`<line x1="-40" y1="${-28+i*18}" x2="${[30,38,26][i]}" y2="${-28+i*18}" ${st('#8A949C',5)}/>`).join('')}<rect x="-12" y="36" width="24" height="22" fill="#6E7881" ${st()}/><rect x="-124" y="58" width="248" height="16" rx="6" fill="#9A8F7E" ${st()}/><rect x="-108" y="74" width="14" height="44" fill="#7C7264"/><rect x="94" y="74" width="14" height="44" fill="#7C7264"/><rect x="-40" y="46" width="80" height="12" rx="4" fill="#6E7881" ${st(C.navy,3)}/></g>`};
P.e30_desk=(o,T)=>`<g><rect x="-124" y="10" width="248" height="22" rx="8" fill="${C.brown}" ${st()}/><rect x="-104" y="32" width="16" height="84" fill="${C.brown}" ${st()}/><rect x="88" y="32" width="16" height="84" fill="${C.brown}" ${st()}/><rect x="52" y="-44" width="66" height="54" rx="6" fill="${C.navy2}" ${st()}/><rect x="58" y="-38" width="54" height="42" fill="#C9D1D7"/><rect x="-96" y="-30" width="70" height="40" rx="6" fill="${C.cream}" ${st()}/><line x1="-86" y1="-16" x2="-40" y2="-16" ${st('#9AA7B0',4)}/><line x1="-86" y1="-4" x2="-52" y2="-4" ${st('#9AA7B0',4)}/></g>`;
P.e30_loop=(o,T)=>{const a=T*40;const arc=(rot,c)=>`<g transform="rotate(${f(rot)})"><path d="M0 -76 A76 76 0 0 1 76 0" fill="none" ${st(c,18)}/><path d="M52 -14 L78 14 L102 -16Z" fill="${c}" ${st(c,4)}/></g>`;return `<g transform="rotate(${f(a)})">${arc(0,C.gold)}${arc(180,C.blue)}</g>`};
P.e30_improve=(o,T,k)=>{let b='';[.3,.5,.72,.95].forEach((h,i)=>{const g=ease((k-i*.18)/.5)*h;b+=`<rect x="${-96+i*50}" y="${f(80-g*170)}" width="38" height="${f(g*170)}" rx="6" fill="${[C.cold,C.gold,C.orange,C.moss][i]}" ${st(C.navy,4)}/>`});const m=Math.sin(T*3)*5;
  return `<g>${b}<path d="M-100 20 L-40 -20 L10 -2 L88 -86" fill="none" ${st(C.red,9)} transform="translate(0,${f(m*.3)})"/><path d="M62 -92 L92 -92 L92 -62" fill="none" ${st(C.red,9)}/><line x1="-112" y1="84" x2="112" y2="84" ${st(C.navy,6)}/></g>`};
P.e30_present=(o,T)=>{const b=Math.abs(Math.sin(T*3))*8;return `<g><rect x="-80" y="-14" width="160" height="104" rx="8" fill="${C.red}" ${st()}/><rect x="-14" y="-14" width="28" height="104" fill="${C.gold}" ${st()}/><g transform="translate(0,${f(-b)})"><rect x="-92" y="-52" width="184" height="42" rx="8" fill="#E5604D" ${st()}/><rect x="-14" y="-52" width="28" height="42" fill="${C.gold}" ${st()}/><path d="M0 -52 C-44 -112 -76 -64 0 -52 C76 -64 44 -112 0 -52Z" fill="${C.gold}" ${st()}/></g></g>`};
P.e30_plane=(o,T)=>{const fly=o.fly,sw=Math.sin(T*2.2),rot=fly?-10+sw*2:0,by=fly?sw*5:0;let tr='';
  if(fly)for(let i=0;i<3;i++){const ph=(T*1.4+i/3)%1;tr+=`<line x1="${f(-122-ph*60)}" y1="${-18+i*20}" x2="${f(-156-ph*60)}" y2="${-18+i*20}" ${st('#8FB9D0',6)} opacity="${f(1-ph)}"/>`}
  let w='';for(let i=0;i<6;i++)w+=`<circle cx="${-70+i*24}" cy="-10" r="6" fill="${C.sky}" ${st(C.navy,2.5)}/>`;
  return `<g transform="translate(0,${f(by)}) rotate(${f(rot)})">${tr}<path d="M-108 -8 L-134 -66 L-92 -66 L-56 -34Z" fill="${C.red}" ${st()}/><path d="M-14 8 L-70 76 L-30 76 L56 8Z" fill="#B9C6CE" ${st()}/><path d="M-112 -6 Q-112 -34 -80 -36 L70 -36 Q124 -30 124 -2 Q124 20 70 22 L-80 22 Q-112 22 -112 -6Z" fill="${C.white}" ${st()}/><clipPath id="e30pl"><path d="M-112 -6 Q-112 -34 -80 -36 L70 -36 Q124 -30 124 -2 Q124 20 70 22 L-80 22 Q-112 22 -112 -6Z"/></clipPath><rect x="-120" y="6" width="250" height="9" fill="${C.blue}" clip-path="url(#e30pl)"/>${w}<path d="M88 -26 Q112 -24 118 -8 L88 -8Z" fill="${C.sky}" ${st(C.navy,3)}/><ellipse cx="14" cy="34" rx="30" ry="12" fill="#8FA3B0" ${st(C.navy,4)}/></g>`};
P.e30_airport=(o,T)=>{let w='';for(let i=0;i<6;i++)w+=`<rect x="${-100+i*34}" y="22" width="26" height="22" fill="${C.sky}" ${st(C.navy,3)}/>`;const px=((T*40)%300)-170;
  return `<g><rect x="-128" y="84" width="256" height="30" fill="#8FA3B0" ${st()}/><line x1="-110" y1="99" x2="110" y2="99" stroke="#fff" stroke-width="4" stroke-dasharray="18 14"/><rect x="-116" y="14" width="190" height="70" fill="#E7D3A6" ${st()}/><rect x="-124" y="6" width="206" height="12" fill="${C.goldD}" ${st()}/>${w}<rect x="92" y="-70" width="22" height="154" fill="#D9C9A2" ${st()}/><rect x="76" y="-110" width="54" height="44" rx="8" fill="${C.sky}" ${st()}/><rect x="70" y="-70" width="66" height="10" rx="4" fill="${C.navy}"/><g transform="translate(${f(px)},-40) scale(.34)">${P.e30_plane({fly:1},T)}</g></g>`};
/* plane landing on a runway */
P.e30_landing=(o,T)=>{const ph=(T*.3)%1,u=Math.min(1,ph/.7),x=-110+u*190+(ph>.7?(ph-.7)/.3*40:0),y=-70+u*u*118,rot=-(1-u)*2+ (1-u)*14;let dash='';for(let i=0;i<6;i++)dash+=`<rect x="${-110+i*44}" y="96" width="26" height="6" fill="#fff"/>`;
  return `<g><g transform="translate(-76,-78) scale(.4)">${P.sun({},T)}</g><rect x="-126" y="82" width="252" height="40" fill="#6F7C86" ${st()}/>${dash}<g transform="translate(${f(x)},${f(y)}) rotate(${f(rot)}) scale(.5)">${P.e30_plane({},T)}<rect x="-20" y="46" width="8" height="22" fill="${C.navy}"/><circle cx="-16" cy="70" r="11" fill="${C.navy}"/><rect x="40" y="38" width="8" height="30" fill="${C.navy}"/><circle cx="44" cy="70" r="11" fill="${C.navy}"/></g></g>`};
P.e30_modelplane=(o,T)=>{const bob=Math.sin(T*2)*4;return `<g><rect x="-110" y="76" width="220" height="20" rx="8" fill="${C.brown}" ${st()}/><rect x="-44" y="64" width="88" height="14" rx="6" fill="${C.navy2}" ${st()}/><rect x="-6" y="0" width="12" height="66" fill="#B9C6CE" ${st()}/><g transform="translate(0,${f(-30+bob)}) rotate(-12) scale(.62)">${P.e30_plane({},T)}</g></g>`};
P.e30_rolemodel=(o,T)=>{const b=Math.sin(T*3)*5;return `<g><rect x="-50" y="38" width="100" height="78" rx="6" fill="#E7D3A6" ${st()}/><rect x="-62" y="26" width="124" height="16" rx="5" fill="${C.goldD}" ${st()}/><g transform="translate(0,-26) scale(.56)">${P.person({c:'#B07AA1',hair:'bun',hc:'#3A2A22'},T)}</g><g transform="translate(54,${f(-96+b)}) scale(.26)">${P.star({},T)}</g><g transform="translate(-100,80) scale(.3)">${P.person({c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g><g transform="translate(100,80) scale(.3)">${P.person({c:'#D96C8B',hair:'long',hc:'#3A2A22'},T)}</g></g>`};
P.e30_finish=(o,T)=>{const w=Math.sin(T*4)*4;let ck='';for(let r=0;r<4;r++)for(let c=0;c<5;c++)ck+=`<rect x="${-4+c*24}" y="${-108+r*20+Math.sin(T*4+c)*2}" width="24" height="20" fill="${(r+c)%2?C.navy:C.white}"/>`;
  return `<g><line x1="-8" y1="-122" x2="-8" y2="108" ${st(C.navy,9)}/><g transform="translate(${f(w*.2)},0)">${ck}<rect x="-4" y="-108" width="120" height="80" fill="none" ${st(C.navy,4)}/></g><ellipse cx="-8" cy="112" rx="40" ry="10" fill="${C.navy2}" ${st(C.navy,3)}/></g>`};
P.e30_target=(o,T)=>{const ph=(T*.6)%1,ax=ph<.4?ease(ph/.4):1;return `<g><circle r="96" fill="${C.white}" ${st()}/><circle r="70" fill="${C.red}" ${st(C.navy,4)}/><circle r="44" fill="${C.white}" ${st(C.navy,4)}/><circle r="20" fill="${C.red}" ${st(C.navy,4)}/><g transform="translate(${f(120-ax*120)},${f(-110+ax*110)})"><line x1="0" y1="0" x2="${f(52)}" y2="${f(-52)}" ${st(C.brown,7)}/><path d="M52 -52 l16 -4 l-4 -12 l-16 4Z M40 -40 l-10 -2 l2 -12Z" fill="${C.gold}" ${st(C.navy,3)}/></g></g>`};
P.e30_future=(o,T)=>{let d='';for(let i=0;i<4;i++){const ph=(T*.6+i/4)%1,y=-10+ph*120,w=3+ph*10;d+=`<rect x="${-w/2}" y="${f(y)}" width="${f(w)}" height="${f(6+ph*22)}" fill="#fff"/>`}
  let r='';for(let i=0;i<10;i++)r+=`<line x1="0" y1="-26" x2="0" y2="-50" transform="translate(0,-20) rotate(${i*36+T*12})" ${st('#C9971F',5)} opacity=".8"/>`;
  return `<g><clipPath id="e30fu"><rect x="-112" y="-120" width="224" height="244" rx="22"/></clipPath><g clip-path="url(#e30fu)"><rect x="-112" y="-120" width="224" height="244" fill="url(#gSky)"/><g transform="translate(0,-8)">${r}<circle cy="-20" r="34" fill="#F6CE4B" ${st('#C9971F',5)}/></g><path d="M-112 6 Q-60 -34 -10 6 T112 -4 V130 H-112Z" fill="${C.leaf}" ${st()}/><path d="M-12 6 L12 6 L96 130 L-96 130Z" fill="#8A949C"/>${d}</g><rect x="-112" y="-120" width="224" height="244" rx="22" fill="none" ${st()}/></g>`};
P.e30_minutes=(o,T)=>{const n=o.n||20,a=n*6,ex=Math.sin(a*Math.PI/180)*96,ey=-Math.cos(a*Math.PI/180)*96;let t='';for(let i=0;i<12;i++)t+=`<line x1="0" y1="-92" x2="0" y2="${i%3?-82:-72}" transform="rotate(${i*30})" ${st(C.navy,4)}/>`;
  return `<g><g transform="translate(0,-14) scale(.84)"><circle r="104" fill="${C.cream}" ${st(C.navy,6)}/><path d="M0 0 L0 -96 A96 96 0 ${a>180?1:0} 1 ${f(ex)} ${f(ey)}Z" fill="${C.gold}" opacity=".9"/>${t}<line x1="0" y1="0" x2="0" y2="-80" ${st(C.navy,6)}/><line x1="0" y1="0" x2="${f(ex*.8)}" y2="${f(ey*.8)}" ${st(C.navy,5)}/><circle r="8" fill="${C.navy}"/></g><g transform="translate(0,102)"><rect x="-58" y="-26" width="116" height="42" rx="21" fill="${C.navy}" ${st()}/><text y="8" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" fill="${C.cream}">${n} min</text></g></g>`};
P.e30_week=(o,T)=>{const L=['S','M','T','W','T','F','S'],on=o.days||[1,3,5];let b='';L.forEach((l,i)=>{const h=on.includes(i);b+=`<g transform="translate(${-108+i*36},0) scale(${f(h?1+.06*Math.sin(T*5):1)})"><rect x="-14" y="-32" width="28" height="64" rx="8" fill="${h?C.gold:C.white}" ${st()}/><text y="9" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="${C.navy}">${l}</text></g>`});return `<g><rect x="-136" y="-60" width="272" height="120" rx="18" fill="${C.cream}" ${st()}/>${b}</g>`};
P.e30_num=(o,T)=>{const s=String(o.n),fs=s.length>=3?64:s.length==2?84:112;return `<g transform="scale(${f(1+.04*Math.sin(T*4))})"><circle r="84" fill="${C.gold}" ${st()}/><circle r="68" fill="none" ${st(C.goldD,3)}/><text x="0" y="${f(fs*.36)}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${fs}" fill="${C.navy}">${s}</text></g>`};
P.e30_lines=(o,T,k)=>{const n=o.n||1;let s='';for(let i=0;i<n;i++){const pp=ease((k-i*.3)/.4);s+=`<line x1="-66" y1="${-86+i*26}" x2="${f(-66+(130-(i%3)*26)*pp)}" y2="${-86+i*26}" ${st(C.navy2,6)}/>`}return `<g><rect x="-86" y="-120" width="172" height="240" rx="10" fill="${C.cream}" ${st()}/>${s}<g transform="translate(60,84) rotate(40)">${_e30pencil(0)}</g></g>`};
P.e30_start=(o,T)=>{const p=1+.06*Math.sin(T*4);return `<g transform="scale(${f(p)})"><circle r="92" fill="${C.moss}" ${st()}/><path d="M-30 -52 L56 0 L-30 52Z" fill="#fff" ${st('#fff',8)}/></g>`};
P.e30_timeline=(o,T)=>{const e=o.at==='end',x=e?100:-100;return `<g><line x1="-112" y1="0" x2="112" y2="0" ${st(C.navy,10)}/><circle cx="-100" cy="0" r="14" fill="${e?C.white:C.gold}" ${st()}/><circle cx="100" cy="0" r="14" fill="${e?C.gold:C.white}" ${st()}/><g transform="translate(${x},${f(-50+Math.sin(T*4)*5)})"><path d="M0 28 L-26 -10 A32 32 0 1 1 26 -10Z" fill="${C.red}" ${st()}/><circle cy="-22" r="10" fill="#fff"/></g></g>`};
P.e30_beach=(o,T)=>{const sw=Math.sin(T*1.6)*3;let lv='';for(let i=0;i<5;i++){const a=(-150+i*34)*Math.PI/180,ex=Math.cos(a)*84,ey=-70+Math.sin(a)*60+16+sw,cx=Math.cos(a)*50,cy=-70+Math.sin(a)*44-10;lv+=`<path d="M0 -70 Q${f(cx)} ${f(cy)} ${f(ex)} ${f(ey)}" fill="none" ${st(C.navy,16)}/><path d="M0 -70 Q${f(cx)} ${f(cy)} ${f(ex)} ${f(ey)}" fill="none" ${st(C.leaf,10)}/>`}
  return `<g><g transform="translate(70,-70) scale(.5)">${P.sun({},T)}</g><path d="M-124 70 Q-40 40 0 62 T124 54 V108 H-124Z" fill="${C.blue}" ${st()}/><path d="M-14 100 Q-4 20 -2 -70" fill="none" ${st(C.navy,22)}/><path d="M-14 100 Q-4 20 -2 -70" fill="none" ${st(C.brown,14)}/><g transform="translate(-2,0)">${lv}</g></g>`};
P.e30_afraid=(o,T)=>{const sh=Math.sin(T*38)*2.6,ph=(T*.9)%1;return `<g><g transform="translate(${f(sh)},24) scale(.85)">${P.person({c:o.c||'#4DA3D8',hair:o.hair||'short',hc:o.hc||'#222'},T)}</g><path d="M70 ${f(-56+ph*14)} C82 -38 90 -28 90 -16 a20 20 0 0 1 -40 0 C50 -28 58 -38 70 -56Z" fill="${C.blue}" ${st(C.navy,4)} transform="translate(0,${f(ph*8)})"/><path d="M-72 -56 l-22 -12 M-76 -30 l-26 0 M-72 -4 l-22 12" ${st(C.navy,5)} fill="none" opacity="${f(.5+.5*Math.sin(T*20))}"/></g>`};
P.e30_case=(o,T)=>`<g><path d="M-30 -66 V-90 Q-30 -104 -16 -104 H16 Q30 -104 30 -90 V-66" fill="none" ${st(C.navy,9)}/><rect x="-96" y="-68" width="192" height="148" rx="20" fill="${C.orange}" ${st()}/><rect x="-96" y="-8" width="192" height="12" fill="#C9651B"/><rect x="-14" y="-18" width="28" height="30" rx="6" fill="${C.gold}" ${st(C.navy,3.5)}/><circle cx="-60" cy="92" r="9" fill="${C.navy}"/><circle cx="60" cy="92" r="9" fill="${C.navy}"/></g>`;
/* hero: notebook with plans being ticked, pencil writing, rising star */
P.e30_hero=(o,T)=>{const cyc=(T%5)/5,n=Math.floor(cyc*4);let r='';for(let i=0;i<3;i++){const y=-52+i*46,on=i<n||(i===n&&((T*5)%1)>.5)&&false;const tick=i<Math.min(3,Math.floor(cyc*4.2));r+=`<rect x="-64" y="${y-14}" width="28" height="28" rx="6" fill="${C.white}" ${st(C.navy,4)}/><line x1="-22" y1="${y}" x2="${[66,50,70][i]}" y2="${y}" ${st('#9AA7B0',6)}/>${tick?_e30check(-50,y,1.3):''}`}
  let rings='';for(let i=0;i<6;i++)rings+=`<rect x="${-78+i*31}" y="-136" width="13" height="28" rx="6" fill="#B9C6CE" ${st(C.navy,3.5)}/>`;
  const wx=Math.sin(T*5)*8;
  return `<g><g transform="rotate(-4)"><rect x="-100" y="-120" width="200" height="248" rx="16" fill="${C.paper}" ${st()}/><rect x="-100" y="-120" width="200" height="30" rx="14" fill="${C.blue}" ${st()}/>${rings}${r}</g><g transform="translate(${f(62+wx)},${f(78+Math.sin(T*10)*3)})">${_e30pencil(40)}</g><g transform="translate(${f(92+Math.sin(T*2)*4)},${f(-98+Math.sin(T*3)*6)}) scale(.32)">${P.star({},T)}</g></g>`};

/* Episode 31 props: big family party, graduation, geography, flowers, painting, pencil, cinema, theatre, actors. All faceless. Uses C, st, f, ease, clamp, blob, P. */
const _e31ink='#1E2B33';
const _e31bl=(x,y,r,col,T,i)=>{const s=1+.05*Math.sin((T||0)*2.4+(i||0));let c=[];for(let k=0;k<6;k++)c.push([Math.cos(k*1.047)*r*.62,Math.sin(k*1.047)*r*.62,r*.46]);
  return `<g transform="translate(${f(x)},${f(y)}) scale(${f(s)})">${blob(c,col,Math.max(2.5,r*.12))}<circle r="${f(r*.34)}" fill="${col==='#fff'?'#F6CE4B':'#E58A2F'}" ${st(_e31ink,Math.max(2,r*.08))}/></g>`};
const _e31balloon=(x,y,col,T,i)=>{const b=Math.sin(T*1.7+i)*5;return `<g transform="translate(${f(x+b*.6)},${f(y+b)})"><path d="M0 24 q-6 30 4 54" fill="none" ${st(_e31ink,2.5)}/><ellipse cx="0" cy="0" rx="21" ry="27" fill="${col}" ${st()}/><polygon points="0,26 -6,34 6,34" fill="${col}" ${st(_e31ink,3)}/><ellipse cx="-7" cy="-9" rx="4" ry="8" fill="#fff" opacity=".55"/></g>`};
const _e31confetti=(T,n,w,h)=>{let s='';const cs=['#F2994A','#4DA3D8','#D9534F','#F6CE4B','#5E9B63','#D96C8B'];for(let i=0;i<n;i++){const x=-w+((i*67)%(2*w))+Math.sin(T*2+i)*6,y=-h+((T*50+i*43)%(2*h));s+=`<rect x="${f(x)}" y="${f(y)}" width="8" height="5" fill="${cs[i%6]}" transform="rotate(${f(T*140+i*40)} ${f(x)} ${f(y)})" opacity=".9"/>`}return s};
const _e31bunting=(y0,w,T)=>{let s=`<path d="M${-w} ${y0} Q0 ${y0+34} ${w} ${y0}" fill="none" ${st(_e31ink,4)}/>`;const cs=['#D9534F','#F6CE4B','#4DA3D8','#5E9B63','#F2994A'];for(let i=0;i<9;i++){const t=(i+.5)/9,x=-w+2*w*t,y=y0+34*2*t*(1-t)+2,sw=Math.sin(T*2+i)*2;s+=`<polygon points="${f(x-12)},${f(y)} ${f(x+12)},${f(y)} ${f(x+sw)},${f(y+26)}" fill="${cs[i%5]}" ${st(_e31ink,3)}/>`}return s};
const _e31ppl=(x,base,s,o,T)=>`<g transform="translate(${f(x)},${f(base-108*s)}) scale(${f(s)})">${P.person(o,T)}</g>`;
const _e31GRAN={c:'#B07AA1',hair:'bun',hc:'#D5D8DB'},_e31DAD={c:'#4DA3D8',hair:'short',hc:'#222'},_e31MUM={c:'#D96C8B',hair:'long',hc:'#3A2A22'},_e31BOY={c:'#F2994A',hair:'short',hc:'#3A2A22'},_e31GIRL={c:'#4F7A5A',hair:'long',hc:'#F2D16B'},_e31UNC={c:'#8E6BB5',hair:'short',hc:'#6A3F26'};

/* ---------- hero: a big family party ---------- */
P.e31_hero=(o,T)=>{const b=(i)=>Math.sin(T*3+i)*2;
  return `<g>${_e31bunting(-112,118,T)}${_e31balloon(-106,-30,'#D9534F',T,0)}${_e31balloon(106,-32,'#4DA3D8',T,1.7)}${_e31balloon(-66,-22,'#F6CE4B',T,3)}${_e31balloon(68,-24,'#5E9B63',T,4.4)}
  ${_e31ppl(-92,116,.38,{..._e31GIRL,ph:5},T)}${_e31ppl(-46,116,.54,{..._e31UNC,ph:1},T)}${_e31ppl(2,116,.5,{..._e31GRAN,ph:3},T)}${_e31ppl(50,116,.56,{..._e31MUM,ph:4},T)}${_e31ppl(94,116,.4,{..._e31BOY,ph:2},T)}
  <g transform="translate(0,${f(-50+b(0))})"><polygon points="0,-22 6,-8 22,-6 10,4 14,20 0,12 -14,20 -10,4 -22,-6 -6,-8" fill="${C.gold}" ${st(C.goldD,3)}/></g>${_e31confetti(T,16,115,110)}</g>`};

/* ---------- party (decor only) ---------- */
P.e31_party=(o,T)=>`<g>${_e31bunting(-96,118,T)}${_e31balloon(-80,-20,'#D9534F',T,0)}${_e31balloon(0,-30,'#F6CE4B',T,2)}${_e31balloon(80,-20,'#4DA3D8',T,4)}${_e31balloon(-40,20,'#5E9B63',T,6)}${_e31balloon(42,24,'#F2994A',T,8)}${_e31confetti(T,18,115,110)}</g>`;

/* ---------- graduation: cap and diploma ---------- */
P.e31_grad=(o,T)=>{const tw=Math.sin(T*3)*5,fl=Math.sin(T*1.6)*3;
  return `<g transform="translate(0,${f(fl)})"><path d="M-62 -4 V38 Q0 70 62 38 V-4 Z" fill="#2B3D48" ${st()}/><polygon points="0,-62 -122,-14 0,34 122,-14" fill="#1E2B33" ${st()}/><polygon points="0,-52 -100,-14 0,26 100,-14" fill="#2B3D48"/><path d="M0 -14 L96 -2 V${f(50+tw)}" fill="none" ${st(C.gold,6)}/><circle cx="96" cy="${f(54+tw)}" r="8" fill="${C.gold}" ${st(C.goldD,3)}/><path d="M96 56 v22" ${st(C.gold,6)}/><circle cx="0" cy="-14" r="8" fill="${C.gold}" ${st(C.goldD,3)}/>
  <g transform="translate(-12,70) rotate(-12)"><rect x="-70" y="-14" width="140" height="28" rx="14" fill="#F4EFE0" ${st()}/><rect x="-6" y="-14" width="12" height="28" fill="#D9534F" ${st(_e31ink,3)}/></g></g>`};

/* ---------- map, river, weather, sea ---------- */
P.e31_map=(o,T)=>{const pin=(x,y,i)=>`<g transform="translate(${x},${f(y-Math.abs(Math.sin(T*2.4+i))*5)})"><path d="M0 0 C-12 -16 -12 -30 0 -30 C12 -30 12 -16 0 0Z" fill="${C.red}" ${st(_e31ink,3)}/><circle cx="0" cy="-22" r="4" fill="#fff"/></g>`;
  return `<g><rect x="-122" y="-90" width="244" height="180" rx="10" fill="${C.brown}" ${st()}/><rect x="-108" y="-76" width="216" height="152" fill="#8FD0EA" ${st(_e31ink,3)}/><clipPath id="e31mc"><rect x="-108" y="-76" width="216" height="152"/></clipPath><g clip-path="url(#e31mc)"><path d="M-96 -44 Q-70 -70 -34 -56 Q-12 -40 -22 -10 Q-6 18 -30 34 Q-56 50 -70 20 Q-92 8 -96 -44Z" fill="#8CC17A" ${st(_e31ink,3)}/><path d="M18 -62 Q60 -72 90 -48 Q104 -20 84 -4 Q86 24 58 30 Q32 22 40 -4 Q8 -26 18 -62Z" fill="#D9C27A" ${st(_e31ink,3)}/><path d="M-6 44 Q30 36 56 52 Q50 74 10 74 Q-20 66 -6 44Z" fill="#8CC17A" ${st(_e31ink,3)}/><path d="M-76 -40 q14 10 6 24 t18 22 t0 22" fill="none" ${st('#4DA3D8',4)}/><polygon points="52,-30 66,-52 80,-30" fill="#8FA3B0" ${st(_e31ink,3)}/></g>${pin(-46,-12,0)}${pin(64,10,1.3)}${pin(20,56,2.6)}</g>`};
P.e31_river=(o,T)=>{const dx=(T*30)%40;let w='';for(let i=0;i<4;i++)w+=`<path d="M${-30+i*8} ${-60+i*40} q16 8 28 0" fill="none" ${st('#fff',3)} opacity=".6"/>`;
  return `<g><clipPath id="e31rc"><rect x="-122" y="-100" width="244" height="200" rx="14"/></clipPath><g clip-path="url(#e31rc)"><rect x="-122" y="-100" width="244" height="200" fill="${C.sky}"/><polygon points="-122,-6 -66,-76 -8,-6" fill="#8FA3B0" ${st()}/><polygon points="-30,-6 40,-90 122,-6" fill="#A9BAC4" ${st()}/><rect x="-122" y="-6" width="244" height="106" fill="#8CC17A"/><path d="M-30 -6 C-60 20 40 40 -10 62 C-50 82 30 90 10 104 L70 104 C80 90 20 80 50 60 C90 40 -10 20 20 -6Z" fill="#4DA3D8" ${st(_e31ink,3)}/>${w}<g transform="translate(-92,40) scale(.36)">${P.tree({},T)}</g><g transform="translate(96,50) scale(.3)">${P.tree({},T)}</g></g><rect x="-122" y="-100" width="244" height="200" rx="14" fill="none" ${st()}/></g>`};
P.e31_weather=(o,T)=>`<g><g transform="translate(-44,-40) scale(.66)">${P.sun({},T)}</g><g transform="translate(30,-4) scale(.95)">${P.rain({},T)}</g></g>`;
P.e31_sea=(o,T)=>{let w='';for(let r=0;r<3;r++){let d=`M-130 ${16+r*34}`;for(let i=0;i<6;i++)d+=` q11 -12 22 0 t22 0`;w+=`<path d="${d}" fill="none" ${st(r?'#fff':'#BFE3F2',5)} opacity="${r?.7:1}" transform="translate(${f(Math.sin(T*1.2+r)*8)},0)"/>`}
  return `<g><clipPath id="e31sc"><rect x="-130" y="-100" width="260" height="200" rx="14"/></clipPath><g clip-path="url(#e31sc)"><rect x="-130" y="-100" width="260" height="104" fill="${C.sky}"/><g transform="translate(60,-50) scale(.5)">${P.sun({},T)}</g><rect x="-130" y="0" width="260" height="100" fill="${C.blue}"/>${w}</g><rect x="-130" y="-100" width="260" height="200" rx="14" fill="none" ${st()}/></g>`};
P.e31_wallmap=(o,T)=>`<g><rect x="-122" y="-110" width="244" height="220" rx="10" fill="#F4E5C2" ${st()}/><g transform="translate(0,-34) scale(.74)">${P.e31_map({},T)}</g><g transform="translate(10,62) scale(.6)">${P.bed({},T)}</g></g>`;

/* ---------- science ---------- */
P.e31_flask=(o,T)=>{let b='';for(let i=0;i<4;i++){const ph=(T*.7+i/4)%1;b+=`<circle cx="${f(-16+i*11+Math.sin(T*3+i)*3)}" cy="${f(40-ph*84)}" r="${4+i%2*2}" fill="#fff" opacity="${f(.85-ph*.6)}"/>`}
  return `<g><clipPath id="e31fc"><path d="M-14 -90 V-44 L-62 66 Q-68 90 -44 90 H44 Q68 90 62 66 L14 -44 V-90Z"/></clipPath><path d="M-14 -90 V-44 L-62 66 Q-68 90 -44 90 H44 Q68 90 62 66 L14 -44 V-90Z" fill="#EAF6FB" ${st()}/><g clip-path="url(#e31fc)"><path d="M-80 ${f(14+Math.sin(T*2)*2)} H80 V100 H-80Z" fill="#5FCB8A"/>${b}</g><path d="M-14 -90 V-44 L-62 66 Q-68 90 -44 90 H44 Q68 90 62 66 L14 -44 V-90Z" fill="none" ${st()}/><rect x="-22" y="-100" width="44" height="14" rx="6" fill="#EAF6FB" ${st()}/></g>`};
P.e31_scientist=(o,T)=>`<g><g transform="translate(-26,-6) scale(.98)">${P.person({c:'#F4F7F9',hair:o.hair||'long',hc:o.hc||'#3A2A22',ph:1},T)}<rect x="-40" y="26" width="26" height="34" rx="4" fill="#fff" ${st(_e31ink,3)}/><rect x="-33" y="20" width="4" height="16" fill="${C.blue}"/></g><g transform="translate(78,44) scale(.62)">${P.e31_flask({},T)}</g></g>`;
P.e31_doctor=(o,T)=>`<g><g transform="translate(0,6)">${P.person({c:'#F4F7F9',hair:'short',hc:'#222'},T)}<rect x="-40" y="30" width="30" height="30" rx="4" fill="#fff" ${st(_e31ink,3)}/><path d="M-25 36 v18 M-34 45 h18" ${st(C.red,6)}/></g></g>`;

/* ---------- family ---------- */
P.e31_family=(o,T)=>`<g>${_e31ppl(-100,100,.42,{..._e31UNC,ph:1},T)}${_e31ppl(-52,100,.34,{..._e31BOY,ph:2},T)}${_e31ppl(-4,100,.46,{..._e31GRAN,ph:3},T)}${_e31ppl(44,100,.4,{..._e31MUM,ph:4},T)}${_e31ppl(94,100,.34,{..._e31GIRL,ph:5},T)}<g transform="translate(0,${f(-52+Math.sin(T*3)*3)}) scale(1.1)"><path d="${heartPath}" fill="${C.red}" ${st()}/></g></g>`;

/* ---------- rooms ---------- */
const _e31sofa=(x,y,s,col)=>`<g transform="translate(${x},${y}) scale(${s})"><rect x="-96" y="-54" width="192" height="64" rx="18" fill="${col}" ${st()}/><rect x="-112" y="-14" width="36" height="76" rx="14" fill="${col}" ${st()}/><rect x="76" y="-14" width="36" height="76" rx="14" fill="${col}" ${st()}/><rect x="-80" y="-6" width="160" height="56" rx="12" fill="${col}" ${st()}/><line x1="0" y1="-4" x2="0" y2="50" ${st(_e31ink,3)}/><rect x="-90" y="62" width="10" height="16" fill="${C.brown}"/><rect x="80" y="62" width="10" height="16" fill="${C.brown}"/></g>`;
P.e31_livingroom=(o,T)=>`<g><rect x="-122" y="-100" width="244" height="200" rx="12" fill="#F4E5C2" ${st()}/><rect x="-122" y="46" width="244" height="54" fill="#C9A06A"/><rect x="-122" y="-100" width="244" height="200" rx="12" fill="none" ${st()}/><rect x="-100" y="-80" width="64" height="62" fill="${C.sky}" ${st(_e31ink,4)}/><line x1="-68" y1="-80" x2="-68" y2="-18" ${st(_e31ink,3)}/>${_e31sofa(16,24,.78,'#5E8BA8')}<g transform="translate(98,-6)"><line x1="0" y1="-50" x2="0" y2="64" ${st(_e31ink,5)}/><path d="M-22 -26 L-12 -64 H12 L22 -26Z" fill="#FFE08A" ${st(_e31ink,4)}/><ellipse cx="0" cy="66" rx="18" ry="6" fill="${_e31ink}"/></g></g>`;
P.e31_kitchen=(o,T)=>{let s='';for(let i=0;i<3;i++){const ph=(T*.8+i/3)%1;s+=`<path d="M${-22+i*22} ${f(-30-ph*44)} q-8 -12 0 -22 t0 -22" fill="none" ${st('#9AA7B0',5)} opacity="${f(1-ph)}"/>`}
  return `<g><rect x="-122" y="-100" width="244" height="200" rx="12" fill="#EAF2F6" ${st()}/><rect x="-108" y="-86" width="216" height="46" rx="6" fill="${C.brown}" ${st()}/><line x1="0" y1="-86" x2="0" y2="-40" ${st(_e31ink,3)}/><circle cx="-10" cy="-62" r="4" fill="${C.gold}"/><circle cx="10" cy="-62" r="4" fill="${C.gold}"/><rect x="-122" y="30" width="244" height="70" fill="#B98B5E" ${st()}/><rect x="-122" y="20" width="244" height="14" fill="#9FB0BA" ${st()}/>${s}<rect x="-52" y="-22" width="104" height="44" rx="8" fill="#7C8D98" ${st()}/><ellipse cx="0" cy="-22" rx="56" ry="9" fill="#5C6B75" ${st()}/><path d="M-56 -22 q-24 -6 -24 8" fill="none" ${st(_e31ink,6)}/><path d="M56 -22 q24 -6 24 8" fill="none" ${st(_e31ink,6)}/><line x1="-30" y1="50" x2="-30" y2="86" ${st(_e31ink,3)}/><line x1="30" y1="50" x2="30" y2="86" ${st(_e31ink,3)}/></g>`};
P.e31_garden=(o,T)=>`<g><clipPath id="e31gc"><rect x="-122" y="-100" width="244" height="200" rx="14"/></clipPath><g clip-path="url(#e31gc)"><rect x="-122" y="-100" width="244" height="200" fill="${C.sky}"/><g transform="translate(78,-60) scale(.42)">${P.sun({},T)}</g><path d="M-122 20 Q0 -10 122 20 V100 H-122Z" fill="#8CC17A" ${st()}/><g transform="translate(-76,30) scale(.5)">${P.tree({},T)}</g><g stroke="${_e31ink}" stroke-width="4"><line x1="14" y1="4" x2="14" y2="34"/><line x1="44" y1="2" x2="44" y2="34"/><line x1="74" y1="6" x2="74" y2="38"/><line x1="8" y1="14" x2="86" y2="16"/></g>${[[-30,62,'#fff'],[10,76,'#F6CE4B'],[52,62,'#fff'],[88,78,'#F6CE4B'],[-62,82,'#F6CE4B']].map(([x,y,c],i)=>`<line x1="${x}" y1="${y}" x2="${x}" y2="${y+24}" ${st(C.leaf,4)}/>${_e31bl(x,y,15,c,T,i)}`).join('')}</g><rect x="-122" y="-100" width="244" height="200" rx="14" fill="none" ${st()}/></g>`;
const _e31sit=(x,s,o,T)=>`<g transform="translate(${x},0) scale(${s})"><ellipse cx="0" cy="92" rx="76" ry="26" fill="${o.p||'#4F5B66'}" ${st()}/><g transform="translate(0,-14)">${P.person(o,T)}</g><ellipse cx="0" cy="96" rx="64" ry="18" fill="${o.p||'#4F5B66'}" ${st()}/></g>`;
P.e31_floor=(o,T)=>`<g><ellipse cx="0" cy="84" rx="132" ry="34" fill="#D96C8B" ${st()}/><ellipse cx="0" cy="84" rx="100" ry="22" fill="none" ${st('#F4E5C2',4)}/>${_e31sit(-62,.62,{..._e31GRAN,ph:1},T).replace(/translate\(-62,0\)/,'translate(-62,-6)')}${_e31sit(62,.62,{..._e31BOY,ph:2,p:'#2B3D48'},T).replace(/translate\(62,0\)/,'translate(62,-6)')}</g>`;

/* ---------- flowers ---------- */
P.e31_flower=(o,T)=>{const c=o.c||'#fff';const sw=Math.sin(T*1.6)*3;return `<g transform="rotate(${f(sw)} 0 100)"><path d="M0 100 V-4" ${st(C.leaf,9)}/><path d="M0 60 Q-44 40 -52 70 Q-20 82 0 60Z" fill="${C.leaf}" ${st()}/><path d="M0 40 Q40 14 52 40 Q22 56 0 40Z" fill="${C.leaf}" ${st()}/>${_e31bl(0,-34,56,c,T,0)}</g>`};
P.e31_bouquet=(o,T)=>{const hd=[[-54,-52,'#fff'],[0,-76,'#F6CE4B'],[54,-52,'#fff'],[-26,-14,'#F6CE4B'],[28,-12,'#fff']];let s='';hd.forEach(([x,y],i)=>{s+=`<path d="M0 50 Q${x*.4} ${(50+y)/2} ${x} ${y}" fill="none" ${st(C.leaf,6)}/>`});
  const paper=o.paper?`<path d="M-66 -2 L66 -2 L24 108 L-24 108Z" fill="#E7D3A6" ${st()}/><path d="M-66 -2 L0 34 L66 -2" fill="#F4E5C2" ${st()}/><path d="M-12 62 L0 74 L12 62 L24 74 L0 84 L-24 74Z" fill="${C.red}" ${st(_e31ink,3)}/>`:`<rect x="-14" y="46" width="28" height="12" rx="4" fill="${C.red}" ${st(_e31ink,3)}/><path d="M0 58 V104" ${st(C.leaf,8)}/>`;
  return `<g transform="rotate(${f(Math.sin(T*1.5)*2)} 0 100)">${s}${paper}${hd.map(([x,y,c],i)=>_e31bl(x,y,30,c,T,i)).join('')}</g>`};
P.e31_flowershop=(o,T)=>{let aw='';for(let i=0;i<6;i++)aw+=`<path d="M${-96+i*32} -30 h32 v24 q-16 14 -32 0Z" fill="${i%2?'#fff':'#D96C8B'}" ${st(_e31ink,3)}/>`;
  const bucket=(x,cs)=>`<g transform="translate(${x},62)"><path d="M-22 0 H22 L16 38 H-16Z" fill="#7C8D98" ${st(_e31ink,4)}/>${cs.map(([dx,dy,c],i)=>`<line x1="${dx}" y1="${dy}" x2="${dx*.4}" y2="2" ${st(C.leaf,3)}/>${_e31bl(dx,dy,11,c,T,i)}`).join('')}</g>`;
  return `<g><rect x="-100" y="-86" width="200" height="40" rx="8" fill="${C.moss}" ${st()}/><text x="0" y="-57" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="26" fill="${C.cream}" letter-spacing="4">FLOWERS</text>${aw}<rect x="-94" y="-6" width="188" height="108" fill="#F4E5C2" ${st()}/><rect x="-8" y="10" width="44" height="92" fill="${C.brown}" ${st()}/><rect x="-84" y="8" width="62" height="50" fill="${C.sky}" ${st(_e31ink,3)}/>${bucket(-60,[[-10,36,'#fff'],[10,32,'#F6CE4B']])}${bucket(66,[[-10,34,'#F6CE4B'],[10,36,'#fff']])}</g>`};

/* ---------- food ---------- */
P.e31_chickenrice=(o,T)=>{let s='';for(let i=0;i<3;i++){const ph=(T*.8+i/3)%1;s+=`<path d="M${-30+i*30} ${f(-34-ph*44)} q-9 -12 0 -24 t0 -24" fill="none" ${st('#9AA7B0',5)} opacity="${f(1-ph)}"/>`}
  const leg=(x,y,r)=>`<g transform="translate(${x},${y}) rotate(${r})"><path d="M-30 -12 Q-30 -34 0 -34 Q32 -34 32 -6 Q30 18 -8 18 Q-30 16 -30 -12Z" fill="#C97B3A" ${st()}/><rect x="26" y="-12" width="40" height="12" rx="6" fill="#F4EFE0" ${st(_e31ink,4)} transform="rotate(14 30 -6)"/><circle cx="68" cy="-4" r="9" fill="#F4EFE0" ${st(_e31ink,4)}/><circle cx="74" cy="6" r="9" fill="#F4EFE0" ${st(_e31ink,4)}/></g>`;
  return `<g>${s}<ellipse cx="0" cy="62" rx="122" ry="34" fill="#fff" ${st()}/><ellipse cx="0" cy="58" rx="92" ry="22" fill="#F4EFE0" ${st(_e31ink,3)}/><path d="M-76 56 Q-62 -20 -10 -22 Q40 -20 50 56Z" fill="#fff" ${st()}/>${[[-40,30],[-16,6],[4,36],[24,12],[-4,-8],[36,40],[-30,50]].map(([x,y])=>`<ellipse cx="${x}" cy="${y}" rx="7" ry="3" fill="#E9DFC8" transform="rotate(${x*3} ${x} ${y})"/>`).join('')}${leg(36,22,-6)}</g>`};
P.e31_chicken=(o,T)=>`<g transform="rotate(${f(-20+Math.sin(T*2)*3)})"><path d="M-62 -24 Q-62 -76 0 -76 Q66 -76 66 -14 Q60 38 -14 38 Q-62 34 -62 -24Z" fill="#C97B3A" ${st()}/><path d="M-30 -48 q22 -14 50 -6" fill="none" stroke="#E6A15F" stroke-width="8" stroke-linecap="round"/><rect x="48" y="-24" width="72" height="20" rx="10" fill="#F4EFE0" ${st()} transform="rotate(18 52 -14)"/><circle cx="118" cy="14" r="14" fill="#F4EFE0" ${st()}/><circle cx="104" cy="32" r="14" fill="#F4EFE0" ${st()}/></g>`;
P.e31_popcorn=(o,T)=>{let p='';[[-36,-62],[0,-76],[36,-62],[-18,-48],[20,-50],[-50,-40],[52,-40]].forEach(([x,y],i)=>{p+=`<circle cx="${x}" cy="${f(y+Math.sin(T*2+i)*2)}" r="20" fill="#FFF6D8" ${st()}/>`});let st2='';for(let i=0;i<5;i++)st2+=`<path d="M${-58+i*29} -30 L${-50+i*25} 96 L${-30+i*25} 96 L${-29+i*29} -30Z" fill="${i%2?'#fff':C.red}"/>`;
  return `<g>${p}<path d="M-64 -34 L-46 100 H46 L64 -34Z" fill="#fff" ${st()}/><clipPath id="e31pc"><path d="M-62 -32 L-45 98 H45 L62 -32Z"/></clipPath><g clip-path="url(#e31pc)">${[0,1,2,3].map(i=>`<polygon points="${-62+i*31},-32 ${-31+i*31},-32 ${-22+i*22},98 ${-45+i*22+ (i? -0:0)},98" fill="${C.red}" opacity="${i%2?0:1}"/>`).join('')}</g><path d="M-64 -34 L-46 100 H46 L64 -34Z" fill="none" ${st()}/></g>`};

/* ---------- painting, pencil, pen, eraser ---------- */
const _e31scene=(T)=>`<rect x="-70" y="-52" width="140" height="104" fill="${C.sky}"/><rect x="-70" y="12" width="140" height="40" fill="#8CC17A"/><circle cx="46" cy="-30" r="12" fill="#F6CE4B"/><path d="M-28 6 L-40 46 H-4 L-16 6Z" fill="#D96C8B"/><circle cx="-22" cy="-6" r="10" fill="#E3AE82"/><path d="M-32 -10 Q-22 -26 -12 -10 Q-22 -16 -32 -10Z" fill="#3A2A22"/>${[[-58,34,'#fff'],[14,40,'#F6CE4B'],[34,26,'#fff'],[52,42,'#F6CE4B'],[-50,18,'#F6CE4B']].map(([x,y,c],i)=>`<line x1="${x}" y1="${y}" x2="${x}" y2="${y+14}" stroke="${C.leaf}" stroke-width="2.5"/><circle cx="${x}" cy="${y}" r="7" fill="${c}" stroke="#555" stroke-width="1.5"/>`).join('')}`;
P.e31_painting=(o,T)=>`<g transform="rotate(${f(Math.sin(T*1.4)*1.5)})"><clipPath id="e31pic"><rect x="-70" y="-52" width="140" height="104"/></clipPath><rect x="-100" y="-80" width="200" height="160" rx="8" fill="${C.brown}" ${st()}/><rect x="-86" y="-66" width="172" height="132" fill="#F4EFE0" ${st(_e31ink,3)}/><g transform="scale(1.18)" clip-path="url(#e31pic)">${_e31scene(T)}</g></g>`;
P.e31_wallpaint=(o,T)=>`<g><rect x="-122" y="-104" width="244" height="208" rx="12" fill="#F4E5C2" ${st()}/><rect x="-122" y="58" width="244" height="46" fill="#C9A06A"/><rect x="-122" y="-104" width="244" height="208" rx="12" fill="none" ${st()}/><path d="M-30 -86 L0 -62 L30 -86" fill="none" ${st(_e31ink,3)}/><g transform="translate(0,-26) scale(.66)">${P.e31_painting({},T)}</g>${_e31sofa(0,64,.6,'#5E8BA8')}</g>`;
P.e31_pencil=(o,T)=>{const p=clamp(((T*.45)%2.2)/1.5);const w=170*p;
  return `<g><rect x="-110" y="-86" width="220" height="172" rx="10" fill="${C.paper}" ${st()}/><clipPath id="e31wc"><rect x="-96" y="-74" width="${f(w)}" height="90"/></clipPath><g clip-path="url(#e31wc)"><text x="-92" y="-42" font-family="Fraunces" font-style="italic" font-weight="700" font-size="32" fill="${C.navy2}">For Sara,</text><path d="M-92 -12 q18 -10 36 0 t36 0 t36 0 t36 0 t36 0 M-92 14 q18 -10 36 0 t36 0 t36 0" fill="none" ${st(C.navy2,4)}/></g><g transform="translate(${f(-96+w)},${f(-26)}) rotate(40)"><rect x="-9" y="-118" width="18" height="100" rx="3" fill="${C.gold}" ${st()}/><path d="M-9 -18 L0 12 L9 -18Z" fill="${C.cream}" ${st()}/><path d="M-3 4 L0 12 L3 4Z" fill="${_e31ink}"/><rect x="-9" y="-134" width="18" height="16" fill="#E88CA2" ${st(_e31ink,3)}/><rect x="-9" y="-124" width="18" height="6" fill="#B9C6CE"/></g></g>`};
P.e31_eraser=(o,T)=>{const ph=(T*.5)%1.6,er=clamp(ph/1.1),sx=Math.sin(T*9)*16*(er<1?1:0);
  return `<g><rect x="-110" y="-86" width="220" height="172" rx="10" fill="${C.paper}" ${st()}/><path d="M-80 20 q20 -50 40 -6 t40 -2 t40 -10 t30 20" fill="none" ${st(C.navy2,6)} opacity="${f(1-er)}"/><path d="M-80 20 q20 -30 40 -6 t40 -2 t40 -10 t30 20" fill="none" ${st(C.navy2,3)} opacity="${f(clamp(ph-1.2)/.4)}"/><g transform="translate(${f(-30+ er*80+sx)},${f(-6)}) rotate(-30)"><rect x="-9" y="-100" width="18" height="86" rx="3" fill="${C.gold}" ${st()}/><rect x="-9" y="-8" width="18" height="18" fill="#B9C6CE" ${st(_e31ink,3)}/><rect x="-9" y="8" width="18" height="22" rx="4" fill="#E88CA2" ${st(_e31ink,3)}/></g></g>`};
P.e31_pen=(o,T)=>`<g transform="rotate(-24)"><rect x="-12" y="-114" width="24" height="170" rx="10" fill="${C.blue}" ${st()}/><rect x="-6" y="-114" width="8" height="70" rx="3" fill="${C.white}" opacity=".7"/><path d="M-12 56 L0 100 L12 56Z" fill="#B9C6CE" ${st()}/><circle cx="0" cy="102" r="4" fill="${_e31ink}"/><rect x="12" y="-110" width="6" height="64" rx="3" fill="${C.gold}" ${st(_e31ink,3)}/></g>`;

/* ---------- chart ---------- */
P.e31_chart=(o,T,k)=>{const hs=[26,32,44,62,82,98,104,96,78,56,38,28];let b='';hs.forEach((h,i)=>{const hot=h>=60,g=ease((k||2)/.9-i*.05);const hh=h*g;b+=`<rect x="${-100+i*17}" y="${f(60-hh)}" width="13" height="${f(hh)}" rx="2" fill="${hot?C.red:C.blue}" ${st(_e31ink,2.5)}/>`});
  return `<g><rect x="-122" y="-96" width="244" height="192" rx="12" fill="#fff" ${st()}/>${b}<line x1="-110" y1="62" x2="104" y2="62" ${st(_e31ink,4)}/><line x1="-110" y1="-40" x2="-110" y2="62" ${st(_e31ink,4)}/><rect x="-106" y="-78" width="14" height="14" fill="${C.red}" ${st(_e31ink,2.5)}/><text x="-85" y="-66" font-family="Fraunces" font-weight="800" font-size="16" fill="${_e31ink}">SUMMER</text><rect x="6" y="-78" width="14" height="14" fill="${C.blue}" ${st(_e31ink,2.5)}/><text x="27" y="-66" font-family="Fraunces" font-weight="800" font-size="16" fill="${_e31ink}">WINTER</text><text x="0" y="86" text-anchor="middle" font-family="Fraunces" font-weight="700" font-size="16" fill="${C.navy2}" opacity="0"></text></g>`};

/* ---------- photo, blonde girl, cat ---------- */
P.e31_blondegirl=(o,T)=>{const fl=o.flowers?[[-36,-66],[-18,-88],[12,-90],[36,-68],[-44,-32],[44,-30],[0,-70]].map(([x,y],i)=>_e31bl(x,y,9,'#fff',T,i)).join(''):'';
  return `<g>${P.person({c:'#F28CA6',hair:'long',hc:'#F2D16B'},T)}${fl}</g>`};
P.e31_photo=(o,T)=>{const old=o.old;return `<g transform="rotate(${f(-4+Math.sin(T*1.3)*2)})"><rect x="-96" y="-116" width="192" height="232" rx="6" fill="#FBF8EF" ${st()}/><clipPath id="e31phc"><rect x="-80" y="-100" width="160" height="170"/></clipPath><g clip-path="url(#e31phc)"><rect x="-80" y="-100" width="160" height="170" fill="${old?'#D9C39A':C.sky}"/><rect x="-80" y="10" width="160" height="60" fill="${old?'#BFA77A':'#8CC17A'}"/><g transform="translate(0,16) scale(.96)">${old?P.person({c:'#A68B5B',hair:'long',hc:'#E8CC86',skin:'#D2B48C'},T):P.e31_blondegirl({flowers:1},T)}</g></g><rect x="-80" y="-100" width="160" height="170" fill="none" ${st(_e31ink,3)}/></g>`};
P.e31_cat=(o,T)=>{const fat=o.fat!==0,rx=fat?96:62,ry=fat?72:46,br=Math.sin(T*1.6)*(fat?3:2);
  return `<g><path d="M${rx-8} 30 Q${rx+44} 30 ${rx+36} -30" fill="none" stroke="#E39B4B" stroke-width="16" stroke-linecap="round"/><ellipse cx="0" cy="${f(26+br*.4)}" rx="${rx+br}" ry="${ry+br}" fill="#E39B4B" ${st()}/><path d="M-26 -30 Q-8 -46 14 -30 M18 -34 Q36 -44 52 -26" fill="none" stroke="#C9741E" stroke-width="7" stroke-linecap="round"/><ellipse cx="0" cy="${fat?60:50}" rx="${fat?60:40}" ry="${fat?26:20}" fill="#FFF3D9"/><circle cx="-${rx*.5}" cy="-${ry*.55}" r="34" fill="#E39B4B" ${st()}/><polygon points="${-rx*.5-30},${-ry*.55-18} ${-rx*.5-26},${-ry*.55-56} ${-rx*.5-4},${-ry*.55-28}" fill="#E39B4B" ${st()}/><polygon points="${-rx*.5+4},${-ry*.55-30} ${-rx*.5+26},${-ry*.55-54} ${-rx*.5+32},${-ry*.55-14}" fill="#E39B4B" ${st()}/></g>`};
P.e31_catchair=(o,T)=>`<g><g transform="translate(0,-8) scale(.82)">${P.e31_cat({fat:1},T)}</g><rect x="-58" y="76" width="116" height="14" rx="6" fill="#A9743F" ${st()}/><rect x="-50" y="90" width="12" height="30" fill="${C.brown}" ${st()}/><rect x="38" y="90" width="12" height="30" fill="${C.brown}" ${st()}/>${o.zzz?`<g transform="translate(70,-60) scale(.6)">${P.zzz({},T)}</g>`:''}</g>`;

/* ---------- cinema, screen, clapperboard ---------- */
P.e31_cinema=(o,T)=>{let bl='';for(let i=0;i<10;i++)bl+=`<circle cx="${-100+i*22.2}" cy="-86" r="4" fill="${(i+Math.floor(T*3))%2?C.gold:'#fff'}"/>`;
  return `<g><rect x="-112" y="-102" width="224" height="52" rx="8" fill="#2B3D48" ${st()}/>${bl}<text x="0" y="-60" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="34" fill="${C.gold}" letter-spacing="5">CINEMA</text><rect x="-100" y="-50" width="200" height="146" fill="#E8DFC8" ${st()}/><rect x="-86" y="-34" width="52" height="74" fill="#D9534F" ${st(_e31ink,3)}/><rect x="34" y="-34" width="52" height="74" fill="#4DA3D8" ${st(_e31ink,3)}/><circle cx="-60" cy="-8" r="12" fill="${C.gold}"/><polygon points="52,24 68,-6 78,24" fill="#fff"/><rect x="-24" y="30" width="48" height="66" fill="${C.brown}" ${st()}/></g>`};
P.e31_screen=(o,T)=>{const hd=(x,y,c)=>`<g transform="translate(${x},${y})"><circle cx="0" cy="-16" r="15" fill="${c}" ${st(_e31ink,3)}/><path d="M-22 14 Q-22 -2 0 -2 Q22 -2 22 14Z" fill="${c}" ${st(_e31ink,3)}/></g>`;
  const chair=(x,y)=>`<g transform="translate(${x},${y})"><rect x="-26" y="-28" width="52" height="46" rx="12" fill="#B83A3A" ${st(_e31ink,3.5)}/></g>`;
  return `<g><rect x="-118" y="-100" width="236" height="14" fill="#8A2E2E" ${st()}/><path d="M-118 -86 Q-98 -20 -118 20 H-96 Q-76 -30 -96 -86Z" fill="#B83A3A" ${st()}/><path d="M118 -86 Q98 -20 118 20 H96 Q76 -30 96 -86Z" fill="#B83A3A" ${st()}/><clipPath id="e31scc"><rect x="-90" y="-86" width="180" height="106"/></clipPath><rect x="-90" y="-86" width="180" height="106" fill="#fff" ${st()}/><g clip-path="url(#e31scc)"><rect x="-90" y="-86" width="180" height="106" fill="${C.sky}"/><polygon points="-90,20 -40,-40 10,20" fill="#8FA3B0"/><polygon points="-10,20 40,-30 90,20" fill="#A9BAC4"/><g transform="translate(${f(Math.sin(T*.8)*10+40)},-52) scale(.28)">${P.sun({},T)}</g></g>${chair(-70,64)}${chair(0,64)}${chair(70,64)}${hd(-35,66,'#4F5B66')}${hd(35,66,'#6A4F3C')}</g>`};
P.e31_clap=(o,T)=>{const op=Math.max(0,Math.sin(T*2.6))*-18;let st1='';for(let i=0;i<5;i++)st1+=`<polygon points="${-96+i*40},-6 ${-76+i*40},-6 ${-56+i*40},-34 ${-76+i*40},-34" fill="${i%2?'#fff':_e31ink}"/>`;
  return `<g><rect x="-100" y="-4" width="200" height="104" rx="6" fill="#2B3D48" ${st()}/><line x1="-100" y1="34" x2="100" y2="34" ${st('#fff',3)}/><line x1="-100" y1="66" x2="100" y2="66" ${st('#fff',3)}/><text x="-86" y="26" font-family="Fraunces" font-weight="800" font-size="20" fill="#fff" letter-spacing="2">MOVIE</text><g transform="rotate(${f(op)} -100 -8)"><rect x="-100" y="-38" width="200" height="30" rx="4" fill="${_e31ink}" ${st()}/><clipPath id="e31cl"><rect x="-98" y="-36" width="196" height="26"/></clipPath><g clip-path="url(#e31cl)" transform="translate(0,-2)">${st1}</g></g></g>`};
P.e31_film=(o,T)=>{let h='';for(let i=0;i<5;i++)h+=`<rect x="-92" y="${-92+i*40}" width="16" height="22" rx="3" fill="#fff"/><rect x="76" y="${-92+i*40}" width="16" height="22" rx="3" fill="#fff"/>`;
  return `<g transform="rotate(-8)"><rect x="-104" y="-110" width="208" height="220" rx="6" fill="${_e31ink}" ${st()}/>${h}${[0,1].map(i=>`<rect x="-58" y="${-96+i*108}" width="116" height="94" fill="${i?'#8FD0EA':'#F4C77A'}" ${st('#fff',3)}/>`).join('')}<polygon points="-18,-72 -18,-34 18,-53" fill="#fff" opacity=".9"/></g>`};

/* ---------- poor boy, wallet, books ---------- */
P.e31_poorboy=(o,T)=>`<g><g transform="translate(60,24) scale(.7)"><polygon points="-82,-4 0,-72 82,-4" fill="#8B5E3C" ${st()}/><rect x="-66" y="-6" width="132" height="92" fill="#C9B38A" ${st()}/><rect x="-14" y="28" width="38" height="58" fill="#6F4A2E" ${st()}/><rect x="-54" y="8" width="32" height="26" fill="#FFE08A" ${st(_e31ink,3)}/></g><g transform="translate(-42,8) scale(.82)">${P.person({c:'#9A8F7D',hair:'short',hc:'#3A2A22'},T)}<rect x="-30" y="30" width="26" height="22" fill="#B7765B" ${st(_e31ink,3)}/><rect x="14" y="56" width="26" height="22" fill="#6F8FA8" ${st(_e31ink,3)}/><line x1="-30" y1="41" x2="-4" y2="41" stroke="${_e31ink}" stroke-width="2" stroke-dasharray="4 3"/></g></g>`;
P.e31_wallet=(o,T)=>`<g transform="rotate(${f(Math.sin(T*1.5)*2)})"><path d="M-108 -40 Q-108 -62 -86 -62 H86 Q108 -62 108 -40 V70 Q108 92 86 92 H-86 Q-108 92 -108 70Z" fill="${C.brown}" ${st()}/><path d="M-90 -44 H90 V64 H-90Z" fill="#3A2A22" ${st(_e31ink,3)}/><path d="M-108 -2 H108" ${st(_e31ink,3)}/><path d="M-100 -2 Q-110 -40 -100 -62 L100 -62 Q110 -40 100 -2Z" fill="#6F4A2E" opacity="0"/><path d="M48 12 h60 a14 14 0 0 1 14 14 v20 a14 14 0 0 1 -14 14 h-60 a14 14 0 0 1 -14 -14 v-20 a14 14 0 0 1 14 -14Z" fill="#A9743F" ${st()}/><circle cx="54" cy="36" r="8" fill="${C.gold}" ${st(_e31ink,3)}/></g>`;
P.e31_books=(o,T)=>{const cs=[C.red,C.blue,C.moss,C.gold2];let s='';for(let i=0;i<4;i++)s+=`<rect x="${-88+(i%2)*12}" y="${64-i*38}" width="${176-(i%3)*18}" height="34" rx="5" fill="${cs[i]}" ${st()}/><rect x="${-74+(i%2)*12}" y="${72-i*38}" width="64" height="7" rx="3" fill="#fff" opacity=".6"/>`;return `<g>${s}</g>`};
P.e31_openbook=(o,T)=>{let l='';for(let i=0;i<5;i++)l+=`<line x1="-96" y1="${-44+i*20}" x2="-22" y2="${-44+i*20}" ${st('#9AA7B0',3)}/><line x1="22" y1="${-44+i*20}" x2="96" y2="${-44+i*20}" ${st('#9AA7B0',3)}/>`;
  return `<g><path d="M-112 -70 Q-56 -86 0 -64 Q56 -86 112 -70 V74 Q56 58 0 80 Q-56 58 -112 74Z" fill="#F4EFE0" ${st()}/><line x1="0" y1="-64" x2="0" y2="80" ${st(_e31ink,4)}/>${l}</g>`};

/* ---------- actor, actress, theatre ---------- */
P.e31_actor=(o,T)=>{const fem=o.f,bob=Math.sin(T*2)*2;
  const body=fem?P.person({c:'#C0397A',hair:'long',hc:'#3A2A22'},T):P.person({c:'#2B3D48',hair:'short',hc:'#222'},T)+`<polygon points="-12,-6 0,2 12,-6 12,12 0,4 -12,12" fill="${C.red}" ${st(_e31ink,3)}/>`;
  return `<g><path d="M-110 -110 Q-90 -40 -108 20 H-86 Q-66 -40 -86 -110Z" fill="#B83A3A" ${st()}/><path d="M110 -110 Q90 -40 108 20 H86 Q66 -40 86 -110Z" fill="#B83A3A" ${st()}/><polygon points="-26,-112 26,-112 78,100 -78,100" fill="#FFF3C4" opacity=".55"/><ellipse cx="0" cy="104" rx="84" ry="14" fill="#FFF3C4" ${st(_e31ink,3)}/><g transform="translate(0,${f(bob)}) scale(.86)">${body}</g><g transform="translate(0,${f(-100+Math.sin(T*3)*3)}) scale(.7)"><polygon points="0,-22 6,-8 22,-6 10,4 14,20 0,12 -14,20 -10,4 -22,-6 -6,-8" fill="${C.gold}" ${st(C.goldD,3)}/></g></g>`};
P.e31_theatre=(o,T)=>{let cols='';for(let i=0;i<4;i++)cols+=`<rect x="${-84+i*48}" y="-26" width="26" height="92" fill="${C.cream}" ${st()}/>`;
  return `<g><polygon points="-122,-26 0,-98 122,-26" fill="#8A2E2E" ${st()}/><text x="0" y="-40" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="20" fill="${C.cream}" letter-spacing="3">THEATRE</text>${cols}<rect x="-20" y="-20" width="40" height="86" fill="#B83A3A" ${st(_e31ink,4)}/><path d="M0 -20 V66" ${st(_e31ink,3)}/><rect x="-122" y="66" width="244" height="14" fill="#E8DFC8" ${st()}/><rect x="-134" y="80" width="268" height="14" fill="#DCD2B8" ${st()}/></g>`};

/* ---------- plant, watering can, lie / truth ---------- */
P.e31_plant=(o,T)=>{const dead=o.dead,sw=dead?0:Math.sin(T*1.5)*2;let pl;
  if(dead)pl=`<path d="M0 30 V-24 Q0 -52 28 -50 Q50 -48 50 -24" fill="none" ${st('#8A6B3D',7)}/><path d="M50 -24 Q74 -16 62 6 Q44 -4 50 -24Z" fill="#A98A4F" ${st(_e31ink,3)}/><path d="M0 -4 Q-34 -12 -44 14 Q-14 22 0 -4Z" fill="#B59A5E" ${st(_e31ink,3)}/><path d="M-56 70 Q-34 56 -22 76 Q-44 84 -56 70Z" fill="#A98A4F" ${st(_e31ink,3)}/>`;
  else pl=`<g transform="rotate(${f(sw)} 0 40)"><path d="M0 40 V-40" ${st(C.leaf,8)}/><path d="M0 -4 Q-48 -26 -58 6 Q-20 20 0 -4Z" fill="${C.leaf}" ${st()}/><path d="M0 -34 Q44 -62 58 -30 Q22 -14 0 -34Z" fill="${C.leaf}" ${st()}/></g>`;
  return `<g transform="translate(0,-12)">${pl}<path d="M-46 38 H46 L36 100 H-36Z" fill="#C9744A" ${st()}/><rect x="-54" y="30" width="108" height="16" rx="5" fill="#D98A5C" ${st()}/></g>`};
P.e31_water=(o,T)=>{let d='';for(let i=0;i<4;i++){const ph=(T*1.1+i/4)%1;d+=`<path d="M${f(-82-ph*8)} ${f(-8+ph*86)} q-5 9 0 14 q5 -5 0 -14" fill="${C.blue}" opacity="${f(1-ph*.8)}"/>`}
  return `<g transform="rotate(${f(-12+Math.sin(T*1.4)*3)})"><path d="M-40 -36 H44 L52 70 Q52 88 34 88 H-30 Q-48 88 -48 70Z" fill="#5E9BC4" ${st()}/><path d="M-40 -34 L-100 -52 L-96 -30 L-42 -6" fill="#5E9BC4" ${st()}/><ellipse cx="-96" cy="-44" rx="8" ry="14" fill="#7DB4D8" ${st(_e31ink,3)}/><path d="M44 -20 Q96 -22 90 28 Q84 60 50 54" fill="none" ${st(_e31ink,8)}/><path d="M-26 -36 Q4 -76 34 -36" fill="none" ${st(_e31ink,7)}/>${d}</g>`};
P.e31_say=(o,T)=>{const yes=o.t==='Yes';
  return `<g><g transform="translate(-52,24) scale(.62)">${P.person({c:'#F2994A',hair:'short',hc:'#3A2A22'},T)}</g><g transform="translate(70,40) scale(.52)">${P.e31_plant({dead:1},T)}</g><g transform="translate(14,-66)"><path d="M-62 -34 H62 Q76 -34 76 -20 V16 Q76 30 62 30 H20 L-6 56 L-8 30 H-62 Q-76 30 -76 16 V-20 Q-76 -34 -62 -34Z" fill="#fff" ${st()}/><text x="0" y="12" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="46" fill="${yes?C.moss:C.red}">${o.t||'No'}</text></g></g>`};

/* ---------- weekend, years, old man ---------- */
P.e31_weekend=(o,T)=>{let b='';['S','M','T','W','T','F','S'].forEach((l,i)=>{const on=i===0||i===6,pulse=on?1+.06*Math.sin(T*5):1;b+=`<g transform="translate(${-108+i*36},12) scale(${f(pulse)})"><rect x="-14" y="-32" width="28" height="64" rx="8" fill="${on?C.gold:C.white}" ${st()}/><text x="0" y="9" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="20" fill="${_e31ink}">${l}</text></g>`});
  return `<g><rect x="-136" y="-44" width="272" height="120" rx="18" fill="${C.cream}" ${st()}/>${b}<text x="0" y="-62" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" fill="${_e31ink}" letter-spacing="4">WEEKEND</text></g>`};
P.e31_years=(o,T)=>{const n=o.n||4;let b='';for(let i=0;i<n;i++){const p=ease(((T*1.2)%(n+2)-i*.5)/.5);const pu=1+.04*Math.sin(T*4+i);b+=`<g transform="translate(${-96+i*64},0) scale(${f(pu)})"><rect x="-27" y="-44" width="54" height="80" rx="10" fill="${C.gold}" ${st()}/><text x="0" y="12" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="52" fill="${_e31ink}">${i+1}</text></g>`}
  return `<g><rect x="-132" y="-70" width="264" height="130" rx="18" fill="${C.cream}" ${st()}/><text x="0" y="-84" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" fill="${_e31ink}" letter-spacing="4" opacity="0"></text><g transform="translate(0,-18)">${b}</g><text x="0" y="52" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="${C.navy2}" letter-spacing="6">YEARS</text></g>`};
P.e31_oldman=(o,T)=>`<g>${P.person({c:'#7C6A55',hair:'short',hc:'#E4E7EA'},T)}<rect x="-30" y="34" width="24" height="22" fill="#9A8F7D" ${st(_e31ink,3)}/><path d="M-26 -22 Q-30 12 0 14 Q30 12 26 -22 Q10 -4 0 -4 Q-10 -4 -26 -22Z" fill="#E4E7EA" ${st(_e31ink,3)}/><g transform="translate(42,-56) rotate(-60)"><rect x="-4" y="-34" width="8" height="40" rx="2" fill="${C.gold}" ${st(_e31ink,3)}/><path d="M-4 6 L0 16 L4 6Z" fill="${C.cream}" ${st(_e31ink,2.5)}/><rect x="-4" y="-40" width="8" height="8" fill="#E88CA2" ${st(_e31ink,2.5)}/></g></g>`;
P.e31_camera=(o,T)=>{const fl=Math.max(0,Math.sin(T*2.4))>.9?`<circle cx="60" cy="-46" r="28" fill="#fff" opacity=".7"/>`:'';return `<g><rect x="-100" y="-44" width="200" height="124" rx="20" fill="${C.navy2}" ${st()}/><rect x="-100" y="-44" width="200" height="38" rx="20" fill="#B9C6CE" ${st()}/><rect x="-82" y="-66" width="46" height="26" rx="8" fill="${_e31ink}" ${st()}/><circle cx="0" cy="26" r="50" fill="${_e31ink}" ${st()}/><circle cx="0" cy="26" r="36" fill="#3D6C8A" ${st('#9FB0BA',5)}/><circle cx="0" cy="26" r="18" fill="${_e31ink}"/><rect x="58" y="-60" width="30" height="16" rx="5" fill="${C.red}" ${st(_e31ink,3)}/>${fl}</g>`};

/* ---------- Sara: the cousin, optionally with a graduation cap ---------- */
P.e31_sara=(o,T)=>{const cap=o.cap?`<g transform="translate(0,${f(Math.sin(T*3)*2)})"><path d="M-26 -96 V-78 Q0 -66 26 -78 V-96Z" fill="#2B3D48" ${st(_e31ink,4)}/><polygon points="0,-130 -62,-106 0,-82 62,-106" fill="#1E2B33" ${st(_e31ink,4)}/><path d="M0 -106 L52 -100 V-76" fill="none" ${st(C.gold,5)}/><circle cx="52" cy="-72" r="6" fill="${C.gold}" ${st(C.goldD,2)}/></g>`:'';
  return `<g>${P.person({c:'#4F7A5A',hair:'long',hc:'#2A1D18'},T)}${cap}</g>`};

/* ---------- two weeks (two rows of days) and colour swatches ---------- */
P.e31_twoweeks=(o,T)=>{let b='';for(let r=0;r<2;r++)['S','M','T','W','T','F','S'].forEach((l,i)=>{const pu=1+.04*Math.sin(T*4+i+r*2);b+=`<g transform="translate(${-108+i*36},${-46+r*92}) scale(${f(pu)})"><rect x="-14" y="-30" width="28" height="60" rx="8" fill="${C.gold}" ${st()}/><text x="0" y="8" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="20" fill="${_e31ink}">${l}</text></g>`});
  return `<g><rect x="-136" y="-92" width="272" height="184" rx="18" fill="${C.cream}" ${st()}/>${b}</g>`};
P.e31_swatch=(o,T)=>{const pu=1+.05*Math.sin(T*3);return `<g><circle cx="-62" cy="0" r="${f(60*pu)}" fill="${C.red}" ${st()}/><circle cx="62" cy="0" r="${f(60/pu)}" fill="${C.blue}" ${st()}/></g>`};

/* A2 ep 2 props begin */
/* Episode 102 props: Healthy or Not? Daily habits (headache, water, sleep, sweets, nuts, walking, heart, oil, beans, lemon, tips). Faceless. Uses C, st, f, ease, clamp, P. */
const _e102tx=(t,x,y,fs,fill)=>`<text x="${x}" y="${y}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${fs}" fill="${fill||C.navy}">${t}</text>`;
const _e102bis=(x,y,r,rot,T)=>`<g transform="translate(${f(x)},${f(y)}) rotate(${rot||0})"><circle r="${r}" fill="#E3A857" ${st(C.navy,Math.max(3,r*.1))}/><circle r="${r*.78}" fill="none" stroke="#F3CE8A" stroke-width="${Math.max(2,r*.07)}" stroke-dasharray="${r*.18} ${r*.14}"/>${[[-.35,-.3],[.3,-.4],[.05,.05],[-.3,.35],[.38,.28]].map(([a,b])=>`<circle cx="${f(a*r)}" cy="${f(b*r)}" r="${f(r*.14)}" fill="#6B3F22"/>`).join('')}</g>`;
const _e102nut=(x,y,r,rot)=>`<g transform="translate(${f(x)},${f(y)}) rotate(${rot||0})"><path d="M0 ${-r*1.1} C${r*.9} ${-r*.6} ${r*.9} ${r*.7} 0 ${r*1.1} C${-r*.9} ${r*.7} ${-r*.9} ${-r*.6} 0 ${-r*1.1}Z" fill="#B9763E" ${st(C.navy,Math.max(2.5,r*.16))}/><path d="M${-r*.3} ${-r*.5} Q${-r*.45} 0 ${-r*.25} ${r*.5}" fill="none" stroke="#E2B27A" stroke-width="${Math.max(2,r*.16)}" stroke-linecap="round"/></g>`;
const _e102lemon=(x,y,s,rot)=>`<g transform="translate(${x},${y}) rotate(${rot||0}) scale(${s})"><path d="M-52 0 Q-52 -40 0 -40 Q52 -40 52 0 Q52 40 0 40 Q-52 40 -52 0Z" fill="#F7D84A" ${st()}/><path d="M-54 0 Q-62 -4 -66 2 Q-60 8 -54 4Z M54 0 Q62 -4 66 2 Q60 8 54 4Z" fill="#F7D84A" ${st(C.navy,4)}/><path d="M-30 -22 Q-14 -34 8 -32" fill="none" stroke="#fff" stroke-width="6" stroke-linecap="round" opacity=".6"/><path d="M6 -40 q12 -22 36 -16 q-4 22 -36 16Z" fill="${C.leaf}" ${st(C.navy,4)}/></g>`;
const _e102slice=(x,y,r)=>{let s='';for(let i=0;i<8;i++)s+=`<path d="M0 0 L${f(Math.cos(i*Math.PI/4+.1)*r*.78)} ${f(Math.sin(i*Math.PI/4+.1)*r*.78)}" ${st('#fff',Math.max(2,r*.07))}/>`;return `<g transform="translate(${x},${y})"><circle r="${r}" fill="#F7D84A" ${st(C.navy,Math.max(3,r*.12))}/><circle r="${r*.82}" fill="#FBEB9A"/>${s}<circle r="${r*.1}" fill="#fff"/></g>`};
const _e102ph=(id,inner,o)=>{o=o||{};const w=o.w||112,h=o.h||212,x0=-w/2+8,y0=-h/2+16,sw=w-16,sh=h-32;return `<g><rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="22" fill="${C.navy}" ${st()}/><clipPath id="e102_${id}"><rect x="${x0}" y="${y0}" width="${sw}" height="${sh}" rx="9"/></clipPath><rect x="${x0}" y="${y0}" width="${sw}" height="${sh}" rx="9" fill="${o.bg||C.cream}"/><g clip-path="url(#e102_${id})">${inner}</g><rect x="-13" y="${-h/2+6}" width="26" height="5" rx="2.5" fill="#41525c"/></g>`};

/* ---------- pain: headache, stomach ---------- */
P.e102_headache=(o,T,k)=>{let r='';for(let i=0;i<12;i++){const a=i*30*Math.PI/180,p=(Math.sin(T*7+i*1.7)+1)/2,r1=56,r2=70+p*16;r+=`<line x1="${f(Math.cos(a)*r1)}" y1="${f(Math.sin(a)*r1-44)}" x2="${f(Math.cos(a)*r2)}" y2="${f(Math.sin(a)*r2-44)}" ${st(C.red,7)}/>`}
  return `<g><g transform="translate(0,12)">${P.person({c:o.c||'#4DA3D8',hair:'short',hc:'#222'},T)}</g><g transform="translate(0,8)">${r}</g><g transform="translate(66,-124) scale(.55)"><path d="M-86 40 a38 38 0 0 1 4 -74 a54 54 0 0 1 104 -10 a40 40 0 0 1 60 34 a30 30 0 0 1 -6 50Z" fill="#7C8F9B" ${st()}/><path d="M-4 -20 L-26 30 H-4 L-16 66 L20 14 H0 L16 -20Z" fill="${C.gold}" ${st(C.navy,5)}/></g></g>`};
P.e102_stomach=(o,T,k)=>{const p=1+Math.sin(T*6)*.08;let z='';for(let i=0;i<4;i++){const a=i*90+T*30;z+=`<path d="M${f(Math.cos(a*Math.PI/180)*30)} ${f(Math.sin(a*Math.PI/180)*30+58)} l${f(Math.cos(a*Math.PI/180)*22)} ${f(Math.sin(a*Math.PI/180)*22)}" ${st(C.red,6)}/>`}
  return `<g><g transform="translate(0,12)">${P.person({c:o.c||'#4DA3D8',hair:'short',hc:'#222'},T)}</g><g transform="translate(0,58) scale(${f(p)})"><circle r="24" fill="${C.red}" opacity=".35"/><path d="M-16 -4 q8 -14 16 -2 q8 12 -4 16 q-14 2 -12 -10 q2 -6 8 -4" fill="none" ${st(C.red,6)}/></g>${z}</g>`};
P.e102_pills=(o,T,k)=>`<g><g transform="translate(-34,-6) rotate(-6)"><rect x="-44" y="-84" width="88" height="22" rx="8" fill="#fff" ${st()}/><path d="M-40 -62 H40 V92 Q40 104 28 104 H-28 Q-40 104 -40 92Z" fill="#E3A24F" ${st()}/><rect x="-36" y="-34" width="72" height="84" rx="8" fill="#fff" ${st(C.navy,4)}/><path d="M-9 -8 h18 v14 h14 v18 h-14 v14 h-18 v-14 h-14 v-18 h14Z" fill="${C.red}"/><path d="M-32 -56 V-70" ${st('#fff',5)} opacity=".6"/></g><g transform="translate(56,64)"><g transform="rotate(-24)"><path d="M-30 0 a14 14 0 0 1 14 -14 h16 v28 h-16 a14 14 0 0 1 -14 -14Z" fill="${C.red}" ${st(C.navy,4)}/><path d="M0 -14 h16 a14 14 0 0 1 0 28 h-16Z" fill="#fff" ${st(C.navy,4)}/></g></g><g transform="translate(78,2)"><circle r="17" fill="#fff" ${st(C.navy,4)}/><line x1="-12" y1="0" x2="12" y2="0" ${st('#B9C6CE',3)}/></g><g transform="translate(24,98)"><circle r="15" fill="#F7E7A8" ${st(C.navy,4)}/><line x1="-10" y1="0" x2="10" y2="0" ${st('#C9B36A',3)}/></g></g>`;

/* ---------- water ---------- */
P.e102_water=(o,T,k)=>{const n=o.n||8,cols=Math.min(4,n);let g='';for(let i=0;i<n;i++){const a=Math.floor(i/4),b=i%4,cx=(b-(Math.min(n,4)-1)/2)*66,cy=(n>4?-48+a*104:0);const fill=ease((k-.08*i-.2)/.5);g+=`<g transform="translate(${cx},${cy})"><clipPath id="e102_wg${i}"><path d="M-26 -42 H26 L21 38 Q21 44 15 44 H-15 Q-21 44 -21 38Z"/></clipPath><path d="M-26 -42 H26 L21 38 Q21 44 15 44 H-15 Q-21 44 -21 38Z" fill="#EAF6FD" ${st()}/><g clip-path="url(#e102_wg${i})"><rect x="-30" y="${f(44-84*.8*fill)}" width="60" height="90" fill="${C.cold}"/><path d="M-30 ${f(44-84*.8*fill)} q15 -6 30 0 t30 0" fill="${C.sky}" opacity=".9"/></g><path d="M-26 -42 H26 L21 38 Q21 44 15 44 H-15 Q-21 44 -21 38Z" fill="none" ${st()}/><path d="M-17 -30 L-14 20" stroke="#fff" stroke-width="5" stroke-linecap="round" opacity=".7"/></g>`}return `<g>${g}</g>`};
P.e102_bottle=(o,T,k)=>{const lv=ease(k/1.2)*.8;let m='';for(let i=0;i<5;i++)m+=`<line x1="22" y1="${-40+i*36}" x2="40" y2="${-40+i*36}" ${st(C.navy,4)}/>`;return `<g><clipPath id="e102_bt"><path d="M-36 -70 Q-36 -92 -20 -100 V-112 H20 V-100 Q36 -92 36 -70 V104 Q36 118 22 118 H-22 Q-36 118 -36 104Z"/></clipPath><path d="M-36 -70 Q-36 -92 -20 -100 V-112 H20 V-100 Q36 -92 36 -70 V104 Q36 118 22 118 H-22 Q-36 118 -36 104Z" fill="#EAF6FD"/><g clip-path="url(#e102_bt)"><rect x="-40" y="${f(118-228*lv)}" width="80" height="240" fill="${C.cold}"/><path d="M-40 ${f(118-228*lv)} q20 -7 40 0 t40 0" fill="${C.sky}"/></g><path d="M-36 -70 Q-36 -92 -20 -100 V-112 H20 V-100 Q36 -92 36 -70 V104 Q36 118 22 118 H-22 Q-36 118 -36 104Z" fill="none" ${st()}/><rect x="-24" y="-132" width="48" height="24" rx="6" fill="${C.blue}" ${st()}/>${m}<path d="M-26 -60 V80" stroke="#fff" stroke-width="6" stroke-linecap="round" opacity=".7"/>${o.lemon?`<g transform="translate(30,-108)">${_e102slice(0,0,24)}</g>`:''}</g>`};
P.e102_lemonwater=(o,T,k)=>`<g><path d="M-62 -66 H62 L50 82 Q48 96 34 96 H-34 Q-48 96 -50 82Z" fill="#EAF6FD" ${st()}/><path d="M-57 -26 H57 L50 82 Q48 96 34 96 H-34 Q-48 96 -50 82Z" fill="${C.cold}" opacity=".9"/><path d="M-57 -26 q14 -8 28 0 t28 0 t28 0" fill="none" stroke="#fff" stroke-width="5" opacity=".8" transform="translate(${f(Math.sin(T*2)*3)},0)"/><path d="M-62 -66 H62 L50 82 Q48 96 34 96 H-34 Q-48 96 -50 82Z" fill="none" ${st()}/><path d="M-46 -52 L-38 60" stroke="#fff" stroke-width="7" stroke-linecap="round" opacity=".7"/><g transform="translate(58,-66) rotate(20)">${_e102slice(0,0,36)}</g><rect x="14" y="-122" width="12" height="100" rx="6" fill="${C.red}" ${st(C.navy,4)} transform="rotate(12 20 -22)"/></g>`;

/* ---------- desk, sweets, energy ---------- */
P.e102_sitdesk=(o,T,k)=>`<g><g transform="translate(-30,8) scale(.9)">${P.person({c:o.c||'#4DA3D8',hair:'short',hc:'#222'},T)}</g><rect x="-130" y="62" width="260" height="20" rx="8" fill="${C.brown}" ${st()}/><rect x="-116" y="82" width="14" height="40" fill="${C.brown}" ${st()}/><rect x="102" y="82" width="14" height="40" fill="${C.brown}" ${st()}/><g transform="translate(62,0)"><rect x="-52" y="-62" width="104" height="70" rx="8" fill="${C.navy2}" ${st()}/><rect x="-44" y="-54" width="88" height="54" rx="4" fill="#CFEAF7"/><rect x="-34" y="-44" width="44" height="8" rx="4" fill="#fff"/><rect x="-34" y="-28" width="64" height="8" rx="4" fill="${C.blue}"/><rect x="-8" y="8" width="16" height="22" fill="#5C7585" ${st(C.navy,3)}/><rect x="-28" y="26" width="56" height="10" rx="5" fill="#5C7585" ${st(C.navy,3)}/></g></g>`;
P.e102_biscuits=(o,T,k)=>{if(o.box){return `<g><rect x="-96" y="-4" width="192" height="100" rx="14" fill="${C.blue}" ${st()}/><rect x="-104" y="-26" width="208" height="30" rx="10" fill="#3B8DC0" ${st()}/><circle cx="0" cy="50" r="26" fill="${C.cream}" ${st(C.navy,4)}/><path d="M-12 52 q12 -26 24 0" fill="none" ${st(C.navy,4)}/>${_e102bis(-52,-40,34,-12)}${_e102bis(8,-52,34,10)}${_e102bis(62,-36,32,24)}</g>`}
  const n=o.n==null?5:o.n;if(n===1)return `<g transform="rotate(${f(Math.sin(T*2)*5)})">${_e102bis(0,0,98*(o.sc||1),-10)}</g>`;
  const pos=[[-84,22],[0,40],[84,22],[-42,-38],[44,-38],[0,-90]];let s='';for(let i=0;i<n&&i<6;i++){const p=ease((k-.1*i)/.3);s+=`<g transform="translate(0,${f((1-p)*-30)})" opacity="${f(p)}">${_e102bis(pos[i][0],pos[i][1]+Math.sin(T*2+i)*2,44,i*25)}</g>`}return `<g>${s}</g>`};
P.e102_battery=(o,T,k)=>{let l=o.l==null?.5:o.l;if(o.mode==='drop')l=1-ease(k/2.6)*.88;if(o.mode==='up')l=.12+ease(k/1.8)*.88;if(o.mode==='cycle')l=.5+.45*Math.sin(T*2.4);const col=l>.55?C.leaf:l>.25?C.orange:C.red;const w=Math.max(0,176*l);
  return `<g><rect x="-110" y="-60" width="212" height="120" rx="22" fill="#fff" ${st()}/><rect x="102" y="-24" width="20" height="48" rx="8" fill="${C.navy}" ${st()}/><rect x="-98" y="-48" width="${f(w)}" height="96" rx="12" fill="${col}" ${st(C.navy,3)}/>${[1,2,3].map(i=>`<line x1="${-98+i*44}" y1="-48" x2="${-98+i*44}" y2="48" stroke="#fff" stroke-width="4" opacity=".5"/>`).join('')}${l<.25?`<path d="M-14 -34 L-30 6 H-10 L-20 38 L22 -8 H2 L14 -34Z" fill="${C.gold}" ${st(C.navy,4)} opacity="${f(.5+.5*Math.sin(T*8))}"/>`:''}</g>`};
P.e102_sugarcrash=(o,T,k)=>{const pr=ease(k/2.2);const pts=[[-110,70],[-70,50],[-30,-60],[0,-84],[30,-40],[70,50],[110,84]];let d='M'+pts.map(p=>p.join(' ')).join(' L');
  const L=520;return `<g><line x1="-120" y1="96" x2="124" y2="96" ${st()}/><line x1="-120" y1="96" x2="-120" y2="-100" ${st()}/><path d="${d}" fill="none" ${st(C.navy,14)} stroke-dasharray="${L}" stroke-dashoffset="${f(L*(1-pr))}"/><path d="${d}" fill="none" ${st(C.orange,7)} stroke-dasharray="${L}" stroke-dashoffset="${f(L*(1-pr))}"/><g transform="translate(-74,-72) scale(.34)">${_e102bis(0,0,60,0)}</g><g transform="translate(100,-44) scale(.7)"><path d="M0 -26 V6 M0 22 V26" ${st(C.red,10)}/></g></g>`};
P.e102_nuts=(o,T,k)=>{const n=o.n||9;let s='';const pos=[[-34,-8,20],[0,-14,-30],[34,-6,60],[-18,-30,10],[18,-32,-50],[-46,-26,40],[48,-24,-20],[0,-46,5],[-30,-50,-40],[30,-52,25],[0,-64,70]];for(let i=0;i<n&&i<11;i++)s+=_e102nut(pos[i][0],pos[i][1]+Math.sin(T*2+i)*1.2,19,pos[i][2]);
  return `<g transform="translate(0,16)"><path d="M-80 -2 H80 Q76 62 40 72 H-40 Q-76 62 -80 -2Z" fill="${C.brown}" ${st()}/><path d="M-60 10 H60" stroke="#B88357" stroke-width="5" stroke-linecap="round" opacity=".7"/>${s}<path d="M-80 -2 H80" ${st()}/></g>`};
P.e102_nutsbag=(o,T,k)=>{let s='';for(let i=0;i<9;i++)s+=_e102nut(-58+i*14,-92+(i%3)*-16+Math.sin(T*2+i)*1.5,20,i*40-80);return `<g>${s}<path d="M-82 -82 L-64 -112 L-40 -96 L-18 -118 L10 -98 L38 -116 L60 -94 L84 -82 L92 104 Q92 118 78 118 H-78 Q-92 118 -92 104Z" fill="#D9A867" ${st()}/><path d="M-82 -82 H84" ${st()} fill="none"/><rect x="-52" y="-30" width="104" height="80" rx="14" fill="${C.cream}" ${st(C.navy,4)}/>${_e102nut(0,26,24,-30)}${_e102tx('NUTS',0,-4,26)}</g>`};
P.e102_walker=(o,T,k)=>{const s=Math.sin(T*4.4),c=o.c||'#4DA3D8',sh=o.shoe||C.red;const leg=(a,col)=>`<g transform="translate(0,40) rotate(${a})"><line x1="0" y1="0" x2="0" y2="64" ${st(C.navy,16)}/><line x1="0" y1="0" x2="0" y2="64" ${st(col,9)}/><path d="M-5 64 H22 Q30 64 30 72 H-5Z" fill="${sh}" ${st(C.navy,4)}/></g>`;const arm=(a)=>`<g transform="translate(0,-18) rotate(${a})"><line x1="0" y1="0" x2="0" y2="46" ${st(C.navy,14)}/><line x1="0" y1="0" x2="0" y2="46" ${st(c,8)}/><circle cy="48" r="7" fill="#E3AE82" ${st(C.navy,3)}/></g>`;
  return `<g><ellipse cx="0" cy="116" rx="70" ry="9" fill="#000" opacity=".13"/>${leg(-s*30,'#34495E')}${arm(s*34)}<rect x="-20" y="-34" width="40" height="86" rx="18" fill="${c}" ${st()}/>${leg(s*30,'#34495E')}${arm(-s*34)}<rect x="-8" y="-52" width="16" height="22" fill="#E3AE82" ${st(C.navy,4)}/><circle cx="2" cy="-68" r="26" fill="#E3AE82" ${st()}/><path d="M-24 -72 Q-22 -98 4 -96 Q28 -92 28 -68 Q10 -84 -24 -72Z" fill="${o.hc||'#222'}" ${st(C.navy,4)}/></g>`};
