  const items=[[-50,-12,'b'],[-20,-4,'b'],[24,-10,'b'],[52,-4,'b'],[-34,-20,'c'],[8,-18,'c'],[38,-20,'t'],[-4,-6,'b'],[66,-14,'b']].map(([x,y,t])=>t==='b'?`<ellipse cx="${x}" cy="${y}" rx="9" ry="6" fill="#9E3B2E" ${st(C.navy,2.5)}/>`:t==='c'?`<circle cx="${x}" cy="${y}" r="8" fill="${C.orange}" ${st(C.navy,2.5)}/>`:`<circle cx="${x}" cy="${y}" r="7" fill="${C.red}" ${st(C.navy,2.5)}/>`).join('');
