P.e103_helpers=(o,T)=>`<g><g transform="translate(-86,14) scale(.6)">${P.person({c:'#D96C8B',hair:'long',hc:'#3A2A22',ph:0},T)}</g><g transform="translate(0,14) scale(.6)">${_e103officer({ph:1},T)}</g><g transform="translate(86,14) scale(.6)">${_e103man({c:'#9C7BB8',hair:'bun',hc:'#D9D9D9',ph:2},T,'')}</g>${[-86,0,86].map((x,i)=>`<g transform="translate(${x},${-70+Math.sin(T*3+i)*3}) scale(.42)"><path d="${heartPath}" fill="${C.red}" ${st()}/></g>`).join('')}</g>`;
