  if(hair==='long')h=`<path d="M-40 -40 Q-44 -92 0 -92 Q44 -92 40 -40 L46 20 L28 22 L28 -34 L-28 -34 L-28 22 L-46 20Z" fill="${hc}" ${st()}/>`;
  else if(hair==='bun')h=`<circle cx="0" cy="-102" r="16" fill="${hc}" ${st()}/><path d="M-36 -52 Q-38 -92 0 -92 Q38 -92 36 -52 Q0 -70 -36 -52Z" fill="${hc}" ${st()}/>`;
  else if(hair==='none')h='';
  else h=`<path d="M-36 -54 Q-40 -92 0 -92 Q40 -92 36 -54 Q10 -72 -36 -54Z" fill="${hc}" ${st()}/>`;
