/* white shirt + black vest + red bow tie (waiter) */
const _e104wtorso=`<path d="M-62 108 L-62 36 Q-62 -4 0 -4 Q62 -4 62 36 L62 108 Z" fill="#F6F2E8" ${st()}/><path d="M-62 108 V40 Q-62 4 -36 -2 L-15 -4 L-24 44 L-26 108Z" fill="#2B3036" ${st()}/><path d="M62 108 V40 Q62 4 36 -2 L15 -4 L24 44 L26 108Z" fill="#2B3036" ${st()}/><path d="M-14 -4 L0 22 L14 -4" fill="none" ${st(C.navy,4)}/>`;
const _e104bow=`<path d="M0 6 L-17 -2 V14Z M0 6 L17 -2 V14Z" fill="${C.red}" ${st(C.navy,3)}/><circle cx="0" cy="6" r="4.5" fill="#A93C3A" ${st(C.navy,2.5)}/>`;
const _e104waiter=(o,T)=>_e104man({torso:_e104wtorso,hair:'short',hc:'#222',...o},T,_e104bow);
const _e104chefhat=`<path d="M-30 -78 Q-50 -98 -32 -116 Q-24 -138 0 -128 Q24 -138 32 -116 Q50 -98 30 -78Z" fill="#fff" ${st()}/><rect x="-33" y="-86" width="66" height="20" rx="5" fill="#fff" ${st()}/><path d="M-12 -112 q0 14 -2 20 M12 -112 q0 14 2 20" fill="none" ${st('#C8D2DA',3)}/>`;
const _e104chef=(o,T)=>{const an=o.angry,p=an?(T*3)%1:0;let pf='';if(an)for(let i=0;i<3;i++){const ph=(T*1.8+i/3)%1;pf+=`<g opacity="${f(1-ph)}" transform="translate(${(i-1)*60},${f(-150-ph*30)}) scale(${f(.5+ph*.5)})"><circle r="16" fill="#E86A5C" ${st(C.red,3)}/><circle cx="16" cy="-6" r="11" fill="#E86A5C" ${st(C.red,3)}/></g>`}
  return `<g>${_e104man({torso:`<path d="M-62 108 L-62 36 Q-62 -4 0 -4 Q62 -4 62 36 L62 108 Z" fill="#fff" ${st()}/><path d="M-12 -4 L0 20 L12 -4" fill="none" ${st(C.navy,4)}/><path d="M0 22 V108" ${st('#C8D2DA',3.5)}/><circle cx="-12" cy="46" r="5" fill="#C8D2DA" ${st(C.navy,2.5)}/><circle cx="-12" cy="72" r="5" fill="#C8D2DA" ${st(C.navy,2.5)}/><circle cx="12" cy="46" r="5" fill="#C8D2DA" ${st(C.navy,2.5)}/><circle cx="12" cy="72" r="5" fill="#C8D2DA" ${st(C.navy,2.5)}/>`,hair:'none',...o},T,`<path d="M-17 4 L0 22 L17 4 L10 -2 L0 8 L-10 -2Z" fill="${C.red}" ${st(C.navy,3)}/>${_e104chefhat}`)}${pf}${an?`<path d="M-96 -30 l22 8 M-100 -4 l24 2 M96 -30 l-22 8 M100 -4 l-24 2" ${st(C.red,5)} opacity="${f(.5+.5*Math.sin(T*9))}"/>`:''}</g>`};
const _e104manager=(o,T)=>_e104man({c:'#2B3D48',hair:'short',hc:'#9AA0A6',...o},T,`<path d="M-30 -2 L0 44 L30 -2 L14 -6 L0 14 L-14 -6Z" fill="#fff" ${st(C.navy,3)}/><path d="M-5 14 L5 14 L8 54 L0 62 L-8 54Z" fill="${C.red}" ${st(C.navy,3)}/><rect x="22" y="48" width="30" height="16" rx="3" fill="${C.cream}" ${st(C.navy,3)}/><line x1="27" y1="56" x2="47" y2="56" ${st('#9AA7B0',3)}/>`);
const _e104boss=(o,T)=>{const an=o.angry;let pf='';if(an)for(let i=0;i<3;i++){const ph=(T*1.8+i/3)%1;pf+=`<g opacity="${f(1-ph)}" transform="translate(${(i-1)*62},${f(-124-ph*30)}) scale(${f(.5+ph*.5)})"><circle r="16" fill="#E86A5C" ${st(C.red,3)}/><circle cx="16" cy="-6" r="11" fill="#E86A5C" ${st(C.red,3)}/></g>`}
  return `<g>${_e104man({c:'#4B3F73',hair:'long',hc:'#2B1D1A',...o},T,`<path d="M-26 -2 L0 40 L26 -2 L12 -6 L0 10 L-12 -6Z" fill="#fff" ${st(C.navy,3)}/><path d="M-10 -4 L0 28 L10 -4" fill="none" ${st(C.navy,3.5)}/><circle cx="-34" cy="46" r="4.5" fill="${C.gold}" ${st(C.navy,2)}/>`)}${pf}</g>`};
const _e104msuit=(o,T)=>_e104man({c:'#2B3540',hair:'bun',hc:'#2A1D18',...o},T,`<path d="M-24 -2 L0 40 L24 -2 L12 -6 L0 8 L-12 -6Z" fill="#fff" ${st(C.navy,3)}/>`);
const _e104yellburst=(o,T)=>{let pts='';for(let i=0;i<16;i++){const a=i/16*Math.PI*2,r=i%2?64:98;pts+=`${f(Math.cos(a)*r)},${f(Math.sin(a)*r)} `}
  return `<g transform="rotate(${f(Math.sin(T*9)*3)}) scale(${f(1+.05*Math.sin(T*10))})"><polygon points="${pts}" fill="${C.red}" ${st()}/><text y="22" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${o.fs||70}" fill="#fff">${o.t||'!!!'}</text></g>`};
