P.e104_boss=(o,T)=>`<g>${_e104boss(o,T)}</g>`;
P.e104_msuit=(o,T)=>`<g>${_e104msuit(o,T)}</g>`;
/* plate with rice, chicken, vegetables (hot = steam, cold = blue tint) */
const _e104plate=(o,T)=>{o=o||{};let food='',fx='';
  if(!o.empty)food=`<ellipse cx="-18" cy="4" rx="26" ry="14" fill="#fff" ${st(C.navy,3)}/><g fill="#E3D9BF"><circle cx="-26" cy="0" r="1.8"/><circle cx="-14" cy="-2" r="1.8"/><circle cx="-20" cy="6" r="1.8"/><circle cx="-8" cy="6" r="1.8"/></g><path d="M6 6 q4 -18 26 -16 q16 4 10 16 q-8 12 -26 8z" fill="#C97B3B" ${st(C.navy,3)}/><path d="M36 -6 l10 -6 M38 -2 l12 -2" ${st('#F0E6CC',5)}/><circle cx="-4" cy="18" r="7" fill="#5DAA55" ${st(C.navy,2.5)}/><circle cx="8" cy="22" r="6" fill="#7BC25F" ${st(C.navy,2.5)}/><circle cx="-34" cy="20" r="6" fill="#E8793A" ${st(C.navy,2.5)}/>`;
  if(o.hot)for(let i=0;i<3;i++){const ph=(T*.9+i/3)%1;fx+=`<path d="M${-30+i*28} ${f(-14-ph*34)} q-8 -10 0 -20 t0 -20" fill="none" ${st('#9AA7B0',4.5)} opacity="${f(1-ph)}"/>`}
  if(o.cold)fx=`<g fill="#BFE3F2" ${st(C.blue,2.5)}><path d="M-40 -20 l8 -14 l8 14z" transform="translate(0,${f(Math.sin(T*3)*1.5)})"/><path d="M-8 -22 l8 -16 l8 16z"/><path d="M26 -20 l8 -14 l8 14z"/></g>`;
  return `<g>${_e104sh(0,30,76,9)}<ellipse cx="0" cy="10" rx="78" ry="28" fill="${o.cold?'#DCEBF3':'#fff'}" ${st()}/><ellipse cx="0" cy="8" rx="54" ry="17" fill="${o.cold?'#CFE1EC':'#EEF2F5'}" stroke="#C8D2DA" stroke-width="3"/>${food}${fx}</g>`};
