/* four plates fall from the waiter's arm (k-animated) */
P.e104_drop=(o,T,k)=>{const p=o.still?1:clamp((k-.6)/1.2);let s='',m='';
  for(let i=0;i<4;i++){const q=ease(clamp(p*1.4-i*.1)),x0=36,y0=-40-i*15,x1=-6+i*46,y1=70+(i%2)*8,x=x0+(x1-x0)*q,y=y0+(y1-y0)*q-Math.sin(q*Math.PI)*28,r=q*(i%2?200:-160);
    s+=`<g transform="translate(${f(x)},${f(y)}) rotate(${f(r)}) scale(.4)">${_e104plate({empty:q>.98},T)}</g>`}
  if(p>.95){const a=ease((p-.95)/.05);m=`<g opacity="${f(a)}"><g fill="#E3D9BF" ${st(C.navy,2)}>${[-6,18,40,64,86,108,128].map((x,i)=>`<ellipse cx="${x}" cy="${78+(i%3)*7}" rx="8" ry="4"/>`).join('')}</g><path d="M40 84 q4 -12 18 -9 q10 4 4 11z" fill="#C97B3B" ${st(C.navy,2.5)}/><circle cx="96" cy="86" r="5" fill="#5DAA55" ${st(C.navy,2)}/><circle cx="12" cy="88" r="5" fill="#E8793A" ${st(C.navy,2)}/></g>`}
  const arm=p<.3?_e104arm(-34,58,34,-8,'#F6F2E8',26):_e104arm(-34,58,6,70,'#F6F2E8',26);
  return `<g><rect x="-132" y="96" width="264" height="10" rx="5" fill="#C9A878" ${st()}/><g transform="translate(-70,20) scale(.74)">${_e104waiter({still:1},T)}</g>${arm}${m}${s}</g>`};
/* an arm in a sleeve with a hand at its end */
const _e104arm=(x1,y1,x2,y2,col,w)=>`<path d="M${x1} ${y1} L${x2} ${y2}" stroke="${C.navy}" stroke-width="${(w||36)+7}" stroke-linecap="round"/><path d="M${x1} ${y1} L${x2} ${y2}" stroke="${col||'#F6F2E8'}" stroke-width="${w||36}" stroke-linecap="round"/><circle cx="${x2}" cy="${y2}" r="${(w||36)*.5}" fill="${_e104sk}" ${st(C.navy,4)}/>`;
/* waiter carrying a tray with a plate and a drink */
P.e104_serve=(o,T)=>{const bob=Math.sin(T*2)*2;
  return `<g><g transform="translate(-52,18) scale(.8)">${_e104waiter({still:1},T)}</g><g transform="translate(0,${f(bob)})"><path d="M-10 70 L40 8" stroke="${C.navy}" stroke-width="40" stroke-linecap="round"/><path d="M-10 70 L40 8" stroke="#F6F2E8" stroke-width="33" stroke-linecap="round"/><ellipse cx="62" cy="-2" rx="84" ry="13" fill="#B9C6CE" ${st()}/><circle cx="50" cy="8" r="13" fill="${_e104sk}" ${st(C.navy,3.5)}/><g transform="translate(30,-24) scale(.5)">${_e104plate({hot:o.hot,cold:o.cold},T)}</g><g transform="translate(106,-30)"><path d="M-12 -18 H12 L9 20 H-9Z" fill="#CFE6F2" ${st(C.navy,3.5)}/><path d="M-10 -4 H10 L9 20 H-9Z" fill="#6FB6E3"/></g></g></g>`};
/* tables: wiping a table with a cloth */
P.e104_clean=(o,T)=>{const wx=Math.sin(T*3.2)*34,sp=Math.max(0,Math.sin(T*3.2+1.2));
  return `<g>${_e104sh(0,92,118,10)}<path d="M-100 30 H100 L88 48 H-88Z" fill="#E86A5C" ${st()}/><path d="M-90 30 H90" ${st('#fff',4)} stroke-dasharray="14 14" opacity=".8"/><rect x="-82" y="48" width="12" height="46" rx="3" fill="${C.brown}" ${st()}/><rect x="70" y="48" width="12" height="46" rx="3" fill="${C.brown}" ${st()}/><g transform="translate(${f(wx)},0)">${_e104arm(48,-46,6,18,'#F6F2E8',26)}<rect x="-24" y="14" width="42" height="18" rx="6" fill="#4DA3D8" ${st()} transform="rotate(-8 0 22)"/></g><g opacity="${f(sp)}">${[[-70,8,1],[-40,-6,.8],[56,4,1],[84,-10,.7]].map(a=>`<polygon points="0,-10 3,-3 10,0 3,3 0,10 -3,3 -10,0 -3,-3" transform="translate(${a[0]},${a[1]}) scale(${a[2]})" fill="${C.gold}"/>`).join('')}</g><g transform="translate(-88,-14)"><rect x="-10" y="-18" width="20" height="42" rx="6" fill="#9AD0E8" ${st()}/><rect x="-6" y="-30" width="12" height="14" rx="3" fill="${C.red}" ${st(C.navy,3)}/></g></g>`};
/* kitchen: stove with steaming pot and pan */
P.e104_kitchen=(o,T)=>{let s='';for(let i=0;i<3;i++){const ph=(T*.9+i/3)%1;s+=`<path d="M${-60+i*18} ${f(-40-ph*40)} q-9 -12 0 -24 t0 -24" fill="none" ${st('#9AA7B0',5)} opacity="${f(1-ph)}"/>`}
  const fl=(x)=>`<path d="M${x} 62 q-9 -12 0 -24 q3 8 9 10 q2 -8 -2 -14 q14 10 8 28z" fill="${C.orange}" ${st(C.red,2.5)} transform="scale(${f(1+.1*Math.sin(T*9+x))})" />`;
  return `<g><rect x="-120" y="52" width="240" height="56" rx="8" fill="#8E9AA3" ${st()}/><rect x="-120" y="44" width="240" height="14" rx="5" fill="#B9C6CE" ${st()}/><circle cx="-80" cy="84" r="10" fill="${C.navy}"/><circle cx="-40" cy="84" r="10" fill="${C.navy}"/><circle cx="50" cy="84" r="10" fill="${C.navy}"/><g transform="translate(0,${f(-4)})"><rect x="-96" y="-30" width="68" height="76" rx="8" fill="#6F7F8A" ${st()}/><rect x="-102" y="-40" width="80" height="14" rx="6" fill="#8A9BA6" ${st()}/><path d="M-100 -4 H-124" ${st(C.navy,8)}/>${s}</g><g transform="translate(50,0)"><path d="M-44 36 H44 L48 20 H-48Z" fill="#3C4A53" ${st()}/><path d="M48 24 L100 6" ${st(C.brown,10)}/><g transform="translate(-14,6)">${fl(-10)}${fl(14)}</g></g></g>`};
/* family restaurant front */
const _e104front=(o,T,inner,sign)=>{let aw='';for(let i=0;i<8;i++)aw+=`<path d="M${-120+i*30} -34 h30 v34 q-15 14 -30 0z" fill="${i%2?'#fff':o.a}" ${st(C.navy,3.5)}/>`;
  return `<g><rect x="-112" y="-34" width="224" height="132" fill="#F0DDB4" ${st()}/><rect x="-112" y="-86" width="224" height="52" rx="6" fill="${o.b}" ${st()}/>${sign}<rect x="-96" y="10" width="112" height="74" rx="6" fill="#CFE6F2" ${st()}/><g clip-path="url(#e104_fw${o.id})">${inner}</g><rect x="-96" y="10" width="112" height="74" rx="6" fill="none" ${st()}/><line x1="-40" y1="10" x2="-40" y2="84" ${st(C.navy,3)}/><rect x="36" y="14" width="56" height="84" rx="4" fill="${C.brown}" ${st()}/><rect x="44" y="22" width="40" height="30" rx="3" fill="#A9743F" ${st(C.navy,3)}/><circle cx="46" cy="64" r="4" fill="${C.gold}" ${st(C.navy,2)}/>${aw}<clipPath id="e104_fw${o.id}"><rect x="-96" y="10" width="112" height="74" rx="6"/></clipPath></g>`};
P.e104_rest=(o,T)=>{const tb=(x)=>`<ellipse cx="${x}" cy="62" rx="22" ry="7" fill="#fff" ${st(C.navy,3)}/><rect x="${x-3}" y="62" width="6" height="22" fill="${C.brown}"/><circle cx="${x}" cy="40" r="9" fill="${_e104sk}" ${st(C.navy,3)}/><rect x="${x-10}" y="48" width="20" height="14" rx="6" fill="${x<-40?C.blue:C.orange}" ${st(C.navy,3)}/>`;
  const sign=`<ellipse cx="-14" cy="-60" rx="20" ry="7" fill="#fff" ${st(C.navy,3)}/><path d="M-50 -64 v20 M-56 -64 v8 M-44 -64 v8 M-56 -56 q6 4 12 0" fill="none" ${st(C.cream,4)}/><path d="M26 -66 q10 4 6 24 M26 -66 v26" fill="none" ${st(C.cream,4)}/><circle cx="12" cy="-60" r="0"/><path d="M60 -50 h40" ${st(C.cream,4)}/>`;
  return `<g>${_e104sh(0,102,122,9)}${_e104front({a:C.red,b:'#3E7CB1',id:'r'},T,tb(-70)+tb(-12),sign)}<g transform="translate(64,36) rotate(${f(Math.sin(T*2)*4)})"><rect x="-17" y="-10" width="34" height="18" rx="4" fill="${C.cream}" ${st(C.navy,3)}/><text y="4" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="11" fill="#2F7C57">OPEN</text></g></g>`};
P.e104_shop=(o,T)=>{const items=`<rect x="-90" y="52" width="100" height="6" fill="${C.brown}"/><rect x="-86" y="30" width="20" height="22" rx="3" fill="#E8793A" ${st(C.navy,2.5)}/><rect x="-60" y="22" width="18" height="30" rx="3" fill="#4DA3D8" ${st(C.navy,2.5)}/><rect x="-36" y="34" width="22" height="18" rx="3" fill="#8E6BB5" ${st(C.navy,2.5)}/><rect x="-8" y="26" width="16" height="26" rx="3" fill="#F0C64A" ${st(C.navy,2.5)}/><rect x="-90" y="78" width="100" height="6" fill="${C.brown}"/>`;
  const sign=`<g transform="translate(0,-60)"><path d="M-40 6 h80 v-6 h-80z M-34 -14 h68 l8 14 h-84z" fill="${C.cream}" ${st(C.navy,3)}/></g>`;
  return `<g>${_e104sh(0,102,122,9)}${_e104front({a:'#4F9A63',b:'#E6A744',id:'s'},T,items,sign)}<g transform="translate(64,36) rotate(${f(Math.sin(T*2)*4)})"><rect x="-17" y="-10" width="34" height="18" rx="4" fill="${C.cream}" ${st(C.navy,3)}/><text y="4" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="11" fill="#2F7C57">OPEN</text></g></g>`};
/* window with a paper sign: WAITER WANTED */
P.e104_wanted=(o,T)=>{const sw=Math.sin(T*1.6)*1.5;
  return `<g><rect x="-122" y="-100" width="244" height="200" rx="10" fill="${C.brown}" ${st()}/><rect x="-108" y="-86" width="216" height="172" rx="4" fill="#CFE6F2" ${st(C.navy,3)}/><path d="M-108 -86 L-30 -86 L-108 -10Z M30 86 L108 86 L108 20Z" fill="#fff" opacity=".35"/><line x1="0" y1="-86" x2="0" y2="86" ${st(C.brown,6)}/><line x1="-108" y1="0" x2="108" y2="0" ${st(C.brown,6)}/><g transform="translate(0,2) rotate(${f(-3+sw)})"><rect x="-84" y="-58" width="168" height="116" rx="8" fill="${C.cream}" ${st()}/><rect x="-74" y="-48" width="148" height="96" rx="4" fill="none" ${st(C.red,4)}/><text y="-6" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" fill="${C.navy}">WAITER</text><text y="38" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" fill="${C.red}">WANTED</text><circle cx="0" cy="-58" r="7" fill="${C.red}" ${st(C.navy,3)}/></g></g>`};
/* uniform: white shirt, black trousers, black jacket */
const _e104uni=()=>`<g transform="translate(-92,0)"><path d="M-34 -50 L-14 -58 Q0 -42 14 -58 L34 -50 L56 -14 L38 -2 L28 -14 V50 H-28 V-14 L-38 -2 L-56 -14Z" fill="#fff" ${st()}/><path d="M-14 -58 Q0 -42 14 -58" fill="none" ${st(C.navy,4)}/><path d="M0 -42 V50" ${st('#C8D2DA',3)}/></g><g transform="translate(0,6)"><path d="M-30 -56 H30 L36 54 H10 L0 -8 L-10 54 H-36Z" fill="#2B3036" ${st()}/><line x1="-30" y1="-42" x2="30" y2="-42" ${st('#555E66',3)}/></g><g transform="translate(92,0)"><path d="M-34 -52 L-16 -60 L0 -20 L16 -60 L34 -52 L58 -14 L40 0 L30 -14 V52 H-30 V-14 L-40 0 L-58 -14Z" fill="#2B3036" ${st()}/><path d="M-16 -60 L0 -20 L16 -60" fill="#F6F2E8" ${st(C.navy,3)}/><circle cx="-6" cy="14" r="4" fill="#555E66"/><circle cx="-6" cy="34" r="4" fill="#555E66"/></g>`;
P.e104_uni=(o,T)=>{const sw=Math.sin(T*1.4)*1.5;return `<g transform="rotate(${f(sw)})"><rect x="-130" y="-92" width="260" height="8" rx="4" fill="${C.brown}" ${st()}/>${_e104uni()}</g>`};
/* Adam in a jacket that is far too big */
P.e104_toobig=(o,T)=>{const bob=Math.sin(T*2)*1.5;
  const torso=`<path d="M-104 112 Q-112 30 -92 14 Q-60 -4 -34 -4 L0 22 L34 -4 Q60 -4 92 14 Q112 30 104 112Z" fill="#2B3036" ${st()}/><path d="M-26 -2 L0 40 L26 -2" fill="#fff" ${st(C.navy,3.5)}/><path d="M-26 -2 L-60 -2 L-12 52 L0 40Z M26 -2 L60 -2 L12 52 L0 40Z" fill="#3A4249" ${st(C.navy,3.5)}/>`;
  return `<g><g transform="translate(0,${f(bob)})"><path d="M-96 20 Q-130 70 -118 140 L-90 140 Q-86 80 -76 40Z M96 20 Q130 70 118 140 L90 140 Q86 80 76 40Z" fill="#2B3036" ${st()}/>${_e104man({torso,hair:'short',hc:'#222',c:'#2B3036',still:1},T,'')}</g><g transform="translate(70,28) rotate(8)"><path d="M0 -24 L-10 -40" ${st(C.navy,2.5)}/><rect x="-22" y="-24" width="44" height="30" rx="5" fill="${C.cream}" ${st(C.navy,3.5)}/><text y="-2" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="19" fill="${C.red}">XXL</text></g></g>`};
/* order pad and pencil */
P.e104_pad=(o,T)=>{const w=Math.sin(T*5)*3;let r='';for(let i=0;i<4;i++)r+=`<path d="M-44 ${-34+i*30} q10 -8 20 0 t20 0 t22 0 t18 0" fill="none" ${st('#7A8A94',3.5)}/>`;
  return `<g transform="rotate(-6)"><rect x="-62" y="-82" width="124" height="164" rx="12" fill="${C.cream}" ${st()}/><rect x="-62" y="-82" width="124" height="26" rx="12" fill="${C.red}" ${st()}/>${[-40,-20,0,20,40].map(x=>`<circle cx="${x}" cy="-70" r="5" fill="${C.cream}" ${st(C.navy,2.5)}/>`).join('')}<g transform="translate(0,-4)">${r}</g><g transform="translate(${f(30+w)},${f(34-w)}) rotate(40)"><rect x="-6" y="-60" width="12" height="76" fill="#F0C64A" ${st(C.navy,3.5)}/><path d="M-6 16 L0 32 L6 16Z" fill="#E3AE82" ${st(C.navy,3)}/><path d="M-6 -60 h12 v-10 a6 6 0 0 0 -12 0z" fill="#E86A5C" ${st(C.navy,3)}/></g></g>`};
/* tray with drinks */
P.e104_drinks=(o,T)=>{const g=(x,col,h)=>`<g transform="translate(${x},0)"><path d="M-17 ${-h} H17 L13 30 H-13Z" fill="#E3F1F8" ${st(C.navy,3.5)}/><path d="M-15 ${-h+h*.35} H15 L13 30 H-13Z" fill="${col}" opacity=".9"/><rect x="-11" y="${-h+4}" width="5" height="${h*.6}" rx="2.5" fill="#fff" opacity=".6"/></g>`;
  return `<g>${_e104sh(0,66,104,9)}<ellipse cx="0" cy="44" rx="108" ry="22" fill="#B9C6CE" ${st()}/><ellipse cx="0" cy="40" rx="92" ry="14" fill="#DCE5EA"/>${g(-56,'#F2994A',64)}${g(0,'#6FB6E3',74)}${g(56,'#E86A5C',58)}</g>`};
/* big number plaque */
P.e104_num=(o,T)=>{const t=String(o.t),fs=t.length>5?56:t.length>3?84:t.length>2?100:120;return `<g transform="scale(${f(1+.03*Math.sin(T*3))})"><rect x="-116" y="-74" width="232" height="${o.sub?168:148}" rx="30" fill="${C.gold}" ${st()}/><rect x="-102" y="-60" width="204" height="${o.sub?140:120}" rx="22" fill="none" ${st(C.goldD,3)}/><text x="0" y="${o.sub?18:26}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${fs}" fill="${C.navy}">${t}</text>${o.sub?`<text x="0" y="62" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${String(o.sub).length>8?24:32}" fill="${C.goldD}" letter-spacing="${String(o.sub).length>8?2:3}">${o.sub}</text>`:''}</g>`};
/* banknote */
const _e104bill=(x,y,rot,s)=>`<g transform="translate(${x},${y}) rotate(${rot}) scale(${s||1})"><rect x="-58" y="-30" width="116" height="60" rx="7" fill="#7BC27F" ${st()}/><rect x="-50" y="-22" width="100" height="44" rx="4" fill="none" stroke="#3E8E4F" stroke-width="3"/><circle r="17" fill="#9AD49C" ${st('#3E8E4F',3)}/><text y="8" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="#2F7C45">$</text></g>`;
const _e104coin=(x,y,s)=>`<g transform="translate(${x},${y}) scale(${s||1})"><circle r="16" fill="${C.gold}" ${st(C.navy,3.5)}/><circle r="10" fill="none" ${st(C.goldD,2.5)}/></g>`;
P.e104_cash=(o,T)=>{const n=o.n||3;let s='';for(let i=0;i<n;i++)s+=_e104bill(f((i-(n-1)/2)*14),f(24-i*22),f((i-(n-1)/2)*7));return `<g transform="translate(0,${f(Math.sin(T*2)*3)})">${_e104sh(0,76,80,8)}${s}${_e104coin(-70,66,1.1)}${_e104coin(-48,72,1.1)}</g>`};
/* salary vs tips: tall pile for tips, small one for salary */
P.e104_vs=(o,T,k)=>{const pr=ease(k/1.2);const pile=(x,n,lab)=>{let s='';for(let i=0;i<n;i++)s+=`<g transform="translate(${x},${f(76-i*17*pr)})"><ellipse rx="40" ry="11" cy="6" fill="${C.goldD}" ${st(C.navy,3)}/><ellipse rx="40" ry="11" fill="${C.gold}" ${st(C.navy,3)}/></g>`;return s+`<text x="${x}" y="112" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="${C.navy}">${lab}</text>`};
  return `<g><line x1="-130" y1="86" x2="130" y2="86" ${st(C.navy,4)}/>${pile(-62,2,'SALARY')}${pile(62,7,'TIPS')}<g transform="translate(62,${f(-82-Math.sin(T*3)*2)}) scale(.8)">${_e104bill(0,0,-6)}</g></g>`};
/* saucer with tip */
P.e104_tip=(o,T)=>`<g>${_e104sh(0,60,90,9)}<ellipse cx="0" cy="44" rx="96" ry="22" fill="#fff" ${st()}/><ellipse cx="0" cy="42" rx="70" ry="14" fill="#EEF2F5" stroke="#C8D2DA" stroke-width="3"/>${_e104bill(-12,18,-8,.9)}${_e104coin(48,34,.9)}${_e104coin(66,40,.8)}${_e104coin(30,46,.8)}<g transform="translate(0,${f(-48+Math.sin(T*3)*3)})"><rect x="-50" y="-26" width="100" height="50" rx="12" fill="${C.gold}" ${st()}/><text y="12" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="40" fill="${C.navy}">TIP</text></g></g>`;
/* coins stack with a green arrow up */
P.e104_raise=(o,T,k)=>{const r=ease(k/1);let s='';for(let i=0;i<4;i++)s+=`<g transform="translate(-34,${f(70-i*22*r)})"><ellipse rx="52" ry="14" cy="7" fill="${C.goldD}" ${st(C.navy,3.5)}/><ellipse rx="52" ry="14" fill="${C.gold}" ${st(C.navy,3.5)}/></g>`;
  return `<g>${s}<g transform="translate(70,${f(-4-Math.sin(T*3)*5)})"><path d="M0 -70 L40 -20 H14 V50 H-14 V-20 H-40Z" fill="#4F9A63" ${st()}/></g></g>`};
/* climbing steps to a star: progress */
P.e104_climb=(o,T,k)=>{const q=Math.min(3,Math.floor(k*1.1)),fr=(k*1.1)%1;let s='';for(let i=0;i<4;i++)s+=`<rect x="${-112+i*56}" y="${74-i*36}" width="56" height="${36*(i+1)+30}" fill="${i%2?'#D9C9A2':'#E7D3A6'}" ${st(C.navy,4)}/>`;
  const pi=Math.min(3,q),px=-84+pi*56,py=62-pi*36;
  return `<g>${s}<g transform="translate(${px},${py-20}) scale(.5)">${P.person({c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g><g transform="translate(94,-62) scale(.34)">${P.star({},T)}</g></g>`};
/* task notes: ten sticky notes */
P.e104_tasks=(o,T)=>{const cs=['#F6D26B','#F2994A','#9AD0E8','#9AD49C','#E88CA2'];let s='';for(let i=0;i<10;i++){const c=i%5,r=Math.floor(i/5),x=-92+c*46,y=-42+r*64,ro=((i*37)%9)-4;s+=`<g transform="translate(${x},${y}) rotate(${ro})"><rect x="-20" y="-24" width="40" height="46" rx="3" fill="${cs[(i+r*2)%5]}" ${st(C.navy,3)}/><path d="M-12 -10 h24 M-12 0 h24 M-12 10 h14" ${st('#6B5B3E',2.5)}/></g>`}return `<g>${s}</g>`};
/* mail: send a report. all:1 = the whole company receives it (tiny people grid) */
P.e104_send=(o,T,k)=>{const all=o.all,cols=all?9:4,rows=all?5:2,x0=all?-96:-60;let g='';const cs=['#E86A5C','#4DA3D8','#4F9A63','#F2994A','#8E6BB5','#F0C64A'];let n=0;
  for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){const t=ease((k-.5-(r*cols+c)*(all?.03:.12))/.25);g+=`<g transform="translate(${x0+c*(all?24:40)},${(all?10:30)+r*(all?24:46)}) scale(${f((all?.9:1.5)*t+.05)})" opacity="${f(t)}"><circle cy="-8" r="7" fill="${_e104sk}" ${st(C.navy,2)}/><rect x="-8" y="-1" width="16" height="14" rx="6" fill="${cs[(r*3+c)%6]}" ${st(C.navy,2)}/></g>`}
  const fly=ease(k/.7);
  return `<g>${all?`<rect x="-130" y="-8" width="260" height="140" rx="12" fill="#E8EEF1" ${st(C.navy,4)}/>`:''}<g transform="translate(${f(all?0:-84)},${f(-70+fly*(all?0:10))})"><rect x="-44" y="-28" width="88" height="58" rx="6" fill="${C.cream}" ${st()}/><path d="M-44 -26 L0 8 L44 -26" fill="none" ${st(C.navy,4)}/></g>${all?'':`<path d="M-30 -52 L28 -4" ${st(C.red,4)} stroke-dasharray="3 9"/><path d="M-30 -56 L28 -22" ${st(C.red,0)}/>`}${g}</g>`};
/* grid of 20 replies: only 2 answered */
P.e104_replies=(o,T,k)=>{let s='';for(let i=0;i<20;i++){const c=i%5,r=Math.floor(i/5),x=-100+c*50,y=-72+r*48,on=o.on?o.on.includes(i):(i===6||i===16),t=ease((k-.2-i*.05)/.2);s+=`<g transform="translate(${x},${y}) scale(${f(t)})"><rect x="-19" y="-13" width="38" height="26" rx="4" fill="${on?C.gold:'#E8EEF1'}" ${st(on?C.navy:'#9AA7B0',on?3.5:3)}/><path d="M-19 -11 L0 4 L19 -11" fill="none" ${st(on?C.navy:'#9AA7B0',3)}/>${on?`<circle cx="16" cy="-12" r="9" fill="${C.moss}" ${st(C.navy,2.5)}/><path d="M11 -12 l4 4 l7 -8" fill="none" stroke="#fff" stroke-width="3"/>`:''}</g>`}return `<g>${s}</g>`};
/* circle: job needs experience, experience needs a job */
P.e104_circle=(o,T)=>{const r=88,pt=(a)=>[Math.cos(a*Math.PI/180)*r,Math.sin(a*Math.PI/180)*r];const ar=(a0,a1)=>{const p0=pt(a0),p1=pt(a1);return `<path d="M${f(p0[0])} ${f(p0[1])} A${r} ${r} 0 0 1 ${f(p1[0])} ${f(p1[1])}" fill="none" ${st(C.red,10)} stroke-linecap="round"/><polygon points="20,0 -10,-17 -10,17" transform="translate(${f(p1[0])},${f(p1[1])}) rotate(${a1+90})" fill="${C.red}" ${st(C.navy,3)}/>`};
  return `<g><g transform="rotate(${f(T*35)})">${ar(-80,80)}${ar(100,260)}</g><g transform="translate(-34,4) scale(.38)">${P.brief({},T)}</g><g transform="translate(36,2)"><path d="M-12 14 l-8 30 l20 -10 l20 10 l-8 -30" fill="${C.red}" ${st(C.navy,3)}/><circle r="26" fill="${C.gold}" ${st()}/><polygon points="0,-15 4,-5 15,-5 6,2 9,13 0,7 -9,13 -6,2 -15,-5 -4,-5" fill="#fff"/></g></g>`};
P.e104_apply=(o,T,k)=>{const cl=Math.floor(T*1.2)%2;return `<g>${_e104sh(0,98,120,9)}<path d="M-124 88 H124 L108 100 H-108Z" fill="#B9C6CE" ${st()}/><rect x="-100" y="-86" width="200" height="172" rx="12" fill="${C.navy}" ${st()}/><rect x="-88" y="-74" width="176" height="148" rx="4" fill="${C.white}"/><rect x="-88" y="-74" width="176" height="24" fill="#4DA3D8"/><rect x="-76" y="-34" width="88" height="10" rx="5" fill="#C8D2DA"/><rect x="-76" y="-14" width="120" height="10" rx="5" fill="#C8D2DA"/><rect x="-76" y="6" width="100" height="10" rx="5" fill="#C8D2DA"/><rect x="-44" y="32" width="88" height="30" rx="15" fill="${cl?'#E0A92C':C.gold}" ${st()}/><text y="53" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="20" fill="${C.navy}">APPLY</text><path d="M${f(30+Math.sin(T*2)*6)} 66 l0 22 l6 -5 l5 10 l5 -3 l-5 -10 l8 -1z" fill="#fff" ${st(C.navy,2.5)}/></g>`};
/* interview: two interviewers behind a desk, the candidate on the left */
P.e104_interview=(o,T)=>`<g><rect x="-132" y="-84" width="264" height="190" rx="14" fill="#E9E1CC" ${st(C.navy,4)}/><g transform="translate(26,-12) scale(.46)">${_e104manager({still:1},T)}</g><g transform="translate(96,-12) scale(.46)">${_e104boss({still:1},T)}</g><rect x="-6" y="16" width="136" height="24" rx="5" fill="${C.brown}" ${st()}/><rect x="4" y="40" width="116" height="56" fill="#A9743F" ${st()}/><rect x="46" y="4" width="28" height="14" rx="2" fill="#fff" ${st(C.navy,2.5)} transform="rotate(-6 60 10)"/><g transform="translate(-76,18) scale(.56)">${_e104msuit({still:1},T)}</g><rect x="-98" y="56" width="44" height="14" rx="4" fill="#7A5A3A" ${st(C.navy,3)}/></g>`;
/* three interview questions: goals, position, offer */
const _e104target=(s,T)=>`<g transform="scale(${s})"><circle r="60" fill="#fff" ${st()}/><circle r="42" fill="${C.red}" ${st(C.navy,3.5)}/><circle r="24" fill="#fff" ${st(C.navy,3.5)}/><circle r="9" fill="${C.red}" ${st(C.navy,3)}/><path d="M0 0 L58 -58" ${st(C.navy,5)}/><path d="M52 -52 l16 -2 l-8 -10 l-8 -10z" fill="${C.gold}" ${st(C.navy,3)}/></g>`;
P.e104_target=(o,T)=>`<g transform="scale(${f(1+.03*Math.sin(T*3))})">${_e104target(1.4,T)}</g>`;
P.e104_qs=(o,T,k)=>{const rows=[()=>_e104target(.36,T),()=>`<g transform="scale(.3)">${P.brief({},T)}</g>`,()=>`<g transform="scale(.3)">${P.e104_gift({still:1},T)}</g>`];let s='';
  rows.forEach((fn,i)=>{const t=ease((k-.2-i*.45)/.3),y=-70+i*72;s+=`<g transform="translate(0,${f(y+(1-t)*14)})" opacity="${f(t)}"><rect x="-120" y="-30" width="240" height="60" rx="30" fill="#fff" ${st()}/><path d="M-96 30 l-12 18 l30 -18z" fill="#fff" ${st(C.navy,0)}/><g transform="translate(-84,0)">${fn()}</g><text x="30" y="14" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="46" fill="${C.goldD}">?</text></g>`});return `<g>${s}</g>`};
/* three good traits: fast learner, hard worker, good with people */
P.e104_traits=(o,T,k)=>{const cs=[()=>_e104bolt(0,0,.85,C.gold),()=>`<g transform="translate(0,0)">${[-18,0,18].map(y=>`<rect x="-24" y="${y-7}" width="14" height="14" rx="3" fill="#fff" ${st(C.navy,2.5)}/><path d="M-22 ${y} l4 4 l7 -9" fill="none" ${st(C.moss,3)}/><line x1="-4" y1="${y}" x2="24" y2="${y}" ${st('#9AA7B0',3.5)}/>`).join('')}</g>`,()=>`<g transform="translate(-16,6) scale(.3)">${P.person({c:C.blue,hair:'short',hc:'#222',ph:0},T)}</g><g transform="translate(16,6) scale(.3)">${P.person({c:'#E88CA2',hair:'long',hc:'#3A2A22',ph:1},T)}</g>`];let s='';
  cs.forEach((fn,i)=>{const t=ease((k-.2-i*.5)/.3);s+=`<g transform="translate(${-92+i*92},0) scale(${f(.4+.6*t)})" opacity="${f(t)}"><circle r="44" fill="${C.cream}" ${st()}/>${fn()}</g>`});return `<g>${s}</g>`};
/* offer letter with a gold seal */
P.e104_offer=(o,T)=>`<g transform="rotate(${f(Math.sin(T*1.5)*2)})"><rect x="-84" y="-100" width="168" height="200" rx="10" fill="${C.cream}" ${st()}/><text y="-58" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="36" fill="${C.navy}">OFFER</text><path d="M-56 -34 h112 M-56 -12 h112 M-56 10 h80" ${st('#9AA7B0',5)}/><g transform="translate(34,58)"><circle r="26" fill="${C.gold}" ${st()}/><path d="M-12 2 l8 9 l16 -20" fill="none" ${st(C.navy,5)}/></g></g>`;
/* big counting number 1..10 */
P.e104_ten=(o,T,k)=>{const n=Math.min(10,1+Math.floor(k*2.2)),pr=Math.min(1,(k*2.2)/9);return `<g><circle r="96" fill="${C.cream}" ${st()}/><circle r="84" fill="none" ${st('#E3D9BF',10)}/><path d="${(()=>{const a=-Math.PI/2,b=a+pr*Math.PI*1.9999,x1=Math.cos(a)*84,y1=Math.sin(a)*84,x2=Math.cos(b)*84,y2=Math.sin(b)*84;return `M${f(x1)} ${f(y1)} A84 84 0 ${pr>.5?1:0} 1 ${f(x2)} ${f(y2)}`})()}" fill="none" ${st(C.red,10)} stroke-linecap="round"/><text y="${n>9?30:38}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${n>9?88:112}" fill="${C.navy}">${n}</text></g>`};
/* report checked again: paper, magnifier, tick */
P.e104_recheck=(o,T)=>{const mv=Math.sin(T*1.6)*10;return `<g><rect x="-76" y="-96" width="140" height="180" rx="8" fill="#fff" ${st()}/><path d="M-54 -66 h88 M-54 -42 h88 M-54 -18 h60 M-54 6 h88 M-54 30 h70" ${st('#9AA7B0',5)}/><g transform="translate(${f(30+mv)},${f(30+mv*.4)})"><circle r="38" fill="#DDF0F8" fill-opacity=".7" ${st(C.navy,7)}/><path d="M28 28 L58 58" ${st(C.brown,12)}/><path d="M-16 0 l11 12 l22 -26" fill="none" ${st(C.moss,8)}/></g></g>`};
/* manager with a small team */
P.e104_team=(o,T)=>{const n=o.n||3,cs=['#4DA3D8','#F2994A','#4F9A63'],hs=['short','long','short'];let s='';for(let i=0;i<n;i++)s+=`<g transform="translate(${f((i-(n-1)/2)*84)},80) scale(.42)">${P.person({c:cs[i],hair:hs[i],hc:'#3A2A22',ph:i},T)}</g>`;
  return `<g><g transform="translate(0,-48) scale(.55)">${_e104boss({still:1,...o},T)}</g>${s}</g>`};
/* three ordered steps: important task, e-mails, small tasks */
