P.e106_seaplastic=(o,T,k)=>{let b='';for(let i=0;i<6;i++){const ph=((T*.3+i*.17)%1);b+=`<circle cx="${-100+i*40}" cy="${f(100-ph*210)}" r="${3+i%3*2}" fill="none" stroke="#fff" stroke-width="2.5" opacity=".8"/>`}
  return `<g><clipPath id="e106_spc"><rect x="-124" y="-110" width="248" height="236" rx="18"/></clipPath><g clip-path="url(#e106_spc)"><rect x="-124" y="-110" width="248" height="236" fill="#5DB4DC"/><rect x="-124" y="-110" width="248" height="236" fill="#2E6FA8" opacity=".35"/><path d="M-124 -80 q31 -14 62 0 t62 0 t62 0 t62 0" fill="none" stroke="#fff" stroke-width="5" opacity=".8"/>${b}<g transform="translate(${f(-60+Math.sin(T)*10)},20) scale(.42)">${P.e106_fish({c:C.orange},T,k)}</g><g transform="translate(${f(50+Math.sin(T*.8)*12)},60) scale(.34) scale(-1,1)">${P.e106_fish({c:'#F2D14E'},T,k)}</g><g transform="translate(${f(10+Math.sin(T*1.2)*14)},-30) scale(.7)">${_e105pb(60,50,'rgba(255,255,255,.8)',4)}</g><g transform="translate(-70,-52) rotate(-30) scale(.9)">${_e105bottle(0,0,0,'#E3F3FA')}</g><path d="M-124 110 q31 -22 62 0 t62 0 t62 0 t62 0 V126 H-124Z" fill="#EBD7A6"/></g><rect x="-124" y="-110" width="248" height="236" rx="18" fill="none" ${st()}/></g>`};
P.e106_oceanbring=(o,T,k)=>{const ph=(T*.35)%1,x=-90+ph*190;let w='';for(let r=0;r<3;r++)w+=`<path d="M-130 ${20+r*26} q16 -12 32 0 t32 0 t32 0 t32 0 t32 0 t32 0 t32 0 t32 0" fill="none" ${st('#fff',4)} opacity="${f(.9-r*.2)}" transform="translate(${f(Math.sin(T*1.6+r)*10)},0)"/>`;
  return `<g><clipPath id="e106_obc"><rect x="-124" y="-90" width="248" height="200" rx="18"/></clipPath><g clip-path="url(#e106_obc)"><rect x="-124" y="-90" width="248" height="90" fill="${C.sky}"/><rect x="-124" y="0" width="248" height="110" fill="${C.blue}"/><path d="M60 110 L124 14 V110Z" fill="#EBD7A6"/>${w}<g transform="translate(${f(x)},${f(-6+Math.sin(T*3)*4)}) rotate(${f(-60+Math.sin(T*3)*10)})">${_e105bottle(0,0,0,'#E3F3FA')}</g><path d="M-100 -50 Q0 -90 90 -30" fill="none" ${st(C.navy,3.5)} stroke-dasharray="3 9"/><path d="M80 -44 L96 -26 L74 -22Z" fill="${C.navy}"/></g><rect x="-124" y="-90" width="248" height="200" rx="18" fill="none" ${st()}/></g>`};
P.e106_bagpile=(o,T,k)=>{let s='';for(let i=0;i<9;i++){const p=ease((k-i*.1)/.3);s+=`<g transform="translate(${-80+(i%5)*40+(i>4?20:0)},${i>4?30:76}) scale(${f(.4*p)})">${P.e106_garbagebag({},T,k)}</g>`}return `<g>${s}</g>`};

/* ---------- electricity ---------- */
P.e106_bill=(o,T,k)=>{const a=ease((k-.2)/.6),b=ease((k-.6)/.7);
  return `<g><rect x="-96" y="-112" width="192" height="228" rx="12" fill="#fff" ${st()}/><rect x="-96" y="-112" width="192" height="40" rx="12" fill="${C.gold}" ${st()}/><rect x="-96" y="-90" width="192" height="18" fill="${C.gold}"/><path d="M-62 -104 L-76 -86 L-66 -86 L-72 -72 L-52 -92 L-62 -92Z" fill="${C.navy}"/><rect x="-36" y="-96" width="80" height="10" rx="5" fill="${C.navy}" opacity=".5"/><line x1="-76" y1="88" x2="76" y2="88" ${st(C.navy,3)}/><rect x="-52" y="${f(88-a*60)}" width="40" height="${f(a*60)}" rx="4" fill="${C.cold}" ${st(C.navy,3)}/><rect x="10" y="${f(88-b*118)}" width="40" height="${f(b*118)}" rx="4" fill="${C.red}" ${st(C.navy,3)}/><g transform="translate(0,-34)"><path d="M-50 40 L-50 20" stroke="none"/></g><g transform="translate(30,${f(-12-b*0)})" opacity="${f(b)}"><circle cx="0" cy="-8" r="0"/></g></g>`};
P.e106_room=(o,T,k)=>{const gl=.6+.4*Math.sin(T*3);
  return `<g><rect x="-124" y="-110" width="248" height="236" rx="14" fill="#F4E5C2" ${st()}/><rect x="-124" y="60" width="248" height="66" fill="#B98250" ${st()}/><line x1="0" y1="-110" x2="0" y2="-76" ${st(C.navy,4)}/><path d="M-26 -76 H26 L40 -50 H-40Z" fill="${C.gold}" ${st()}/><circle cx="0" cy="-46" r="10" fill="#FFF1B8" ${st(C.navy,3)}/><g opacity="${f(.35*gl)}"><path d="M-50 -40 L-100 60 H100 L50 -40Z" fill="#FFF1B8"/></g><g transform="translate(-72,10)"><rect x="-38" y="-40" width="76" height="56" rx="6" fill="${C.navy}" ${st()}/><rect x="-32" y="-34" width="64" height="44" rx="3" fill="${C.cold}"/><path d="M-20 -10 L-6 -24 L6 -10 L18 -22" fill="none" stroke="#fff" stroke-width="3" opacity=".7"/><rect x="-10" y="16" width="20" height="10" fill="${C.navy2}"/><rect x="-22" y="24" width="44" height="8" rx="3" fill="${C.navy2}"/></g><g transform="translate(66,6)"><rect x="-44" y="22" width="88" height="10" rx="3" fill="${C.brown}" ${st()}/><rect x="-36" y="32" width="8" height="40" fill="${C.brown}"/><rect x="28" y="32" width="8" height="40" fill="${C.brown}"/><rect x="-30" y="-32" width="60" height="42" rx="4" fill="${C.navy}" ${st()}/><rect x="-25" y="-27" width="50" height="32" fill="#8FC6E4"/><path d="M-34 10 H34 L40 22 H-40Z" fill="#9FB0BA" ${st()}/></g><rect x="-124" y="-110" width="248" height="236" rx="14" fill="none" ${st()}/></g>`};
P.e106_fridge=(o,T,k)=>{const nw=o.new,bolts=nw?1:2;let b='';for(let i=0;i<bolts;i++)b+=`<path d="M${88+i*0} ${-70+i*40} l-12 18 h9 l-7 16 l16 -20 h-10 l8 -14Z" fill="${C.gold}" ${st(C.navy,2.5)}/>`;
  return `<g><ellipse cx="0" cy="108" rx="60" ry="8" fill="#000" opacity=".14"/><rect x="-52" y="-108" width="104" height="212" rx="${nw?10:26}" fill="${nw?'#E9EEF1':'#E8DDB2'}" ${st()}/><line x1="-52" y1="-30" x2="52" y2="-30" ${st(C.navy,4)}/><rect x="36" y="-90" width="8" height="46" rx="4" fill="${nw?'#9FB0BA':'#B09A5A'}" ${st(C.navy,2.5)}/><rect x="36" y="-20" width="8" height="64" rx="4" fill="${nw?'#9FB0BA':'#B09A5A'}" ${st(C.navy,2.5)}/><path d="M-40 -96 L-40 -40" stroke="#fff" stroke-width="6" opacity=".6" stroke-linecap="round"/>${nw?`<circle cx="-30" cy="-60" r="5" fill="${C.leaf}" ${st(C.navy,2)}/>`:`<path d="M-30 20 q6 -10 14 -2 M-4 60 q8 -8 12 4 M-34 70 l10 6" fill="none" stroke="#B0763A" stroke-width="5" stroke-linecap="round" opacity=".7"/>`}${b}</g>`};
P.e106_tvbed=(o,T,k)=>{const fl=.5+.5*Math.sin(T*6);
  return `<g><ellipse cx="0" cy="96" rx="124" ry="10" fill="#000" opacity=".12"/><g transform="translate(-52,-6)"><rect x="-56" y="-40" width="112" height="76" rx="8" fill="${C.navy}" ${st()}/><rect x="-48" y="-32" width="96" height="60" rx="4" fill="${fl>.5?'#6FB1D6':'#8FC6E4'}"/><path d="M-30 14 L-14 -10 L2 8 L14 -6 L30 14" fill="none" stroke="#fff" stroke-width="4" opacity=".7"/><rect x="-14" y="36" width="28" height="8" fill="${C.navy2}"/><rect x="-34" y="44" width="68" height="8" rx="3" fill="${C.navy2}"/></g><g transform="translate(72,0)"><rect x="-58" y="40" width="116" height="20" rx="6" fill="${C.brown}" ${st()}/><rect x="-54" y="56" width="10" height="34" fill="${C.brown}"/><rect x="44" y="56" width="10" height="34" fill="${C.brown}"/><rect x="-56" y="8" width="112" height="40" rx="12" fill="#F6EEDC" ${st()}/><ellipse cx="-24" cy="2" rx="26" ry="11" fill="#fff" ${st()}/><circle cx="-24" cy="-14" r="17" fill="${_e106SK}" ${st()}/><path d="M-41 -16 Q-40 -34 -24 -32 Q-8 -34 -7 -16 Q-22 -26 -41 -16Z" fill="#3A2A22" ${st(C.navy,3)}/><path d="M-50 22 Q10 6 58 24 L58 50 L-50 50Z" fill="${C.blue}" ${st()}/></g><g transform="translate(78,-72) scale(.6)">${P.zzz?P.zzz({},T):''}</g></g>`};
P.e106_flame=(o,T,k)=>{const w=Math.sin(T*8)*2;return `<g><path d="M0 -92 C${f(34+w)} -50 62 -28 54 12 C48 52 20 70 0 70 C-20 70 -48 52 -54 12 C-62 -28 -34 -50 0 -92Z" fill="${C.orange}" ${st()}/><path d="M0 -40 C22 -14 36 4 32 28 C28 50 14 56 0 56 C-14 56 -28 50 -32 28 C-36 4 -22 -14 0 -40Z" fill="${C.gold}"/><path d="M0 4 C10 18 16 28 12 40 C8 50 -8 50 -12 40 C-16 28 -10 18 0 4Z" fill="#FFF1B8"/></g>`};
P.e106_oil=(o,T,k)=>`<g><path d="M0 -92 C40 -30 62 -4 62 28 a62 62 0 0 1 -124 0 C-62 -4 -40 -30 0 -92Z" fill="#2E3B45" ${st()}/><path d="M-30 4 q-8 24 8 40" fill="none" stroke="#fff" stroke-width="9" opacity=".35" stroke-linecap="round"/><ellipse cx="0" cy="70" rx="50" ry="8" fill="#000" opacity=".15"/></g>`;
P.e106_powerstation=(o,T,k)=>{let sm='';if(!o.clean)for(let i=0;i<4;i++){const ph=((T*.45+i/4)%1),x=(i%2?58:-58)+Math.sin(ph*6+i)*10;sm+=`<g transform="translate(${f(x)},${f(-100-ph*70)}) scale(${f(.34+ph*.5)})" opacity="${f(.9-ph*.8)}">${blob([[-20,6,20],[6,-8,26],[30,8,18]],'#9AA7B0',6)}</g>`}
  const tw=(x)=>`<path d="M${x-34} 70 Q${x-16} 0 ${x-24} -60 L${x+24} -60 Q${x+16} 0 ${x+34} 70Z" fill="#DCE3E8" ${st()}/><path d="M${x-30} 70 Q${x-12} 0 ${x-20} -60" fill="none" stroke="#fff" stroke-width="6" opacity=".6"/><rect x="${x-26}" y="-66" width="52" height="8" rx="3" fill="#B9C6CE" ${st(C.navy,3)}/>`;
  return `<g><ellipse cx="0" cy="96" rx="126" ry="9" fill="#000" opacity=".13"/>${sm}${tw(-58)}${tw(58)}<rect x="-18" y="-24" width="36" height="94" fill="#B9C6CE" ${st()}/><rect x="-22" y="-32" width="44" height="10" fill="${C.red}" ${st()}/><rect x="-124" y="64" width="248" height="30" fill="#8E9BA5" ${st()}/>${o.clean?`<g transform="translate(0,-30) scale(.55)"><path d="M0 40 Q-60 10 -36 -50 Q30 -40 0 40Z" fill="${C.leaf}" ${st()}/></g>`:''}</g>`};
P.e106_connect=(o,T,k)=>{let dots='';for(let i=0;i<5;i++){const t=((T*.5+i/5)%1),x=(1-t)*(1-t)*60+2*(1-t)*t*0+t*t*-70,y=(1-t)*(1-t)*30+2*(1-t)*t*110+t*t*40;dots+=`<circle cx="${f(x)}" cy="${f(y)}" r="6" fill="${C.gold}" ${st(C.navy,2.5)}/>`}
  return `<g><g transform="translate(-100,-14) scale(.7)">${P.e24_lamp({},T,k)}</g><path d="M60 30 Q0 110 -70 40" fill="none" ${st(C.navy,5)}/>${dots}<g transform="translate(72,24) scale(.46)">${P.e106_powerstation({},T,k)}</g></g>`};
P.e106_tap=(o,T,k)=>{let w='';if(!o.off)for(let i=0;i<5;i++){const ph=((T*1.6+i/5)%1);w+=`<ellipse cx="34" cy="${f(-20+ph*84)}" rx="4" ry="9" fill="${C.blue}" opacity="${f(1-ph*.3)}"/>`}
  return `<g><path d="M-30 -60 Q-30 -100 10 -100 Q50 -100 50 -60 L50 -44 H34 L34 -62 Q34 -84 10 -84 Q-14 -84 -14 -62 V-30 H-30Z" fill="#B9C6CE" ${st()}/><rect x="-44" y="-36" width="36" height="14" rx="4" fill="#9FB0BA" ${st()}/><rect x="14" y="-124" width="8" height="26" fill="#9FB0BA" ${st(C.navy,3)}/><rect x="-6" y="-132" width="48" height="12" rx="5" fill="${o.off?C.red:C.blue}" ${st()}/>${w}<rect x="-90" y="60" width="180" height="46" rx="10" fill="#E8EEF1" ${st()}/><g transform="translate(-30,40) scale(.5)"><circle r="46" fill="#fff" ${st()}/><circle r="30" fill="#EAF3FA" ${st(C.blue,4)}/></g><g transform="translate(40,44) scale(.5)"><circle r="46" fill="#fff" ${st()}/><circle r="30" fill="#EAF3FA" ${st(C.blue,4)}/></g></g>`};
P.e106_radiator=(o,T,k)=>{let f2='';for(let i=0;i<6;i++)f2+=`<rect x="${-76+i*26}" y="-52" width="18" height="108" rx="9" fill="#F4F0E6" ${st()}/>`;let w='';const n=o.high?4:2,col=o.high?C.red:C.orange;for(let i=0;i<n;i++){const ph=((T*.7+i/n)%1);w+=`<path d="M${-60+i*40} ${f(-64-ph*34)} q-10 -12 0 -24 t0 -24" fill="none" ${st(col,5)} opacity="${f(1-ph)}"/>`}
  return `<g><rect x="-86" y="-60" width="172" height="12" rx="5" fill="#D8D2C2" ${st()}/>${f2}<rect x="-86" y="52" width="172" height="12" rx="5" fill="#D8D2C2" ${st()}/><rect x="-70" y="64" width="10" height="26" fill="${C.navy2}"/><rect x="60" y="64" width="10" height="26" fill="${C.navy2}"/>${w}</g>`};
P.e106_openwindow=(o,T,k)=>{const sw=Math.sin(T*2)*6,fl=Math.sin(T*3)*8;
  return `<g><rect x="-80" y="-110" width="160" height="220" rx="8" fill="#B07A44" ${st()}/><rect x="-66" y="-96" width="132" height="192" fill="#BFE3F2" ${st(C.navy,3)}/><path d="M-66 -96 L-110 -70 L-110 70 L-66 96Z" fill="#DDF0F8" ${st()} opacity=".95"/><path d="M-66 -96 L-110 -70 L-110 70 L-66 96Z" fill="none" ${st(C.navy,4)}/><path d="M66 -96 L110 -70 L110 70 L66 96Z" fill="#DDF0F8" ${st()} opacity=".95"/><path d="M-30 -80 Q${f(0+fl)} -20 -26 40 Q${f(-6+fl)} 80 -34 90 L-66 90 L-66 -80Z" fill="#E9A090" ${st()} opacity=".0"/><g transform="translate(0,${f(sw)})"><path d="M-20 40 q20 -12 40 0 t40 0" fill="none" ${st('#fff',5)}/><path d="M-60 10 q20 -12 40 0 t40 0" fill="none" ${st('#fff',5)}/></g></g>`};
P.e106_sweater=(o,T,k)=>`<g><path d="M-30 -60 Q0 -42 30 -60 L74 -34 L96 22 L68 36 L56 6 L56 78 Q56 86 48 86 H-48 Q-56 86 -56 78 L-56 6 L-68 36 L-96 22 L-74 -34Z" fill="${o.c||'#C0504D'}" ${st()}/><path d="M-30 -60 Q0 -42 30 -60" fill="none" ${st(C.navy,4)}/><rect x="-56" y="70" width="112" height="14" rx="4" fill="#fff" opacity=".35"/><path d="M-30 -20 L-30 62 M-10 -20 L-10 62 M10 -20 L10 62 M30 -20 L30 62" stroke="#fff" stroke-width="4" opacity=".25"/></g>`;

/* ---------- cars, air, bikes ---------- */
P.e106_traffic=(o,T,k)=>{let s='';[[-84,C.red],[0,C.blue],[84,C.gold2]].forEach(([x,c],i)=>{const ph=((T*.5+i*.3)%1);s+=`<g transform="translate(${x},40)"><g transform="translate(-40,${f(-14-ph*34)}) scale(${f(.3+ph*.4)})" opacity="${f(.85-ph*.8)}">${blob([[-20,6,20],[6,-8,26],[30,8,18]],'#9AA7B0',6)}</g><g transform="scale(.36)">${P.car({},T).replace('fill="'+C.red+'"','fill="'+c+'"')}</g></g>`});
  return `<g><g transform="translate(0,-48) scale(.9)">${P.city({},T)}</g><rect x="-126" y="60" width="252" height="40" fill="#6B7780" ${st()}/><path d="M-120 80 h40 M-40 80 h40 M40 80 h40 M100 80 h20" ${st('#fff',4)}/>${s}</g>`};
P.e106_greysky=(o,T,k)=>{const cl=o.clean;let c='';if(!cl)for(let i=0;i<3;i++)c+=`<g transform="translate(${-90+i*90},${-70+(i%2)*22}) scale(${.9+i*.1})" opacity=".9">${blob([[-52,10,34],[-8,-16,46],[42,-4,38],[64,22,26],[-14,22,34],[26,26,32],[-38,24,28]],'#8793A0')}</g>`;
  return `<g><clipPath id="e106_gsc"><rect x="-124" y="-110" width="248" height="236" rx="18"/></clipPath><g clip-path="url(#e106_gsc)"><rect x="-124" y="-110" width="248" height="236" fill="${cl?'#9ED3EE':'#A9B2B8'}"/>${cl?`<g transform="translate(70,-66) scale(.5)">${P.sun({},T)}</g>`:''}${c}<g transform="translate(0,22) scale(.95)">${P.city({},T)}</g><rect x="-124" y="80" width="248" height="46" fill="#6B7780"/></g><rect x="-124" y="-110" width="248" height="236" rx="18" fill="none" ${st()}/></g>`};
P.e106_pump=(o,T,k)=>`<g><ellipse cx="0" cy="100" rx="78" ry="9" fill="#000" opacity=".14"/><rect x="-54" y="-98" width="108" height="192" rx="12" fill="${C.red}" ${st()}/><rect x="-42" y="-86" width="84" height="52" rx="6" fill="#DDF0F8" ${st(C.navy,3)}/><g transform="translate(0,-60) scale(.3)"><path d="M0 -90 C40 -30 62 -4 62 28 a62 62 0 0 1 -124 0 C-62 -4 -40 -30 0 -90Z" fill="${C.gold}" ${st(C.navy,10)}/></g><rect x="-42" y="-22" width="84" height="12" rx="4" fill="#fff" opacity=".4"/><rect x="-62" y="86" width="124" height="16" rx="5" fill="${C.navy2}" ${st()}/><path d="M54 -40 Q96 -34 92 10 L92 46" fill="none" ${st(C.navy,9)}/><rect x="80" y="40" width="26" height="40" rx="6" fill="#9FB0BA" ${st()}/><path d="M-30 20 h60" stroke="#fff" stroke-width="5" opacity=".5"/></g>`;
P.e106_carshare=(o,T,k)=>{const bob=Math.sin(T*3)*1.5;let h='';
  [[-50,'#E2B653','bun'],[-14,'#4DA3D8','short'],[22,'#D96C8B','long'],[58,'#4F7A5A','short']].forEach(([x,c,hr],i)=>{h+=`<g transform="translate(${x},-22)"><circle r="12" fill="${_e106SK}" ${st(C.navy,3)}/><path d="M-12 -2 Q-12 -16 0 -16 Q12 -16 12 -2 Q4 -10 -12 -2Z" fill="${['#2A1D18','#222','#3A2A22','#2A1D18'][i]}"/></g>`});
  return `<g transform="translate(0,${f(bob)})"><ellipse cx="0" cy="84" rx="126" ry="9" fill="#000" opacity=".14"/><path d="M-118 62 L-118 20 Q-118 8 -104 6 L-78 -2 L-58 -50 Q-52 -62 -38 -62 L50 -62 Q64 -62 70 -50 L92 -2 L106 6 Q118 10 118 22 L118 62 Z" fill="${C.orange}" ${st()}/><path d="M-70 -4 L-52 -48 L50 -48 L74 -4Z" fill="${C.sky}" ${st(C.navy,4)}/>${h}<path d="M-70 -4 L-52 -48 L50 -48 L74 -4Z" fill="#fff" opacity=".0"/><rect x="-118" y="40" width="236" height="10" fill="#fff" opacity=".3"/><circle cx="-62" cy="66" r="24" fill="${C.navy}" ${st()}/><circle cx="-62" cy="66" r="10" fill="#9FB0BA"/><circle cx="64" cy="66" r="24" fill="${C.navy}" ${st()}/><circle cx="64" cy="66" r="10" fill="#9FB0BA"/></g>`};
P.e106_bikelane=(o,T,k)=>{const x=-90+((T*.3)%1)*180;
  return `<g><polygon points="-130,-60 130,-60 130,100 -130,100" fill="#6B7780" ${st()}/><rect x="-130" y="10" width="260" height="62" fill="${C.leaf}" opacity=".85"/><path d="M-130 10 H130 M-130 72 H130" stroke="#fff" stroke-width="4" stroke-dasharray="14 10"/><g transform="translate(${f(x)},40) scale(.52)">${P.e14_bike?P.e14_bike({},T,k):''}</g>${[-100,-30,40,110].map(q=>`<rect x="${q-4}" y="-30" width="8" height="30" rx="3" fill="#fff" ${st(C.navy,3)}/>`).join('')}</g>`};
P.e106_pie=(o,T,k)=>{const p=o.p==null?.5:o.p,a=ease(k/.8)*p*Math.PI*2,x=Math.sin(a)*92,y=-Math.cos(a)*92,lg=a>Math.PI?1:0;
  return `<g><circle r="96" fill="#fff" ${st()}/><path d="M0 0 L0 -92 A92 92 0 ${lg} 1 ${f(x)} ${f(y)} Z" fill="${C.leaf}" ${st(C.navy,4)}/><circle r="96" fill="none" ${st()}/></g>`};
P.e106_factory=(o,T,k)=>{let sm='';for(let i=0;i<4;i++){const ph=((T*.45+i/4)%1),x=(i%2?44:-8);sm+=`<g transform="translate(${f(x+Math.sin(ph*6+i)*8)},${f(-80-ph*60)}) scale(${f(.3+ph*.5)})" opacity="${f(.9-ph*.8)}">${blob([[-20,6,20],[6,-8,26],[30,8,18]],'#9AA7B0',6)}</g>`}
  return `<g><ellipse cx="0" cy="96" rx="126" ry="9" fill="#000" opacity=".13"/>${sm}<rect x="-8" y="-66" width="26" height="106" fill="#C0504D" ${st()}/><rect x="-14" y="-72" width="38" height="10" fill="#8C3A38" ${st()}/><rect x="36" y="-50" width="22" height="90" fill="#C0504D" ${st()}/><rect x="32" y="-56" width="30" height="10" fill="#8C3A38" ${st()}/><path d="M-116 90 V-6 L-76 -34 V-6 L-36 -34 V-6 L4 -34 V90Z" fill="#B9C6CE" ${st()}/><rect x="4" y="-4" width="112" height="94" fill="#C9D3D9" ${st()}/>${[0,1,2].map(i=>`<rect x="${-100+i*34}" y="20" width="22" height="22" fill="#FFE9A8" ${st(C.navy,3)}/>`).join('')}${[0,1,2].map(i=>`<rect x="${20+i*32}" y="16" width="20" height="26" fill="${C.sky}" ${st(C.navy,3)}/>`).join('')}<rect x="-30" y="52" width="38" height="38" fill="${C.navy2}" ${st()}/></g>`};

/* ---------- forests, rivers, trees ---------- */
const _e106stump=(x,y,s)=>`<g transform="translate(${x},${y}) scale(${s||1})"><ellipse cx="0" cy="14" rx="20" ry="6" fill="#000" opacity=".15"/><path d="M-16 14 L-14 -6 L14 -6 L16 14Z" fill="${C.brown}" ${st(C.navy,3.5)}/><ellipse cx="0" cy="-6" rx="14" ry="5" fill="#E8C98F" ${st(C.navy,3)}/><ellipse cx="0" cy="-6" rx="7" ry="2.5" fill="none" stroke="#B9884B" stroke-width="2"/></g>`;
P.e106_forest=(o,T,k)=>{const st_=o.stage||0;let t='';
  const spots=[[-86,40,.8,'#4E8F5A'],[-40,52,.95,C.leaf],[8,44,1,'#4E8F5A'],[52,54,.9,C.leaf],[94,42,.8,'#4E8F5A'],[-62,14,.7,C.leaf],[-18,10,.78,'#4E8F5A'],[30,12,.72,C.leaf],[74,10,.68,'#4E8F5A']];
  spots.forEach(([x,y,s,c],i)=>{const keep=st_===0||(st_===1&&(i===1||i===6||i===8))||st_===3&&i===2;if(keep)t+=_e106tree(x,y,s,c);else t+=_e106stump(x,y+4,s*.9)});
  const bird=st_===0?`<g transform="translate(${f(-30+Math.sin(T)*20)},-70)"><path d="M-14 0 Q-7 -10 0 0 Q7 -10 14 0" fill="none" ${st(C.navy,4)}/></g><g transform="translate(${f(50-Math.sin(T*1.2)*20)},-86)"><path d="M-10 0 Q-5 -8 0 0 Q5 -8 10 0" fill="none" ${st(C.navy,4)}/></g>`:'';
  return `<g><clipPath id="e106_fc"><rect x="-124" y="-110" width="248" height="236" rx="18"/></clipPath><g clip-path="url(#e106_fc)"><rect x="-124" y="-110" width="248" height="236" fill="${st_===0?'#BFE3F2':'#E9D9B8'}"/><rect x="-124" y="40" width="248" height="86" fill="${st_===0?'#7DB06F':'#B79B6A'}"/>${bird}${t}</g><rect x="-124" y="-110" width="248" height="236" rx="18" fill="none" ${st()}/></g>`};
P.e106_sapling=(o,T,k)=>{const g=ease(k/.8),sw=Math.sin(T*2)*3;
  return `<g><ellipse cx="0" cy="84" rx="62" ry="10" fill="#000" opacity=".14"/><path d="M-62 86 Q-30 54 0 56 Q30 54 62 86Z" fill="#8B5E3C" ${st()}/><g transform="translate(0,56) rotate(${f(sw)}) scale(${f(.4+.6*g)})"><path d="M0 0 Q-4 -50 0 -100" fill="none" ${st(C.leaf,9)}/><path d="M0 -50 Q-50 -62 -56 -100 Q-6 -96 0 -50Z" fill="${C.leaf}" ${st()}/><path d="M0 -80 Q50 -92 58 -128 Q6 -126 0 -80Z" fill="${C.moss}" ${st()}/></g></g>`};
P.e106_grow=(o,T,k)=>{const g=ease((((T*.28)%1.2))/1.1);
  return `<g><ellipse cx="0" cy="90" rx="100" ry="10" fill="#000" opacity=".14"/><rect x="-110" y="78" width="220" height="14" rx="6" fill="#7DB06F" ${st()}/><g transform="translate(0,${f(80-79.8*(.22+g*.85))}) scale(${f(.22+g*.85)})" >${_e106tree(0,0,2.1,C.leaf)}</g></g>`};
P.e106_planting=(o,T,k)=>{const dig=Math.sin(T*3)*6;
  return `<g><ellipse cx="0" cy="96" rx="120" ry="10" fill="#000" opacity=".13"/><rect x="-124" y="80" width="248" height="16" rx="6" fill="#7DB06F" ${st()}/><g transform="translate(-56,0) scale(.9)">${P.person({c:o.c||'#8E6B3E',hair:'short',hc:'#D5D8DB'},T)}</g><g transform="translate(56,0)"><path d="M-40 82 Q0 52 40 82Z" fill="#8B5E3C" ${st()}/><path d="M0 56 Q-2 24 0 -4" fill="none" ${st(C.leaf,7)}/><path d="M0 28 Q-34 20 -38 -6 Q-4 -4 0 28Z" fill="${C.leaf}" ${st(C.navy,4)}/><path d="M0 12 Q32 4 38 -22 Q4 -22 0 12Z" fill="${C.moss}" ${st(C.navy,4)}/></g><g transform="translate(${f(8+dig)},40) rotate(24)"><rect x="-4" y="-50" width="8" height="80" fill="${C.brown}" ${st(C.navy,3)}/><path d="M-14 30 H14 L10 56 Q0 62 -10 56Z" fill="#B9C6CE" ${st()}/></g></g>`};
P.e106_river=(o,T,k)=>{const d=o.dirty,wc=d?'#8E8466':'#6FB6DE',w=d?'#B5AA84':'#fff';let tr='';
  tr=`${_e106tree(-90,-30,.8)}${_e106tree(92,-40,.85)}${_e106tree(-62,-70,.6,'#4E8F5A')}`;
  const junk=d?`<g transform="translate(${f(-10+Math.sin(T)*10)},46) rotate(-70) scale(.7)">${_e105bottle(0,0,0,'#CFE8F4')}</g><g transform="translate(40,${f(10+Math.sin(T*1.4)*3)}) scale(.5)">${_e105pb(60,50,'rgba(255,255,255,.9)',4)}</g>`:'';
  return `<g><clipPath id="e106_rc"><rect x="-124" y="-110" width="248" height="236" rx="18"/></clipPath><g clip-path="url(#e106_rc)"><rect x="-124" y="-110" width="248" height="236" fill="#8FC77F"/>${tr}<path d="M-30 -110 Q-70 -40 0 0 Q60 40 10 126 L110 126 Q130 40 70 0 Q10 -40 50 -110Z" fill="${wc}" ${st(C.navy,4)}/><path d="M-6 -80 q-20 30 14 52 M10 20 q30 24 -4 60" fill="none" stroke="${w}" stroke-width="5" stroke-linecap="round" opacity=".8"/>${junk}</g><rect x="-124" y="-110" width="248" height="236" rx="18" fill="none" ${st()}/></g>`};
P.e106_axe=(o,T,k)=>`<g><ellipse cx="0" cy="88" rx="110" ry="9" fill="#000" opacity=".13"/>${[[-60,60],[-18,66],[24,60]].map(([x,y],i)=>`<g transform="translate(${x},${y})"><rect x="-22" y="-22" width="44" height="44" rx="6" fill="${C.brown}" ${st()}/><ellipse cx="22" cy="0" rx="8" ry="22" fill="#E8C98F" ${st(C.navy,3)}/><path d="M-12 -14 V14" stroke="#B07A44" stroke-width="3"/></g>`).join('')}<g transform="translate(46,0)"><rect x="-26" y="30" width="52" height="56" rx="6" fill="${C.brown}" ${st()}/><ellipse cx="0" cy="30" rx="26" ry="9" fill="#E8C98F" ${st()}/><g transform="translate(6,16) rotate(${f(-30+Math.sin(T*3)*2)})"><rect x="-4" y="-70" width="8" height="84" rx="3" fill="#B07A44" ${st()}/><path d="M-4 -70 Q-34 -76 -36 -54 Q-30 -40 -4 -44Z" fill="#B9C6CE" ${st()}/></g></g></g>`;
P.e106_coatglobe=(o,T,k)=>{const sh=Math.sin(T*3)*.5+.5;
  return `<g><g transform="scale(.92)">${P.globe({},T)}</g><path d="M-96 -6 Q0 40 96 -6 L100 26 Q0 78 -100 26Z" fill="${C.orange}" ${st()}/><path d="M-80 4 L-76 30 M-50 18 L-46 46 M-16 24 L-12 54 M20 24 L22 54 M52 18 L52 46 M82 4 L80 30" stroke="#fff" stroke-width="5" opacity=".5" stroke-linecap="round"/>${[0,1,2].map(i=>`<path d="M${-60+i*60} ${f(-100-sh*8)} q-10 -12 0 -24 t0 -24" fill="none" ${st(C.red,5)} opacity="${f(.5+sh*.4)}"/>`).join('')}</g>`};
P.e106_thermo=(o,T,k)=>{const h=ease(k/1.3)*(o.h||.85);
  return `<g><rect x="-22" y="-112" width="44" height="186" rx="22" fill="#fff" ${st()}/><circle cx="0" cy="84" r="36" fill="${C.red}" ${st()}/><rect x="-9" y="${f(76-h*168)}" width="18" height="${f(h*168+8)}" rx="9" fill="${C.red}"/>${[0,1,2,3,4].map(i=>`<line x1="12" y1="${-84+i*30}" x2="${i%2?20:26}" y2="${-84+i*30}" ${st(C.navy,3)}/>`).join('')}<path d="M-12 -90 V50" stroke="#fff" stroke-width="5" opacity=".5" stroke-linecap="round"/></g>`};

/* ---------- solutions ---------- */
P.e106_solar=(o,T,k)=>{let g='';for(let r=0;r<3;r++)for(let c=0;c<4;c++)g+=`<rect x="${-62+c*32}" y="${-26+r*22}" width="28" height="18" fill="#2F6BA8" stroke="#BFE3F2" stroke-width="2"/>`;
  const gl=Math.sin(T*3)*.5+.5;
  return `<g><ellipse cx="-4" cy="100" rx="100" ry="9" fill="#000" opacity=".13"/><g transform="translate(70,-66) scale(.5)">${P.sun({},T)}</g><g transform="translate(-14,30)"><path d="M-84 30 L-60 -50 L84 -50 L100 30Z" fill="#1F4E80" ${st()} transform="skewX(0)"/><g transform="skewX(-12) translate(10,12)">${g}</g><path d="M-84 30 L-60 -50 L84 -50 L100 30Z" fill="none" ${st()}/><path d="M-14 30 V64 M44 30 V64" ${st(C.navy2,8)}/><rect x="-40" y="62" width="100" height="8" rx="3" fill="${C.navy2}"/></g><g transform="translate(86,40) scale(${f(.9+gl*.15)})"><path d="M0 -30 L-14 4 H-2 L-8 30 L14 -8 H2 L10 -30Z" fill="${C.gold}" ${st(C.navy,3)}/></g></g>`};
P.e106_hydro=(o,T,k)=>{let p='';const r=T*40;for(let i=0;i<8;i++)p+=`<rect x="-8" y="-84" width="16" height="30" fill="#B07A44" ${st(C.navy,3)} transform="rotate(${i*45})"/>`;let w='';for(let i=0;i<4;i++){const ph=((T*1.2+i/4)%1);w+=`<ellipse cx="${f(-100+ph*60)}" cy="${f(-60+ph*60)}" rx="9" ry="5" fill="#fff" opacity="${f(.8-ph*.3)}"/>`}
  return `<g><rect x="-124" y="40" width="248" height="60" fill="${C.blue}" ${st()}/><path d="M-124 60 q20 -10 40 0 t40 0 t40 0 t40 0 t40 0 t40 0" fill="none" stroke="#fff" stroke-width="4"/><path d="M-124 -70 L-70 -70 L-40 -30 L-40 -26 L-124 -26Z" fill="${C.blue}" ${st()}/>${w}<g transform="translate(20,-2) rotate(${f(r)})"><circle r="70" fill="none" ${st(C.brown,10)}/><circle r="70" fill="none" ${st(C.navy,3)} opacity="0"/>${p}<circle r="14" fill="${C.brown}" ${st()}/><path d="M0 -70 V70 M-70 0 H70" ${st(C.brown,7)}/></g><rect x="14" y="60" width="12" height="40" fill="${C.navy2}"/><g transform="translate(100,-70) scale(.8)"><path d="M0 -30 L-14 4 H-2 L-8 30 L14 -8 H2 L10 -30Z" fill="${C.gold}" ${st(C.navy,3)}/></g></g>`};
P.e106_park=(o,T,k)=>`<g><ellipse cx="0" cy="100" rx="116" ry="9" fill="#000" opacity=".13"/>${_e106tree(-84,56,.9,'#4E8F5A')}${_e106tree(88,52,1,C.leaf)}<rect x="-8" y="-30" width="16" height="130" fill="${C.brown}" ${st()}/><rect x="-86" y="-86" width="172" height="86" rx="10" fill="${C.moss}" ${st()}/><rect x="-78" y="-78" width="156" height="70" rx="6" fill="none" stroke="${C.cream}" stroke-width="3"/><text x="0" y="-48" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="26" fill="${C.cream}" letter-spacing="2">NATIONAL</text><text x="0" y="-18" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="30" fill="${C.gold}" letter-spacing="4">PARK</text></g>`;
P.e106_gavel=(o,T,k)=>{const hit=Math.sin(T*4);const a=-30+Math.max(0,hit)*30;
  return `<g><ellipse cx="0" cy="96" rx="90" ry="10" fill="#000" opacity=".13"/><rect x="-60" y="60" width="120" height="30" rx="8" fill="#8B5E3C" ${st()}/><ellipse cx="0" cy="60" rx="60" ry="10" fill="#B07A44" ${st()}/><g transform="translate(0,40) rotate(${f(a)} 0 0)"><rect x="-6" y="-100" width="12" height="100" rx="5" fill="#B07A44" ${st()}/><rect x="-44" y="-132" width="88" height="40" rx="10" fill="#8B5E3C" ${st()}/><rect x="-44" y="-122" width="88" height="6" fill="#fff" opacity=".25"/></g></g>`};
P.e106_drought=(o,T,k)=>`<g><clipPath id="e106_dc"><rect x="-124" y="-110" width="248" height="236" rx="18"/></clipPath><g clip-path="url(#e106_dc)"><rect x="-124" y="-110" width="248" height="236" fill="#FFE0A0"/><g transform="translate(60,-56) scale(.8)">${P.sun({hot:1},T)}</g><rect x="-124" y="10" width="248" height="116" fill="#D2A66A"/><path d="M-110 30 L-60 50 L-70 90 L-30 110 M-60 50 L-10 44 L20 76 L80 66 L110 100 M20 76 L10 118 M-10 44 L-4 18 M80 66 L100 30" fill="none" stroke="#8B5E3C" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><path d="M-80 10 q-6 -30 -22 -44 M-80 10 q10 -24 26 -30 M-80 10 v-36" fill="none" stroke="#8B5E3C" stroke-width="5" stroke-linecap="round"/></g><rect x="-124" y="-110" width="248" height="236" rx="18" fill="none" ${st()}/></g>`;
P.e106_table=(o,T,k)=>`<g><ellipse cx="0" cy="102" rx="110" ry="9" fill="#000" opacity=".13"/><rect x="-100" y="-20" width="200" height="22" rx="6" fill="${o.col||'#B07A44'}" ${st()}/><path d="M-84 -10 H-30 M-6 -10 H60 M20 -2 H84" stroke="#8A5E34" stroke-width="3" stroke-linecap="round" opacity=".6"/><rect x="-86" y="2" width="16" height="96" fill="#8A5E34" ${st()}/><rect x="70" y="2" width="16" height="96" fill="#8A5E34" ${st()}/><rect x="-70" y="30" width="140" height="8" fill="#8A5E34" ${st(C.navy,3)}/></g>`;
P.e106_paintcan=(o,T,k)=>{const sw=Math.sin(T*3)*6;
  return `<g><ellipse cx="-20" cy="98" rx="70" ry="9" fill="#000" opacity=".13"/><path d="M-62 -26 L62 -26 L56 90 Q0 104 -56 90Z" fill="#DCE3E8" ${st()}/><path d="M-60 -10 H60 L56 40 H-56Z" fill="${C.leaf}" ${st(C.navy,3)}/><ellipse cx="0" cy="-26" rx="62" ry="14" fill="#9FB0BA" ${st()}/><ellipse cx="0" cy="-26" rx="46" ry="9" fill="${C.leaf}"/><path d="M-52 -26 Q-56 6 -48 18" fill="none" stroke="${C.leaf}" stroke-width="7" stroke-linecap="round"/><g transform="translate(${f(46+sw)},-30) rotate(32)"><rect x="-6" y="-70" width="12" height="60" rx="5" fill="${C.brown}" ${st()}/><rect x="-9" y="-12" width="18" height="16" fill="#B9C6CE" ${st(C.navy,3)}/><path d="M-9 4 Q0 30 9 4Z" fill="${C.leaf}" ${st(C.navy,3)}/></g></g>`};
P.e106_circles=(o,T,k)=>{const n=o.n||4,cols=['#BFE3F2','#CFE8C8','#F9E4BC','#F4C9C0'];let s='';
  for(let i=n-1;i>=0;i--){const p=ease((k-.3-(n-1-i)*.35)/.4),r=34+i*28;s+=`<circle r="${f(r*p)}" fill="${cols[i%4]}" ${st(C.navy,4)} opacity="${f(p)}"/>`}
  return `<g>${s}<g transform="translate(0,8) scale(.34)">${P.person({c:o.c||'#E2B653',hair:'bun',hc:'#2A1D18'},T)}</g></g>`};
P.e106_cyc=(o,T,k)=>{const r=T*40;return `<g transform="rotate(${f(r)})"><path d="M0 -92 A92 92 0 0 1 80 -46" fill="none" ${st(C.navy,13)}/><path d="M0 -92 A92 92 0 0 1 80 -46" fill="none" ${st(C.moss,8)}/><path d="M86 -66 L90 -28 L60 -46Z" fill="${C.moss}" ${st(C.navy,4)}/><g transform="rotate(180)"><path d="M0 -92 A92 92 0 0 1 80 -46" fill="none" ${st(C.navy,13)}/><path d="M0 -92 A92 92 0 0 1 80 -46" fill="none" ${st(C.moss,8)}/><path d="M86 -66 L90 -28 L60 -46Z" fill="${C.moss}" ${st(C.navy,4)}/></g></g>`};

/* Episode 106 intro hero: a slowly turning Earth inside a green recycling ring, with a little sprout growing on top - our planet, small changes */
const _e106iS=(x,y,s,T,ph,c='#FFE9A8')=>{const a=.5+.5*Math.sin(T*2.4+ph);const r=s*(.65+.35*a);return `<path d="M${f(x)} ${f(y-r)}Q${f(x)} ${f(y)} ${f(x+r*.8)} ${f(y)}Q${f(x)} ${f(y)} ${f(x)} ${f(y+r)}Q${f(x)} ${f(y)} ${f(x-r*.8)} ${f(y)}Q${f(x)} ${f(y)} ${f(x)} ${f(y-r)}Z" fill="${c}" opacity="${f(.45+.55*a)}"/>`};
const _e106iPlate=(T,c1,c2)=>`<defs><radialGradient id="e106i_pl" cx="50%" cy="38%" r="62%"><stop offset="0" stop-color="${c1}" stop-opacity=".62"/><stop offset=".7" stop-color="${c2}" stop-opacity=".22"/><stop offset="1" stop-color="${c2}" stop-opacity=".06"/></radialGradient></defs><circle r="132" fill="url(#e106i_pl)"/><circle r="132" fill="none" stroke="${c1}" stroke-opacity=".4" stroke-width="2.5"/><circle r="122" fill="none" stroke="#fff" stroke-opacity=".28" stroke-width="2" stroke-dasharray="3 11" stroke-linecap="round" transform="rotate(${f(T*6)})"/>`;
const _e106iLand=(off)=>[-1,0,1].map(k=>`<g transform="translate(${f(-75-off+k*150)},0)"><path d="M10 -30Q30 -45 52 -32Q62 -20 48 -8Q40 6 28 2Q14 -4 6 -16Z" fill="url(#e106i_ld)" stroke="#2E8A4F" stroke-width="2"/><path d="M30 10Q46 6 54 20Q56 38 42 48Q32 36 28 24Z" fill="url(#e106i_ld)" stroke="#2E8A4F" stroke-width="2"/><path d="M84 -36Q108 -44 128 -30Q140 -14 122 -6Q108 0 98 -10Q82 -14 84 -36Z" fill="url(#e106i_ld)" stroke="#2E8A4F" stroke-width="2"/><path d="M96 12Q118 8 132 22Q130 40 112 42Q96 36 96 12Z" fill="url(#e106i_ld)" stroke="#2E8A4F" stroke-width="2"/><circle cx="68" cy="-4" r="4" fill="#7ED88A"/><circle cx="146" cy="6" r="3.500" fill="#7ED88A"/></g>`).join('');
const _e106iCloud=(off,y,w)=>[-1,0,1].map(k=>`<rect x="${f(-90-off+k*180)}" y="${y}" width="${w}" height="7" rx="3.500" fill="#fff" opacity=".6"/>`).join('');
const _e106iArrow=(i)=>{const R=97,pt=(d,r)=>{const a=d*Math.PI/180;return [r*Math.cos(a),r*Math.sin(a)]};const a0=-96,a1=-22;const p0=pt(a0,R),p1=pt(a1,R),t=pt(a1+17,R),l=pt(a1-3,R+13),r=pt(a1-3,R-13);const d=`M${f(p0[0])} ${f(p0[1])}A${R} ${R} 0 0 1 ${f(p1[0])} ${f(p1[1])}`;return `<g transform="rotate(${i*120})"><path d="${d}" fill="none" ${st(C.navy,15)}/><path d="${d}" fill="none" stroke="url(#e106i_rg)" stroke-width="9" stroke-linecap="round"/><path d="M${f(l[0])} ${f(l[1])}L${f(t[0])} ${f(t[1])}L${f(r[0])} ${f(r[1])}Z" fill="#7FE08A" ${st(C.navy,4.500)}/></g>`};
P.e106_ihero=(o,T,k)=>{
  const s=Math.sin,b=(a,p,sp=1.4)=>s(T*sp+p)*a;
  const off=(T*9)%150, off2=(T*14)%180;
  const sw=b(4,0,1.5);
  const grow=1+.04*s(T*2);
  return `<g>
  <defs>
   <radialGradient id="e106i_oc" cx="35%" cy="30%" r="80%"><stop offset="0" stop-color="#8FE0FF"/><stop offset=".55" stop-color="#2F9BE8"/><stop offset="1" stop-color="#1B4FA8"/></radialGradient>
   <linearGradient id="e106i_ld" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#9CE87A"/><stop offset="1" stop-color="#3FB06A"/></linearGradient>
   <linearGradient id="e106i_rg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#B6F58A"/><stop offset="1" stop-color="#3FCB7A"/></linearGradient>
   <radialGradient id="e106i_sh" cx="35%" cy="30%" r="80%"><stop offset=".55" stop-color="#0A1A40" stop-opacity="0"/><stop offset="1" stop-color="#0A1A40" stop-opacity=".5"/></radialGradient>
   <linearGradient id="e106i_lf" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#C8FF8A"/><stop offset="1" stop-color="#4FC464"/></linearGradient>
   <clipPath id="e106i_gc"><circle r="64"/></clipPath>
  </defs>
  ${_e106iPlate(T,'#6EE0A0','#2A8FB0')}
  <g transform="rotate(${f(T*9)})">${_e106iArrow(0)}${_e106iArrow(1)}${_e106iArrow(2)}</g>
  <g transform="translate(0,${f(4+b(2.500,0,1.2))})">
    <circle r="64" fill="url(#e106i_oc)"/>
    <g clip-path="url(#e106i_gc)">
      <g transform="translate(0,0)">${_e106iLand(off)}</g>
      <ellipse cx="0" cy="-64" rx="36" ry="12" fill="#fff" opacity=".85"/><ellipse cx="0" cy="66" rx="30" ry="10" fill="#fff" opacity=".8"/>
      ${_e106iCloud(off2,-32,38)}${_e106iCloud((off2+70)%180,22,30)}${_e106iCloud((off2+30)%180,40,26)}
      <circle r="64" fill="url(#e106i_sh)"/>
      <path d="M-44 -30Q-36 -46 -18 -52" fill="none" stroke="#fff" stroke-opacity=".7" stroke-width="5" stroke-linecap="round"/>
    </g>
    <circle r="64" fill="none" ${st(C.navy,5)}/>
    <g transform="translate(${f(-4)},-58) rotate(${f(sw*.6)})">
      <path d="M0 2Q-2 -14 2 -26" fill="none" ${st(C.navy,8)}/><path d="M0 2Q-2 -14 2 -26" fill="none" stroke="#5DBB4F" stroke-width="3.500" stroke-linecap="round"/>
      <g transform="translate(2,-26)">
       <g transform="rotate(${f(-4+sw)}) scale(${f(grow)})"><path d="M0 0C-4 -16 -22 -22 -34 -12C-30 4 -12 8 0 0Z" fill="url(#e106i_lf)" ${st(C.navy,4)}/><path d="M-2 -2Q-16 -8 -28 -10" fill="none" stroke="#3E9E4F" stroke-width="2" stroke-linecap="round"/></g>
       <g transform="rotate(${f(4-sw)}) scale(${f(grow)})"><path d="M0 0C4 -18 24 -24 36 -14C32 4 12 8 0 0Z" fill="url(#e106i_lf)" ${st(C.navy,4)}/><path d="M2 -2Q16 -10 30 -12" fill="none" stroke="#3E9E4F" stroke-width="2" stroke-linecap="round"/></g>
      </g>
    </g>
  </g>
  ${_e106iS(-122,-40,9,T,0)}${_e106iS(122,-52,7,T,1.7,'#C8FFD8')}${_e106iS(110,70,8,T,3.1)}${_e106iS(-112,70,6,T,4.4,'#C8FFD8')}${_e106iS(0,-124,6,T,2.2)}${_e106iS(-30,116,6,T,5.1,'#C8FFD8')}
  </g>`};

/* A2 ep 6 props end */
/* A2 ep 7 props begin */
/* Episode 107 props: weather — hot summers, winter desert camping, a rainy green country, sand storms, floods, the coast, feelings, plans and tips for hot days. Faceless. Uses C, st, f, ease, clamp, P. */
const _e107pan=(id,inner,o={})=>{const w=o.w||260,h=o.h||210,r=o.r||18;return `<g><clipPath id="${id}"><rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="${r}"/></clipPath><g clip-path="url(#${id})">${inner}</g><rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="${r}" fill="none" ${st()}/></g>`};
const _e107rnd=(i,m)=>{const s=Math.sin(i*127.1+m*311.7)*43758.5453;return s-Math.floor(s)};
const _e107sun=(x,y,r,T,hot,n=12)=>{const c=hot?'#F28C38':'#F6CE4B',rc=hot?'#C9651B':'#C9971F';let ra='';for(let i=0;i<n;i++)ra+=`<line x1="0" y1="${f(-(r+9))}" x2="0" y2="${f(-(r+9+r*.4))}" transform="translate(${x},${y}) rotate(${f(i*360/n+T*12)})" ${st(rc,Math.max(3,r*.1))}/>`;return ra+`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" ${st(rc,Math.max(3,r*.07))}/><circle cx="${f(x-r*.3)}" cy="${f(y-r*.3)}" r="${f(r*.26)}" fill="#fff" opacity=".35"/>`};
const _e107hill=(y0,amp,wl,ph,fill,sc,w)=>{let e='';for(let x=-136;x<=136;x+=8){const y=y0+Math.sin(x/wl+ph)*amp+Math.sin(x/(wl*.43)+ph*2.1)*amp*.25;e+=(x===-136?'M':'L')+x+' '+f(y)+' '}return `<path d="${e}L136 130 L-136 130Z" fill="${fill}"/><path d="${e}" fill="none" ${st(sc||C.navy,w||4)}/>`};
const _e107star=(x,y,s,col,op)=>`<polygon points="0,-12 3,-3 12,0 3,3 0,12 -3,3 -12,0 -3,-3" transform="translate(${f(x)},${f(y)}) scale(${f(s)})" fill="${col||C.gold}" opacity="${op==null?1:f(op)}"/>`;
const _e107p=(x,y,s,o,T,extra)=>`<g transform="translate(${f(x)},${f(y)}) scale(${f(s)})">${P.person(o,T)}${extra||''}</g>`;
const _e107cap=(c)=>`<path d="M-40 -58 A40 40 0 0 1 40 -58 Z" fill="${c}" ${st(C.navy,5)}/><rect x="-44" y="-64" width="88" height="16" rx="8" fill="${C.cream}" ${st(C.navy,5)}/><circle cx="0" cy="-98" r="11" fill="${C.white}" ${st(C.navy,4)}/>`;
const _e107back=(x,y,s,c,hc)=>`<g transform="translate(${f(x)},${f(y)}) scale(${f(s)})"><path d="M-62 108 L-62 36 Q-62 -4 0 -4 Q62 -4 62 36 L62 108 Z" fill="${c}" ${st()}/><rect x="-11" y="-20" width="22" height="22" fill="#D79B70" ${st(C.navy,4)}/><circle cx="0" cy="-54" r="40" fill="${hc||'#3A2A22'}" ${st()}/><path d="M-22 -80 q14 -8 30 -2" fill="none" stroke="#fff" stroke-width="5" opacity=".18"/></g>`;
const _e107heat=(x,y,n,gap,T,col,w)=>{let s='';for(let i=0;i<n;i++){const ph=(T*.7+i/n)%1;s+=`<path d="M${f(x+i*gap)} ${f(y-ph*34)} q9 -9 0 -18 t0 -18" fill="none" ${st(col||'#E5604D',w||4)} opacity="${f(Math.sin(ph*Math.PI)*.85)}"/>`}return s};
const _e107snow=(x,y,r,col,w)=>{let s='';for(let i=0;i<3;i++)s+=`<line x1="${-r}" y1="0" x2="${r}" y2="0" transform="translate(${f(x)},${f(y)}) rotate(${i*60})" ${st(col||'#7FB6D6',w||4)}/>`;return s};
const _e107foot=(x,y,rot,fl,T)=>{let t='';[[-11,-24,5.5],[-3,-30,5],[6,-30,4.6],[13,-25,4.2],[18,-17,3.6]].forEach(([a,b,r])=>t+=`<circle cx="${a}" cy="${b}" r="${r}" fill="#E3AE82" ${st(C.navy,3)}/>`);return `<g transform="translate(${f(x)},${f(y)}) rotate(${rot}) scale(${fl},1)">${t}<path d="M-14 -12 Q-16 -26 0 -26 Q16 -26 16 -12 Q18 10 10 24 Q0 32 -8 24 Q-16 10 -14 -12Z" fill="#E3AE82" ${st(C.navy,4)}/></g>`};

/* ---------- temperature: thermometer + big number ---------- */
P.e107_temp=(o,T,k)=>{const deg=o.deg==null?45:o.deg,lv=o.lv==null?.9:o.lv,cur=lv*ease(k/1.1),col=o.col||(lv<.3?'#4DA3D8':lv<.62?'#F2994A':'#D9534F'),h=164*cur;let t='';
  for(let i=0;i<7;i++)t+=`<line x1="20" y1="${-92+i*24}" x2="${i%2?32:40}" y2="${-92+i*24}" ${st(C.navy,3.5)}/>`;
  const pul=1+.03*Math.sin(T*4),txt=String(deg)+'°',nn=o.nonum,ox=nn?0:-58;
  return `<g>${lv>.62?_e107heat(ox-26,-100,3,26,T):''}<g transform="translate(${ox},10)"><rect x="-19" y="-118" width="38" height="196" rx="19" fill="${C.white}" ${st()}/><circle cx="0" cy="96" r="34" fill="${C.white}" ${st()}/><rect x="-9" y="${f(80-h)}" width="18" height="${f(h+14)}" rx="9" fill="${col}"/><circle cx="0" cy="96" r="24" fill="${col}"/><circle cx="-7" cy="88" r="6" fill="#fff" opacity=".45"/><rect x="-11" y="-104" width="4" height="120" rx="2" fill="#fff" opacity=".6"/>${t}</g>${nn?'':`<g transform="translate(56,14) scale(${f(pul)})"><rect x="-62" y="-42" width="124" height="84" rx="20" fill="${C.cream}" ${st()}/><text x="0" y="20" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${txt.length>3?46:56}" fill="${C.navy}">${txt}</text></g>`}</g>`};

/* ---------- a hot oven ---------- */
P.e107_oven=(o,T)=>{const g=.75+.25*Math.sin(T*3);let k='';for(let i=0;i<4;i++)k+=`<circle cx="${-60+i*40}" cy="-70" r="9" fill="${C.cream}" ${st(C.navy,3.5)}/><line x1="${-60+i*40}" y1="-70" x2="${-60+i*40}" y2="-76" ${st(C.red,3)}/>`;
  return `<g>${_e107heat(-50,-96,4,34,T)}<rect x="-96" y="-98" width="192" height="190" rx="16" fill="#CBD6DC" ${st()}/><rect x="-96" y="-98" width="192" height="40" rx="16" fill="${C.navy2}" ${st()}/><rect x="-96" y="-76" width="192" height="18" fill="${C.navy2}"/><line x1="-96" y1="-58" x2="96" y2="-58" ${st()}/>${k}<rect x="-74" y="-40" width="148" height="12" rx="6" fill="#9FB0BA" ${st()}/><rect x="-70" y="-16" width="140" height="92" rx="12" fill="#3B2A24" ${st()}/><rect x="-60" y="-6" width="120" height="72" rx="8" fill="#F28C38" opacity="${f(g)}"/><rect x="-46" y="8" width="92" height="46" rx="6" fill="#FFD36B" opacity="${f(g*.9)}"/><line x1="-60" y1="14" x2="60" y2="14" ${st(C.navy,3.5)}/><line x1="-60" y1="42" x2="60" y2="42" ${st(C.navy,3.5)}/><path d="M-52 -2 l22 -0" stroke="#fff" stroke-width="5" stroke-linecap="round" opacity=".5"/><rect x="-80" y="92" width="22" height="12" rx="4" fill="${C.navy2}"/><rect x="58" y="92" width="22" height="12" rx="4" fill="${C.navy2}"/></g>`};

/* ---------- heat hitting a (faceless) person ---------- */
P.e107_hotface=(o,T,k)=>{const hit=Math.sin(T*3.4)*5;let w='';for(let i=0;i<3;i++){const dx=((T*60+i*40)%120)-30;w+=`<g transform="translate(${f(-62+i*8)},${f(-66+i*38)}) rotate(24)"><path d="M${f(dx)} 0 q8 -10 16 0 t16 0 t16 0 t16 0" fill="none" ${st('#E5604D',6)} opacity="${f(clamp(1-Math.abs(dx-30)/70))}"/></g>`}
  return `<g>${_e107sun(-72,-74,42,T,1)}${w}${_e107p(56+hit,38,.8,{c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g>`};

/* ---------- panel: desert sky, enormous sun, no clouds ---------- */
P.e107_desertsky=(o,T)=>{let sh='';for(let i=0;i<3;i++)sh+=`<path d="M-120 ${44+i*14} q15 -7 30 0 t30 0 t30 0 t30 0 t30 0 t30 0 t30 0 t30 0" transform="translate(${f(Math.sin(T*1.4+i)*8)},0)" fill="none" stroke="#fff" stroke-width="3" opacity=".45"/>`;
  return _e107pan('e107_cdk',`<rect x="-140" y="-110" width="280" height="230" fill="#8FD0EE"/><rect x="-140" y="-110" width="280" height="90" fill="#7DC4E8"/>${_e107sun(0,-44,60,T,1,16)}${_e107hill(40,10,46,.5,'#EBC98A')}${_e107hill(68,9,38,2,'#D9AE62')}${sh}`)};

/* ---------- panel: a lonely tree, still hot ---------- */
P.e107_shade=(o,T)=>{const sw=Math.sin(T*1.2)*1.5;
  return _e107pan('e107_csh',`<rect x="-140" y="-110" width="280" height="230" fill="#9ED8F2"/>${_e107sun(76,-62,34,T,1)}${_e107hill(52,6,50,1,'#E6C88A')}<ellipse cx="-12" cy="72" rx="82" ry="14" fill="#7A5A3A" opacity=".35"/><g transform="translate(-14,66) scale(.78) rotate(${f(sw)} 0 100)"><rect x="-12" y="-80" width="24" height="112" fill="${C.brown}" ${st()}/><g transform="translate(0,-56) scale(1.1)">${blob([[0,-56,58],[-48,-10,42],[48,-10,42],[0,-6,40]],C.leaf)}</g></g>${_e107p(-30,72,.34,{c:'#E2B653',hair:'bun',hc:'#2A1D18'},T)}${_e107heat(-110,50,3,16,T,'#E5604D',3.5)}${_e107heat(70,56,3,14,T,'#E5604D',3.5)}<g transform="translate(14,44)"><path d="M0 0 q-5 8 0 12 q5 -4 0 -12" fill="${C.blue}"/></g>`)};

/* ---------- panel: hot tiles by the pool, bare feet ---------- */
P.e107_hotground=(o,T,k)=>{const lift=Math.abs(Math.sin(T*5.2))*8;let tl='';for(let r=0;r<4;r++)for(let c=-6;c<=6;c++)tl+=`<rect x="${c*40+(r%2)*20-18}" y="${-20+r*34}" width="38" height="32" fill="${(r+c)%2?'#EBCB9A':'#E6C28A'}" stroke="#C99A58" stroke-width="2"/>`;
  let wv='';for(let r=0;r<2;r++)wv+=`<path d="M-120 ${-80+r*26} q15 -9 30 0 t30 0 t30 0 t30 0 t30 0 t30 0 t30 0 t30 0" fill="none" stroke="#fff" stroke-width="${4-r*.5}" opacity="${.7-r*.2}" transform="translate(${f(Math.sin(T*1.6+r)*6)},0)"/>`;
  return _e107pan('e107_chg',`<rect x="-140" y="-110" width="280" height="230" fill="#BFE3F2"/><rect x="-140" y="-110" width="280" height="86" fill="#5BB9E0"/>${wv}<rect x="-140" y="-26" width="280" height="12" fill="#F4EEDC" stroke="${C.navy}" stroke-width="4"/>${tl}<ellipse cx="0" cy="34" rx="100" ry="42" fill="#F28C38" opacity="${f(.3+.12*Math.sin(T*4))}"/>${_e107heat(-70,86,5,34,T,'#E5604D',4.5)}${_e107foot(-28,f(38-lift),-6,1,T)}${_e107foot(30,f(48-lift*.5),8,-1,T)}`)};

/* ---------- a cat running (silhouette, no face) ---------- */
P.e107_runcat=(o,T)=>{const a=Math.sin(T*14)*16,col='#E39B4B',dk='#B7702A';let sp='';for(let i=0;i<3;i++){const ph=(T*2.2+i/3)%1;sp+=`<line x1="${f(-70-ph*30)}" y1="${-10+i*26}" x2="${f(-112-ph*30)}" y2="${-10+i*26}" ${st('#9AA7B0',5)} opacity="${f(1-ph)}"/>`}
  const leg=(x,ang)=>`<g transform="translate(${x},34) rotate(${f(ang)})"><path d="M0 0 L0 62" ${st(dk,15)}/><path d="M0 0 L0 62" ${st(col,9)}/></g>`;
  return `<g transform="translate(0,${f(-Math.abs(Math.sin(T*7))*6)})">${sp}<ellipse cx="0" cy="104" rx="84" ry="9" fill="#000" opacity=".12"/>${leg(-46,-a-18)}${leg(-26,a-6)}${leg(32,-a+8)}${leg(54,a+22)}<path d="M-58 14 C-100 -10 -104 -62 -78 -88" fill="none" ${st(dk,17)}/><path d="M-58 14 C-100 -10 -104 -62 -78 -88" fill="none" ${st(col,10)}/><ellipse cx="0" cy="22" rx="68" ry="34" fill="${col}" ${st()}/><path d="M-30 4 q18 -10 38 -4 M-20 22 q20 -8 44 -2" fill="none" stroke="${dk}" stroke-width="5" stroke-linecap="round" opacity=".6"/><circle cx="70" cy="-6" r="29" fill="${col}" ${st()}/><polygon points="52,-26 54,-56 72,-34" fill="${col}" ${st()}/><polygon points="76,-34 94,-54 92,-20" fill="${col}" ${st()}/><polygon points="55,-32 57,-46 66,-36" fill="#F4C6A8"/><polygon points="80,-34 88,-44 88,-28" fill="#F4C6A8"/></g>`};

/* ---------- full-body running child (faceless), feet at y=108 ---------- */
const _e107run=(col,hc,T,sp)=>{const a=Math.sin(T*(sp||11))*26;
  const leg=(ang)=>`<g transform="translate(0,46) rotate(${f(ang)})"><path d="M0 0 L0 50" ${st(C.navy,18)}/><path d="M0 0 L0 50" ${st('#3F5A73',11)}/><ellipse cx="9" cy="54" rx="17" ry="9" fill="${C.white}" ${st()}/></g>`;
  const arm=(ang)=>`<g transform="translate(0,-20) rotate(${f(ang)})"><path d="M0 0 L0 42" ${st(C.navy,15)}/><path d="M0 0 L0 42" ${st('#E3AE82',9)}/></g>`;
  return `<g transform="rotate(8 0 100)">${arm(-a-30)}${leg(a+7)}${leg(-a+16)}<path d="M-30 52 L-34 -22 Q-34 -34 0 -34 Q34 -34 34 -22 L30 52 Z" fill="${col}" ${st()}/>${arm(a-30)}<circle cx="0" cy="-62" r="30" fill="#E3AE82" ${st()}/><path d="M-30 -66 Q-32 -96 0 -96 Q32 -96 30 -66 Q8 -80 -30 -66Z" fill="${hc}" ${st()}/></g>`};
/* ---------- a boy running with speed lines ---------- */
P.e107_kidfast=(o,T)=>{let sp='';for(let i=0;i<3;i++){const ph=(T*2.4+i/3)%1;sp+=`<line x1="${f(-52-ph*30)}" y1="${-30+i*34}" x2="${f(-92-ph*30)}" y2="${-30+i*34}" ${st('#9AA7B0',5)} opacity="${f(1-ph)}"/>`}
  const j=Math.abs(Math.sin(T*5.5))*8;return `<g>${sp}<ellipse cx="4" cy="108" rx="62" ry="9" fill="#000" opacity=".13"/><g transform="translate(0,${f(-j)})">${_e107run(o.c||'#F2994A',o.hc||'#3A2A22',T)}</g></g>`};

/* ---------- shopping centre ---------- */
P.e107_mall=(o,T)=>{let wn='';[-92,-66].forEach(x=>wn+=`<rect x="${x}" y="-20" width="20" height="62" fill="${C.sky}" ${st(C.navy,3)}/>`);[72,46].forEach(x=>wn+=`<rect x="${x}" y="-20" width="20" height="62" fill="${C.sky}" ${st(C.navy,3)}/>`);
  const c=1+.06*Math.sin(T*3);let air='';for(let i=0;i<3;i++){const ph=(T*.8+i/3)%1;air+=`<path d="M${f(-18+i*18)} ${f(46+ph*14)} q-5 7 0 14" fill="none" ${st('#7FB6D6',4)} opacity="${f(1-ph)}"/>`}
  return `<g><rect x="-110" y="-48" width="220" height="128" fill="#F4E5C2" ${st()}/><rect x="-118" y="-84" width="236" height="40" rx="8" fill="${C.moss}" ${st()}/><text x="0" y="-54" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" fill="${C.cream}" letter-spacing="8">MALL</text>${wn}<path d="M-46 -20 H46 V0 H-46Z" fill="${C.red}" ${st(C.navy,3)}/><rect x="-40" y="0" width="80" height="80" fill="#CFE9F4" ${st()}/><line x1="0" y1="0" x2="0" y2="80" ${st(C.navy,4)}/><path d="M-30 12 l14 -0 M-30 24 l22 -0" stroke="#fff" stroke-width="5" stroke-linecap="round" opacity=".7"/><rect x="-124" y="80" width="248" height="12" rx="4" fill="#DCD2B8" ${st()}/>${air}<g transform="translate(92,-96) scale(${f(c)})"><circle r="26" fill="#EAF6FB" ${st('#7FB6D6',4)}/>${_e107snow(0,0,16,'#4DA3D8',4)}</g></g>`};

/* ---------- air conditioner blowing cool air ---------- */
P.e107_cool=(o,T)=>{let fl='';for(let i=0;i<5;i++){const ph=(T*.7+i/5)%1,x=-70+i*35+Math.sin(T*2+i)*6,y=-20+ph*130;fl+=`<g opacity="${f(Math.sin(ph*Math.PI))}">${_e107snow(x,y,12,'#4DA3D8',3.5)}</g>`}
  let w='';for(let i=0;i<3;i++){const ph=(T*.9+i/3)%1;w+=`<path d="M${-60+i*60} ${f(-18+ph*40)} q-10 12 0 24 t0 24" fill="none" ${st('#9FD0EA',5)} opacity="${f(1-ph)}"/>`}
  return `<g><rect x="-112" y="-104" width="224" height="84" rx="24" fill="${C.white}" ${st()}/><rect x="-92" y="-62" width="184" height="20" rx="10" fill="#DCE5EA" ${st(C.navy,3)}/><rect x="-92" y="-88" width="70" height="12" rx="6" fill="#DCE5EA" ${st(C.navy,3)}/><circle cx="88" cy="-84" r="6" fill="#52C27A" ${st(C.navy,3)}/>${w}${fl}</g>`};

/* ---------- city at sunset / night ---------- */
P.e107_dusk=(o,T)=>{const n=o.night;let b='';const hs=[56,88,44,104,70,92,52,80];hs.forEach((h,i)=>{const x=-136+i*36;b+=`<rect x="${x}" y="${100-h}" width="32" height="${h+30}" fill="${n?'#1B2A4A':'#4A4E73'}" stroke="${C.navy}" stroke-width="4"/>`;for(let r=0;r<Math.floor(h/24);r++)for(let c=0;c<2;c++){const lit=(i*7+r*3+c)%3!==0;b+=`<rect x="${x+5+c*13}" y="${100-h+8+r*22}" width="9" height="12" fill="${lit?(n?'#FFE08A':'#FFD36B'):'#6C7092'}" opacity="${lit?1:.6}"/>`}});
  let sky='',st2='';if(n){sky=`<rect x="-140" y="-110" width="280" height="240" fill="#1E3A66"/><rect x="-140" y="30" width="280" height="100" fill="#26497D"/>`;[[-100,-80],[-60,-50],[-20,-86],[40,-60],[90,-84],[110,-36],[-110,-20],[0,-30]].forEach(([x,y],i)=>st2+=_e107star(x,y,.5+.3*Math.sin(T*3+i),'#fff'));st2+=`<path d="M52 -88 A34 34 0 1 0 74 -34 A27 27 0 0 1 52 -88 Z" fill="#F7E7A8" ${st()}/>`}
  else{sky=`<rect x="-140" y="-110" width="280" height="240" fill="#7B6AA8"/><rect x="-140" y="-40" width="280" height="90" fill="#E8836B"/><rect x="-140" y="10" width="280" height="60" fill="#F6B25A"/>`;st2=`<clipPath id="e107_cdsun"><rect x="-140" y="-110" width="280" height="148"/></clipPath><g clip-path="url(#e107_cdsun)"><circle cx="0" cy="${f(46-clamp(T*0)*0)}" r="50" fill="#F28C38" ${st('#C9651B',5)}/></g>`}
  return _e107pan('e107_cdu',sky+st2+b)};

/* ---------- park at night: lamps, trees, people strolling ---------- */
P.e107_parknight=(o,T)=>{let ppl='';[[0,'#E2B653','bun'],[1,'#4DA3D8','short'],[2,'#D96C8B','long']].forEach(([i,c,h])=>{const x=-90+((T*14+i*80)%240);ppl+=_e107p(x,70,.3,{c,hair:h,hc:'#2A1D18',ph:i*2},T)});
  let lamps='';[-84,10,98].forEach((x,i)=>{lamps+=`<circle cx="${x}" cy="-26" r="${f(26+3*Math.sin(T*2+i))}" fill="#FFE08A" opacity=".3"/><rect x="${x-3}" y="-20" width="6" height="86" fill="${C.navy2}"/><rect x="${x-9}" y="-34" width="18" height="16" rx="5" fill="#FFE08A" ${st(C.navy,3.5)}/>`});
  let sts='';[[-100,-84],[-50,-70],[10,-90],[70,-74],[112,-92],[40,-52]].forEach(([x,y],i)=>sts+=_e107star(x,y,.45+.25*Math.sin(T*3+i),'#fff'));
  return _e107pan('e107_cpn',`<rect x="-140" y="-110" width="280" height="240" fill="#1E3A66"/>${sts}<path d="M60 -96 A30 30 0 1 0 78 -50 A23 23 0 0 1 60 -96 Z" fill="#F7E7A8" ${st(C.navy,4)}/><g transform="translate(-100,40) scale(.7)">${blob([[0,-56,58],[-42,-12,40],[42,-12,40],[0,-6,36]],'#3E7A57')}<rect x="-12" y="14" width="24" height="60" fill="#5A3E2A" ${st()}/></g><g transform="translate(112,36) scale(.6)">${blob([[0,-56,58],[-42,-12,40],[42,-12,40],[0,-6,36]],'#3E7A57')}<rect x="-12" y="14" width="24" height="60" fill="#5A3E2A" ${st()}/></g><rect x="-140" y="64" width="280" height="70" fill="#2E5A55" stroke="${C.navy}" stroke-width="4"/><path d="M-140 112 Q0 70 140 112" fill="none" stroke="#C8B58A" stroke-width="22" opacity=".8"/>${lamps}${ppl}`)};

/* ---------- thought bubble with an icon ---------- */
P.e107_think=(o,T)=>{const p=o.p||{c:'#E2B653',hair:'bun',hc:'#2A1D18'};const ic=o.icon&&P[o.icon]?P[o.icon](o.io||{},T,99):'';
  return `<g>${_e107p(-52,48,.62,p,T)}<circle cx="-30" cy="-30" r="9" fill="${C.white}" ${st(C.navy,4)}/><circle cx="-6" cy="-52" r="14" fill="${C.white}" ${st(C.navy,4)}/><g transform="translate(46,-66)">${blob([[-50,12,34],[-6,-16,48],[44,-4,40],[62,22,28],[-14,24,36],[26,28,32]],C.white)}<g transform="translate(6,6) scale(${o.is||.46})">${ic}</g></g></g>`};
P.e107_swirl=(o,T)=>{let d='';for(let a=0;a<=720;a+=18){const r=6+a/720*70,x=Math.cos((a+T*120)*Math.PI/180)*r,y=Math.sin((a+T*120)*Math.PI/180)*r;d+=(a?'L':'M')+f(x)+' '+f(y)+' '}return `<g><circle r="88" fill="${C.gold}" ${st()}/><path d="${d}" fill="none" ${st(C.navy,8)}/></g>`};

/* ---------- lovely winter day: bright blue sky, a few white clouds, family sitting outside ---------- */
P.e107_winterday=(o,T)=>{let cl='';[[-20,-72,.34,0],[56,-80,.26,1.6],[100,-44,.2,3]].forEach(([x,y,s,ph])=>cl+=`<g transform="translate(${f(x+Math.sin(T*.6+ph)*6)},${y}) scale(${s})">${cloudShape()}</g>`);
  const fam=o.sit?`<ellipse cx="0" cy="84" rx="110" ry="14" fill="#000" opacity=".1"/><path d="M-96 100 L-70 56 L70 56 L96 100Z" fill="#F4E5C2" ${st()}/><path d="M-84 90 L-62 64 M-40 90 L-20 64 M10 90 L30 64 M58 90 L76 64" stroke="${C.red}" stroke-width="7" opacity=".6"/>${_e107p(-44,18,.3,{c:'#E2B653',hair:'bun',hc:'#2A1D18'},T)}${_e107p(0,12,.34,{c:'#4DA3D8',hair:'short',hc:'#222'},T)}${_e107p(46,20,.28,{c:'#D96C8B',hair:'long',hc:'#3A2A22'},T)}<g transform="translate(86,52) scale(.4)"><path d="M-40 -10 L40 -10 L34 36 L-34 36Z" fill="#C98842" ${st()}/><path d="M-36 -10 Q0 -64 36 -10" fill="none" ${st(C.navy,6)}/></g>`:'';
  return _e107pan('e107_cwd',`<rect x="-140" y="-110" width="280" height="240" fill="#A7DCF2"/>${_e107sun(-84,-70,24,T,0)}${cl}${_e107hill(34,8,52,.6,'#8DBF7E')}${_e107hill(58,7,40,2,'#6FAE6A')}${fam}`)};

/* ---------- desert after rain: green grass everywhere (o.rain: with rain cloud) ---------- */
P.e107_greendesert=(o,T,k)=>{let g='';for(let i=0;i<46;i++){const x=-124+_e107rnd(i,1)*248,y=26+_e107rnd(i,2)*80,gr=o.nograss?0:ease((k-.3-_e107rnd(i,3)*1.2)/.6),h=(8+_e107rnd(i,4)*9)*gr;g+=`<path d="M${f(x-4)} ${f(y)} L${f(x-6)} ${f(y-h)} L${f(x)} ${f(y-h*.6)} L${f(x+1)} ${f(y-h*1.2)} L${f(x+4)} ${f(y-h*.6)} L${f(x+7)} ${f(y-h*.9)} L${f(x+5)} ${f(y)}Z" fill="#5E9B63" stroke="#3F7A47" stroke-width="1.5"/>`}
  let rn='';if(o.rain){let d='';for(let i=0;i<10;i++){const x=-100+i*22,y=((T*170+i*41)%100);d+=`<line x1="${x}" y1="${f(-34+y)}" x2="${x-7}" y2="${f(-14+y)}" ${st(C.blue,4.5)} opacity="${f(1-y/110)}"/>`}rn=`<g transform="translate(0,-62) scale(1.3,1)">${cloudShape('#C9D5DC')}</g>${d}`}
  return _e107pan('e107_cgd',`<rect x="-140" y="-110" width="280" height="240" fill="${o.rain?'#B9C9D2':'#A7DCF2'}"/>${o.rain?'':_e107sun(78,-68,24,T,0)}${_e107hill(10,12,46,.8,o.nograss?'#EBC98A':'#D8D286')}${_e107hill(50,9,36,2.4,o.nograss?'#D9AE62':'#B9C873')}${g}${rn}`)};

/* ---------- the road from the city into the desert ---------- */
P.e107_drive=(o,T)=>{let dash='';for(let i=0;i<6;i++){const ph=(i*.18+T*.5)%1,y=-6+ph*110,w=3+ph*8;dash+=`<rect x="${f(-w/2)}" y="${f(y)}" width="${f(w)}" height="${f(6+ph*14)}" fill="#fff"/>`}
  let city='';[[-110,22],[-92,34],[-76,18],[-60,28]].forEach(([x,h],i)=>city+=`<rect x="${x}" y="${-20-h}" width="14" height="${h+30}" fill="#8A9BA6" ${st(C.navy,3)}/>`);
  return _e107pan('e107_cdr',`<rect x="-140" y="-110" width="280" height="240" fill="#A7DCF2"/>${_e107sun(80,-72,26,T,0)}${_e107hill(-6,8,50,.3,'#EBC98A')}${city}${_e107hill(10,10,40,2,'#D9AE62')}<polygon points="-6,-6 6,-6 100,120 -100,120" fill="#5B6770" ${st(C.navy,4)}/>${dash}<g transform="translate(34,60) scale(.42)"><g transform="translate(0,${f(Math.sin(T*9)*1.4)})">${P.car({},T)}</g></g>`)};

/* ---------- tent ---------- */
P.e107_tent=(o,T)=>{const c=o.c||C.orange,fl=Math.sin(T*4)*6;
  return `<g><ellipse cx="0" cy="84" rx="120" ry="14" fill="#000" opacity=".12"/><line x1="-92" y1="84" x2="-62" y2="62" ${st(C.navy,4)}/><line x1="92" y1="84" x2="62" y2="62" ${st(C.navy,4)}/><line x1="0" y1="-98" x2="0" y2="-124" ${st(C.navy,5)}/><path d="M0 -124 h${f(26+fl)} l-8 8 l8 8 h${f(-26-fl)}Z" fill="${C.red}" ${st(C.navy,3.5)}/><polygon points="-86,84 0,-96 86,84" fill="${c}" ${st()}/><polygon points="0,-96 86,84 22,84" fill="#000" opacity=".12"/><polygon points="-18,-32 -40,84 40,84 18,-32" fill="none"/><path d="M0 -50 L-30 84 L30 84Z" fill="#3B2A24" ${st()}/><path d="M0 -50 L-30 84 L-6 84Z" fill="${c}" ${st()}/><path d="M0 -50 L30 84 L8 84Z" fill="${c}" ${st()} opacity=".96"/><circle cx="0" cy="-8" r="5" fill="${C.cream}" ${st(C.navy,3)}/><line x1="-60" y1="30" x2="-34" y2="22" stroke="#fff" stroke-width="5" opacity=".4" stroke-linecap="round"/></g>`};

/* ---------- camp in the desert (day or night) ---------- */
P.e107_camp=(o,T)=>{const n=o.night;let sts='';if(n)for(let i=0;i<26;i++)sts+=_e107star(-124+_e107rnd(i,5)*248,-100+_e107rnd(i,6)*90,.3+_e107rnd(i,7)*.4+.18*Math.sin(T*3+i),'#fff');
  const tent=(x,y,s,c)=>`<g transform="translate(${x},${y}) scale(${s})"><polygon points="-66,50 0,-62 66,50" fill="${c}" ${st(C.navy,6)}/><path d="M0 -26 L-22 50 L22 50Z" fill="${n?'#FFD36B':'#3B2A24'}" ${st(C.navy,5)}/></g>`;
  return _e107pan('e107_ccm',`<rect x="-140" y="-110" width="280" height="240" fill="${n?'#142A52':'#A7DCF2'}"/>${n?sts+`<path d="M56 -92 A28 28 0 1 0 74 -46 A22 22 0 0 1 56 -92 Z" fill="#F7E7A8" ${st(C.navy,4)}/>`:_e107sun(84,-70,24,T,0)}${_e107hill(20,9,46,.5,n?'#7A6A3E':'#EBC98A')}${_e107hill(62,8,38,2,n?'#5C4E2C':'#D9AE62')}${tent(-82,44,.62,C.orange)}${tent(2,52,.8,'#4DA3D8')}${tent(84,42,.62,C.red)}${n?`<g transform="translate(-34,76) scale(.3)">${P.fire({},T)}</g>`:`<g transform="translate(-44,84) scale(.2)">${P.car({},T)}</g>`}`)};

/* ---------- a big group: exactly 30 faceless people ---------- */
P.e107_group30=(o,T)=>{const cols=['#E2B653','#4DA3D8','#D96C8B','#4F7A5A','#F2994A','#8E6BB5','#C0504D','#6A8FA8'],hs=['bun','short','long'],hcs=['#2A1D18','#222','#3A2A22','#8B5E3C','#BDC3C7'];let s='';
  for(let r=0;r<5;r++)for(let c=0;c<6;c++){const i=r*6+c,x=-100+c*40+(r%2)*10-5,y=-62+r*38;s+=_e107p(x,y,.3,{c:cols[(i*3+r)%8],hair:hs[(i+r)%3],hc:hcs[(i*7)%5],ph:i*.7},T)}
  return `<g>${s}</g>`};

/* ---------- panel: small yellow hills and sky everywhere (nothing else) ---------- */
P.e107_dunes=(o,T)=>{let rp='';for(let i=0;i<4;i++)rp+=`<path d="M${-100+i*14} ${60+i*11} q30 -8 60 0" fill="none" stroke="#C99A4E" stroke-width="3" opacity=".7"/>`;
  return _e107pan('e107_cdn',`<rect x="-140" y="-110" width="280" height="240" fill="#A7DCF2"/><rect x="-140" y="-110" width="280" height="70" fill="#8FD0EE"/>${_e107hill(10,12,60,.4,'#F0D395')}${_e107hill(40,12,50,2.2,'#E2BD72')}${_e107hill(78,10,44,4,'#D6A95C')}${rp}`)};

/* ---------- children running up and down a small hill ---------- */
P.e107_hillkids=(o,T)=>{const hy=x=>72-96*Math.exp(-Math.pow((x-10)/72,2));let pth='';for(let x=-136;x<=136;x+=8)pth+=(x===-136?'M':'L')+x+' '+f(hy(x))+' ';
  let kids='';[['#F2994A','#3A2A22'],['#D96C8B','#2A1D18'],['#4DA3D8','#222']].forEach(([c,h],i)=>{const u=(T*.22+i/3)%1,tri=u<.5?u*2:2-u*2,x=-86+tri*92,up=u<.5,ys=hy(x);kids+=`<g transform="translate(${f(x)},${f(ys-108*.26+6)}) scale(${up?.26:-.26},.26)">${_e107run(c,h,T,9)}</g>`});
  return _e107pan('e107_chk',`<rect x="-140" y="-110" width="280" height="240" fill="#A7DCF2"/>${_e107sun(-88,-66,24,T,0)}<path d="${pth}L136 130 L-136 130Z" fill="#EBC98A"/><path d="${pth}" fill="none" ${st(C.navy,4)}/><path d="M-60 100 Q10 70 80 100" fill="none" stroke="#D6A95C" stroke-width="3"/>${kids}`)};

/* ---------- cold desert night: coats, hats and a fire ---------- */
P.e107_nightfire=(o,T)=>{let sts='';for(let i=0;i<20;i++)sts+=_e107star(-124+_e107rnd(i,8)*248,-100+_e107rnd(i,9)*70,.28+_e107rnd(i,3)*.35+.15*Math.sin(T*3+i),'#fff');
  const gl=1+.06*Math.sin(T*9);
  const pr=(x,y,s,c,cap)=>_e107p(x,y,s,{c,hair:'short',hc:'#222',ph:x},T,_e107cap(cap));
  return _e107pan('e107_cnf',`<rect x="-140" y="-110" width="280" height="240" fill="#142A52"/>${sts}${_e107hill(40,8,50,.5,'#6B5A34')}${_e107hill(74,6,40,2,'#54472A')}<circle cx="0" cy="48" r="${f(86*gl)}" fill="#F28C38" opacity=".22"/>${pr(-82,56,.34,'#4F7A5A',C.red)}${pr(82,56,.34,'#8E6BB5','#4DA3D8')}${pr(-44,42,.3,'#C0504D',C.gold)}${pr(44,42,.3,'#4DA3D8',C.red)}<g transform="translate(0,56) scale(.46)">${P.fire({},T)}</g>`)};

/* ---------- panel: starry sky in the desert (many stars) ---------- */
P.e107_stars=(o,T)=>{let sts='';for(let i=0;i<90;i++){const x=-130+_e107rnd(i,11)*260,y=-104+_e107rnd(i,12)*150,s=.22+_e107rnd(i,13)*.55;sts+=_e107star(x,y,s*(.85+.25*Math.sin(T*2.6+i)),i%7?'#fff':C.gold)}
  return _e107pan('e107_cst',`<rect x="-140" y="-110" width="280" height="240" fill="#102450"/><path d="M-130 70 Q-20 -10 130 -80" fill="none" stroke="#3B5A9A" stroke-width="40" opacity=".25"/>${sts}${_e107hill(78,8,50,.6,'#0A1730','#050B1A')}`)};

/* ---------- panel: night sky above a city: lights, exactly ten stars ---------- */
P.e107_citysky=(o,T)=>{let b='';const hs=[44,70,52,86,60,78,48,64];hs.forEach((h,i)=>{const x=-136+i*36;b+=`<rect x="${x}" y="${100-h}" width="32" height="${h+30}" fill="#1B2A4A" stroke="${C.navy}" stroke-width="4"/>`;for(let r=0;r<Math.floor(h/22);r++)for(let c=0;c<2;c++)if((i+r+c)%3)b+=`<rect x="${x+5+c*13}" y="${100-h+8+r*21}" width="9" height="11" fill="#FFE08A"/>`});
  const sp=[[-104,-84],[-70,-46],[-30,-92],[8,-60],[44,-96],[84,-52],[112,-84],[-8,-24],[70,-18],[-100,-12]];let sts='';sp.forEach(([x,y],i)=>sts+=_e107star(x,y,.62+.18*Math.sin(T*3+i),'#fff'));
  return _e107pan('e107_ccs',`<rect x="-140" y="-110" width="280" height="240" fill="#2C3E70"/><rect x="-140" y="-10" width="280" height="140" fill="#5A5A86" opacity=".55"/><rect x="-140" y="30" width="280" height="100" fill="#8A6A78" opacity=".5"/>${sts}${b}`)};

/* ---------- lying on a big carpet, looking at the stars ---------- */
P.e107_carpet=(o,T)=>{let sts='';for(let i=0;i<34;i++)sts+=_e107star(-126+_e107rnd(i,21)*252,-102+_e107rnd(i,22)*100,.25+_e107rnd(i,23)*.5+.15*Math.sin(T*2.8+i),i%6?'#fff':C.gold);
  const lie=(x,y,c,hc)=>`<g transform="translate(${x},${y})"><rect x="-4" y="-7" width="46" height="16" rx="8" fill="${c}" ${st(C.navy,3.5)}/><circle cx="-14" cy="0" r="11" fill="#E3AE82" ${st(C.navy,3.5)}/><path d="M-24 -2 Q-22 -13 -10 -10 Q-4 -4 -14 -3Z" fill="${hc}" ${st(C.navy,2.5)}/></g>`;
  let pat='';for(let i=0;i<8;i++)pat+=`<path d="M${-72+i*20} 62 l10 -8 l10 8 l-10 8Z" fill="${i%2?C.gold:C.cream}" ${st(C.navy,1.5)}/>`;
  return _e107pan('e107_ccp',`<rect x="-140" y="-110" width="280" height="240" fill="#102450"/>${sts}${_e107hill(32,8,50,.6,'#3B3322','#1A1608')}<rect x="-140" y="46" width="280" height="90" fill="#3B3322"/><path d="M-110 100 L-84 40 L84 40 L110 100Z" fill="${C.red}" ${st(C.navy,5)}/><path d="M-98 94 L-76 48 L76 48 L98 94Z" fill="none" stroke="${C.gold}" stroke-width="4"/>${pat}<g transform="translate(0,6)">${lie(-74,58,'#4DA3D8','#222')}${lie(-16,66,'#E2B653','#2A1D18')}${lie(42,58,'#D96C8B','#3A2A22')}</g>`)};

/* ---------- a far continent: globe with a pin ---------- */
P.e107_globe=(o,T,k)=>{const bn=Math.abs(Math.sin(T*3))*8,pop=ease(k/.5);
  return `<g><g transform="translate(-6,10) scale(.92)">${P.globe({},T)}</g><path d="M-122 96 Q-70 20 -4 -26" fill="none" ${st(C.navy,4)} stroke-dasharray="2 12"/><g transform="translate(34,${f(-32-bn)}) scale(${f(pop)})"><ellipse cx="0" cy="${f(40+bn)}" rx="${f(18-bn*.4)}" ry="6" fill="#000" opacity=".2"/><path d="M0 34 C-34 -4 -30 -38 0 -40 C30 -38 34 -4 0 34Z" fill="${C.red}" ${st()}/><circle cx="0" cy="-16" r="10" fill="${C.cream}" ${st(C.navy,3.5)}/></g></g>`};

/* ---------- cold green country: grey sky, rolling green hills, rain ---------- */
const _e107tree=(x,y,s,c)=>`<g transform="translate(${x},${y}) scale(${s})"><rect x="-8" y="-6" width="16" height="44" fill="${C.brown}" ${st(C.navy,5)}/>${blob([[0,-34,34],[-24,-8,24],[24,-8,24]],c||C.leaf,5)}</g>`;
P.e107_greenland=(o,T)=>{const rn=o.rain==null?1:o.rain;let d='';if(rn)for(let i=0;i<14;i++){const x=-124+i*19,y=((T*180+i*47)%130);d+=`<line x1="${x}" y1="${f(-40+y)}" x2="${x-8}" y2="${f(-22+y)}" ${st(C.blue,4)} opacity="${f(1-y/140)}"/>`}
  return _e107pan('e107_cgl',`<rect x="-140" y="-110" width="280" height="240" fill="#B4C4CD"/>${[[-70,-70,.9,0],[40,-82,1.1,2],[100,-56,.7,4]].map(([x,y,s,p])=>`<g transform="translate(${f(x+Math.sin(T*.5+p)*7)},${y}) scale(${s})">${cloudShape('#DCE5EA')}</g>`).join('')}${_e107hill(0,12,46,.8,'#8DBF7E')}${_e107hill(40,10,38,2.4,'#6FAE6A')}${_e107tree(-86,44,.52)}${_e107tree(90,40,.46,'#4F8F57')}${_e107hill(82,7,36,4,'#4F8F57')}${d}`)};

/* ---------- three weeks, a raindrop every single day ---------- */
P.e107_raincal=(o,T,k)=>{let g='';for(let r=0;r<3;r++)for(let c=0;c<7;c++){const i=r*7+c,p=ease((k-.2-i*.09)/.3);g+=`<rect x="${-96+c*28}" y="${-44+r*44}" width="24" height="38" rx="6" fill="#DCE5EA" ${st(C.navy,2.5)}/><g transform="translate(${-84+c*28},${-25+r*44}) scale(${f(.19*p)})"><path d="M0 -40 C20 -12 28 -2 28 12 a28 28 0 0 1 -56 0 C-28 -2 -20 -12 0 -40Z" fill="${C.blue}" ${st(C.navy,5)}/></g>`}
  return `<g><rect x="-114" y="-104" width="228" height="206" rx="18" fill="${C.white}" ${st()}/><path d="M-114 -66 V-86 Q-114 -104 -96 -104 H96 Q114 -104 114 -86 V-66 Z" fill="${C.red}" ${st()}/><circle cx="-62" cy="-108" r="7" fill="${C.navy}"/><circle cx="62" cy="-108" r="7" fill="${C.navy}"/><g transform="translate(0,12)">${g}</g></g>`};

/* ---------- a whole year: 365 small squares, only ten rainy days ---------- */
P.e107_yearrain=(o,T,k)=>{const rainy=new Set([14,71,98,130,175,203,241,289,322,350]);let g='';for(let r=0;r<5;r++)for(let c=0;c<73;c++){const i=r*73+c,on=rainy.has(i);g+=on?`<rect x="${f(-118.5+c*3.2)}" y="${-31+r*17}" width="4.6" height="20" rx="1.2" fill="${C.blue}" stroke="${C.navy}" stroke-width="1.2"/>`:`<rect x="${f(-117+c*3.2)}" y="${-28+r*17}" width="2.8" height="14" rx=".6" fill="#F2C24A"/>`}
  return `<g><rect x="-132" y="-86" width="264" height="148" rx="18" fill="${C.cream}" ${st()}/><text x="0" y="-48" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" fill="${C.navy}" letter-spacing="5">1 YEAR</text>${g}<g transform="translate(0,${f(92+Math.sin(T*3)*2)})"><path d="M0 -34 C14 -10 20 -2 20 8 a20 20 0 0 1 -40 0 C-20 -2 -14 -10 0 -34Z" fill="${C.blue}" ${st(C.navy,4)}/></g></g>`};

/* ---------- person standing in the rain (arms up), optional umbrella / coat ---------- */
P.e107_inrain=(o,T)=>{let d='';for(let i=0;i<16;i++){const x=-92+((i*37)%184),y=((T*210+i*53)%190)-100;d+=`<line x1="${x}" y1="${f(y)}" x2="${x-7}" y2="${f(y+20)}" ${st(C.blue,4.5)} opacity="${f(clamp(1-(y+100)/230))}"/>`}
  const up=Math.sin(T*4)*6,c=o.coat?'#8E3532':'#4DA3D8';
  const arms=o.umb?'':`<path d="M-54 40 L-92 ${f(-8+up)}" ${st(C.navy,17)}/><path d="M-54 40 L-92 ${f(-8+up)}" ${st(c,11)}/><circle cx="-94" cy="${f(-12+up)}" r="11" fill="#E3AE82" ${st(C.navy,4)}/><path d="M54 40 L92 ${f(-8-up)}" ${st(C.navy,17)}/><path d="M54 40 L92 ${f(-8-up)}" ${st(c,11)}/><circle cx="94" cy="${f(-12-up)}" r="11" fill="#E3AE82" ${st(C.navy,4)}/>`;
  const umb=o.umb?`<g transform="translate(0,-22) scale(.8)">${P.e4_umbrella({},T)}</g>`:'';
  return `<g>${o.umb?umb:`<g transform="translate(0,-86) scale(.74)">${cloudShape('#C9D5DC')}</g>`}${d}<g transform="translate(0,34) scale(.82)">${arms}${P.person({c,hair:'short',hc:'#222'},T)}${o.coat?`<path d="M-62 108 L-62 36 Q-62 -4 0 -4 Q62 -4 62 36 L62 108Z" fill="none"/><rect x="-44" y="-8" width="88" height="20" rx="10" fill="#C0504D" ${st()}/>`:''}</g></g>`};

/* ---------- cousin behind a window, a small figure outside in the rain ---------- */
P.e107_windowview=(o,T)=>{let d='';for(let i=0;i<22;i++){const x=-130+((i*47)%260),y=((T*200+i*61)%260)-110;d+=`<line x1="${x}" y1="${f(y)}" x2="${x-6}" y2="${f(y+18)}" ${st(C.blue,3.5)} opacity=".8"/>`}
  const j=Math.abs(Math.sin(T*4))*5;
  return _e107pan('e107_cwv',`<rect x="-140" y="-110" width="280" height="240" fill="#B4C4CD"/><rect x="-140" y="-110" width="280" height="150" fill="#E9D8B6"/><rect x="-140" y="-86" width="280" height="6" fill="#D6C29B" opacity=".6"/><rect x="-62" y="-92" width="124" height="112" fill="#FFE7B0" ${st(C.navy,6)}/><g clip-path="url(#e107_cwv2)">${_e107p(0,-10,.5,{c:'#6A8FA8',hair:'short',hc:'#BDC3C7'},T)}</g><clipPath id="e107_cwv2"><rect x="-58" y="-88" width="116" height="104"/></clipPath><line x1="0" y1="-92" x2="0" y2="20" ${st(C.navy,4)}/><rect x="-74" y="20" width="148" height="12" rx="4" fill="${C.cream}" ${st()}/><path d="M-62 -92 Q-40 -50 -62 20Z" fill="${C.red}" opacity=".85" ${st(C.navy,3)}/><path d="M62 -92 Q40 -50 62 20Z" fill="${C.red}" opacity=".85" ${st(C.navy,3)}/><rect x="-140" y="40" width="280" height="100" fill="#8FA3AE"/><ellipse cx="-70" cy="84" rx="50" ry="8" fill="#7FB0C9"/><ellipse cx="80" cy="70" rx="34" ry="6" fill="#7FB0C9"/>${d}<g transform="translate(88,${f(70-j)})"><path d="M-14 28 L-26 -4 M14 28 L26 -4" ${st(C.navy,5)}/>${_e107p(0,-2,.3,{c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g>`)};

/* ---------- wet things: shoes, clothes, bag ---------- */
const _e107drip=(x,y,T,n)=>{let s='';for(let i=0;i<(n||3);i++){const ph=(T*.9+i/(n||3))%1;s+=`<path d="M${f(x+i*18-18)} ${f(y+ph*44)} q-5 8 0 12 q5 -4 0 -12" fill="${C.blue}" ${st(C.navy,1.5)} opacity="${f(1-ph)}"/>`}return s};
const _e107tee=(c)=>`<path d="M-30 -62 Q0 -44 30 -62 L72 -40 L56 -4 L38 -14 L38 66 L-38 66 L-38 -14 L-56 -4 L-72 -40Z" fill="${c}" ${st()}/><path d="M-30 -62 Q0 -44 30 -62" fill="none" ${st(C.navy,5)}/><path d="M-26 -50 Q0 -36 26 -50" fill="none" stroke="#fff" stroke-width="4" opacity=".4"/>`;
P.e107_tshirt=(o,T)=>`<g transform="scale(1.7)">${_e107tee(o.c||C.white)}</g>`;
P.e107_wet=(o,T)=>{const it=o.item||'all';const shoe=`<g transform="scale(.62)">${P.shoe({one:1,c:'#5B7DA8'},T)}</g>${_e107drip(0,18,T)}`,cl=`<g transform="scale(.72)">${_e107tee('#7A9CC0')}</g><g opacity=".5">${[[-14,-6],[10,12],[-8,28]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="7" fill="${C.blue}"/>`).join('')}</g>${_e107drip(0,36,T)}`,bag=`<g transform="scale(.58)">${P.bag({c:'#3F6E9C'},T)}</g>${_e107drip(0,40,T)}`;
  if(it==='shoes')return `<g transform="scale(1.7)">${shoe}</g>`;if(it==='clothes')return `<g transform="scale(1.7)">${cl}</g>`;if(it==='bag')return `<g transform="scale(1.7)">${bag}</g>`;
  return `<g><g transform="translate(-86,0)">${shoe}</g><g transform="translate(0,-4)">${cl}</g><g transform="translate(88,0)">${bag}</g></g>`};

/* ---------- mud on a shoe ---------- */
P.e107_mudshoe=(o,T)=>`<g><g transform="scale(1.1)">${P.shoe({one:1,c:'#5B7DA8'},T)}</g>${[[-60,24,16],[-20,36,12],[26,38,18],[70,30,11],[-86,10,10],[4,12,9],[50,10,8]].map(([x,y,r],i)=>`<ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r*.7}" fill="#6F4A2E" ${st('#4A3220',3)}/>`).join('')}${_e107drip(20,50,T,2).replace(/fill="[^"]+"/g,'fill="#6F4A2E"')}</g>`;

/* ---------- lake between green hills (o.sun: bright sun and a mirror-like lake) ---------- */
P.e107_lake=(o,T,k)=>{const sun=o.sun;let sh='';for(let i=0;i<5;i++)sh+=`<path d="M${-96+i*38} ${52+(i%2)*14} h${22+(i%3)*8}" stroke="#fff" stroke-width="3.5" stroke-linecap="round" opacity="${f(.4+.35*Math.sin(T*2.4+i))}"/>`;
  return _e107pan('e107_clk',`<rect x="-140" y="-110" width="280" height="240" fill="${sun?'#A7DCF2':'#BAC8D0'}"/>${sun?_e107sun(70,-64,32,T,0):`<g transform="translate(-40,-78) scale(.8)">${cloudShape('#DCE5EA')}</g><g transform="translate(70,-86) scale(.6)">${cloudShape('#DCE5EA')}</g>`}${_e107hill(-6,10,40,.5,'#7FAF8A')}<rect x="-140" y="22" width="280" height="110" fill="${sun?'#6FC1E6':'#7FA9C2'}"/><path d="M-136 22 H136" ${st(C.navy,4)} fill="none"/><clipPath id="e107_clk2"><rect x="-140" y="24" width="280" height="110"/></clipPath><g clip-path="url(#e107_clk2)"><g opacity=".35" transform="translate(0,44) scale(1,-.8)">${_e107hill(-12,10,40,.5,sun?'#4A8F6A':'#5B7C6E','none',0)}</g></g>${sh}${sun?`<circle cx="70" cy="62" r="14" fill="#fff" opacity="${f(.5+.2*Math.sin(T*3))}"/>`:''}<path d="M-136 20 Q-110 -4 -80 20 Q-60 36 -30 22 L-136 22Z" fill="#6FAE6A" ${st(C.navy,4)}/><path d="M136 22 Q110 -10 78 14 Q60 30 40 22Z" fill="#6FAE6A" ${st(C.navy,4)}/><g transform="translate(-92,20) scale(.34)"><rect x="-70" y="-16" width="140" height="88" fill="#F4E5C2" ${st(C.navy,8)}/><polygon points="-86,-14 0,-80 86,-14" fill="${C.red}" ${st(C.navy,8)}/><rect x="-14" y="22" width="28" height="50" fill="${C.brown}" ${st(C.navy,6)}/></g>${_e107tree(104,34,.28)}`)};

/* ---------- a green valley between two big hills with a river ---------- */
P.e107_valley=(o,T)=>{let gr='';for(let i=0;i<24;i++){const x=-120+_e107rnd(i,31)*240,y=30+_e107rnd(i,32)*72;gr+=`<path d="M${f(x-4)} ${f(y)} l-2 -9 l5 4 l1 -8 l3 8 l4 -5 l-2 10Z" fill="#4F8F57"/>`}
  const w=Math.sin(T*2)*3;
  return _e107pan('e107_cvl',`<rect x="-140" y="-110" width="280" height="240" fill="#AEDCEE"/>${[[-70,-76,.6,0],[60,-86,.5,2]].map(([x,y,s,p])=>`<g transform="translate(${f(x+Math.sin(T*.5+p)*6)},${y}) scale(${s})">${cloudShape()}</g>`).join('')}<path d="M-140 -10 Q-96 -66 -40 -30 Q-12 -6 -6 40 L-140 130Z" fill="#7FB87A" ${st(C.navy,4.5)}/><path d="M140 -20 Q96 -70 46 -30 Q16 -6 8 40 L140 130Z" fill="#6FAE6A" ${st(C.navy,4.5)}/><path d="M-6 40 Q-2 20 0 12 Q2 20 8 40 L60 130 L-60 130Z" fill="#8DBF7E" ${st(C.navy,0)}/><path d="M-4 38 Q8 62 -14 82 Q-40 104 -26 130 L40 130 Q30 104 36 84 Q44 60 8 38Z" fill="#5BB9E0" ${st(C.navy,4)}/><path d="M-6 86 q10 -8 20 -2 M2 108 q10 -8 20 0" fill="none" stroke="#fff" stroke-width="3" opacity=".7" transform="translate(${f(w)},0)"/>${gr}${_e107tree(-96,36,.4)}${_e107tree(-70,50,.32,'#4F8F57')}${_e107tree(100,40,.42,'#4F8F57')}${_e107tree(78,58,.3)}`)};

/* ---------- sheep and cows on a green hill ---------- */
P.e107_herd=(o,T)=>{let gr='';for(let i=0;i<20;i++){const x=-120+_e107rnd(i,41)*240,y=-4+_e107rnd(i,42)*100;gr+=`<path d="M${f(x-4)} ${f(y)} l-2 -9 l5 4 l1 -8 l3 8 l4 -5 l-2 10Z" fill="#4F8F57"/>`}
  const bob=Math.sin(T*2)*1.5;
  return _e107pan('e107_chd',`<rect x="-140" y="-110" width="280" height="240" fill="#B4C4CD"/><g transform="translate(-30,-72) scale(.8)">${cloudShape('#DCE5EA')}</g><g transform="translate(86,-84) scale(.55)">${cloudShape('#DCE5EA')}</g>${_e107hill(-6,12,42,1,'#8DBF7E')}${_e107hill(30,10,38,3,'#6FAE6A')}${gr}<g transform="translate(-84,34) scale(.36)">${P.e25_sheep({},T)}</g><g transform="translate(-26,${f(70+bob)}) scale(.38)">${P.e25_sheep({},T)}</g><g transform="translate(76,56) scale(-.4,.4)">${P.e5_cow({},T)}</g>`)};

/* ---------- a path up the hill, two walkers (seen from behind) ---------- */
P.e107_hillwalk=(o,T)=>{const pt=u=>[-56+u*92+Math.sin(u*7)*20,98-u*142];let d='';for(let i=0;i<=24;i++){const [x,y]=pt(i/24);d+=(i?'L':'M')+f(x)+' '+f(y)+' '}
  let w='';[['#4DA3D8',0],['#E2B653',.2]].forEach(([c,off],i)=>{const u=.12+((T*.05+off)%.7),[x,y]=pt(u);w+=_e107back(x,y-4,.22-u*.08,c,'#2A1D18')});
  return _e107pan('e107_chw',`<rect x="-140" y="-110" width="280" height="240" fill="#B4C4CD"/><g transform="translate(-60,-70) scale(.7)">${cloudShape('#DCE5EA')}</g><path d="M-140 120 L-140 -4 Q-60 -52 20 -52 Q90 -52 140 20 L140 130Z" fill="#7FB87A" ${st(C.navy,4.5)}/><path d="M-140 100 Q-100 60 -40 70 Q10 78 40 40 L140 60 V130 H-140Z" fill="#6FAE6A"/><path d="${d}" fill="none" stroke="#D9C79A" stroke-width="14" stroke-linecap="round"/><path d="${d}" fill="none" stroke="#B89A5E" stroke-width="2" stroke-dasharray="3 9" stroke-linecap="round"/>${w}${_e107tree(-96,84,.42,'#4F8F57')}${_e107tree(104,96,.4)}`)};

/* ---------- standing on top: valley, lake and clouds below/around ---------- */
P.e107_viewtop=(o,T)=>{
  return _e107pan('e107_cvt',`<rect x="-140" y="-110" width="280" height="240" fill="#AEC4D0"/>${[[-90,-80,.9,0],[10,-90,1.1,2],[100,-70,.8,4]].map(([x,y,s,p])=>`<g transform="translate(${f(x+Math.sin(T*.5+p)*7)},${y}) scale(${s})">${cloudShape('#E8EEF1')}</g>`).join('')}${_e107hill(-24,10,38,.7,'#8AB59A')}<rect x="-140" y="-2" width="280" height="50" fill="#7FB0C9"/><path d="M-136 -2 H136" ${st(C.navy,3.5)} fill="none"/><path d="M-90 20 h50 M10 30 h60 M-40 38 h34" stroke="#fff" stroke-width="3" opacity=".7" stroke-linecap="round"/>${_e107hill(40,8,44,2,'#7FB87A')}<path d="M-140 130 L-140 84 Q-60 56 0 70 Q80 54 140 86 L140 130Z" fill="#4F8F57" ${st(C.navy,5)}/>${_e107back(-26,92,.3,'#4DA3D8','#222')}${_e107back(14,96,.28,'#E2B653','#2A1D18')}`)};

/* ---------- very low clouds touching the hills ---------- */
P.e107_lowclouds=(o,T)=>{const dr=Math.sin(T*.7)*10;
  return _e107pan('e107_clc',`<rect x="-140" y="-110" width="280" height="240" fill="#B4C4CD"/><path d="M-140 80 L-140 22 Q-96 -26 -50 22 Q-30 40 -10 18 Q30 -34 80 18 Q110 40 140 14 V130 H-140Z" fill="#6FAE6A" ${st(C.navy,4.5)}/><rect x="-140" y="74" width="280" height="60" fill="#7FA9C2"/><path d="M-140 74 H140" ${st(C.navy,4)} fill="none"/><g transform="translate(${f(dr)},0)">${[[-110,-70],[-50,-62],[10,-70],[70,-60],[130,-70]].map(([x,y])=>`<g transform="translate(${x},${y}) scale(.95,.7)">${cloudShape('#EEF2F4')}</g>`).join('')}</g><g transform="translate(${f(-dr*.6)},0)">${[[-76,34],[-4,28],[56,36]].map(([x,y])=>`<g transform="translate(${x},${y}) scale(.6,.4)">${cloudShape('#E1E8EC')}</g>`).join('')}</g>`)};

/* ---------- helpers: colour mix, car, waves ---------- */
const _e107mix=(a,b,p)=>{const h=s=>[1,3,5].map(i=>parseInt(s.slice(i,i+2),16)),A=h(a),B=h(b);return '#'+A.map((v,i)=>Math.round(v+(B[i]-v)*p).toString(16).padStart(2,'0')).join('')};
const _e107car=(col,o={})=>`<g><path d="M-124 40 V0 Q-124 -12 -108 -16 L-70 -22 L-42 -62 Q-38 -68 -30 -68 H46 Q54 -68 58 -62 L84 -22 L112 -14 Q124 -10 124 4 V40 Z" fill="${col}" ${st()}/><path d="M-34 -58 H42 L64 -24 H-56 Z" fill="${o.win||C.sky}" ${st(C.navy,3)}/><line x1="4" y1="-58" x2="4" y2="-24" ${st(C.navy,3)}/><path d="M-100 6 H-60 M60 6 H100" stroke="#fff" stroke-width="4" opacity=".35" stroke-linecap="round"/><circle cx="-70" cy="44" r="24" fill="${C.navy}"/><circle cx="-70" cy="44" r="10" fill="${C.grey}"/><circle cx="72" cy="44" r="24" fill="${C.navy}"/><circle cx="72" cy="44" r="10" fill="${C.grey}"/></g>`;
const _e107wave=(base,A,L,ph,fill,foam)=>{let e='';for(let x=-136;x<=136;x+=6){const s=Math.sin(x/L+ph),y=base-A*Math.pow(Math.abs(s),.75)*(s<0?.55:1);e+=(x===-136?'M':'L')+x+' '+f(y)+' '}return `<path d="${e}L136 130 L-136 130Z" fill="${fill}"/><path d="${e}" fill="none" stroke="${foam?'#fff':C.navy}" stroke-width="${foam?5:3.5}" stroke-linejoin="round" opacity="${foam?.9:1}"/>`};
const _e107dust=(T,lv,n)=>{let s='';for(let i=0;i<(n||16);i++){const y=-110+_e107rnd(i,51)*230,len=40+_e107rnd(i,52)*80,x=((T*(120+_e107rnd(i,53)*140)+_e107rnd(i,54)*400)%420)-150;s+=`<line x1="${f(x)}" y1="${f(y)}" x2="${f(x+len)}" y2="${f(y-len*.12)}" stroke="${i%3?'#F2CC7A':'#8A5A1E'}" stroke-width="${3+_e107rnd(i,55)*5}" stroke-linecap="round" opacity="${f(.25+lv*.4)}"/>`}return s};

/* ---------- sand storm (lv 0..1) ---------- */
P.e107_sandstorm=(o,T,k)=>{const lv=o.lv==null?1:o.lv;
  return _e107pan('e107_css',`<rect x="-140" y="-110" width="280" height="240" fill="${_e107mix('#E8B960','#B8742A',lv)}"/><circle cx="50" cy="-50" r="30" fill="#F6E3A8" opacity="${f(.5-.3*lv)}"/>${_e107hill(50,10,44,.7,_e107mix('#D9AE62','#8A5A1E',lv))}${_e107hill(86,8,36,2,_e107mix('#C99A4E','#6B4318',lv))}${_e107dust(T,lv,22)}<rect x="-140" y="-110" width="280" height="240" fill="#C98A2E" opacity="${f(.12+.28*lv)}"/>`)};

/* ---------- the sky turns from blue to yellow and dark within minutes ---------- */
P.e107_skyturn=(o,T,k)=>{const p=ease((k-.3)/2.6);
  return _e107pan('e107_cst2',`<rect x="-140" y="-110" width="280" height="240" fill="${_e107mix('#A7DCF2','#B8742A',p)}"/>${p<.7?_e107sun(60,-60,24,T,0).replace(/<(line|circle)/g,'<$1 opacity="'+f(1-p*1.4)+'"'):''}${_e107hill(46,10,44,.7,_e107mix('#EBC98A','#8A5A1E',p))}<polygon points="-4,52 4,52 70,130 -70,130" fill="${_e107mix('#5B6770','#3B3A38',p)}" ${st(C.navy,3)}/><g opacity="${f(p)}">${_e107dust(T,p,14)}</g>`)};

/* ---------- car crawling through a sand storm, lights on ---------- */
P.e107_stormcar=(o,T)=>{const b=Math.sin(T*6)*1.2;
  return _e107pan('e107_csc',`<rect x="-140" y="-110" width="280" height="240" fill="#C0802F"/><polygon points="-6,-10 6,-10 120,130 -120,130" fill="#4A3A2A" ${st(C.navy,3)}/>${[0,1,2].map(i=>{const ph=(i*.33+T*.4)%1;return `<rect x="-3" y="${f(-6+ph*100)}" width="6" height="${f(6+ph*14)}" fill="#E8D7B0" opacity="${f(.6)}"/>`}).join('')}<g transform="translate(0,${f(20+b)}) scale(.52)">${_e107car('#C0504D')}<polygon points="112,-4 250,-44 250,40" fill="#FFF3B0" opacity="${f(.28+.06*Math.sin(T*3))}"/><circle cx="116" cy="-4" r="9" fill="#FFF3B0" ${st(C.navy,3)}/></g>${_e107dust(T,1,24)}<rect x="-140" y="-110" width="280" height="240" fill="#C98A2E" opacity=".3"/>`)};

/* ---------- petrol station ---------- */
P.e107_petrol=(o,T)=>{const dust=o.dust;
  return `<g><rect x="-128" y="-100" width="256" height="52" rx="10" fill="${C.red}" ${st()}/><rect x="-128" y="-60" width="256" height="12" fill="${C.cream}" ${st(C.navy,3)}/><text x="0" y="-68" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" fill="${C.cream}" letter-spacing="5">PETROL</text><rect x="-100" y="-48" width="14" height="136" fill="#CBD6DC" ${st(C.navy,4)}/><rect x="86" y="-48" width="14" height="136" fill="#CBD6DC" ${st(C.navy,4)}/><rect x="-72" y="2" width="70" height="86" rx="10" fill="${C.cream}" ${st()}/><rect x="-60" y="14" width="46" height="26" rx="5" fill="${C.navy2}"/><text x="-37" y="34" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="19" fill="#7DE08F">0.00</text><rect x="-60" y="50" width="46" height="10" rx="4" fill="${C.red}" ${st(C.navy,2.5)}/><path d="M-2 30 Q26 20 24 52 Q22 70 12 80" fill="none" ${st(C.navy,6)}/><rect x="6" y="76" width="22" height="12" rx="3" fill="${C.navy2}"/><rect x="40" y="14" width="40" height="74" rx="4" fill="#F4E5C2" ${st()}/><rect x="46" y="22" width="28" height="22" fill="${C.sky}" ${st(C.navy,3)}/><rect x="-124" y="88" width="248" height="14" rx="4" fill="#9FB0BA" ${st()}/></g>`};

/* ---------- car covered in yellow dust (o.wash: clean again, soapy) ---------- */
P.e107_yellowcar=(o,T)=>{if(o.wash){let b='';for(let i=0;i<9;i++){const ph=(T*.7+i/9)%1,x=-90+_e107rnd(i,61)*180,y=-60+_e107rnd(i,62)*100-ph*20;b+=`<circle cx="${f(x)}" cy="${f(y)}" r="${f(6+_e107rnd(i,63)*8)}" fill="#fff" ${st('#7FB6D6',2.5)} opacity="${f(.9-ph*.5)}"/>`}
    return `<g><g transform="scale(.95)">${_e107car('#C0504D')}</g>${b}${_e107star(-60,-70,1.3,'#fff')}${_e107star(70,-50,1,C.gold)}</g>`}
  let sp='';for(let i=0;i<26;i++)sp+=`<circle cx="${f(-110+_e107rnd(i,64)*220)}" cy="${f(-50+_e107rnd(i,65)*86)}" r="${f(2+_e107rnd(i,66)*3)}" fill="#B8903C" opacity=".7"/>`;
  let dst='';for(let i=0;i<3;i++){const ph=(T*.6+i/3)%1;dst+=`<circle cx="${f(-120+ph*60)}" cy="${f(-20+i*24)}" r="${f(8+ph*8)}" fill="#E0B04A" opacity="${f(.6-ph*.6)}"/>`}
  return `<g><g transform="scale(.95)">${_e107car('#E0B04A',{win:'#D9C48A'})}</g>${sp}<path d="M-96 -18 q40 -10 80 0" stroke="#F6DC95" stroke-width="6" fill="none" stroke-linecap="round" opacity=".8" transform="scale(.95)"/>${dst}</g>`};

/* ---------- street flooded after heavy rain (o.car: car in water up to the doors) ---------- */
P.e107_floodstreet=(o,T)=>{let d='';for(let i=0;i<16;i++){const x=-130+i*17,y=((T*220+i*57)%150)-100;d+=`<line x1="${x}" y1="${f(y)}" x2="${x-6}" y2="${f(y+16)}" ${st(C.blue,3.5)} opacity=".85"/>`}
  const w=(r)=>`<path d="M-136 ${52+r*22} q17 -9 34 0 t34 0 t34 0 t34 0 t34 0 t34 0 t34 0 t34 0 t34 0" fill="none" stroke="#fff" stroke-width="3.5" opacity="${.7-r*.2}" transform="translate(${f(Math.sin(T*1.8+r)*10)},0)"/>`;
  const hs=(x,c)=>`<rect x="${x}" y="-18" width="64" height="72" fill="${c}" ${st(C.navy,4)}/><polygon points="${x-6},-18 ${x+32},-52 ${x+70},-18" fill="${C.red}" ${st(C.navy,4)}/><rect x="${x+8}" y="-4" width="18" height="20" fill="#FFE08A" ${st(C.navy,3)}/><rect x="${x+38}" y="14" width="18" height="40" fill="${C.brown}" ${st(C.navy,3)}/>`;
  return _e107pan('e107_cfl',`<rect x="-140" y="-110" width="280" height="240" fill="#8FA3AE"/><g transform="translate(-30,-82) scale(1.1,.8)">${cloudShape('#6F8390')}</g><g transform="translate(70,-90) scale(.8,.6)">${cloudShape('#6F8390')}</g>${hs(-134,'#F4E5C2')}${hs(-60,'#E7D3A6')}${hs(76,'#F4E5C2')}<rect x="-140" y="54" width="280" height="80" fill="#6B7780"/>${o.car?`<g transform="translate(14,34) scale(.5)">${_e107car('#D9534F')}</g>`:''}<rect x="-140" y="${o.car?44:50}" width="280" height="90" fill="#6FB1D6" opacity=".82"/>${w(0)}${w(1)}${w(2)}${d}`)};

/* ---------- very hard ground: the rain stays on top ---------- */
P.e107_hardground=(o,T)=>{let d='';for(let i=0;i<9;i++){const ph=(T*1.1+i/9)%1,x=-112+i*28;d+=`<path d="M${x} ${f(-96+ph*92)} q-4 7 0 11 q4 -4 0 -11" fill="${C.blue}" ${st(C.navy,1.5)}/>`;if(ph>.85)d+=`<path d="M${x-8} -4 q8 -12 16 0" fill="none" ${st(C.blue,3)} opacity="${f((ph-.85)*6)}"/>`}
  return _e107pan('e107_chg2',`<rect x="-140" y="-110" width="280" height="240" fill="#B4C4CD"/><g transform="translate(0,-82) scale(1.7,.9)">${cloudShape('#9FB0BA')}</g><rect x="-140" y="0" width="280" height="130" fill="#B98A5A"/><rect x="-140" y="0" width="280" height="22" fill="#7A828A" ${st(C.navy,3)}/><path d="M-100 40 l22 14 l-8 24 M20 56 l26 -12 l14 22 M80 30 l-10 22 M-30 88 l24 -10 l10 24" fill="none" stroke="#7A5230" stroke-width="3.5" stroke-linecap="round"/><path d="M-140 -6 q17 -8 34 0 t34 0 t34 0 t34 0 t34 0 t34 0 t34 0 t34 0 t34 0" fill="#6FB1D6" stroke="${C.navy}" stroke-width="3.5" transform="translate(${f(Math.sin(T*2)*8)},0)"/><rect x="-140" y="-4" width="280" height="8" fill="#6FB1D6" opacity=".0"/>${d}`)};

/* ---------- school / office shut ---------- */
P.e107_closed=(o,T)=>{const sc=o.k!=='office';const sw=Math.sin(T*2)*2.5;
  const bld=sc?`<rect x="-110" y="-46" width="220" height="132" fill="#E7C98A" ${st()}/><polygon points="-122,-46 0,-104 122,-46" fill="${C.red}" ${st()}/><rect x="-60" y="-56" width="120" height="30" rx="6" fill="${C.cream}" ${st(C.navy,4)}/><text x="0" y="-33" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="22" fill="${C.navy}" letter-spacing="3">SCHOOL</text>${[-86,-50,50,86].map(x=>`<rect x="${x-14}" y="-8" width="28" height="32" fill="${C.sky}" ${st(C.navy,3)}/>`).join('')}<rect x="-24" y="22" width="48" height="64" fill="${C.brown}" ${st()}/>`:`<rect x="-80" y="-104" width="160" height="190" fill="#9FB6C4" ${st()}/><rect x="-92" y="-116" width="184" height="16" fill="${C.navy2}" ${st()}/>${[0,1,2,3].map(r=>[0,1,2].map(c=>`<rect x="${-62+c*44}" y="${-84+r*36}" width="28" height="24" fill="#D6EAF4" ${st(C.navy,3)}/>`).join('')).join('')}<rect x="-26" y="30" width="52" height="56" fill="${C.navy2}" ${st()}/><rect x="-60" y="10" width="120" height="16" rx="4" fill="${C.cream}" ${st(C.navy,3)}/><text x="0" y="23" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="13" fill="${C.navy}" letter-spacing="3">OFFICE</text>`;
  return `<g>${bld}<g transform="translate(${sc?0:0},${sc?44:52}) rotate(${f(sw)})"><rect x="-58" y="-16" width="116" height="34" rx="8" fill="${C.red}" ${st()}/><text x="0" y="9" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="${C.cream}" letter-spacing="3">CLOSED</text></g><rect x="-124" y="86" width="248" height="12" rx="4" fill="#DCD2B8" ${st()}/></g>`};

/* ---------- watching the rain from the window (people seen from behind) ---------- */
P.e107_watchwin=(o,T)=>{let d='';for(let i=0;i<14;i++){const x=-70+((i*37)%140),y=((T*190+i*61)%200)-110;d+=`<line x1="${x}" y1="${f(y)}" x2="${x-6}" y2="${f(y+18)}" ${st(C.blue,4)} opacity=".85"/>`}
  return _e107pan('e107_cww',`<rect x="-140" y="-110" width="280" height="240" fill="#E9D8B6"/><rect x="-82" y="-96" width="164" height="128" fill="#8FA3AE"/><g transform="translate(-10,-62) scale(1.3,.9)">${cloudShape('#5F7380')}</g><g transform="translate(56,-72) scale(.8,.6)">${cloudShape('#6F8390')}</g><clipPath id="e107_cww2"><rect x="-82" y="-96" width="164" height="128"/></clipPath><g clip-path="url(#e107_cww2)">${d}</g><rect x="-82" y="-96" width="164" height="128" fill="none" ${st(C.navy,6)}/><line x1="0" y1="-96" x2="0" y2="32" ${st(C.navy,5)}/><line x1="-82" y1="-34" x2="82" y2="-34" ${st(C.navy,5)}/><path d="M-82 -104 Q-54 -34 -82 40Z" fill="#E88CA2" ${st(C.navy,3.5)}/><path d="M82 -104 Q54 -34 82 40Z" fill="#E88CA2" ${st(C.navy,3.5)}/><rect x="-98" y="30" width="196" height="14" rx="6" fill="${C.cream}" ${st()}/>${_e107back(-30,52,.5,'#D96C8B','#2A1D18')}${_e107back(32,56,.46,'#4DA3D8','#222')}`)};

/* ---------- cosy house in the rain: warm light inside, steam from the chimney ---------- */
P.e107_cozy=(o,T)=>{let d='';for(let i=0;i<18;i++){const x=-132+i*15,y=((T*210+i*59)%190)-100;d+=`<line x1="${x}" y1="${f(y)}" x2="${x-7}" y2="${f(y+18)}" ${st('#9FD0EA',3.5)} opacity=".8"/>`}
  let sm='';for(let i=0;i<3;i++){const ph=(T*.5+i/3)%1;sm+=`<circle cx="${f(52+ph*10)}" cy="${f(-62-ph*40)}" r="${f(7+ph*9)}" fill="#C9D5DC" opacity="${f(.85-ph)}"/>`}
  return _e107pan('e107_ccz',`<rect x="-140" y="-110" width="280" height="240" fill="#4C5F70"/><g transform="translate(-20,-86) scale(1.4,.9)">${cloudShape('#34444F')}</g><g transform="translate(86,-92) scale(.9,.7)">${cloudShape('#3E4F5B')}</g><rect x="-140" y="68" width="280" height="64" fill="#3C5A52"/>${sm}<rect x="40" y="-52" width="22" height="40" fill="${C.brown}" ${st()}/><rect x="-82" y="-8" width="164" height="82" fill="#E7C98A" ${st()}/><polygon points="-98,-6 0,-70 98,-6" fill="#A8433F" ${st()}/><rect x="-62" y="12" width="46" height="40" fill="#FFD36B" ${st(C.navy,4)}/><line x1="-39" y1="12" x2="-39" y2="52" ${st(C.navy,3)}/><rect x="14" y="12" width="46" height="40" fill="#FFD36B" ${st(C.navy,4)}/><line x1="37" y1="12" x2="37" y2="52" ${st(C.navy,3)}/><rect x="-16" y="30" width="30" height="44" fill="${C.brown}" ${st()}/><circle cx="-39" cy="32" r="30" fill="#FFD36B" opacity="${f(.2+.08*Math.sin(T*3))}"/>${d}`)};

/* ---------- the coast: sea, beach, small house, palm tree ---------- */
const _e107palm=(x,y,s,T)=>{const sw=Math.sin(T*1.6)*3;let fr='';[[-70,-18],[-48,-44],[0,-56],[48,-44],[70,-18]].forEach(([a,b],i)=>fr+=`<path d="M0 0 Q${a*.5} ${b-22} ${a+(a>0?1:-1)*0} ${b+30}" fill="none" ${st(C.navy,9)}/><path d="M0 0 Q${a*.5} ${b-22} ${a} ${b+30}" fill="none" ${st('#5E9B63',5)}/>`);return `<g transform="translate(${x},${y}) scale(${s})"><path d="M0 100 Q16 40 0 -10" fill="none" ${st(C.navy,16)}/><path d="M0 100 Q16 40 0 -10" fill="none" ${st('#A9743F',9)}/><g transform="translate(0,-12) rotate(${f(sw)})">${fr}</g></g>`};
P.e107_coast=(o,T)=>{let w='';for(let i=0;i<4;i++)w+=`<path d="M-130 ${-8+i*9} q10 -6 20 0 t20 0 t20 0 t20 0 t20 0 t20 0 t20 0 t20 0 t20 0 t20 0 t20 0 t20 0 t20 0" fill="none" stroke="#fff" stroke-width="2.5" opacity="${.7-i*.12}" transform="translate(${f(Math.sin(T*1.5+i)*8)},0)"/>`;
  return _e107pan('e107_cco',`<rect x="-140" y="-110" width="280" height="240" fill="#A7DCF2"/>${_e107sun(76,-70,24,T,0)}<rect x="-140" y="-22" width="280" height="50" fill="#4DA3D8"/><path d="M-140 -22 H140" ${st(C.navy,4)} fill="none"/>${w}<path d="M-140 28 Q-40 14 140 34 V130 H-140Z" fill="#F0D9A0" ${st(C.navy,4)}/><g transform="translate(-46,32) scale(.5)"><rect x="-70" y="-30" width="140" height="92" fill="${C.white}" ${st(C.navy,8)}/><polygon points="-86,-28 0,-90 86,-28" fill="${C.red}" ${st(C.navy,8)}/><rect x="-16" y="8" width="32" height="54" fill="${C.brown}" ${st(C.navy,6)}/><rect x="30" y="-12" width="30" height="28" fill="${C.sky}" ${st(C.navy,5)}/><rect x="-60" y="-12" width="30" height="28" fill="${C.sky}" ${st(C.navy,5)}/></g>${_e107palm(60,28,.5,T)}<path d="M-20 130 Q0 80 -10 50" fill="none" stroke="#D6B878" stroke-width="12" stroke-linecap="round" opacity=".7"/>`)};

/* ---------- hot AND wet air on the coast ---------- */
P.e107_humid=(o,T)=>{let dr='';for(let i=0;i<14;i++){const ph=(T*.4+_e107rnd(i,71))%1,x=-112+_e107rnd(i,72)*224,y=-60+_e107rnd(i,73)*150-ph*14;dr+=`<path d="M${f(x)} ${f(y)} q-4 7 0 11 q4 -4 0 -11" fill="${C.blue}" opacity="${f(.35+.45*Math.sin(ph*Math.PI))}"/>`}
  let sw='';for(let i=0;i<3;i++){const ph=(T*.8+i/3)%1;sw+=`<path d="M${f(-62)} ${f(-76+ph*40)} q-4 8 0 12 q4 -4 0 -12" fill="${C.blue}" ${st(C.navy,2)} opacity="${f(1-ph)}" transform="translate(${i*0},${i*0})"/><path d="M${f(62)} ${f(-76+ph*40)} q-4 8 0 12 q4 -4 0 -12" fill="${C.blue}" ${st(C.navy,2)} opacity="${f(1-ph)}"/>`}
  return `<g>${_e107sun(-82,-76,34,T,1)}<g transform="translate(30,26) scale(.82)">${P.person({c:'#6FB1D6',hair:'short',hc:'#222'},T)}<ellipse cx="-24" cy="52" rx="20" ry="26" fill="#3F7FA8" opacity=".55"/><ellipse cx="26" cy="40" rx="16" ry="20" fill="#3F7FA8" opacity=".55"/><ellipse cx="0" cy="84" rx="30" ry="14" fill="#3F7FA8" opacity=".5"/>${sw}</g>${dr}</g>`};

/* ---------- glasses that fog up (watch k) ---------- */
P.e107_glasses=(o,T,k)=>{const p=ease((k-.4)/1.6);const lens=(x)=>`<circle cx="${x}" cy="0" r="40" fill="${_e107mix('#D6EAF4','#FFFFFF',p)}" opacity=".95"/><circle cx="${x}" cy="0" r="40" fill="#fff" opacity="${f(p*.8)}"/><path d="M${x-26} -14 q10 -12 24 -10" fill="none" stroke="#fff" stroke-width="6" stroke-linecap="round" opacity="${f(.9-p*.6)}"/>`;let m='';for(let i=0;i<4;i++){const ph=(T*.6+i/4)%1;m+=`<circle cx="${f(-60+i*40+Math.sin(T*2+i)*6)}" cy="${f(-52-ph*34)}" r="${f(8+ph*10)}" fill="#fff" ${st('#B9C6CE',2.5)} opacity="${f(p*(1-ph)*.9)}"/>`}
  return `<g><g transform="translate(0,16)"><circle cx="-52" cy="0" r="40" fill="none" ${st(C.navy,15)}/><circle cx="52" cy="0" r="40" fill="none" ${st(C.navy,15)}/>${lens(-52)}${lens(52)}<circle cx="-52" cy="0" r="40" fill="none" ${st(C.navy,8)}/><circle cx="52" cy="0" r="40" fill="none" ${st(C.navy,8)}/><path d="M-14 -6 Q0 -22 14 -6" fill="none" ${st(C.navy,8)}/><path d="M-92 -8 L-124 -20 M92 -8 L124 -20" ${st(C.navy,8)}/></g>${m}</g>`};

/* ---------- waves: small and calm, or enormous hitting the rocks ---------- */
P.e107_waves=(o,T)=>{const big=o.big,ph=T*(big?1.6:1.1);let rocks='',sp='';
  if(big){rocks=`<polygon points="70,130 80,70 106,52 130,56 140,130" fill="#5F6B73" ${st(C.navy,4)}/><polygon points="96,130 104,86 124,78 140,90 140,130" fill="#7A858D" ${st(C.navy,3)}/>`;for(let i=0;i<9;i++){const q=(T*1.1+i/9)%1;sp+=`<circle cx="${f(74+_e107rnd(i,81)*36-q*8)}" cy="${f(56-q*50)}" r="${f(3+_e107rnd(i,82)*5)}" fill="#fff" opacity="${f(1-q)}"/>`}}
  return _e107pan('e107_cwa',`<rect x="-140" y="-110" width="280" height="240" fill="${big?'#8FA0AB':'#A7DCF2'}"/>${big?`<g transform="translate(-40,-80) scale(1.4,.9)">${cloudShape('#6F8390')}</g><g transform="translate(86,-84) scale(.9,.7)">${cloudShape('#7F919D')}</g>`:_e107sun(70,-68,26,T,0)}${_e107wave(big?-14:0,big?26:8,big?40:34,ph,big?'#5BA9D6':'#6FB1D6',1)}${_e107wave(big?30:34,big?34:8,big?34:28,-ph*.8+1,big?'#4D9BC8':'#4D9BC8',1)}${_e107wave(big?74:70,big?26:7,big?26:24,ph*.9+2,big?'#3F8DBB':'#3F8DBB',1)}${rocks}${sp}`)};

/* ---------- 'no swimming' sign ---------- */
P.e107_noswim=(o,T)=>{const w=Math.sin(T*3)*3;return `<g><rect x="-6" y="76" width="12" height="50" fill="#9FB0BA" ${st()}/><circle r="86" fill="${C.white}" ${st(C.red,14)}/><g transform="translate(0,4)"><path d="M-56 38 q14 -12 28 0 t28 0 t28 0 t28 0" fill="none" ${st(C.blue,8)} transform="translate(${f(w)},0)"/><circle cx="-38" cy="-10" r="14" fill="${C.navy}"/><path d="M-22 4 L28 8" fill="none" ${st(C.navy,15)}/><path d="M-8 -2 Q6 -38 34 -18" fill="none" ${st(C.navy,10)}/><path d="M28 8 L52 -4" fill="none" ${st(C.navy,10)}/></g><line x1="-62" y1="-62" x2="62" y2="62" ${st(C.red,14)}/></g>`};

/* ---------- red beach warning flag ---------- */
P.e107_flag=(o,T)=>{const c=o.c||C.red;let t='',b='';for(let i=0;i<=7;i++){const x=i*11,y=Math.sin(i*.9-T*5)*5;t+=(i?'L':'M')+f(x)+' '+f(-100+y)+' ';b=`L${f(x)} ${f(-56+y)} `+b}
  return `<g transform="translate(-26,0)"><ellipse cx="0" cy="104" rx="64" ry="14" fill="#F0D9A0" ${st()}/><rect x="-4" y="-112" width="8" height="212" rx="3" fill="${C.cream}" ${st(C.navy,4)}/><path d="${t}${b}Z" transform="translate(4,0)" fill="${c}" ${st()}/></g>`};

/* ---------- sitting on the beach, watching big waves hit the rocks ---------- */
P.e107_beachwatch=(o,T)=>{const ph=T*1.5;let sp='';for(let i=0;i<8;i++){const q=(T*1.1+i/8)%1;sp+=`<circle cx="${f(86+_e107rnd(i,83)*30-q*8)}" cy="${f(2-q*46)}" r="${f(3+_e107rnd(i,84)*5)}" fill="#fff" opacity="${f(1-q)}"/>`}
  return _e107pan('e107_cbw',`<rect x="-140" y="-110" width="280" height="240" fill="#8FA0AB"/><g transform="translate(-30,-84) scale(1.4,.9)">${cloudShape('#6F8390')}</g>${_e107wave(-34,26,40,ph,'#5BA9D6',1)}${_e107wave(8,30,34,-ph*.8+1,'#4D9BC8',1)}<polygon points="80,60 90,0 114,-18 138,-12 146,60" fill="#5F6B73" ${st(C.navy,4)}/>${sp}<path d="M-140 56 Q-20 36 140 62 V130 H-140Z" fill="#F0D9A0" ${st(C.navy,4)}/>${_e107back(-52,84,.3,'#D96C8B','#2A1D18')}${_e107back(-8,90,.3,'#4DA3D8','#222')}${_e107back(38,84,.28,'#E2B653','#2A1D18')}`)};

/* ---------- children run into small waves and back ---------- */
P.e107_kidswave=(o,T)=>{let kids='';[['#F2994A','#3A2A22',0],['#D96C8B','#2A1D18',.5]].forEach(([c,h,off],i)=>{const u=(T*.3+off)%1,tri=u<.5?u*2:2-u*2,x=-70+tri*140,dir=u<.5?1:-1,y=i?72:56;kids+=`<g transform="translate(${f(x)},${f(y-108*.34)}) scale(${dir*.34},.34)">${_e107run(c,h,T,10)}</g>`});
  return _e107pan('e107_ckw',`<rect x="-140" y="-110" width="280" height="240" fill="#A7DCF2"/>${_e107sun(-84,-70,24,T,0)}${_e107wave(-8,8,30,T*1.2,'#6FB1D6',1)}${_e107wave(22,8,26,-T*1.1,'#4DA3D8',1)}<path d="M-140 44 Q0 30 140 46 V130 H-140Z" fill="#F0D9A0" ${st(C.navy,4)}/>${kids}`)};

/* ---------- battery ---------- */
P.e107_battery=(o,T)=>{const lv=o.lv==null?3:o.lv,col=lv>=3?'#52C27A':lv===2?C.orange:C.red;let sg='';for(let i=0;i<3;i++)sg+=`<rect x="${-70+i*46}" y="-26" width="38" height="52" rx="6" fill="${i<lv?col:'#E1E8EC'}" opacity="${i<lv?(lv===1?f(.6+.4*Math.sin(T*5)):1):1}"/>`;
  return `<g><rect x="-86" y="-46" width="164" height="92" rx="16" fill="${C.white}" ${st()}/><rect x="78" y="-18" width="16" height="36" rx="6" fill="${C.navy}"/>${sg}</g>`};

/* ---------- mood: full of energy / tired ---------- */
P.e107_mood=(o,T)=>{const tired=o.k==='tired';
  if(!tired){const jump=Math.abs(Math.sin(T*4))*16;let sp='';for(let i=0;i<8;i++){const a=i*45+T*40;sp+=`<line x1="0" y1="-120" x2="0" y2="-142" transform="translate(-34,22) rotate(${f(a)})" ${st(C.gold,6)} opacity="${f(.5+.5*Math.sin(T*6+i))}"/>`}
    return `<g>${sp}<g transform="translate(0,${f(-jump)})">${_e107p(-34,34,.72,{c:'#E2B653',hair:'bun',hc:'#2A1D18'},T)}</g><ellipse cx="-34" cy="104" rx="${f(54-jump*.5)}" ry="8" fill="#000" opacity=".12"/><g transform="translate(78,-30) scale(.5)">${P.e107_battery({lv:3},T)}</g></g>`}
  return `<g><g transform="translate(-34,34) rotate(${f(-8+Math.sin(T*1.2)*1.5)} 0 70) scale(.72)">${P.person({c:'#B9A56E',hair:'bun',hc:'#2A1D18'},T)}</g><ellipse cx="-34" cy="104" rx="54" ry="8" fill="#000" opacity=".12"/><g transform="translate(60,-70) scale(.8)">${P.zzz({},T)}</g><g transform="translate(78,-30) scale(.5)">${P.e107_battery({lv:1},T)}</g></g>`};

/* ---------- angry: red steam over a person ---------- */
P.e107_steam=(o,T)=>{let s='';for(let i=0;i<4;i++){const ph=(T*.8+i/4)%1;s+=`<circle cx="${f(-30+i*20+Math.sin(T*3+i)*5)}" cy="${f(-86-ph*60)}" r="${f(8+ph*14)}" fill="#E5604D" opacity="${f(1-ph)}"/>`}
  const z=(x,y,m)=>`<path d="M${x} ${y} l10 -16 l-8 0 l10 -18" fill="none" ${st('#E5604D',6)} transform="scale(${m},1)"/>`;
  return `<g>${s}${z(-80,-30,1)}${z(-80,-30,-1)}<g transform="translate(0,28)">${P.person({c:'#C0504D',hair:'short',hc:'#222'},T)}</g></g>`};

/* ---------- plant that needs the right sun, water and temperature ---------- */
P.e107_plantneeds=(o,T,k)=>{const sw=Math.sin(T*1.4)*3;let lv='';[[-40,-10,-30],[40,-30,30],[-34,-62,-24],[36,-80,26],[0,-112,0]].forEach(([x,y,r],i)=>{const g=ease((k-i*.2)/.4);lv+=`<g transform="translate(${x*.0},${y+30}) rotate(${r}) scale(${f(.4+.6*g)})"><path d="M0 0 C-34 -20 -34 -62 0 -78 C34 -62 34 -20 0 0Z" fill="#5E9B63" ${st(C.navy,5)}/><path d="M0 -4 V-64" stroke="#3F7A47" stroke-width="4"/></g>`});
  let dr='';for(let i=0;i<3;i++){const ph=(T*.8+i/3)%1;dr+=`<path d="M${f(82+i*14)} ${f(-96+ph*70)} q-6 10 0 15 q6 -5 0 -15" fill="${C.blue}" ${st(C.navy,2)} opacity="${f(1-ph*.8)}"/>`}
  return `<g>${_e107sun(-78,-80,28,T,0)}${dr}<g transform="translate(104,36) scale(.42)">${P.thermo({level:.5},T,9)}</g><g transform="translate(-6,0) rotate(${f(sw)} 0 100)"><rect x="-6" y="-54" width="12" height="150" rx="5" fill="#5E9B63" ${st(C.navy,4)}/><g transform="translate(0,-38)">${lv}</g></g><path d="M-52 78 L52 78 L40 124 L-40 124Z" fill="#C0724A" ${st()}/><rect x="-58" y="68" width="116" height="16" rx="6" fill="#D98B5F" ${st()}/></g>`};

/* ---------- gloom: person under a small rain cloud ---------- */
P.e107_gloom=(o,T)=>{let d='';for(let i=0;i<7;i++){const x=-40+i*14,y=((T*150+i*37)%80);d+=`<line x1="${x}" y1="${f(-70+y)}" x2="${x-5}" y2="${f(-54+y)}" ${st(C.blue,4)} opacity="${f(1-y/90)}"/>`}
  return `<g><g transform="translate(0,${f(-100+Math.sin(T*1.2)*4)}) scale(.62)">${cloudShape('#8FA0AB')}</g>${d}<g transform="translate(0,40) rotate(${f(5)} 0 100) scale(.78)">${P.person({c:'#7A8FA8',hair:'short',hc:'#222'},T)}</g></g>`};

/* ---------- phone: weather icon / photo of clouds / video / chat ---------- */
P.e107_phone=(o,T,k)=>{const kind=o.k||'photo';let scr='';
  if(kind==='temp'){scr=`<g transform="translate(0,-2) scale(.62)">${P.thermo({level:.9},T,9)}</g>`}
  else if(kind==='cloud'){scr=`<g transform="translate(0,6) scale(.55)">${cloudShape()}</g>`}
  else if(kind==='rain'){scr=`<g transform="translate(0,-2) scale(.66)">${P.rain({heavy:0},T)}</g>`}
  else if(kind==='storm'){scr=`<rect x="-46" y="-86" width="92" height="170" fill="#C98A2E"/>${_e107dust(T,1,8).replace(/stroke-width="[^"]+"/g,'stroke-width="3"')}<g transform="translate(0,30) scale(.5,.4)">${_e107hill(0,10,40,.7,'#8A5A1E').replace(/136/g,'60')}</g>`}
  else if(kind==='msgs'){let b='';[[-1,-52,'#fff'],[1,-12,'#FFE7A8'],[-1,28,'#fff']].forEach(([s,y,c],i)=>{const p=ease((k-.2-i*.45)/.3);b+=`<g transform="translate(${s*6},${y}) scale(${f(p)})" opacity="${f(p)}"><rect x="${s<0?-44:-28}" y="-16" width="72" height="34" rx="14" fill="${c}" ${st(C.navy,3)}/><g transform="translate(${s<0?-8:8},1) scale(.2)">${i===1?P.drop({},T):cloudShape()}</g></g>`});scr=b}
  else{ // photo or video
    scr=`<rect x="-44" y="-70" width="88" height="110" fill="#9FB6C4"/><g transform="translate(0,-26) scale(.42)">${cloudShape('#EEF2F4')}</g><path d="M-30 -2 l10 12 M-4 -2 l10 12 M20 -2 l10 12" stroke="${C.blue}" stroke-width="3" stroke-linecap="round"/><rect x="-36" y="50" width="72" height="8" rx="4" fill="#E1E8EC"/>`+(kind==='video'?`<circle cx="0" cy="-20" r="20" fill="#fff" opacity=".85" ${st(C.navy,3)}/><polygon points="-6,-30 -6,-10 12,-20" fill="${C.navy}"/>`:'')}
  return `<g><rect x="-64" y="-114" width="128" height="228" rx="24" fill="${C.navy}" ${st()}/><clipPath id="e107_cph"><rect x="-52" y="-96" width="104" height="188" rx="12"/></clipPath><rect x="-52" y="-96" width="104" height="188" rx="12" fill="${kind==='msgs'||kind==='temp'||kind==='cloud'||kind==='rain'?'#DCEBF3':C.cream}"/><g clip-path="url(#e107_cph)">${scr}</g><rect x="-22" y="80" width="44" height="6" rx="3" fill="${C.navy}" opacity=".35"/></g>`};

/* ---------- a rainy day on the calendar, with bunting ---------- */
P.e107_raindaycal=(o,T,k)=>{let bu='';const cs=[C.red,C.gold,C.blue,C.moss,C.orange];for(let i=0;i<6;i++){const x=-100+i*40,y=-88+Math.sin(i/5*Math.PI)*14;bu+=`<polygon points="${x-16},${y} ${x+16},${y} ${x},${y+34}" fill="${cs[i%5]}" ${st(C.navy,3.5)}/>`}
  return `<g><path d="M-120 -90 Q0 -62 120 -90" fill="none" ${st(C.navy,4)}/>${bu}<g transform="translate(0,26)"><rect x="-84" y="-60" width="168" height="150" rx="16" fill="${C.white}" ${st()}/><path d="M-84 -34 V-44 Q-84 -60 -68 -60 H68 Q84 -60 84 -44 V-34Z" fill="${C.red}" ${st()}/><g transform="translate(0,${f(18+Math.sin(T*3)*3)}) scale(1.05)"><path d="M0 -44 C20 -14 28 -2 28 12 a28 28 0 0 1 -56 0 C-28 -2 -20 -14 0 -44Z" fill="${C.blue}" ${st()}/><path d="M-10 6 q-2 10 6 14" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round" opacity=".7"/></g></g></g>`};

/* ---------- small framed plans: desert trip / coast day / picnic on grass ---------- */
P.e107_planicon=(o,T)=>{const kd=o.k||'desert';let inner='';
  if(kd==='desert')inner=`<rect x="-140" y="-110" width="280" height="240" fill="#A7DCF2"/>${_e107sun(60,-56,20,T,0)}${_e107hill(10,8,44,.5,'#EBC98A')}${_e107hill(52,8,36,2,'#D9AE62')}<g transform="translate(-22,36) scale(.46)"><polygon points="-66,50 0,-62 66,50" fill="${C.orange}" ${st(C.navy,7)}/><path d="M0 -26 L-22 50 L22 50Z" fill="#3B2A24" ${st(C.navy,5)}/></g>`;
  else if(kd==='coast')inner=`<rect x="-140" y="-110" width="280" height="240" fill="#A7DCF2"/>${_e107sun(60,-56,20,T,0)}${_e107wave(-6,7,30,T*1.2,'#6FB1D6',1)}${_e107wave(26,7,26,-T*1.1,'#4DA3D8',1)}<path d="M-140 58 Q0 42 140 62 V130 H-140Z" fill="#F0D9A0" ${st(C.navy,4)}/>`;
  else inner=`<rect x="-140" y="-110" width="280" height="240" fill="#A7DCF2"/>${_e107sun(60,-56,20,T,0)}${_e107hill(10,7,46,.6,'#8DBF7E')}<rect x="-140" y="30" width="280" height="100" fill="#6FAE6A"/><path d="M-60 90 L-40 48 L40 48 L60 90Z" fill="#F4E5C2" ${st()}/><path d="M-46 84 L-32 56 M-8 84 L2 56 M28 84 L38 56" stroke="${C.red}" stroke-width="6" opacity=".6"/><g transform="translate(34,38) scale(.34)"><path d="M-40 -10 L40 -10 L34 36 L-34 36Z" fill="#C98842" ${st()}/><path d="M-36 -10 Q0 -64 36 -10" fill="none" ${st(C.navy,6)}/></g><circle cx="-22" cy="48" r="9" fill="#E1A25B" ${st(C.navy,3)}/>`;
  return _e107pan('e107_cpi'+kd,inner,{w:220,h:180,r:16})};

/* ---------- wide sun hat ---------- */
P.e107_hat=(o,T)=>`<g><ellipse cx="0" cy="40" rx="116" ry="32" fill="#E9CE8A" ${st()}/><path d="M-62 36 Q-62 -52 0 -52 Q62 -52 62 36Z" fill="#F4DFA0" ${st()}/><path d="M-62 28 Q0 46 62 28 L62 14 Q0 32 -62 14Z" fill="${C.red}" ${st(C.navy,4)}/><path d="M-84 52 q14 8 34 8 M30 62 q24 0 54 -10" fill="none" stroke="#C9A860" stroke-width="3" opacity=".6"/><path d="M-30 -30 q14 -12 34 -10" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round" opacity=".5"/></g>`;

/* ---------- sun cream tube ---------- */
P.e107_suncream=(o,T)=>`<g transform="rotate(-18)"><path d="M-46 -84 L46 -84 L40 86 L-40 86Z" fill="#F6CE4B" ${st()}/><rect x="-42" y="-10" width="84" height="76" fill="${C.white}" ${st(C.navy,3)}/><g transform="translate(0,28) scale(.3)">${_e107sun(0,0,60,T,0,10)}</g><rect x="-34" y="-124" width="68" height="42" rx="8" fill="${C.red}" ${st()}/><rect x="-26" y="-82" width="52" height="10" fill="#C9433F"/><path d="M-30 -70 L-26 80" stroke="#fff" stroke-width="5" opacity=".5" stroke-linecap="round"/></g>`;

/* ---------- a hot parked car with a child and a dog inside ---------- */
P.e107_hotcar=(o,T)=>{const who=o.who||'both';let ins='';
  if(who!=='dog')ins+=_e107p(-10,-44,.17,{c:'#F2994A',hair:'short',hc:'#3A2A22'},T);
  if(who!=='child')ins+=`<g transform="translate(${who==='dog'?4:36},-34)"><path d="M-14 6 Q-14 -12 0 -12 Q14 -12 14 6Z" fill="#B9733C" ${st(C.navy,3)}/><path d="M-12 -8 q-8 -2 -6 12 q6 2 8 -4Z" fill="#8A5528" ${st(C.navy,2.5)}/></g>`;
  return `<g>${_e107sun(-80,-96,24,T,1)}${_e107heat(-40,-46,5,22,T,'#E5604D',4)}<g transform="translate(-8,30) scale(.8)">${_e107car('#C0504D',{win:'#BFE3F2'})}</g><clipPath id="e107_chc"><path d="M-62 -26 H56 L36 -54 H-34Z"/></clipPath><g transform="translate(-8,44)" clip-path="url(#e107_chc)"></g><g transform="translate(-8,30) scale(.8)"><clipPath id="e107_chc2"><path d="M-34 -58 H42 L64 -24 H-56Z"/></clipPath><g clip-path="url(#e107_chc2)">${ins}</g></g><g transform="translate(98,40) scale(.46)">${P.thermo({level:.97},T,9)}</g></g>`};

/* ---------- phone with a location pin (telling someone where you go) ---------- */
P.e107_phonepin=(o,T,k)=>{const bn=Math.abs(Math.sin(T*3))*6;
  return `<g><rect x="-64" y="-114" width="128" height="228" rx="24" fill="${C.navy}" ${st()}/><rect x="-52" y="-96" width="104" height="188" rx="12" fill="#E4EFD8"/><path d="M-52 -20 q30 -40 60 0 t44 -30" fill="none" stroke="#fff" stroke-width="9"/><path d="M-52 30 q40 10 104 -20" fill="none" stroke="#fff" stroke-width="9"/><path d="M-20 -96 L10 92" stroke="#fff" stroke-width="7"/><g transform="translate(4,${f(-8-bn)})"><ellipse cx="0" cy="${f(46+bn)}" rx="12" ry="4" fill="#000" opacity=".2"/><path d="M0 44 C-26 12 -22 -22 0 -24 C22 -22 26 12 0 44Z" fill="${C.red}" ${st()}/><circle cx="0" cy="-4" r="8" fill="${C.cream}" ${st(C.navy,3)}/></g><rect x="-22" y="80" width="44" height="6" rx="3" fill="${C.navy}" opacity=".35"/></g>`};

/* ---------- four seasons ---------- */
P.e107_seasons=(o,T)=>{const cell=(x,y,bg,inner)=>`<g transform="translate(${x},${y})"><rect x="-60" y="-48" width="120" height="96" rx="14" fill="${bg}" ${st()}/>${inner}</g>`;
  const leaf=`<path d="M-4 30 C-40 4 -34 -26 6 -34 C26 -8 22 14 -4 30Z" fill="${C.orange}" ${st(C.navy,4)} transform="rotate(${f(Math.sin(T*2)*8)})"/><path d="M-4 30 L6 -20" stroke="${C.navy}" stroke-width="3"/>`;
  let fl='';for(let i=0;i<5;i++)fl+=`<circle cx="0" cy="-17" r="11" fill="#F29BB5" ${st(C.navy,3)} transform="rotate(${i*72})"/>`;
  return `<g>${cell(-66,-54,'#BFE3F2',`<g transform="scale(.5)">${_e107sun(0,0,34,T,1,10)}</g>`)}${cell(66,-54,'#F6E3B4',leaf)}${cell(-66,54,'#DCEAF2',`<g transform="scale(1.4)">${_e107snow(0,0,16,'#4DA3D8',4)}</g>`)}${cell(66,54,'#DCEFD2',`<g>${fl}<circle r="9" fill="${C.gold}" ${st(C.navy,3)}/></g>`)}</g>`};

/* ---------- TIP card with a number ---------- */
P.e107_tip=(o,T)=>{const p=1+.03*Math.sin(T*4);return `<g transform="scale(${f(p)})"><rect x="-100" y="-86" width="200" height="172" rx="26" fill="${C.cream}" ${st()}/><path d="M-100 -50 V-60 Q-100 -86 -74 -86 H74 Q100 -86 100 -60 V-50Z" fill="${C.gold}" ${st()}/><rect x="-100" y="-62" width="200" height="12" fill="${C.gold}"/><line x1="-100" y1="-50" x2="100" y2="-50" ${st(C.navy,5)}/><text x="0" y="-60" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" fill="${C.navy}" letter-spacing="8">TIP</text><text x="0" y="52" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="104" fill="${C.navy}">${o.n}</text></g>`};

/* ---------- house covered in yellow dust ---------- */
P.e107_dusthouse=(o,T)=>`<g><clipPath id="e107_cdh"><rect x="-122" y="-104" width="244" height="200"/></clipPath>${P.house({},T)}<g clip-path="url(#e107_cdh)"><ellipse cx="0" cy="-30" rx="100" ry="34" fill="#E0B04A" opacity=".5"/><ellipse cx="0" cy="40" rx="104" ry="50" fill="#E0B04A" opacity=".4"/>${_e107dust(T,.7,12)}</g><path d="M-112 96 q30 -22 60 -4 q40 -16 80 -2 q40 -8 56 6 L112 100 L-112 100Z" fill="#E0B04A" ${st('#B8903C',4)}/></g>`;

/* ---------- a person walking (full body, calm pace) ---------- */
P.e107_walk=(o,T)=>{const j=Math.abs(Math.sin(T*3))*4;return `<g><ellipse cx="0" cy="108" rx="60" ry="9" fill="#000" opacity=".13"/><g transform="translate(0,${f(-j)})">${_e107run(o.c||'#4DA3D8',o.hc||'#222',T,3.2)}</g></g>`};

/* Episode 107 intro hero: a blazing sun peeking behind a storm cloud with flashing lightning and falling rain, plus a hot thermometer - hot summers and big storms */
const _e107iS=(x,y,s,T,ph,c='#FFE9A8')=>{const a=.5+.5*Math.sin(T*2.4+ph);const r=s*(.65+.35*a);return `<path d="M${f(x)} ${f(y-r)}Q${f(x)} ${f(y)} ${f(x+r*.8)} ${f(y)}Q${f(x)} ${f(y)} ${f(x)} ${f(y+r)}Q${f(x)} ${f(y)} ${f(x-r*.8)} ${f(y)}Q${f(x)} ${f(y)} ${f(x)} ${f(y-r)}Z" fill="${c}" opacity="${f(.45+.55*a)}"/>`};
const _e107iPlate=(T,c1,c2)=>`<defs><radialGradient id="e107i_pl" cx="50%" cy="38%" r="62%"><stop offset="0" stop-color="${c1}" stop-opacity=".62"/><stop offset=".7" stop-color="${c2}" stop-opacity=".22"/><stop offset="1" stop-color="${c2}" stop-opacity=".06"/></radialGradient></defs><circle r="132" fill="url(#e107i_pl)"/><circle r="132" fill="none" stroke="${c1}" stroke-opacity=".4" stroke-width="2.5"/><circle r="122" fill="none" stroke="#fff" stroke-opacity=".28" stroke-width="2" stroke-dasharray="3 11" stroke-linecap="round" transform="rotate(${f(T*6)})"/>`;
P.e107_ihero=(o,T,k)=>{
  const s=Math.sin,b=(a,p,sp=1.4)=>s(T*sp+p)*a;
  const flash=Math.pow(Math.max(0,s(T*2.3)),12);
  const glow=.5+.5*s(T*2);
  const rays=Array.from({length:12},(_,i)=>`<path d="M-7 -44L0 ${i%2?-52:-60}L7 -44Z" transform="rotate(${i*30})" fill="#FFC23A" ${st(C.navy,3)}/>`).join('');
  const drops=Array.from({length:8},(_,i)=>{const u=((T*.85+i*.29)%1);const x=-30+i*13+(i%2)*4;return `<path d="M${f(x-u*6)} ${f(30+u*66)}l-4 10" stroke="#8FDCFF" stroke-width="4.500" stroke-linecap="round" opacity="${f(Math.min(1,u*6)*(1-Math.pow(u,5)))}"/>`}).join('');
  const lvl=-18-8*glow;
  const wind=[0,1].map(i=>`<path d="M${-6+i*10} ${72+i*14}H${40+i*8}Q${52+i*8} ${72+i*14} ${52+i*8} ${64+i*14}" fill="none" stroke="#fff" stroke-opacity=".75" stroke-width="3.500" stroke-linecap="round" stroke-dasharray="26 40" stroke-dashoffset="${f(-T*40-i*20)}"/>`).join('');
  return `<g>
  <defs>
   <radialGradient id="e107i_sn" cx="40%" cy="35%" r="70%"><stop offset="0" stop-color="#FFF3A0"/><stop offset=".6" stop-color="#FFC93A"/><stop offset="1" stop-color="#F58A2A"/></radialGradient>
   <radialGradient id="e107i_sg" cx="50%" cy="50%" r="50%"><stop offset="0" stop-color="#FFC93A" stop-opacity=".7"/><stop offset="1" stop-color="#FFC93A" stop-opacity="0"/></radialGradient>
   <linearGradient id="e107i_cl" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#C5D0EE"/><stop offset="1" stop-color="#6F7DB5"/></linearGradient>
   <linearGradient id="e107i_th" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FF8A6A"/><stop offset="1" stop-color="#E5303A"/></linearGradient>
  </defs>
  ${_e107iPlate(T,'#7C8CF0','#3B3F9A')}
  <g transform="translate(0,14)">
  <g transform="translate(-48,${f(-44+b(3,0,1.1))})">
    <circle r="${f(70+6*glow)}" fill="url(#e107i_sg)"/>
    <g transform="rotate(${f(T*10)})">${rays}</g>
    <circle r="36" fill="url(#e107i_sn)" ${st(C.navy,5)}/>
    <path d="M-24 -14Q-18 -26 -6 -29" fill="none" stroke="#fff" stroke-opacity=".8" stroke-width="5" stroke-linecap="round"/>
  </g>
  <g transform="translate(${f(30+b(4,0,.8))},${f(-8+b(2,1,1.1))})">
    <path d="M-62 28Q-84 28 -82 8Q-80 -10 -62 -8Q-58 -34 -30 -32Q-14 -52 12 -42Q36 -54 54 -32Q82 -32 84 -6Q92 20 68 28Z" fill="url(#e107i_cl)" ${st(C.navy,5)}/>
    <path d="M-70 4Q-68 -2 -60 -2" fill="none" stroke="#fff" stroke-opacity=".75" stroke-width="4" stroke-linecap="round"/>
    <path d="M-34 -22Q-26 -34 -12 -34" fill="none" stroke="#fff" stroke-opacity=".6" stroke-width="4" stroke-linecap="round"/>
    <g transform="translate(-4,22) scale(${f(1+.1*flash)})"><path d="M10 -4L-10 30H2L-6 58L22 18H8L18 -4Z" fill="#FFE55C" ${st(C.navy,4)} /><path d="M10 -4L-10 30H2L-6 58L22 18H8L18 -4Z" fill="#fff" opacity="${f(.7*flash)}"/></g>
    ${drops}
  </g>
  <g transform="translate(-98,${f(40+b(2,1,1.2))}) scale(.9)">
    <rect x="-10" y="-52" width="20" height="96" rx="10" fill="#EAF6FF" ${st(C.navy,4.500)}/>
    <circle cy="46" r="18" fill="#EAF6FF" ${st(C.navy,4.500)}/>
    <rect x="-5" y="${f(lvl)}" width="10" height="${f(46-lvl)}" rx="5" fill="url(#e107i_th)"/>
    <circle cy="46" r="12.500" fill="url(#e107i_th)"/><circle cx="-4" cy="42" r="3.500" fill="#fff" opacity=".8"/>
    <path d="M14 -40H24M14 -26H21M14 -12H24M14 2H21M14 16H24" stroke="#FFD3A0" stroke-width="3" stroke-linecap="round"/>
    <path d="M-7 -44V30" stroke="#fff" stroke-opacity=".8" stroke-width="2.500" stroke-linecap="round" transform="translate(-0.5,0)"/>
  </g>
  </g>
  ${_e107iS(-126,-8,8,T,0)}${_e107iS(122,-74,8,T,1.7,'#C9D2FF')}${_e107iS(122,40,6,T,3.1)}${_e107iS(-20,-116,6,T,4.4,'#C9D2FF')}${_e107iS(60,108,6,T,2.2,'#C9D2FF')}
  </g>`};

/* A2 ep 7 props end */
/* A2 ep 8 props begin */
/* Episode 108 props: hobbies and free time — basketball, cycling, drawing, a competition, a coach, climbing, camping, photos, stamps, novels, TV series, tips. Faceless. Uses C, st, f, ease, clamp, P. */
const _e108pan=(id,inner,o={})=>{const w=o.w||260,h=o.h||210,r=o.r||18;return `<g><clipPath id="${id}"><rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="${r}"/></clipPath><g clip-path="url(#${id})">${inner}</g><rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="${r}" fill="none" ${st()}/></g>`};
const _e108rnd=(i,m)=>{const s=Math.sin(i*127.1+m*311.7)*43758.5453;return s-Math.floor(s)};
const _e108p=(x,y,s,o,T,extra)=>`<g transform="translate(${f(x)},${f(y)}) scale(${f(s)})">${P.person(o,T)}${extra||''}</g>`;
const _e108sun=(x,y,r,T)=>{let ra='';for(let i=0;i<10;i++)ra+=`<line x1="0" y1="${f(-(r+7))}" x2="0" y2="${f(-(r+7+r*.4))}" transform="translate(${x},${y}) rotate(${f(i*36+T*8)})" ${st('#E0A526',4)}/>`;return `${ra}<circle cx="${x}" cy="${y}" r="${r}" fill="#F6CE4B" ${st(C.navy,4)}/>`};
const _e108hill=(y0,amp,wl,ph,fill)=>{let e='';for(let x=-140;x<=140;x+=8){const y=y0+Math.sin(x/wl+ph)*amp+Math.sin(x/(wl*.43)+ph*2.1)*amp*.25;e+=(x===-140?'M':'L')+x+' '+f(y)+' '}return `<path d="${e}L140 140 L-140 140Z" fill="${fill}" ${st(C.navy,4)}/>`};
const _e108tree=(x,y,s,col)=>`<g transform="translate(${f(x)},${f(y)}) scale(${f(s)})"><rect x="-6" y="-4" width="12" height="34" fill="#8A5A34" ${st(C.navy,4)}/><circle cx="0" cy="-22" r="30" fill="${col||'#5CA86A'}" ${st(C.navy,4)}/><circle cx="-12" cy="-30" r="9" fill="#fff" opacity=".18"/></g>`;
const _e108back=(x,y,s,c,hc,hair)=>`<g transform="translate(${f(x)},${f(y)}) scale(${f(s)})"><path d="M-62 108 L-62 36 Q-62 -4 0 -4 Q62 -4 62 36 L62 108 Z" fill="${c}" ${st()}/><rect x="-11" y="-20" width="22" height="22" fill="#D79B70" ${st(C.navy,4)}/><circle cx="0" cy="-54" r="38" fill="${hc}" ${st()}/>${hair==='bun'?`<circle cx="0" cy="-102" r="16" fill="${hc}" ${st()}/>`:''}</g>`;
const _e108cap=(c)=>`<path d="M-38 -70 A38 38 0 0 1 38 -70 Z" fill="${c}" ${st()}/><path d="M-4 -70 L58 -70 Q66 -70 66 -63 L-4 -63Z" fill="${c}" ${st()}/>`;
const _e108cat=(x,y,s,col,T,flip)=>{const tl=Math.sin(T*2)*6;return `<g transform="translate(${f(x)},${f(y)}) scale(${f(flip?-s:s)},${f(s)})"><path d="M52 30 Q96 24 84 -22 Q80 -32 70 -24" fill="none" ${st(C.navy,14)}/><path d="M52 30 Q96 24 84 -22 Q80 -32 70 ${f(-24+tl)}" fill="none" ${st(col,8)}/><ellipse cx="6" cy="22" rx="56" ry="38" fill="${col}" ${st()}/><circle cx="-44" cy="-14" r="30" fill="${col}" ${st()}/><path d="M-66 -34 L-62 -66 L-44 -44Z" fill="${col}" ${st()}/><path d="M-30 -40 L-20 -66 L-18 -30Z" fill="${col}" ${st()}/></g>`};
const _e108tvbox=(inner,id,T,w,h)=>{w=w||200;h=h||138;return `<g><clipPath id="${id}"><rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="10"/></clipPath><rect x="${-w/2-12}" y="${-h/2-12}" width="${w+24}" height="${h+24}" rx="18" fill="#2B3A4A" ${st()}/><g clip-path="url(#${id})">${inner}</g><rect x="-34" y="${h/2+12}" width="68" height="14" rx="4" fill="#2B3A4A" ${st()}/><rect x="-60" y="${h/2+24}" width="120" height="10" rx="5" fill="#2B3A4A" ${st()}/></g>`};

/* ---------- basketball hoop with a ball ---------- */
P.e108_hoop=(o,T,k)=>{const by=Math.abs(Math.sin(T*3))*26,ang=T*60;let net='';for(let i=0;i<5;i++)net+=`<path d="M${-30+i*15} 18 L${-22+i*11} 58" ${st(C.white,3)}/>`;
  return `<g><rect x="-6" y="-60" width="12" height="190" fill="#7E8C99" ${st()}/><rect x="-80" y="-112" width="160" height="104" rx="8" fill="${C.white}" ${st()}/><rect x="-30" y="-52" width="60" height="44" fill="none" ${st(C.red,5)}/><ellipse cx="0" cy="18" rx="34" ry="8" fill="none" ${st(C.orange,8)}/>${net}<path d="M-30 20 Q0 36 30 20" fill="none" ${st(C.navy,3)}/><g transform="translate(0,${f(104-by)})"><circle cx="0" cy="0" r="30" fill="#F28C38" ${st()}/><g transform="rotate(${f(ang)})"><path d="M-30 0 H30 M0 -30 V30" ${st(C.navy,3.5)} fill="none"/><path d="M-21 -21 Q0 0 -21 21 M21 -21 Q0 0 21 21" fill="none" ${st(C.navy,3.5)}/></g></g></g>`};

/* ---------- indoor court panel with players (n of them) ---------- */
P.e108_court=(o,T,k)=>{const n=o.n==null?8:o.n,cols=['#E2B653','#4DA3D8','#D96C8B','#4F7A5A','#F2994A','#8E6BB5','#C0504D','#6A8FA8'],hs=['bun','short','long','short'];let pl='';
  for(let i=0;i<n;i++){const col=i%4,row=(i/4|0),x=-84+col*56+row*0,y=18+row*40;pl+=_e108p(x,y,.23,{c:cols[i%8],hair:hs[i%4],hc:['#222','#3A2A22','#8B5E3C','#BDC3C7'][i%4],ph:i},T)}
  const coach=o.coach?_e108p(-112,2,.34,{c:'#C0504D',hair:'short',hc:'#BDC3C7'},T,_e108cap('#C0504D')):'';
  return _e108pan('e108_cct',`<rect x="-140" y="-110" width="280" height="230" fill="#E8C48A"/><rect x="-140" y="-110" width="280" height="64" fill="#C9D5DC"/><line x1="-140" y1="-46" x2="140" y2="-46" ${st(C.navy,3)}/>${[-100,-40,20,80].map(x=>`<line x1="${x}" y1="-46" x2="${x}" y2="-110" stroke="#fff" stroke-width="3" opacity=".6"/>`).join('')}<rect x="-100" y="-30" width="200" height="130" fill="none" stroke="#fff" stroke-width="4"/><line x1="0" y1="-30" x2="0" y2="100" stroke="#fff" stroke-width="4"/><circle cx="0" cy="35" r="26" fill="none" stroke="#fff" stroke-width="4"/><g transform="translate(110,-26) scale(.34)">${P.e108_hoop({},T,k)}</g>${pl}${coach}`)};

/* ---------- bicycle with a (faceless) rider in a helmet ---------- */
const _e108bike=(T,col,mv)=>{const r=T*(mv==null?240:mv),wheel=(x)=>{let sp='';for(let i=0;i<6;i++)sp+=`<line x1="0" y1="-32" x2="0" y2="32" transform="rotate(${f(r+i*30)})" stroke="#9AA7B0" stroke-width="2"/>`;return `<g transform="translate(${x},40)"><circle r="36" fill="none" ${st(C.navy,7)}/>${sp}<circle r="5" fill="${C.navy}"/></g>`};
  const pa=Math.sin(T*8)*10;
  return `<g>${wheel(-58)}${wheel(62)}<path d="M-58 40 L-16 -20 L34 -20 L62 40 M-16 -20 L8 40 L-58 40 M34 -20 L26 -40 M26 -40 H44" fill="none" ${st(col,8)}/><path d="M-16 -20 L-24 -34 M-34 -34 H-14" fill="none" ${st(C.navy,6)}/><circle cx="8" cy="40" r="9" fill="#9AA7B0" ${st(C.navy,3)}/><path d="M8 40 L${f(8+pa)} ${f(62)}" ${st(C.navy,5)}/>
  <path d="M-24 -34 L8 -92 L30 -58" fill="none" ${st('#3F5A73',16)}/><path d="M-24 -34 L8 -92 L30 -58" fill="none" ${st('#4DA3D8',9)}/><path d="M-24 -34 L${f(0+pa*.6)} 6 L${f(8+pa)} 36" fill="none" ${st('#3F5A73',13)}/><path d="M30 -58 L42 -42" fill="none" ${st('#E3AE82',9)}/><path d="M8 -92 L12 -108" ${st('#E3AE82',12)}/><circle cx="16" cy="-122" r="19" fill="#E3AE82" ${st()}/><path d="M-2 -126 Q-2 -148 18 -146 Q38 -144 36 -124 Z" fill="${C.red}" ${st()}/></g>`};
P.e108_bike=(o,T,k)=>{let sp='';for(let i=0;i<3;i++){const ph=(T*2.2+i/3)%1;sp+=`<line x1="${f(-90-ph*40)}" y1="${-60+i*40}" x2="${f(-140-ph*40)}" y2="${-60+i*40}" ${st('#9AA7B0',5)} opacity="${f(1-ph)}"/>`}
  return `<g><ellipse cx="0" cy="80" rx="110" ry="9" fill="#000" opacity=".13"/>${sp}<g transform="translate(0,${f(-Math.abs(Math.sin(T*8))*3)})">${_e108bike(T,o.col||'#E8943A')}</g></g>`};

/* ---------- panel: river, a long hill and a bike; optional "40 km" ---------- */
P.e108_route=(o,T,k)=>{const x=-100+((T*.12)%1)*200,km=o.km||'40 km';
  return _e108pan('e108_crt',`<rect x="-140" y="-110" width="280" height="230" fill="#BFE4F4"/>${_e108sun(96,-70,22,T)}<path d="M-30 -10 Q40 -50 100 -6 Q140 24 140 40 L140 140 L-30 140Z" fill="#78B86A" ${st(C.navy,4)}/><path d="M-140 6 Q-120 -6 -80 8 Q-40 22 -10 12 L-20 140 L-140 140Z" fill="#5BB3E0" ${st(C.navy,4)}/><path d="M-120 30 Q-80 28 -50 36" fill="none" stroke="#fff" stroke-width="3" opacity=".7"/><path d="M-6 118 Q10 76 60 56 Q96 40 70 6" fill="none" ${st('#9B7B55',16)}/><path d="M-6 118 Q10 76 60 56 Q96 40 70 6" fill="none" stroke="#E8C48A" stroke-width="9" stroke-linecap="round"/><g transform="translate(${f(Math.min(30,x*.3)+40)},${f(70-Math.max(0,x+100)*.12)}) scale(.28)">${_e108bike(T,'#E8943A')}</g><g transform="translate(-92,70)"><rect x="-3" y="0" width="6" height="40" fill="#8A5A34" ${st(C.navy,3)}/><rect x="-28" y="-20" width="56" height="26" rx="5" fill="${C.cream}" ${st(C.navy,4)}/><text x="0" y="-2" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="16" fill="${C.navy}">${km}</text></g>`)};

/* ---------- panel: cycle race around a lake, many riders ---------- */
P.e108_bikerace=(o,T,k)=>{let r='';const cols=['#E8943A','#4DA3D8','#D9534F','#4F7A5A','#8E6BB5','#E2B653'];for(let i=0;i<34;i++){const a=((i/34)+T*.03)*Math.PI*2+_e108rnd(i,1)*.12,rr=1+(_e108rnd(i,2)-.5)*.1,x=Math.cos(a)*88*rr,y=Math.sin(a)*46*rr;r+=`<circle cx="${f(x)}" cy="${f(y)}" r="5.5" fill="${cols[i%6]}" ${st(C.navy,2.5)}/>`}
  return _e108pan('e108_cbr',`<rect x="-140" y="-110" width="280" height="230" fill="#9CCB84"/><ellipse cx="0" cy="0" rx="62" ry="30" fill="#5BB3E0" ${st(C.navy,4)}/><path d="M-20 -6 q10 -5 20 0 t20 0" fill="none" stroke="#fff" stroke-width="3" opacity=".7"/><ellipse cx="0" cy="0" rx="88" ry="46" fill="none" stroke="#F4EEDC" stroke-width="13"/><ellipse cx="0" cy="0" rx="88" ry="46" fill="none" ${st(C.navy,3)} stroke-dasharray="3 9" opacity=".5"/>${r}${_e108tree(-122,-80,.5)}${_e108tree(120,70,.5)}${_e108tree(-110,86,.45)}<rect x="-30" y="76" width="60" height="26" rx="6" fill="${C.cream}" ${st(C.navy,4)}/><text x="0" y="95" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="17" fill="${C.navy}">60 km</text>`)};

/* ---------- speed watch on a wrist ---------- */
P.e108_speedwatch=(o,T,k)=>{const a=-60+Math.abs(Math.sin(T*1.6))*120;let tk='';for(let i=0;i<7;i++)tk+=`<line x1="0" y1="-50" x2="0" y2="-42" transform="rotate(${-60+i*20})" ${st(C.navy,3)}/>`;
  return `<g><rect x="-30" y="-130" width="60" height="70" rx="10" fill="#3F5A73" ${st()}/><rect x="-30" y="60" width="60" height="70" rx="10" fill="#3F5A73" ${st()}/><rect x="-62" y="-62" width="124" height="124" rx="30" fill="#2B3A4A" ${st()}/><circle cx="0" cy="0" r="48" fill="${C.cream}" ${st(C.navy,4)}/>${tk}<g transform="translate(0,12)"><path d="M-50 0 A50 50 0 0 1 50 0" fill="none" stroke="${C.moss}" stroke-width="7" transform="scale(.8)"/><line x1="0" y1="0" x2="0" y2="-34" transform="rotate(${f(a)})" ${st(C.red,5)}/><circle r="5" fill="${C.navy}"/></g><text x="0" y="30" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="13" fill="${C.navy}">km/h</text><rect x="62" y="-8" width="9" height="16" rx="3" fill="#2B3A4A" ${st(C.navy,3)}/></g>`};

/* ---------- TV panel with different programmes: k = comedy | cartoon | drama | hotel ---------- */
const _e108screen=(k,T)=>{
  if(k==='cartoon')return `<rect x="-110" y="-80" width="220" height="160" fill="#FFE9A8"/><rect x="-110" y="20" width="220" height="60" fill="#F2B6A0"/><rect x="-70" y="-62" width="140" height="34" rx="6" fill="#fff" ${st(C.navy,3)}/><text x="0" y="-38" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="15" fill="${C.red}">RESTAURANT</text>${_e108cat(-32,30,.46,'#E39B4B',T)}<ellipse cx="62" cy="40" rx="26" ry="8" fill="#fff" ${st(C.navy,3)}/><path d="M42 40 L46 14 H78 L82 40Z" fill="#F4C6D2" ${st(C.navy,3)}/>`;
  if(k==='drama')return `<rect x="-110" y="-80" width="220" height="160" fill="#CFE0EA"/><rect x="-110" y="40" width="220" height="40" fill="#9BB3C1"/><rect x="-70" y="-70" width="76" height="110" fill="#fff" ${st(C.navy,3)}/><rect x="-40" y="-60" width="14" height="40" fill="${C.red}"/><rect x="-53" y="-47" width="40" height="14" fill="${C.red}"/>${_e108p(40,-10,.46,{c:'#fff',hair:'long',hc:'#2A1D18'},T)}${_e108p(86,0,.4,{c:'#fff',hair:'short',hc:'#222'},T)}`;
  if(k==='hotel')return `<rect x="-110" y="-80" width="220" height="160" fill="#F4E5C2"/><rect x="-110" y="40" width="220" height="40" fill="#C79468"/><rect x="-90" y="-70" width="70" height="20" rx="4" fill="${C.red}" ${st(C.navy,3)}/><text x="-55" y="-55" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="14" fill="#fff">HOTEL</text><g transform="translate(40,30) rotate(${f(Math.sin(T*3)*3-6)})"><rect x="-26" y="-92" width="52" height="116" rx="4" fill="#B07A4A" ${st(C.navy,4)}/><circle cx="14" cy="-30" r="5" fill="${C.gold}"/></g>${_e108p(-30,16,.4,{c:'#4DA3D8',hair:'short',hc:'#222'},T)}`;
  return `<rect x="-110" y="-80" width="220" height="160" fill="#BFE4F4"/><circle cx="50" cy="-40" r="22" fill="#F6CE4B"/><path d="M-110 30 Q-40 -20 30 30 T110 20 V80 H-110Z" fill="#78B86A"/>${_e108p(-30,24,.4,{c:'#D96C8B',hair:'long',hc:'#3A2A22'},T)}`};
P.e108_tv=(o,T,k)=>`<g>${_e108tvbox(_e108screen(o.k||'comedy',T),'e108_ctv'+(o.k||'c'),T)}</g>`;
/* family on a sofa seen from behind watching the TV */
P.e108_tvfam=(o,T,k)=>{const n=o.n||4,cols=['#D96C8B','#4F7A5A','#F2994A','#6A8FA8','#8E6BB5'],hcs=['#3A2A22','#222','#8B5E3C','#BDC3C7','#2A1D18'];let b='';for(let i=0;i<n;i++)b+=_e108back(-n*21+21+i*42+0,86,.32,cols[i%5],hcs[i%5],i%2?'':'bun');
  return `<g><g transform="translate(0,-30) scale(.78)">${P.e108_tv({k:o.k||'comedy'},T,k)}</g>${b}<rect x="-110" y="104" width="220" height="42" rx="16" fill="#8A5A6E" ${st()}/><rect x="-124" y="84" width="30" height="62" rx="12" fill="#8A5A6E" ${st()}/><rect x="94" y="84" width="30" height="62" rx="12" fill="#8A5A6E" ${st()}/></g>`};

/* ---------- drawing a picture: paper, pencil, a tree being sketched ---------- */
P.e108_draw=(o,T,k)=>{const p=clamp(k/2.4,0,1),px=-30+Math.sin(T*3)*14,py=20+Math.cos(T*4)*6;
  return `<g><ellipse cx="0" cy="112" rx="120" ry="12" fill="#000" opacity=".12"/><rect x="-112" y="-96" width="224" height="196" rx="8" fill="${C.white}" ${st()}/><path d="M-112 -70 H112" stroke="#D5DDE3" stroke-width="2"/><g opacity="${f(clamp(p*3,0,1))}"><rect x="-8" y="-4" width="16" height="64" fill="#8A5A34" ${st(C.navy,4)}/></g><g opacity="${f(clamp(p*3-1,0,1))}"><circle cx="0" cy="-32" r="48" fill="#6DB574" ${st(C.navy,4)}/><circle cx="-18" cy="-46" r="12" fill="#fff" opacity=".2"/></g><g opacity="${f(clamp(p*3-2,0,1))}"><circle cx="-76" cy="-62" r="16" fill="#F6CE4B" ${st(C.navy,4)}/><path d="M-100 60 H100" ${st(C.moss,5)}/></g><g transform="translate(${f(px+60)},${f(py-10)}) rotate(40)"><rect x="-8" y="-70" width="16" height="96" fill="#F2B84B" ${st()}/><polygon points="-8,26 8,26 0,48" fill="#E8C9A0" ${st(C.navy,4)}/><polygon points="-3,40 3,40 0,48" fill="${C.navy}"/><rect x="-8" y="-70" width="16" height="14" fill="#D96C8B" ${st()}/></g></g>`};

/* ---------- kitchen wall covered with a child's scribbles ---------- */
P.e108_wallscrib=(o,T,k)=>{const col=['#E0584B','#4DA3D8','#F6CE4B','#4F9A5A'];let s='';for(let i=0;i<6;i++){const x=-92+i*34,y=-40+(i%3)*30;s+=`<path d="M${x} ${y} q16 -34 30 0 t28 6 q-20 22 -44 20 q-18 -14 ${i*3} -26" fill="none" stroke="${col[i%4]}" stroke-width="6" stroke-linecap="round"/>`}
  return `<g><clipPath id="e108_cws"><rect x="-120" y="-100" width="240" height="190" rx="10"/></clipPath><rect x="-120" y="-100" width="240" height="190" rx="10" fill="#F4E5C2" ${st()}/><g clip-path="url(#e108_cws)">${[0,1,2].map(i=>`<rect x="-120" y="${54+i*0}" width="240" height="40" fill="#8FC1D4"/>`)[0]}${s}<rect x="-120" y="52" width="240" height="6" fill="${C.cream}" ${st(C.navy,3)}/>${_e108p(70,40,.36,{c:'#F2994A',hair:'bun',hc:'#2A1D18'},T)}<g transform="translate(${f(30+Math.sin(T*4)*8)},${f(24)}) rotate(-50)"><rect x="-5" y="-22" width="10" height="44" rx="3" fill="#E0584B" ${st(C.navy,3)}/><polygon points="-5,22 5,22 0,34" fill="#E0584B" ${st(C.navy,3)}/></g></g></g>`};

/* ---------- phone: a message from a colleague (text is the thing) ---------- */
P.e108_smsg=(o,T,k)=>{const a=ease(k/.5),b=ease((k-.7)/.5);
  return `<g><rect x="-62" y="-122" width="124" height="244" rx="24" fill="#2B3A4A" ${st()}/><rect x="-52" y="-104" width="104" height="208" rx="8" fill="#EAF3F8"/><rect x="-52" y="-104" width="104" height="30" rx="8" fill="${C.moss}"/><text x="0" y="-84" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="16" fill="#fff">Sara</text><g opacity="${f(a)}"><rect x="-46" y="-62" width="84" height="48" rx="12" fill="#fff" ${st(C.navy,3)}/><text x="-4" y="-42" text-anchor="middle" font-family="Fraunces" font-weight="700" font-size="12" fill="${C.navy}">Drawing</text><text x="-4" y="-26" text-anchor="middle" font-family="Fraunces" font-weight="700" font-size="12" fill="${C.navy}">competition!</text></g><g opacity="${f(b)}"><rect x="-38" y="-2" width="84" height="40" rx="12" fill="#F6CE4B" ${st(C.navy,3)}/><text x="4" y="22" text-anchor="middle" font-family="Fraunces" font-weight="700" font-size="14" fill="${C.navy}">Enter!</text></g><circle cx="${f(-8+Math.sin(T*5)*0)}" cy="78" r="6" fill="${C.moss}" opacity="${f(.5+.5*Math.sin(T*5))}"/></g>`};

/* ---------- competition poster: k = draw | photo ---------- */
P.e108_poster=(o,T,k)=>{const ph=o.k==='photo',pul=1+.015*Math.sin(T*3);
  return `<g transform="scale(${f(pul)})"><rect x="-96" y="-124" width="192" height="248" rx="10" fill="#FFF7DE" ${st()}/><rect x="-80" y="-108" width="160" height="34" rx="6" fill="${ph?C.moss:C.red}"/><text x="0" y="-84" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="22" fill="#fff" letter-spacing="2">${ph?'PHOTO':'DRAWING'}</text><text x="0" y="-48" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="19" fill="${C.navy}">COMPETITION</text>${ph?`<rect x="-62" y="-30" width="124" height="96" rx="6" fill="#BFE4F4" ${st(C.navy,4)}/><polygon points="-62,66 -22,6 6,40 26,16 62,66" fill="#78A88A" ${st(C.navy,3)}/><circle cx="34" cy="-8" r="12" fill="#F6CE4B"/><g transform="translate(0,92)"><rect x="-22" y="-14" width="44" height="28" rx="6" fill="#4A5A68" ${st(C.navy,3)}/><circle cx="0" cy="0" r="9" fill="#BFE4F4" ${st(C.navy,3)}/></g>`:`<g transform="translate(0,12)"><rect x="-62" y="-42" width="124" height="96" rx="6" fill="#fff" ${st(C.navy,4)}/><path d="M-50 40 Q-20 -6 6 22 T52 -6" fill="none" ${st(C.blue,5)}/><circle cx="-34" cy="-18" r="10" fill="#F6CE4B"/></g><g transform="translate(40,98) rotate(35)"><rect x="-5" y="-26" width="10" height="46" fill="#F2B84B" ${st(C.navy,3)}/><polygon points="-5,20 5,20 0,32" fill="#E8C9A0" ${st(C.navy,3)}/></g>`}</g>`};

/* ---------- grandmother's garden: old tree, little table with tea, cat asleep (opt cat) ---------- */
P.e108_garden=(o,T,k)=>{const sw=Math.sin(T*1.1)*1.5;
  const cat=o.cat?`${_e108cat(-66,86,.38,'#E39B4B',T)}`:'';
  return _e108pan('e108_cgd',`<rect x="-140" y="-110" width="280" height="240" fill="#BFE4F4"/>${_e108sun(94,-66,20,T)}${_e108hill(34,7,50,1,'#8CCB7A')}${_e108hill(62,6,40,2,'#6DB574')}<g transform="translate(${-30+sw},0)"><path d="M-14 70 L-10 -20 Q-12 -40 -26 -50 L-14 -48 L-4 -34 L0 -62 L10 -34 L26 -50 L22 -34 Q14 -22 18 -8 L22 70Z" fill="#9A6A3C" ${st(C.navy,4)}/><circle cx="0" cy="-70" r="56" fill="#5CA86A" ${st(C.navy,4)}/><circle cx="-42" cy="-46" r="34" fill="#4F9A5A" ${st(C.navy,4)}/><circle cx="44" cy="-46" r="36" fill="#6DB574" ${st(C.navy,4)}/><circle cx="-14" cy="-90" r="12" fill="#fff" opacity=".2"/></g><g transform="translate(76,64)"><ellipse cx="0" cy="30" rx="34" ry="8" fill="#000" opacity=".15"/><ellipse cx="0" cy="-8" rx="32" ry="9" fill="#C28B56" ${st(C.navy,4)}/><rect x="-4" y="-4" width="8" height="30" fill="#9A6A3C" ${st(C.navy,3)}/><rect x="-22" y="22" width="44" height="7" rx="3" fill="#9A6A3C" ${st(C.navy,3)}/><g transform="translate(0,-14)"><path d="M-12 0 L12 0 L9 -16 L-9 -16Z" fill="#fff" ${st(C.navy,3)}/><path d="M12 -12 q9 0 0 8" fill="none" ${st(C.navy,3)}/></g></g>${cat}`)};

/* ---------- a block of flats ---------- */
P.e108_flat=(o,T,k)=>{let w='';for(let r=0;r<4;r++)for(let c=0;c<3;c++){const lit=((r*3+c)*7)%5===0;w+=`<rect x="${-62+c*42}" y="${-86+r*44}" width="28" height="30" rx="3" fill="${lit?'#FFE08A':'#BFE4F4'}" ${st(C.navy,3.5)}/>`}
  return `<g><ellipse cx="0" cy="104" rx="110" ry="10" fill="#000" opacity=".13"/><rect x="-86" y="-110" width="172" height="214" rx="6" fill="#C9A38A" ${st()}/><rect x="-96" y="-122" width="192" height="18" rx="5" fill="#8C6B5A" ${st()}/>${w}<rect x="-18" y="62" width="36" height="42" rx="3" fill="#7A5A44" ${st(C.navy,4)}/></g>`};

/* ---------- remembering: a person with a thought cloud holding a tree and a table ---------- */
P.e108_memory=(o,T,k)=>{const bob=Math.sin(T*2)*3;
  return `<g>${_e108p(-58,38,.82,{c:'#E2B653',hair:'bun',hc:'#2A1D18'},T)}<g transform="translate(40,${f(-58+bob)})"><circle cx="-56" cy="52" r="7" fill="#fff" ${st(C.navy,3)}/><circle cx="-42" cy="30" r="11" fill="#fff" ${st(C.navy,3)}/><path d="M-60 -40 Q-80 -62 -50 -76 Q-40 -102 -4 -92 Q26 -112 52 -86 Q88 -82 78 -48 Q96 -16 62 -6 Q40 20 8 6 Q-24 24 -50 2 Q-84 -4 -60 -40Z" fill="#fff" ${st()}/>${_e108tree(-14,-22,.5)}<ellipse cx="34" cy="-18" rx="18" ry="5" fill="#C28B56" ${st(C.navy,3)}/><rect x="31" y="-15" width="6" height="18" fill="#9A6A3C" ${st(C.navy,2.5)}/></g></g>`};

/* ---------- a phone call to grandmother ---------- */
P.e108_call=(o,T,k)=>{let w='';for(let i=0;i<3;i++){const ph=(T*.9+i/3)%1;w+=`<path d="M${f(-38+i*0)} ${f(-40)} a${20+i*14} ${20+i*14} 0 0 1 0 ${(20+i*14)*2}" transform="translate(${f(i*-4)},${-i*14}) scale(1)" fill="none" ${st('#7FB6D6',5)} opacity="${f(1-ph)}" style="display:none"/>`}
  const ring=Math.sin(T*18)*4;
  return `<g>${_e108p(-96,34,.62,{c:'#E2B653',hair:'bun',hc:'#2A1D18'},T,`<g transform="translate(-52,-38) rotate(${f(-18+ring)})"><rect x="-10" y="-30" width="20" height="60" rx="9" fill="#2B3A4A" ${st(C.navy,4)}/></g>`)}${_e108p(96,34,.62,{c:'#B07AA1',hair:'bun',hc:'#D5D8DB'},T,`<g transform="translate(52,-38) rotate(${f(18-ring)})"><rect x="-10" y="-30" width="20" height="60" rx="9" fill="#2B3A4A" ${st(C.navy,4)}/></g>`)}<path d="M-30 -30 Q0 -64 30 -30" fill="none" ${st('#7FB6D6',5)} stroke-dasharray="2 10" stroke-linecap="round"/><g transform="translate(0,${f(-26+Math.sin(T*3)*3)}) scale(.5)">${P.heart({},T)}</g></g>`};

/* ---------- late-night desk: lamp, drawing, dark window with moon ---------- */
P.e108_nightdesk=(o,T,k)=>{const fl=.9+.1*Math.sin(T*2);
  return _e108pan('e108_cnd',`<rect x="-140" y="-110" width="280" height="240" fill="#24365C"/><rect x="-100" y="-86" width="86" height="96" rx="6" fill="#142A52" ${st(C.navy,5)}/><path d="M-70 -66 A16 16 0 1 0 -52 -38 A12 12 0 0 1 -70 -66Z" fill="#F7E7A8"/><circle cx="-34" cy="-70" r="2" fill="#fff"/><circle cx="-84" cy="-26" r="2" fill="#fff"/><polygon points="20,-14 130,-14 160,130 -10,130" fill="#FFE9A8" opacity="${f(.3*fl)}"/><rect x="-140" y="48" width="280" height="90" fill="#8A5A34"/><rect x="-140" y="48" width="280" height="8" fill="#6D4528"/><g transform="translate(90,48)"><path d="M0 0 L-6 -50 L26 -92" fill="none" ${st(C.navy,6)}/><path d="M12 -96 L48 -78 L36 -52 L0 -66Z" fill="#E0584B" ${st(C.navy,4)}/><rect x="-26" y="-4" width="44" height="10" rx="4" fill="#4A5A68" ${st(C.navy,4)}/></g><g transform="translate(-6,52) rotate(-4)"><rect x="-56" y="-14" width="112" height="70" rx="3" fill="#fff" ${st(C.navy,4)}/><path d="M-40 40 Q-16 -4 6 22 T44 -4" fill="none" ${st(C.blue,4)}/></g><g transform="translate(-52,40)"><rect x="-7" y="-26" width="14" height="52" rx="4" fill="#F2B84B" ${st(C.navy,3)}/></g>`)};

/* ---------- rosette: second prize, with an email envelope ---------- */
P.e108_prize2=(o,T,k)=>{const s=1+.04*Math.sin(T*3),op=ease(k/.6);
  return `<g><g transform="translate(-52,18)"><rect x="-76" y="-52" width="152" height="104" rx="10" fill="${C.white}" ${st()}/><path d="M-76 -48 L0 14 L76 -48" fill="none" ${st(C.navy,5)}/><rect x="-46" y="-10" width="92" height="8" rx="3" fill="#D5DDE3"/><rect x="-46" y="8" width="64" height="8" rx="3" fill="#D5DDE3"/></g><g transform="translate(78,-38) scale(${f(s*op)})"><path d="M-26 30 L-38 96 L-14 82 L0 98 L0 34Z" fill="${C.red}" ${st(C.navy,4)}/><path d="M26 30 L38 96 L14 82 L0 98 L0 34Z" fill="#C0392B" ${st(C.navy,4)}/><circle cx="0" cy="0" r="46" fill="#4DA3D8" ${st()}/><circle cx="0" cy="0" r="34" fill="#9AC9E8" ${st(C.navy,4)}/><text x="0" y="14" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="40" fill="${C.navy}">2</text></g></g>`};

/* ---------- art-centre wall: framed garden drawing, people from behind ---------- */
P.e108_gallery=(o,T,k)=>{const pic=`<rect x="-52" y="-62" width="104" height="82" fill="#BFE4F4"/><path d="M-52 4 Q-10 -12 52 6 V20 H-52Z" fill="#78B86A"/><circle cx="-12" cy="-22" r="22" fill="#5CA86A" ${st(C.navy,2.5)}/><rect x="-15" y="-4" width="6" height="20" fill="#8A5A34"/><circle cx="34" cy="-42" r="9" fill="#F6CE4B"/>`;
  return _e108pan('e108_cgl',`<rect x="-140" y="-110" width="280" height="240" fill="#F1E7D3"/><rect x="-140" y="72" width="280" height="60" fill="#B99A78"/><g transform="translate(0,-26)"><rect x="-62" y="-72" width="124" height="102" rx="3" fill="#8A5A34" ${st()}/>${pic}</g><g transform="translate(-112,-36)"><rect x="-22" y="-34" width="44" height="58" fill="#fff" ${st(C.navy,3)}/></g><g transform="translate(112,-36)"><rect x="-22" y="-34" width="44" height="58" fill="#fff" ${st(C.navy,3)}/></g>${_e108back(-18,34,.45,'#E2B653','#2A1D18','bun')}${_e108back(38,50,.4,'#B07AA1','#D5D8DB','bun')}<path d="M4 98 L16 104" ${st('#D79B70',7)}/>`)};

/* ---------- box of pencils and colours + a small award plaque ---------- */
P.e108_pencilbox=(o,T,k)=>{const cols=['#E0584B','#F2994A','#F6CE4B','#4F9A5A','#4DA3D8','#8E6BB5','#D96C8B','#7A5A44'];let pc='';cols.forEach((c,i)=>{pc+=`<g transform="translate(${-70+i*20},4) rotate(${(i-3.5)*3})"><rect x="-7" y="-70" width="14" height="86" fill="${c}" ${st(C.navy,3)}/><polygon points="-7,-70 7,-70 0,-88" fill="#E8C9A0" ${st(C.navy,3)}/><polygon points="-3,-80 3,-80 0,-88" fill="${c}"/></g>`});
  return `<g><g transform="translate(-30,10)">${pc}<path d="M-100 8 L100 8 L90 76 L-90 76Z" fill="#C79468" ${st()}/><path d="M-100 8 L100 8" ${st(C.navy,5)}/><line x1="-60" y1="30" x2="60" y2="30" stroke="#8A5A34" stroke-width="3"/></g><g transform="translate(74,50) rotate(-6)"><rect x="-44" y="-36" width="88" height="62" rx="6" fill="#F0C64A" ${st()}/><rect x="-36" y="-28" width="72" height="46" rx="3" fill="none" ${st('#C9971F',3)}/><text x="0" y="2" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="19" fill="${C.navy}">MAYA</text><path d="M-6 8 h12" ${st('#C9971F',3)}/><rect x="-24" y="26" width="48" height="10" rx="3" fill="#7A5A44" ${st()}/></g></g>`};

/* ---------- sitting-room shelf with the small award ---------- */
P.e108_shelf=(o,T,k)=>{
  return _e108pan('e108_csf',`<rect x="-140" y="-110" width="280" height="240" fill="#F1E7D3"/><rect x="-140" y="86" width="280" height="50" fill="#B99A78"/><rect x="-120" y="30" width="240" height="12" fill="#8A5A34" ${st(C.navy,4)}/><g transform="translate(-4,6) rotate(-4)"><rect x="-32" y="-26" width="64" height="48" rx="5" fill="#F0C64A" ${st()}/><text x="0" y="0" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="15" fill="${C.navy}">MAYA</text><rect x="-18" y="22" width="36" height="8" rx="3" fill="#7A5A44" ${st(C.navy,3)}/></g><g transform="translate(-86,30)"><path d="M-18 0 L18 0 L12 -34 L-12 -34Z" fill="#C0504D" ${st(C.navy,4)}/><path d="M0 -34 Q-18 -64 -24 -50 M0 -34 Q0 -76 8 -64 M0 -34 Q20 -60 28 -48" fill="none" ${st(C.moss,6)}/></g><g transform="translate(86,30)"><rect x="-22" y="-44" width="14" height="44" fill="#4DA3D8" ${st(C.navy,3)}/><rect x="-6" y="-52" width="14" height="52" fill="#E0584B" ${st(C.navy,3)}/><rect x="10" y="-40" width="14" height="40" fill="#4F9A5A" ${st(C.navy,3)}/></g><rect x="-110" y="-90" width="70" height="50" fill="#BFE4F4" ${st(C.navy,4)}/><line x1="-75" y1="-90" x2="-75" y2="-40" ${st(C.navy,3)}/>`)};

/* ---------- a drawing of an old market: stalls and lots of people ---------- */
P.e108_oldmarket=(o,T,k)=>{let pp='';const cols=['#E2B653','#4DA3D8','#D96C8B','#4F7A5A','#F2994A','#8E6BB5','#C0504D'];for(let i=0;i<16;i++)pp+=_e108p(-122+(i%8)*35+(i>7?17:0),(i>7?78:56),.19,{c:cols[i%7],hair:['bun','short','long'][i%3],hc:['#2A1D18','#222','#8B5E3C'][i%3],ph:i},T);
  const stall=(x,c)=>`<g transform="translate(${x},0)"><rect x="-30" y="-8" width="60" height="46" fill="#C79468" ${st(C.navy,3.5)}/><path d="M-36 -8 L36 -8 L30 -34 L-30 -34Z" fill="${c}" ${st(C.navy,3.5)}/><path d="M-36 -8 q9 10 18 0 q9 10 18 0 q9 10 18 0 q9 10 18 0" fill="${c}" ${st(C.navy,3)}/><circle cx="-12" cy="14" r="7" fill="#E0584B"/><circle cx="6" cy="14" r="7" fill="#F6CE4B"/><circle cx="22" cy="14" r="7" fill="#4F9A5A"/></g>`;
  return `<g><rect x="-142" y="-106" width="284" height="226" rx="10" fill="#8A5A34" ${st()}/><g transform="scale(.94)">${_e108pan('e108_com',`<rect x="-140" y="-110" width="280" height="230" fill="#FBE9C3"/><rect x="-140" y="-110" width="280" height="40" fill="#BFE4F4"/><rect x="-140" y="40" width="280" height="90" fill="#E8D2A6"/>${stall(-88,'#E0584B')}${stall(0,'#4DA3D8')}${stall(88,'#F2994A')}${pp}`,{w:280,h:230,r:6})}</g></g>`};

/* ---------- a coach with a cap, whistle and clipboard ---------- */
P.e108_coach=(o,T,k)=>`<g><ellipse cx="0" cy="112" rx="84" ry="10" fill="#000" opacity=".13"/>${_e108p(0,0,1.15,{c:'#C0504D',hair:'short',hc:'#BDC3C7'},T,`${_e108cap('#2B3A4A')}<path d="M0 -4 L0 40" ${st(C.white,3)}/><circle cx="0" cy="44" r="7" fill="${C.gold}" ${st(C.navy,3)}/><rect x="-2" y="36" width="22" height="9" rx="4" fill="${C.gold}" ${st(C.navy,3)}/><g transform="translate(46,56) rotate(8)"><rect x="-22" y="-30" width="44" height="58" rx="5" fill="#fff" ${st()}/><rect x="-10" y="-36" width="20" height="10" rx="3" fill="#7E8C99" ${st(C.navy,3)}/><path d="M-12 -10 h24 M-12 2 h24 M-12 14 h14" ${st(C.navy,3)}/></g>`)}</g>`;

/* ---------- running from one end of the hall to the other ---------- */
P.e108_sprint=(o,T,k)=>{const x=-80+(Math.abs(((T*.45)%2)-1))*160;
  return _e108pan('e108_csp',`<rect x="-140" y="-110" width="280" height="230" fill="#E8C48A"/><rect x="-140" y="-110" width="280" height="50" fill="#C9D5DC"/><line x1="-140" y1="-60" x2="140" y2="-60" ${st(C.navy,3)}/><line x1="-110" y1="-30" x2="-110" y2="110" stroke="#fff" stroke-width="6"/><line x1="110" y1="-30" x2="110" y2="110" stroke="#fff" stroke-width="6"/><path d="M-96 76 H96" fill="none" ${st(C.red,5)} stroke-dasharray="12 10"/><polygon points="96,76 80,66 80,86" fill="${C.red}"/><polygon points="-96,76 -80,66 -80,86" fill="${C.red}"/>${[-110,110].map(a=>`<polygon points="${a-10},40 ${a+10},40 ${a},12" fill="#F2994A" ${st(C.navy,3)}/>`).join('')}<g transform="translate(${f(x)},12) scale(${f(Math.abs(((T*.45)%2)-1)>.5?1:1)})"><ellipse cx="0" cy="62" rx="26" ry="5" fill="#000" opacity=".15"/>${_e108p(0,0,.46,{c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g>`)};

/* ---------- scoreboard: lost by two points ---------- */
P.e108_score=(o,T,k)=>{const bl=.6+.4*Math.abs(Math.sin(T*2));
  return `<g><rect x="-6" y="40" width="12" height="80" fill="#7E8C99" ${st()}/><rect x="-118" y="-92" width="236" height="140" rx="12" fill="#2B3A4A" ${st()}/><rect x="-104" y="-78" width="208" height="112" rx="6" fill="#142A52"/><text x="0" y="-26" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" fill="#FFD36B" letter-spacing="3">LOST BY</text><text x="-56" y="26" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="62" fill="#FF6B5B" opacity="${f(bl)}">2</text><text x="30" y="20" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="#FFD36B">POINTS</text></g>`};

/* ---------- a coach sitting next to a sad player on a bench, hand on shoulder ---------- */
P.e108_sitnext=(o,T,k)=>{const h=ease(k/.8);
  return `<g><ellipse cx="0" cy="118" rx="140" ry="10" fill="#000" opacity=".13"/>${_e108p(-62,6,.7,{c:'#4DA3D8',hair:'short',hc:'#222'},T)}${_e108p(66,-4,.78,{c:'#C0504D',hair:'short',hc:'#BDC3C7'},T,_e108cap('#2B3A4A'))}<path d="M-12 50 Q14 30 40 44" fill="none" ${st('#C0504D',16)} opacity="${f(h)}"/><circle cx="-26" cy="40" r="9" fill="#E3AE82" ${st(C.navy,3)} opacity="${f(h)}"/><rect x="-150" y="88" width="300" height="16" rx="6" fill="#B07A4A" ${st()}/><rect x="-130" y="104" width="12" height="22" fill="#8A5A34" ${st(C.navy,3)}/><rect x="118" y="104" width="12" height="22" fill="#8A5A34" ${st(C.navy,3)}/></g>`};

/* ---------- indoor climbing wall: climber at height h (0..1), teacher below, optional "3 m" marker ---------- */
P.e108_climb=(o,T,k)=>{const h=o.h==null?.5:o.h,top=!!o.top,cy=78-h*165,hc=['#E0584B','#F6CE4B','#4DA3D8','#4F9A5A','#8E6BB5','#F2994A'];let ho='';for(let i=0;i<26;i++)ho+=`<circle cx="${f(-90+_e108rnd(i,3)*180)}" cy="${f(-96+_e108rnd(i,4)*190)}" r="${f(6+_e108rnd(i,5)*3)}" fill="${hc[i%6]}" ${st(C.navy,2.5)}/>`;
  const sway=Math.sin(T*2)*2;
  return _e108pan('e108_ccl',`<rect x="-140" y="-110" width="280" height="240" fill="#D9E1E6"/><rect x="-100" y="-110" width="200" height="240" fill="#A9B7C2" ${st(C.navy,4)}/>${ho}${top?`<path d="M-100 -106 H100" ${st(C.red,5)}/>`:''}<g transform="translate(90,36)">${_e108p(0,0,.34,{c:'#4F7A5A',hair:'short',hc:'#222'},T)}</g><path d="M86 22 Q40 ${f(cy+30)} ${f(-14+sway)} ${f(cy+14)}" fill="none" ${st('#F6CE4B',3.5)}/><g transform="translate(${f(-14+sway)},${f(cy)}) scale(1.1)"><path d="M-8 12 L-16 40 M8 12 L16 36" ${st(C.navy,9)} fill="none"/><path d="M-8 12 L-16 40 M8 12 L16 36" ${st('#3F5A73',5)} fill="none"/><path d="M-12 -12 L-20 -38 M12 -12 L22 -34" ${st(C.navy,8)} fill="none"/><path d="M-12 -12 L-20 -38 M12 -12 L22 -34" ${st('#E3AE82',4.5)} fill="none"/><rect x="-14" y="-16" width="28" height="34" rx="9" fill="#E2B653" ${st()}/><rect x="-14" y="6" width="28" height="7" fill="#C0504D" ${st(C.navy,2.5)}/><circle cx="0" cy="-28" r="12" fill="#E3AE82" ${st(C.navy,3.5)}/><path d="M-12 -30 Q-12 -42 0 -42 Q12 -42 12 -30 Q0 -36 -12 -30Z" fill="#2A1D18" ${st(C.navy,2.5)}/><circle cx="0" cy="-45" r="6" fill="#2A1D18" ${st(C.navy,2.5)}/></g>${o.m?`<g transform="translate(-122,0)"><line x1="0" y1="${f(cy)}" x2="0" y2="70" ${st(C.red,4)}/><rect x="-8" y="${f((cy+70)/2-10)}" width="40" height="20" rx="4" fill="${C.cream}" ${st(C.navy,3)}/><text x="12" y="${f((cy+70)/2+5)}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="13" fill="${C.navy}">3 m</text></g>`:''}`)};

/* ---------- camp by a mountain lake: tents, fire (opt big) ---------- */
P.e108_lakecamp=(o,T,k)=>{const tent=(x,y,s,c)=>`<g transform="translate(${x},${y}) scale(${s})"><polygon points="-62,44 0,-56 62,44" fill="${c}" ${st(C.navy,6)}/><path d="M0 -22 L-20 44 L20 44Z" fill="#3B2A24" ${st(C.navy,5)}/></g>`;
  return _e108pan('e108_clc',`<rect x="-140" y="-110" width="280" height="240" fill="#BFE4F4"/><polygon points="-150,10 -70,-96 10,10" fill="#8FA3B0" ${st()}/><polygon points="-96,-58 -70,-96 -44,-58 -58,-64 -70,-52 -82,-64" fill="#fff" ${st(C.navy,3)}/><polygon points="-30,10 60,-70 150,10" fill="#A9BAC4" ${st()}/>${_e108sun(104,-70,18,T)}<rect x="-140" y="0" width="280" height="60" fill="#5BB3E0"/><path d="M-100 22 q12 -6 24 0 t24 0 M40 36 q12 -6 24 0 t24 0" fill="none" stroke="#fff" stroke-width="3" opacity=".7"/><path d="M-140 52 Q-60 40 20 56 T140 50 V140 H-140Z" fill="#7DBB6C" ${st(C.navy,4)}/>${tent(-76,64,.62,C.orange)}${tent(2,72,.7,'#4DA3D8')}${tent(84,66,.6,C.red)}<g transform="translate(-38,96) scale(.3)">${P.fire({},T)}</g>${_e108tree(-122,64,.55)}${_e108tree(122,60,.55)}`)};

/* ---------- view from the mountain top: lake, forest, tiny camp below; two people from behind ---------- */
P.e108_summit=(o,T,k)=>{
  return _e108pan('e108_csm',`<rect x="-140" y="-110" width="280" height="240" fill="#BFE4F4"/>${_e108sun(96,-76,18,T)}<path d="M-140 -20 Q-90 -44 -50 -22 Q0 -50 60 -26 Q110 -42 140 -20 V140 H-140Z" fill="#7DA08C" ${st(C.navy,4)}/><ellipse cx="10" cy="22" rx="86" ry="22" fill="#5BB3E0" ${st(C.navy,4)}/><path d="M-30 18 q10 -4 20 0 t20 0" fill="none" stroke="#fff" stroke-width="3" opacity=".7"/>${[-120,-104,-90,-70,80,100,116].map((x,i)=>_e108tree(x,8+(i%3)*10,.22,'#4F9A5A')).join('')}<polygon points="-6,-4 4,-18 14,-4" fill="${C.orange}" ${st(C.navy,2.5)}/><polygon points="22,0 31,-12 40,0" fill="#4DA3D8" ${st(C.navy,2.5)}/><path d="M-140 140 L-140 74 Q-60 56 0 68 Q80 56 140 76 V140Z" fill="#8F8579" ${st(C.navy,4)}/>${_e108back(-34,66,.5,'#E2B653','#2A1D18','bun')}${_e108back(28,70,.5,'#4F7A5A','#2A1D18','long')}`)};

/* ---------- rock with a hand and a boot (climbing with hands and feet) ---------- */
P.e108_rockhands=(o,T,k)=>{const a=ease(k/.5),m=Math.sin(T*3)*3;
  return `<g><path d="M-120 100 L-96 -60 Q-60 -108 -10 -96 Q50 -112 96 -70 L124 100Z" fill="#8F8579" ${st()}/><path d="M-60 -60 L-40 -20 M40 -66 L60 -30 M-70 30 L-30 54" fill="none" stroke="#6D655B" stroke-width="5" stroke-linecap="round"/><g transform="translate(-30,${f(-24+m)})"><path d="M-18 30 L-22 -8 Q-22 -16 -16 -14 L-14 -4 L-14 -26 Q-14 -34 -8 -32 L-6 -8 L-4 -34 Q-4 -42 2 -40 L4 -8 L8 -30 Q10 -36 15 -34 L14 -4 L20 -16 Q24 -22 28 -17 L22 18 Q18 34 0 36Z" fill="#E3AE82" ${st(C.navy,4)}/></g><g transform="translate(52,${f(46-m)})"><path d="M-30 -22 L-8 -22 L-8 -4 L22 4 Q36 10 34 24 L-30 24Z" fill="#7A5A44" ${st()}/><path d="M-30 24 H34" ${st(C.navy,6)}/></g></g>`};

/* ---------- taking a photograph with a phone: viewfinder on a mountain view ---------- */
P.e108_phonecam=(o,T,k)=>{const fl=Math.max(0,1-((T*.6)%3)*8),z=1+.03*Math.sin(T*2);
  return `<g><rect x="-86" y="-126" width="172" height="252" rx="28" fill="#2B3A4A" ${st()}/><clipPath id="e108_cpc"><rect x="-74" y="-110" width="148" height="206" rx="10"/></clipPath><g clip-path="url(#e108_cpc)"><rect x="-74" y="-110" width="148" height="206" fill="#BFE4F4"/><g transform="scale(${f(z)})"><polygon points="-96,70 -30,-34 20,50 50,-4 100,70" fill="#8FA3B0" ${st(C.navy,3)}/><polygon points="-30,-34 -44,-12 -34,-18 -26,-8 -18,-20" fill="#fff"/><circle cx="40" cy="-60" r="16" fill="#F6CE4B"/><rect x="-80" y="48" width="160" height="60" fill="#78B86A" ${st(C.navy,3)}/></g></g><path d="M-52 -80 H-30 M-52 -80 V-58 M52 -80 H30 M52 -80 V-58 M-52 56 H-30 M-52 56 V34 M52 56 H30 M52 56 V34" fill="none" ${st(C.white,5)}/><circle cx="0" cy="112" r="9" fill="${C.white}" opacity=".9" ${st(C.navy,3)}/><rect x="-74" y="-110" width="148" height="206" rx="10" fill="#fff" opacity="${f(fl*.7)}"/></g>`};

/* ---------- a grandfather (grey hair) with an album of stamps ---------- */
P.e108_granpa=(o,T,k)=>`<g>${_e108p(0,-4,1.05,{c:'#7A8F5A',hair:'short',hc:'#D5D8DB'},T)}<g transform="translate(0,${f(82+Math.sin(T*2)*2)})"><rect x="-64" y="-26" width="128" height="62" rx="6" fill="#8E5A3C" ${st()}/><line x1="0" y1="-26" x2="0" y2="36" ${st(C.navy,4)}/><rect x="-52" y="-14" width="44" height="38" fill="#fff" ${st(C.navy,2.5)}/><rect x="8" y="-14" width="44" height="38" fill="#fff" ${st(C.navy,2.5)}/><rect x="-44" y="-8" width="14" height="14" fill="#E0584B"/><rect x="-26" y="-8" width="14" height="14" fill="#4DA3D8"/><rect x="16" y="-8" width="14" height="14" fill="#4F9A5A"/><rect x="34" y="-8" width="14" height="14" fill="#F6CE4B"/></g></g>`;

/* ---------- panel: an album page of stamps (a bird, a building, a silhouette, a flower) ---------- */
P.e108_stamps=(o,T,k)=>{const stamp=(x,y,c,inner,rot)=>`<g transform="translate(${x},${y}) rotate(${rot||0})"><rect x="-27" y="-33" width="54" height="66" fill="#fff" ${st(C.navy,3)} stroke-dasharray="4 3"/><rect x="-21" y="-27" width="42" height="54" fill="${c}"/>${inner}</g>`,
  bird=`<path d="M-12 8 Q-4 -14 12 -10 L18 -16 L16 -6 Q12 10 -12 8Z" fill="#fff" ${st(C.navy,2.5)}/>`,
  bld=`<rect x="-12" y="-12" width="24" height="26" fill="#fff" ${st(C.navy,2.5)}/><polygon points="-14,-12 0,-24 14,-12" fill="${C.red}" ${st(C.navy,2.5)}/>`,
  bust=`<circle cx="0" cy="-8" r="9" fill="#E3AE82" ${st(C.navy,2.5)}/><path d="M-16 20 Q-14 4 0 4 Q14 4 16 20Z" fill="#fff" ${st(C.navy,2.5)}/>`,
  flw=`<circle cx="0" cy="-4" r="6" fill="#F6CE4B" ${st(C.navy,2)}/>${[0,72,144,216,288].map(a=>`<circle cx="0" cy="-15" r="6" fill="#D96C8B" ${st(C.navy,2)} transform="rotate(${a} 0 -4)"/>`).join('')}<path d="M0 4 V22" ${st(C.moss,3)}/>`;
  return `<g><rect x="-132" y="-106" width="264" height="212" rx="12" fill="#8E5A3C" ${st()}/><rect x="-116" y="-92" width="232" height="184" rx="6" fill="#F4E5C2" ${st(C.navy,3)}/>${stamp(-78,-44,'#9AC9E8',bird,-3)}${stamp(0,-44,'#F7C96B',bld,2)}${stamp(78,-44,'#B7D8A4',bust,-2)}${stamp(-78,42,'#E7A9B4',flw,2)}${stamp(0,42,'#C6B6E0',bird,-2)}${stamp(78,42,'#F2B58A',bld,3)}</g>`};

/* ---------- a big box of stamps ---------- */
P.e108_stampbox=(o,T,k)=>{let s='';for(let i=0;i<14;i++){const x=-78+_e108rnd(i,1)*156,y=-70+_e108rnd(i,2)*40,r=-30+_e108rnd(i,3)*60,c=['#9AC9E8','#F7C96B','#B7D8A4','#E7A9B4','#F2B58A'][i%5];s+=`<g transform="translate(${f(x)},${f(y)}) rotate(${f(r)})"><rect x="-17" y="-21" width="34" height="42" fill="#fff" ${st(C.navy,2.5)}/><rect x="-12" y="-16" width="24" height="32" fill="${c}"/></g>`}
  return `<g><ellipse cx="0" cy="104" rx="130" ry="11" fill="#000" opacity=".13"/>${s}<path d="M-120 -24 L120 -24 L106 98 L-106 98Z" fill="#B97B4A" ${st()}/><rect x="-128" y="-40" width="256" height="24" rx="6" fill="#8E5A3C" ${st()}/><rect x="-40" y="10" width="80" height="34" rx="4" fill="${C.cream}" ${st(C.navy,3.5)}/><path d="M-26 22 h52 M-26 32 h34" ${st(C.navy,3)}/></g>`};

/* ---------- old cameras on a shelf ---------- */
P.e108_oldcams=(o,T,k)=>{const cam=(x,c,w)=>`<g transform="translate(${x},0)"><rect x="${-w/2}" y="-30" width="${w}" height="56" rx="6" fill="${c}" ${st()}/><rect x="${-w/2}" y="-14" width="${w}" height="26" fill="#D8D0C0" opacity=".9"/><circle cx="0" cy="-2" r="19" fill="#2B3A4A" ${st()}/><circle cx="0" cy="-2" r="10" fill="#7FB6D6" ${st(C.navy,3)}/><circle cx="-5" cy="-6" r="3" fill="#fff"/><rect x="${w/2-22}" y="-38" width="16" height="10" rx="3" fill="#7E8C99" ${st(C.navy,3)}/></g>`;
  return `<g><g transform="translate(-76,-10)">${cam(0,'#3A3A3A',74)}</g><g transform="translate(66,-4)">${cam(0,'#9B4A3A',64)}</g><g transform="translate(-6,64)">${cam(0,'#2F6B55',70)}</g><rect x="-132" y="96" width="264" height="14" rx="5" fill="#8A5A34" ${st()}/></g>`};

/* ---------- jar full of pencils ---------- */
P.e108_pencils=(o,T,k)=>{const cols=['#E0584B','#F2994A','#F6CE4B','#4F9A5A','#4DA3D8','#8E6BB5','#D96C8B'];let p='';for(let i=0;i<15;i++){const x=-48+i*6.8,h=70+_e108rnd(i,1)*44,r=(i-7)*3.2;p+=`<g transform="translate(${f(x)},40) rotate(${f(r)})"><rect x="-5" y="${-h}" width="10" height="${h}" fill="${cols[i%7]}" ${st(C.navy,2.5)}/><polygon points="-5,${-h} 5,${-h} 0,${-h-16}" fill="#E8C9A0" ${st(C.navy,2.5)}/></g>`}
  return `<g><ellipse cx="0" cy="110" rx="76" ry="9" fill="#000" opacity=".13"/>${p}<path d="M-62 -2 L62 -2 L56 106 Q0 118 -56 106Z" fill="#BFE4F4" opacity=".92" ${st()}/><path d="M-50 10 L-46 90" stroke="#fff" stroke-width="5" opacity=".6" stroke-linecap="round"/></g>`};

/* ---------- open novel with a little island rising from the page ---------- */
P.e108_bookisland=(o,T,k)=>{const w=Math.sin(T*2)*3;
  return `<g><ellipse cx="0" cy="108" rx="130" ry="11" fill="#000" opacity=".13"/><path d="M-124 40 L0 66 L124 40 L124 100 L0 124 L-124 100Z" fill="#fff" ${st()}/><path d="M0 66 V124" ${st(C.navy,4)}/><path d="M-124 40 Q-60 24 0 50 Q60 24 124 40" fill="none" ${st(C.navy,4)}/><path d="M-110 56 q50 -6 100 14 M10 70 q50 -20 100 -14" fill="none" stroke="#C8D2D8" stroke-width="3"/><path d="M-70 40 Q-30 -4 0 6 Q40 -10 72 40Z" fill="#5BB3E0" ${st(C.navy,3.5)}/><path d="M-36 26 Q-12 -14 20 -4 Q36 6 40 26Z" fill="#E8C48A" ${st(C.navy,3.5)}/><rect x="-6" y="-44" width="6" height="46" fill="#8A5A34" ${st(C.navy,3)} transform="rotate(-6 -3 2)"/><path d="M-3 -42 Q-28 -52 -40 -34 M-3 -42 Q-14 -66 8 -62 M-3 -42 Q22 -62 36 -40" fill="none" ${st(C.moss,7)}/><g transform="translate(24,${f(-6+w*.3)})"><rect x="-10" y="-14" width="22" height="20" fill="#fff" ${st(C.navy,3)}/><polygon points="-13,-14 1,-26 15,-14" fill="${C.red}" ${st(C.navy,3)}/></g><path d="M-90 28 q10 -6 20 0 t20 0 M44 28 q10 -6 20 0 t20 0" fill="none" ${st('#7FB6D6',3)} transform="translate(0,${f(w*.4)})"/></g>`};

/* ---------- reading a book under a lamp at night ---------- */
P.e108_reader=(o,T,k)=>{const fl=.85+.15*Math.sin(T*2);
  return _e108pan('e108_crd',`<rect x="-140" y="-110" width="280" height="240" fill="#24365C"/><path d="M60 -80 A22 22 0 1 0 82 -44 A17 17 0 0 1 60 -80Z" fill="#F7E7A8"/><polygon points="40,-30 128,-30 150,130 18,130" fill="#FFE9A8" opacity="${f(.28*fl)}"/><rect x="-140" y="62" width="280" height="80" fill="#6D4F8A"/><g transform="translate(90,70)"><path d="M0 0 L0 -50 Q4 -90 -22 -96" fill="none" ${st(C.navy,6)}/><path d="M-38 -108 L-6 -112 L-14 -84 L-44 -80Z" fill="#E0584B" ${st(C.navy,4)}/></g>${_e108p(-20,24,.55,{c:'#E2B653',hair:'bun',hc:'#2A1D18'},T)}<g transform="translate(-20,64)"><path d="M-40 -16 L0 -4 L40 -16 L40 22 L0 34 L-40 22Z" fill="#fff" ${st(C.navy,4)}/><path d="M0 -4 V34" ${st(C.navy,3)}/></g>`)};

/* ---------- a cat in a chef's hat holding a cake (faceless silhouette) ---------- */
P.e108_catchef=(o,T,k)=>{const b=Math.sin(T*2)*3;
  return `<g><ellipse cx="0" cy="112" rx="90" ry="9" fill="#000" opacity=".13"/>${_e108cat(-8,60,1.05,'#E39B4B',T)}<g transform="translate(-54,${f(8+b)})"><path d="M-26 -4 L-24 -26 Q-40 -34 -28 -50 Q-22 -62 -8 -54 Q2 -68 16 -54 Q32 -50 26 -34 L24 -4Z" fill="#fff" ${st()}/><rect x="-26" y="-6" width="50" height="10" fill="#fff" ${st(C.navy,4)}/></g><g transform="translate(58,76)"><ellipse cx="0" cy="22" rx="42" ry="9" fill="#fff" ${st()}/><path d="M-30 20 V-8 H30 V20Z" fill="#F4C6D2" ${st()}/><path d="M-30 -8 Q-20 -22 -10 -8 Q0 -22 10 -8 Q20 -22 30 -8Z" fill="#fff" ${st(C.navy,3.5)}/><circle cx="0" cy="-22" r="8" fill="${C.red}" ${st(C.navy,3)}/></g></g>`};

/* ---------- a cake falling toward a (faceless) visitor ---------- */
P.e108_cakefall=(o,T,k)=>{const fall=Math.min(1,k/1.2),y=-88+fall*58+Math.abs(Math.sin(T*6))*(fall>=1?4:0);
  return `<g>${_e108p(0,38,.9,{c:'#6A8FA8',hair:'short',hc:'#222'},T)}<g transform="translate(0,${f(y-6)})"><ellipse cx="0" cy="22" rx="52" ry="9" fill="#fff" ${st()}/><path d="M-44 20 V-10 H44 V20Z" fill="#F4C6D2" ${st()}/><path d="M-44 -10 Q-32 -26 -20 -10 Q-8 -26 4 -10 Q16 -26 28 -10 Q36 -22 44 -10Z" fill="#fff" ${st(C.navy,3.5)}/><circle cx="0" cy="-24" r="9" fill="${C.red}" ${st(C.navy,3)}/></g>${fall<1?`<path d="M-74 -70 V-40 M74 -70 V-40" ${st('#9AA7B0',4)}/>`:`<path d="M-56 12 q-10 14 -2 28 M56 12 q10 14 2 28" fill="none" ${st(C.white,6)}/>`}</g>`};

/* ---------- a small hotel with a door that has come off its hinge ---------- */
P.e108_hotel=(o,T,k)=>{const ang=Math.min(1,k/1)*18+Math.sin(T*3)*1.5;
  return `<g><ellipse cx="0" cy="106" rx="130" ry="10" fill="#000" opacity=".13"/><rect x="-104" y="-70" width="208" height="170" fill="#F4D9A8" ${st()}/><rect x="-116" y="-96" width="232" height="30" rx="6" fill="${C.red}" ${st()}/><text x="0" y="-74" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="#fff" letter-spacing="4">HOTEL</text>${[-72,-24,24,72].map(x=>`<rect x="${x-14}" y="-40" width="28" height="34" rx="3" fill="#BFE4F4" ${st(C.navy,3.5)}/>`).join('')}<rect x="-30" y="30" width="60" height="70" fill="#2B3A4A" ${st(C.navy,4)}/><g transform="translate(34,100) rotate(${f(ang)})"><rect x="-64" y="-72" width="64" height="72" rx="3" fill="#B07A4A" ${st(C.navy,4)}/><circle cx="-12" cy="-34" r="5" fill="${C.gold}"/></g>${_e108p(-82,60,.34,{c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g>`};

/* ---------- a stack of thin short books ---------- */
P.e108_shortbooks=(o,T,k)=>{const cols=['#E0584B','#4DA3D8','#4F9A5A','#F2994A','#8E6BB5'];let b='';cols.forEach((c,i)=>{b+=`<g transform="translate(${f((i%2?10:-6)+Math.sin(i)*4)},${f(80-i*30)})"><rect x="-84" y="-14" width="168" height="26" rx="4" fill="${c}" ${st()}/><rect x="-80" y="-8" width="160" height="14" fill="#fff" opacity=".85"/><rect x="-80" y="-8" width="14" height="14" fill="${c}" opacity=".8"/></g>`});
  return `<g><ellipse cx="0" cy="104" rx="110" ry="9" fill="#000" opacity=".13"/>${b}</g>`};

/* ---------- five players together beat one star ---------- */
P.e108_team5=(o,T,k)=>{const cs=['#E2B653','#4DA3D8','#D96C8B','#4F7A5A','#F2994A'];let p='';cs.forEach((c,i)=>{p+=_e108p(-100+i*50,40,.3,{c,hair:['bun','short','long','short','bun'][i],hc:'#2A1D18',ph:i},T)});
  return `<g><g transform="translate(-14,0)">${p}<path d="M-124 -26 q60 -34 120 -34 q60 0 120 34" fill="none" ${st(C.moss,6)} stroke-dasharray="2 10" stroke-linecap="round"/></g><g transform="translate(0,-88)"><text x="0" y="14" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="40" fill="${C.navy}">5 &gt; 1</text></g><g transform="translate(0,100)">${_e108p(0,0,.2,{c:'#9AA7B0',hair:'short',hc:'#222'},T)}</g></g>`};

/* ---------- phone put away in a drawer ---------- */
P.e108_phoneaway=(o,T,k)=>{const sl=ease(k/.8)*40;
  return `<g><rect x="-120" y="-70" width="240" height="170" rx="10" fill="#B07A4A" ${st()}/><rect x="-104" y="-54" width="208" height="64" rx="6" fill="#C79468" ${st(C.navy,4)}/><rect x="-24" y="-30" width="48" height="12" rx="6" fill="${C.gold}" ${st(C.navy,3)}/><g transform="translate(0,${f(24+sl*.5)})"><rect x="-104" y="20" width="208" height="70" rx="6" fill="#9B6A3C" ${st(C.navy,4)}/><rect x="-92" y="26" width="184" height="30" rx="4" fill="#6D4528"/><g transform="translate(0,34) rotate(-8)"><rect x="-22" y="-16" width="44" height="82" rx="8" fill="#2B3A4A" ${st(C.navy,3.5)} transform="rotate(90) translate(-26,-20) scale(.85)"/><rect x="-30" y="-8" width="60" height="30" rx="6" fill="#2B3A4A" ${st(C.navy,3.5)}/><rect x="-26" y="-4" width="52" height="22" rx="3" fill="#7FB6D6"/></g></g></g>`};

/* ---------- the week: Thursday highlighted, weekend activities ---------- */
P.e108_weekplan=(o,T,k)=>{const days=['M','T','W','T','F','S','S'],names=['MON','TUE','WED','THU','FRI','SAT','SUN'];let d='';days.forEach((dd,i)=>{const th=i===3,x=-132+i*44;d+=`<g transform="translate(${x},0)"><rect x="-19" y="-30" width="38" height="64" rx="8" fill="${th?C.gold:C.cream}" ${st()}/><text x="0" y="-6" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${th?13:12}" fill="${C.navy}">${names[i]}</text>${th?`<g transform="translate(0,18)"><circle r="9" fill="#fff" ${st(C.navy,2.5)}/><path d="M-4 0 L-1 3 L5 -4" fill="none" ${st(C.moss,3)}/></g>`:''}</g>`});
  const b=Math.sin(T*2)*3;
  return `<g><g transform="translate(0,52)">${d}</g><g transform="translate(-44,${f(-60+b)}) scale(.5)">${P.e108_bike({},T,k)}</g><g transform="translate(46,${f(-62-b)}) scale(.6)">${P.e108_tent?P.e108_tent({},T,k):''}</g></g>`};

/* ---------- a small tent icon ---------- */
P.e108_tent=(o,T,k)=>`<g><ellipse cx="0" cy="56" rx="80" ry="8" fill="#000" opacity=".12"/><polygon points="-80,56 0,-72 80,56" fill="#4DA3D8" ${st()}/><path d="M0 -30 L-26 56 L26 56Z" fill="#3B2A24" ${st(C.navy,5)}/><line x1="0" y1="-72" x2="0" y2="-30" ${st(C.navy,5)}/></g>`;

/* ---------- tip card ---------- */
P.e108_tip=(o,T)=>{const p=1+.03*Math.sin(T*4);return `<g transform="scale(${f(p)})"><rect x="-100" y="-86" width="200" height="172" rx="26" fill="${C.cream}" ${st()}/><path d="M-100 -50 V-60 Q-100 -86 -74 -86 H74 Q100 -86 100 -60 V-50Z" fill="${C.gold}" ${st()}/><rect x="-100" y="-62" width="200" height="12" fill="${C.gold}"/><line x1="-100" y1="-50" x2="100" y2="-50" ${st(C.navy,5)}/><text x="0" y="-60" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" fill="${C.navy}" letter-spacing="8">TIP</text><text x="0" y="52" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="104" fill="${C.navy}">${o.n}</text></g>`};

/* ---------- a grid of hobby icons (ball, bike, pencil, book) ---------- */
P.e108_hobbies=(o,T,k)=>{const tile=(x,y,c,inner,i)=>{const p=ease((k-i*.15)/.4);return `<g transform="translate(${x},${y}) scale(${f(.6+.4*p)})" opacity="${f(p)}"><rect x="-58" y="-58" width="116" height="116" rx="20" fill="${c}" ${st()}/>${inner}</g>`};
  return `<g>${tile(-66,-66,'#F9DDB0',`<circle r="30" fill="#F28C38" ${st()}/><path d="M-30 0 H30 M0 -30 V30" ${st(C.navy,3.5)} fill="none"/><path d="M-21 -21 Q0 0 -21 21 M21 -21 Q0 0 21 21" fill="none" ${st(C.navy,3.5)}/>`,0)}${tile(66,-66,'#CFE6F4',`<g transform="translate(0,6) scale(.44)">${_e108bike(0,'#E8943A',0)}</g>`,1)}${tile(-66,66,'#DDEFD2',`<g transform="rotate(35)"><rect x="-8" y="-40" width="16" height="64" fill="#F2B84B" ${st()}/><polygon points="-8,24 8,24 0,44" fill="#E8C9A0" ${st(C.navy,4)}/><rect x="-8" y="-40" width="16" height="12" fill="#D96C8B" ${st()}/></g>`,2)}${tile(66,66,'#F4D1DA',`<path d="M-40 -22 L0 -12 L40 -22 L40 26 L0 38 L-40 26Z" fill="#fff" ${st()}/><path d="M0 -12 V38" ${st(C.navy,3.5)}/>`,3)}</g>`};

/* ---------- a person with a bright idea thinking while pedalling ---------- */
P.e108_ideabike=(o,T,k)=>`<g><g transform="translate(0,28) scale(.8)">${P.e108_bike({},T,k)}</g><g transform="translate(74,-92) scale(.6)">${P.bulb({},T)}</g></g>`;

/* ---------- a gold number pill for 3-digit numbers (200, 300) ---------- */
P.e108_num=(o,T)=>{const t=String(o.n),w=70+t.length*40,p=1+.03*Math.sin(T*3);return `<g transform="scale(${f(p)})"><rect x="${-w/2}" y="-58" width="${w}" height="116" rx="58" fill="${C.gold}" ${st()}/><rect x="${-w/2+10}" y="-48" width="${w-20}" height="96" rx="48" fill="none" stroke="${C.gold2}" stroke-width="4"/><text x="0" y="24" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="70" fill="${C.navy}">${t}</text></g>`};

const _e108iPlate=(id,c1,c2,T,ring)=>`<defs><radialGradient id="${id}" cx="50%" cy="40%" r="65%"><stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></radialGradient></defs><circle r="136" fill="${c1}" opacity="${f(.10+.04*Math.sin(T*1.5))}"/><circle r="126" fill="url(#${id})"/><circle r="126" fill="none" stroke="${ring}" stroke-width="3" opacity=".7"/><circle r="136" fill="none" stroke="${ring}" stroke-width="2" stroke-dasharray="3 11" opacity=".55" transform="rotate(${f(T*8)})"/>`;
const _e108iSp=(x,y,s,T,ph,col)=>{const a=.5+.5*Math.sin(T*2.4+ph),z=s*(.55+.45*a);return `<path transform="translate(${x},${y}) scale(${f(z)})" d="M0,-1 Q.14,-.14 1,0 Q.14,.14 0,1 Q-.14,.14 -1,0 Q-.14,-.14 0,-1Z" fill="${col||'#FFE9A0'}" opacity="${f(.45+.55*a)}"/>`};
/* Episode 108 intro hero: basketball + hobby icons (headphones, bike wheel, paint palette, camera) */
P.e108_ihero=(o,T,k)=>{const b=(i,a,s=1.5)=>Math.sin(T*s+i)*a;
const bob=b(0,6,2.2),sh=1-bob/60;
const spokes=[0,1,2,3,4,5].map(i=>`<line x1="0" y1="0" x2="0" y2="-21" ${st('#FFF3C9',1.6)} transform="rotate(${f(i*30+T*40)})"/><line x1="0" y1="0" x2="0" y2="21" ${st('#FFF3C9',1.6)} transform="rotate(${f(i*30+T*40)})"/>`).join('');
const note=(ph)=>{const u=((T*.45+ph)%1);const y=-u*46,a=Math.sin(u*Math.PI);return `<g transform="translate(${f(Math.sin(u*6+ph*9)*5)},${f(y)})" opacity="${f(a)}"><ellipse cx="0" cy="0" rx="6" ry="4.5" fill="#FFD36B" ${st(C.navy,2)} transform="rotate(-20)"/><path d="M5,-1 V-20 q8,2 9,9" fill="none" ${st('#FFD36B',3.2)}/></g>`};
return `<g>${_e108iPlate('e108i_p','#3F7FA6','#17283A',T,'#F0C64A')}
<defs><radialGradient id="e108i_b" cx="35%" cy="30%" r="80%"><stop offset="0" stop-color="#FFC27A"/><stop offset=".55" stop-color="#F2802E"/><stop offset="1" stop-color="#C74F12"/></radialGradient>
<linearGradient id="e108i_pl" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FFF0C8"/><stop offset="1" stop-color="#EBC584"/></linearGradient>
<linearGradient id="e108i_hp" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FF9FB0"/><stop offset="1" stop-color="#E5486A"/></linearGradient></defs>
${_e108iSp(-100,-92,9,T,0)}${_e108iSp(100,-96,7,T,2)}${_e108iSp(2,-112,6,T,4)}${_e108iSp(110,6,5,T,1)}
<g transform="translate(-86,${f(-44+b(1,4))})"><path d="M-27,8 C-30,-36 30,-36 27,8" fill="none" ${st(C.navy,12)}/><path d="M-27,8 C-30,-36 30,-36 27,8" fill="none" ${st('#7BE0D2',6)}/><rect x="-37" y="-2" width="17" height="32" rx="8" fill="url(#e108i_hp)" ${st(C.navy,4)}/><rect x="20" y="-2" width="17" height="32" rx="8" fill="url(#e108i_hp)" ${st(C.navy,4)}/><g transform="translate(40,-10)">${note(0)}</g></g>
<g transform="translate(88,${f(-42+b(2,4))})"><circle r="30" fill="#14222D" opacity=".5"/><circle r="27" fill="none" ${st(C.navy,8)}/><circle r="27" fill="none" ${st('#FFC94A',4)}/>${spokes}<circle r="5" fill="#FFC94A" ${st(C.navy,2.5)}/></g>
<ellipse cx="0" cy="${f(68)}" rx="${f(40*sh)}" ry="${f(8*sh)}" fill="#000" opacity=".28"/>
<g transform="translate(0,${f(8+bob)})"><circle r="52" fill="url(#e108i_b)" ${st(C.navy,5)}/><g transform="rotate(${f(b(0,10,1.1))})" fill="none" ${st(C.navy,3.4)}><path d="M-52,0 H52 M0,-52 V52"/><path d="M-37,-37 Q-14,0 -37,37 M37,-37 Q14,0 37,37"/></g><ellipse cx="-20" cy="-26" rx="14" ry="7" fill="#fff" opacity=".35" transform="rotate(-35 -20 -26)"/></g>
<g transform="translate(-84,${f(60+b(3,4))}) rotate(-12)"><path d="M-30,-4 C-34,-30 -4,-40 20,-32 C42,-24 46,2 30,14 C20,22 8,8 -3,18 C-15,28 -28,22 -30,-4Z" fill="url(#e108i_pl)" ${st(C.navy,4)}/><circle cx="-12" cy="2" r="4.5" fill="#17283A"/><circle cx="-14" cy="-18" r="6" fill="#E5484D"/><circle cx="2" cy="-26" r="6" fill="#4DA3D8"/><circle cx="20" cy="-16" r="6" fill="#5EB56A"/><circle cx="26" cy="2" r="5.5" fill="#F0C64A"/><g transform="rotate(${f(b(0,5,2))} 28 -30)"><rect x="28" y="-62" width="7" height="36" rx="3" fill="#F2994A" ${st(C.navy,3)} transform="rotate(30 31 -44)"/></g></g>
<g transform="translate(86,${f(62+b(4,4))})"><rect x="-32" y="-18" width="64" height="42" rx="9" fill="#E9EEF2" ${st(C.navy,4.5)}/><rect x="-32" y="-18" width="64" height="14" rx="7" fill="#7E9BB0" ${st(C.navy,4.5)}/><rect x="-14" y="-28" width="18" height="10" rx="3" fill="#E9EEF2" ${st(C.navy,4)}/><circle cx="0" cy="6" r="14" fill="#2B3D48" ${st(C.navy,4)}/><circle cx="0" cy="6" r="8" fill="#4DA3D8"/><circle cx="-3" cy="3" r="3" fill="#fff" opacity=".8"/><circle cx="22" cy="-10" r="3" fill="${Math.sin(T*3)>0?'#FFD36B':'#E5484D'}"/></g>
</g>`};

/* A2 ep 8 props end */
/* A2 ep 9 props begin */
/* Episode 109 props: A thief in our building (safety at home and outside). Faceless. Calm symbols only. Uses C, st, f, ease, clamp, P. */
const _e109sh=(rx,y)=>`<ellipse cx="0" cy="${y}" rx="${rx}" ry="${f(rx*.09)}" fill="#1E2B33" opacity=".15"/>`;
const _e109steel='#B9C6CE',_e109steelD='#7C909C',_e109wall='#F4E5C2',_e109brick='#C98E6B';
/* a thick tube with a navy outline: used for bicycle frames, bars, pipes */
const _e109tube=(x1,y1,x2,y2,col,w)=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" ${st(C.navy,w+6)}/><line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" ${st(col,w)}/>`;
const _e109star=(x,y,r,fill,stroke)=>{let p='';for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*.45:r;p+=`${f(x+Math.cos(a)*rr)},${f(y+Math.sin(a)*rr)} `}return `<polygon points="${p}" fill="${fill}" ${st(stroke||C.goldD,3)}/>`};

/* ---------- bicycle (side view, facing right). o: c colour, star (yellow sticker), zoom, lock (chain), ghost (empty dotted outline), ride (wheels turn fast), still ---------- */
P.e109_bike=(o,T,k)=>{
  const col=o.c||'#3E86C6',gh=o.ghost,spin=o.still?0:T*(o.ride?300:36);
  const tb=(x1,y1,x2,y2,w)=>gh?`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#8A9BA5" stroke-width="3" stroke-dasharray="7 7" stroke-linecap="round"/>`:_e109tube(x1,y1,x2,y2,col,w||7);
  const wheel=(cx)=>{let sp='';if(!gh)for(let i=0;i<8;i++)sp+=`<line x1="0" y1="-36" x2="0" y2="36" transform="rotate(${f(i*22.5+spin)})" stroke="#D9E2E7" stroke-width="2"/>`;
    return gh?`<circle cx="${cx}" cy="38" r="44" fill="none" stroke="#8A9BA5" stroke-width="3" stroke-dasharray="7 7"/>`:`<g transform="translate(${cx},38)"><circle r="44" fill="#fff" fill-opacity=".18" ${st(C.navy,12)}/><circle r="44" fill="none" stroke="#46535D" stroke-width="6"/><circle r="38" fill="none" stroke="#D9E2E7" stroke-width="2"/>${sp}<circle r="7" fill="${_e109steel}" ${st(C.navy,3)}/></g>`};
  const ca=-(o.still?0:T*(o.ride?9:1.2));
  const px=-6+Math.cos(ca)*17,py=46+Math.sin(ca)*17;
  let s='';
  s+=wheel(-72)+wheel(72);
  if(!gh){
    s+=`<path d="M-54 8 Q-6 -2 4 46" fill="none" stroke="${C.navy}" stroke-width="2" opacity="0"/>`;
    s+=`<path d="M36 6 Q72 -20 108 6" fill="none" ${st(C.navy,12)}/><path d="M36 6 Q72 -20 108 6" fill="none" ${st(col,6)}/>`;  /* front mudguard */
    s+=`<line x1="-6" y1="33" x2="-72" y2="32" ${st('#46535D',3)}/><line x1="-6" y1="59" x2="-72" y2="45" ${st('#46535D',3)}/>`; /* chain */
  }
  s+=tb(-6,46,-72,38,6)+tb(-24,-22,-72,38,5);                         /* chain stay, seat stay */
  s+=tb(-6,46,-26,-30,7)+tb(-24,-24,48,-26,7)+tb(52,-18,-6,46,8)+tb(48,-32,56,-10,9)+tb(56,-10,72,38,6);
  s+=tb(-26,-30,-30,-46,5);                                           /* seat post */
  s+=tb(48,-32,44,-54,5);                                             /* stem */
  if(gh){s+=`<ellipse cx="-32" cy="-52" rx="20" ry="7" fill="none" stroke="#8A9BA5" stroke-width="3" stroke-dasharray="6 6"/><path d="M34 -58 Q50 -62 64 -52" fill="none" stroke="#8A9BA5" stroke-width="3" stroke-dasharray="6 6"/>`}
  else{
    s+=`<ellipse cx="-32" cy="-52" rx="22" ry="8" fill="#6F4A2E" ${st()}/><ellipse cx="-36" cy="-54" rx="9" ry="2.6" fill="#fff" opacity=".35"/>`;
    s+=`<path d="M32 -58 Q50 -64 64 -52 L68 -42" fill="none" ${st(C.navy,10)}/><path d="M32 -58 Q50 -64 64 -52" fill="none" ${st(_e109steel,5)}/><path d="M64 -52 L68 -42" fill="none" ${st('#6F4A2E',8)}/>`;
    s+=`<path d="M52 -62 a10 10 0 0 1 14 0 l-3 7 h-8Z" fill="${C.gold}" ${st(C.navy,3)}/>`;                /* lamp */
    s+=`<circle cx="-6" cy="46" r="15" fill="${_e109steel}" ${st(C.navy,4)}/><circle cx="-6" cy="46" r="6" fill="${_e109steelD}"/>`;
    s+=`<line x1="-6" y1="46" x2="${f(px)}" y2="${f(py)}" ${st(C.navy,5)}/><rect x="${f(px-9)}" y="${f(py-3)}" width="18" height="7" rx="3" fill="#46535D" ${st(C.navy,3)}/>`;
    s+=`<circle cx="-72" cy="38" r="8" fill="${_e109steel}" ${st(C.navy,3)}/>`;
  }
  if(o.star&&!gh){const pl=1+.1*Math.sin(T*4);s+=`<g transform="translate(90,-6) scale(${f(pl)})">${_e109star(0,0,13,C.gold,C.goldD)}</g>`;
    if(o.zoom)s+=`<g transform="translate(90,-6)"><circle r="26" fill="none" ${st(C.navy,5)}/><circle r="26" fill="#fff" fill-opacity=".18"/><line x1="18" y1="18" x2="40" y2="40" ${st(C.navy,8)}/><line x1="18" y1="18" x2="40" y2="40" ${st(C.brown,4)}/></g>`}
  if(o.lock&&!gh){s+=`<path d="M-86 4 Q-72 -26 -40 -10 Q-20 4 -30 28 Q-60 50 -90 24" fill="none" ${st(C.navy,12)}/><path d="M-86 4 Q-72 -26 -40 -10 Q-20 4 -30 28 Q-60 50 -90 24" fill="none" stroke="#C9D3D9" stroke-width="6" stroke-dasharray="10 5"/><g transform="translate(-56,16) scale(.34)">${P.e109_lock({s:'closed'},T,k)}</g>`}
  return `<g>${_e109sh(104,86)}<g>${s}</g></g>`};

/* ---------- padlock. o.s: closed | open | broken (two pieces, cut shackle); o.strong = heavy new lock with chain ---------- */
P.e109_lock=(o,T,k)=>{
  const sw=Math.sin(T*1.6)*2,st_=o.s||'closed';
  const bodyP=`M-48 8 Q-48 -6 -34 -6 L34 -6 Q48 -6 48 8 L48 68 Q48 82 34 82 L-34 82 Q-48 82 -48 68Z`;
  const key=`<circle cx="0" cy="28" r="10" fill="${C.navy}"/><path d="M-5 32 L-8 56 L8 56 L5 32Z" fill="${C.navy}"/>`;
  const shine=`<path d="M-38 6 Q-38 2 -32 2 L-30 2 L-30 70 L-32 70 Q-38 70 -38 66Z" fill="#fff" opacity=".35"/>`;
  if(st_==='broken'){
    const L=`M-48 8 Q-48 -6 -34 -6 L-4 -6 L4 10 L-6 24 L6 40 L-4 56 L2 82 L-34 82 Q-48 82 -48 68Z`,R=`M-4 -6 L34 -6 Q48 -6 48 8 L48 68 Q48 82 34 82 L2 82 L-4 56 L6 40 L-6 24 L4 10Z`;
    return `<g transform="translate(0,-10)">${_e109sh(80,96)}
      <g transform="translate(${f(-16+sw*.5)},4) rotate(-9 -30 82)"><path d="M-30 -6 V-40 Q-30 -58 -14 -66" fill="none" ${st(C.navy,16)}/><path d="M-30 -6 V-40 Q-30 -58 -14 -66" fill="none" ${st(_e109steel,8)}/><path d="${L}" fill="${C.gold}" ${st()}/><path d="M-38 6 Q-38 2 -32 2 L-30 2 L-30 70 L-32 70 Q-38 70 -38 66Z" fill="#fff" opacity=".35"/><circle cx="-18" cy="30" r="7" fill="${C.navy}"/></g>
      <g transform="translate(${f(16-sw*.5)},8) rotate(11 30 82)"><path d="M30 -6 V-40 Q30 -58 14 -66" fill="none" ${st(C.navy,16)}/><path d="M30 -6 V-40 Q30 -58 14 -66" fill="none" ${st(_e109steel,8)}/><path d="${R}" fill="${C.gold2}" ${st()}/><path d="M6 32 L8 56 L22 56 L18 32Z" fill="${C.navy}" opacity=".0"/></g></g>`}
  const open=st_==='open';
  const sh=open?`<path d="M-30 -6 V-42 a30 30 0 0 1 60 0 V-26" fill="none" ${st(C.navy,16)}/><path d="M-30 -6 V-42 a30 30 0 0 1 60 0 V-26" fill="none" ${st(_e109steel,8)}/>`:`<path d="M-30 -6 V-42 a30 30 0 0 1 60 0 V-6" fill="none" ${st(C.navy,16)}/><path d="M-30 -6 V-42 a30 30 0 0 1 60 0 V-6" fill="none" ${st(_e109steel,8)}/>`;
  const chain=o.strong?`<g>${[-1,1].map(sd=>{let c='';for(let i=0;i<4;i++)c+=`<rect x="${sd*(62+i*24)-12}" y="${i%2?36:42}" width="24" height="${i%2?20:12}" rx="${i%2?10:6}" fill="none" ${st(_e109steelD,6)}/>`;return c}).join('')}</g>`:'';
  const glint=o.strong?`<g transform="translate(34,-4) scale(${f(.6+.4*Math.sin(T*3))})"><polygon points="0,-16 4,-4 16,0 4,4 0,16 -4,4 -16,0 -4,-4" fill="#fff" ${st(C.gold,2)}/></g>`:'';
  return `<g transform="translate(0,-8) rotate(${f(sw)} 0 40)">${_e109sh(70,96)}${chain}${sh}<path d="${bodyP}" fill="${C.gold}" ${st()}/><rect x="-38" y="52" width="76" height="22" rx="8" fill="${C.goldD}" opacity=".25"/>${shine}${o.strong?`<rect x="-36" y="4" width="72" height="66" rx="10" fill="none" stroke="${C.goldD}" stroke-width="3"/>`:''}${key}${glint}</g>`};

/* ---------- key ---------- */
P.e109_key=(o,T,k)=>{const sw=Math.sin(T*2)*4;
  return `<g transform="rotate(${f(-35+sw)})">${_e109sh(0,0)}<rect x="-14" y="-4" width="150" height="20" rx="8" fill="${C.gold}" ${st()}/><rect x="96" y="16" width="14" height="30" rx="3" fill="${C.gold}" ${st()}/><rect x="120" y="16" width="14" height="22" rx="3" fill="${C.gold}" ${st()}/><circle cx="-34" cy="6" r="44" fill="${C.gold}" ${st()}/><circle cx="-34" cy="6" r="18" fill="${o.bg||'#F8F1D8'}" ${st(C.navy,5)}/><path d="M-60 -18 Q-42 -36 -18 -26" fill="none" stroke="#fff" stroke-width="5" opacity=".5"/><line x1="12" y1="6" x2="90" y2="6" stroke="${C.goldD}" stroke-width="3" opacity=".6"/></g>`};

/* ---------- hat(s). o.c colour, o.k brim | cap ---------- */
P.e109_hat=(o,T,k)=>{const c=o.c||'#6B5B4E',dk=o.cd||'#463A31',cap=o.k==='cap';
  if(cap)return `<g>${_e109sh(84,66)}<path d="M-76 40 Q-84 -30 0 -40 Q84 -30 76 40Z" fill="${c}" ${st()}/><path d="M-4 -38 Q70 -26 70 30" fill="none" ${st(dk,4)}/><path d="M-76 40 Q-10 66 100 46 Q108 30 76 40Z" fill="${dk}" ${st()}/><circle cx="0" cy="-42" r="6" fill="${dk}" ${st(C.navy,3)}/></g>`;
  return `<g>${_e109sh(110,62)}<path d="M-54 8 Q-56 -62 0 -66 Q56 -62 54 8Z" fill="${c}" ${st()}/><path d="M-54 -8 Q0 4 54 -8 L54 8 Q0 20 -54 8Z" fill="${C.red}" ${st(C.navy,4)}/><path d="M-30 -52 Q-24 -62 -10 -62" fill="none" stroke="#fff" stroke-width="5" opacity=".35"/><ellipse cx="0" cy="12" rx="108" ry="22" fill="${dk}" ${st()}/><path d="M-96 8 Q0 26 96 8" fill="none" stroke="#fff" stroke-width="3" opacity=".25"/></g>`};

/* ---------- the thief, told calmly: a figure in a grey coat, big hat and scarf (nothing of a face is drawn) ---------- */
P.e109_thief=(o,T,k)=>{const sway=o.walk?Math.sin(T*5)*3:Math.sin(T*1.6),bob=o.walk?-Math.abs(Math.sin(T*5))*4:0;
  return `<g transform="translate(${f(sway)},${f(bob)})">${_e109sh(66,112)}
   <path d="M-60 110 L-60 36 Q-60 -4 0 -4 Q60 -4 60 36 L60 110Z" fill="#5C6A76" ${st()}/><path d="M-14 -4 L0 44 L14 -4Z" fill="#46535D" ${st(C.navy,3)}/><path d="M0 44 L0 108" ${st(C.navy,3)} fill="none"/><rect x="-60" y="62" width="120" height="8" fill="#46535D" opacity=".5"/>
   <circle cx="0" cy="-54" r="38" fill="#8C99A5" ${st()}/><path d="M-36 -42 Q0 -26 36 -42" fill="none" ${st(C.navy,3)}/><path d="M-30 -30 Q0 -14 30 -30" fill="none" ${st(C.navy,3)}/>
   <path d="M-36 -62 Q-36 -112 0 -112 Q36 -112 36 -62Z" fill="#3C4650" ${st()}/><rect x="-37" y="-78" width="74" height="12" fill="${C.red}" ${st(C.navy,3)}/><ellipse cx="0" cy="-64" rx="58" ry="12" fill="#2F3A44" ${st()}/></g>`};

/* ---------- police officer (faceless): cap with badge, blue uniform; o.note = notebook, o.f = woman officer, o.two = a second one behind ---------- */
P.e109_police=(o,T,k)=>{const bob=Math.sin(T*2)*2;
  const one=(x,sc,fem,note)=>`<g transform="translate(${x},0) scale(${sc})"><g transform="translate(0,${f(bob)})">${fem?`<path d="M-38 -48 Q-46 -10 -34 14 L-18 6 L-26 -40Z M38 -48 Q46 -10 34 14 L18 6 L26 -40Z" fill="#2A1D18" ${st()}/>`:''}
   <path d="M-62 108 L-62 36 Q-62 -4 0 -4 Q62 -4 62 36 L62 108Z" fill="#2F5D9A" ${st()}/><path d="M-12 -4 L0 20 L12 -4Z" fill="#fff" ${st(C.navy,3)}/><rect x="-62" y="72" width="124" height="12" fill="#1E3F6B" ${st(C.navy,3)}/><rect x="-9" y="70" width="18" height="16" rx="3" fill="${C.gold}" ${st(C.navy,3)}/>
   <rect x="-9" y="-20" width="18" height="20" fill="#E3AE82" ${st(C.navy,4)}/><circle cx="0" cy="-54" r="36" fill="#E3AE82" ${st()}/>
   <path d="M-40 -64 Q-40 -102 0 -102 Q40 -102 40 -64Z" fill="#2F5D9A" ${st()}/><rect x="-42" y="-70" width="84" height="12" rx="4" fill="#1E3F6B" ${st(C.navy,3)}/><path d="M-30 -60 Q0 -48 30 -60" fill="none" ${st(C.navy,3)} opacity="0"/>${_e109star(0,-86,9,C.gold,C.goldD)}
   <g transform="translate(-34,22) scale(.8)">${_e109star(0,0,12,C.gold,C.goldD)}</g>
   ${note?`<g transform="translate(12,34) rotate(-10)"><rect x="0" y="0" width="52" height="64" rx="5" fill="#fff" ${st()}/><line x1="10" y1="16" x2="42" y2="16" ${st('#9AA7B0',3)}/><line x1="10" y1="28" x2="42" y2="28" ${st('#9AA7B0',3)}/><line x1="10" y1="40" x2="32" y2="40" ${st('#9AA7B0',3)}/><rect x="40" y="-8" width="7" height="46" rx="3" fill="${C.gold}" ${st(C.navy,3)} transform="rotate(${f(18+Math.sin(T*4)*6)} 43 38)"/></g>`:''}</g></g>`;
  return `<g>${_e109sh(o.two?120:66,112)}${o.two?one(-58,.86,o.f,0)+one(58,.86,0,o.note):one(0,1,o.f,o.note)}</g>`};

/* ---------- police car with flashing light bar (o.lights=0 turns it off) ---------- */
P.e109_policecar=(o,T,k)=>{const on=o.lights!==0,ph=Math.floor(T*4)%2;
  const lg=on?`<ellipse cx="-14" cy="-60" rx="${ph?42:20}" ry="${ph?30:14}" fill="${C.red}" opacity="${ph?.28:.12}"/><ellipse cx="14" cy="-60" rx="${ph?20:42}" ry="${ph?14:30}" fill="#3E86C6" opacity="${ph?.12:.28}"/>`:'';
  return `<g>${_e109sh(120,84)}${lg}<rect x="-26" y="-60" width="26" height="16" rx="4" fill="${on&&ph?C.red:'#A94441'}" ${st(C.navy,4)}/><rect x="0" y="-60" width="26" height="16" rx="4" fill="${on&&!ph?'#4DA3D8':'#2F6A9A'}" ${st(C.navy,4)}/>
  <path d="M-116 62 L-116 18 Q-116 6 -100 4 L-70 0 L-46 -40 L52 -40 L80 0 L110 6 Q120 10 120 22 L120 62Z" fill="#fff" ${st()}/><path d="M-116 34 L120 34 L120 50 L-116 50Z" fill="#2F5D9A" ${st(C.navy,3)}/>
  <path d="M-58 -2 L-38 -32 L-4 -32 L-4 -2Z" fill="${C.sky}" ${st(C.navy,4)}/><path d="M6 -2 L6 -32 L44 -32 L68 -2Z" fill="${C.sky}" ${st(C.navy,4)}/><text x="2" y="48" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="15" fill="#fff" letter-spacing="2">POLICE</text>
  <circle cx="-68" cy="62" r="24" fill="${C.navy}" ${st()}/><circle cx="-68" cy="62" r="11" fill="${_e109steel}"/><circle cx="72" cy="62" r="24" fill="${C.navy}" ${st()}/><circle cx="72" cy="62" r="11" fill="${_e109steel}"/><rect x="108" y="14" width="12" height="10" rx="3" fill="${C.gold}" ${st(C.navy,3)}/></g>`};

/* ---------- the building gate (iron bars between two brick pillars). o.open (swings open), o.ajar, o.lock = 'on' | 'off' (padlock shown) ---------- */
P.e109_gate=(o,T,k)=>{
  const op=o.ajar?.55:(o.open?ease((k-.25)/.9)*.82:0),sx=Math.max(.1,1-op);
  const leaf=(side)=>{let b='';for(let i=0;i<8;i++){const x=i*11;b+=`<line x1="${x}" y1="-74" x2="${x}" y2="84" ${st(C.navy,4.5)}/><polygon points="${x-4.5},-74 ${x},-88 ${x+4.5},-74" fill="#46535D" ${st(C.navy,2.5)}/>`}
    return `<g transform="translate(${side*80},0) scale(${-side*sx},1)">${b}<rect x="-2" y="-56" width="84" height="9" rx="3" fill="#46535D" ${st(C.navy,3)}/><rect x="-2" y="46" width="84" height="9" rx="3" fill="#46535D" ${st(C.navy,3)}/><path d="M4 -40 Q40 -14 76 -40" fill="none" ${st('#46535D',4)}/></g>`};
  const pil=(x)=>`<g transform="translate(${x},0)"><rect x="-20" y="-82" width="40" height="176" fill="${_e109brick}" ${st()}/><g opacity=".4">${[-52,-26,0,26,52,78].map(y=>`<line x1="-20" y1="${y}" x2="20" y2="${y}" ${st(C.navy,2)}/>`).join('')}</g><rect x="-26" y="-96" width="52" height="16" rx="4" fill="#E7D3A6" ${st()}/><rect x="-6" y="-112" width="12" height="16" fill="#E7D3A6" ${st(C.navy,3)}/></g>`;
  const sh=o.lock==='on'?`<g transform="translate(0,6) scale(.4)">${P.e109_lock({s:'closed'},T,k)}</g>`:(o.lock==='off'?`<g transform="translate(14,26) rotate(22) scale(.4)">${P.e109_lock({s:'open'},T,k)}</g>`:'');
  const yard=`<rect x="-80" y="-82" width="160" height="176" fill="#8FB59A"/><rect x="-80" y="30" width="160" height="64" fill="#D9C79A"/><rect x="-54" y="-82" width="108" height="112" fill="#E3B98F"/><rect x="-20" y="-6" width="40" height="36" rx="3" fill="${C.brown}"/>`;
  return `<g>${_e109sh(130,96)}${yard}${leaf(-1)}${leaf(1)}${pil(-100)}${pil(100)}${sh}</g>`};

/* ---------- apartment building facade. o.lit [floors lit], o.night, o.hi floor (ring around it), o.gate, o.cam ---------- */
P.e109_building=(o,T,k)=>{
  const night=o.night,lit=o.lit||[],wall=night?'#5F6E92':'#E3B98F',wallD=night?'#4A5878':'#C99D74';
  let s='';
  s+=`<rect x="-102" y="-96" width="204" height="196" fill="${wall}" ${st()}/><rect x="-110" y="-110" width="220" height="20" rx="4" fill="${night?'#3C4766':'#8B5E3C'}" ${st()}/>`;
  for(let r=0;r<4;r++)s+=`<line x1="-102" y1="${-96+r*48}" x2="102" y2="${-96+r*48}" ${st(wallD,3)}/>`;
  for(let fl=0;fl<3;fl++){const y=-84+fl*48,floorNo=3-fl;           /* top row = 3rd floor */
    for(let c=0;c<3;c++){const x=-72+c*60,on=lit.includes(floorNo)||(o.allLit),blink=on?(.9+.1*Math.sin(T*3+c)):1;
      s+=`<rect x="${x-18}" y="${y}" width="36" height="34" rx="4" fill="${on?'#FFE08A':(night?'#27304C':C.sky)}" ${st(C.navy,4)} opacity="${f(blink)}"/><line x1="${x}" y1="${y}" x2="${x}" y2="${y+34}" ${st(C.navy,3)}/><line x1="${x-18}" y1="${y+17}" x2="${x+18}" y2="${y+17}" ${st(C.navy,3)}/><rect x="${x-22}" y="${y+34}" width="44" height="6" rx="2" fill="${night?'#3C4766':'#fff'}" ${st(C.navy,3)}/>`}}
  /* ground floor: entrance door + two windows */
  s+=`<rect x="-72" y="62" width="36" height="26" rx="4" fill="${lit.includes(0)?'#FFE08A':(night?'#27304C':C.sky)}" ${st(C.navy,4)}/><rect x="36" y="62" width="36" height="26" rx="4" fill="${lit.includes(0)?'#FFE08A':(night?'#27304C':C.sky)}" ${st(C.navy,4)}/><rect x="-22" y="50" width="44" height="50" rx="6" fill="${C.brown}" ${st()}/><rect x="-14" y="58" width="28" height="22" rx="3" fill="${night?'#27304C':'#A9743F'}" ${st(C.navy,3)}/><circle cx="14" cy="80" r="3.5" fill="${C.gold}" ${st(C.navy,2)}/>`;
  if(o.hi!=null){const fl=o.hi,y=fl===0?58:-84+(3-fl)*48-6,h=fl===0?36:46,pulse=1+.03*Math.sin(T*4);
    s+=`<g transform="translate(0,${f(y+h/2)}) scale(${f(pulse)})"><rect x="-100" y="${-h/2}" width="200" height="${h}" rx="12" fill="${C.gold}" fill-opacity=".18" ${st(C.red,6)}/></g><g transform="translate(112,${f(y+h/2)})"><circle r="17" fill="${C.red}" ${st()}/><text x="0" y="8" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="#fff">${fl}</text></g>`}
  let ex='';
  if(o.gate){let bars='';for(let i=0;i<19;i++)bars+=`<line x1="${-90+i*10}" y1="76" x2="${-90+i*10}" y2="104" ${st(C.navy,3)}/>`;ex+=`<g>${bars}<line x1="-96" y1="82" x2="96" y2="82" ${st(C.navy,5)}/><line x1="-96" y1="98" x2="96" y2="98" ${st(C.navy,5)}/><rect x="-14" y="72" width="28" height="32" fill="#fff" fill-opacity=".0"/><g transform="translate(0,90) scale(.26)">${P.e109_lock({s:o.lock==='off'?'open':'closed'},T,k)}</g></g>`}
  if(o.cam)ex+=`<g transform="translate(-92,-4) scale(.34)">${P.e109_camera({cone:1},T,k)}</g>`;
  return `<g>${_e109sh(120,102)}${s}${ex}</g>`};

/* ---------- security camera on a wall bracket; o.cone shows what it sees ---------- */
P.e109_camera=(o,T,k)=>{const led=Math.sin(T*5)>0,cone=o.cone?`<polygon points="-34,-4 -150,96 -42,126" fill="${C.gold}" opacity="${f(.2+.07*Math.sin(T*3))}"/><polygon points="-34,-4 -150,96 -42,126" fill="none" stroke="${C.goldD}" stroke-width="2" stroke-dasharray="7 6" opacity=".6"/>`:'';
  return `<g>${cone}<rect x="64" y="-84" width="22" height="130" rx="6" fill="${_e109steel}" ${st()}/><rect x="18" y="-60" width="52" height="14" rx="6" fill="${_e109steelD}" ${st()}/>
   <g transform="rotate(24 20 -50)"><rect x="-62" y="-80" width="90" height="56" rx="18" fill="#fff" ${st()}/><rect x="-66" y="-84" width="76" height="12" rx="6" fill="${_e109steel}" ${st(C.navy,3)}/><circle cx="-48" cy="-52" r="21" fill="${C.navy}" ${st()}/><circle cx="-48" cy="-52" r="13" fill="#3D6C8A"/><circle cx="-53" cy="-58" r="5" fill="#fff" opacity=".8"/><circle cx="8" cy="-64" r="5.5" fill="${led?C.red:'#7A2E2C'}" ${st(C.navy,2)}/>${led?`<circle cx="8" cy="-64" r="10" fill="${C.red}" opacity=".3"/>`:''}</g></g>`};

/* ---------- laptop showing the camera video. o.k gate | hall, o.t time stamp, o.fig = figure in view, o.box = highlight box, o.pause ---------- */
P.e109_monitor=(o,T,k)=>{const t=o.t||'02:00',pl=!o.pause;
  const vid=(()=>{let v=`<rect x="-92" y="-62" width="184" height="116" fill="#1F2D44"/>`;
    if(o.k==='hall'){v+=`<rect x="-92" y="24" width="184" height="30" fill="#2B3A56"/><polygon points="40,24 92,-22 92,24" fill="#3A4A68"/><polygon points="48,24 92,-14 92,24" fill="#2B3A56"/>`}
    else{v+=`<rect x="-92" y="22" width="184" height="32" fill="#2B3A56"/><rect x="-80" y="-32" width="16" height="62" fill="#4A5C7C"/><rect x="64" y="-32" width="16" height="62" fill="#4A5C7C"/>`;
      const sx=o.open?Math.max(.2,1-ease((k-.3)/.8)*.75):1;
      for(const sd of [-1,1]){let b='';for(let i=0;i<5;i++)b+=`<line x1="${i*10}" y1="-24" x2="${i*10}" y2="24" stroke="#8DA0BC" stroke-width="2.5"/>`;v+=`<g transform="translate(${sd*62},0) scale(${sd*sx},1)">${b}<line x1="0" y1="-14" x2="40" y2="-14" stroke="#8DA0BC" stroke-width="2.5"/></g>`}}
    if(o.fig)v+=`<g transform="translate(${f(o.fx==null?0:o.fx)},12) scale(.32)">${P.e109_thief({},T,k)}</g>`;
    if(o.box){const p=1+.04*Math.sin(T*5);v+=`<g transform="translate(0,-6) scale(${f(p)})" fill="none" stroke="${C.gold}" stroke-width="3.5"><path d="M-26 -14 v-12 h12 M26 -14 v-12 h-12 M-26 24 v12 h12 M26 24 v12 h-12"/></g>`}
    return v})();
  return `<g>${_e109sh(120,100)}<path d="M-124 94 L124 94 L108 70 L-108 70Z" fill="${_e109steel}" ${st()}/><rect x="-24" y="80" width="48" height="6" rx="3" fill="${_e109steelD}"/><rect x="-106" y="-80" width="212" height="152" rx="12" fill="${C.navy2}" ${st()}/><clipPath id="e109_mc"><rect x="-92" y="-66" width="184" height="124" rx="4"/></clipPath><g clip-path="url(#e109_mc)" transform="translate(0,-4)">${vid}<circle cx="-78" cy="-48" r="5" fill="${C.red}" opacity="${f(.5+.5*Math.sin(T*5))}"/><text x="-66" y="-43" font-family="Fraunces" font-weight="800" font-size="15" fill="#fff">${t}</text></g><rect x="-92" y="42" width="184" height="16" fill="#000" opacity=".35" transform="translate(0,-4)"/><g transform="translate(0,46)">${pl?`<polygon points="-80,-3 -80,9 -70,3" fill="#fff"/>`:`<rect x="-82" y="-3" width="4" height="12" fill="#fff"/><rect x="-74" y="-3" width="4" height="12" fill="#fff"/>`}<rect x="-58" y="2" width="140" height="3" rx="1.5" fill="#fff" opacity=".35"/><rect x="-58" y="2" width="${f(pl?20+((T*8)%100):70)}" height="3" rx="1.5" fill="${C.gold}"/></g></g>`};

/* ---------- three floors, a door opens on each (neighbours come out) ---------- */
P.e109_floors=(o,T,k)=>{let s='';const cols=[['#D96C8B','long','#3A2A22'],['#B07AA1','bun','#D5D8DB'],['#8E6BB5','short','#222']];
  for(let i=0;i<3;i++){const y=-96+i*68,op=ease((k-.3-i*.35)/.45);
    s+=`<g transform="translate(0,${y})"><rect x="-120" y="0" width="240" height="64" fill="${_e109wall}" ${st()}/><rect x="-120" y="56" width="240" height="8" fill="#C9A86E" ${st(C.navy,3)}/><rect x="-100" y="10" width="54" height="40" rx="4" fill="${C.sky}" ${st(C.navy,3)}/><line x1="-73" y1="10" x2="-73" y2="50" ${st(C.navy,3)}/>
    <rect x="46" y="4" width="46" height="60" fill="#FFE08A" ${st()}/><g transform="translate(69,38) scale(.3)" opacity="${f(op)}">${P.person({c:cols[i][0],hair:cols[i][1],hc:cols[i][2]},T)}</g>
    <g transform="translate(46,0) scale(${f(Math.max(.14,1-op*.86))},1)"><rect x="0" y="4" width="46" height="60" fill="${C.brown}" ${st()}/><rect x="6" y="12" width="34" height="22" fill="#A9743F" ${st(C.navy,2.5)}/><circle cx="38" cy="38" r="3.5" fill="${C.gold}"/></g></g>`}
  return `<g>${s}</g>`};

/* ---------- hall of the building: stairs, bikes on the wall side. o.bikes colours, o.gap index (empty dotted spot), o.floorlock (broken lock on floor), o.look (magnifier under stairs), o.cam, o.dim ---------- */
P.e109_hall=(o,T,k)=>{
  const cols=o.bikes||['#D9534F','#3E86C6','#5E9B63'],xs=[-98,-44,10];let b='';
  cols.forEach((cc,i)=>{const ghost=o.gap===i;b+=`<g transform="translate(${xs[i]},50) scale(.28)">${P.e109_bike({c:cc,ghost,still:1},T,k)}</g>`});
  const st_=`<polygon points="56,100 56,36 72,36 72,12 88,12 88,-12 104,-12 104,-36 120,-36 120,-60 130,-60 130,100" fill="#E7D3A6" ${st()}/><polygon points="62,100 130,100 130,-22 118,-22 118,0 102,0 102,24 86,24 86,48 70,48 70,72 62,72" fill="#6F5A48" opacity=".5"/>${[[56,36,72],[72,12,88],[88,-12,104],[104,-36,120],[120,-60,130]].map(([a,y,b])=>`<line x1="${a+2}" y1="${y}" x2="${b-1}" y2="${y}" ${st('#fff',3.5)} opacity=".8"/>`).join('')}`;
  const rail=`<path d="M52 4 L124 -96" fill="none" ${st(C.brown,6)}/><path d="M64 26 V-4 M84 -2 V-30 M104 -30 V-60 M122 -66 V-92" fill="none" ${st(C.brown,3)} opacity=".0"/>`;
  const look=o.look?`<g transform="translate(98,78)"><circle r="20" fill="#fff" fill-opacity=".25" ${st(C.navy,5)}/><line x1="16" y1="16" x2="34" y2="34" ${st(C.navy,9)}/><line x1="16" y1="16" x2="34" y2="34" ${st(C.brown,4)}/></g>`:'';
  const fl=o.floorlock?`<g transform="translate(-4,88) scale(.26) rotate(-80)">${P.e109_lock({s:'broken'},T,k)}</g>`:'';
  const cam=o.cam?`<g transform="translate(-92,-60) scale(.3) scale(-1,1)">${P.e109_camera({cone:1},T,k)}</g>`:'';
  return `<g><rect x="-128" y="-96" width="256" height="156" fill="${_e109wall}" ${st()}/><rect x="-128" y="-4" width="256" height="64" fill="#E8D7AC" opacity=".6"/><line x1="-128" y1="-4" x2="128" y2="-4" ${st('#C9A86E',3)}/>
  <rect x="-104" y="-82" width="60" height="46" rx="4" fill="${C.sky}" ${st()}/><line x1="-74" y1="-82" x2="-74" y2="-36" ${st(C.navy,3)}/><rect x="-30" y="-72" width="44" height="34" rx="3" fill="#fff" ${st()}/><path d="M-22 -48 l10 -12 l8 8 l8 -10 l10 14Z" fill="${C.leaf}"/>
  <rect x="-128" y="60" width="256" height="40" fill="#C9A26A" ${st()}/>${[-84,-40,4,48,92].map(x=>`<line x1="${x}" y1="60" x2="${x-14}" y2="100" ${st('#A9824E',2.5)}/>`).join('')}
  ${b}${st_}${rail}${look}${fl}${cam}${o.dim?`<rect x="-128" y="-96" width="256" height="196" fill="#1E2B33" opacity=".38"/>`:''}</g>`};

/* ---------- neighbours and other characters (faceless). o.k old | young | manager | shop | sister ---------- */
P.e109_neighbour=(o,T,k)=>{const kd=o.k||'old',bob=Math.sin(T*2+(o.ph||0))*2;
  const D={old:{c:'#B07AA1',hair:'bun',hc:'#D5D8DB'},young:{c:'#4F7A5A',hair:'short',hc:'#3A2A22'},manager:{c:'#5B6C8F',hair:'short',hc:'#222'},shop:{c:'#EADFC4',hair:'short',hc:'#D5D8DB'},sister:{c:'#4F7A5A',hair:'long',hc:'#2A1D18'}}[kd]||{};
  let ov='';
  if(kd==='old')ov=`<path d="M-62 40 Q-40 20 -14 -2 L0 40 L14 -2 Q40 20 62 40 L62 70 Q0 94 -62 70Z" fill="#8E5F86" ${st()}/><path d="M-30 52 Q0 66 30 52" fill="none" stroke="#fff" stroke-width="3" opacity=".5"/>`;
  if(kd==='young')ov=`<path d="M-30 -2 Q0 22 30 -2" fill="none" ${st(C.navy,4)}/><path d="M-10 14 V44 M10 14 V44" fill="none" ${st('#fff',4)}/><rect x="-34" y="66" width="68" height="30" rx="10" fill="none" ${st('#3E6648',4)}/>`;
  if(kd==='manager')ov=`<path d="M-8 -2 L0 12 L8 -2Z" fill="#fff" ${st(C.navy,3)}/><path d="M0 12 L-7 24 L0 70 L7 24Z" fill="${C.red}" ${st(C.navy,3)}/>`;
  if(kd==='shop')ov=`<path d="M-44 34 L44 34 L52 108 L-52 108Z" fill="#8B5E3C" ${st()}/><rect x="-26" y="62" width="52" height="30" rx="6" fill="#A9743F" ${st(C.navy,3)}/><path d="M-30 34 L-20 -4 M30 34 L20 -4" fill="none" ${st(C.navy,4)}/>`;
  const cap=kd==='shop'?`<g transform="translate(0,${f(bob)})"><path d="M-38 -66 Q-36 -98 0 -98 Q36 -98 38 -66Z" fill="#5C6A76" ${st()}/><rect x="-42" y="-72" width="84" height="10" rx="4" fill="#46535D" ${st(C.navy,3)}/></g>`:'';
  return `<g>${P.person(D,T)}<g transform="translate(0,${f(bob)})">${ov}</g>${cap}</g>`};

/* ---------- shout / speech burst. o.t text, o.fs, o.c ---------- */
P.e109_burst=(o,T,k)=>{let p='';const n=14,pu=1+.05*Math.sin(T*6);for(let i=0;i<n*2;i++){const a=i*Math.PI/n,r=(i%2?72:100)*pu;p+=`${f(Math.cos(a)*r)},${f(Math.sin(a)*r*.82)} `}
  return `<g><polygon points="${p}" fill="${o.c||C.gold}" ${st()}/><text x="0" y="${f((o.fs||70)*.34)}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${o.fs||70}" fill="${C.navy}">${o.t||'!'}</text></g>`};

/* ---------- thought cloud holding another prop: o.p prop name, o.o its options, o.s its scale ---------- */
P.e109_think=(o,T,k)=>{const inner=o.p&&P[o.p]?`<g transform="translate(0,-14) scale(${o.s||.6})">${P[o.p](o.o||{},T,k)}</g>`:'';
  const cl=[[0,-12,58],[-70,-20,48],[-30,-62,52],[28,-66,54],[72,-30,48],[66,26,44],[8,38,52],[-52,24,44]].map(([x,y,r])=>`<circle cx="${x}" cy="${y}" r="${r}"/>`).join('');
  return `<g><g fill="#fff" ${st(C.navy,5)}>${cl}</g><g fill="#fff">${cl}</g><circle cx="-80" cy="82" r="15" fill="#fff" ${st(C.navy,4)}/><circle cx="-102" cy="108" r="9" fill="#fff" ${st(C.navy,4)}/>${inner}</g>`};

/* ---------- shopping bags full of food ---------- */
P.e109_shopping=(o,T,k)=>{const sw=Math.sin(T*2)*2;
  const bag=(x,y,rot,c,items)=>`<g transform="translate(${x},${f(y+sw)}) rotate(${rot})">${items}<path d="M-40 -30 L-44 80 Q0 92 44 80 L40 -30Z" fill="${c}" ${st()}/><path d="M-40 -30 L-6 -16 L-44 80Z" fill="#000" opacity=".1"/><path d="M-22 -30 Q0 -62 22 -30" fill="none" ${st(C.navy,5)}/><rect x="-16" y="12" width="32" height="22" rx="5" fill="#fff" opacity=".8"/></g>`;
  const it1=`<g transform="rotate(-18)"><rect x="-8" y="-100" width="18" height="90" rx="9" fill="#E7B66B" ${st()}/><path d="M-4 -86 l10 6 M-4 -66 l10 6" fill="none" stroke="${C.goldD}" stroke-width="2.5"/></g><path d="M-24 -30 Q-34 -76 -20 -84 Q-6 -60 -8 -30Z" fill="${C.leaf}" ${st(C.navy,3)}/>`;
  const it2=`<circle cx="-12" cy="-40" r="20" fill="${C.orange}" ${st()}/><circle cx="16" cy="-44" r="18" fill="${C.red}" ${st()}/><path d="M16 -62 q4 -10 12 -10" fill="none" ${st(C.leaf,5)}/>`;
  return `<g>${_e109sh(100,96)}${bag(-46,8,-5,'#C79A62',it1)}${bag(48,20,6,'#E3C08A',it2)}</g>`};

/* ---------- knock on a door: a hand taps (o.n unused) ---------- */
P.e109_knock=(o,T,k)=>{const ph=Math.abs(Math.sin(T*6)),hx=-104+ph*30,hit=ph>.85;
  return `<g>${_e109sh(80,112)}<rect x="-64" y="-110" width="128" height="222" rx="8" fill="${C.brown}" ${st()}/><rect x="-46" y="-92" width="92" height="82" rx="6" fill="#A9743F" ${st(C.navy,3)}/><rect x="-46" y="6" width="92" height="88" rx="6" fill="#A9743F" ${st(C.navy,3)}/><circle cx="38" cy="10" r="8" fill="${C.gold}" ${st(C.navy,3)}/>
  ${hit?`<g ${st(C.red,5)} fill="none"><path d="M-72 -30 q-10 -12 -2 -26"/><path d="M-78 -8 q-14 -4 -22 -14"/><path d="M-72 -50 q-14 2 -24 -6" /></g>`:''}
  <g transform="translate(${f(hx)},-4)"><rect x="-40" y="-26" width="56" height="52" rx="20" fill="#E3AE82" ${st()}/><path d="M-6 -24 v18 M6 -24 v18 M18 -20 v14" fill="none" ${st('#B97F58',3)}/><rect x="-62" y="-14" width="26" height="30" rx="8" fill="${C.cream}" ${st()}/></g></g>`};

/* ---------- a padlock rattling with sound lines (strange noise at night) ---------- */
P.e109_noise=(o,T,k)=>{const j=Math.sin(T*26)*3,p=(T*2)%1;let w='';
  for(const sd of [-1,1])for(let i=0;i<3;i++){const q=(p+i/3)%1;w+=`<path d="M${sd*(58+q*40)} -34 Q${sd*(72+q*40)} 0 ${sd*(58+q*40)} 34" fill="none" ${st(C.goldD,5)} opacity="${f(1-q)}"/>`}
  return `<g>${w}<g transform="translate(${f(j)},0) scale(.9)">${P.e109_lock({s:'closed'},0,k)}</g></g>`};

/* ---------- evidence bag with the broken lock ---------- */
P.e109_evidence=(o,T,k)=>`<g>${_e109sh(90,100)}<path d="M-84 -66 L84 -66 L92 96 L-92 96Z" fill="#DCEBF3" fill-opacity=".75" ${st()}/><path d="M-70 -50 L-76 80" fill="none" stroke="#fff" stroke-width="6" opacity=".6"/><rect x="-86" y="-80" width="172" height="22" rx="4" fill="${C.red}" ${st()}/><line x1="-70" y1="-69" x2="70" y2="-69" stroke="#fff" stroke-width="3" opacity=".7"/><g transform="translate(0,22) scale(.62)">${P.e109_lock({s:'broken'},T,k)}</g><g transform="translate(60,-34) rotate(12)"><path d="M0 0 Q20 -26 40 -4" fill="none" ${st(C.navy,3)}/><rect x="14" y="-8" width="40" height="52" rx="5" fill="#fff" ${st()}/><line x1="22" y1="8" x2="46" y2="8" ${st('#9AA7B0',3)}/><line x1="22" y1="20" x2="46" y2="20" ${st('#9AA7B0',3)}/><line x1="22" y1="32" x2="38" y2="32" ${st('#9AA7B0',3)}/></g></g>`;

/* ---------- two officers walk the thief away, calmly ---------- */
P.e109_arrest=(o,T,k)=>`<g><g transform="translate(-108,6) scale(.8)">${P.e109_police({f:o.f},T)}</g><g transform="translate(108,6) scale(.8) scale(-1,1)">${P.e109_police({},T)}</g><g transform="translate(0,14) scale(.78)">${P.e109_thief({walk:1},T,k)}</g></g>`;

/* ---------- phone call. o.k police: a star badge on the screen ---------- */
P.e109_call=(o,T,k)=>{let w='';const p=(T*1.4)%1;for(let i=0;i<3;i++){const q=(p+i/3)%1;w+=`<path d="M${58+q*34} -30 q16 30 0 60" fill="none" ${st(C.goldD,5)} opacity="${f(1-q)}"/><path d="M${-58-q*34} -30 q-16 30 0 60" fill="none" ${st(C.goldD,5)} opacity="${f(1-q)}"/>`}
  return `<g>${w}<rect x="-48" y="-104" width="96" height="190" rx="18" fill="${C.navy}" ${st()}/><rect x="-40" y="-90" width="80" height="160" rx="8" fill="#EAF2F6"/><circle cx="0" cy="-26" r="30" fill="#2F5D9A" ${st(C.navy,3)}/>${_e109star(0,-26,20,C.gold,C.goldD)}<rect x="-24" y="14" width="48" height="8" rx="4" fill="#9AA7B0"/><rect x="-16" y="30" width="32" height="8" rx="4" fill="#C3CDD3"/><circle cx="0" cy="52" r="12" fill="${C.moss}" ${st(C.navy,3)}/><path d="M-5 52 q5 -7 10 0" fill="none" stroke="#fff" stroke-width="3"/><rect x="-14" y="-98" width="28" height="5" rx="2.5" fill="#46535D"/></g>`};

/* ---------- phone showing a photo of the bicycle ---------- */
P.e109_photophone=(o,T,k)=>{const fl=Math.max(0,Math.sin(T*2.2)-.9)*8;
  return `<g><rect x="-68" y="-112" width="136" height="224" rx="22" fill="${C.navy}" ${st()}/><clipPath id="e109_pp"><rect x="-58" y="-96" width="116" height="192" rx="10"/></clipPath><g clip-path="url(#e109_pp)"><rect x="-58" y="-96" width="116" height="192" fill="#DDEFF7"/><rect x="-58" y="20" width="116" height="76" fill="#C9D9A8"/><g transform="translate(0,-4) scale(.46)">${P.e109_bike({still:1,star:o.star},T,k)}</g>${fl>0?`<rect x="-58" y="-96" width="116" height="192" fill="#fff" opacity="${f(fl/8)}"/>`:''}</g><path d="M-46 -84 v-12 h12 M46 -84 v-12 h-12 M-46 84 v12 h12 M46 84 v12 h-12" fill="none" ${st('#fff',4)} opacity=".0"/><circle cx="0" cy="104" r="4" fill="#46535D"/></g>`};

/* ---------- web page with a bicycle for sale. o.star shows the star, o.k list = several results ---------- */
P.e109_web=(o,T,k)=>{const lst=o.k==='list';let c='';
  if(lst){for(let i=0;i<3;i++){const y=-26+i*44,ccs=['#D9534F','#5E9B63','#3E86C6'];c+=`<rect x="-92" y="${y}" width="184" height="38" rx="6" fill="#fff" ${st(C.navy,3)}/><g transform="translate(-66,${y+19}) scale(.11)">${P.e109_bike({c:ccs[i],still:1},T,k)}</g><line x1="-30" y1="${y+13}" x2="70" y2="${y+13}" ${st('#9AA7B0',4)}/><line x1="-30" y1="${y+26}" x2="30" y2="${y+26}" ${st('#C3CDD3',4)}/>`}}
  else c=`<rect x="-92" y="-30" width="120" height="104" rx="6" fill="#DDEFF7" ${st(C.navy,3)}/><g transform="translate(-32,30) scale(.42)">${P.e109_bike({still:1,star:o.star,zoom:o.zoom},T,k)}</g><rect x="42" y="-24" width="58" height="26" rx="6" fill="${C.red}" ${st(C.navy,3)}/><text x="71" y="-6" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="13" fill="#fff">SALE</text><line x1="42" y1="16" x2="98" y2="16" ${st('#9AA7B0',4)}/><line x1="42" y1="32" x2="86" y2="32" ${st('#C3CDD3',4)}/><rect x="42" y="46" width="58" height="24" rx="6" fill="${C.moss}" ${st(C.navy,3)}/>`;
  return `<g><rect x="-110" y="-96" width="220" height="190" rx="14" fill="#F4F7F9" ${st()}/><rect x="-110" y="-96" width="220" height="30" rx="14" fill="${_e109steel}" ${st()}/><rect x="-110" y="-80" width="220" height="14" fill="${_e109steel}"/><line x1="-110" y1="-66" x2="110" y2="-66" ${st(C.navy,4)}/><circle cx="-92" cy="-81" r="5" fill="${C.red}"/><circle cx="-76" cy="-81" r="5" fill="${C.gold}"/><circle cx="-60" cy="-81" r="5" fill="${C.leaf}"/><rect x="-44" y="-90" width="140" height="18" rx="9" fill="#fff" ${st(C.navy,2.5)}/><circle cx="82" cy="-81" r="4.5" fill="none" ${st(C.navy,2.5)}/><g transform="translate(0,-6)">${c}</g></g>`};

/* ---------- market with striped stalls ---------- */
P.e109_market=(o,T,k)=>{let s='';const stall=(x,c1,items)=>{let aw='';for(let i=0;i<6;i++)aw+=`<path d="M${x-48+i*16} -34 h16 v22 q-8 10 -16 0Z" fill="${i%2?'#fff':c1}" ${st(C.navy,3)}/>`;
    return `<g><rect x="${x-46}" y="-12" width="6" height="104" fill="${C.brown}" ${st(C.navy,3)}/><rect x="${x+40}" y="-12" width="6" height="104" fill="${C.brown}" ${st(C.navy,3)}/><path d="M${x-52} -34 L${x+52} -34 L${x+44} -52 L${x-44} -52Z" fill="${c1}" ${st()}/>${aw}<rect x="${x-50}" y="48" width="100" height="44" rx="4" fill="#C9A26A" ${st()}/>${items}</g>`};
  const crates=(x,cols)=>cols.map((c,i)=>`<circle cx="${x-30+i*20}" cy="40" r="10" fill="${c}" ${st(C.navy,3)}/>`).join('');
  s+=stall(-70,C.red,crates(-70,[C.orange,C.red,C.gold,C.leaf]))+stall(70,C.moss,crates(70,[C.leaf,C.gold,C.orange,C.red]));
  const bunt=`<path d="M-124 -88 Q0 -62 124 -88" fill="none" ${st(C.navy,3)}/>`+[-100,-60,-20,20,60,100].map((x,i)=>`<polygon points="${x-9},${-80+Math.abs(x)*.0+ (x*x)/900} ${x+9},${-80+(x*x)/900} ${x},${-62+(x*x)/900}" fill="${[C.red,C.gold,C.blue][i%3]}" ${st(C.navy,2)}/>`).join('');
  return `<g>${_e109sh(130,100)}${bunt}${s}${o.crowd?`<g transform="translate(0,66) scale(.8)">${P.crowd({n:5},T)}</g>`:''}</g>`};

/* ---------- day card (o.d = SAT ...) ---------- */
P.e109_day=(o,T,k)=>`<g><rect x="-90" y="-100" width="180" height="200" rx="16" fill="#fff" ${st()}/><path d="M-90 -84 Q-90 -100 -74 -100 L74 -100 Q90 -100 90 -84 L90 -44 L-90 -44Z" fill="${C.red}" ${st()}/><circle cx="-44" cy="-100" r="8" fill="${C.cream}" ${st(C.navy,3)}/><circle cx="44" cy="-100" r="8" fill="${C.cream}" ${st(C.navy,3)}/><circle cx="0" cy="-72" r="9" fill="#fff" opacity=".35"/><text x="0" y="40" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${(o.d||'SAT').length>3?56:78}" fill="${C.navy}">${o.d||'SAT'}</text></g>`;

/* ---------- sign hung on the gate: PLEASE LOCK THE GATE ---------- */
P.e109_gatesign=(o,T,k)=>{const sw=Math.sin(T*2)*2.5;
  return `<g><g>${[-100,-70,-40,-10,20,50,80,110].map(x=>`<line x1="${x}" y1="-124" x2="${x}" y2="116" ${st(C.navy,4)}/>`).join('')}<line x1="-120" y1="-96" x2="124" y2="-96" ${st('#46535D',6)}/></g>
  <g transform="rotate(${f(sw)} 0 -96)"><path d="M-60 -96 L-30 -66 M60 -96 L30 -66" fill="none" ${st(C.navy,3)}/><rect x="-100" y="-68" width="200" height="144" rx="12" fill="#FFE08A" ${st()}/><rect x="-90" y="-58" width="180" height="124" rx="7" fill="none" stroke="${C.red}" stroke-width="4"/><text x="0" y="-20" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="27" fill="${C.navy}">PLEASE</text><text x="0" y="16" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="28" fill="${C.red}">LOCK THE</text><text x="0" y="52" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="31" fill="${C.red}">GATE</text></g></g>`};

/* ---------- small locked room under the stairs (the bicycles' new home) ---------- */
P.e109_bikeroom=(o,T,k)=>`<g><rect x="-128" y="-96" width="256" height="196" fill="${_e109wall}" ${st()}/><polygon points="-128,100 -128,-60 -80,-60 -80,-30 -32,-30 -32,0 16,0 16,30 128,30 128,100" fill="#E7D3A6" opacity="0"/><polygon points="-128,-96 128,-96 128,-60 50,-60 50,-30 2,-30 2,0 -46,0 -46,30 -94,30 -94,60 -128,60" fill="#D2BE90" ${st()} opacity="0"/>
  <path d="M-128 20 L-128 -96 L0 -96 L128 -96" fill="none"/><polygon points="-128,100 -128,60 -90,60 -90,30 -52,30 -52,0 -14,0 -14,-30 24,-30 24,-60 62,-60 62,-90 128,-90 128,100" fill="#E7D3A6" ${st()}/><polygon points="-96,100 128,100 128,-84 100,-84 100,-60 66,-60 66,-34 28,-34 28,-4 -10,-4 -10,26 -48,26 -48,56 -86,56 -86,76" fill="#6F5A48" opacity=".42"/>
  <rect x="30" y="22" width="82" height="76" rx="4" fill="${C.brown}" ${st()}/><rect x="40" y="32" width="62" height="56" rx="3" fill="#A9743F" ${st(C.navy,3)}/><g transform="translate(96,64) scale(.26)">${P.e109_lock({s:'closed'},T,k)}</g><g transform="translate(-60,70) scale(.34)">${P.e109_bike({still:1,c:'#3E86C6'},T,k)}</g></g>`;

/* ---------- prison: a stone wall with a small barred window ---------- */
P.e109_prison=(o,T,k)=>{let br='';for(let r=0;r<6;r++)for(let c=0;c<5;c++)br+=`<rect x="${-110+c*44+(r%2)*-22}" y="${-96+r*34}" width="44" height="34" fill="${(r+c)%2?'#9AA7B0':'#8C99A5'}" ${st(C.navy,2.5)}/>`;
  return `<g><clipPath id="e109_pc"><rect x="-110" y="-96" width="220" height="190" rx="10"/></clipPath><g clip-path="url(#e109_pc)">${br}</g><rect x="-110" y="-96" width="220" height="190" rx="10" fill="none" ${st()}/><rect x="-46" y="-56" width="92" height="76" rx="6" fill="#2B3D48" ${st()}/><rect x="-38" y="-48" width="76" height="60" fill="#BFE3F2"/>${[-24,-8,8,24].map(x=>`<line x1="${x}" y1="-52" x2="${x}" y2="16" ${st(C.navy,6)}/>`).join('')}<rect x="-52" y="18" width="104" height="10" rx="4" fill="#6F8794" ${st()}/><g transform="translate(0,58) scale(.3)">${P.e109_lock({s:'closed'},T,k)}</g></g>`};

/* ---------- scales of justice. o.l / o.r = {p,o,s} things on the pans, o.tilt -1..1 (+ right side is heavier) ---------- */
P.e109_scales=(o,T,k)=>{const tl=(o.tilt||0)*10+Math.sin(T*1.6)*2,a=tl*Math.PI/180,L=84;
  const pan=(sd,it)=>{const ex=sd*L*Math.cos(a),ey=-70+sd*L*Math.sin(a);return `<g transform="translate(${f(ex)},${f(ey)})"><line x1="0" y1="0" x2="-34" y2="68" ${st(C.navy,3)}/><line x1="0" y1="0" x2="34" y2="68" ${st(C.navy,3)}/><path d="M-44 68 L44 68 Q36 92 0 92 Q-36 92 -44 68Z" fill="${C.gold}" ${st()}/>${it&&P[it.p]?`<g transform="translate(0,${f(44-(it.s||.34)*60)}) scale(${it.s||.34})">${P[it.p](it.o||{},T,k)}</g>`:''}</g>`};
  return `<g>${_e109sh(70,104)}<rect x="-8" y="-70" width="16" height="170" rx="6" fill="${C.goldD}" ${st()}/><path d="M-40 104 L40 104 L28 84 L-28 84Z" fill="${C.goldD}" ${st()}/><g transform="translate(0,-70) rotate(${f(tl)})"><rect x="-90" y="-7" width="180" height="14" rx="7" fill="${C.gold}" ${st()}/></g><circle cx="0" cy="-70" r="11" fill="${C.gold2}" ${st()}/>${pan(-1,o.l)}${pan(1,o.r)}</g>`};

/* ---------- wrench ---------- */
P.e109_wrench=(o,T,k)=>`<g transform="rotate(${f(-40+Math.sin(T*3)*8)})"><rect x="-10" y="-30" width="20" height="130" rx="9" fill="${_e109steel}" ${st()}/><path d="M-30 -30 Q-34 -84 -12 -92 L-12 -62 L12 -62 L12 -92 Q34 -84 30 -30Z" fill="${_e109steel}" ${st()}/><path d="M-6 -20 v110" stroke="#fff" stroke-width="4" opacity=".5" fill="none"/></g>`;

/* ---------- bank card ---------- */
P.e109_card=(o,T,k)=>`<g transform="rotate(${f(-8+Math.sin(T*1.6)*2)})">${_e109sh(90,80)}<rect x="-96" y="-60" width="192" height="120" rx="14" fill="${o.c||'#3E86C6'}" ${st()}/><rect x="-96" y="-36" width="192" height="26" fill="${C.navy}"/><rect x="-74" y="8" width="40" height="32" rx="6" fill="${C.gold}" ${st(C.goldD,3)}/><path d="M-74 24 h40 M-54 8 v32" fill="none" stroke="${C.goldD}" stroke-width="2.5"/><circle cx="48" cy="38" r="15" fill="#E2B653" opacity=".95"/><circle cx="66" cy="38" r="15" fill="${C.red}" opacity=".85"/><path d="M-90 -52 Q-30 -58 20 -52" fill="none" stroke="#fff" stroke-width="4" opacity=".35"/></g>`;

/* ---------- a bag with everything important around it: phone, money, keys, card ---------- */
P.e109_bagitems=(o,T,k)=>{const b=(i)=>Math.sin(T*2+i)*4;
  return `<g><g transform="translate(0,${f(8+b(0))}) scale(.78)">${P.bag({c:'#D96C8B'},T)}</g>
   <g transform="translate(-104,${f(-70+b(1))}) rotate(-10) scale(.42)">${P.e109_cover({c:C.navy},T)}</g>
   <g transform="translate(104,${f(-66+b(2))}) scale(.34)">${P.coins({},T)}</g>
   <g transform="translate(-100,${f(84+b(3))}) rotate(-8) scale(.46)">${P.keys({},T)}</g>
   <g transform="translate(104,${f(82+b(4))}) scale(.52)">${P.e109_card({},T)}</g></g>`};

/* ---------- phone, back view with a coloured cover (default green) ---------- */
P.e109_cover=(o,T,k)=>`<g><rect x="-60" y="-112" width="120" height="224" rx="22" fill="${o.c||'#4F9D6A'}" ${st()}/><rect x="-46" y="-98" width="46" height="46" rx="12" fill="${C.navy2}" ${st(C.navy,3)}/><circle cx="-31" cy="-83" r="9" fill="#3D6C8A" ${st(C.navy,2.5)}/><circle cx="-14" cy="-66" r="9" fill="#3D6C8A" ${st(C.navy,2.5)}/><circle cx="-30" cy="-65" r="3" fill="${C.gold}"/><path d="M-50 -20 Q-50 60 -34 96" fill="none" stroke="#fff" stroke-width="6" opacity=".25"/><circle cx="14" cy="8" r="20" fill="#fff" opacity=".12"/></g>`;

/* ---------- small restaurant table: plates, cups, two chairs, lamp ---------- */
P.e109_table=(o,T,k)=>`<g>${_e109sh(120,100)}<path d="M0 -112 V-70" ${st(C.navy,4)} fill="none"/><path d="M-30 -66 Q0 -112 30 -66Z" fill="${C.gold}" ${st()}/><circle cx="0" cy="-62" r="9" fill="#FFE08A" ${st(C.navy,3)}/>
  <rect x="-112" y="-20" width="30" height="64" rx="8" fill="${C.brown}" ${st()}/><rect x="-112" y="44" width="10" height="56" fill="${C.brown}" ${st(C.navy,3)}/><rect x="82" y="-20" width="30" height="64" rx="8" fill="${C.brown}" ${st()}/><rect x="102" y="44" width="10" height="56" fill="${C.brown}" ${st(C.navy,3)}/>
  <ellipse cx="0" cy="26" rx="84" ry="22" fill="#fff" ${st()}/><rect x="-8" y="46" width="16" height="54" fill="${C.brown}" ${st()}/><path d="M-30 100 h60" ${st(C.navy,6)}/><ellipse cx="-34" cy="22" rx="24" ry="8" fill="#F4EFE0" ${st(C.navy,3)}/><ellipse cx="-34" cy="19" rx="14" ry="4.5" fill="${C.orange}"/><g transform="translate(30,14)"><path d="M-14 -16 L14 -16 L10 12 Q0 18 -10 12Z" fill="#fff" ${st(C.navy,3)}/><path d="M14 -10 a8 8 0 0 1 0 14" fill="none" ${st(C.navy,3)}/>${[0,1].map(i=>`<path d="M${-5+i*8} -22 q-4 -8 0 -14" fill="none" ${st('#9AA7B0',3)} opacity="${f(.4+.4*Math.sin(T*3+i))}"/>`).join('')}</g></g>`;

/* ---------- hand on the shoulder. default: strap hangs empty, o.ghost = dotted outline of the missing bag, o.bag = the bag is still there ---------- */
P.e109_shoulder=(o,T,k)=>{const sw=Math.sin(T*3)*3,bg=o.bag;
  const strap=`<path d="M22 4 Q30 40 ${bg?'-8':f(10+sw)} ${bg?60:92}" fill="none" ${st(C.navy,14)}/><path d="M22 4 Q30 40 ${bg?'-8':f(10+sw)} ${bg?60:92}" fill="none" ${st('#8B5E3C',8)}/>`;
  const bagS=bg?`<g transform="translate(-36,66) scale(.42)">${P.bag({c:'#D96C8B'},T)}</g>`:'';
  const gh=o.ghost?`<rect x="-70" y="28" width="68" height="82" rx="20" fill="none" stroke="#8A9BA5" stroke-width="4" stroke-dasharray="9 8"/>`:'';
  return `<g><g transform="translate(-14,0)">${P.person({c:'#E2B653',hair:'bun',hc:'#2A1D18'},T)}${strap}${bagS}${gh}</g><g transform="translate(40,10)"><ellipse cx="0" cy="0" rx="22" ry="17" fill="#E3AE82" ${st()}/><path d="M-16 -2 h8 M-14 6 h8" ${st('#B97F58',3)} fill="none"/></g></g>`};

/* ---------- checking the water: a tap, falling drops and a clipboard ---------- */
P.e109_water=(o,T,k)=>{let d='';for(let i=0;i<3;i++){const p=(T*1.3+i/3)%1;d+=`<path d="M-62 ${f(-8+p*92)} q-6 10 0 16 q6 -6 0 -16Z" fill="${C.blue}" ${st(C.navy,2.5)} opacity="${f(1-p*.6)}"/>`}
  return `<g>${_e109sh(110,100)}<rect x="-116" y="-64" width="86" height="22" rx="6" fill="${_e109steel}" ${st()}/><path d="M-60 -52 L-60 -26 Q-60 -14 -72 -14 L-84 -14" fill="none" ${st(C.navy,22)}/><path d="M-60 -52 L-60 -26 Q-60 -14 -72 -14 L-84 -14" fill="none" ${st(_e109steel,12)}/><path d="M-78 -64 L-78 -88 M-96 -88 h36" ${st(C.red,8)} fill="none"/>${d}<path d="M-98 76 Q-62 96 -26 76 L-30 96 L-94 96Z" fill="#7FC9E6" ${st()}/>
  <g transform="translate(46,6) rotate(6)"><rect x="-44" y="-76" width="88" height="124" rx="8" fill="${C.brown}" ${st()}/><rect x="-34" y="-62" width="68" height="100" fill="#fff" ${st(C.navy,3)}/><rect x="-18" y="-82" width="36" height="16" rx="5" fill="${C.gold}" ${st()}/>${[0,1,2].map(i=>`<path d="M-26 ${-40+i*28} l5 6 l9 -11" fill="none" ${st(C.moss,3.5)}/><line x1="-6" y1="${-38+i*28}" x2="26" y2="${-38+i*28}" ${st('#9AA7B0',4)}/>`).join('')}</g></g>`};

/* ---------- hat shop ---------- */
P.e109_hatshop=(o,T,k)=>{let aw='';for(let i=0;i<8;i++)aw+=`<path d="M${-112+i*28} -52 h28 v26 q-14 14 -28 0Z" fill="${i%2?'#fff':C.red}" ${st(C.navy,3)}/>`;
  const hs=[['#6B5B4E','brim'],['#D96C8B','cap'],['#4F7A5A','brim'],['#E2B653','cap']];
  return `<g>${_e109sh(120,104)}<rect x="-112" y="-96" width="224" height="38" rx="8" fill="${C.navy2}" ${st()}/><text x="0" y="-68" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="30" fill="${C.cream}" letter-spacing="8">HATS</text>${aw}<rect x="-106" y="-26" width="212" height="128" fill="#F4E5C2" ${st()}/><rect x="-92" y="-14" width="116" height="84" rx="6" fill="${C.sky}" ${st(C.navy,3)}/><line x1="-92" y1="30" x2="24" y2="30" ${st('#C9A86E',5)}/>
  ${hs.map(([c,kd],i)=>`<g transform="translate(${-70+(i%2)*56},${i<2?12:56}) scale(.26)">${P.e109_hat({c,k:kd},T)}</g>`).join('')}<rect x="42" y="12" width="52" height="90" fill="${C.brown}" ${st()}/><circle cx="52" cy="58" r="4" fill="${C.gold}"/></g>`};

/* ---------- a bag hidden under a table (o.where under) or left on the table (o.where on) ---------- */
P.e109_hidden=(o,T,k)=>{const on=o.where==='on';
  return `<g>${_e109sh(110,100)}${on?'':`<rect x="-84" y="22" width="168" height="76" fill="#2B3D48"/><g transform="translate(-20,64) scale(.34)">${P.bag({c:'#D96C8B'},T)}</g>`}
  <rect x="-92" y="-14" width="184" height="40" fill="${on?'#E7D3A6':'#E7D3A6'}" opacity="0"/><path d="M-100 -4 L100 -4 L100 92 L-100 92Z" fill="#fff" opacity="0"/>
  <path d="M-96 8 L-96 98 L-84 88 L-72 98 L-60 88 L-48 98 L-36 88 L-24 98 L-12 88 L0 98 L12 88 L24 98 L36 88 L48 98 L60 88 L72 98 L84 88 L96 98 L96 8Z" fill="#E88CA2" ${st()} ${on?'':'opacity="0"'}/>
  ${on?`<path d="M-96 8 V98 H96 V8Z" fill="#E88CA2" ${st()}/>`:`<path d="M-96 8 V98 H-52 V40 Q-70 40 -96 8Z" fill="#E88CA2" ${st()}/><path d="M96 8 V98 H52 V8Z" fill="#E88CA2" ${st()}/>`}
  <ellipse cx="0" cy="4" rx="108" ry="22" fill="#A9743F" ${st()}/><ellipse cx="0" cy="0" rx="100" ry="17" fill="#C48B52"/>${on?`<g transform="translate(0,${f(-38+Math.sin(T*2)*2)}) scale(.46)">${P.bag({c:'#D96C8B'},T)}</g>`:`<g transform="translate(46,-14) scale(.28)">${P.coins({},T)}</g>`}</g>`};

/* ---------- old framed photograph of a grandmother, young (faceless portrait) ---------- */
P.e109_photo=(o,T,k)=>`<g transform="rotate(${f(-4+Math.sin(T*1.4)*1.5)})"><rect x="-82" y="-100" width="164" height="200" rx="8" fill="${C.brown}" ${st()}/><rect x="-66" y="-84" width="132" height="168" fill="#EBD9B8" ${st(C.navy,3)}/><clipPath id="e109_ph"><rect x="-66" y="-84" width="132" height="168"/></clipPath><g clip-path="url(#e109_ph)"><rect x="-66" y="-84" width="132" height="168" fill="#D9C39A"/><path d="M-66 84 L-66 40 Q-40 14 0 14 Q40 14 66 40 L66 84Z" fill="#8E6B5A" ${st(C.navy,3)}/><path d="M-14 14 L0 40 L14 14" fill="#F4EFE0" ${st(C.navy,3)}/><circle cx="0" cy="-22" r="34" fill="#E3C09A" ${st(C.navy,3)}/><path d="M-36 -26 Q-34 -66 0 -66 Q34 -66 36 -26 Q10 -48 -36 -26Z" fill="#4A3228" ${st(C.navy,3)}/><circle cx="0" cy="-72" r="14" fill="#4A3228" ${st(C.navy,3)}/></g><rect x="-66" y="-84" width="132" height="168" fill="#8B5E3C" opacity=".12"/></g>`;

/* ---------- a handbag with a secret pocket. o.pocket rings it, o.photo pulls the photo out, o.phone shows the phone top ---------- */
P.e109_bagopen=(o,T,k)=>{const pl=1+.05*Math.sin(T*4);
  return `<g>${_e109sh(100,104)}${o.phone!==0?`<g transform="translate(-24,-70) rotate(-8)"><rect x="-26" y="-46" width="52" height="96" rx="10" fill="#4F9D6A" ${st()}/><rect x="-18" y="-38" width="22" height="22" rx="6" fill="${C.navy2}" ${st(C.navy,2.5)}/></g>`:''}
  <path d="M-48 -44 Q-48 -118 0 -118 Q48 -118 48 -44" fill="none" ${st(C.navy,9)}/><path d="M-96 -40 L96 -40 L84 100 Q0 112 -84 100Z" fill="#B97B47" ${st()}/><path d="M-96 -40 L96 -40 L90 -12 Q0 6 -90 -12Z" fill="#9D6736" ${st()}/><circle cx="0" cy="-8" r="7" fill="${C.gold}" ${st(C.navy,3)}/>
  <rect x="-52" y="30" width="104" height="50" rx="12" fill="#D39A63" ${st()}/><path d="M-44 44 h88" ${st('#8B5E3C',4)} fill="none"/><rect x="-6" y="38" width="12" height="16" rx="3" fill="${C.gold}" ${st(C.navy,2.5)}/>
  ${o.photo?`<g transform="translate(112,-4) rotate(8) scale(.5)">${P.e109_photo({},T)}</g>`:''}
  ${o.pocket?`<g transform="translate(0,55) scale(${f(pl)})"><rect x="-64" y="-34" width="128" height="68" rx="18" fill="${C.gold}" fill-opacity=".18" ${st(C.red,5)}/></g>`:''}</g>`};

/* ---------- jacket with a pocket (keys / coins inside) ---------- */
P.e109_jacket=(o,T,k)=>{const sw=Math.sin(T*2)*1.5;
  return `<g>${_e109sh(90,106)}<path d="M-96 -20 L-56 -52 Q-18 -64 0 -50 Q18 -64 56 -52 L96 -20 L88 84 L58 84 L58 108 L-58 108 L-58 84 L-88 84Z" fill="#3F7F82" ${st()}/><path d="M-56 -52 L-18 -64 L0 -20 L-30 40 Z" fill="#336A6D" ${st(C.navy,3)}/><path d="M56 -52 L18 -64 L0 -20 L30 40 Z" fill="#336A6D" ${st(C.navy,3)}/><line x1="0" y1="-20" x2="0" y2="108" ${st(C.navy,3)}/><path d="M0 -20 L-30 40 M0 -20 L30 40" fill="none" ${st(C.navy,3)}/><path d="M-88 84 L-58 84 M58 84 L88 84" ${st(C.navy,3)} fill="none"/>
  <g transform="translate(-34,${f(40+sw*.3)})"><g transform="rotate(-8 0 0)"><rect x="-12" y="-36" width="9" height="44" rx="4" fill="${_e109steel}" ${st(C.navy,3)}/><circle cx="-8" cy="-40" r="9" fill="${C.gold}" ${st(C.navy,3)}/></g><path d="M-26 0 L26 0 L24 36 L-24 36Z" fill="#2F6A6D" ${st()}/><path d="M-26 0 L26 0 L24 12 Q0 20 -24 12Z" fill="#3F7F82" ${st(C.navy,3)}/></g></g>`};

/* ---------- gold TIP ribbon with the tip number ---------- */
P.e109_tip=(o,T,k)=>{const pu=1+.03*Math.sin(T*3);
  return `<g transform="scale(${f(pu)})"><path d="M-128 -22 L-98 -22 L-98 38 L-128 38 L-112 8Z" fill="${C.goldD}" ${st()}/><path d="M128 -22 L98 -22 L98 38 L128 38 L112 8Z" fill="${C.goldD}" ${st()}/><rect x="-104" y="-36" width="208" height="76" rx="14" fill="${C.gold}" ${st()}/><rect x="-96" y="-28" width="192" height="60" rx="9" fill="none" stroke="${C.goldD}" stroke-width="2.5" opacity=".6"/><text x="0" y="22" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${String(o.n).length>1?46:52}" fill="${C.navy}" letter-spacing="3">TIP ${o.n}</text></g>`};

/* ---------- ID card on a lanyard (the stranger shows you a company card) ---------- */
P.e109_idcard=(o,T,k)=>{const sw=Math.sin(T*1.8)*3;
  return `<g transform="rotate(${f(sw)} 0 -100)"><path d="M-30 -118 L0 -64 L30 -118" fill="none" ${st(C.navy,7)}/><path d="M-30 -118 L0 -64 L30 -118" fill="none" ${st(C.red,3.5)}/><rect x="-14" y="-72" width="28" height="14" rx="4" fill="${_e109steel}" ${st(C.navy,3)}/><rect x="-70" y="-60" width="140" height="170" rx="14" fill="#fff" ${st()}/><rect x="-70" y="-60" width="140" height="42" rx="14" fill="#2F5D9A" ${st()}/><rect x="-70" y="-36" width="140" height="18" fill="#2F5D9A"/><circle cx="-38" cy="-38" r="11" fill="${C.gold}" ${st(C.goldD,3)}/><line x1="-18" y1="-38" x2="46" y2="-38" ${st('#fff',5)}/><rect x="-48" y="-2" width="58" height="66" rx="8" fill="#D9E2E7" ${st(C.navy,3)}/><line x1="26" y1="6" x2="56" y2="6" ${st('#9AA7B0',5)}/><line x1="26" y1="24" x2="52" y2="24" ${st('#C3CDD3',5)}/><line x1="26" y1="42" x2="56" y2="42" ${st('#C3CDD3',5)}/><rect x="-48" y="78" width="104" height="10" rx="5" fill="#C3CDD3"/></g>`};

/* ---------- a door with a security chain, someone asks who it is (o.chain) ---------- */
P.e109_doorchain=(o,T,k)=>`<g>${_e109sh(80,112)}<rect x="-64" y="-110" width="128" height="222" rx="8" fill="${C.brown}" ${st()}/><rect x="-46" y="-92" width="92" height="82" rx="6" fill="#A9743F" ${st(C.navy,3)}/><rect x="-46" y="6" width="92" height="88" rx="6" fill="#A9743F" ${st(C.navy,3)}/><circle cx="0" cy="-60" r="11" fill="#fff" ${st(C.navy,4)}/><circle cx="0" cy="-60" r="5" fill="#3D6C8A"/><circle cx="38" cy="10" r="8" fill="${C.gold}" ${st(C.navy,3)}/><g transform="translate(20,-24)"><rect x="-30" y="-6" width="60" height="12" rx="6" fill="${_e109steel}" ${st(C.navy,3)}/>${[-18,-6,6,18].map(x=>`<rect x="${x-6}" y="-4" width="12" height="8" rx="4" fill="none" ${st(C.navy,2.5)}/>`).join('')}<circle cx="-28" cy="0" r="6" fill="${C.gold}" ${st(C.navy,3)}/></g></g>`;

/* ---------- social media post with holiday photo (o.t caption) ---------- */
P.e109_post=(o,T,k)=>`<g><rect x="-100" y="-114" width="200" height="226" rx="16" fill="#fff" ${st()}/><circle cx="-72" cy="-90" r="14" fill="${C.cold}" ${st(C.navy,3)}/><line x1="-48" y1="-96" x2="30" y2="-96" ${st('#9AA7B0',5)}/><line x1="-48" y1="-82" x2="-4" y2="-82" ${st('#C3CDD3',4)}/>
  <clipPath id="e109_pk"><rect x="-90" y="-66" width="180" height="116"/></clipPath><g clip-path="url(#e109_pk)"><rect x="-90" y="-66" width="180" height="116" fill="${C.sky}"/><circle cx="52" cy="-34" r="20" fill="#F6CE4B" ${st(C.goldD,3)}/><rect x="-90" y="-8" width="180" height="60" fill="${C.blue}"/><path d="M-90 4 q15 -8 30 0 t30 0 t30 0 t30 0 t30 0 t30 0" fill="none" stroke="#fff" stroke-width="3"/><rect x="-90" y="26" width="180" height="26" fill="#E7D3A6"/><g transform="translate(-30,8)"><line x1="0" y1="-8" x2="0" y2="40" ${st(C.navy,3)}/><path d="M-34 -4 Q0 -48 34 -4Z" fill="${C.red}" ${st()}/></g></g>
  <g transform="translate(-72,72) scale(.5)">${P.heart({},T)}</g><text x="-40" y="94" font-family="Fraunces" font-weight="800" font-size="26" fill="${C.navy}">${o.t||'2 weeks!'}</text></g>`;

/* ---------- dark empty house with the door left open (o.open) ---------- */
P.e109_emptyhouse=(o,T,k)=>`<g>${_e109sh(120,98)}<rect x="-92" y="-10" width="184" height="104" fill="#C9B88F" ${st()}/><polygon points="-112,-8 0,-96 112,-8" fill="#8F4A47" ${st()}/><rect x="42" y="-76" width="26" height="46" fill="#6F4A2E" ${st()}/><rect x="-78" y="8" width="38" height="38" fill="#2B3D48" ${st()}/><rect x="40" y="8" width="38" height="38" fill="#2B3D48" ${st()}/><line x1="-59" y1="8" x2="-59" y2="46" ${st(C.navy,3)}/><line x1="59" y1="8" x2="59" y2="46" ${st(C.navy,3)}/><rect x="-20" y="30" width="40" height="64" fill="#2B3D48" ${st()}/>${o.open?`<path d="M-20 30 L-44 40 L-44 94 L-20 94Z" fill="${C.brown}" ${st()}/><path d="M${f(-8+Math.sin(T*3)*3)} 62 h24" fill="none" ${st(C.red,6)} opacity="0"/>`:`<rect x="-20" y="30" width="40" height="64" fill="${C.brown}" ${st()}/><circle cx="10" cy="64" r="4" fill="${C.gold}"/>`}</g>`;

/* ---------- keypad with a hidden number (dots), o.n how many dots ---------- */
P.e109_pin=(o,T,k)=>{let b='';for(let i=0;i<9;i++)b+=`<circle cx="${-36+(i%3)*36}" cy="${-4+Math.floor(i/3)*36}" r="13" fill="#fff" ${st(C.navy,3)}/><text x="${-36+(i%3)*36}" y="${1+Math.floor(i/3)*36}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="15" fill="${C.navy}">${i+1}</text>`;
  const n=o.n==null?4:o.n;let d='';for(let i=0;i<4;i++)d+=`<circle cx="${-33+i*22}" cy="-58" r="7" fill="${i<n?C.gold:'#3C4B56'}"/>`;
  return `<g><rect x="-64" y="-100" width="128" height="196" rx="16" fill="${C.navy2}" ${st()}/><rect x="-50" y="-86" width="100" height="56" rx="8" fill="#1A2830"/>${d}<g transform="translate(0,2)">${b}</g><circle cx="-36" cy="104" r="0" fill="none"/></g>`};

/* ---------- person holding the bag in front of the body, crowd behind ---------- */
P.e109_holdbag=(o,T,k)=>`<g><g transform="translate(0,-74) scale(.6)" opacity=".95">${P.crowd({n:6},T)}</g><g transform="translate(0,46) scale(.8)">${P.person({c:'#E2B653',hair:'bun',hc:'#2A1D18'},T)}<path d="M30 -2 Q40 40 -6 60" fill="none" ${st(C.navy,12)}/><path d="M30 -2 Q40 40 -6 60" fill="none" ${st('#8B5E3C',6)}/><rect x="-40" y="34" width="80" height="64" rx="16" fill="#3E86C6" ${st()}/><path d="M-40 52 h80" ${st(C.navy,4)} fill="none"/><circle cx="0" cy="68" r="6" fill="${C.gold}" ${st(C.navy,3)}/><ellipse cx="-42" cy="70" rx="14" ry="12" fill="#E3AE82" ${st()}/><ellipse cx="42" cy="70" rx="14" ry="12" fill="#E3AE82" ${st()}/></g></g>`;

/* ---------- trousers: front (phone safe in the front pocket) or o.back (phone sticking out of the back pocket) ---------- */
P.e109_pants=(o,T,k)=>{const bk=o.back,sw=Math.sin(T*3)*2;
  const body=`<path d="M-56 -96 L56 -96 L62 104 L10 104 L0 -6 L-10 104 L-62 104Z" fill="#4A6FA5" ${st()}/><rect x="-56" y="-96" width="112" height="20" fill="#3A5885" ${st()}/><path d="M-30 -96 v20 M30 -96 v20 M0 -96 v20" ${st(C.navy,3)} fill="none"/><path d="M0 -76 V-6" ${st('#3A5885',3)} fill="none"/>`;
  const ph=(x,y,rot,col)=>`<g transform="translate(${x},${y}) rotate(${rot})"><rect x="-13" y="-34" width="26" height="46" rx="5" fill="${col||C.navy}" ${st(C.navy,3)}/><rect x="-9" y="-30" width="18" height="30" rx="2" fill="#BFE3F2"/></g>`;
  if(bk)return `<g>${_e109sh(70,108)}${body}<path d="M-48 -52 L-8 -52 L-8 -4 L-28 8 L-48 -4Z" fill="#4A6FA5" ${st(C.navy,3.5)}/><path d="M-42 -46 L-14 -46 L-14 -8 L-28 2 L-42 -8Z" fill="none" stroke="#C9D9F0" stroke-width="2" stroke-dasharray="5 4"/><path d="M48 -52 L8 -52 L8 -4 L28 8 L48 -4Z" fill="#4A6FA5" ${st(C.navy,3.5)}/>${ph(28,f(-40+sw),8,'#E2B653')}<path d="M48 -52 L8 -52 L8 -4 L28 8 L48 -4Z" fill="none" opacity="0"/><path d="M12 -24 L44 -24 L48 -4 L28 8 L8 -4Z" fill="#4A6FA5" ${st(C.navy,3.5)}/></g>`;
  return `<g>${_e109sh(70,108)}${body}<path d="M-14 -94 Q-14 -50 -50 -38" fill="none" ${st(C.navy,3.5)}/><path d="M14 -94 Q14 -50 50 -38" fill="none" ${st(C.navy,3.5)}/>${ph(30,-66,6)}<path d="M18 -62 Q30 -58 44 -62 L48 -40 Q30 -34 14 -42Z" fill="#4A6FA5" ${st(C.navy,3.5)}/><path d="M16 -92 Q16 -50 52 -38" fill="none" opacity="0"/></g>`};

/* ---------- gift box ---------- */
P.e109_gift=(o,T,k)=>`<g transform="rotate(${f(Math.sin(T*2.4)*3)})">${_e109sh(80,90)}<rect x="-76" y="-8" width="152" height="96" rx="8" fill="${C.red}" ${st()}/><rect x="-86" y="-34" width="172" height="36" rx="8" fill="#E86A66" ${st()}/><rect x="-16" y="-34" width="32" height="122" fill="${C.gold}" ${st()}/><path d="M0 -34 Q-52 -90 -50 -48 Q-48 -30 0 -34Z M0 -34 Q52 -90 50 -48 Q48 -30 0 -34Z" fill="${C.gold}" ${st()}/><circle cx="0" cy="-34" r="11" fill="${C.goldD}" ${st()}/></g>`;

/* ---------- stop sign ---------- */
P.e109_stop=(o,T,k)=>{let p='';for(let i=0;i<8;i++){const a=Math.PI/8+i*Math.PI/4;p+=`${f(Math.cos(a)*92)},${f(Math.sin(a)*92)} `}
  return `<g transform="rotate(${f(Math.sin(T*3)*2)})"><rect x="-8" y="60" width="16" height="70" fill="#9FB0BA" ${st()}/><polygon points="${p}" fill="${C.red}" ${st()}/><polygon points="${p.split(' ').filter(Boolean).map(q=>q.split(',').map(v=>f(v*.86)).join(',')).join(' ')}" fill="none" stroke="#fff" stroke-width="5"/><text x="0" y="17" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="46" fill="#fff" letter-spacing="2">STOP</text></g>`};

/* ---------- go back to the last place: a U-turn arrow to a map pin ---------- */
P.e109_goback=(o,T,k)=>{const off=-(T*40)%24;
  return `<g><path d="M84 70 C90 -60 -70 -60 -70 14" fill="none" ${st('#9AA7B0',12)} stroke-dasharray="14 10" stroke-dashoffset="${f(off)}"/><path d="M84 70 C90 -60 -70 -60 -70 14" fill="none" ${st(C.moss,6)} stroke-dasharray="14 10" stroke-dashoffset="${f(off)}"/><path d="M-92 4 L-70 34 L-48 4Z" fill="${C.moss}" ${st(C.navy,4)}/><g transform="translate(-70,${f(86+Math.sin(T*3)*3)}) scale(.8)"><path d="M0 40 C-34 -2 -30 -40 0 -40 C30 -40 34 -2 0 40Z" fill="${C.red}" ${st()}/><circle cx="0" cy="-12" r="12" fill="#fff" ${st(C.navy,3)}/></g><g transform="translate(84,70) scale(.5)">${P.person({c:'#E2B653',hair:'bun',hc:'#2A1D18'},T)}</g></g>`};

/* ---------- suitcase for a holiday ---------- */
P.e109_suitcase=(o,T,k)=>`<g>${_e109sh(100,100)}<path d="M-30 -44 v-26 Q-30 -82 -18 -82 L18 -82 Q30 -82 30 -70 v26" fill="none" ${st(C.navy,10)}/><rect x="-92" y="-48" width="184" height="144" rx="18" fill="#C0583E" ${st()}/><rect x="-62" y="-48" width="16" height="144" fill="#8F3E2A" opacity=".55"/><rect x="46" y="-48" width="16" height="144" fill="#8F3E2A" opacity=".55"/><rect x="-14" y="-12" width="28" height="22" rx="5" fill="${C.gold}" ${st(C.navy,3)}/><circle cx="-30" cy="46" r="15" fill="${C.sky}" ${st(C.navy,3)}/><path d="M-37 46 h14 M-30 39 v14" ${st(C.navy,2.5)} fill="none"/><circle cx="34" cy="50" r="13" fill="${C.gold}" ${st(C.navy,3)}/>${_e109star(34,50,8,'#fff',C.goldD)}</g>`;

/* ---------- somebody checks a neighbour's door (hand on the handle, lock closed) ---------- */
P.e109_checkdoor=(o,T,k)=>{const ph=Math.sin(T*2.4)*3;
  return `<g>${_e109sh(120,112)}<rect x="30" y="-110" width="100" height="222" rx="8" fill="${C.brown}" ${st()}/><rect x="44" y="-94" width="72" height="80" rx="6" fill="#A9743F" ${st(C.navy,3)}/><rect x="44" y="2" width="72" height="90" rx="6" fill="#A9743F" ${st(C.navy,3)}/><circle cx="48" cy="12" r="8" fill="${C.gold}" ${st(C.navy,3)}/><g transform="translate(-72,18) scale(.9)">${P.e109_neighbour({k:'young'},T)}</g><g transform="translate(${f(24+ph)},12)"><ellipse cx="0" cy="0" rx="17" ry="13" fill="#E3AE82" ${st()}/></g><path d="M-24 40 Q10 40 24 12" fill="none" ${st('#3E6648',14)}/><path d="M-24 40 Q10 40 24 12" fill="none" ${st('#4F7A5A',8)}/></g>`};

/* ---------- shield with a check: much safer ---------- */
P.e109_shield=(o,T,k)=>{const pu=1+.03*Math.sin(T*3);
  return `<g transform="scale(${f(pu)})"><path d="M0 -104 L88 -68 V6 Q88 70 0 108 Q-88 70 -88 6 V-68Z" fill="${C.blue}" ${st()}/><path d="M0 -88 L72 -58 V4 Q72 58 0 92Z" fill="#fff" opacity=".18"/><path d="M-40 4 L-10 36 L44 -26" fill="none" ${st('#fff',16)}/></g>`};

/* ---------- medal with ribbon (the hero) ---------- */
P.e109_medal=(o,T,k)=>`<g transform="rotate(${f(Math.sin(T*2)*4)} 0 -80)"><path d="M-44 -108 L-4 -20 L-28 -14 L-64 -96Z" fill="${C.red}" ${st()}/><path d="M44 -108 L4 -20 L28 -14 L64 -96Z" fill="#fff" ${st()}/><circle cx="0" cy="26" r="54" fill="${C.gold}" ${st()}/><circle cx="0" cy="26" r="40" fill="none" ${st(C.goldD,4)}/>${_e109star(0,26,32,'#fff',C.goldD)}</g>`;

/* ---------- detective: magnifying glass over a fingerprint ---------- */
P.e109_fingerprint=(o,T,k)=>{let r='';for(let i=1;i<=6;i++)r+=`<path d="M${-i*8} 20 a${i*8} ${i*9} 0 0 1 ${i*16} 0" fill="none" ${st('#6F8794',3.5)}/><path d="M${-i*8+4} 34 q${-3} 26 ${i*2} 40" fill="none" ${st('#6F8794',3.5)} opacity=".0"/>`;
  const sw=Math.sin(T*1.6)*10;
  return `<g><rect x="-100" y="-90" width="150" height="190" rx="12" fill="#F4EFE0" ${st()}/><g transform="translate(-26,0)">${r}<path d="M-48 28 q0 36 12 50 M-32 30 q0 28 8 44 M-16 30 q0 26 4 40 M0 30 v42 M16 30 q0 28 -4 44 M32 30 q0 26 -8 40" fill="none" ${st('#6F8794',3.5)}/></g><g transform="translate(${f(20+sw)},${f(10-sw*.4)})"><circle cx="30" cy="-10" r="52" fill="#BFE3F2" fill-opacity=".35" ${st(C.navy,8)}/><path d="M16 -40 Q30 -52 48 -44" fill="none" stroke="#fff" stroke-width="5" opacity=".7"/><line x1="68" y1="30" x2="112" y2="76" ${st(C.navy,16)}/><line x1="68" y1="30" x2="112" y2="76" ${st(C.brown,8)}/></g></g>`};

const _e109iPlate=(id,c1,c2,T,ring)=>`<defs><radialGradient id="${id}" cx="50%" cy="40%" r="65%"><stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></radialGradient></defs><circle r="136" fill="${c1}" opacity="${f(.10+.04*Math.sin(T*1.5))}"/><circle r="126" fill="url(#${id})"/><circle r="126" fill="none" stroke="${ring}" stroke-width="3" opacity=".7"/><circle r="136" fill="none" stroke="${ring}" stroke-width="2" stroke-dasharray="3 11" opacity=".55" transform="rotate(${f(T*8)})"/>`;
const _e109iSp=(x,y,s,T,ph,col)=>{const a=.5+.5*Math.sin(T*2.4+ph),z=s*(.55+.45*a);return `<path transform="translate(${x},${y}) scale(${f(z)})" d="M0,-1 Q.14,-.14 1,0 Q.14,.14 0,1 Q-.14,.14 -1,0 Q-.14,-.14 0,-1Z" fill="${col||'#FFE9A0'}" opacity="${f(.45+.55*a)}"/>`};
/* Episode 109 intro hero: shield + padlock + key + flashlight beam (staying safe) */
P.e109_ihero=(o,T,k)=>{const b=(i,a,s=1.5)=>Math.sin(T*s+i)*a;
const sh='M0,-104 L78,-74 V-8 C78,44 38,82 0,102 C-38,82 -78,44 -78,-8 V-74Z';
const sweep=((T*.5)%1.6)*220-130;
return `<g>${_e109iPlate('e109i_p','#35557A','#121D2A',T,'#7BD3F0')}
<defs><linearGradient id="e109i_s" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#7CCBF5"/><stop offset="1" stop-color="#2A67B0"/></linearGradient>
<linearGradient id="e109i_l" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFE186"/><stop offset="1" stop-color="#E0A02A"/></linearGradient>
<linearGradient id="e109i_k" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FFE186"/><stop offset="1" stop-color="#D99A2B"/></linearGradient>
<linearGradient id="e109i_bm" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FFF6C8" stop-opacity=".55"/><stop offset="1" stop-color="#FFF6C8" stop-opacity="0"/></linearGradient>
<clipPath id="e109i_c"><path d="${sh}"/></clipPath></defs>
${_e109iSp(-104,40,7,T,0)}${_e109iSp(108,-70,8,T,2)}${_e109iSp(100,20,5,T,4)}
<g transform="translate(0,${f(b(0,3,1.4))})"><path d="${sh}" transform="translate(0,6)" fill="#000" opacity=".25"/>
<path d="${sh}" fill="url(#e109i_s)" ${st(C.navy,5.5)}/>
<g clip-path="url(#e109i_c)"><path d="M-70,-100 L-20,-100 L-70,40Z" fill="#fff" opacity=".12"/><g transform="translate(${f(sweep)},0) rotate(20)"><rect x="-9" y="-160" width="16" height="320" fill="#fff" opacity=".22"/></g></g>
<path d="M0,-88 L64,-64 V-8 C64,36 32,68 0,86 C-32,68 -64,36 -64,-8 V-64Z" fill="none" stroke="#fff" stroke-width="2.5" opacity=".55"/>
<g transform="translate(0,4)"><path d="M-21,-4 V-26 A21,21 0 0 1 21,-26 V-4" fill="none" ${st(C.navy,14)} transform="translate(0,${f(Math.max(0,b(0,0))) })"/><path d="M-21,-4 V-26 A21,21 0 0 1 21,-26 V-4" fill="none" ${st('#E3EAF0',7)}/>
<rect x="-36" y="-6" width="72" height="58" rx="12" fill="url(#e109i_l)" ${st(C.navy,5)}/><rect x="-30" y="-1" width="60" height="10" rx="5" fill="#fff" opacity=".35"/>
<circle cx="0" cy="18" r="8" fill="${C.navy}"/><path d="M-4,22 L-6,38 H6 L4,22Z" fill="${C.navy}"/></g></g>
<g transform="translate(-112,-86) rotate(40)"><polygon points="12,-12 140,-52 140,52 12,12" fill="url(#e109i_bm)" opacity="${f(.65+.25*Math.sin(T*2))}" transform="rotate(${f(b(0,4,1.2))})"/><rect x="-26" y="-9" width="38" height="18" rx="5" fill="#8CA0AE" ${st(C.navy,3.5)}/><path d="M12,-14 L26,-18 V18 L12,14Z" fill="#FFD36B" ${st(C.navy,3.5)}/></g>
<g transform="translate(86,${f(70+b(2,4))}) rotate(${f(-30+b(1,7))})"><circle cx="-26" cy="0" r="15" fill="url(#e109i_k)" ${st(C.navy,4.5)}/><circle cx="-26" cy="0" r="6" fill="#26343E"/><rect x="-12" y="-5.5" width="52" height="11" rx="3" fill="url(#e109i_k)" ${st(C.navy,4.5)}/><path d="M26,5 V17 H33 V5 M36,5 V13 H42 V5" fill="url(#e109i_k)" ${st(C.navy,3.5)}/></g>
</g>`};

/* A2 ep 9 props end */
/* A2 ep 10 props begin */
/* Episode 110 props: exams, essays, bad marks and good methods (study stories). Faceless. Uses C, st, f, ease, clamp, P. */
const _e110sh=(rx,y)=>`<ellipse cx="0" cy="${y}" rx="${rx}" ry="${f(rx*.09)}" fill="#1E2B33" opacity=".15"/>`;
const _e110steel='#B9C6CE',_e110steelD='#7C909C',_e110paper='#FFFEF8';
const _e110star=(x,y,r,fill,stroke)=>{let p='';for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*.45:r;p+=`${f(x+Math.cos(a)*rr)},${f(y+Math.sin(a)*rr)} `}return `<polygon points="${p}" fill="${fill}" ${st(stroke||C.goldD,3)}/>`};
const _e110x=(x,y,r,col)=>`<g ${st(col||C.red,5)} fill="none"><line x1="${x-r}" y1="${y-r}" x2="${x+r}" y2="${y+r}"/><line x1="${x+r}" y1="${y-r}" x2="${x-r}" y2="${y+r}"/></g>`;
const _e110ticks=(x,y,r)=>`<path d="M${x-r} ${y} l${r*.6} ${r*.7} l${r*1.2} ${-r*1.5}" fill="none" ${st(C.moss,5)}/>`;

/* ---------- exam paper. o.score + o.sub (red circled mark), o.errs (red crosses, up to 12), o.tick (green ticks), o.k 'q' = numbered questions (easy ones green, hard ones orange), o.n stack of n papers ---------- */
P.e110_exam=(o,T,k)=>{
  const one=(ox,oy,rot)=>{let s='';
    s+=`<rect x="-80" y="-108" width="160" height="216" rx="8" fill="${_e110paper}" ${st()}/><rect x="-62" y="-90" width="70" height="9" rx="4" fill="${C.cold}"/><line x1="-62" y1="-70" x2="40" y2="-70" ${st('#C3CDD3',3)}/>`;
    if(o.k==='q'){const E=[1,1,0,0];for(let i=0;i<4;i++){const y=-44+i*40;s+=`<circle cx="-56" cy="${y}" r="13" fill="${E[i]?C.moss:C.orange}" ${st(C.navy,3)}/><text x="-56" y="${y+6}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="17" fill="#fff">${i+1}</text><line x1="-34" y1="${y}" x2="${E[i]?56:62}" y2="${y}" ${st('#9AA7B0',5)}/>${E[i]?'':`<line x1="-34" y1="${y+12}" x2="30" y2="${y+12}" ${st('#C3CDD3',4)}/>`}`}}
    else{for(let i=0;i<6;i++){const y=-48+i*28;s+=`<line x1="-62" y1="${y}" x2="${[58,44,62,36,56,48][i]}" y2="${y}" ${st('#C3CDD3',4)}/>`}}
    const n=Math.min(12,o.errs||0),pos=[[40,-48],[-30,-20],[48,8],[-40,36],[20,36],[-6,-48],[52,-20],[-52,8],[2,64],[44,64],[-46,64],[16,-20]];
    for(let i=0;i<n;i++)s+=_e110x(pos[i][0],pos[i][1],7);
    if(o.tick)for(let i=0;i<o.tick;i++)s+=_e110ticks(-58+i*30,70,7);
    if(o.score!=null){s+=`<g transform="translate(${o.sub?20:34},-72) rotate(-8)"><ellipse rx="${o.sub?58:(String(o.score).length>2?44:38)}" ry="27" fill="#fff" fill-opacity=".9" ${st(C.red,4)}/><text x="${o.sub?-18:0}" y="12" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${o.sub?30:38}" fill="${C.red}">${o.score}</text>${o.sub?`<text x="20" y="11" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="19" fill="${C.red}">${o.sub}</text>`:''}</g>`}
    return `<g transform="translate(${ox},${oy}) rotate(${rot})">${s}</g>`};
  const n=o.n||1;let g='';for(let i=n-1;i>=0;i--)g+=one(i*22-(n-1)*11,-i*8+(n-1)*4,i*4-(n-1)*2+Math.sin(T*1.5)*0.6);
  return `<g>${_e110sh(100,116)}${g}</g>`};

/* ---------- score bar 0..100 with a pass line at 50 (o.v value, o.pass) ---------- */
P.e110_bar=(o,T,k)=>{const v=o.v==null?28:o.v,ps=o.pass==null?50:o.pass,g=ease((k-.2)/1.0),W=240,x0=-120,col=v<ps?C.red:C.moss,vx=x0+W*v/100*g;
  return `<g><rect x="${x0}" y="-18" width="${W}" height="36" rx="18" fill="#E9EEF1" ${st()}/><clipPath id="e110_bc"><rect x="${x0}" y="-18" width="${W}" height="36" rx="18"/></clipPath><g clip-path="url(#e110_bc)"><rect x="${x0}" y="-18" width="${f(Math.max(0,vx-x0))}" height="36" fill="${col}"/></g><rect x="${x0}" y="-18" width="${W}" height="36" rx="18" fill="none" ${st()}/>
  <line x1="${x0+W*ps/100}" y1="-44" x2="${x0+W*ps/100}" y2="34" ${st(C.navy,4)} stroke-dasharray="7 6"/><text x="${x0+W*ps/100}" y="-52" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="26" fill="${C.navy}">${ps}</text>
  <text x="${x0}" y="62" text-anchor="middle" font-family="Fraunces" font-weight="700" font-size="22" fill="${C.navy2}">0</text><text x="${x0+W}" y="62" text-anchor="middle" font-family="Fraunces" font-weight="700" font-size="22" fill="${C.navy2}">100</text>
  <g transform="translate(${f(vx)},0)"><circle r="23" fill="${C.cream}" ${st(col,6)}/><text y="9" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${v>99?18:24}" fill="${C.navy}">${v}</text></g></g>`};

/* ---------- results posted on a board outside the office; o.n = the highlighted score ---------- */
P.e110_results=(o,T,k)=>{let r='';for(let i=0;i<5;i++){const y=-44+i*28,hi=i===2;r+=`<rect x="-62" y="${y-11}" width="124" height="22" rx="4" fill="${hi?C.gold:'#F1F4F6'}" ${hi?st(C.goldD,3):''}/><line x1="-52" y1="${y}" x2="${hi?-8:-14}" y2="${y}" ${st('#9AA7B0',4)}/>${hi?`<text x="46" y="${y+7}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="20" fill="${C.red}">${o.n||28}</text>`:`<line x1="34" y1="${y}" x2="52" y2="${y}" ${st('#C3CDD3',4)}/>`}`}
  return `<g>${_e110sh(110,110)}<rect x="-104" y="-104" width="208" height="206" rx="10" fill="#C9A26A" ${st()}/><rect x="-92" y="-92" width="184" height="182" rx="6" fill="#DDBB82"/><g transform="translate(0,-2) rotate(-1.5)"><rect x="-72" y="-82" width="144" height="170" rx="4" fill="#fff" ${st(C.navy,3)}/><rect x="-62" y="-76" width="124" height="18" fill="${C.cold}" opacity=".5"/>${r}</g><circle cx="0" cy="-90" r="7" fill="${C.red}" ${st(C.navy,3)}/></g>`};

/* ---------- people (faceless). o.k prof | prof2 (woman professor) | lab (lab teacher) | dad | mum | friend | sara | cousin | brother ---------- */
P.e110_pp=(o,T,k)=>{const kd=o.k||'prof',bob=Math.sin(T*2+(o.ph||0))*2;
  const D={prof:{c:'#8B6B4A',hair:'short',hc:'#D5D8DB'},prof2:{c:'#3F7F82',hair:'long',hc:'#6A3F26'},lab:{c:'#FFFFFF',hair:'bun',hc:'#6A3F26'},dad:{c:'#8E6BB5',hair:'short',hc:'#222'},mum:{c:'#D96C8B',hair:'long',hc:'#3A2A22'},friend:{c:'#4F7A5A',hair:'short',hc:'#3A2A22'},sara:{c:'#E07A5F',hair:'long',hc:'#2A1D18'},cousin:{c:'#FFFFFF',hair:'short',hc:'#3A2A22'},brother:{c:'#F2994A',hair:'short',hc:'#3A2A22'}}[kd]||{};
  let ov='';
  if(kd==='prof')ov=`<path d="M-8 -2 L0 12 L8 -2Z" fill="#fff" ${st(C.navy,3)}/><path d="M0 12 L-6 22 L0 64 L6 22Z" fill="${C.red}" ${st(C.navy,3)}/><path d="M-62 36 Q-40 20 -14 -2 L0 40 L14 -2 Q40 20 62 36" fill="none" ${st(C.navy,3)}/>`;
  if(kd==='prof2')ov=`<path d="M-30 -2 Q0 22 30 -2" fill="none" ${st(C.navy,4)}/><line x1="0" y1="18" x2="0" y2="108" ${st(C.navy,3)}/><circle cx="0" cy="40" r="3.5" fill="${C.gold}"/><circle cx="0" cy="62" r="3.5" fill="${C.gold}"/>`;
  if(kd==='lab'||kd==='cousin')ov=`<path d="M-14 -4 L0 30 L14 -4" fill="${kd==='lab'?'#4DA3D8':'#4DA3D8'}" ${st(C.navy,3)}/><line x1="0" y1="30" x2="0" y2="108" ${st(C.navy,3)}/><rect x="-46" y="60" width="26" height="22" rx="4" fill="none" ${st(C.navy,3)}/>`;
  if(kd==='dad')ov=`<path d="M-8 -2 L0 12 L8 -2Z" fill="#fff" ${st(C.navy,3)}/>`;
  return `<g>${P.person(D,T)}<g transform="translate(0,${f(bob)})">${ov}</g></g>`};

/* ---------- lecture hall: green board with a molecule, lecturer, rows of students seen from behind. o.front = star on the front-row seat, o.ghost = the empty (missed) seat ---------- */
P.e110_lecture=(o,T,k)=>{let seats='';const cols=['#D96C8B','#4DA3D8','#5E9B63','#F2994A','#8E6BB5'];
  for(let r=0;r<2;r++)for(let i=0;i<5;i++){const x=-96+i*48,y=40+r*50,gh=o.ghost&&r===1&&i===2,fr=o.front&&r===1&&i===2;
    seats+=gh?`<rect x="${x-17}" y="${y-8}" width="34" height="40" rx="8" fill="none" stroke="#8A9BA5" stroke-width="3.5" stroke-dasharray="7 6"/>`:`<rect x="${x-17}" y="${y+4}" width="34" height="30" rx="8" fill="${cols[(i+r)%5]}" ${st()}/><circle cx="${x}" cy="${y-6}" r="14" fill="${['#3A2A22','#222','#6A3F26','#2A1D18','#8B5E3C'][(i*2+r)%5]}" ${st(C.navy,3)}/>`;
    if(fr)seats+=`<g transform="translate(${x},${y-34}) scale(${f(1+.1*Math.sin(T*4))})">${_e110star(0,0,15,C.gold,C.goldD)}</g>`}
  const hx=`<polygon points="-34,-48 -14,-58 6,-48 6,-26 -14,-16 -34,-26" fill="none" ${st('#fff',3.5)}/><polygon points="-26,-44 -14,-50 -2,-44 -2,-30 -14,-24 -26,-30" fill="none" stroke="#fff" stroke-width="2" opacity=".6"/><path d="M6 -38 H40 M22 -50 V-26" fill="none" ${st('#fff',3.5)}/><path d="M-60 -10 H60" ${st('#fff',3)} fill="none" opacity=".7"/>`;
  return `<g>${_e110sh(120,106)}<rect x="-122" y="-100" width="244" height="176" rx="10" fill="#E8D7AC" ${st()}/><rect x="-104" y="-90" width="150" height="100" rx="8" fill="#2F6B55" ${st(C.brown,8)}/><g transform="translate(-30,-34)">${hx}</g><rect x="-98" y="14" width="138" height="6" fill="${C.brown}"/><g transform="translate(82,-18) scale(.6)">${P.e110_pp({k:'prof'},T)}</g><path d="M62 -42 L22 -60" ${st(C.brown,4)} fill="none"/>${seats}</g>`};

/* ---------- notebook page. o.k copied (strange symbols, red ?) | own (neat lines in blue) ---------- */
P.e110_notes=(o,T,k)=>{const own=o.k==='own';let s='';
  if(own){for(let i=0;i<6;i++)s+=`<line x1="-70" y1="${-60+i*26}" x2="${[66,50,70,58,64,40][i]}" y2="${-60+i*26}" ${st('#4DA3D8',4)}/>`;s+=`<g transform="translate(50,56)"><rect x="-6" y="-60" width="12" height="62" rx="5" fill="${C.gold}" ${st()} transform="rotate(35)"/></g>`}
  else{s+=`<polygon points="-62,-62 -48,-70 -34,-62 -34,-46 -48,-38 -62,-46" fill="none" ${st('#7C909C',3)}/><path d="M-20 -54 H50 M-62 -22 q10 -14 20 0 t20 0 M-62 8 H-10 M0 8 h40 M-62 34 q16 -22 30 0 M-10 34 h14 M20 28 l30 12" fill="none" ${st('#7C909C',3.2)}/><text x="-62" y="-6" font-family="Fraunces" font-weight="700" font-size="20" fill="#7C909C">12 = 3.5</text>`}
  return `<g>${_e110sh(120,106)}<path d="M-120 -90 L0 -80 L120 -90 L120 100 L0 112 L-120 100Z" fill="#fff" ${st()}/><line x1="0" y1="-80" x2="0" y2="112" ${st(C.navy,4)}/><g transform="translate(-60,0) scale(.82)">${s}</g><g opacity=".9" transform="translate(60,0) scale(.82)">${own?'':''}</g>${o.k==='copied'?`<g transform="translate(58,6)"><circle r="44" fill="${C.gold}" ${st()}/><text x="0" y="26" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="76" fill="${C.navy}">?</text></g>`:(own?`<g transform="translate(60,0)"><circle r="44" fill="${C.moss}" ${st()}/><path d="M-20 2 L-4 18 L22 -14" fill="none" stroke="#fff" stroke-width="10" stroke-linecap="round" stroke-linejoin="round"/></g>`:'')}</g>`};

/* ---------- cups of coffee (o.n cups) ---------- */
P.e110_coffee=(o,T,k)=>{const n=o.n||4;let s='';for(let i=0;i<n;i++){const x=(i-(n-1)/2)*66,pop=ease((k-.15-i*.22)/.3);
    s+=`<g transform="translate(${f(x)},${f((1-pop)*-30)})" opacity="${f(pop)}"><path d="M-26 -24 L26 -24 L20 34 Q0 46 -20 34Z" fill="#fff" ${st()}/><path d="M-24 -16 H24" ${st(C.brown,10)}/><path d="M26 -14 a16 16 0 0 1 0 30" fill="none" ${st()}/><ellipse cx="0" cy="38" rx="34" ry="8" fill="#E9EEF1" ${st(C.navy,3)}/>${[0,1].map(j=>`<path d="M${-8+j*16} -36 q-6 -10 0 -20 t0 -18" fill="none" ${st('#9AA7B0',3)} opacity="${f(.3+.3*Math.sin(T*3+j+i))}"/>`).join('')}</g>`}
  return `<g>${_e110sh(150,56)}${s}</g>`};

/* ---------- empty head: a person and an empty thought cloud ---------- */
P.e110_emptyhead=(o,T,k)=>{const cl=[[0,-12,58],[-70,-20,48],[-30,-62,52],[28,-66,54],[72,-30,48],[66,26,44],[8,38,52],[-52,24,44]].map(([x,y,r])=>`<circle cx="${x}" cy="${y}" r="${r}"/>`).join('');
  return `<g><g transform="translate(-76,52) scale(.8)">${P.person({c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g><g transform="translate(34,-30) scale(.7)"><g fill="#fff" ${st(C.navy,5)}>${cl}</g><g fill="#fff">${cl}</g><circle cx="-62" cy="82" r="13" fill="#fff" ${st(C.navy,4)}/><circle cx="-84" cy="106" r="8" fill="#fff" ${st(C.navy,4)}/><g fill="#C3CDD3">${[-20,0,20].map((x,i)=>`<circle cx="${x}" cy="${f(-6+Math.sin(T*3+i)*3)}" r="5"/>`).join('')}</g></g></g>`};

/* ---------- office door with a plaque ---------- */
P.e110_office=(o,T,k)=>`<g>${_e110sh(80,112)}<rect x="-64" y="-110" width="128" height="222" rx="8" fill="${C.brown}" ${st()}/><rect x="-46" y="-52" width="92" height="150" rx="6" fill="#A9743F" ${st(C.navy,3)}/><rect x="-44" y="-96" width="88" height="34" rx="6" fill="${C.gold}" ${st()}/><text x="0" y="-72" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="19" fill="${C.navy}" letter-spacing="1">OFFICE</text><circle cx="34" cy="20" r="8" fill="${C.gold}" ${st(C.navy,3)}/><rect x="-26" y="-34" width="52" height="30" rx="4" fill="#fff" opacity=".0"/></g>`;

/* ---------- race track with a finish flag ---------- */
P.e110_race=(o,T,k)=>{let t='';for(let i=0;i<4;i++)t+=`<path d="M-124 ${-30+i*28} H124" ${st('#fff',3)} stroke-dasharray="14 12" fill="none"/>`;
  let fl='';for(let r=0;r<4;r++)for(let c=0;c<5;c++)fl+=`<rect x="${c*14}" y="${r*14}" width="14" height="14" fill="${(r+c)%2?'#fff':C.navy}"/>`;
  return `<g><rect x="-130" y="-48" width="260" height="124" rx="14" fill="#C9694A" ${st()}/>${t}<rect x="76" y="-48" width="14" height="124" fill="#fff" opacity=".9"/><g transform="translate(86,-92)"><rect x="-3" y="0" width="6" height="64" fill="#9FB0BA" ${st(C.navy,2.5)}/><g transform="translate(3,0) skewY(${f(Math.sin(T*4)*4)})"><g clip-path="url(#e110_rc)">${fl}</g></g><clipPath id="e110_rc"><rect x="0" y="0" width="70" height="56"/></clipPath><rect x="3" y="0" width="70" height="56" fill="none" ${st(C.navy,3)}/></g></g>`};

/* ---------- chemistry flask (o.c liquid colour) ---------- */
P.e110_flask=(o,T,k)=>{const c=o.c||'#4DA3D8';let b='';for(let i=0;i<3;i++){const p=(T*.7+i/3)%1;b+=`<circle cx="${f(-12+i*14)}" cy="${f(30-p*50)}" r="${f(3+i)}" fill="#fff" opacity="${f(1-p)}"/>`}
  return `<g>${_e110sh(70,100)}<clipPath id="e110_fc"><path d="M-18 -70 L18 -70 L18 -20 L66 84 Q70 100 52 100 L-52 100 Q-70 100 -66 84 L-18 -20Z"/></clipPath><g clip-path="url(#e110_fc)"><rect x="-80" y="14" width="160" height="90" fill="${c}"/>${b}</g><path d="M-18 -70 L18 -70 L18 -20 L66 84 Q70 100 52 100 L-52 100 Q-70 100 -66 84 L-18 -20Z" fill="#fff" fill-opacity=".18" ${st()}/><rect x="-24" y="-78" width="48" height="12" rx="5" fill="${_e110steel}" ${st(C.navy,3)}/><path d="M-10 -60 V-18" stroke="#fff" stroke-width="5" opacity=".6" fill="none"/></g>`};

/* ---------- lab bench: two bottles poured into one glass. o.res blue | brown (wrong bottle: bad smell) ---------- */
P.e110_lab=(o,T,k)=>{const br=o.res==='brown',pc=ease((k-.2)/.8);let sm='';
  if(br)for(let i=0;i<3;i++){const p=(T*.8+i/3)%1;sm+=`<path d="M${-14+i*14} ${f(-20-p*70)} q-10 -10 0 -20 t0 -20" fill="none" ${st('#7DB35A',5)} opacity="${f(1-p)}"/>`}
  const bot=(x,c,rot,lab)=>`<g transform="translate(${x},-62) rotate(${rot})"><path d="M-18 -14 H18 V54 Q18 66 6 66 H-6 Q-18 66 -18 54Z" fill="${c}" ${st()}/><rect x="-9" y="-40" width="18" height="28" fill="${c}" ${st()}/><rect x="-11" y="-48" width="22" height="10" rx="3" fill="${_e110steelD}" ${st(C.navy,3)}/><rect x="-13" y="18" width="26" height="22" rx="3" fill="#fff"/><text x="0" y="36" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="17" fill="${C.navy}">${lab}</text></g>`;
  const res=br?'#6F4A2E':'#4DA3D8';
  return `<g>${_e110sh(120,100)}<rect x="-124" y="64" width="248" height="22" rx="6" fill="#C9A26A" ${st()}/>${bot(-62,'#E8F1F6',-40,'A')}${bot(62,'#F4E2B8',40,'B')}<path d="M-34 -30 Q-26 20 -6 36 M34 -30 Q26 20 6 36" fill="none" ${st('#E8F1F6',5)} opacity="${f(pc)}" stroke-dasharray="4 6"/><path d="M-30 20 H30 L24 64 H-24Z" fill="#fff" fill-opacity=".3" ${st()}/><clipPath id="e110_lc"><path d="M-27 34 H27 L24 62 H-24Z"/></clipPath><g clip-path="url(#e110_lc)"><rect x="-30" y="${f(62-28*pc)}" width="60" height="30" fill="${res}"/></g>${sm}</g>`};

/* ---------- egg ---------- */
P.e110_egg=(o,T,k)=>{let sm='';for(let i=0;i<3;i++){const p=(T*.8+i/3)%1;sm+=`<path d="M${-30+i*30} ${f(-40-p*60)} q-10 -10 0 -20 t0 -20" fill="none" ${st('#7DB35A',5)} opacity="${f(1-p)}"/>`}
  return `<g>${_e110sh(60,90)}<path d="M0 -70 C46 -70 62 -10 62 24 C62 66 34 88 0 88 C-34 88 -62 66 -62 24 C-62 -10 -46 -70 0 -70Z" fill="#F4E9D2" ${st()}/><path d="M-36 -10 Q-44 20 -30 50" fill="none" stroke="#fff" stroke-width="7" opacity=".7"/><path d="M-12 -62 L-4 -40 L-14 -30" fill="none" ${st('#B7A27E',3)} opacity="0"/>${sm}</g>`};

/* ---------- six plants in pots. o.k same | varied; o.can = watering can ---------- */
P.e110_plants=(o,T,k)=>{let s='';const H=o.k==='varied'?[70,30,56,22,64,40]:[44,44,44,44,44,44],CL=o.k==='varied'?['#5E9B63','#D8C44A','#5E9B63','#D8C44A','#5E9B63','#9BBE5C']:Array(6).fill('#5E9B63'),gr=ease((k-.2)/1.0);
  for(let i=0;i<6;i++){const x=-96+i*38,h=H[i]*(.6+.4*gr),sw=Math.sin(T*2+i)*2;
    s+=`<g transform="translate(${x},40)"><path d="M0 0 V${-h}" ${st(CL[i],6)} stroke="${CL[i]}"/><path d="M0 0 V${-h}" fill="none" stroke="${C.navy}" stroke-width="2" opacity=".0"/><ellipse cx="${-9+sw*.2}" cy="${-h+4}" rx="12" ry="6" transform="rotate(-30 ${-9} ${-h+4})" fill="${CL[i]}" ${st(C.navy,2.5)}/><ellipse cx="${9-sw*.2}" cy="${-h-6}" rx="12" ry="6" transform="rotate(30 9 ${-h-6})" fill="${CL[i]}" ${st(C.navy,2.5)}/><path d="M-16 0 L16 0 L12 34 L-12 34Z" fill="#C0583E" ${st()}/></g>`}
  const can=o.can?`<g transform="translate(-6,-64) rotate(${f(-24+Math.sin(T*3)*3)})"><path d="M-30 -10 H30 L26 40 H-26Z" fill="${C.blue}" ${st()}/><path d="M30 6 L64 -22 L70 -14 L34 20Z" fill="${C.blue}" ${st()}/><path d="M-30 0 Q-52 -6 -44 -30" fill="none" ${st(C.navy,5)}/>${[0,1,2].map(i=>`<circle cx="${f(70+i*8)}" cy="${f(((T*60+i*20)%60)-8)}" r="3.5" fill="${C.blue}"/>`).join('')}</g>`:'';
  return `<g>${_e110sh(120,76)}<rect x="-122" y="38" width="244" height="14" rx="5" fill="#C9A26A" ${st()}/>${s}${can}</g>`};

/* ---------- very long essay: a thick stack of pages ---------- */
P.e110_essay=(o,T,k)=>{let s='';for(let i=0;i<9;i++)s+=`<rect x="${-72+(i%3)*2}" y="${70-i*16}" width="150" height="20" rx="4" fill="${i%2?'#F6F3EA':'#FFFEF8'}" ${st(C.navy,3.5)}/>`;
  return `<g>${_e110sh(100,96)}${s}<g transform="translate(0,-92) rotate(${f(Math.sin(T*1.6)*1.5)})"><rect x="-72" y="-14" width="152" height="40" rx="6" fill="#FFFEF8" ${st()}/><line x1="-56" y1="-2" x2="40" y2="-2" ${st('#9AA7B0',5)}/><line x1="-56" y1="12" x2="14" y2="12" ${st('#C3CDD3',4)}/></g><rect x="-16" y="-110" width="30" height="20" rx="4" fill="${C.gold}" ${st()}/></g>`};

/* ---------- instructions on two pages. o.hi = 2 rings page two ---------- */
P.e110_instr=(o,T,k)=>{const pg=(x,rot,n,hi)=>{let l='';for(let i=0;i<6;i++)l+=`<circle cx="${x-34}" cy="${-52+i*28}" r="5" fill="${hi?C.red:C.gold}"/><line x1="${x-20}" y1="${-52+i*28}" x2="${x+[40,30,44,26,40,34][i]}" y2="${-52+i*28}" ${st('#9AA7B0',4)}/>`;
    return `<g transform="rotate(${rot} ${x} 0)"><rect x="${x-52}" y="-92" width="104" height="196" rx="8" fill="#fff" ${st()}/><text x="${x}" y="-66" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="20" fill="${C.navy2}">${n}</text>${l.replace(/<circle cx="[^"]*" cy="-52" r="5"[^>]*\/>/,'')}</g>`};
  const hi=o.hi===2;
  return `<g>${_e110sh(120,112)}<g opacity="${hi?.55:1}">${pg(-62,-3,1)}</g>${pg(62,3,2,hi)}${hi?`<rect x="6" y="-98" width="116" height="206" rx="12" fill="none" ${st(C.red,6)} transform="rotate(3 62 0)"/>`:''}</g>`};

/* ---------- how an essay is built. o.bad = one long block with no parts ---------- */
P.e110_parts=(o,T,k)=>{
  if(o.bad)return `<g>${_e110sh(100,106)}<rect x="-72" y="-100" width="144" height="200" rx="10" fill="#fff" ${st()}/>${Array.from({length:9},(_,i)=>`<line x1="-54" y1="${-76+i*20}" x2="${[54,50,56,46,54,52,56,48,30][i]}" y2="${-76+i*20}" ${st('#9AA7B0',4)}/>`).join('')}</g>`;
  const blk=(y,h,c,w)=>`<rect x="${-w/2}" y="${y}" width="${w}" height="${h}" rx="8" fill="${c}" ${st()}/><line x1="${-w/2+14}" y1="${y+h/2}" x2="${w/2-14}" y2="${y+h/2}" stroke="#fff" stroke-width="5" opacity=".8" stroke-linecap="round"/>`;
  return `<g>${_e110sh(100,106)}${blk(-100,30,C.gold,120)}${blk(-60,44,C.blue,150)}${blk(-8,44,C.blue,150)}${blk(44,44,C.blue,150)}${blk(96-6,30,C.gold,120)}</g>`};

/* ---------- books: o.k stack | list (names of the books at the end) | shelf ---------- */
P.e110_books=(o,T,k)=>{
  if(o.k==='list'){let l='';for(let i=0;i<5;i++)l+=`<rect x="-52" y="${-52+i*30}" width="14" height="22" rx="2" fill="${[C.red,C.blue,C.moss,C.gold2,'#8E6BB5'][i]}" ${st(C.navy,2.5)}/><line x1="-26" y1="${-41+i*30}" x2="${[54,40,56,46,50][i]}" y2="${-41+i*30}" ${st('#9AA7B0',5)}/>`;
    return `<g>${_e110sh(90,112)}<rect x="-76" y="-100" width="152" height="204" rx="8" fill="#fff" ${st()}/>${l}</g>`}
  let s='';const cs=[C.red,C.blue,C.moss,C.gold2,'#8E6BB5'];for(let i=0;i<5;i++)s+=`<rect x="${-96+(i%2)*10}" y="${72-i*34}" width="${180-(i%3)*14}" height="30" rx="5" fill="${cs[i]}" ${st()}/><rect x="${-96+(i%2)*10+14}" y="${78-i*34}" width="70" height="6" rx="3" fill="#fff" opacity=".6"/>`;
  return `<g>${_e110sh(100,106)}${s}</g>`};

/* ---------- big paper dictionary with a magnifying glass ---------- */
P.e110_dict=(o,T,k)=>`<g>${_e110sh(100,106)}<rect x="-76" y="-100" width="152" height="200" rx="10" fill="#8F3E2A" ${st()}/><rect x="-76" y="-100" width="22" height="200" rx="8" fill="#6F2E1E" ${st()}/><rect x="-44" y="-76" width="100" height="70" rx="6" fill="${C.gold}" ${st(C.goldD,3)}/><text x="6" y="-26" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="46" fill="#8F3E2A">A-Z</text><rect x="-44" y="20" width="100" height="8" rx="4" fill="${C.gold}"/><rect x="-44" y="40" width="70" height="8" rx="4" fill="${C.gold}"/><path d="M-76 -86 L-62 -100" stroke="${C.gold}" stroke-width="5"/><g transform="translate(${f(52+Math.sin(T*1.6)*4)},50)"><circle r="30" fill="#BFE3F2" fill-opacity=".5" ${st(C.navy,6)}/><line x1="22" y1="22" x2="50" y2="50" ${st(C.navy,12)}/><line x1="22" y1="22" x2="50" y2="50" ${st(C.brown,6)}/></g></g>`;

/* ---------- dictionary app on a phone ---------- */
P.e110_dictapp=(o,T,k)=>`<g><rect x="-62" y="-112" width="124" height="224" rx="22" fill="${C.navy}" ${st()}/><rect x="-52" y="-96" width="104" height="192" rx="10" fill="#F4F7F9"/><rect x="-44" y="-84" width="88" height="24" rx="12" fill="#fff" ${st(C.navy,2.5)}/><circle cx="26" cy="-72" r="6" fill="none" ${st(C.navy,2.5)}/><text x="-34" y="-12" font-family="Fraunces" font-weight="800" font-size="52" fill="${C.blue}">Aa</text><line x1="-40" y1="14" x2="40" y2="14" ${st('#9AA7B0',5)}/><line x1="-40" y1="34" x2="26" y2="34" ${st('#C3CDD3',4)}/><line x1="-40" y1="52" x2="34" y2="52" ${st('#C3CDD3',4)}/><rect x="-40" y="66" width="80" height="18" rx="9" fill="${C.gold}" ${st(C.goldD,2.5)}/><circle cx="0" cy="104" r="4" fill="#46535D"/></g>`;

/* ---------- study group: four people round a table with books and a speech bubble ---------- */
P.e110_group=(o,T,k)=>{const cs=[['#D96C8B','long','#3A2A22'],['#4DA3D8','short','#222'],['#4F7A5A','bun','#6A3F26'],['#E2B653','long','#2A1D18']];let p='';
  [[-96,-8],[-34,-30],[34,-30],[96,-8]].forEach(([x,y],i)=>{p+=`<g transform="translate(${x},${y}) scale(.5)">${P.person({c:cs[i][0],hair:cs[i][1],hc:cs[i][2],ph:i},T)}</g>`});
  return `<g>${_e110sh(130,104)}${p}<ellipse cx="0" cy="34" rx="130" ry="32" fill="#C9A26A" ${st()}/><ellipse cx="0" cy="30" rx="118" ry="24" fill="#DDBB82"/><rect x="-10" y="60" width="20" height="40" fill="${C.brown}" ${st()}/><g transform="translate(-52,26)"><rect x="-22" y="-8" width="44" height="26" rx="3" fill="${C.red}" ${st(C.navy,3)}/></g><g transform="translate(14,28)"><rect x="-26" y="-8" width="52" height="26" rx="3" fill="${C.blue}" ${st(C.navy,3)}/><rect x="-18" y="-4" width="36" height="4" fill="#fff" opacity=".6"/></g><g transform="translate(70,24) rotate(8)"><rect x="-22" y="-6" width="44" height="22" rx="3" fill="#fff" ${st(C.navy,3)}/><line x1="-12" y1="2" x2="12" y2="2" ${st('#9AA7B0',3)}/><line x1="-12" y1="10" x2="6" y2="10" ${st('#9AA7B0',3)}/></g></g>`};

/* ---------- standing mirror with a reflection that explains the lesson ---------- */
P.e110_mirror=(o,T,k)=>`<g>${_e110sh(70,112)}<path d="M-34 100 L-50 126 M34 100 L50 126" ${st(C.brown,8)} fill="none"/><ellipse cx="0" cy="0" rx="72" ry="104" fill="${C.brown}" ${st()}/><ellipse cx="0" cy="0" rx="60" ry="92" fill="#DDF0F7" ${st(C.navy,3)}/><clipPath id="e110_mc"><ellipse cx="0" cy="0" rx="58" ry="90"/></clipPath><g clip-path="url(#e110_mc)"><g transform="translate(0,40) scale(.7)">${P.person({c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g><path d="M-48 -60 L-8 -86" stroke="#fff" stroke-width="10" opacity=".6" stroke-linecap="round"/></g></g>`;

/* ---------- things to get ready: pen, student card, water bottle, ruler ---------- */
P.e110_kit=(o,T,k)=>{const pop=(i)=>ease((k-.15-i*.2)/.3);
  const pen=`<g transform="translate(-62,-52) rotate(-30)"><rect x="-8" y="-52" width="16" height="92" rx="6" fill="${C.blue}" ${st()}/><path d="M-8 40 L0 62 L8 40Z" fill="${C.cream}" ${st()}/><rect x="-8" y="-60" width="16" height="12" rx="4" fill="${C.red}" ${st(C.navy,3)}/></g>`;
  const card=`<g transform="translate(62,-52) rotate(6)"><rect x="-54" y="-36" width="108" height="72" rx="8" fill="#fff" ${st()}/><rect x="-54" y="-36" width="108" height="20" rx="8" fill="#2F5D9A" ${st()}/><rect x="-54" y="-24" width="108" height="8" fill="#2F5D9A"/><rect x="-42" y="-8" width="30" height="34" rx="4" fill="#D9E2E7" ${st(C.navy,2.5)}/><line x1="0" y1="0" x2="42" y2="0" ${st('#9AA7B0',4)}/><line x1="0" y1="14" x2="34" y2="14" ${st('#C3CDD3',4)}/></g>`;
  const bot=`<g transform="translate(-62,60)"><rect x="-22" y="-44" width="44" height="88" rx="14" fill="#BFE3F2" ${st()}/><rect x="-14" y="-58" width="28" height="16" rx="5" fill="${C.blue}" ${st()}/><rect x="-22" y="-10" width="44" height="26" fill="${C.blue}" opacity=".5"/></g>`;
  let tk='';for(let i=0;i<10;i++)tk+=`<line x1="${-74+i*15}" y1="-16" x2="${-74+i*15}" y2="${i%2?-4:4}" ${st(C.navy,3)}/>`;
  const rul=`<g transform="translate(46,64) rotate(-8)"><rect x="-84" y="-20" width="168" height="40" rx="6" fill="${C.gold}" ${st()}/><g transform="translate(0,4)">${tk.replace(/y1="-16"/g,'y1="-20"')}</g></g>`;
  return `<g>${_e110sh(130,112)}<g opacity="${f(pop(0))}">${pen}</g><g opacity="${f(pop(1))}">${card}</g><g opacity="${f(pop(2))}">${bot}</g><g opacity="${f(pop(3))}">${rul}</g></g>`};

/* ---------- breakfast: toast, egg, glass of milk, orange ---------- */
P.e110_breakfast=(o,T,k)=>`<g>${_e110sh(120,92)}<ellipse cx="-24" cy="40" rx="86" ry="26" fill="#fff" ${st()}/><ellipse cx="-24" cy="38" rx="62" ry="17" fill="#F4F7F9" ${st(C.navy,2.5)}/><path d="M-62 40 Q-62 14 -40 20 Q-30 8 -12 20 Q8 16 8 40Z" fill="#E7B66B" ${st()}/><ellipse cx="-24" cy="28" rx="20" ry="10" fill="#fff" ${st(C.navy,2.5)}/><circle cx="-24" cy="27" r="7" fill="${C.gold}"/><g transform="translate(88,24)"><path d="M-22 -50 H22 L18 38 Q0 46 -18 38Z" fill="#fff" fill-opacity=".8" ${st()}/><path d="M-20 -14 H20 L18 38 Q0 46 -18 38Z" fill="#F4F7F9"/></g><circle cx="-92" cy="-4" r="22" fill="${C.orange}" ${st()}/><path d="M-92 -26 q6 -10 14 -10" fill="none" ${st(C.leaf,5)}/>${[0,1].map(i=>`<path d="M${-30+i*14} -8 q-6 -10 0 -20 t0 -18" fill="none" ${st('#9AA7B0',3)} opacity="${f(.3+.3*Math.sin(T*3+i))}"/>`).join('')}</g>`;

/* ---------- exam room: rows of desks with papers, clock on the wall ---------- */
P.e110_examroom=(o,T,k)=>{let d='';for(let r=0;r<2;r++)for(let i=0;i<4;i++){const x=-84+i*56,y=36+r*44;d+=`<rect x="${x-22}" y="${y}" width="44" height="26" rx="4" fill="#C9A26A" ${st(C.navy,3)}/><rect x="${x-13}" y="${y+4}" width="26" height="16" rx="2" fill="#fff"/><rect x="${x-18}" y="${y+26}" width="5" height="14" fill="${C.brown}"/><rect x="${x+13}" y="${y+26}" width="5" height="14" fill="${C.brown}"/>`}
  return `<g>${_e110sh(130,106)}<rect x="-130" y="-98" width="260" height="190" rx="10" fill="#E8D7AC" ${st()}/><rect x="-130" y="52" width="260" height="40" fill="#C9A26A" opacity=".5"/><g transform="translate(0,-52) scale(.4)">${P.clk({h:9,m:0},T,k)}</g><rect x="-100" y="-86" width="52" height="44" rx="4" fill="${C.sky}" ${st()}/><rect x="52" y="-86" width="52" height="44" rx="4" fill="${C.sky}" ${st()}/>${d}</g>`};

/* ---------- calm: a person with slow soft rings, a leaf ---------- */
P.e110_calm=(o,T,k)=>{let r='';for(let i=0;i<3;i++){const p=(T*.35+i/3)%1;r+=`<circle cx="0" cy="10" r="${f(60+p*90)}" fill="none" stroke="${C.cold}" stroke-width="5" opacity="${f(.7*(1-p))}"/>`}
  return `<g>${r}<g transform="translate(0,12) scale(.9)">${P.person({c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g><g transform="translate(78,-60) rotate(${f(20+Math.sin(T*1.4)*8)})"><path d="M0 40 Q-30 -10 0 -50 Q30 -10 0 40Z" fill="${C.leaf}" ${st()}/><path d="M0 36 V-30" ${st(C.navy,3)} fill="none"/></g></g>`};

/* ---------- copying: two papers with the same mistakes in the same place ---------- */
P.e110_copy=(o,T,k)=>{const pg=(x)=>{let s=`<rect x="${x-52}" y="-84" width="104" height="168" rx="8" fill="#fff" ${st()}/>`;for(let i=0;i<5;i++)s+=`<line x1="${x-38}" y1="${-52+i*28}" x2="${x+[36,28,40,22,34][i]}" y2="${-52+i*28}" ${st('#C3CDD3',4)}/>`;return s+_e110x(x+24,-24,9)+_e110x(x-14,32,9)};
  const pu=1+.06*Math.sin(T*4);
  return `<g>${_e110sh(130,92)}${pg(-72)}${pg(72)}<g stroke-dasharray="7 6" ${st(C.red,3.5)} fill="none"><line x1="-48" y1="-24" x2="96" y2="-24"/><line x1="-86" y1="32" x2="58" y2="32"/></g><g transform="translate(0,4) scale(${f(pu)})"><circle r="20" fill="${C.gold}" ${st()}/><text x="0" y="12" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="34" fill="${C.navy}">=</text></g></g>`};

/* ---------- second chance: a paper with two circling arrows ---------- */
P.e110_redo=(o,T,k)=>`<g><g transform="rotate(${f(T*40)})"><path d="M-96 0 A96 96 0 0 1 60 -76" fill="none" ${st(C.moss,14)}/><polygon points="52,-112 100,-70 40,-50" fill="${C.moss}" ${st()}/><path d="M96 0 A96 96 0 0 1 -60 76" fill="none" ${st(C.moss,14)}/><polygon points="-52,112 -100,70 -40,50" fill="${C.moss}" ${st()}/></g><rect x="-44" y="-58" width="88" height="116" rx="6" fill="#fff" ${st()}/>${[0,1,2,3].map(i=>`<line x1="-30" y1="${-34+i*24}" x2="${[28,18,30,12][i]}" y2="${-34+i*24}" ${st('#9AA7B0',4)}/>`).join('')}</g>`;

/* ---------- copied essay from the internet ---------- */
P.e110_copyweb=(o,T,k)=>`<g><rect x="-110" y="-96" width="220" height="190" rx="14" fill="#F4F7F9" ${st()}/><rect x="-110" y="-96" width="220" height="30" rx="14" fill="${_e110steel}" ${st()}/><rect x="-110" y="-80" width="220" height="14" fill="${_e110steel}"/><line x1="-110" y1="-66" x2="110" y2="-66" ${st(C.navy,4)}/><circle cx="-92" cy="-81" r="5" fill="${C.red}"/><circle cx="-76" cy="-81" r="5" fill="${C.gold}"/><circle cx="-60" cy="-81" r="5" fill="${C.leaf}"/><rect x="-44" y="-90" width="140" height="18" rx="9" fill="#fff" ${st(C.navy,2.5)}/>${[0,1,2,3,4].map(i=>`<line x1="-92" y1="${-42+i*24}" x2="${[62,40,70,30,54][i]}" y2="${-42+i*24}" ${st('#9AA7B0',5)}/>`).join('')}<g transform="translate(${f(60+Math.sin(T*3)*3)},50)"><rect x="-22" y="-26" width="34" height="44" rx="4" fill="#fff" ${st()}/><rect x="-12" y="-14" width="34" height="44" rx="4" fill="#fff" ${st()}/><line x1="-2" y1="-2" x2="14" y2="-2" ${st('#9AA7B0',3)}/><line x1="-2" y1="10" x2="10" y2="10" ${st('#9AA7B0',3)}/></g>${o.check?`<g transform="translate(${f(-30+Math.sin(T*2)*12)},30)"><circle r="30" fill="#BFE3F2" fill-opacity=".4" ${st(C.navy,6)}/><line x1="22" y1="22" x2="46" y2="46" ${st(C.navy,12)}/><line x1="22" y1="22" x2="46" y2="46" ${st(C.brown,6)}/></g>`:''}</g>`;

/* ---------- trophy ---------- */
P.e110_trophy=(o,T,k)=>`<g>${_e110sh(60,104)}<path d="M-52 -64 H52 V-20 Q52 24 0 36 Q-52 24 -52 -20Z" fill="${C.gold}" ${st()}/><path d="M-52 -50 Q-90 -50 -80 -12 Q-70 12 -46 8" fill="none" ${st(C.goldD,8)}/><path d="M52 -50 Q90 -50 80 -12 Q70 12 46 8" fill="none" ${st(C.goldD,8)}/><rect x="-10" y="34" width="20" height="38" fill="${C.goldD}" ${st()}/><rect x="-40" y="70" width="80" height="26" rx="6" fill="${C.brown}" ${st()}/>${_e110star(0,-18,22,'#fff',C.goldD)}<path d="M-38 -54 V-24" stroke="#fff" stroke-width="6" opacity=".5" stroke-linecap="round"/></g>`;

/* ---------- subject icons: atom (physics), triangle + compass (maths), leaf plant (biology) ---------- */
P.e110_atom=(o,T,k)=>{let r='';for(let i=0;i<3;i++)r+=`<ellipse rx="100" ry="36" transform="rotate(${i*60})" fill="none" ${st(C.blue,6)}/>`;
  let e='';for(let i=0;i<3;i++){const a=T*2+i*2.1,ex=Math.cos(a)*100,ey=Math.sin(a)*36,rr=i*60*Math.PI/180;e+=`<circle cx="${f(ex*Math.cos(rr)-ey*Math.sin(rr))}" cy="${f(ex*Math.sin(rr)+ey*Math.cos(rr))}" r="10" fill="${C.red}" ${st(C.navy,3)}/>`}
  return `<g>${r}<circle r="22" fill="${C.gold}" ${st()}/>${e}</g>`};
P.e110_math=(o,T,k)=>`<g><path d="M-96 84 L-96 -70 L68 84Z" fill="${C.gold}" ${st()}/><path d="M-80 66 V-36 L24 66Z" fill="#FFF3C4" ${st(C.navy,3)}/>${[0,1,2,3].map(i=>`<line x1="${-96}" y1="${-40+i*30}" x2="${-84}" y2="${-40+i*30}" ${st(C.navy,3)}/>`).join('')}<g transform="translate(56,-30) rotate(${f(Math.sin(T*1.6)*5)})"><path d="M0 -50 L-30 76 M0 -50 L30 76" fill="none" ${st(C.navy,10)}/><path d="M0 -50 L-30 76 M0 -50 L30 76" fill="none" ${st(_e110steel,5)}/><circle cx="0" cy="-54" r="12" fill="${C.red}" ${st()}/></g></g>`;
P.e110_leaf=(o,T,k)=>`<g>${_e110sh(60,100)}<path d="M0 90 V-10" ${st(C.leaf,10)}/><g transform="rotate(${f(Math.sin(T*1.8)*3)} 0 90)"><path d="M0 -10 Q-70 -40 -62 -96 Q0 -80 0 -10Z" fill="${C.leaf}" ${st()}/><path d="M0 -10 Q70 -40 62 -96 Q0 -80 0 -10Z" fill="#7FBA6A" ${st()}/><path d="M0 40 Q-56 20 -56 -20 Q-4 -10 0 40Z" fill="${C.leaf}" ${st()}/></g><path d="M-44 90 L44 90 L36 126 L-36 126Z" fill="#C0583E" ${st()}/></g>`;

/* ---------- university building with columns and a flag ---------- */
P.e110_uni=(o,T,k)=>{let c='';for(let i=0;i<5;i++)c+=`<rect x="${-80+i*36}" y="-26" width="18" height="84" fill="#F4EFE0" ${st()}/>`;
  return `<g>${_e110sh(130,100)}<polygon points="-110,-30 0,-92 110,-30" fill="#E7D3A6" ${st()}/><circle cx="0" cy="-50" r="12" fill="${C.sky}" ${st(C.navy,3)}/>${c}<rect x="-114" y="-32" width="228" height="10" fill="#E7D3A6" ${st()}/><rect x="-110" y="58" width="220" height="14" fill="#E7D3A6" ${st()}/><rect x="-124" y="72" width="248" height="14" fill="#D9C9A2" ${st()}/><rect x="-14" y="2" width="28" height="56" fill="${C.brown}" ${st(C.navy,3)}/><line x1="0" y1="-92" x2="0" y2="-124" ${st(C.navy,4)}/><path d="M0 -124 h${f(34+Math.sin(T*3)*4)} l-8 10 l8 10 H0Z" fill="${C.red}" ${st(C.navy,3)}/></g>`};

/* ---------- desk at night: lamp, books, clock, a mug (all-night study) ---------- */
P.e110_desk=(o,T,k)=>`<g>${_e110sh(130,104)}<rect x="-130" y="30" width="260" height="22" rx="6" fill="#C9A26A" ${st()}/><rect x="-110" y="52" width="16" height="48" fill="${C.brown}" ${st()}/><rect x="94" y="52" width="16" height="48" fill="${C.brown}" ${st()}/><g transform="translate(-70,26)"><path d="M0 0 L-18 -64 M0 0 L28 -52" ${st(_e110steelD,6)} fill="none"/><path d="M14 -72 L52 -52 L40 -34 Z" fill="${C.gold}" ${st()}/><path d="M26 -34 L70 8 L6 8Z" fill="${C.gold}" opacity=".18"/><rect x="-20" y="-6" width="40" height="10" rx="4" fill="${_e110steelD}" ${st()}/></g><g transform="translate(14,28)"><rect x="-40" y="-22" width="80" height="22" rx="4" fill="${C.blue}" ${st()}/><rect x="-34" y="-42" width="72" height="22" rx="4" fill="${C.red}" ${st()}/></g><g transform="translate(86,-30) scale(.46)">${P.clk({h:3,m:0},T,k)}</g><g transform="translate(-6,-6)"><path d="M-18 8 L18 8 L14 28 Q0 34 -14 28Z" fill="#fff" ${st()}/><path d="M-14 12 H14" ${st(C.brown,6)}/>${[0,1].map(i=>`<path d="M${-6+i*12} 0 q-5 -8 0 -16 t0 -14" fill="none" ${st('#9AA7B0',3)} opacity="${f(.3+.3*Math.sin(T*3+i))}"/>`).join('')}</g></g>`;

/* ---------- closed book (shut your book) ---------- */
P.e110_closedbook=(o,T,k)=>`<g>${_e110sh(90,84)}<rect x="-70" y="-84" width="140" height="170" rx="8" fill="${C.blue}" ${st()}/><rect x="-70" y="-84" width="18" height="170" rx="6" fill="#2F6A9A" ${st()}/><rect x="-36" y="-56" width="86" height="50" rx="6" fill="#fff" opacity=".85"/><line x1="-26" y1="-36" x2="40" y2="-36" ${st('#9AA7B0',5)}/><line x1="-26" y1="-22" x2="20" y2="-22" ${st('#C3CDD3',4)}/><path d="M-70 78 H70" ${st('#fff',3)} opacity=".5"/></g>`;

/* ---------- gold ribbon: TIP n / STEP n (o.t label, o.moon = small moon: tips for the night before an exam) ---------- */
P.e110_tip=(o,T,k)=>{const pu=1+.03*Math.sin(T*3),lab=o.t||'TIP',txt=`${lab} ${o.n}`;
  return `<g transform="scale(${f(pu)})"><path d="M-136 -22 L-106 -22 L-106 38 L-136 38 L-120 8Z" fill="${C.goldD}" ${st()}/><path d="M136 -22 L106 -22 L106 38 L136 38 L120 8Z" fill="${C.goldD}" ${st()}/><rect x="-112" y="-36" width="224" height="76" rx="14" fill="${C.gold}" ${st()}/><rect x="-104" y="-28" width="208" height="60" rx="9" fill="none" stroke="${C.goldD}" stroke-width="2.5" opacity=".6"/>${o.moon?`<g transform="translate(-76,2) scale(.3)"><path d="M30 -88 A80 80 0 1 0 60 52 A62 62 0 0 1 30 -88 Z" fill="#F7E7A8" ${st(C.navy,12)}/></g>`:''}<text x="${o.moon?18:0}" y="22" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="${txt.length>6?44:50}" fill="${C.navy}" letter-spacing="3">${txt}</text></g>`};

const _e110iPlate=(id,c1,c2,T,ring)=>`<defs><radialGradient id="${id}" cx="50%" cy="40%" r="65%"><stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></radialGradient></defs><circle r="136" fill="${c1}" opacity="${f(.10+.04*Math.sin(T*1.5))}"/><circle r="126" fill="url(#${id})"/><circle r="126" fill="none" stroke="${ring}" stroke-width="3" opacity=".7"/><circle r="136" fill="none" stroke="${ring}" stroke-width="2" stroke-dasharray="3 11" opacity=".55" transform="rotate(${f(T*8)})"/>`;
const _e110iSp=(x,y,s,T,ph,col)=>{const a=.5+.5*Math.sin(T*2.4+ph),z=s*(.55+.45*a);return `<path transform="translate(${x},${y}) scale(${f(z)})" d="M0,-1 Q.14,-.14 1,0 Q.14,.14 0,1 Q-.14,.14 -1,0 Q-.14,-.14 0,-1Z" fill="${col||'#FFE9A0'}" opacity="${f(.45+.55*a)}"/>`};
/* Episode 110 intro hero: exam paper with A+ grade, pencil, book stack, clock */
P.e110_ihero=(o,T,k)=>{const b=(i,a,s=1.5)=>Math.sin(T*s+i)*a;
const rows=[0,1,2].map(i=>`<g transform="translate(-40,${-8+i*28})"><circle r="7" fill="#fff" ${st('#4D74B8',2.4)}/>${i!==1?`<path d="M-4,0 L-1,3.5 L5,-4" fill="none" ${st('#2FA05A',3)}/>`:''}<rect x="14" y="-4" width="${[64,48,58][i]}" height="6" rx="3" fill="#B9C6DA"/></g>`).join('');
const pw=b(0,5,3.2);
return `<g>${_e110iPlate('e110i_p','#4B66B5','#17213A',T,'#FFD36B')}
<defs><linearGradient id="e110i_pp" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFFFFF"/><stop offset="1" stop-color="#E8EDF6"/></linearGradient>
<linearGradient id="e110i_cl" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FF8F8A"/><stop offset="1" stop-color="#D9444A"/></linearGradient></defs>
${_e110iSp(-108,-60,8,T,0)}${_e110iSp(106,40,7,T,2)}${_e110iSp(-100,44,5,T,4)}
<g transform="translate(0,${f(-10+b(0,3,1.3))}) rotate(-5)"><rect x="-70" y="-90" width="140" height="176" rx="12" fill="#000" opacity=".25" transform="translate(5,7)"/><rect x="-70" y="-90" width="140" height="176" rx="12" fill="url(#e110i_pp)" ${st(C.navy,5)}/>
<rect x="-52" y="-72" width="62" height="9" rx="4.5" fill="#4D74B8"/><rect x="-52" y="-54" width="44" height="6" rx="3" fill="#B9C6DA"/>
<g transform="translate(0,-4)">${rows}</g>
<rect x="-52" y="52" width="70" height="6" rx="3" fill="#B9C6DA"/>
<g transform="translate(40,-52) rotate(${f(-10+b(1,3,1.6))}) scale(${f(1+.04*Math.sin(T*2.6))})"><ellipse rx="34" ry="26" fill="#FFF1F0" ${st('#E5484D',4.5)}/><text x="0" y="14" text-anchor="middle" font-family="Fraunces,serif" font-weight="900" font-size="40" fill="#E5484D">A+</text></g></g>
<g transform="translate(-8,98)"><rect x="-84" y="-6" width="170" height="22" rx="6" fill="#F0C64A" ${st(C.navy,4.5)}/><rect x="-74" y="-6" width="12" height="22" fill="#D99A2B"/><rect x="-66" y="-30" width="150" height="24" rx="6" fill="#5EB1D8" ${st(C.navy,4.5)}/><rect x="-56" y="-30" width="10" height="24" fill="#3C86B0"/><rect x="-58" y="-52" width="130" height="22" rx="6" fill="#E5675F" ${st(C.navy,4.5)}/><rect x="-46" y="-52" width="10" height="22" fill="#BB4640"/></g>
<g transform="translate(96,${f(-70+b(2,4))})"><line x1="-16" y1="-30" x2="-24" y2="-40" ${st(C.navy,4)}/><line x1="16" y1="-30" x2="24" y2="-40" ${st(C.navy,4)}/><circle cx="-24" cy="-40" r="8" fill="#FFD36B" ${st(C.navy,3.5)}/><circle cx="24" cy="-40" r="8" fill="#FFD36B" ${st(C.navy,3.5)}/><circle r="28" fill="#FFF6DC" ${st(C.navy,5)}/><circle r="22" fill="none" stroke="#E0B060" stroke-width="2" stroke-dasharray="2 8.7"/><line x1="0" y1="0" x2="0" y2="-14" ${st(C.navy,3.5)}/><line x1="0" y1="0" x2="10" y2="4" ${st(C.navy,3.5)} transform="rotate(${f(T*20)})"/><line x1="0" y1="0" x2="0" y2="-19" ${st('#E5484D',1.8)} transform="rotate(${f(T*90)})"/><circle r="3" fill="${C.navy}"/></g>
<g transform="translate(${f(62+pw)},${f(44+pw*.5)}) rotate(40) scale(.8)"><rect x="-60" y="-8" width="80" height="16" rx="3" fill="#FFC94A" ${st(C.navy,4.5)}/><rect x="-60" y="-8" width="80" height="5" fill="#fff" opacity=".35"/><rect x="-74" y="-8" width="14" height="16" rx="4" fill="#F28FA0" ${st(C.navy,4.5)}/><rect x="-62" y="-8" width="4" height="16" fill="#C8CFD6"/><path d="M20,-8 L44,0 L20,8Z" fill="#F4D7A8" ${st(C.navy,4.5)}/><path d="M38,-2.5 L44,0 L38,2.5Z" fill="${C.navy}"/></g>
</g>`};

/* A2 ep 10 props end */
/* A2 ep 11 props begin */
/* Episode 111 props (A2 ep 11): small acts of kindness - neighbour, car trouble, charity, welcome card, lending. Faceless. Uses C, st, f, ease, clamp, P. */
const _e111SK='#E3AE82';
const _e111PM={c:'#E2B653',hair:'bun',hc:'#2A1D18'},_e111PA={c:'#4DA3D8',hair:'short',hc:'#222'},_e111POLD={c:'#B07AA1',hair:'bun',hc:'#D5D8DB'},_e111POM={c:'#6A8FA8',hair:'short',hc:'#CFD3D6'},_e111PMUM={c:'#D96C8B',hair:'long',hc:'#3A2A22'},_e111PSA={c:'#4F7A5A',hair:'long',hc:'#2A1D18'};
const _e111pp=(x,y,s,o,T,fl)=>`<g transform="translate(${f(x)},${f(y)}) scale(${f(s*(fl?-1:1))},${f(s)})">${P.person(o,T)}</g>`;
const _e111g=(x,y,s,inner)=>`<g transform="translate(${f(x)},${f(y)}) scale(${f(s)})">${inner}</g>`;
const _e111hand=(a,col)=>{col=col||_e111SK;let s='';[-17,-8,1,10].forEach((x,i)=>{s+=`<rect x="${x}" y="${-62+[4,-4,0,8][i]}" width="9" height="${34-[4,-4,0,8][i]*.0+10}" rx="4.5" fill="${col}" ${st(C.navy,3.5)}/>`});
  return `<g transform="rotate(${f(a||0)})">${s}<rect x="-19" y="-36" width="40" height="40" rx="14" fill="${col}" ${st(C.navy,3.5)}/><rect x="-36" y="-30" width="15" height="30" rx="7" transform="rotate(-38 -28 -6)" fill="${col}" ${st(C.navy,3.5)}/></g>`};
const _e111fist=(col)=>{col=col||_e111SK;return `<g><rect x="-22" y="-20" width="44" height="40" rx="14" fill="${col}" ${st(C.navy,3.5)}/><path d="M-8 -18 V-2 M4 -18 V-2 M14 -16 V-2" fill="none" ${st(C.navy,3)}/><rect x="-18" y="2" width="26" height="14" rx="7" fill="${col}" ${st(C.navy,3)}/></g>`};
const _e111car=(col,o)=>{o=o||{};col=col||C.blue;const hood=o.hood;
  const win=o.night?'#2B3D58':C.sky;
  const hoodSVG=hood?`<path d="M82 -22 L112 -16 Q124 -12 124 4 V10 H82Z" fill="#2B3138" ${st()}/><g transform="translate(84,-22) rotate(-64)"><rect x="0" y="-10" width="56" height="13" rx="5" fill="${col}" ${st()}/><rect x="6" y="-7" width="40" height="3" rx="1.5" fill="#fff" opacity=".35"/></g>`:'';
  return `<g><ellipse cx="0" cy="70" rx="132" ry="9" fill="#000" opacity=".18"/><path d="M-124 44 V2 Q-124 -10 -108 -14 L-66 -22 L-40 -60 Q-36 -66 -28 -66 H38 Q48 -66 54 -58 L82 -22 L108 -16 Q124 -10 124 6 V44 Z" fill="${col}" ${st()}/>${hoodSVG}<path d="M-30 -57 H34 L56 -26 H-50 Z" fill="${win}" ${st(C.navy,4)}/><line x1="2" y1="-57" x2="2" y2="-26" ${st(C.navy,4)}/><path d="M-30 -57 L-14 -57 L-34 -26 L-50 -26Z" fill="#fff" opacity=".28"/><path d="M-100 -4 H100" fill="none" stroke="#fff" stroke-width="5" opacity=".28" stroke-linecap="round"/><rect x="-14" y="-18" width="22" height="6" rx="3" fill="${C.navy}" opacity=".6"/><ellipse cx="-70" cy="44" rx="30" ry="26" fill="${C.navy2}"/><ellipse cx="72" cy="44" rx="30" ry="26" fill="${C.navy2}"/><circle cx="-70" cy="46" r="23" fill="${C.navy}"/><circle cx="-70" cy="46" r="10" fill="${C.grey}"/><circle cx="72" cy="46" r="23" fill="${C.navy}"/><circle cx="72" cy="46" r="10" fill="${C.grey}"/><rect x="-126" y="-8" width="8" height="18" rx="3" fill="${C.red}" ${st(C.navy,2.5)}/><ellipse cx="118" cy="0" rx="9" ry="12" fill="#FFE27A" ${st(C.navy,2.5)}/></g>`};
const _e111moon=(x,y,s)=>`<g transform="translate(${x},${y}) scale(${s})"><path d="M30 -88 A80 80 0 1 0 60 52 A62 62 0 0 1 30 -88 Z" fill="#F7E7A8" ${st()}/></g>`;

/* two flat doors side by side (the neighbour's flat next to mine) */
P.e111_flats=(o,T)=>`<g><rect x="-132" y="-104" width="264" height="190" rx="8" fill="#F4E5C2" ${st()}/><rect x="-132" y="70" width="264" height="16" fill="#B98258" ${st()}/><rect x="-100" y="-62" width="82" height="132" rx="6" fill="${C.blue}" ${st()}/><rect x="-88" y="-50" width="58" height="46" rx="4" fill="#6FB1D6" ${st(C.navy,3)}/><circle cx="-34" cy="12" r="6" fill="${C.gold}" ${st(C.navy,3)}/><rect x="18" y="-62" width="82" height="132" rx="6" fill="${C.brown}" ${st()}/><rect x="30" y="-50" width="58" height="46" rx="4" fill="#A9743F" ${st(C.navy,3)}/><circle cx="84" cy="12" r="6" fill="${C.gold}" ${st(C.navy,3)}/><rect x="-86" y="-90" width="54" height="14" rx="4" fill="${C.cream}" ${st(C.navy,3)}/><rect x="32" y="-90" width="54" height="14" rx="4" fill="${C.cream}" ${st(C.navy,3)}/><g transform="translate(-60,70)"><ellipse cx="0" cy="0" rx="34" ry="6" fill="#8B5E3C" ${st(C.navy,3)}/></g><g transform="translate(60,70)"><ellipse cx="0" cy="0" rx="34" ry="6" fill="#C0504D" ${st(C.navy,3)}/></g><g transform="translate(-118,56)"><path d="M-10 0 L10 0 L6 28 L-6 28Z" fill="#C0504D" ${st(C.navy,3)}/><path d="M0 0 V-24 M0 -8 L-12 -18 M0 -14 L12 -26" fill="none" ${st(C.leaf,4)}/><circle cx="-12" cy="-20" r="6" fill="${C.gold}"/><circle cx="12" cy="-28" r="6" fill="#F4A7B9"/></g></g>`;

/* a plate that fell and broke: crash on the floor */
P.e111_fall=(o,T,k)=>{const t=clamp(k/.55),fall=t<1,y=fall?-90+t*t*150:60;let w='';
  const b=ease((k-.5)/.4);
  const pieces=[[-34,-10,-22],[10,6,28],[40,-14,12],[-8,-24,-40]];
  if(!fall){pieces.forEach(([dx,dy,r],i)=>{w+=`<g transform="translate(${f(dx*b*1.4)},${f(56-Math.abs(dy)*b*.3)}) rotate(${r})"><path d="M-26 0 L26 -6 L8 20 Z" fill="${C.white}" ${st(C.navy,4)}/><path d="M-26 0 L-10 -3" ${st(C.blue,5)} fill="none"/></g>`});
    for(let i=0;i<8;i++){const a=i*Math.PI/4,r=64+b*26;w+=`<line x1="${f(Math.cos(a)*r)}" y1="${f(30+Math.sin(a)*r*.7)}" x2="${f(Math.cos(a)*(r+20))}" y2="${f(30+Math.sin(a)*(r+20)*.7)}" ${st(C.orange,5)} opacity="${f(.9-b*.5)}"/>`}}
  const plate=fall?`<g transform="translate(0,${f(y)}) rotate(${f(t*40)})"><ellipse rx="52" ry="16" fill="${C.white}" ${st()}/><ellipse rx="34" ry="8" fill="#E6EEF2" ${st(C.blue,3)}/></g>`:'';
  return `<g><rect x="-132" y="72" width="264" height="18" rx="4" fill="#B98258" ${st()}/><rect x="-132" y="-80" width="264" height="152" fill="#F4E5C2" opacity=".0"/>${plate}${w}</g>`};

/* knock on a door */
P.e111_knock=(o,T)=>{const kn=Math.max(0,Math.sin(T*7)),dx=-kn*16;let r='';for(let i=0;i<3;i++){const a=(T*1.7+i/3)%1;r+=`<path d="M${f(-20-a*30)} ${f(-30-i*0)} q-10 ${f(14)} 0 ${f(28)}" fill="none" ${st(C.goldD,5)} opacity="${f((1-a)*(kn>.2?1:.4))}" transform="translate(0,${i*18-10})"/>`}
  return `<g><rect x="-30" y="-120" width="130" height="236" rx="8" fill="${C.brown}" ${st()}/><rect x="-14" y="-102" width="98" height="92" rx="6" fill="#A9743F" ${st(C.navy,3)}/><rect x="-14" y="8" width="98" height="90" rx="6" fill="#A9743F" ${st(C.navy,3)}/><circle cx="84" cy="14" r="8" fill="${C.gold}" ${st(C.navy,3)}/><g transform="translate(${f(-56+dx)},-4)"><rect x="-90" y="-18" width="64" height="38" rx="10" fill="${C.blue}" ${st()}/><g transform="translate(-4,0) rotate(90)">${_e111fist()}</g></g>${r}</g>`};

/* tea for two */
P.e111_teatwo=(o,T)=>{let s='';for(let i=0;i<3;i++){const a=(T*.8+i/3)%1;s+=`<path d="M${-6+i*14} ${f(-44-a*34)} q-8 -10 0 -20 t0 -20" fill="none" ${st('#9AA7B0',4)} opacity="${f(1-a)}"/>`}
  const cup=(x)=>`<g transform="translate(${x},40)"><ellipse cx="0" cy="26" rx="34" ry="7" fill="${C.cream}" ${st(C.navy,3)}/><path d="M-26 -8 H26 L20 18 Q0 32 -20 18Z" fill="${C.white}" ${st(C.navy,4)}/><path d="M26 0 a11 11 0 1 1 -4 16" fill="none" ${st(C.navy,4)}/><ellipse cx="0" cy="-8" rx="26" ry="5" fill="#B36B2C" ${st(C.navy,3)}/></g>`;
  return `<g><rect x="-126" y="64" width="252" height="16" rx="6" fill="${C.brown}" ${st()}/><rect x="-104" y="80" width="12" height="40" fill="${C.brown}" ${st(C.navy,4)}/><rect x="92" y="80" width="12" height="40" fill="${C.brown}" ${st(C.navy,4)}/><g transform="translate(0,28)">${s}<path d="M-34 -36 h68 q10 42 -8 66 h-52 q-18 -24 -8 -66Z" fill="#E88CA2" ${st()}/><ellipse cx="0" cy="-36" rx="34" ry="8" fill="#D9738A" ${st()}/><path d="M-22 -50 q22 -22 44 0" fill="none" ${st(C.navy,5)}/><circle cx="0" cy="-58" r="6" fill="${C.gold}" ${st(C.navy,3)}/><path d="M34 -18 q30 -2 30 -30 q-6 6 -28 10" fill="#E88CA2" ${st(C.navy,4)}/><path d="M-34 -18 q-22 -4 -26 -20" fill="none" ${st(C.navy,6)}/><path d="M-22 -26 q-4 20 4 40" fill="none" stroke="#fff" stroke-width="5" opacity=".5" stroke-linecap="round"/></g>${cup(-88)}${cup(88)}</g>`};

/* invitation card with a flower; o.door => sliding under a door */
const _e111card=(w,h)=>`<g><rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="8" fill="#FFF4D6" ${st()}/><rect x="${-w/2+8}" y="${-h/2+8}" width="${w-16}" height="${h-16}" rx="4" fill="none" stroke="${C.gold2}" stroke-width="3" stroke-dasharray="7 5"/><g transform="translate(${w/2-34},${-h/2+34})"><g fill="#F4A7B9" ${st(C.navy,2.5)}>${[0,72,144,216,288].map(a=>`<circle cx="${f(Math.cos(a*Math.PI/180)*11)}" cy="${f(Math.sin(a*Math.PI/180)*11)}" r="9"/>`).join('')}</g><circle r="7" fill="${C.gold}" ${st(C.navy,2.5)}/></g><path d="M${-w/2+20} ${-h/2+34} h${w*.4}" ${st(C.navy2,4)} fill="none"/><path d="M${-w/2+20} ${-h/2+54} h${w*.62}" ${st('#9AA7B0',4)} fill="none"/><path d="M${-w/2+20} ${-h/2+72} h${w*.55}" ${st('#9AA7B0',4)} fill="none"/><path d="M${-w/2+20} ${-h/2+90} h${w*.3}" ${st('#9AA7B0',4)} fill="none"/></g>`;
P.e111_invcard=(o,T,k)=>{if(!o.door)return `<g transform="rotate(${f(Math.sin(T*1.4)*3-4)})">${_e111card(200,140)}</g>`;
  const p=ease(k/.9);return `<g><rect x="-86" y="-120" width="172" height="190" rx="8" fill="${C.brown}" ${st()}/><rect x="-68" y="-102" width="136" height="78" rx="6" fill="#A9743F" ${st(C.navy,3)}/><circle cx="58" cy="-6" r="7" fill="${C.gold}" ${st(C.navy,3)}/><rect x="-86" y="66" width="172" height="6" fill="#2B3138"/><rect x="-140" y="72" width="280" height="30" fill="#D9C79A" ${st()}/><g transform="translate(${f(-8+(1-p)*0)},${f(96-(1-p)*26)}) rotate(-6)"><rect x="-70" y="-22" width="140" height="34" rx="5" fill="#FFF4D6" ${st()}/><rect x="-62" y="-14" width="124" height="18" rx="3" fill="none" stroke="${C.gold2}" stroke-width="2.5" stroke-dasharray="6 4"/><circle cx="46" cy="-6" r="7" fill="#F4A7B9" ${st(C.navy,2.5)}/><circle cx="46" cy="-6" r="3" fill="${C.gold}"/></g></g>`};

/* tin of biscuits */
P.e111_biscuits=(o,T)=>{const b=(x,y,r)=>`<g transform="translate(${x},${y}) rotate(${r})"><circle r="26" fill="#E1A25B" ${st('#A9741F',4)}/><circle r="17" fill="none" stroke="#C98842" stroke-width="3" stroke-dasharray="3 5"/><circle cx="-7" cy="-6" r="3" fill="#8B5E3C"/><circle cx="8" cy="3" r="3" fill="#8B5E3C"/><circle cx="-2" cy="11" r="3" fill="#8B5E3C"/></g>`;
  return `<g><ellipse cx="0" cy="96" rx="104" ry="12" fill="#000" opacity=".15"/><path d="M-82 -8 V82 Q0 112 82 82 V-8Z" fill="${C.red}" ${st()}/><path d="M-82 30 Q0 58 82 30 V54 Q0 82 -82 54Z" fill="${C.gold}" ${st(C.navy,4)}/><path d="M-64 -4 V70" stroke="#fff" stroke-width="6" opacity=".25" stroke-linecap="round"/><ellipse cx="0" cy="-8" rx="82" ry="22" fill="#B8423F" ${st()}/><ellipse cx="0" cy="-8" rx="68" ry="15" fill="#6B2E2A"/>${b(-34,-26,-10)}${b(30,-30,14)}${b(-2,-46,4)}</g>`};

/* phone with photos */
P.e111_phonephotos=(o,T)=>{const hi=Math.floor(T*1.2)%4;
  const tile=(x,y,i,bg,inner)=>`<g transform="translate(${x},${y})"><rect width="44" height="44" rx="6" fill="${bg}" ${st(C.navy,i===hi?5:3)}/>${inner}</g>`;
  const fl=`<path d="M22 40 V22" ${st(C.leaf,3)} fill="none"/><circle cx="22" cy="18" r="8" fill="#F4A7B9" ${st(C.navy,2.5)}/><circle cx="22" cy="18" r="3.5" fill="${C.gold}"/>`;
  const ck=`<rect x="8" y="22" width="28" height="16" rx="3" fill="#F4C6D2" ${st(C.navy,2.5)}/><circle cx="22" cy="18" r="5" fill="${C.red}" ${st(C.navy,2)}/>`;
  const tr=`<circle cx="22" cy="18" r="13" fill="${C.leaf}" ${st(C.navy,2.5)}/><rect x="19" y="28" width="6" height="12" fill="${C.brown}"/>`;
  const hs=`<rect x="8" y="20" width="28" height="20" fill="#F4E5C2" ${st(C.navy,2.5)}/><polygon points="5,21 22,7 39,21" fill="${C.red}" ${st(C.navy,2.5)}/>`;
  return `<g><rect x="-66" y="-116" width="132" height="232" rx="24" fill="${C.navy}" ${st()}/><rect x="-55" y="-98" width="110" height="196" rx="12" fill="${C.cream}"/>${tile(-52,-80,0,'#DFF1F8',fl)}${tile(8,-80,1,'#FFE9C7',ck)}${tile(-52,-24,2,'#DFF1F8',tr)}${tile(8,-24,3,'#FFE9C7',hs)}${tile(-52,32,4,'#E6F0DA',fl)}${tile(8,32,5,'#DFF1F8',ck)}<rect x="-22" y="86" width="44" height="6" rx="3" fill="${C.navy}" opacity=".35"/><circle cx="0" cy="-107" r="3" fill="#41525c"/></g>`};

/* two people and arrows: kindness goes both ways */
P.e111_bothways=(o,T)=>{const b=Math.sin(T*3)*3;
  return `<g>${_e111pp(-98,10,.62,_e111PM,T)}${_e111pp(98,10,.62,_e111POLD,T,1)}<g transform="translate(0,${f(-34+b)})"><path d="M-48 0 Q0 -40 48 0" fill="none" ${st(C.moss,7)}/><path d="M34 -10 L50 2 L30 8" fill="none" ${st(C.moss,7)}/></g><g transform="translate(0,${f(40-b)})"><path d="M48 0 Q0 40 -48 0" fill="none" ${st(C.red,7)}/><path d="M-34 10 L-50 -2 L-30 -8" fill="none" ${st(C.red,7)}/></g><g transform="translate(0,${f(-8)}) scale(.38)">${P.heart({},T)}</g></g>`};

/* a car with its bonnet up and smoke (broken down); o.night */
P.e111_brokecar=(o,T)=>{let sm='';for(let i=0;i<4;i++){const a=(T*.7+i/4)%1;sm+=`<circle cx="${f(108+Math.sin(T*2+i)*8+a*16)}" cy="${f(-60-a*70)}" r="${f(8+a*16)}" fill="#C7D0D6" ${st('#8FA0AB',3)} opacity="${f(1-a)}"/>`}
  const tri=`<g transform="translate(-170,40)"><polygon points="0,-46 34,14 -34,14" fill="${C.red}" ${st()}/><polygon points="0,-28 18,2 -18,2" fill="#fff"/></g>`;
  const hz=Math.sin(T*6)>0?'#FFB02E':'#7A5320';
  return `<g><rect x="-200" y="66" width="400" height="30" rx="4" fill="#3B4350" ${st(C.navy,4)}/><path d="M-170 82 h40 M-100 82 h40 M-30 82 h40 M40 82 h40 M110 82 h40" ${st('#E8E2CF',5)} fill="none"/>${tri}${_e111car(o.col||C.red,{hood:1,night:o.night})}${sm}<circle cx="-120" cy="-6" r="7" fill="${hz}"/><circle cx="116" cy="8" r="6" fill="${hz}"/></g>`};

/* phone with almost-empty battery */
P.e111_lowphone=(o,T)=>{const bl=Math.sin(T*5)>-.2;
  return `<g><rect x="-62" y="-112" width="124" height="224" rx="24" fill="${C.navy}" ${st()}/><rect x="-52" y="-94" width="104" height="188" rx="12" fill="#2B3138"/><g transform="translate(0,-8)"><rect x="-36" y="-26" width="68" height="40" rx="8" fill="none" ${st('#C7D0D6',6)}/><rect x="32" y="-14" width="9" height="16" rx="3" fill="#C7D0D6"/><rect x="-28" y="-18" width="12" height="24" rx="3" fill="${bl?C.red:'#6B2E2A'}"/></g><path d="M-26 40 h52 M-16 58 h32" ${st('#4B545C',5)} fill="none"/><circle cx="0" cy="-103" r="3" fill="#41525c"/></g>`};

/* car with headlights driving at night */
P.e111_headlights=(o,T)=>{const bm=.55+.2*Math.sin(T*3);
  return `<g><rect x="-210" y="66" width="420" height="30" rx="4" fill="#3B4350" ${st(C.navy,4)}/><path d="M-170 82 h40 M-100 82 h40 M-30 82 h40 M40 82 h40 M110 82 h40" ${st('#E8E2CF',5)} fill="none"/><g transform="translate(${f(Math.sin(T*2)*3-50)},0)"><polygon points="124,-4 290,-62 290,56" fill="#FFF3B0" opacity="${f(bm)}"/><polygon points="124,0 290,-22 290,30" fill="#FFF3B0" opacity=".35"/>${_e111car(o.col||'#4DA3D8',{night:1})}</g></g>`};

/* a person waving both hands */
P.e111_waving=(o,T)=>{const w=Math.sin(T*7)*14;const oc=o.pc||{c:'#4DA3D8',hair:'short',hc:'#222'};
  const arm=(sx)=>`<g><path d="M${sx*52} 44 L${sx*92} -34" fill="none" ${st(C.navy,30)}/><path d="M${sx*52} 44 L${sx*92} -34" fill="none" stroke="${oc.c}" stroke-width="22" stroke-linecap="round"/><g transform="translate(${sx*96},-40) rotate(${f(w*sx)}) scale(.62)">${_e111hand(0)}</g></g>`;
  return `<g>${arm(-1)}${arm(1)}${P.person(oc,T)}</g>`};

/* the driver of a car, in the open window (close-up) */
P.e111_driverwin=(o,T)=>`<g><rect x="-130" y="-100" width="260" height="210" rx="20" fill="#B8A99A" ${st()}/><rect x="-130" y="38" width="260" height="14" fill="#A39482"/><clipPath id="e111_dw"><path d="M-104 -80 H70 L100 20 H-104 Z"/></clipPath><g clip-path="url(#e111_dw)"><rect x="-110" y="-90" width="220" height="120" fill="#2B3D58"/>${_e111pp(-4,-4,.88,{c:'#7A6A5A',hair:'short',hc:'#D5D8DB'},T)}</g><path d="M-104 -80 H70 L100 20 H-104 Z" fill="none" ${st(C.navy,7)}/><path d="M-104 -80 H-60 L-90 20 H-104Z" fill="#fff" opacity=".18"/><rect x="104" y="-40" width="40" height="30" rx="10" fill="#B8A99A" ${st()}/><rect x="-60" y="62" width="64" height="12" rx="6" fill="${C.navy}" opacity=".6"/><rect x="-130" y="96" width="260" height="14" fill="${C.navy}" opacity=".2"/></g>`;

/* two persons pushing a car to the side */
P.e111_pushcar=(o,T)=>{const s=Math.sin(T*3)*3,arm=(x,y)=>`<path d="M${x} ${y} L-88 14" fill="none" ${st(C.navy,17)}/><path d="M${x} ${y} L-88 14" fill="none" stroke="#E3AE82" stroke-width="10" stroke-linecap="round"/>`;
  return `<g><rect x="-270" y="66" width="540" height="30" rx="4" fill="#3B4350" ${st(C.navy,4)}/><g transform="translate(${f(50+s)},0)">${_e111car(C.red,{night:1})}</g><g transform="translate(${f(s)},0)">${_e111pp(-210,16,.44,{c:'#7A6A5A',hair:'short',hc:'#D5D8DB'},T)}${arm(-186,34)}${_e111pp(-146,10,.46,_e111PA,T)}${arm(-120,30)}</g><g transform="translate(-40,-112)"><path d="M0 0 H70 M52 -14 L72 0 L52 14" fill="none" ${st(C.gold,8)}/></g></g>`};

/* a hand lends a phone to another hand */
P.e111_lendphone=(o,T)=>{const b=Math.sin(T*3)*6;
  return `<g><g transform="translate(${f(30+b*.4)},4) rotate(8)"><rect x="-44" y="-100" width="88" height="160" rx="18" fill="${C.navy}" ${st()}/><rect x="-36" y="-86" width="72" height="130" rx="9" fill="${C.cream}"/><rect x="-22" y="-62" width="44" height="14" rx="7" fill="${C.cold}"/><rect x="-10" y="-38" width="32" height="14" rx="7" fill="${C.gold}"/><rect x="-22" y="-14" width="44" height="14" rx="7" fill="${C.cold}"/></g><g transform="translate(${f(70+b*.4)},96) rotate(-14)"><rect x="-26" y="0" width="52" height="50" rx="10" fill="#6A8FA8" ${st()}/><rect x="-30" y="-48" width="52" height="56" rx="18" fill="${_e111SK}" ${st(C.navy,3.5)}/><rect x="-36" y="-30" width="15" height="26" rx="7" transform="rotate(30 -28 -14)" fill="${_e111SK}" ${st(C.navy,3.5)}/></g><g transform="translate(${f(-100+b)},60) rotate(40)">${_e111hand(0)}<rect x="-24" y="2" width="48" height="44" rx="8" fill="#B07AA1" ${st()}/></g><path d="M-30 -92 q30 -34 70 -20" fill="none" ${st(C.gold,6)}/><path d="M30 -122 l14 10 l-16 8" fill="none" ${st(C.gold,6)}/></g>`};

/* wrench and screwdriver (a friend who fixes cars) */
P.e111_wrench=(o,T)=>{const r=Math.sin(T*2)*3;
  return `<g transform="rotate(${f(r)})"><g transform="rotate(-40)"><rect x="-12" y="-20" width="24" height="150" rx="10" fill="#B9C6CE" ${st()}/><path d="M-30 -20 Q-34 -70 -12 -84 L-12 -52 L12 -52 L12 -84 Q34 -70 30 -20Z" fill="#B9C6CE" ${st()}/><rect x="-6" y="40" width="5" height="70" rx="2" fill="#fff" opacity=".5"/></g><g transform="rotate(40)"><rect x="-8" y="-100" width="16" height="130" rx="4" fill="#B9C6CE" ${st()}/><rect x="-14" y="20" width="28" height="100" rx="12" fill="${C.orange}" ${st()}/><rect x="-14" y="46" width="28" height="12" fill="${C.red}" opacity=".7"/></g><g transform="translate(70,-72)"><circle r="26" fill="${C.gold}" ${st()}/><circle r="10" fill="#FFF8E6" ${st(C.navy,4)}/>${[0,60,120,180,240,300].map(a=>`<rect x="-5" y="-34" width="10" height="12" fill="${C.gold}" ${st(C.navy,3)} transform="rotate(${a+T*20})"/>`).join('')}</g></g>`};

/* bottle of water and a bowl of dates */
P.e111_waterdates=(o,T)=>{const dt=(x,y,r)=>`<g transform="translate(${x},${y}) rotate(${r})"><ellipse rx="17" ry="11" fill="#7B4A2B" ${st('#4B2A18',3)}/><path d="M-9 -3 q9 -4 18 0" fill="none" stroke="#B07A55" stroke-width="2.5"/></g>`;
  return `<g><g transform="translate(-62,0)"><rect x="-14" y="-102" width="28" height="16" rx="4" fill="${C.blue}" ${st()}/><path d="M-14 -86 H14 L16 -74 Q34 -62 34 -42 V76 Q34 90 20 90 H-20 Q-34 90 -34 76 V-42 Q-34 -62 -16 -74Z" fill="#EAF6FB" ${st()}/><path d="M-34 -4 H34 V62 H-34Z" fill="${C.blue}" opacity=".35"/><rect x="-34" y="10" width="68" height="34" fill="#fff" opacity=".85"/><path d="M-20 27 h40" ${st(C.blue,5)} fill="none"/><path d="M-22 -50 V40" stroke="#fff" stroke-width="5" opacity=".8" stroke-linecap="round"/></g><g transform="translate(60,34)"><ellipse cx="0" cy="38" rx="62" ry="12" fill="#000" opacity=".14"/><path d="M-64 0 H64 Q60 52 0 58 Q-60 52 -64 0Z" fill="${C.brown}" ${st()}/><ellipse cx="0" cy="0" rx="64" ry="14" fill="#A9743F" ${st()}/>${dt(-30,-4,-10)}${dt(0,-10,12)}${dt(30,-4,-18)}${dt(-14,-16,20)}${dt(16,-20,-6)}</g></g>`};

/* car driving away at night: tail lights getting smaller */
P.e111_taillights=(o,T,k)=>{const p=clamp(k/6),sc=1-p*.55,y=40-p*40;
  return `<g><polygon points="-30,-110 30,-110 190,110 -190,110" fill="#3B4350" ${st(C.navy,4)}/><path d="M0 -104 V-84 M0 -66 V-40 M0 -20 V20 M0 52 V108" ${st('#E8E2CF',6)} fill="none"/><g transform="translate(0,${f(y)}) scale(${f(sc)})"><ellipse cx="0" cy="62" rx="68" ry="8" fill="#000" opacity=".25"/><rect x="-62" y="-6" width="124" height="62" rx="16" fill="#4DA3D8" ${st()}/><path d="M-46 -6 L-34 -42 H34 L46 -6Z" fill="#4DA3D8" ${st()}/><path d="M-34 -10 L-26 -34 H26 L34 -10Z" fill="#2B3D58" ${st(C.navy,3)}/><rect x="-54" y="18" width="26" height="14" rx="5" fill="#FF4B3E" ${st(C.navy,3)}/><rect x="28" y="18" width="26" height="14" rx="5" fill="#FF4B3E" ${st(C.navy,3)}/><rect x="-18" y="38" width="36" height="10" rx="3" fill="#fff" ${st(C.navy,3)}/><circle cx="-44" cy="58" r="12" fill="${C.navy}"/><circle cx="44" cy="58" r="12" fill="${C.navy}"/></g></g>`};

/* people helping each other in a chain: pay it forward */
P.e111_chain=(o,T)=>{const b=Math.sin(T*3)*3;const ar=(x)=>`<g transform="translate(${x},${f(-76+b)})"><path d="M-38 12 Q0 -26 38 12" fill="none" ${st(C.moss,7)}/><path d="M24 -2 L40 12 L20 18" fill="none" ${st(C.moss,7)}/><g transform="translate(0,-24) scale(.3)">${P.heart({},T)}</g></g>`;
  return `<g>${_e111pp(-150,24,.6,{c:'#7A6A5A',hair:'short',hc:'#D5D8DB'},T)}${_e111pp(0,24,.6,_e111PA,T)}${_e111pp(150,24,.6,{c:'#F2994A',hair:'long',hc:'#3A2A22'},T)}${ar(-75)}${ar(75)}</g>`};

/* name tag with a question mark: no name */
P.e111_noname=(o,T)=>`<g transform="rotate(${f(Math.sin(T*1.6)*4-4)})"><rect x="-112" y="-84" width="224" height="168" rx="14" fill="${C.white}" ${st()}/><path d="M-112 -70 Q-112 -84 -98 -84 H98 Q112 -84 112 -70 V-22 H-112Z" fill="${C.red}" ${st()}/><text x="0" y="-38" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="40" fill="${C.cream}" letter-spacing="5">HELLO</text><text x="0" y="-4" text-anchor="middle" font-family="Fraunces" font-weight="600" font-size="22" fill="${C.cream}" opacity="0">.</text><text x="0" y="62" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="84" fill="${C.goldD}">?</text></g>`;

/* two people alike: I am a human being, like you */
P.e111_alike=(o,T)=>`<g>${_e111pp(-84,10,.78,_e111PA,T)}${_e111pp(84,10,.78,{c:'#7A6A5A',hair:'short',hc:'#D5D8DB'},T)}<rect x="-20" y="-24" width="40" height="9" rx="4" fill="${C.gold}" ${st(C.navy,3)}/><rect x="-20" y="2" width="40" height="9" rx="4" fill="${C.gold}" ${st(C.navy,3)}/><g transform="translate(0,-122) scale(.34)">${P.heart({},T)}</g></g>`;

/* ---------- charity ---------- */
const _e111loaf=(x,y,r)=>`<g transform="translate(${x},${y}) rotate(${r})"><rect x="-26" y="-14" width="52" height="28" rx="14" fill="#E1A25B" ${st(C.navy,4)}/><path d="M-12 -10 l6 20 M0 -12 l6 24 M12 -10 l6 20" fill="none" stroke="#B9772F" stroke-width="3" stroke-linecap="round"/></g>`;
const _e111apple=(x,y)=>`<g transform="translate(${x},${y})"><circle r="15" fill="${C.red}" ${st(C.navy,4)}/><path d="M0 -14 q2 -10 8 -12" fill="none" ${st(C.brown,4)}/><ellipse cx="8" cy="-20" rx="7" ry="4" fill="${C.leaf}" ${st(C.navy,2.5)} transform="rotate(-25 8 -20)"/></g>`;
const _e111milk=(x,y,s)=>`<g transform="translate(${x},${y}) scale(${s})"><path d="M-18 -44 H18 V38 H-18Z" fill="${C.white}" ${st(C.navy,4)}/><path d="M-18 -44 L0 -62 L18 -44Z" fill="${C.blue}" ${st(C.navy,4)}/><rect x="-18" y="-20" width="36" height="34" fill="${C.blue}" opacity=".85"/><circle cx="0" cy="-3" r="9" fill="#fff"/></g>`;
const _e111carrot=(x,y,r)=>`<g transform="translate(${x},${y}) rotate(${r})"><path d="M-9 -30 Q0 -44 9 -30 L2 30 Q0 36 -2 30Z" fill="${C.orange}" ${st(C.navy,3.5)}/><path d="M0 -30 l-6 -16 M0 -30 l2 -20 M0 -30 l8 -14" fill="none" ${st(C.leaf,4)}/></g>`;
const _e111box=(open)=>`<g><path d="M-82 -20 L-96 -52 L-52 -42Z" fill="#C9A06A" ${st()}/><path d="M82 -20 L96 -52 L52 -42Z" fill="#C9A06A" ${st()}/><path d="M-84 -26 H84 V76 H-84Z" fill="#D2A66A" ${st()}/><rect x="-84" y="-26" width="168" height="20" fill="#BE9158" ${st()}/><rect x="-24" y="-8" width="48" height="14" rx="4" fill="#fff" opacity=".35"/></g>`;
P.e111_foodbox=(o,T)=>`<g><g transform="translate(0,${f(Math.sin(T*2)*2)})">${_e111carrot(-48,-34,-14)}${_e111carrot(-30,-40,10)}${_e111milk(10,-34,.9)}${_e111apple(52,-26)}${_e111loaf(-44,-14,-8)}${_e111loaf(40,-8,10)}${_e111box()}</g><ellipse cx="0" cy="92" rx="100" ry="10" fill="#000" opacity=".14"/></g>`;

/* the public hall where families get a hot meal */
P.e111_hall=(o,T)=>{let st1='';for(let i=0;i<3;i++){const a=(T*.8+i/3)%1;st1+=`<path d="M${-14+i*14} ${f(8-a*30)} q-6 -9 0 -18 t0 -18" fill="none" ${st('#9AA7B0',4)} opacity="${f(1-a)}"/>`}
  return `<g><polygon points="-136,-30 0,-112 136,-30" fill="${C.red}" ${st()}/><rect x="-120" y="-30" width="240" height="100" fill="#F4E5C2" ${st()}/><rect x="-86" y="-64" width="172" height="28" rx="6" fill="${C.cream}" ${st(C.navy,3)}/><text x="0" y="-44" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="19" fill="${C.navy}" letter-spacing="2">PUBLIC HALL</text><rect x="-104" y="-8" width="40" height="38" fill="#FFE08A" ${st(C.navy,3)}/><rect x="-104" y="-8" width="40" height="38" fill="none" ${st(C.navy,3)}/><path d="M-84 -8 V30 M-104 11 H-64" ${st(C.navy,3)} fill="none"/><rect x="-26" y="6" width="52" height="64" rx="4" fill="${C.brown}" ${st()}/><path d="M0 6 V70" ${st(C.navy,3)} fill="none"/><rect x="-136" y="70" width="272" height="14" fill="#DCD2B8" ${st()}/><g transform="translate(84,34)"><g transform="translate(0,-4)">${st1}</g><path d="M-30 4 H30 Q26 40 0 44 Q-26 40 -30 4Z" fill="${C.white}" ${st()}/><ellipse cx="0" cy="4" rx="30" ry="7" fill="#E1A25B" ${st()}/></g></g>`};

/* e-mail sent to everyone in the office */
P.e111_email=(o,T)=>{const fl=((T*.7)%1);
  return `<g><g transform="translate(0,${f(-70-Math.sin(T*3)*4)})"><rect x="-70" y="-44" width="140" height="92" rx="12" fill="${C.cream}" ${st()}/><path d="M-66 -38 L0 14 L66 -38" fill="none" ${st()}/><path d="M-66 44 L-18 2 M66 44 L18 2" fill="none" ${st(C.navy,4)}/><circle cx="62" cy="-44" r="14" fill="${C.red}" ${st()}/></g><g transform="translate(0,96)">${[-150,-75,0,75,150].map((x,i)=>_e111pp(x,0,.38,[{c:'#D9534F',hair:'short',hc:'#3A2A22'},{c:'#4F7A5A',hair:'long',hc:'#2A1D18'},_e111PM,_e111PA,{c:'#8E6BB5',hair:'bun',hc:'#6A3F26'}][i],T+i)).join('')}</g><path d="M-30 -2 V36 M0 -2 V36 M30 -2 V36" ${st(C.goldD,5)} fill="none" stroke-dasharray="6 8" stroke-dashoffset="${f(-T*20)}"/></g>`};

/* cake day stall in the office kitchen */
P.e111_cakestall=(o,T)=>{let aw='';for(let i=0;i<6;i++)aw+=`<path d="M${-108+i*36} -62 h36 v28 q-18 14 -36 0Z" fill="${i%2?'#fff':C.red}" ${st(C.navy,3)}/>`;
  const cake=(x,y,c)=>`<g transform="translate(${x},${y})"><ellipse cx="0" cy="22" rx="30" ry="7" fill="${C.cream}" ${st(C.navy,3)}/><path d="M-24 22 V0 H24 V22Z" fill="${c}" ${st(C.navy,3.5)}/><path d="M-24 0 q6 -10 12 0 t12 0 t12 0 t12 0" fill="#fff" ${st(C.navy,3)}/><circle cx="0" cy="-8" r="6" fill="${C.red}" ${st(C.navy,2.5)}/></g>`;
  return `<g><rect x="-100" y="-66" width="8" height="140" fill="${C.navy2}"/><rect x="92" y="-66" width="8" height="140" fill="${C.navy2}"/><rect x="-112" y="-96" width="224" height="38" rx="8" fill="${C.gold2}" ${st()}/><text x="0" y="-70" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="24" fill="${C.navy}" letter-spacing="3">CAKE DAY</text>${aw}<rect x="-120" y="30" width="240" height="14" rx="5" fill="${C.brown}" ${st()}/><rect x="-108" y="44" width="216" height="40" fill="#A9743F" ${st()}/>${cake(-70,6,'#F4C6D2')}${cake(-10,6,'#F2C98A')}<g transform="translate(46,14)"><ellipse cx="0" cy="10" rx="30" ry="7" fill="${C.cream}" ${st(C.navy,3)}/><g transform="translate(-8,0)"><circle r="10" fill="#E1A25B" ${st('#A9741F',3)}/></g><g transform="translate(8,-4)"><circle r="10" fill="#E1A25B" ${st('#A9741F',3)}/></g><g transform="translate(0,4)"><circle r="10" fill="#E1A25B" ${st('#A9741F',3)}/></g></g><g transform="translate(96,22) scale(.34)">${P.coins({},T)}</g></g>`};

/* one day of cake vs two weeks of emails: coin stacks */
P.e111_vs=(o,T,k)=>{const stack=(x,n,col)=>{let s='';for(let i=0;i<n;i++){const p=ease((k-.3-i*.07)/.25);s+=`<g opacity="${f(p)}" transform="translate(${x},${f(70-i*13-(1-p)*20)})"><ellipse rx="40" ry="11" cy="6" fill="${C.goldD}" ${st(C.navy,3)}/><ellipse rx="40" ry="11" fill="${col}" ${st(C.navy,3)}/></g>`}return s};
  return `<g><line x1="-130" y1="86" x2="130" y2="86" ${st(C.navy,5)}/>${stack(-64,9,C.gold)}${stack(64,4,C.gold)}<text x="-64" y="118" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="26" fill="${C.navy}">1 day</text><text x="64" y="118" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="26" fill="${C.navy}">2 weeks</text><g transform="translate(-64,-86) scale(.46)">${P.cake({},T)}</g><g transform="translate(64,-70) scale(.42)">${P.msg({},T,9)}</g></g>`};

/* packing food boxes */
P.e111_packing=(o,T)=>`<g>${_e111pp(0,-34,.62,{c:'#4F7A5A',hair:'bun',hc:'#6A3F26'},T)}<rect x="-130" y="26" width="260" height="14" rx="5" fill="${C.brown}" ${st()}/><rect x="-112" y="40" width="10" height="56" fill="${C.brown}" ${st(C.navy,3)}/><rect x="102" y="40" width="10" height="56" fill="${C.brown}" ${st(C.navy,3)}/><g transform="translate(-72,10) scale(.5)">${_e111box()}</g><g transform="translate(70,6) scale(.5)">${_e111box()}${_e111loaf(0,-30,0)}${_e111apple(-30,-28)}${_e111milk(32,-30,.8)}</g><g transform="translate(0,-4)">${_e111loaf(-8,18,0)}</g></g>`;

/* a child looks into a box of food: milk and biscuits */
P.e111_boxkid=(o,T)=>{const b=Math.sin(T*3)*2;
  return `<g>${_e111pp(0,-50+b,.62,{c:'#F2994A',hair:'bun',hc:'#3A2A22'},T)}<g transform="translate(0,12)"><path d="M-70 -6 H70 V84 H-70Z" fill="#D2A66A" ${st()}/><rect x="-70" y="-6" width="140" height="16" fill="#BE9158" ${st()}/><path d="M-70 -6 L-84 -34 L-48 -26Z" fill="#C9A06A" ${st()}/><path d="M70 -6 L84 -34 L48 -26Z" fill="#C9A06A" ${st()}/><g transform="translate(-38,-28)"><rect x="-20" y="-36" width="40" height="60" rx="4" fill="${C.white}" ${st()}/><rect x="-20" y="-36" width="40" height="18" fill="${C.blue}" ${st()}/><circle cx="0" cy="-2" r="8" fill="${C.blue}"/></g><g transform="translate(36,-20) rotate(8)"><rect x="-26" y="-30" width="52" height="46" rx="5" fill="${C.red}" ${st()}/><circle cx="0" cy="-8" r="13" fill="#E1A25B" ${st('#A9741F',3)}/></g></g><g transform="translate(86,-70)"><polygon points="0,-16 4,-4 16,0 4,4 0,16 -4,4 -16,0 -4,-4" fill="${C.gold}" transform="scale(${f(.9+.3*Math.sin(T*4))})"/></g></g>`};

/* hope: a box with a rising sun and a heart */
P.e111_hope=(o,T,k)=>{let r='';for(let i=0;i<9;i++)r+=`<line x1="0" y1="-70" x2="0" y2="${f(-96-Math.sin(T*4+i)*6)}" transform="rotate(${-80+i*20})" ${st(C.gold,7)}/>`;
  return `<g><g transform="translate(0,-10)">${r}<circle r="58" fill="#FFE27A" ${st(C.goldD,5)} opacity=".95"/></g><g transform="translate(0,70) scale(.7)">${_e111milk(-34,-34,.9)}${_e111loaf(34,-12,6)}${_e111box()}</g><g transform="translate(0,-14) scale(.36)">${P.heart({},T)}</g></g>`};

/* blossom tree for spring */
P.e111_springtree=(o,T)=>{const sw=Math.sin(T*1.2)*1.5;let p='';for(let i=0;i<7;i++){const a=(T*.35+i/7)%1;p+=`<ellipse cx="${f(-70+i*24+Math.sin(T*2+i)*8)}" cy="${f(-20+a*110)}" rx="5" ry="3" fill="#F4A7B9" opacity="${f(1-a*.8)}" transform="rotate(${f(a*160+i*30)} ${f(-70+i*24)} ${f(-20+a*110)})"/>`}
  const bl=[[0,-62,56],[-48,-24,42],[48,-24,42],[0,-10,38],[-20,-76,36],[30,-72,32]];
  return `<g><ellipse cx="0" cy="104" rx="110" ry="10" fill="#6FA66A" ${st(C.navy,3)}/><g transform="rotate(${f(sw)} 0 100)"><path d="M-14 104 L-10 8 H10 L14 104Z" fill="${C.brown}" ${st()}/><path d="M0 40 L-30 10 M0 28 L30 2" fill="none" ${st(C.brown,10)}/>${blob(bl,'#F7B9C9')}${[[-30,-50],[12,-80],[40,-36],[-50,-20],[8,-24],[-8,-60]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="7" fill="#fff"/><circle cx="${x}" cy="${y}" r="2.5" fill="${C.gold}"/>`).join('')}</g>${p}</g>`};

/* the manager (faceless, with a tie) */
P.e111_boss=(o,T)=>`<g>${P.person({c:'#2B3D48',hair:'short',hc:'#3A2A22'},T)}<path d="M-10 -2 L0 12 L10 -2Z" fill="#fff" ${st(C.navy,3)}/><path d="M0 12 L-7 24 L0 70 L7 24Z" fill="${C.red}" ${st(C.navy,3.5)}/><g transform="translate(76,78) scale(.4)">${P.brief({},T)}</g></g>`;

/* ---------- adam's new colleague ---------- */
/* nervous newcomer at an office door (shake lines) */
P.e111_newbie=(o,T)=>{const sh=Math.sin(T*22)*2.5;
  return `<g><rect x="-132" y="-112" width="120" height="206" rx="6" fill="#DCE8EF" ${st()}/><path d="M-72 -112 V94" ${st(C.navy,4)} fill="none"/><rect x="-120" y="-98" width="36" height="150" fill="#fff" opacity=".45"/><circle cx="-80" cy="0" r="6" fill="${C.gold}" ${st(C.navy,3)}/><rect x="-146" y="94" width="148" height="12" rx="4" fill="#B98258" ${st()}/><g transform="translate(${f(60+sh)},0) scale(.9)">${P.person({c:'#F2994A',hair:'short',hc:'#3A2A22',bag:'#4F7A5A'},T)}</g><g ${st(C.navy,5)} fill="none"><path d="M${f(122+sh)} -34 l14 -8 M${f(128+sh)} 0 h18 M${f(122+sh)} 34 l14 8"/><path d="M${f(-4+sh)} -34 l-14 -8 M${f(-8+sh)} 0 h-18 M${f(-4+sh)} 34 l-14 8"/></g></g>`};

/* alone at lunch: one person, empty chairs */
P.e111_lonely=(o,T)=>{const chair=(x,fl)=>`<g transform="translate(${x},34) scale(${fl},1)"><rect x="-6" y="-34" width="50" height="10" rx="4" fill="${C.brown}" ${st(C.navy,4)}/><rect x="-6" y="-34" width="10" height="70" rx="4" fill="${C.brown}" ${st(C.navy,4)}/><rect x="-6" y="14" width="50" height="10" rx="4" fill="${C.brown}" ${st(C.navy,4)}/><rect x="34" y="14" width="10" height="56" fill="${C.brown}" ${st(C.navy,4)}/></g>`;
  return `<g>${chair(-148,-1)}${chair(148,1)}${_e111pp(0,-26,.7,_e111PA,T)}<rect x="-100" y="28" width="200" height="14" rx="6" fill="${C.brown}" ${st()}/><rect x="-80" y="42" width="10" height="58" fill="${C.brown}" ${st(C.navy,3)}/><rect x="70" y="42" width="10" height="58" fill="${C.brown}" ${st(C.navy,3)}/><g transform="translate(0,22)"><rect x="-44" y="-8" width="88" height="10" rx="4" fill="#B9C6CE" ${st(C.navy,3)}/><ellipse cx="-14" cy="-12" rx="22" ry="7" fill="#fff" ${st(C.navy,3)}/><circle cx="26" cy="-14" r="8" fill="${C.red}" ${st(C.navy,3)}/></g><g transform="translate(0,-122) scale(.55)" opacity=".85">${P.rain({},T)}</g></g>`};

/* a laptop (the company gives you one) */
P.e111_laptop=(o,T)=>`<g><rect x="-100" y="-80" width="200" height="130" rx="12" fill="${C.navy2}" ${st()}/><rect x="-88" y="-68" width="176" height="106" rx="4" fill="#DFF1F8"/><rect x="-76" y="-56" width="70" height="10" rx="5" fill="${C.cold}"/><rect x="-76" y="-36" width="110" height="8" rx="4" fill="#B9C6CE"/><rect x="-76" y="-20" width="90" height="8" rx="4" fill="#B9C6CE"/><rect x="-76" y="-4" width="48" height="26" rx="5" fill="${C.gold}" ${st(C.navy,3)}/><path d="M-124 50 H124 L108 76 H-108Z" fill="#B9C6CE" ${st()}/><rect x="-20" y="56" width="40" height="8" rx="4" fill="#8FA0AB"/></g>`;

/* a missing friend: dashed outline person with ? */
P.e111_ghost=(o,T)=>`<g><path d="M-62 108 L-62 36 Q-62 -4 0 -4 Q62 -4 62 36 L62 108 Z" fill="#fff" fill-opacity=".45" ${st('#7A8B96',5)} stroke-dasharray="10 9"/><circle cx="0" cy="-54" r="38" fill="#fff" fill-opacity=".45" ${st('#7A8B96',5)} stroke-dasharray="10 9"/><text x="0" y="-36" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="62" fill="${C.goldD}" transform="rotate(${f(Math.sin(T*3)*6)} 0 -50)">?</text></g>`;

/* welcome sign on a door with bunting */
P.e111_welcome=(o,T)=>{let fl='';const cs=[C.red,C.gold,C.blue,C.moss,C.orange,C.red,C.gold];for(let i=0;i<7;i++)fl+=`<polygon points="${-120+i*40},${-92+Math.sin(i*1.6)*0} ${-100+i*40},-60 ${-80+i*40},-92" fill="${cs[i]}" ${st(C.navy,3)} transform="translate(0,${f(Math.sin(T*3+i)*2)})"/>`;
  return `<g><path d="M-124 -92 Q0 -60 124 -92" fill="none" ${st(C.navy,3)} transform="translate(0,-8)"/>${fl.replace(/translate\(0,/g,'translate(0,')}<rect x="-62" y="-40" width="124" height="148" rx="6" fill="${C.brown}" ${st()}/><rect x="-48" y="-26" width="96" height="60" rx="4" fill="#A9743F" ${st(C.navy,3)}/><circle cx="40" cy="60" r="7" fill="${C.gold}" ${st(C.navy,3)}/><g transform="translate(0,${f(Math.sin(T*2)*2)}) rotate(${f(Math.sin(T*2)*2)} 0 -10)"><path d="M-50 -34 V-18 M50 -34 V-18" ${st(C.navy,4)} fill="none"/><rect x="-92" y="-18" width="184" height="60" rx="10" fill="${C.cream}" ${st()}/><text x="0" y="22" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="34" fill="${C.moss}">Welcome!</text></g></g>`};

/* printer */
P.e111_printer=(o,T)=>{const pp=ease(((T*.5)%1)/.8);
  return `<g><rect x="-60" y="-96" width="120" height="48" fill="${C.white}" ${st()}/><path d="M-40 -84 H40 M-40 -68 H20" ${st('#9AA7B0',4)} fill="none"/><rect x="-100" y="-50" width="200" height="104" rx="16" fill="#C9D3DA" ${st()}/><rect x="-80" y="-34" width="70" height="22" rx="5" fill="${C.navy2}"/><circle cx="52" cy="-22" r="7" fill="${C.moss}" ${st(C.navy,3)}/><circle cx="72" cy="-22" r="7" fill="${C.red}" ${st(C.navy,3)}/><rect x="-74" y="20" width="148" height="12" rx="4" fill="${C.navy}"/><g transform="translate(0,${f(26+pp*16)})"><rect x="-58" y="0" width="116" height="${f(40+pp*10)}" fill="${C.white}" ${st(C.navy,4)}/><path d="M-40 14 H34 M-40 28 H18" ${st('#9AA7B0',4)} fill="none"/></g><rect x="-100" y="54" width="200" height="12" rx="6" fill="#8FA0AB" ${st()}/></g>`};

/* coffee machine (o.cup) */
P.e111_cmachine=(o,T)=>{let s='';for(let i=0;i<3;i++){const a=(T*.8+i/3)%1;s+=`<path d="M${-14+i*14} ${f(34-a*40)} q-6 -10 0 -20 t0 -20" fill="none" ${st('#9AA7B0',4)} opacity="${f(1-a)}"/>`}
  return `<g><rect x="-76" y="-108" width="152" height="196" rx="18" fill="${C.navy2}" ${st()}/><rect x="-76" y="-108" width="152" height="44" rx="18" fill="${C.red}" ${st()}/><rect x="-56" y="-54" width="112" height="46" rx="8" fill="#DFF1F8" ${st(C.navy,3)}/><circle cx="-34" cy="-30" r="8" fill="${C.gold}" ${st(C.navy,3)}/><circle cx="-8" cy="-30" r="8" fill="${C.moss}" ${st(C.navy,3)}/><rect x="14" y="-38" width="32" height="16" rx="5" fill="${C.navy}"/><rect x="-26" y="0" width="52" height="14" rx="4" fill="${C.navy}"/><g transform="translate(0,0)"><path d="M-22 36 H22 L16 78 H-16Z" fill="${C.white}" ${st()}/><path d="M22 44 q16 2 12 16 q-4 8 -12 8" fill="none" ${st(C.navy,4)}/><ellipse cx="0" cy="36" rx="22" ry="5" fill="#6B4226" ${st(C.navy,3)}/>${s}</g><rect x="-76" y="78" width="152" height="12" rx="6" fill="#1B242B"/></g>`};

/* big welcome card with many short messages */
P.e111_bigcard=(o,T)=>{const cols=[C.red,C.blue,C.moss,C.orange,'#8E6BB5'];let m='';const rows=[[-84,-4,'w1'],[-6,-14,'w2'],[-84,32,'w3'],[-6,28,'w4'],[-60,66,'w5']];
  rows.forEach(([x,y],i)=>{m+=`<path d="M${x} ${y} q8 -9 16 0 t16 0 t16 0 t16 0 M${x} ${y+14} q8 -9 16 0 t16 0 t16 0" fill="none" ${st(cols[i%5],4)}/>`});
  return `<g transform="rotate(${f(Math.sin(T*1.3)*2)})"><rect x="-122" y="-100" width="244" height="200" rx="14" fill="#FFF4D6" ${st()}/><rect x="-122" y="-100" width="244" height="56" rx="14" fill="${C.gold}" ${st()}/><rect x="-122" y="-62" width="244" height="18" fill="${C.gold}"/><path d="M-122 -44 H122" ${st(C.navy,4)} fill="none"/><text x="0" y="-62" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="40" fill="${C.navy}">Welcome!</text>${m}<g transform="translate(96,-6) scale(.34)">${P.heart({},T)}</g><g transform="translate(100,60) scale(.3)">${P.sun({},T)}</g></g>`};

/* one kind act becomes two: a heart makes another heart (ripples) */
P.e111_ripple=(o,T,k)=>{let r='';for(let i=0;i<3;i++){const a=(T*.6+i/3)%1;r+=`<circle cx="-30" cy="26" r="${f(20+a*90)}" fill="none" ${st(C.red,5)} opacity="${f(.7-a*.7)}"/>`}
  const p=ease((k-.2)/.7);
  return `<g>${r}<g transform="translate(-30,26) scale(.64)">${P.heart({},T)}</g><g transform="translate(${f(50*p)},${f(-58*p)}) scale(${f(.42*p)})" opacity="${f(p)}">${P.heart({},T+1)}</g><path d="M2 -6 Q30 -6 40 -34" fill="none" ${st(C.goldD,5)} stroke-dasharray="3 9" opacity="${f(p)}"/></g>`};

/* ---------- lending and borrowing ---------- */
/* big travel bag; o.open shows winter clothes inside */
P.e111_suitcase=(o,T)=>{
  if(o.open)return `<g><ellipse cx="0" cy="88" rx="112" ry="8" fill="#000" opacity=".15"/><path d="M-104 -4 H104 L96 78 Q0 92 -96 78Z" fill="#3F7C5A" ${st()}/><g transform="translate(-52,-26) rotate(-10)"><path d="M-34 24 V-16 L-54 14 L-66 6 L-38 -34 H38 L66 6 L54 14 L34 -16 V24Z" fill="${C.red}" ${st()}/><path d="M-34 -2 H34 M-34 10 H34" stroke="#fff" stroke-width="4" opacity=".55"/></g><g transform="translate(44,-26) rotate(8)"><path d="M-30 20 Q-34 -34 0 -38 Q34 -34 30 20Z" fill="${C.blue}" ${st()}/><rect x="-33" y="6" width="66" height="16" rx="6" fill="#fff" ${st(C.navy,3.5)}/><circle cy="-44" r="9" fill="#fff" ${st(C.navy,3.5)}/></g><g transform="translate(0,2)"><path d="M-80 -8 q80 34 160 0" fill="none" ${st(C.navy,17)}/><path d="M-80 -8 q80 34 160 0" fill="none" stroke="${C.orange}" stroke-width="11"/><path d="M-60 6 v-10 M-30 12 v-10 M0 14 v-10 M30 12 v-10 M60 6 v-10" stroke="#fff" stroke-width="4" opacity=".7"/></g><path d="M-104 -4 H-70 L-60 78 H-96Z" fill="#4F9A6E" ${st()}/><path d="M104 -4 H70 L60 78 H96Z" fill="#4F9A6E" ${st()}/></g>`;
  return `<g><path d="M-40 -62 Q-40 -96 0 -96 Q40 -96 40 -62" fill="none" ${st(C.navy,9)}/><rect x="-116" y="-62" width="232" height="140" rx="30" fill="#4F9A6E" ${st()}/><rect x="-116" y="-62" width="232" height="38" rx="30" fill="#3F7C5A" ${st()}/><rect x="-116" y="-44" width="232" height="20" fill="#3F7C5A"/><path d="M-116 -24 H116" ${st(C.navy,4)} fill="none"/><rect x="-70" y="-4" width="140" height="58" rx="14" fill="#6BB88B" ${st(C.navy,4)}/><rect x="-14" y="-12" width="28" height="22" rx="6" fill="${C.gold}" ${st(C.navy,4)}/><path d="M-96 -62 V78 M96 -62 V78" ${st(C.navy,5)} fill="none" opacity=".35"/><g transform="translate(70,-30) rotate(10)"><rect x="-16" y="-2" width="36" height="24" rx="4" fill="${C.cream}" ${st(C.navy,3)}/><circle cx="-6" cy="8" r="3" fill="${C.navy}"/></g><ellipse cx="0" cy="88" rx="112" ry="8" fill="#000" opacity=".15"/></g>`};

/* toolbox with hammer and screwdriver */
P.e111_toolbox=(o,T)=>`<g><g transform="rotate(-18 -30 0)"><rect x="-8" y="-100" width="16" height="70" rx="6" fill="${C.brown}" ${st()}/><rect x="-36" y="-122" width="72" height="30" rx="8" fill="#B9C6CE" ${st()}/></g><g transform="rotate(14 40 0)"><rect x="34" y="-92" width="10" height="64" rx="3" fill="#B9C6CE" ${st()}/><rect x="28" y="-48" width="22" height="30" rx="8" fill="${C.orange}" ${st()}/></g><path d="M-40 -30 Q-40 -56 0 -56 Q40 -56 40 -30" fill="none" ${st(C.navy,9)}/><rect x="-110" y="-30" width="220" height="110" rx="14" fill="${C.red}" ${st()}/><rect x="-110" y="-30" width="220" height="30" rx="14" fill="#E8665F" ${st()}/><rect x="-110" y="-12" width="220" height="12" fill="#E8665F"/><path d="M-110 0 H110" ${st(C.navy,4)} fill="none"/><rect x="-24" y="-8" width="48" height="24" rx="6" fill="${C.gold}" ${st(C.navy,4)}/><path d="M-90 10 V70" stroke="#fff" stroke-width="6" opacity=".3" stroke-linecap="round"/><ellipse cx="0" cy="88" rx="116" ry="9" fill="#000" opacity=".15"/></g>`;

/* months passing: one, two, six (o.nums) */
P.e111_months=(o,T,k)=>{const nums=o.nums||[1,2,6];let s='';const n=nums.length,gap=n===3?96:130;
  nums.forEach((m,i)=>{const p=ease((k-.1-i*.4)/.3),x=(i-(n-1)/2)*gap;s+=`<g opacity="${f(p)}" transform="translate(${x},${f((1-p)*24)})"><rect x="-42" y="-70" width="84" height="130" rx="12" fill="${C.white}" ${st()}/><path d="M-42 -42 V-58 Q-42 -70 -30 -70 H30 Q42 -70 42 -58 V-42Z" fill="${C.red}" ${st()}/><text x="0" y="22" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="62" fill="${C.navy}">${m}</text><text x="0" y="46" text-anchor="middle" font-family="Fraunces" font-weight="700" font-size="17" fill="${C.navy2}">${m>1?'months':'month'}</text></g>`});
  return `<g><g transform="translate(0,6)">${s}</g></g>`};

/* fridge with a note on it */
