/* patterns made of many small coloured stones; o.kind: floor | star | tree | circle */
P.e112_mosaic=(o,T)=>{const kind=o.kind||'floor',cols=['#C8553D','#E0B34F','#4D7BA8','#5E8F5A','#F4E5C2','#8E6BB5'];
  const tile=(x,y,c,r)=>`<rect x="${f(x-6)}" y="${f(y-6)}" width="12" height="12" rx="3" fill="${c}" ${st(C.navy,1.8)} transform="rotate(${r||0} ${f(x)} ${f(y)})"/>`;
  let s='';
  if(kind==='star'){const pts=[];for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,r=i%2?38:92;pts.push([Math.cos(a)*r,Math.sin(a)*r])}const inside=(x,y)=>{let c=false;for(let i=0,j=9;i<10;j=i++){const[xi,yi]=pts[i],[xj,yj]=pts[j];if((yi>y)!==(yj>y)&&x<(xj-xi)*(y-yi)/(yj-yi)+xi)c=!c}return c};let n=0;for(let gy=-84;gy<=92;gy+=14)for(let gx=-84;gx<=84;gx+=14)if(inside(gx,gy+4)){n++;s+=tile(gx,gy+4,(Math.abs(gx)+Math.abs(gy))<14?'#C8553D':(n%2?'#E0B34F':'#F4E5C2'),0)}}
  else if(kind==='tree'){for(let r=0;r<4;r++)for(let c=-r;c<=r;c++)s+=tile(c*14,-60+r*20,cols[3],0);for(let r=0;r<3;r++)for(let c=-(r+1);c<=r+1;c++)s+=tile(c*14,6+r*18,cols[3],0);for(let r=0;r<4;r++)s+=tile(0,40+r*14,'#8A5A33',0)}
  else if(kind==='circle'){for(let i=0;i<16;i++){const a=i*Math.PI/8;s+=tile(Math.cos(a)*70,Math.sin(a)*70,cols[i%cols.length],i*22)}for(let i=0;i<10;i++){const a=i*Math.PI/5;s+=tile(Math.cos(a)*36,Math.sin(a)*36,cols[(i+2)%cols.length],i*36)}s+=tile(0,0,'#E0B34F')}
  else{for(let r=0;r<7;r++)for(let c=0;c<10;c++){const x=-117+c*26,y=-80+r*26,m=(r+c)%2,q=(r*3+c*5)%6;s+=tile(x,y,m?cols[q]:cols[4],0);if(!m)s+=`<circle cx="${x}" cy="${y}" r="3" fill="${cols[(q+3)%6]}"/>`}}
  const bg=kind==='floor'?`<rect x="-130" y="-94" width="260" height="188" rx="8" fill="#E8DCC4" ${st()}/>`:`<circle r="${kind==='tree'?0:92}" fill="#E8DCC4" ${st()}/>${kind==='tree'?`<rect x="-80" y="-92" width="160" height="184" rx="12" fill="#E8DCC4" ${st()}/>`:''}`;
  return `<g>${bg}${s}</g>`};
