  cs.forEach((c,i)=>{const x=-78+i*78,sw=Math.sin(T*1.6+i)*1.5;g+=`<g transform="translate(${x},-62) rotate(${f(sw)})"><circle cx="0" cy="-4" r="9" fill="${C.gold}" ${st(C.navy,3)}/><path d="M-32 -2 H32 V102 Q0 112 -32 102Z" fill="${c}" ${st()}/><rect x="-32" y="22" width="64" height="9" fill="#fff" opacity=".8"/><rect x="-32" y="38" width="64" height="4" fill="#fff" opacity=".5"/><path d="M-22 4 V90" stroke="#fff" stroke-width="5" stroke-linecap="round" opacity=".28"/></g>`});
