const _e113iPlate=(id,c1,c2,T,ring)=>`<defs><radialGradient id="${id}" cx="50%" cy="40%" r="65%"><stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></radialGradient></defs><circle r="136" fill="${c1}" opacity="${f(.10+.04*Math.sin(T*1.5))}"/><circle r="126" fill="url(#${id})"/><circle r="126" fill="none" stroke="${ring}" stroke-width="3" opacity=".7"/><circle r="136" fill="none" stroke="${ring}" stroke-width="2" stroke-dasharray="3 11" opacity=".55" transform="rotate(${f(T*8)})"/>`;
