P.e119_ideapile=(o,T,k)=>{let s='';const cr=[[-84,36,22],[-40,48,20],[8,34,24],[56,50,20],[-62,-4,20],[-14,0,22],[38,-2,22],[84,22,18],[-30,-36,18],[22,-38,18]];cr.forEach(([x,y,r],i)=>{const p=ease((k-i*.06)/.3);s+=`<g transform="translate(${x},${y}) scale(${f(p)}) rotate(${i*37})"><path d="M${-r} 0 L${-r*.5} ${-r*.9} L${r*.4} ${-r} L${r} ${-r*.2} L${r*.8} ${r*.7} L${-r*.2} ${r} Z" fill="#fff" ${st(C.navy,3.5)}/><path d="M${-r*.4} ${-r*.2} L${r*.3} ${r*.3} M${-r*.2} ${r*.4} L${r*.5} ${-r*.4}" ${st('#CBD3D8',2.5)}/></g>`});
  return `<g>${_e119sh(0,86,110)}${s}<g transform="translate(0,-92) scale(.55)">${P.bulb({},T)}</g></g>`};

