P.e119_journalist=(o,T)=>{const w=Math.sin(T*3)*3;const over=`<g transform="translate(-60,48) rotate(-10)"><rect x="-26" y="-34" width="52" height="68" rx="5" fill="#FFF3C4" ${st()}/><path d="M-16 -18 H16 M-16 -4 H16 M-16 10 H8" ${st('#B79B45',3)}/></g><g transform="translate(${f(58+w)},44) rotate(14)"><rect x="-17" y="-32" width="34" height="62" rx="7" fill="#2B3D48" ${st(C.navy,4)}/><rect x="-12" y="-26" width="24" height="40" rx="3" fill="#BFE3F2"/></g>`;
  return `<g>${_e119sh(0,110,58)}<g>${P.person({c:'#4F7A5A',hair:'long',hc:'#2A1D18'},T)}${over}</g></g>`};
P.e119_paper=(o,T,k)=>{const ch=o.cheese;return `<g>${_e119sh(0,110,100)}<g transform="rotate(${f(-4+Math.sin(T*1.6)*1.4)})"><rect x="-96" y="-102" width="192" height="204" rx="6" fill="#F4EFE0" ${st()}/><rect x="-80" y="-88" width="160" height="32" rx="3" fill="${C.navy}"/><path d="M-62 -70 H62" ${st(C.cream,6)}/>${ch?`<rect x="-80" y="-44" width="100" height="70" fill="#FFE9A8" ${st(C.navy,3)}/><g transform="translate(-30,-8) scale(.46)">${P.e119_cheese({},T)}</g>`:`<rect x="-80" y="-44" width="100" height="70" fill="#BFE3F2" ${st(C.navy,3)}/>`}<path d="M32 -40 H80 M32 -26 H80 M32 -12 H80 M32 2 H70 M-80 40 H80 M-80 56 H80 M-80 72 H50 M-80 88 H66" ${st('#9AA7B0',4)}/></g></g>`};
