P.e119_oil=(o,T)=>{const r=Math.sin(T*2)*10;return `<g>${_e119sh(0,100,120)}<path d="M-40 100 L-10 -20 L20 100" fill="none" ${st(C.navy,8)}/><path d="M-30 60 H10 M-22 24 H2" ${st(C.navy,5)}/><g transform="translate(-10,-40) rotate(${f(r)})"><rect x="-80" y="-12" width="150" height="24" rx="12" fill="${C.red}" ${st()}/><circle cx="-80" cy="0" r="16" fill="#9AA7B0" ${st()}/><rect x="60" y="0" width="12" height="60" fill="${C.navy2}" ${st(C.navy,3)}/></g><g transform="translate(78,50)"><path d="M-30 -48 H30 V48 H-30Z" fill="#2B3D48" ${st()}/><path d="M-30 -20 H30 M-30 20 H30" ${st('#6B7C87',4)}/><path d="M0 -8 Q-12 8 0 22 Q12 8 0 -8Z" fill="${C.gold}" opacity=".9"/></g></g>`};
