P.e119_mic=(o,T)=>{let w='';for(let i=0;i<3;i++){const ph=(T*1.2+i/3)%1;w+=`<path d="M${f(52+ph*30)} ${f(-60)} a${f(20+ph*24)} ${f(20+ph*24)} 0 0 1 0 ${f(64+ph*20)}" fill="none" ${st(C.goldD,5)} opacity="${f(1-ph)}"/>`}
  return `<g>${_e119sh(0,110,60)}${w}<rect x="-30" y="-100" width="60" height="100" rx="30" fill="#6B7C87" ${st()}/><path d="M-30 -70 H30 M-30 -50 H30 M-30 -30 H30" ${st('#C0C7CC',4)}/><path d="M-48 -30 Q-48 22 0 22 Q48 22 48 -30" fill="none" ${st(C.navy,8)}/><path d="M0 22 V80 M-34 90 H34" ${st(C.navy,9)}/></g>`};
P.e119_scales=(o,T)=>{const tilt=Math.sin(T*1.6)*3;return `<g>${_e119sh(0,110,60)}<rect x="-6" y="-100" width="12" height="190" fill="${C.goldD}" ${st()}/><rect x="-46" y="86" width="92" height="16" rx="6" fill="${C.goldD}" ${st()}/><g transform="rotate(${f(tilt)} 0 -92)"><path d="M-90 -92 H90" ${st(C.goldD,9)}/><g transform="translate(-90,-92)"><path d="M0 0 L-34 60 M0 0 L34 60" ${st(C.navy,3)}/><path d="M-44 60 H44 Q40 84 0 84 Q-40 84 -44 60Z" fill="${C.gold}" ${st()}/></g><g transform="translate(90,-92)"><path d="M0 0 L-34 60 M0 0 L34 60" ${st(C.navy,3)}/><path d="M-44 60 H44 Q40 84 0 84 Q-40 84 -44 60Z" fill="${C.gold}" ${st()}/></g></g><circle cx="0" cy="-100" r="12" fill="${C.gold}" ${st()}/></g>`};
P.e119_lawbook=(o,T)=>`<g>${_e119sh(0,96,90)}${_e119book(0,40,170,56,'#5B3E6B',0)}${_e119book(0,-14,150,50,C.red,0)}<g transform="translate(0,-74) scale(.5)">${P.e119_scales({},T)}</g></g>`;
P.e119_argue=(o,T)=>`<g><g transform="translate(-100,40) scale(.8)">${P.person({c:'#4DA3D8',hair:'short',hc:'#222'},T)}</g><g transform="translate(100,40) scale(.8)">${P.person({c:'#D96C8B',hair:'long',hc:'#3A2A22'},T)}</g><g transform="translate(-88,-66) scale(.42)">${P.bubble({side:'R',text:'!',fs:84,w:100,ty:26},T)}</g><g transform="translate(88,-66) scale(.42)">${P.bubble({side:'L',text:'!',fs:84,w:100,ty:26},T)}</g></g>`;
P.e119_ask=(o,T)=>`<g><g transform="translate(-86,40) scale(.82)">${P.person({c:'#4F7A5A',hair:'long',hc:'#2A1D18'},T)}</g><g transform="translate(110,40) scale(.7)">${P.person({c:'#B07AA1',hair:'bun',hc:'#D5D8DB'},T)}</g><g transform="translate(-4,-70) scale(.5)">${P.q({},T)}</g><g transform="translate(110,-62) scale(.5)">${P.bubble({side:'L',text:'...',fs:60,w:90,ty:22},T)}</g></g>`;
P.e119_copies=(o,T)=>{let s='';for(let i=0;i<5;i++)s+=`<g transform="translate(${-70+i*34},${40-i*6}) rotate(${-6+i*3})"><rect x="-44" y="-70" width="88" height="116" rx="4" fill="#F4EFE0" ${st()}/><rect x="-36" y="-62" width="72" height="16" fill="${C.navy}"/><path d="M-34 -30 H34 M-34 -14 H34 M-34 2 H20" ${st('#9AA7B0',3)}/></g>`;
  return `<g>${_e119sh(0,96,110)}${s}${_e119pill('10',0,-96,84,34)}</g>`};
P.e119_wallnews=(o,T,k)=>{return `<g>${_e119sh(0,100,120)}<rect x="-130" y="-110" width="260" height="210" rx="10" fill="#E8D7B0" ${st()}/><path d="M-130 -20 H130" ${st('#CDBF9B',6)}/><g transform="rotate(-3)"><rect x="-62" y="-84" width="124" height="160" rx="4" fill="#fff" ${st()}/><rect x="-52" y="-74" width="104" height="22" fill="${C.navy}"/><path d="M-50 -36 H50 M-50 -20 H50 M-50 -4 H30 M-50 18 H50 M-50 34 H50 M-50 50 H40" ${st('#9AA7B0',4)}/><circle cx="0" cy="-86" r="9" fill="${C.red}" ${st(C.navy,3)}/></g></g>`};
P.e119_ball=(o,T)=>{const r=T*80;return `<g>${_e119sh(0,86,70)}<g transform="rotate(${f(r)})"><circle r="68" fill="#fff" ${st()}/><path d="M0 -26 L25 -8 L15 22 H-15 L-25 -8Z" fill="${C.navy2}"/><path d="M0 -26 V-68 M25 -8 L64 -22 M15 22 L40 54 M-15 22 L-40 54 M-25 -8 L-64 -22" ${st(C.navy,4)}/></g></g>`};
P.e119_tray=(o,T)=>`<g>${_e119sh(0,92,100)}<rect x="-100" y="-56" width="200" height="130" rx="16" fill="#9AA7B0" ${st()}/><rect x="-88" y="-44" width="176" height="106" rx="10" fill="#B9C6CE" ${st(C.navy,3)}/><circle cx="-34" cy="8" r="38" fill="#fff" ${st()}/><path d="M-52 4 q10 -14 20 0 t20 0" fill="none" ${st('#9A7B4F',6)}/><rect x="28" y="-30" width="48" height="36" rx="6" fill="#8EBE7E" ${st()}/><rect x="28" y="12" width="48" height="36" rx="6" fill="#E2A92B" ${st()}/></g>`;
P.e119_teachercar=(o,T)=>`<g><g transform="translate(-86,34) scale(.78)">${P.person({c:'#8E6BB5',hair:'bun',hc:'#2A1D18'},T)}</g><g transform="translate(86,26) scale(.85)">${P.car({},T)}</g></g>`;

/* ---------- author / secretary ---------- */
P.e119_childbook=(o,T)=>`<g>${_e119sh(0,104,76)}<g transform="rotate(${f(-4+Math.sin(T*2)*2)})"><rect x="-70" y="-100" width="140" height="196" rx="8" fill="${C.blue}" ${st()}/><rect x="-70" y="-100" width="16" height="196" fill="#000" opacity=".16"/><circle cx="8" cy="-42" r="28" fill="${C.gold}" ${st()}/><path d="M-30 20 Q-6 -10 20 20 Q44 -10 54 20 V62 H-30Z" fill="${C.leaf}" ${st()}/><rect x="-30" y="62" width="84" height="12" rx="3" fill="${C.cream}" ${st(C.navy,3)}/><path d="M-26 -82 H50" ${st(C.cream,6)}/></g></g>`;
P.e119_author=(o,T)=>{const w=Math.sin(T*3)*2;const over=`<g transform="translate(-60,46) rotate(-10) scale(.5)">${_e119book(0,0,80,110,C.blue,0,1).replace(/<g transform="translate\(0,0\) rotate\(0\)">/,'<g>')}</g><g transform="translate(${f(60+w)},40) rotate(34)"><rect x="-5" y="-54" width="10" height="64" rx="4" fill="${C.navy2}" ${st()}/><path d="M-5 10 L0 26 L5 10Z" fill="#F4D8B0" ${st(C.navy,3)}/></g>`;
  return `<g>${_e119sh(0,110,58)}<g>${P.person({c:'#B07AA1',hair:'bun',hc:'#D5D8DB'},T)}${over}</g></g>`};
P.e119_phonemail=(o,T,k)=>{let w='';for(let i=0;i<3;i++){const ph=(T*2+i/3)%1;w+=`<path d="M${f(-104-ph*18)} ${-40} q-10 20 0 40" fill="none" ${st(C.red,5)} opacity="${f(1-ph)}"/>`}
  return `<g>${w}<g transform="translate(-66,6) scale(.7)">${P.e119_deskphone({},T)}</g><g transform="translate(72,0) scale(.62)">${P.msg({},T,3)}</g></g>`};
P.e119_deskphone=(o,T)=>{let b='';for(let r=0;r<3;r++)for(let c=0;c<3;c++)b+=`<rect x="${-34+c*26}" y="${6+r*18}" width="20" height="13" rx="4" fill="#fff" ${st(C.navy,2.5)}/>`;
  return `<g>${_e119sh(0,84,98)}<path d="M-100 -34 Q-100 -62 -66 -62 H66 Q100 -62 100 -34 V-24 Q100 -12 84 -12 H44 Q32 -12 32 -22 H-32 Q-32 -12 -44 -12 H-84 Q-100 -12 -100 -24Z" fill="#4A5A64" ${st()}/><path d="M-70 -8 H70 L92 76 Q94 84 86 84 H-86 Q-94 84 -92 76Z" fill="#5B6D79" ${st()}/><rect x="-46" y="-4" width="92" height="64" rx="8" fill="#3C4F5C" ${st(C.navy,3)}/>${b}</g>`};
P.e119_ten=(o,T,k)=>{let s='';for(let i=0;i<10;i++){const x=-108+(i%5)*54,y=-44+Math.floor(i/5)*104,last=i===9;const p=ease((k-i*.12)/.3);
  s+=`<g transform="translate(${x},${y}) scale(${f(.001+p)})"><rect x="-20" y="-36" width="40" height="64" rx="3" fill="#B9C6CE" ${st(C.navy,3.5)}/>${[0,1,2].map(r=>`<rect x="-12" y="${-28+r*16}" width="9" height="9" fill="#FFE08A"/><rect x="3" y="${-28+r*16}" width="9" height="9" fill="#FFE08A"/>`).join('')}<circle cx="14" cy="-34" r="${last?15:13}" fill="${last?C.moss:C.red}" ${st(C.navy,3)}/>${last?`<path d="M7 -34 L12 -28 L22 -42" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>`:`<path d="M8 -40 L20 -28 M20 -40 L8 -28" ${st('#fff',4)}/>`}</g>`}
  return `<g>${s}</g>`};
P.e119_sixmonths=(o,T)=>`<g><g transform="translate(-86,0) scale(.82)">${P.door({},T)}</g><g transform="translate(96,0) scale(.82)">${P.e119_numcard({n:6,u:'months'},T)}</g></g>`;
P.e119_numcard=(o,T)=>`<g>${_e119sh(0,96,86)}<rect x="-100" y="-90" width="200" height="180" rx="26" fill="${C.cream}" ${st()}/><rect x="-100" y="-90" width="200" height="40" rx="26" fill="${C.red}" ${st()}/><rect x="-100" y="-66" width="200" height="16" fill="${C.red}"/>${_e119tx(o.n,0,38,(String(o.n).length>3?64:String(o.n).length>2?84:110),C.navy)}${_e119tx(o.u||'',0,72,34,C.goldD)}<circle cx="-56" cy="-92" r="7" fill="${C.navy}"/><circle cx="56" cy="-92" r="7" fill="${C.navy}"/></g>`;
P.e119_evening=(o,T)=>`<g><g transform="translate(-92,-42) scale(.7)">${P.moon({},T)}</g><g transform="translate(60,10) scale(.72)">${P.e119_training({},T)}</g></g>`;

/* ---------- conference / targets ---------- */
P.e119_stage=(o,T,k)=>{let aud='';for(let r=0;r<2;r++)for(let c=0;c<6;c++){const x=-120+c*48+(r?24:0),y=76+r*22;aud+=`<g transform="translate(${x},${y}) scale(.26)">${P.person({c:[C.red,C.blue,C.moss,C.orange,'#8E6BB5',C.gold2][(c+r*2)%6],hair:['short','long','bun'][(c+r)%3],hc:'#2A1D18'},T)}</g>`}
  return `<g>${_e119sh(0,106,140)}<rect x="-140" y="-104" width="280" height="150" rx="10" fill="#2B3D48" ${st()}/><rect x="-124" y="-90" width="248" height="112" rx="6" fill="#fff"/><g transform="translate(-52,-34) scale(.45)">${_e119target(60,0)}</g><path d="M10 -64 H100 M10 -44 H100 M10 -24 H72" ${st('#9AA7B0',5)}/><rect x="-140" y="46" width="280" height="14" fill="${C.brown}" ${st()}/><g transform="translate(60,22) scale(.52)">${P.person({c:'#3B4A6B',hair:'long',hc:'#2A1D18'},T)}<rect x="-40" y="44" width="80" height="64" rx="6" fill="${C.brown}" ${st()}/></g>${aud}</g>`};
P.e119_hall=(o,T)=>{let s='';for(let r=0;r<3;r++)for(let c=0;c<7;c++){s+=`<g transform="translate(${-132+c*44+(r%2?22:0)},${-30+r*40}) scale(.3)">${P.person({c:[C.red,C.blue,C.moss,C.orange,'#8E6BB5',C.gold2][(c+r)%6],hair:['short','long','bun'][(c*2+r)%3],hc:'#2A1D18'},T)}</g>`}
  return `<g>${_e119sh(0,96,140)}<rect x="-150" y="-110" width="300" height="210" rx="14" fill="#E3DACB" ${st()}/>${s}</g>`};
P.e119_target=(o,T,k)=>{const arrow=o.arrow;return `<g>${_e119sh(0,100,90)}<g transform="scale(${f(1+.03*Math.sin(T*3))})">${_e119target(92,arrow)}</g></g>`};
P.e119_dream=(o,T)=>`<g>${[[-40,100,10],[-70,80,15]].map(([x,y,r])=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#fff" ${st()}/>`).join('')}<g transform="translate(0,-4) scale(1.7)">${cloudShape('#fff')}</g><g transform="translate(0,-8)"><path d="M0 -40 L11 -12 L42 -10 L18 10 L26 40 L0 24 L-26 40 L-18 10 L-42 -10 L-11 -12Z" fill="${C.gold}" ${st(C.navy,4)} transform="rotate(${f(Math.sin(T*2)*6)})"/></g></g>`;
P.e119_nopl=(o,T,k)=>`<g><g transform="translate(-92,-4) scale(.8)">${P.e119_target({},T)}</g><g transform="translate(112,0) scale(.8)">${P.e119_dream({},T)}</g></g>`;
P.e119_planlist=(o,T,k)=>{let r='';for(let i=0;i<4;i++){const p=ease((k-.3-i*.3)/.3);r+=`<rect x="-62" y="${-62+i*40}" width="26" height="26" rx="6" fill="#fff" ${st(C.navy,4)}/><path d="M-22 ${-49+i*40} H${[56,40,52,30][i]}" ${st('#B79B45',5)}/><path d="M-57 ${-48+i*40} l7 8 l14 -17" fill="none" ${st(C.moss,6)} opacity="${f(p)}"/>`}
  return `<g>${_e119sh(0,104,80)}<rect x="-86" y="-108" width="172" height="208" rx="14" fill="#FFF3C4" ${st()}/><rect x="-86" y="-108" width="172" height="26" rx="14" fill="${C.red}" ${st()}/><g transform="translate(6,6)">${r}</g></g>`};
P.e119_targetplan=(o,T,k)=>`<g><g transform="translate(-96,0) scale(.85)">${P.e119_target({arrow:1},T,k)}</g><g transform="translate(110,0) scale(.82)">${P.e119_planlist({},T,k)}</g></g>`;
P.e119_smalltargets=(o,T,k)=>{let s='';for(let i=0;i<12;i++){const x=-120+(i%4)*80,y=-64+Math.floor(i/4)*84,p=ease((k-.3-i*.07)/.3);s+=`<g transform="translate(${x},${y}) scale(${f(.001+p*.4)})">${_e119target(80,0)}</g>`}
  return `<g><g transform="translate(0,-110) scale(.34)">${_e119target(100,1)}</g><g transform="translate(0,30)">${s}</g></g>`};
P.e119_month=(o,T,k)=>`<g>${P.calendar({label:o.label||'MONTH',marks:[]},T,k)}</g>`;
P.e119_researcher=(o,T)=>{const over=`<path d="M-62 108 L-62 36 Q-62 -4 0 -4 Q62 -4 62 36 L62 108Z" fill="#fff" ${st()}/><path d="M-14 -4 L0 40 L14 -4Z" fill="${C.cream}" ${st(C.navy,4)}/><rect x="-11" y="-20" width="22" height="22" fill="${_e119SK}" ${st(C.navy,4)}/>`;
  return `<g>${_e119sh(0,110,58)}<g>${P.person({c:'#fff',hair:'short',hc:'#3A2A22'},T)}${over}<g transform="translate(60,36)"><rect x="-28" y="-34" width="56" height="70" rx="5" fill="${C.brown}" ${st()}/><rect x="-22" y="-26" width="44" height="58" fill="#fff"/><path d="M-14 -10 q8 -8 14 0 t14 -10 M-14 6 H14 M-14 18 H8" fill="none" ${st(C.blue,3.5)}/><rect x="-10" y="-40" width="20" height="10" rx="3" fill="#9AA7B0" ${st(C.navy,3)}/></g></g></g>`};
P.e119_study=(o,T,k)=>{let s='';const n=o.dots||80;for(let i=0;i<n;i++){const x=-110+(i%16)*14.6,y=-60+Math.floor(i/16)*20;s+=`<circle cx="${f(x)}" cy="${y}" r="5.5" fill="${[C.blue,C.orange,C.moss,C.red][i%4]}" ${st(C.navy,1.8)} opacity="${f(ease((k-i*.01)/.3))}"/>`}
  return `<g>${_e119sh(0,100,130)}<rect x="-132" y="-88" width="264" height="150" rx="14" fill="#fff" ${st()}/>${s}${_e119pill(o.n||'5000',0,92,150,34)}</g>`};
P.e119_balance=(o,T)=>{const heavy=o.heavy||'purpose',tilt=(heavy==='purpose'?8:-8);return `<g>${_e119sh(0,110,60)}<rect x="-6" y="-100" width="12" height="190" fill="${C.goldD}" ${st()}/><rect x="-46" y="86" width="92" height="16" rx="6" fill="${C.goldD}" ${st()}/><g transform="rotate(${f(tilt)} 0 -92)"><path d="M-100 -92 H100" ${st(C.goldD,9)}/><g transform="translate(-100,-92)"><path d="M0 0 L-34 60 M0 0 L34 60" ${st(C.navy,3)}/><path d="M-44 60 H44 Q40 84 0 84 Q-40 84 -44 60Z" fill="${C.gold}" ${st()}/><g transform="translate(0,46) scale(.4)">${P.coins({},T)}</g></g><g transform="translate(100,-92)"><path d="M0 0 L-34 60 M0 0 L34 60" ${st(C.navy,3)}/><path d="M-44 60 H44 Q40 84 0 84 Q-40 84 -44 60Z" fill="${C.gold}" ${st()}/><g transform="translate(0,38) scale(.42)"><circle r="72" fill="#fff" ${st()}/><circle r="54" fill="${C.red}" ${st(C.navy,3)}/><circle r="36" fill="#fff" ${st(C.navy,3)}/><circle r="18" fill="${C.red}" ${st(C.navy,3)}/></g></g></g><circle cx="0" cy="-100" r="12" fill="${C.gold}" ${st()}/></g>`};
P.e119_meds=(o,T)=>`<g>${_e119sh(0,84,76)}<rect x="-40" y="-70" width="80" height="140" rx="14" fill="${C.orange}" ${st()}/><rect x="-30" y="-92" width="60" height="26" rx="6" fill="#fff" ${st()}/><rect x="-40" y="-20" width="80" height="50" fill="#fff" opacity=".9"/><path d="M-10 -12 h20 v12 h12 v20 h-12 v12 h-20 v-12 h-12 v-20 h12Z" fill="${C.moss}"/></g>`;
P.e119_medkids=(o,T)=>`<g><g transform="translate(-100,10) scale(.8)">${P.e119_meds({},T)}</g><g transform="translate(86,40) scale(.8)">${P.person({c:C.orange,hair:'short',hc:'#3A2A22'},T)}</g></g>`;
P.e119_cardboard=(o,T)=>`<g>${_e119sh(0,92,100)}<path d="M-92 -20 L-60 -52 H60 L92 -20 V76 Q92 84 84 84 H-84 Q-92 84 -92 76Z" fill="#C8A06B" ${st()}/><path d="M-92 -20 H92" ${st(C.navy,4)}/><rect x="-26" y="-20" width="52" height="22" fill="#E7D3A6" ${st(C.navy,3)}/></g>`;
P.e119_handshake=(o,T)=>{const sh=Math.sin(T*6)*3;return `<g>${_e119sh(0,80,110)}<g transform="translate(0,${f(sh)})"><path d="M-130 -28 H-64 L-12 -40 Q10 -46 28 -32 L64 -4 H130 V54 H64 L30 62 Q8 66 -12 50 L-60 20 H-130Z" fill="#fff" opacity="0"/><path d="M-132 -34 H-70 V46 H-132Z" fill="#3B4A6B" ${st()}/><path d="M132 -34 H70 V46 H132Z" fill="#8E3B5B" ${st()}/><path d="M-70 -26 L-20 -38 Q4 -42 22 -28 L70 10 L50 48 L-20 40 L-70 36Z" fill="${_e119SK}" ${st()}/><path d="M20 -2 q20 8 24 26 M0 4 q18 8 22 24 M-18 8 q16 6 20 20" fill="none" ${st('#C99468',3.5)}/><path d="M-70 -10 L-40 -26" fill="none"/></g></g>`};
P.e119_deal=(o,T,k)=>`<g><g transform="translate(0,-34) scale(.78)">${P.e119_handshake({},T)}</g><g transform="translate(0,84) scale(.4)">${_e119sheetdoc()}</g></g>`;
const _e119sheetdoc=()=>`<rect x="-120" y="-66" width="240" height="132" rx="6" fill="#fff" ${st()}/><path d="M-96 -36 H96 M-96 -14 H96 M-96 8 H40" ${st('#9AA7B0',6)}/><path d="M20 40 q14 -24 28 0 t28 0" fill="none" ${st(C.blue,6)}/>`;
P.e119_trem=(o,T)=>{const sh=Math.sin(T*40)*3;return `<g>${_e119sh(0,100,80)}<g transform="translate(${f(sh)},0)"><path d="M-70 -30 Q-86 -4 -64 18 Q-50 40 -20 36 L30 30 Q60 24 60 -4 Q58 -36 20 -40 Z" fill="${_e119SK}" ${st()}/><path d="M-60 -20 q-14 -4 -22 8 M-62 2 q-14 0 -20 12" fill="none" ${st('#C99468',4)}/></g><path d="M-96 -52 q-12 -10 -4 -26 M-82 -66 q-6 -14 6 -22 M94 -30 q12 -6 18 4 M92 -8 q12 -2 14 10" fill="none" ${st(C.goldD,5)}/><g transform="translate(70,-30) scale(.7)"><path d="M-50 -20 Q-60 20 -30 30 L40 20 Q60 0 40 -26Z" fill="${_e119SK}" ${st()}/></g></g>`};
P.e119_venn=(o,T,k)=>{const n=o.n||3;const c=[[-46,-40,C.blue],[46,-40,C.red],[0,40,C.gold]];let s='';c.forEach(([x,y,col],i)=>{if(i>=n)return;const p=ease((k-i*.25)/.4);s+=`<circle cx="${x}" cy="${y}" r="${f(74*p)}" fill="${col}" fill-opacity=".55" ${st()}/>`});
  const ic=[`<path d="M0 -26 L8 -8 L28 -6 L12 8 L18 28 L0 18 L-18 28 L-12 8 L-28 -6 L-8 -8Z" fill="#fff" ${st(C.navy,3)}/>`,`<path d="M0 22 C-40 -6 -22 -40 0 -18 C22 -40 40 -6 0 22Z" fill="#fff" ${st(C.navy,3)}/>`,`<g transform="scale(.3)">${_e119target(70,0)}</g>`];
  let i2='';[[-70,-56],[70,-56],[0,62]].forEach(([x,y],i)=>{if(i<n&&k>.4+i*.25)i2+=`<g transform="translate(${x},${y})">${ic[i]}</g>`});
  return `<g>${s}${i2}</g>`};
P.e119_goodpeople=(o,T)=>`<g><g transform="translate(-100,36) scale(.7)">${P.person({c:'#8E6BB5',hair:'long',hc:'#2A1D18'},T)}</g><g transform="translate(0,36) scale(.7)">${P.person({c:'#4F7A5A',hair:'short',hc:'#222'},T)}</g><g transform="translate(100,36) scale(.7)">${P.person({c:'#F2994A',hair:'bun',hc:'#2A1D18'},T)}</g><g transform="translate(0,-74) scale(.7)">${P.heart({},T)}</g></g>`;
