    s+=`<path d="${d} L${W/2+10} ${H/2} L${-W/2-10} ${H/2}Z" fill="#4DA3D8" ${st(C.navy,3)}/>`;for(let i=0;i<3;i++)s+=`<path d="M${f(((i*110+30-o*2.5)%(W+40))-W/2)} ${by+72+i*6} h26" ${st('#fff',3)}/>`;
