/* speed screen above the doors */
P.e120_speed=(o,T)=>{const n=o.n==null?250:o.n,col=n>=200?C.red:n>=100?C.orange:'#5FD08A';
  return `<g><rect x="-112" y="-68" width="224" height="136" rx="16" fill="#101A24" ${st()}/><rect x="-100" y="-56" width="200" height="112" rx="10" fill="#0B141D" ${st('#3A5368',3)}/><text x="0" y="14" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="${String(n).length>2?78:90}" fill="${col}">${n}</text><text x="0" y="46" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="26" fill="#9FD3F0" letter-spacing="2">km/h</text><circle cx="-88" cy="-44" r="${f(3.4+Math.sin(T*6)*1)}" fill="${col}"/></g>`};
/* big station: lots of trains, a hanging board, unreadable (foreign) signs */
P.e120_station=(o,T)=>{let tr='';const many=o.many;
  const rows=many?[-44,10,64]:[22];
  rows.forEach((y,r)=>{const xs=many?[-64,66]:[0];xs.forEach((x,i)=>{tr+=`<g transform="translate(${x+(r%2)*18},${y}) scale(${many?.27:.5})">${_e120trainOnly(T,{c:['#F4F2EA','#E8D4A8','#CFE4F2'][(r+i)%3],stripe:[C.blue,C.red,C.moss][(r+i)%3],slow:1})}</g>`});tr+=`<rect x="-126" y="${y+14}" width="252" height="5" fill="${C.navy2}"/>`});
  return `<g><path d="M-130 -84 Q0 -150 130 -84 V-66 H-130Z" fill="#9FB0BA" ${st()}/><path d="M-110 -92 V-66 M-60 -110 V-66 M0 -116 V-66 M60 -110 V-66 M110 -92 V-66" fill="none" ${st(C.navy2,4)}/><rect x="-130" y="-66" width="260" height="150" fill="#E8EEF1" ${st()}/><rect x="-130" y="84" width="260" height="14" fill="#6B7C86" ${st()}/>${tr}<g transform="translate(0,${many?-84:-48})"><rect x="-70" y="-13" width="140" height="30" rx="8" fill="#101A24" ${st(C.navy,4)}/><g fill="#F6CE4B">${[0,1,2,3,4].map(i=>`<rect x="${-58+i*24}" y="-6" width="16" height="6" rx="2" opacity="${f(.6+.4*Math.sin(T*3+i))}"/>`).join('')}</g><g fill="#9FD3F0">${[0,1,2,3,4].map(i=>`<rect x="${-58+i*24}" y="5" width="16" height="5" rx="2"/>`).join('')}</g></g></g>`};
/* departure board — rows of unreadable symbols, one row circled */
P.e120_board=(o,T)=>{let r='';const sym=['▲','●','■','◆','★','▼'];for(let i=0;i<5;i++){const y=-60+i*34,hl=o.hl===i;
    r+=`<rect x="-100" y="${y-14}" width="200" height="28" rx="6" fill="${hl?'#2B5B3E':'#16222C'}" ${hl?st(C.gold,3):''}/>`+[0,1,2,3].map(j=>`<text x="${-86+j*26}" y="${y+8}" font-family="Fraunces" font-weight="800" font-size="20" fill="#F6CE4B">${sym[(i*2+j)%6]}</text>`).join('')+`<rect x="22" y="${y-6}" width="${40+(i*17)%30}" height="6" rx="3" fill="#9FD3F0"/><text x="84" y="${y+8}" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="20" fill="${o.num&&hl?C.gold:'#F6CE4B'}">${[3,7,5,9,2][i]}</text>`}
  return `<g><rect x="-114" y="-98" width="228" height="196" rx="14" fill="#0E1822" ${st()}/>${r}<rect x="-6" y="98" width="12" height="24" fill="#9FB0BA" ${st(C.navy,3)}/></g>`};
/* a sign in an unknown language: shapes only */
P.e120_foreign=(o,T)=>{const sym=['▲','●','■','◆','▼','★'];
  return `<g><rect x="-8" y="-20" width="16" height="130" fill="#9FB0BA" ${st()}/><rect x="-110" y="-110" width="220" height="104" rx="18" fill="#2F6B55" ${st()}/><rect x="-98" y="-98" width="196" height="80" rx="10" fill="none" stroke="#fff" stroke-width="3"/>${sym.map((s,i)=>`<text x="${-76+i*30}" y="-48" font-family="Fraunces" font-weight="800" font-size="30" fill="#fff" text-anchor="middle">${s}</text>`).join('')}<path d="M-72 -30 h54 M-8 -30 h50 M52 -30 h20" ${st('#fff',4)}/><g transform="translate(78,-84) scale(.3)">${o.q?P.q({},T):''}</g></g>`};
/* ticket with a train and a big platform/train number */
P.e120_ticket=(o,T)=>`<g transform="rotate(${f(-6+Math.sin(T*2)*1.5)})"><rect x="-104" y="-62" width="208" height="124" rx="14" fill="${C.cream}" ${st()}/><path d="M42 -62 V62" ${st(C.navy,3)} stroke-dasharray="6 7"/><rect x="-104" y="-62" width="208" height="30" rx="14" fill="${C.red}" ${st()}/><text x="-12" y="-40" text-anchor="middle" font-family="Fraunces" font-weight="800" font-size="22" fill="${C.cream}" letter-spacing="4">TICKET</text><g transform="translate(-52,12) scale(.2)">${_e120trainOnly(T,{slow:1})}</g>${o.num!=null?`<text x="72" y="30" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="64" fill="${C.navy}">${o.num}</text>`:''}${o.map?`<path d="M-86 24 q20 -34 44 -6 t44 -10" fill="none" ${st(C.red,4)} stroke-dasharray="3 7"/>`:''}</g>`;

/* ---------- people with a hat (faceless) ---------- */
const _e120hat=(k)=>({cap:`<path d="M-40 -60 Q-40 -106 0 -106 Q40 -106 40 -60 Q0 -72 -40 -60Z" fill="#1F3A5C" ${st()}/><path d="M-46 -62 Q-4 -54 46 -66 L46 -58 Q0 -48 -46 -54Z" fill="#14283F" ${st(C.navy,4)}/><circle cx="0" cy="-86" r="6" fill="${C.gold}" ${st(C.navy,2.5)}/>`,
  helmet:`<path d="M-44 -50 Q-48 -112 0 -112 Q48 -112 44 -50 L44 -44 Q0 -56 -44 -44Z" fill="#E5493F" ${st()}/><path d="M-30 -96 Q-12 -108 4 -106" fill="none" stroke="#fff" stroke-width="7" stroke-linecap="round" opacity=".6"/><rect x="-6" y="-112" width="12" height="62" fill="#fff" opacity=".35"/>`,
  crown:`<path d="M-30 -86 L-34 -122 L-16 -104 L0 -128 L16 -104 L34 -122 L30 -86Z" fill="${C.gold}" ${st()}/><circle cx="0" cy="-114" r="4.5" fill="${C.red}"/>`,
  hard:`<path d="M-42 -58 Q-44 -110 0 -110 Q44 -110 42 -58 Z" fill="#F6CE4B" ${st()}/><rect x="-48" y="-62" width="96" height="9" rx="4" fill="#E2B653" ${st()}/>`})[k]||'';
const _e120who=(o,T)=>{const p=P.person(o,T);return p.replace(/<\/g>$/,`${_e120hat(o.hat)}${o.extra||''}</g>`)};
P.e120_inspector=(o,T)=>`<g><g transform="translate(-34,6)">${_e120who({c:'#2F5D8A',hair:'short',hc:'#222',hat:'cap',ph:1},T).replace('<path d="M-40 -60','<path transform="translate(0,-9)" d="M-40 -60').replace('<path d="M-46 -62','<path transform="translate(0,-9)" d="M-46 -62').replace('<circle cx="0" cy="-86"','<circle transform="translate(0,-9)" cx="0" cy="-86"')}</g><g transform="translate(70,40) rotate(${f(-10+Math.sin(T*3)*5)})"><rect x="-34" y="-22" width="68" height="44" rx="6" fill="${C.cream}" ${st()}/><rect x="-34" y="-22" width="68" height="12" fill="${C.red}" ${st(C.navy,3)}/><path d="M-22 4 h30" ${st(C.navy,3)}/></g>${o.laugh?`<g transform="translate(-6,-92) scale(.52)">${P.bubble({side:'R',text:'HA HA!',fs:34,w:128},T)}</g>`:''}</g>`;
P.e120_ns=(o,T)=>{const w=o.wrong,pu=1+.06*Math.sin(T*5);
  return `<g><rect x="-112" y="-110" width="224" height="220" rx="16" fill="#EFE5C8" ${st()}/><path d="M-112 -72 Q-110 -110 -84 -110 H84 Q110 -110 112 -72Z" fill="#9FB5C2" ${st()}/><path d="M-90 -76 L-60 -108 L-30 -76Z M-30 -76 L10 -112 L50 -76Z M50 -76 L78 -104 L104 -76Z" fill="#8FA3B2" ${st(C.navy,3)}/><path d="M-60 -108 l8 10 l-8 4 l-8 -6Z M10 -112 l10 12 l-10 4 l-10 -4Z" fill="#fff"/><path d="M-112 62 H112 V94 Q112 110 96 110 H-96 Q-112 110 -112 94Z" fill="#4DA3D8" ${st()}/><path d="M-90 82 q10 -8 20 0 t20 0 t20 0 M30 94 q10 -8 20 0 t20 0" fill="none" ${st('#fff',3)}/><path d="M0 -70 V58" ${st(C.navy2,9)}/><path d="M0 -70 V58" ${st('#F4F2EA',4)} stroke-dasharray="10 8"/><g transform="translate(0,${w?20:-20})"><rect x="-22" y="-12" width="44" height="26" rx="8" fill="${w?C.red:C.moss}" ${st()}/><rect x="-14" y="-6" width="28" height="9" rx="3" fill="#CBE8F5"/></g><g transform="translate(-62,${w?34:-34}) scale(${f(pu)})" opacity="${w?.5:1}"><path d="M0 -26 L24 4 H8 V26 H-8 V4 H-24Z" fill="${C.moss}" ${st(C.navy,3.5)}/></g><g transform="translate(62,34) scale(${f(w?pu:1)})" opacity="${w?1:.5}"><path d="M0 26 L24 -4 H8 V-26 H-8 V-4 H-24Z" fill="${C.red}" ${st(C.navy,3.5)}/></g><text x="-62" y="${w?-50:-66}" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="30" fill="${C.navy}" opacity="0"></text><circle cx="86" cy="-44" r="18" fill="${C.cream}" ${st(C.navy,4)}/><text x="86" y="-37" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="22" fill="${C.navy}">N</text><circle cx="86" cy="2" r="18" fill="${C.cream}" ${st(C.navy,4)}/><text x="86" y="9" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="22" fill="${C.navy}">S</text></g>`};
P.e120_mapnote=(o,T)=>`<g transform="rotate(${f(-5+Math.sin(T*2)*1.2)})"><rect x="-108" y="-70" width="216" height="140" rx="12" fill="${C.cream}" ${st()}/><rect x="-108" y="-70" width="216" height="24" rx="12" fill="#E8DFC8" ${st()}/><path d="M-80 30 q16 -44 46 -20 t50 -22 t52 14" fill="none" ${st(C.red,5)} stroke-dasharray="2 9"/><circle cx="-80" cy="30" r="9" fill="${C.navy}"/><g transform="translate(60,-6)"><path d="M0 0 C-14 -14 -16 -24 -16 -30 a16 16 0 0 1 32 0 C16 -24 14 -14 0 0Z" fill="${C.red}" ${st(C.navy,3)}/></g><g transform="translate(66,34) rotate(-40)"><rect x="-6" y="-44" width="12" height="52" rx="4" fill="${C.gold}" ${st()}/><path d="M-6 8 L0 22 L6 8Z" fill="${_e120SK}" ${st(C.navy,3)}/></g></g>`;
/* running with a bag next to a train, doors closing */
P.e120_runner=(o,T,k)=>{const b=Math.sin(T*9)*5,j={H:[16,-90],S:[8,-66],Pv:[-10,-8],A:[[[-6,-40],[-26,-52]],[[30,-52],[48,-74]]],L:[[[-24,40+b],[-38,92]],[[22,22-b],[40,52]]]},dc=ease(k/2.2)*.9;
  return `<g>${_e120sh(0,106,120)}<g transform="translate(32,-6)"><rect x="-6" y="-70" width="120" height="130" rx="14" fill="#F4F2EA" ${st()}/><rect x="-6" y="34" width="120" height="12" fill="${C.blue}"/><rect x="12" y="-52" width="60" height="86" rx="6" fill="#CBE8F5" ${st(C.navy,4)}/><rect x="${f(12+dc*0)}" y="-52" width="${f(30-dc*28)}" height="86" fill="#B9C6CE" ${st(C.navy,3)}/><rect x="${f(72-30+dc*28)}" y="-52" width="${f(30-dc*28)}" height="86" fill="#B9C6CE" ${st(C.navy,3)}/></g><g transform="translate(-70,12) scale(.9)">${_e113man(j,{c:C.blue,hc:'#222',dir:1,ha:10})}<g transform="translate(-14,-44) rotate(-12)"><rect x="-12" y="-22" width="24" height="44" rx="8" fill="${C.orange}" ${st()}/></g></g></g>`};
/* underground: street above, tunnel with a train below */
P.e120_metro=(o,T)=>{const x=((T*70)%420)-210;
  return `<g>${_e120frame('m',250,214,`<rect x="-125" y="-107" width="250" height="60" fill="#BFE3F2"/><rect x="-125" y="-47" width="250" height="154" fill="#9A6B45"/><g fill="#8A5C3A" opacity=".7"><circle cx="-90" cy="-30" r="6"/><circle cx="70" cy="-20" r="5"/><circle cx="-30" cy="-34" r="4"/></g><rect x="-125" y="-52" width="250" height="10" fill="#6FA774" ${st(C.navy,3)}/>${[[-95,34],[-60,50],[-26,42],[8,58],[60,38],[98,48]].map(([bx,h],i)=>`<rect x="${bx-14}" y="${-52-h}" width="28" height="${h}" fill="${['#C9A98B','#B9C6CE','#E7D3A6'][i%3]}" ${st(C.navy,3)}/><rect x="${bx-6}" y="${-52-h+8}" width="12" height="9" fill="#FFE08A"/>`).join('')}<rect x="-125" y="0" width="250" height="84" rx="0" fill="#3B4A57" ${st(C.navy,4)}/><rect x="-125" y="4" width="250" height="76" fill="#55687A"/><g transform="translate(${f(x)},40)"><rect x="-96" y="-30" width="192" height="56" rx="12" fill="#F4F2EA" ${st()}/><rect x="-96" y="6" width="192" height="8" fill="${C.red}"/>${[-76,-34,8,50].map(wx=>`<rect x="${wx}" y="-22" width="30" height="22" rx="4" fill="#CBE8F5" ${st(C.navy,3)}/>`).join('')}<rect x="-5" y="-26" width="10" height="44" fill="#B9C6CE"/></g><rect x="-125" y="70" width="250" height="14" fill="#2C3944"/><path d="M-90 -50 l40 50 h-40Z" fill="#B9A988" ${st(C.navy,3)}/><rect x="-94" y="-82" width="8" height="32" fill="${C.navy2}"/><rect x="-108" y="-100" width="36" height="20" rx="4" fill="${C.blue}" ${st(C.navy,3)}/><path d="M-100 -90 h20 M-90 -96 v12" ${st('#fff',3)}/>`,26)}</g>`};
/* underground map: twelve coloured lines (looks like a child's drawing) */
P.e120_metromap=(o,T,k)=>{const cols=['#E5493F','#F2994A','#F6CE4B','#5FB36B','#4DA3D8','#2F5D8A','#8E6BB5','#D96C8B','#4F7A5A','#8B5E3C','#5CC0C0','#7F8C8D'];let l='';
  cols.forEach((c,i)=>{const p=ease((k-.1-i*.12)/.5);const pts=[0,1,2,3,4].map(j=>[-100+j*50+((i*53+j*29)%36-18),((i*37+j*61+j*j*13)%150)-75]);
    l+=`<path d="M${pts.map(q=>q.join(' ')).join(' L')}" fill="none" stroke="${c}" stroke-width="7" stroke-linecap="round" stroke-linejoin="round" pathLength="1" stroke-dasharray="1" stroke-dashoffset="${f(1-p)}" opacity=".95"/>`;pts.forEach(q=>l+=`<circle cx="${q[0]}" cy="${q[1]}" r="5" fill="#fff" ${st(C.navy,2.5)} opacity="${f(p)}"/>`)});
  return `<g transform="rotate(${f(Math.sin(T*1.6)*1.5)})"><rect x="-122" y="-104" width="244" height="208" rx="14" fill="${C.cream}" ${st()}/>${l}${o.crayon?`<g transform="translate(96,70) rotate(-35)"><rect x="-8" y="-40" width="16" height="64" fill="${C.red}" ${st(C.navy,3)}/><path d="M-8 24 L0 42 L8 24Z" fill="${C.red}" ${st(C.navy,3)}/></g>`:''}</g>`};
/* circle line: a ring, a train going round, lap counter */
P.e120_loop=(o,T,k)=>{const R=82,ang=(o.laps!=null?o.laps*360:0)+(T*70)%360,a=ang*Math.PI/180;let dots='';for(let i=0;i<8;i++){const q=i*Math.PI/4;dots+=`<circle cx="${f(Math.cos(q)*R)}" cy="${f(Math.sin(q)*R)}" r="9" fill="#fff" ${st(C.navy,4)}/>`}
  return `<g><circle r="${R}" fill="none" ${st(C.navy,18)}/><circle r="${R}" fill="none" ${st(C.blue,10)}/>${dots}<g transform="translate(${R},0)"><path d="M0 -14 L18 0 L0 14Z" fill="${C.red}"/></g><g transform="translate(${f(Math.cos(a)*R)},${f(Math.sin(a)*R)}) rotate(${f(ang+90)})"><rect x="-13" y="-22" width="26" height="44" rx="8" fill="#F4F2EA" ${st()}/><rect x="-13" y="-4" width="26" height="8" fill="${C.red}"/></g><text x="0" y="14" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="${o.t?'46':'0'}" fill="${C.navy}">${o.t||''}</text></g>`};
/* museum */
P.e120_museum=(o,T)=>{let cols='';for(let i=0;i<5;i++)cols+=`<rect x="${-86+i*38}" y="-34" width="18" height="86" fill="#F4EEE0" ${st(C.navy,4)}/><rect x="${-90+i*38}" y="-40" width="26" height="10" fill="#E2D6BC" ${st(C.navy,3)}/>`;
  return `<g>${_e120sh(0,100,120)}<path d="M-112 -34 L0 -104 L112 -34Z" fill="#E2D6BC" ${st()}/><circle cx="0" cy="-62" r="12" fill="${C.gold}" ${st(C.navy,3)}/><rect x="-104" y="-34" width="208" height="8" fill="#E2D6BC" ${st()}/>${cols}<rect x="-108" y="52" width="216" height="14" fill="#D9C9A2" ${st()}/><rect x="-118" y="66" width="236" height="14" fill="#C9B88F" ${st()}/><rect x="-32" y="-8" width="64" height="60" rx="6" fill="${C.brown}" ${st()}/>${o.shut?`<g transform="translate(0,${f(2+Math.sin(T*2)*2)}) rotate(${f(Math.sin(T*2)*3)})"><path d="M-14 -8 v-14 M14 -8 v-14" ${st(C.navy,3)}/><rect x="-44" y="-8" width="88" height="40" rx="6" fill="${C.red}" ${st()}/><text x="0" y="20" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="17" fill="#fff">CLOSED</text></g>`:`<path d="M-26 -2 L-26 52 M26 -2 L26 52" ${st(C.navy,3)}/>`}</g>`};

/* ---------- ships ---------- */
const _e120wave=(W,y,T,r,col,op)=>{let d='';for(let x=-W/2-20;x<=W/2+20;x+=10)d+=(d?' L':'M')+`${x} ${f(y+Math.sin((x+T*60*(1+r*.2))/16+r)*4)}`;return `<path d="${d}" fill="none" ${st(col||'#fff',3)} opacity="${op||.8}"/>`};
const _e120shipBody=(T,o)=>{let win='';for(let i=0;i<8;i++)win+=`<circle cx="${-112+i*22}" cy="14" r="6" fill="#CBE8F5" ${st(C.navy,2.5)}/>`;
  let decks='';for(let r=0;r<3;r++){for(let i=0;i<7-r;i++)decks+=`<rect x="${-96+r*16+i*(25)}" y="${-4-r*26}" width="16" height="12" rx="3" fill="${o.night?'#FFE08A':'#CBE8F5'}" ${st(C.navy,2.5)}/>`}
  let sm='';for(let i=0;i<3;i++){const ph=(T*.6+i/3)%1;sm+=`<circle cx="${f(-20-ph*34)}" cy="${f(-100-ph*40)}" r="${f(7+ph*10)}" fill="#E8EEF1" opacity="${f(.85-ph*.85)}"/>`}
  return `<g>${sm}<path d="M-118 22 H128 L104 56 H-96Z" fill="#2F5D8A" ${st()}/><path d="M-114 26 H124" ${st('#fff',5)}/>${win.replace(/cy="14"/g,'cy="40"')}<path d="M-104 22 V-8 H100 L116 22Z" fill="#F4F2EA" ${st()}/>${decks}<rect x="-70" y="-62" width="150" height="26" rx="6" fill="#F4F2EA" ${st()}/><rect x="-52" y="-56" width="14" height="14" rx="3" fill="#CBE8F5" ${st(C.navy,2.5)}/><rect x="-26" y="-56" width="14" height="14" rx="3" fill="#CBE8F5" ${st(C.navy,2.5)}/><rect x="-60" y="-96" width="34" height="34" rx="4" fill="${C.red}" ${st()}/><rect x="-60" y="-84" width="34" height="8" fill="#fff"/><rect x="2" y="-84" width="30" height="22" rx="4" fill="#F4F2EA" ${st()}/><path d="M60 -62 V-90 M60 -90 L96 -64" ${st(C.navy,3.5)}/></g>`};
P.e120_ship=(o,T)=>{const v=o.v||'day',night=v==='night',dawn=v==='dawn',roll=o.rock?Math.sin(T*2.6)*(o.rock*7):Math.sin(T*1.2)*1.5,bob=Math.sin(T*1.3)*3;
  const dusk=v==='dusk',sky=night?'#1B2547':dusk?'#8A6AA0':dawn?'#F6B48B':'#BFE3F2';let s=`<rect x="-125" y="-107" width="250" height="214" fill="${sky}"/>`;
  if(night){for(let i=0;i<16;i++)s+=`<circle cx="${(i*53)%240-120}" cy="${-98+(i*31)%110}" r="${1.4+i%3*.6}" fill="#FFF3C4" opacity="${f(.5+.4*Math.sin(T*2+i))}"/>`;s+=`<path d="M70 -76 a22 22 0 1 0 22 28 a18 18 0 1 1 -22 -28Z" fill="#F7E7A3" ${st('#C9B260',3)}/>`}
  else s+=`<circle cx="${dawn||dusk?70:76}" cy="${dawn?-26:dusk?4:-70}" r="22" fill="${dawn||dusk?'#FFB45A':'#F6CE4B'}" ${st('#C9971F',3)}/>`;
  s+=`<rect x="-125" y="22" width="250" height="90" fill="${night?'#243C6B':dusk?'#6B5A8E':dawn?'#E9856E':'#4DA3D8'}"/>`;
  s+=`<g transform="translate(0,${f(bob)}) rotate(${f(roll)} 0 56)"><g transform="translate(0,6) scale(.74)">${_e120shipBody(T,{night})}</g></g>`;
  for(let r=0;r<4;r++)s+=_e120wave(250,52+r*14,T,r,night?'#8FB2E8':'#fff',.7);
  return `<g>${_e120frame('s'+v+(o.rock?'r':''),250,214,s,26)}</g>`};
/* island: green hill, white houses along the coast, dawn sky */
P.e120_island=(o,T)=>{let hs='';[-70,-30,10,50,86].forEach((x,i)=>hs+=_e120house(x,50-Math.abs(x)*.12-(i%2)*6,1.15,'#fff',[C.red,C.orange][i%2]));
  const s=`<rect x="-125" y="-107" width="250" height="214" fill="url(#e120_dawn)"/><defs><linearGradient id="e120_dawn" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#E88FB0"/><stop offset=".55" stop-color="#F6B48B"/><stop offset="1" stop-color="#FFD9A0"/></linearGradient></defs><circle cx="58" cy="-6" r="26" fill="#FFD27A" ${st('#E2A04A',3)}/><rect x="-125" y="40" width="250" height="70" fill="#E9856E"/><path d="M-120 58 Q-90 -4 -20 4 Q50 -8 118 56 Z" fill="#5E9B63" ${st()}/><path d="M-70 36 Q-30 14 20 26" fill="none" ${st('#7DB77F',6)}/>${hs}<path d="M-100 62 q12 -6 24 0 t24 0 M40 80 q12 -6 24 0 t24 0 M-60 92 q12 -6 24 0 t24 0" fill="none" ${st('#fff',3)} opacity=".8"/>${o.ship?`<g transform="translate(76,60) scale(.2)">${_e120shipBody(T,{})}</g>`:''}`;
  return `<g>${_e120frame('is',250,214,s,26)}</g>`};
/* the front of a ship at dawn with a figure looking forward */
P.e120_bow=(o,T)=>{const j={H:[8,-96],S:[4,-70],Pv:[-2,-8],A:[[[16,-44],[34,-60]],[[22,-40],[40,-56]]],L:[[[-8,46],[-10,100]],[[10,46],[12,100]]]};
  const s=`<rect x="-125" y="-107" width="250" height="214" fill="#F6B48B"/><circle cx="60" cy="-20" r="24" fill="#FFD27A" ${st('#E2A04A',3)}/><rect x="-125" y="12" width="250" height="100" fill="#E9856E"/><path d="M-30 14 Q10 -16 70 14Z" fill="#5E9B63" ${st(C.navy,3)}/>${_e120wave(250,34,T,0,'#fff')}${_e120wave(250,50,T,1,'#fff')}<path d="M-125 66 H125 V112 H-125Z" fill="#B9553F" ${st()}/><path d="M-125 66 H125" ${st('#fff',6)}/><g transform="translate(-30,70) scale(.78)">${_e113man(j,{c:'#B07AA1',hc:'#D5D8DB',hair:'bun',dir:1,pc:'#5C4A6B'})}</g><path d="M30 84 L96 66 L125 66 V112 H30Z" fill="#C9694E" ${st()}/><path d="M-125 80 H40 M52 40 V80 M84 40 V70 M-125 40 H125" fill="none" ${st(C.navy2,4)}/>`;
  return `<g>${_e120frame('bow',250,214,s,26)}</g>`};
P.e120_deck=(o,T)=>{let s=`<rect x="-125" y="-107" width="250" height="214" fill="#1B2547"/>`;for(let i=0;i<24;i++)s+=`<circle cx="${(i*47)%240-120}" cy="${-100+(i*29)%110}" r="${1.4+i%3*.7}" fill="#FFF3C4" opacity="${f(.5+.45*Math.sin(T*2.2+i))}"/>`;
  s+=`<path d="M-50 -64 a22 22 0 1 0 22 28 a18 18 0 1 1 -22 -28Z" fill="#F7E7A3" ${st('#C9B260',3)}/><rect x="-125" y="30" width="250" height="82" fill="#243C6B"/><rect x="-125" y="56" width="250" height="56" fill="#9A6B45" ${st(C.navy,4)}/><path d="M-125 60 H125" ${st('#C99A6A',3)}/><path d="M-125 20 H125 M-110 20 V58 M-60 20 V58 M-10 20 V58 M90 20 V58 M40 20 V58" fill="none" ${st('#E8EEF1',5)}/><g transform="translate(36,56) scale(.8)">${P.person({c:'#B07AA1',hair:'bun',hc:'#D5D8DB'},T)}</g>`;
  return `<g>${_e120frame('dk',250,214,s,26)}</g>`};
/* what is inside a big ship: restaurant, shop, swimming, bedroom */
P.e120_shipinside=(o,T)=>{const cell=(x,y,fill,inner)=>`<g transform="translate(${x},${y})"><rect x="-56" y="-44" width="112" height="88" rx="10" fill="${fill}" ${st()}/>${inner}</g>`;
  return `<g><path d="M-122 70 H128 L106 100 H-100Z" fill="#2F5D8A" ${st()}/>${cell(-60,-42,'#FFE9C2',`<circle cx="0" cy="8" r="26" fill="#fff" ${st(C.navy,4)}/><circle cx="-8" cy="4" r="9" fill="${C.red}"/><circle cx="8" cy="12" r="8" fill="#5FB36B"/><path d="M-46 -14 v50 M-54 -14 v16 M-38 -14 v16" ${st(C.navy,3.5)}/>`)}${cell(60,-42,'#DDEBF4',`<g transform="translate(0,6)"><path d="M-24 -20 h48 l8 52 h-64Z" fill="${C.orange}" ${st()}/><path d="M-12 -20 q12 -26 24 0" fill="none" ${st(C.navy,5)}/></g>`)}${cell(-60,46,'#BFE3F2',`<rect x="-52" y="-10" width="104" height="48" rx="4" fill="#4DA3D8" ${st(C.navy,3)}/><path d="M-44 8 q10 -8 20 0 t20 0 t20 0 t20 0" fill="none" ${st('#fff',4)}/><path d="M30 -10 V-40 M42 -10 V-40" ${st('#B9C6CE',5)}/>`)}${cell(60,46,'#F3E6D0',`<g transform="translate(0,6)"><path d="M-44 24 V-16" ${st(C.brown,7)}/><rect x="-44" y="2" width="88" height="16" fill="${C.blue}" ${st()}/><rect x="-42" y="-8" width="32" height="12" rx="6" fill="#fff" ${st(C.navy,3)}/></g>`)}</g>`};
/* four cabin doors */
P.e120_rooms=(o,T)=>{let d='';for(let i=0;i<4;i++)d+=`<g transform="translate(${-96+i*64},0)"><rect x="-26" y="-92" width="52" height="150" rx="6" fill="#B9553F" ${st()}/><rect x="-18" y="-80" width="36" height="60" rx="4" fill="#C9694E" ${st(C.navy,3)}/><circle cx="12" cy="10" r="5" fill="${C.gold}" ${st(C.navy,2.5)}/><rect x="-14" y="-72" width="28" height="22" rx="4" fill="${C.gold}" ${st(C.navy,3)}/><text x="0" y="-55" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="22" fill="${C.navy}">${i+1}</text></g>`;
  return `<g><rect x="-128" y="-108" width="256" height="182" rx="10" fill="#EFE5C8" ${st()}/><rect x="-128" y="58" width="256" height="16" fill="#8E6B4A" ${st()}/>${d}</g>`};
/* the tiny cupboard room next to the kitchen */
P.e120_cupboard=(o,T)=>{let sm='';for(let i=0;i<4;i++){const ph=(T*.7+i/4)%1;sm+=`<path d="M${f(-92+i*6)} ${f(-26-ph*50)} q-8 -10 0 -20 t0 -20" transform="translate(${i*8},0)" fill="none" ${st('#F2994A',5)} opacity="${f(1-ph)}"/>`}
  return `<g><rect x="-122" y="-96" width="244" height="190" rx="12" fill="#EFE5C8" ${st()}/><rect x="-122" y="-96" width="108" height="190" rx="12" fill="#D9C9A2" ${st()}/><g transform="translate(-66,16)"><rect x="-38" y="-6" width="76" height="52" rx="6" fill="#8E9AA3" ${st()}/><path d="M-22 -6 V-30 H22 V-6" fill="${C.red}" ${st()}/><ellipse cx="0" cy="-30" rx="26" ry="8" fill="#7A3B2E" ${st()}/><path d="M-14 -14 h28" ${st('#fff',3)}/></g>${sm}<rect x="-6" y="-30" width="116" height="104" rx="6" fill="#fff" ${st()}/><rect x="2" y="30" width="100" height="22" fill="${C.blue}" ${st()}/><rect x="6" y="14" width="30" height="16" rx="8" fill="#fff" ${st(C.navy,3)}/><rect x="2" y="52" width="6" height="22" fill="${C.navy2}"/><rect x="96" y="52" width="6" height="22" fill="${C.navy2}"/></g>`};
/* three heads: brown -> white -> green (feeling sick on a ship) */
P.e120_sick=(o,T)=>{const cols=['#B77A4A','#F4F0E6','#7FC46B'],ph=Math.floor((T*.9)%3);let h='';
  cols.forEach((c,i)=>{h+=`<g transform="translate(${-92+i*92},-4) scale(${i===ph?1.1:.95})"><path d="M-30 80 L-30 40 Q-30 22 0 22 Q30 22 30 40 L30 80Z" fill="${C.blue}" ${st()}/><rect x="-9" y="10" width="18" height="16" fill="${c}" ${st(C.navy,3.5)}/><circle cx="0" cy="-12" r="32" fill="${c}" ${st()}/><path d="M-30 -14 Q-32 -46 0 -46 Q32 -46 30 -14 Q8 -30 -30 -14Z" fill="#3A2A22" ${st()}/></g>`;if(i<2)h+=`<path d="M${-60+i*92} -8 h24 m-8 -8 l8 8 l-8 8" fill="none" ${st(C.navy,4.5)}/>`});
  return `<g>${h}${_e120wave(260,76,T,0,C.blue,1)}${_e120wave(260,92,T,1,C.blue,1)}</g>`};
P.e120_sickbed=(o,T)=>`<g><rect x="-110" y="-30" width="220" height="100" rx="10" fill="#4DA3D8" ${st()}/><rect x="-110" y="-70" width="16" height="140" fill="${C.brown}" ${st()}/><rect x="-92" y="-30" width="64" height="40" rx="14" fill="#fff" ${st()}/><circle cx="-60" cy="-12" r="26" fill="#7FC46B" ${st()}/><path d="M-84 -20 Q-84 -44 -60 -44 Q-36 -44 -36 -20 Q-56 -30 -84 -20Z" fill="#3A2A22" ${st(C.navy,3)}/><rect x="-30" y="-24" width="140" height="70" rx="12" fill="#6FB1D6" ${st()}/><path d="M-14 -20 q20 14 40 0 t40 0" fill="none" ${st('#fff',3)} opacity=".6"/><rect x="110" y="40" width="6" height="40" fill="${C.navy2}"/>${[0,1,2].map(i=>`<text x="${f(-24+i*24)}" y="${f(-70-((T*30+i*20)%40))}" font-family="Fraunces" font-weight="900" font-size="26" fill="${C.navy}" opacity="${f(.9-((T*30+i*20)%40)/44)}">z</text>`).join('')}</g>`;

/* ---------- air travel ---------- */
const _e120plane=(T,o)=>`<g transform="rotate(${f(o.rot||0)})"><path d="M-110 -6 Q-110 -26 -70 -26 H70 Q116 -26 128 -4 Q116 14 70 14 H-70 Q-110 14 -110 -6Z" fill="#fff" ${st()}/><path d="M-110 -6 L-124 -44 L-92 -44 L-70 -26Z" fill="${C.red}" ${st()}/><path d="M-20 -10 L-50 -64 H-24 L22 -10Z" fill="#C8D4DA" ${st()}/><path d="M-20 4 L-50 54 H-24 L22 4Z" fill="#B9C6CE" ${st()}/><path d="M100 -20 Q120 -16 126 -6 H88Z" fill="#CBE8F5" ${st(C.navy,3)}/>${[-68,-48,-28,-8,12,32,52].map(x=>`<circle cx="${x}" cy="-8" r="5" fill="#CBE8F5" ${st(C.navy,2.5)}/>`).join('')}<path d="M-114 4 H124" ${st(C.blue,5)}/></g>`;
P.e120_route=(o,T,k)=>{const p=ease(k/1.4),stops=o.stops;let line='',pl='';const x0=-90,x1=90;
  if(!stops){line=`<path d="M${x0} 20 Q0 -50 ${x1} 20" fill="none" ${st(C.navy,5)} stroke-dasharray="4 11"/>`;const t=(T*.45)%1,px=x0+(x1-x0)*t,py=20-70*(1-Math.pow(2*t-1,2))*.5*2;pl=`<g transform="translate(${f(px)},${f(py-6)}) rotate(${f(-40*(2*t-1)*-1)}) scale(.32)">${_e120plane(T,{})}</g>`}
  else{line=`<path d="M${x0} 20 Q-45 -34 0 20 Q45 -34 ${x1} 20" fill="none" ${st(C.navy,5)} stroke-dasharray="4 11"/>`;const t=(T*.35)%1,px=x0+(x1-x0)*t,py=20-52*Math.abs(Math.sin(t*Math.PI*2))*.9;pl=`<g transform="translate(${f(px)},${f(py-6)}) scale(.28)">${_e120plane(T,{})}</g>`}
  return `<g>${line}${_e120pin(x0,26,C.moss)}${_e120pin(x1,26,C.red)}${stops?`<g transform="translate(0,34)"><circle r="13" fill="#fff" ${st()}/><circle r="6" fill="${C.navy}"/></g><g transform="translate(0,-82) scale(.5)">${P.moon({},T)}</g>`:''}${pl}</g>`};
P.e120_airportnight=(o,T)=>{let w='';for(let i=0;i<9;i++)w+=`<rect x="${-96+i*22}" y="38" width="14" height="22" fill="#FFE08A" ${st(C.navy,2.5)}/>`;
  let s=`<rect x="-125" y="-107" width="250" height="214" fill="#1B2547"/>`;for(let i=0;i<18;i++)s+=`<circle cx="${(i*47)%240-120}" cy="${-100+(i*31)%110}" r="${1.4+i%3*.6}" fill="#FFF3C4" opacity="${f(.5+.4*Math.sin(T*2+i))}"/>`;
  s+=`<path d="M70 -88 a20 20 0 1 0 22 26 a16 16 0 1 1 -22 -26Z" fill="#F7E7A3" ${st('#C9B260',3)}/><rect x="40" y="-30" width="18" height="90" fill="#9FB0BA" ${st()}/><rect x="28" y="-52" width="42" height="26" rx="5" fill="#FFE08A" ${st()}/><rect x="-125" y="30" width="250" height="82" fill="#2C3A5C"/><rect x="-118" y="30" width="170" height="40" rx="6" fill="#E8EEF1" ${st()}/>${w.replace(/y="38"/g,'y="38"')}<rect x="-125" y="76" width="250" height="36" fill="#3B4A6B"/><path d="M-110 94 H110" ${st('#fff',3)} stroke-dasharray="14 10"/><g transform="translate(${f(-20+Math.sin(T*.8)*30)},88) scale(.3)">${_e120plane(T,{})}</g>`;
  return `<g>${_e120frame('an',250,214,s,26)}</g>`};
P.e120_pricetag=(o,T)=>{const up=o.dir==='up',col=up?C.red:C.moss,m=Math.sin(T*3)*6;
  return `<g><g transform="translate(-30,${f(up?-m:m)}) rotate(-12)"><path d="M-70 -34 H30 L74 0 L30 34 H-70 Q-80 34 -80 24 V-24 Q-80 -34 -70 -34Z" fill="${C.gold}" ${st()}/><circle cx="-56" cy="0" r="8" fill="${C.cream}" ${st(C.navy,3)}/><path d="M-30 -10 h40 M-30 8 h28" ${st(C.navy,5)}/></g><g transform="translate(86,0) scale(${up?1:-1},1)"><g transform="translate(0,${f(up?-m:m)})"><path d="M0 -62 L30 -26 H12 V60 H-12 V-26 H-30Z" fill="${col}" ${st()} transform="${up?'':'scale(1,-1)'}"/></g></g></g>`};
P.e120_landing=(o,T,k)=>{const hit=o.hit,t=hit?1:ease(k/3);const shake=hit?Math.sin(T*40)*2.4:0;
  return `<g>${_e120frame('ld'+(hit?1:0),250,214,`<rect x="-125" y="-107" width="250" height="214" fill="${hit?'#9FB6C4':'#BFE3F2'}"/>${hit?`<path d="M-110 -70 q30 -20 60 0 t60 0 t60 0" fill="none" ${st('#fff',6)} opacity=".8"/>`:''}<path d="M-125 60 H125 V107 H-125Z" fill="#4A5560" ${st(C.navy,4)}/><path d="M-110 84 H110" ${st('#fff',4)} stroke-dasharray="16 12"/><g transform="translate(${f(-6+shake)},${f(hit?24+Math.abs(shake):-60+t*70)}) rotate(${f(hit?0:-9+t*3)}) scale(.5)">${_e120plane(T,{})}<g>${_e120wheel(40,34,12,0)}${_e120wheel(-30,34,12,0)}<path d="M40 14 V30 M-30 14 V30" ${st(C.navy,5)}/></g></g>${hit?[0,1,2].map(i=>`<circle cx="${f(-42-i*16+((T*60)%14))}" cy="${f(68-i*5)}" r="${7+i*2}" fill="#EDEDED" opacity="${f(.8-i*.2)}"/>`).join('')+`<g ${st(C.red,5)}><path d="M40 20 l12 -8 M46 36 l14 0 M40 52 l12 8"/></g>`:''}`,26)}</g>`};
P.e120_grip=(o,T)=>{const sh=Math.sin(T*38)*2.2;
  return `<g transform="translate(${f(sh)},0)"><rect x="-70" y="-100" width="140" height="170" rx="32" fill="#4F7A5A" ${st()}/><rect x="-54" y="-86" width="108" height="86" rx="22" fill="#5E9B63" ${st(C.navy,4)}/><rect x="-96" y="-10" width="28" height="90" rx="12" fill="#3F6347" ${st()}/><rect x="68" y="-10" width="28" height="90" rx="12" fill="#3F6347" ${st()}/><g transform="translate(0,-8) scale(.62)">${P.person({c:C.orange,hair:'bun',hc:'#2A1D18'},0)}</g><circle cx="-82" cy="2" r="13" fill="${_e120SK}" ${st(C.navy,4)}/><circle cx="82" cy="2" r="13" fill="${_e120SK}" ${st(C.navy,4)}/>${[-1,1].map(d=>`<path d="M${d*112} -20 l${d*12} -8 M${d*114} 6 h${d*16} M${d*112} 30 l${d*12} 8" ${st(C.navy,4.5)}/>`).join('')}</g>`};
P.e120_spill=(o,T,k)=>{const sp=ease((k-.35)/.5);
  return `<g><path d="M-62 112 L-62 36 Q-62 -4 0 -4 Q62 -4 62 36 L62 112 Z" fill="#fff" ${st()}/><path d="M-12 -4 L0 22 L12 -4" fill="${C.cream}" ${st(C.navy,4)}/><g transform="translate(0,10)"><path d="M-24 22 q-10 22 8 34 q22 10 34 -6 q10 -22 -6 -34 q8 -22 -16 -18 q-12 -14 -20 6 q-14 4 0 18Z" fill="#7A4A26" opacity="${f(sp*.95)}" transform="scale(${f(.4+sp*.6)})"/></g><g transform="translate(70,-40) rotate(${f(-52*ease(k/.5))})"><path d="M-26 -30 L26 -30 L18 26 Q0 40 -18 26Z" fill="#fff" ${st()}/><path d="M26 -16 a12 12 0 1 1 -4 22" fill="none" ${st(C.navy,5)}/><path d="M-26 -30 h52" ${st(C.navy,4)}/></g><g fill="#7A4A26">${[0,1,2,3].map(i=>`<circle cx="${f(34+i*10)}" cy="${f(-10+Math.sin(i*2)*8+ease(k/.6)*(14+i*8))}" r="${4-i*.5}" opacity="${f(sp)}"/>`).join('')}</g></g>`};
P.e120_stains=(o,T)=>{const sh=(x,c)=>`<g transform="translate(${x},0) scale(.8)"><path d="M-62 100 L-62 30 Q-62 -4 0 -4 Q62 -4 62 30 L62 100 Z" fill="#fff" ${st()}/><path d="M-12 -4 L0 22 L12 -4" fill="${C.cream}" ${st(C.navy,4)}/><path d="M-22 24 q-10 22 8 34 q22 10 34 -6 q10 -22 -6 -34 q8 -22 -16 -18 q-12 -14 -20 6 q-14 4 0 18Z" fill="#7A4A26"/><g transform="translate(0,-4)"><rect x="-11" y="-20" width="22" height="20" fill="${_e120SK}" ${st(C.navy,4)}/><circle cx="0" cy="-54" r="36" fill="${_e120SK}" ${st()}/><path d="M-36 -56 Q-38 -92 0 -92 Q38 -92 36 -56 Q8 -72 -36 -56Z" fill="${c}" ${st()}/></g></g>`;
  return `<g>${sh(-62,'#222')}${sh(62,'#8B5E3C')}</g>`};
P.e120_thanks=(o,T)=>`<g><g transform="translate(-74,24) scale(.8)">${_e120who({c:'#2F5D8A',hair:'short',hc:'#222',hat:'cap'},T)}</g><g transform="translate(46,34) scale(.5)"><g transform="translate(-60,0)">${P.person({c:C.red,hair:'long',hc:'#3A2A22'},T)}</g><g transform="translate(60,0)">${P.person({c:C.moss,hair:'short',hc:'#222',ph:2},T)}</g></g><g transform="translate(36,-70) scale(.5)">${P.bubble({side:'L',text:'Thank you!',fs:26,w:150},T)}</g></g>`;
P.e120_checkin=(o,T)=>{const bx=((T*40)%200)-100;
  return `<g><rect x="-120" y="30" width="240" height="40" rx="10" fill="#6B7C86" ${st()}/><rect x="-120" y="30" width="240" height="14" rx="6" fill="#8A9AA4"/>${[-100,-60,-20,20,60,100].map(x=>`<circle cx="${x}" cy="56" r="6" fill="${C.navy2}"/>`).join('')}<path d="M-50 30 V-52 Q-50 -86 0 -86 Q50 -86 50 -52 V30" fill="none" ${st(C.navy,22)}/><path d="M-50 30 V-52 Q-50 -86 0 -86 Q50 -86 50 -52 V30" fill="none" ${st('#9FB0BA',12)}/><rect x="-36" y="-52" width="72" height="82" fill="#101A24" opacity=".25"/><g transform="translate(${f(bx)},0)"><rect x="-26" y="-14" width="52" height="44" rx="8" fill="${C.orange}" ${st()}/><path d="M-12 -14 q12 -20 24 0" fill="none" ${st(C.navy,5)}/></g></g>`};

/* ---------- on the road ---------- */
const _e120spokes=(x,y,r,a)=>_e120wheel(x,y,r,a);
const _e120moto=(T,o)=>{const a=T*(o.fast?500:o.slow?90:260);
  return `<g>${_e120sh(0,66,112)}<path d="M-96 26 H-58 L-62 40" fill="none" ${st(C.navy2,8)}/>${_e120wheel(-62,40,26,a)}${_e120wheel(70,40,26,a)}<path d="M52 24 Q74 6 96 22" fill="none" ${st(C.navy,12)}/><path d="M52 24 Q74 6 96 22" fill="none" ${st('#C9301F',6)}/><path d="M-62 40 L-26 6 H18" fill="none" ${st(C.navy,12)}/><path d="M-62 40 L-26 6 H18" fill="none" ${st('#B9C6CE',6)}/><path d="M70 40 L48 -38" fill="none" ${st(C.navy,12)}/><path d="M70 40 L48 -38" fill="none" ${st('#B9C6CE',6)}/><path d="M40 -42 L60 -48" fill="none" ${st(C.navy,9)}/><rect x="-32" y="2" width="68" height="38" rx="10" fill="#7C8A94" ${st()}/><path d="M-20 14 h44 M-20 26 h44" ${st(C.navy,3)}/><path d="M-18 -4 Q-10 -34 24 -32 Q44 -30 46 -8 L44 2 H-14Z" fill="#E5493F" ${st()}/><path d="M-6 -20 Q8 -28 26 -24" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round" opacity=".6"/><path d="M-70 -14 Q-60 -26 -30 -22 L-20 -6 H-66Z" fill="${C.navy2}" ${st()}/><circle cx="62" cy="-24" r="10" fill="#FFE08A" ${st(C.navy,3.5)}/>${o.ring==='front'?`<circle cx="70" cy="40" r="${f(38+Math.sin(T*6)*3)}" fill="none" ${st(C.gold,6)}/>`:''}${o.ring==='back'?`<circle cx="-62" cy="40" r="${f(38+Math.sin(T*6)*3)}" fill="none" ${st(C.gold,6)}/>`:''}${o.ring==='light'?`<circle cx="62" cy="-24" r="${f(24+Math.sin(T*6)*3)}" fill="none" ${st(C.gold,6)}/>`:''}</g>`};
const _e120rider=(T,o)=>{const j={H:[2,-112],S:[-6,-86],Pv:[-34,-30],A:[[[16,-66],[42,-52]],[[18,-62],[44,-48]]],L:[[[0,-16],[-2,20]],[[2,-14],[0,22]]]};
  return `<g transform="translate(-34,-30) scale(.84) translate(34,30)">${_e113man(j,{c:o.jc||'#6B4A2A',pc:'#2F4458',dir:1,ha:6,tw:34,hc:'#222',hair:'none'})}${_e120hatAt(2,-112,'helmet')}</g>`};
