/* Episode 120 intro hero: modern train on rails with a ship badge and a motorcycle badge (getting around: trains, ships, motorcycles) */
const _e120iPlate=(id,c1,c2,T,ring)=>`<defs><radialGradient id="${id}" cx="50%" cy="40%" r="65%"><stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></radialGradient></defs><circle r="136" fill="${c1}" opacity="${f(.10+.04*Math.sin(T*1.5))}"/><circle r="126" fill="url(#${id})"/><circle r="126" fill="none" stroke="${ring}" stroke-width="3" opacity=".7"/><circle r="136" fill="none" stroke="${ring}" stroke-width="2" stroke-dasharray="3 11" opacity=".55" transform="rotate(${f(T*8)})"/>`;
const _e120iSp=(x,y,s,T,ph,col)=>{const a=.5+.5*Math.sin(T*2.4+ph),z=s*(.55+.45*a);return `<path transform="translate(${x},${y}) scale(${f(z)})" d="M0,-1 Q.14,-.14 1,0 Q.14,.14 0,1 Q-.14,.14 -1,0 Q-.14,-.14 0,-1Z" fill="${col||'#FFE9A0'}" opacity="${f(.45+.55*a)}"/>`};
P.e120_ihero=(o,T,k)=>{const b=(i,a,s=1.5)=>Math.sin(T*s+i)*a;
let ties='';for(let i=-8;i<=8;i++){const x=((i*22+ (T*30)%22));ties+=`<rect x="${f(x-4)}" y="104" width="8" height="10" fill="#6A5238"/>`}
let wins='';for(let i=0;i<4;i++)wins+=`<rect x="${-72+i*34}" y="-14" width="26" height="24" rx="6" fill="#BFE9FF" ${st(C.navy,3.5)}/><path d="M${-68+i*34},-8 l10,-0" ${st('#fff',3)} opacity=".8"/>`;
const wave=(y,ph)=>`M-40,${y} q10,-8 20,0 t20,0 t20,0 t20,0`;
return `<g>${_e120iPlate('e120i_p','#34C3A0','#10282A',T,'#A3F0DC')}
<defs><linearGradient id="e120i_t" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFFFFF"/><stop offset="1" stop-color="#C6D3DF"/></linearGradient>
<linearGradient id="e120i_b" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFFFFF"/><stop offset="1" stop-color="#D9E6F0"/></linearGradient>
<radialGradient id="e120i_l" cx="50%" cy="50%" r="50%"><stop offset="0" stop-color="#FFF3A0" stop-opacity=".9"/><stop offset="1" stop-color="#FFF3A0" stop-opacity="0"/></radialGradient>
<clipPath id="e120i_c1"><circle r="38"/></clipPath><clipPath id="e120i_c2"><circle r="38"/></clipPath><clipPath id="e120i_rail"><rect x="-120" y="90" width="240" height="30"/></clipPath></defs>
${_e120iSp(-112,10,7,T,0)}${_e120iSp(112,6,6,T,2)}${_e120iSp(0,-120,6,T,4)}
<g transform="translate(-84,-70)"><circle r="40" fill="url(#e120i_b)" ${st(C.navy,5)}/><g clip-path="url(#e120i_c1)"><rect x="-40" y="0" width="80" height="40" fill="#2F8FD6"/><g transform="translate(0,${f(-6+b(0,2,1.4))}) rotate(${f(b(1,4,1.3))})"><path d="M-30,2 H30 L22,18 H-22Z" fill="#E0504D" ${st(C.navy,3.5)} stroke-linejoin="round"/><rect x="-16" y="-10" width="30" height="12" fill="#fff" ${st(C.navy,3.5)}/><rect x="-6" y="-22" width="10" height="12" fill="#FFC93C" ${st(C.navy,3.5)}/><circle cx="-8" cy="-4" r="2.5" fill="#7FD0F0"/><circle cx="0" cy="-4" r="2.5" fill="#7FD0F0"/><circle cx="8" cy="-4" r="2.5" fill="#7FD0F0"/></g><path d="M-44,16 q11,-8 22,0 t22,0 t22,0 t22,0" fill="none" stroke="#fff" stroke-width="4" opacity=".8" transform="translate(${f((T*14)%22)},0)"/></g><circle r="40" fill="none" ${st(C.navy,5)}/></g>
<g transform="translate(84,-70)"><circle r="40" fill="url(#e120i_b)" ${st(C.navy,5)}/><g clip-path="url(#e120i_c2)"><rect x="-40" y="22" width="80" height="20" fill="#9AA7B4"/><g transform="translate(0,${f(b(0,1.5,5))})">
${[-22,22].map(x=>`<g transform="translate(${x},14)"><circle r="12" fill="#2B3350" ${st(C.navy,3)}/><circle r="6" fill="#C8D3DB"/><g transform="rotate(${f(-T*220)})"><path d="M-6,0 H6 M0,-6 V6" ${st(C.navy,1.8)}/></g></g>`).join('')}
<path d="M-22,14 L-8,-4 H10 L22,14 M10,-4 L16,-14 H26" fill="none" ${st(C.navy,8)}/><path d="M-22,14 L-8,-4 H10 L22,14 M10,-4 L16,-14 H26" fill="none" ${st('#FF6B6B',3.5)}/><path d="M-8,-4 C-12,-14 4,-16 6,-6Z" fill="#FF6B6B" ${st(C.navy,3.5)}/><rect x="-18" y="-6" width="14" height="6" rx="3" fill="#2B3350"/></g></g><circle r="40" fill="none" ${st(C.navy,5)}/></g>
<g transform="translate(0,${f(-2+b(0,1.8,1.5))})">
<g clip-path="url(#e120i_rail)">${ties}</g><rect x="-120" y="96" width="240" height="6" fill="#B9C6D2" ${st(C.navy,3)}/>
<path d="M-98,-30 H64 C92,-30 106,-6 110,18 L112,70 H-98Z" fill="#000" opacity=".22" transform="translate(5,7)"/>
<path d="M-98,-30 H64 C92,-30 106,-6 110,18 L112,70 H-98Z" fill="url(#e120i_t)" ${st(C.navy,5.5)} stroke-linejoin="round"/>
<path d="M-98,34 H112 V52 H-98Z" fill="#FF8A3D" ${st(C.navy,4)}/><path d="M-98,38 H112" ${st('#FFE066',3)}/>
${wins}<path d="M70,-14 H86 C94,-14 100,-2 102,10 H70Z" fill="#BFE9FF" ${st(C.navy,3.5)} stroke-linejoin="round"/>
<circle cx="104" cy="28" r="${f(18+3*Math.sin(T*3))}" fill="url(#e120i_l)"/><circle cx="104" cy="28" r="5" fill="#FFF3A0" ${st(C.navy,2.5)}/>
${[-70,-28,40,82].map(x=>`<g transform="translate(${x},72)"><circle r="14" fill="#2B3350" ${st(C.navy,4)}/><circle r="6" fill="#C8D3DB"/><g transform="rotate(${f(T*140)})"><path d="M-6,0 H6" ${st(C.navy,2)}/></g></g>`).join('')}
</g></g>`};

/* A2 ep 20 props end */
/* A2 ep 21 props begin */
/* Episode 121 props (A2 ep21): animals — spiders, insects, frogs, monkeys, bears, fish, farm. All animals are FACELESS bodies (no eyes, no mouths). Uses C, st, f, ease, clamp, P. */
const _e121SK='#E3AE82';
const _e121sh=(x,y,rx)=>`<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${f(rx*.13)}" fill="#000" opacity=".15"/>`;
const _e121frame=(id,W,H,inner,r)=>`<clipPath id="e121_c${id}"><rect x="${-W/2}" y="${-H/2}" width="${W}" height="${H}" rx="${r||26}"/></clipPath><g clip-path="url(#e121_c${id})">${inner}</g><rect x="${-W/2}" y="${-H/2}" width="${W}" height="${H}" rx="${r||26}" fill="none" ${st(C.navy,6)}/>`;
const _e121num=(x,y,n,p)=>p>0?`<g transform="translate(${x},${y}) scale(${f(p)})"><circle r="13" fill="${C.gold}" ${st(C.navy,3)}/><text x="0" y="6" text-anchor="middle" font-family="Fraunces" font-weight="900" font-size="17" fill="${C.navy}">${n}</text></g>`:'';
/* ---------- spider: body + 8 legs, no eyes ---------- */
const _e121legs=[[[36,-54],[62,-34]],[[46,-36],[74,-8]],[[46,-6],[72,28]],[[38,16],[58,56]]];
const _e121spider=(T,o)=>{o=o||{};const col=o.c||'#2A2230',w=o.fast?9:2.2;let L='',nums='';let n=0;
  [-1,1].forEach(sd=>_e121legs.forEach(([kn,tp],i)=>{const wg=Math.sin(T*(o.fast?14:5)+i*1.3+sd)*w;
    const d=`M${sd*10} ${-24+i*9} L${sd*kn[0]} ${f(kn[1]+wg)} L${sd*tp[0]} ${f(tp[1]+wg*1.5)}`;
    L+=`<path d="${d}" fill="none" ${st(C.navy,9)}/><path d="${d}" fill="none" ${st(col,5)}/>`;
    if(o.num){n++;const p=ease(((o.k||0)-.3-(n-1)*.34)/.25);nums+=_e121num(sd*tp[0]*1.12,tp[1]*1.1,n,p)}}));
  return `<g>${L}<ellipse cx="0" cy="16" rx="30" ry="38" fill="${col}" ${st()}/><path d="M-14 -4 Q-4 -12 -2 0" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round" opacity=".28"/><path d="M0 6 L0 30" stroke="#8A6A9A" stroke-width="4" stroke-linecap="round" opacity=".7"/><circle cx="0" cy="-24" r="17" fill="${col}" ${st()}/>${nums}</g>`};
P.e121_spider=(o,T,k)=>{const s=o.s||1,hang=o.hang;let th='';
  if(hang){const y=Math.sin(T*1.6)*12;return `<g><path d="M0 -150 V${f(-30+y)}" ${st('#fff',3)}/><g transform="translate(0,${f(y+30)}) scale(${s*.8})">${_e121spider(T,o)}</g></g>`}
  return `<g>${o.shadow===0?'':_e121sh(0,64*s,70*s)}<g transform="scale(${s})">${_e121spider(T,Object.assign({k},o))}</g></g>`};
/* ---------- insects (six legs) ---------- */
const _e121leg6=(T,o,sp,hw,ys)=>{hw=hw||26;ys=ys||[-14,12,38];let L='',n=0;
  [-1,1].forEach(sd=>[[hw+34,-28],[hw+42,4],[hw+32,32]].forEach(([tx,dy],i)=>{const y=ys[i],wg=Math.sin(T*6+i*2+sd)*2;
    const d=`M${sd*hw*.6} ${y} L${sd*(hw+18)} ${f(y-12+wg)} L${sd*tx} ${f(y+dy+wg*1.5)}`;L+=`<path d="${d}" fill="none" ${st(C.navy,8)}/><path d="${d}" fill="none" ${st(sp||'#3A2A22',4)}/>`;
    if(o.num){n++;const p=ease(((o.k||0)-.3-(n-1)*.4)/.25);L+=_e121num(sd*(tx+14),y+dy+(dy>0?6:-6),n,p)}}));return L};
const _e121insect=(T,o)=>{const k=o.v||'beetle',fl=Math.sin(T*18)*6;
  if(k==='butterfly')return `<g transform="rotate(${f(Math.sin(T*1.5)*5)})"><g transform="scale(${f(1+Math.sin(T*9)*.08)},1)"><path d="M0 -6 Q-54 -78 -78 -28 Q-80 14 0 6Z" fill="#F2994A" ${st()}/><path d="M0 -6 Q54 -78 78 -28 Q80 14 0 6Z" fill="#F2994A" ${st()}/><path d="M0 6 Q-62 14 -52 56 Q-14 62 0 12Z" fill="#E5493F" ${st()}/><path d="M0 6 Q62 14 52 56 Q14 62 0 12Z" fill="#E5493F" ${st()}/><circle cx="-48" cy="-22" r="10" fill="#fff" opacity=".85"/><circle cx="48" cy="-22" r="10" fill="#fff" opacity=".85"/></g><rect x="-6" y="-26" width="12" height="70" rx="6" fill="${C.navy2}" ${st()}/><path d="M-3 -26 Q-16 -52 -28 -50 M3 -26 Q16 -52 28 -50" fill="none" ${st(C.navy,3.5)}/></g>`;
  if(k==='bee')return `<g><ellipse cx="-22" cy="-28" rx="22" ry="12" fill="#DDEEF8" ${st(C.navy,3)} opacity=".85" transform="rotate(${f(-30+fl)} -10 -14)"/><ellipse cx="22" cy="-28" rx="22" ry="12" fill="#DDEEF8" ${st(C.navy,3)} opacity=".85" transform="rotate(${f(30-fl)} 10 -14)"/>${_e121leg6(T,o,'#3A2A22',22)}<ellipse cx="0" cy="8" rx="26" ry="38" fill="#F6CE4B" ${st()}/><path d="M-24 0 Q0 8 24 0 M-26 18 Q0 28 26 18" fill="none" ${st(C.navy,8)}/><circle cx="0" cy="-34" r="14" fill="${C.navy2}" ${st()}/></g>`;
  if(k==='ladybird')return `<g>${_e121leg6(T,o,'#3A2A22',34,[-10,14,38])}<ellipse cx="0" cy="8" rx="38" ry="44" fill="${C.red}" ${st()}/><path d="M0 -34 V52" ${st(C.navy,4)}/>${[[-18,-8],[18,-8],[-20,24],[20,24],[-8,44],[8,44]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="7" fill="${C.navy}"/>`).join('')}<path d="M-20 -32 A20 20 0 0 1 20 -32 Z" fill="${C.navy}" ${st(C.navy,4)}/></g>`;
  if(k==='ant')return `<g transform="rotate(90)">${_e121leg6(T,o,'#5A3C2A',9,[-14,-4,6])}<ellipse cx="0" cy="-34" rx="14" ry="12" fill="#5A3C2A" ${st()}/><ellipse cx="0" cy="-6" rx="12" ry="14" fill="#5A3C2A" ${st()}/><ellipse cx="0" cy="34" rx="22" ry="26" fill="#5A3C2A" ${st()}/><path d="M-5 -44 Q-14 -66 -28 -64 M5 -44 Q14 -66 28 -64" fill="none" ${st(C.navy,3.5)}/></g>`;
  if(k==='fly')return `<g><ellipse cx="-26" cy="-8" rx="30" ry="14" fill="#DDEEF8" ${st(C.navy,3)} opacity=".85" transform="rotate(${f(-40+fl)} -8 0)"/><ellipse cx="26" cy="-8" rx="30" ry="14" fill="#DDEEF8" ${st(C.navy,3)} opacity=".85" transform="rotate(${f(40-fl)} 8 0)"/>${_e121leg6(T,o,'#2B3D48',14,[-10,10,30])}<ellipse cx="0" cy="14" rx="18" ry="30" fill="#2B3D48" ${st()}/><circle cx="0" cy="-22" r="13" fill="#2B3D48" ${st()}/></g>`;
  if(k==='dragonfly')return `<g><g opacity=".9"><ellipse cx="-34" cy="-30" rx="34" ry="9" fill="#CFEAF6" ${st(C.navy,3)} transform="rotate(${f(-10+fl)} -4 -30)"/><ellipse cx="34" cy="-30" rx="34" ry="9" fill="#CFEAF6" ${st(C.navy,3)} transform="rotate(${f(10-fl)} 4 -30)"/><ellipse cx="-30" cy="-10" rx="30" ry="8" fill="#CFEAF6" ${st(C.navy,3)} transform="rotate(${f(6-fl)} -4 -10)"/><ellipse cx="30" cy="-10" rx="30" ry="8" fill="#CFEAF6" ${st(C.navy,3)} transform="rotate(${f(-6+fl)} 4 -10)"/></g><rect x="-7" y="-52" width="14" height="116" rx="7" fill="#2FA6B8" ${st()}/><circle cx="0" cy="-52" r="12" fill="#2FA6B8" ${st()}/></g>`;
  return `<g>${_e121leg6(T,o,'#3A2A22',28)}<ellipse cx="0" cy="12" rx="32" ry="42" fill="${o.c||'#3F8F6A'}" ${st()}/><path d="M0 -26 V54" ${st(C.navy,4)}/><path d="M-18 -4 q-4 20 4 40" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round" opacity=".35"/><circle cx="0" cy="-34" r="14" fill="#2B3D48" ${st()}/><path d="M-5 -44 Q-12 -62 -24 -60 M5 -44 Q12 -62 24 -60" fill="none" ${st(C.navy,3.5)}/></g>`};
P.e121_insect=(o,T,k)=>`<g>${_e121sh(0,60,56)}<g transform="scale(${o.s||1.1})">${_e121insect(T,Object.assign({k},o))}</g></g>`;
/* many kinds of insects */
P.e121_insects=(o,T)=>{const ks=['beetle','ladybird','bee','butterfly','ant','fly','dragonfly','beetle','bee','ladybird','butterfly','ant'],n=o.n||9;let s='';
  for(let i=0;i<n;i++){const x=-96+(i%3)*96,y=-78+Math.floor(i/3)*78;s+=`<g transform="translate(${x},${y+Math.sin(T*1.8+i)*3}) scale(.42) rotate(${(i*47)%40-20})">${_e121insect(T,{v:ks[i],c:['#3F8F6A','#4DA3D8','#8E6BB5'][i%3]})}</g>`}return `<g>${s}</g>`};
/* spider vs insect with leg counts */
P.e121_legs=(o,T,k)=>`<g><g transform="translate(-100,-4) scale(.56)">${_e121spider(T,{num:1,k})}</g><g transform="translate(106,0) scale(.82)">${_e121insect(T,{v:'beetle',num:o.n6===0?0:1,k:k-(o.delay||0)})}</g></g>`;

/* ---------- frog (side view, faces right) — no eyes, no mouth ---------- */
const _e121frog=(T,o)=>{o=o||{};const c=o.c||'#6FB25A',dk=o.dk||'#4C8F46',lt=o.lt||'#CDE8A8',hop=o.hop?Math.max(0,Math.sin(T*5))*-14:0,th=1+Math.sin(T*4)*.12;
  return `<g transform="translate(0,${f(hop)})"><path d="M-4 54 Q40 58 64 56" fill="none" ${st(C.navy,0)}/><path d="M24 30 L34 56 H54 Q60 58 54 62 H28 Q22 62 20 54Z" fill="${c}" ${st()}/><ellipse cx="2" cy="12" rx="58" ry="38" fill="${c}" ${st()}/><path d="M-50 22 Q-8 50 52 24 Q40 44 0 50 Q-34 48 -50 22Z" fill="${lt}"/><ellipse cx="44" cy="-6" rx="30" ry="24" fill="${c}" ${st()}/><path d="M32 -22 Q48 -26 60 -16" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round" opacity=".4"/>${[[-20,-8,8],[2,-14,7],[-34,10,6],[-8,8,5]].map(([x,y,r])=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${dk}"/>`).join('')}<path d="M-54 34 Q-62 8 -26 8 Q4 8 14 36 Q2 56 -26 56 Q-48 56 -54 34Z" fill="${c}" ${st()}/><path d="M-38 54 L-70 60 Q-96 62 -84 70 L-44 70 L-10 62" fill="${c}" ${st()}/><path d="M-30 22 Q-18 14 -2 22" fill="none" stroke="${dk}" stroke-width="5" stroke-linecap="round" opacity=".6"/></g>`};
P.e121_frog=(o,T)=>`<g>${_e121sh(0,66,92)}<g transform="scale(${o.s||1})">${_e121frog(T,o)}</g></g>`;
/* many frogs after rain, in a field. o.many: count; o.circle */
P.e121_frogs=(o,T,k)=>{const n=o.n||7,cols=[['#6FB25A','#4C8F46'],['#8B6B43','#6A4E2E'],['#7DB86A','#5A9650']];let s='';
  const pos=o.circle?[...Array(7).keys()].map(i=>[Math.cos(i/7*Math.PI*2)*70,Math.sin(i/7*Math.PI*2)*28+30,Math.cos(i/7*Math.PI*2)>0?1:-1]):[[-84,40,1],[-30,56,-1],[30,42,1],[88,58,-1],[-70,-4,-1],[-6,8,1],[62,-6,-1],[-40,-40,1],[28,-40,-1],[90,-30,1]];
  for(let i=0;i<Math.min(n,pos.length);i++){const [x,y,d]=pos[i],cc=cols[i%3],p=ease((k-i*.08)/.3),sc=(o.circle?.38:.34+((i*7)%3)*.06);s+=`<g transform="translate(${x},${y+(1-p)*-10}) scale(${f(d*sc*p)},${f(sc*p)})">${_e121frog(T+i,{c:cc[0],dk:cc[1],hop:i%3===0})}</g>`}
  const rain=o.rain?[...Array(12).keys()].map(i=>`<line x1="${-110+i*20}" y1="${f(-100+((T*220+i*47)%240))}" x2="${-116+i*20}" y2="${f(-80+((T*220+i*47)%240))}" ${st(C.blue,3)} opacity=".7"/>`).join(''):'';
  let tk='';if(o.talk){tk=[[-80,-30],[10,-62],[88,-28],[-30,-66]].map(([x,y],i)=>{const p=ease(((k||0)-.3-i*.25)/.3),w=Math.sin(T*3+i)*3;return `<g transform="translate(${x},${f(y+w)}) scale(${f(p)})"><path d="M-22 -14 H22 Q30 -14 30 -6 V10 Q30 18 22 18 H4 L-6 32 L-8 18 H-22 Q-30 18 -30 10 V-6 Q-30 -14 -22 -14Z" fill="#fff" ${st(C.navy,3.5)}/><circle cx="-12" cy="2" r="3.2" fill="${C.navy}"/><circle cx="0" cy="2" r="3.2" fill="${C.navy}"/><circle cx="12" cy="2" r="3.2" fill="${C.navy}"/></g>`}).join('')}
  return `<g><ellipse cx="0" cy="40" rx="130" ry="62" fill="#8EBE7E" ${st()}/>${s}${rain}${tk}</g>`};
P.e121_waterglass=(o,T)=>`<g>${_e121sh(0,100,60)}<path d="M-50 -80 H50 L40 96 Q38 102 30 102 H-30 Q-38 102 -40 96Z" fill="#DDF0F8" opacity=".9" ${st()}/><path d="M-46 -30 Q0 -22 46 -30 L40 92 Q38 98 30 98 H-30 Q-36 98 -38 92Z" fill="#7FC4E8"/><path d="M-36 -64 L-30 80" stroke="#fff" stroke-width="7" stroke-linecap="round" opacity=".8"/><path d="M-36 -22 q12 -6 24 0 t24 0 t24 0" fill="none" stroke="#fff" stroke-width="3" opacity=".8"/></g>`;
P.e121_frogcol=(o,T)=>`<g><g transform="translate(-76,6) scale(.62)">${_e121frog(T,{c:'#6FB25A',dk:'#4C8F46'})}</g><path d="M-14 0 h30 m-10 -9 l10 9 l-10 9" fill="none" ${st(C.navy,5)}/><g transform="translate(78,6) scale(.62)">${_e121frog(T,{c:'#8B6B43',dk:'#6A4E2E',lt:'#D9C39A'})}</g></g>`;
/* frog drinking through its skin: sits in water, arrows go into the skin */
P.e121_skin=(o,T)=>{let ar='';for(let i=0;i<4;i++){const ph=(T*.8+i/4)%1,x=-40+i*28;ar+=`<path d="M${x} ${f(70-ph*34)} v-14 m-6 6 l6 -8 l6 8" fill="none" ${st(C.blue,4.5)} opacity="${f(Math.sin(ph*Math.PI))}"/>`}
  return `<g><g transform="translate(0,-14) scale(.9)">${_e121frog(T,{})}</g><path d="M-120 44 Q-90 36 -60 44 T0 44 T60 44 T120 44 V100 H-120Z" fill="#4DA3D8" opacity=".92" ${st()}/>${ar}</g>`};
P.e121_frogstone=(o,T)=>`<g><ellipse cx="0" cy="76" rx="90" ry="22" fill="#9AA6AD" ${st()}/><path d="M-72 76 Q-70 38 -20 32 Q40 30 72 76Z" fill="#B7C1C7" ${st()}/><g transform="translate(-4,-6) scale(.7)">${_e121frog(T,{})}</g></g>`;
/* ---------- moon over a field (the favourite photo) ---------- */
const _e121moonin=(T,W,H,o,k)=>{o=o||{};const hw=W/2,hh=H/2,mr=H*.22,rise=ease((k||9)/3),my=o.set?-hh*.15:-hh*.05-rise*hh*.28+(o.low?hh*.3:0),y1=hh*.14,y2=hh*.52;let sts='';for(let i=0;i<18;i++)sts+=`<circle cx="${((i*53)%W)-hw}" cy="${-hh+6+(i*29)%(H*.42)}" r="${1.4+i%3*.5}" fill="#FFF3C4" opacity=".7"/>`;
  const tf=Math.max(.34,H/214*.5);
  return `<rect x="${-hw}" y="${-hh}" width="${W}" height="${H}" fill="#1B2547"/>${sts}<circle cx="0" cy="${f(my)}" r="${f(mr)}" fill="#F7F3E0" ${st('#C9B260',3)}/><circle cx="${f(-mr*.3)}" cy="${f(my-mr*.2)}" r="${f(mr*.18)}" fill="#E6DFC0"/><circle cx="${f(mr*.32)}" cy="${f(my+mr*.3)}" r="${f(mr*.12)}" fill="#E6DFC0"/><path d="M${-hw} ${f(y1)} Q${-hw/2} ${f(y1-16)} 0 ${f(y1)} T${hw} ${f(y1-4)} V${hh} H${-hw}Z" fill="#3E6B4A" ${st(C.navy,3)}/><path d="M${-hw} ${f(y2)} Q${-hw/2} ${f(y2-14)} 0 ${f(y2)} T${hw} ${f(y2-4)} V${hh} H${-hw}Z" fill="#2F5A3D" ${st(C.navy,3)}/>${[-.78,-.48,-.2,.2,.5,.78].map(x=>`<path d="M${f(x*hw)} ${f(y2)} v-14 m-6 6 l6 -8 l6 8" fill="none" ${st('#6FB25A',4)}/>`).join('')}${o.frog===0?'':`<g transform="translate(${f(-W*.02)},${f(hh*.62)}) scale(${f(tf)})"><ellipse cx="0" cy="48" rx="80" ry="20" fill="#9AA6AD" ${st()}/><path d="M-60 48 Q-56 22 -10 18 Q36 16 60 48Z" fill="#B7C1C7" ${st()}/><g transform="translate(-8,-14)">${_e121frog(T,{})}</g></g>`}`};
P.e121_moonfield=(o,T,k)=>{const cam=o.cam?`<g fill="none" ${st('#fff',5)}><path d="M-108 -70 v-24 h24 M108 -70 v-24 h-24 M-108 70 v24 h24 M108 70 v24 h-24"/></g><circle cx="0" cy="-8" r="16" fill="none" stroke="#fff" stroke-width="3" opacity=".7"/>`:'';
  return `<g>${_e121frame('mf'+(o.set?'s':'')+(o.frog===0?'n':'')+(o.low?'l':''),250,214,_e121moonin(T,250,214,o,k)+cam,26)}</g>`};
/* a phone showing the moon photo as its background */
P.e121_phonebg=(o,T,k)=>`<g><rect x="-66" y="-120" width="132" height="240" rx="26" fill="${C.navy}" ${st()}/><clipPath id="e121_pb"><rect x="-56" y="-104" width="112" height="208" rx="14"/></clipPath><g clip-path="url(#e121_pb)"><g transform="scale(1)">${_e121moonin(T,112,208,{},9)}</g></g><rect x="-18" y="-114" width="36" height="6" rx="3" fill="#000" opacity=".5"/></g>`;
/* ---------- monkey — faceless: head disc + ears, no features ---------- */
const _e121monkey=(T,o)=>{o=o||{};const c=o.c||'#8B6B43',lt=o.lt||'#D9B98C',b=o.baby?.72:1,sw=Math.sin(T*2)*4;
  const tail=`<path d="M30 56 Q80 70 74 20 Q70 -6 90 -14" fill="none" ${st(C.navy,12)}/><path d="M30 56 Q80 70 74 20 Q70 -6 90 -14" fill="none" ${st(c,7)}/>`;
  let hair='';if(o.baby)hair=`<path d="M-14 -62 q-12 -22 6 -26 q18 -2 8 16 q16 -22 28 -4 q6 18 -14 14" fill="none" ${st(C.navy,12)}/><path d="M-14 -62 q-12 -22 6 -26 q18 -2 8 16 q16 -22 28 -4 q6 18 -14 14" fill="none" ${st('#3A2A22',6)}/>`;
  const hold=o.hold==='chips'?`<g transform="translate(-58,10) rotate(-14)">${P.e121_chips({},T)}</g>`:'';
  return `<g transform="scale(${b})">${tail}<ellipse cx="0" cy="26" rx="38" ry="46" fill="${c}" ${st()}/><ellipse cx="0" cy="34" rx="22" ry="30" fill="${lt}"/><path d="M-34 6 Q-62 20 -50 52" fill="none" ${st(C.navy,16)}/><path d="M-34 6 Q-62 20 -50 52" fill="none" ${st(c,10)}/><path d="M34 6 Q60 ${f(14+sw)} 52 ${f(44+sw)}" fill="none" ${st(C.navy,16)}/><path d="M34 6 Q60 ${f(14+sw)} 52 ${f(44+sw)}" fill="none" ${st(c,10)}/><ellipse cx="-20" cy="72" rx="20" ry="10" fill="${c}" ${st()}/><ellipse cx="20" cy="72" rx="20" ry="10" fill="${c}" ${st()}/><circle cx="-30" cy="-42" r="12" fill="${c}" ${st()}/><circle cx="30" cy="-42" r="12" fill="${c}" ${st()}/><circle cx="-30" cy="-42" r="5" fill="${lt}"/><circle cx="30" cy="-42" r="5" fill="${lt}"/><circle cx="0" cy="-34" r="30" fill="${c}" ${st()}/><path d="M-16 -50 Q-4 -58 10 -54" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round" opacity=".3"/>${hair}${hold}</g>`};
P.e121_monkey=(o,T)=>`<g>${_e121sh(0,80,70)}<g transform="scale(${o.s||1})">${_e121monkey(T,o)}</g></g>`;
P.e121_chips=(o,T)=>`<g><path d="M-26 -34 L26 -34 L22 34 L-22 34Z" fill="#E5493F" ${st()}/><path d="M-30 -34 q6 -10 12 0 q6 -10 12 0 q6 -10 12 0 q6 -10 12 0 q6 -10 12 0" fill="#E5493F" ${st()}/><circle cx="0" cy="0" r="12" fill="#F6CE4B" ${st(C.navy,3)}/><path d="M-26 20 H26" ${st('#fff',3)} opacity=".7"/></g>`;
/* ---------- bear — faceless ---------- */
