/* laptop whose background is a monkey picture */
P.e121_laptop=(o,T,k)=>`<g>${_e121sh(0,98,120)}<rect x="-100" y="-80" width="200" height="140" rx="12" fill="${C.navy}" ${st()}/><clipPath id="e121_lp"><rect x="-90" y="-70" width="180" height="120" rx="4"/></clipPath><g clip-path="url(#e121_lp)"><rect x="-90" y="-70" width="180" height="120" fill="#CDEBF7"/><rect x="-90" y="20" width="180" height="30" fill="#8EC47A"/><g transform="translate(-20,24) scale(.5)">${_e121monkey(T,{baby:1})}</g><g transform="translate(46,30) scale(.46)">${_e121monkey(T,{c:'#9AA3A8',lt:'#D5DADD'})}</g></g><path d="M-122 64 H122 L106 84 H-106Z" fill="#B8C4CC" ${st()}/><rect x="-22" y="68" width="44" height="6" rx="3" fill="#8A97A0"/></g>`;

/* ================= FISH ================= */
const _e121fish=(T,o)=>{o=o||{};const c=o.c||'#4DA3D8',lt=o.lt||'#CDE8F4',tw=Math.sin(T*5+(o.ph||0))*7;
  return `<g><path d="M-52 0 L-86 ${f(-28+tw)} Q-76 0 -86 ${f(28+tw)}Z" fill="${c}" ${st()}/><path d="M-12 -34 Q10 -62 34 -34Z" fill="${c}" ${st(C.navy,4)}/><path d="M-6 30 Q10 52 24 30Z" fill="${c}" ${st(C.navy,4)}/><ellipse cx="0" cy="0" rx="62" ry="36" fill="${c}" ${st()}/><path d="M-40 10 Q0 40 56 10 Q30 30 0 34 Q-30 32 -40 10Z" fill="${lt}"/><path d="M34 -22 Q44 0 34 22" fill="none" ${st(C.navy,4)}/><path d="M-30 -18 Q-20 0 -30 18 M-12 -22 Q-2 0 -12 22" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round" opacity=".45"/></g>`};
