P.e121_parkgate=(o,T)=>{const inner=`<rect x="-125" y="-107" width="250" height="214" fill="#CDEBF7"/>${_e121tree(-96,30,.7,0)}${_e121tree(100,34,.6,0)}<rect x="-125" y="50" width="250" height="57" fill="#A8A29A"/><rect x="-125" y="42" width="250" height="10" fill="#8EC47A"/><rect x="-84" y="-60" width="14" height="108" fill="#7A5236" ${st(C.navy,4)}/><rect x="6" y="-60" width="14" height="108" fill="#7A5236" ${st(C.navy,4)}/><rect x="-96" y="-82" width="128" height="36" rx="8" fill="#FFF3C4" ${st(C.navy,4)}/>${_e121txt(-32,-67,'WILD',17)}${_e121txt(-32,-52,'ANIMAL PARK',13,C.navy)}<g transform="translate(70,26) scale(.5)">${P.person({c:'#8A9A5B',hair:'short',hc:'#3A2A22'},T)}</g><path d="M42 -34 h20 v-14 h12" opacity="0"/>`;
  return `<g>${_e121frame('pg',250,214,inner,22)}</g>`};
