/* bear sleeping through the cold winter */
P.e121_bearwinter=(o,T)=>{const inner=`<rect x="-125" y="-107" width="250" height="214" fill="#2B3A66"/>${[...Array(16).keys()].map(i=>`<circle cx="${f(((i*53)%250)-125)}" cy="${f(-100+((T*14+i*37)%200))}" r="${2+i%3}" fill="#fff" opacity=".85"/>`).join('')}<path d="M-125 30 Q-60 6 0 24 T125 18 V107 H-125Z" fill="#EAF3F8" ${st(C.navy,3)}/><path d="M-60 80 Q-60 6 10 6 Q80 6 80 80Z" fill="#6A5A4A" ${st()}/><path d="M-40 80 Q-40 26 10 26 Q60 26 60 80Z" fill="#2A2018"/><g transform="translate(10,60) scale(.36)">${_e121bear(T,{pose:'sleep'})}</g>${[-100,100].map(x=>`<g transform="translate(${x},56)"><rect x="-5" y="0" width="10" height="34" fill="#7A5236"/><path d="M0 -50 L-30 10 H30Z M0 -22 L-38 34 H38Z" fill="#3E7A4C" ${st(C.navy,3)}/><path d="M-12 -14 q12 -8 24 0 M-18 14 q18 -10 36 0" fill="none" stroke="#fff" stroke-width="5" opacity=".9"/></g>`).join('')}`;
  return `<g>${_e121frame('bw',250,214,inner,22)}</g>`};
/* monkeys everywhere: trees + ground + roofs. n shown */
P.e121_monkeys=(o,T,k)=>{const sp=[[-84,-14,.3,0],[-20,-34,.28,1],[70,-6,.3,2],[-96,66,.34,1],[-34,70,.3,0],[26,76,.36,1],[90,70,.3,2],[28,-22,.26,0],[-58,24,.26,2],[8,22,.26,1]];
  const cols=[['#8B6B43','#D9B98C'],['#9AA3A8','#D5DADD'],['#7A5A3A','#D9B98C']];let ms='';
  for(let i=0;i<Math.min(o.n||10,sp.length);i++){const [x,y,sc,c]=sp[i],p=ease(((k||0)-i*.1)/.3);ms+=`<g transform="translate(${x},${f(y+Math.sin(T*2+i)*2)}) scale(${f(sc*p)})">${_e121monkey(T+i,{c:cols[c][0],lt:cols[c][1]})}</g>`}
  const inner=`<rect x="-125" y="-107" width="250" height="214" fill="#CDEBF7"/><rect x="-125" y="48" width="250" height="59" fill="#8EC47A"/>${_e121tree(-86,34,.9,0)}${_e121tree(92,38,.8,0)}${ms}`;
  return `<g>${_e121frame('ms',250,214,inner,22)}</g>`};

/* ================= NIGHT, MOON, LAMP ================= */
const _e121bird=(T,o)=>{o=o||{};const c=o.c||'#8A97A0',fl=Math.sin(T*8)*(o.fly?16:0);
  return `<g><path d="M-44 0 L-86 ${f(-12+fl*.3)} L-82 ${f(10+fl*.3)}Z" fill="${c}" ${st(C.navy,4)}/><ellipse cx="-6" cy="8" rx="46" ry="32" fill="${c}" ${st()}/><circle cx="34" cy="-18" r="22" fill="${c}" ${st()}/><path d="M54 -22 L76 -14 L54 -8Z" fill="#F2994A" ${st(C.navy,3.5)}/><path d="M-34 10 Q-8 -26 24 8 Q-2 28 -34 10Z" fill="#fff" opacity=".4" ${st(C.navy,3)}/><path d="M-14 38 l-4 20 M6 38 l-2 20" ${st(C.navy,4)}/><ellipse cx="2" cy="22" rx="26" ry="14" fill="#fff" opacity=".25"/></g>`};
P.e121_bird=(o,T)=>`<g>${_e121sh(0,66,70)}<g transform="scale(${o.s||1.3})">${_e121bird(T,o)}</g></g>`;
/* cat seen from behind: ears + tail only */
const _e121catback=(T,o)=>`<g><path d="M30 60 Q80 56 70 6 Q66 -14 82 -22" fill="none" ${st(C.navy,16)}/><path d="M30 60 Q80 56 70 6 Q66 -14 82 -22" fill="none" ${st((o&&o.c)||'#E08A3C',9)}/><path d="M-42 64 Q-52 -8 0 -12 Q52 -8 42 64Z" fill="${(o&&o.c)||'#E08A3C'}" ${st()}/><path d="M-26 -34 L-22 -64 L-4 -44Z M26 -34 L22 -64 L4 -44Z" fill="${(o&&o.c)||'#E08A3C'}" ${st()}/><circle cx="0" cy="-26" r="28" fill="${(o&&o.c)||'#E08A3C'}" ${st()}/><path d="M-12 -60 L-18 -50 M12 -60 L18 -50" opacity="0"/><path d="M-14 10 q14 -8 28 0" fill="none" stroke="#fff" stroke-width="4" opacity=".4" stroke-linecap="round"/></g>`;
P.e121_waterbowl=(o,T,k)=>{const sun=`<circle cx="76" cy="-70" r="26" fill="#FFD84A" ${st('#E5A93A',3)}/>${[...Array(8).keys()].map(i=>`<line x1="76" y1="-106" x2="76" y2="-114" transform="rotate(${i*45} 76 -70)" ${st('#E5A93A',4)}/>`).join('')}`;
  const bowl=`<g transform="translate(0,48)"><ellipse cx="0" cy="38" rx="86" ry="14" fill="#000" opacity=".15"/><path d="M-76 0 H76 Q70 44 0 48 Q-70 44 -76 0Z" fill="#4DA3D8" ${st()}/><ellipse cx="0" cy="0" rx="76" ry="14" fill="#8CCBE9" ${st()}/><path d="M-44 4 q10 -5 20 0 t20 0 t20 0" fill="none" stroke="#fff" stroke-width="3" opacity=".8"/></g>`;
  return `<g>${sun}<g transform="translate(-70,10) scale(.58)">${_e121bird(T,{})}</g><g transform="translate(86,28) scale(.56)">${_e121catback(T,{})}</g>${bowl}</g>`};
/* an outdoor lamp over a door; insects fly round and round it */
P.e121_doorlamp=(o,T)=>{const ks=['bee','butterfly','beetle','fly','ladybird','dragonfly','bee','fly'];let ins='';
  for(let i=0;i<(o.n||8);i++){const a=T*(1.2+(i%3)*.25)+i*0.8,r=58+(i%3)*20;ins+=`<g transform="translate(${f(Math.cos(a)*r)},${f(-60+Math.sin(a)*r*.7)}) scale(${f(.22+.05*(i%2))}) rotate(${f(a*57.3+90)})">${_e121insect(T+i,{v:ks[i%ks.length]})}</g>`}
  return `<g><rect x="-126" y="-130" width="252" height="250" rx="22" fill="#27345E" ${st()}/><rect x="-44" y="-8" width="88" height="128" rx="8" fill="#8A5A36" ${st()}/><circle cx="30" cy="60" r="5" fill="${C.gold}"/><path d="M-30 20 H30 M-30 60 H30" ${st('#5A3A22',3)} opacity=".6"/><rect x="-12" y="-76" width="24" height="10" fill="#7A5236" ${st()}/><circle cx="0" cy="-60" r="66" fill="#FFE27A" opacity=".4"/><path d="M-14 -68 Q-14 -92 0 -92 Q14 -92 14 -68Z" fill="#FFF3C4" ${st(C.navy,4)}/><ellipse cx="0" cy="-66" rx="14" ry="6" fill="#FFE27A" ${st(C.navy,3)}/>${ins}</g>`};
/* moon phases: full circle, half circle, thin curly crescent. o.v = 'full'|'half'|'thin' or all three */
const _e121phase=(v,x)=>{const mc='#F7F3E0';let sh;
  if(v==='full')sh=`<circle r="40" fill="${mc}" ${st('#C9B260',4)}/><circle cx="-12" cy="-10" r="7" fill="#E6DFC0"/><circle cx="12" cy="14" r="5" fill="#E6DFC0"/>`;
  else if(v==='half')sh=`<circle r="40" fill="#2F3A66" ${st('#C9B260',4)}/><path d="M0 -40 A40 40 0 0 1 0 40Z" fill="${mc}"/><circle r="40" fill="none" ${st('#C9B260',4)}/>`;
  else sh=`<path d="M6 -40 A40 40 0 0 0 6 40 A26 40 0 0 1 6 -40Z" fill="${mc}" stroke="#C9B260" stroke-width="4" stroke-linejoin="round"/>`;
  return `<g transform="translate(${x},0)">${sh}</g>`};
P.e121_moonphases=(o,T)=>{const v=o.v;if(v)return `<g transform="scale(2.2)">${_e121phase(v,0)}</g>`;
  return `<g><rect x="-132" y="-70" width="264" height="140" rx="28" fill="#1B2547" ${st()}/><g transform="translate(0,-4)">${_e121phase('full',-84)}${_e121phase('half',0)}${_e121phase('thin',84)}</g></g>`};
/* the moon rises: big orange near the ground, then smaller and whiter higher up */
P.e121_moonrise=(o,T,k)=>{const p=o.v==='orange'?0:o.v==='white'?1:ease(((k||0)-.3)/5);
  const y=70-p*150,r=44-p*20,mix=(a,b)=>Math.round(a+(b-a)*p),col=`rgb(${mix(245,247)},${mix(150,243)},${mix(60,224)})`;
  const inner=`<rect x="-125" y="-107" width="250" height="214" fill="#1B2547"/>${[...Array(14).keys()].map(i=>`<circle cx="${(i*47)%240-120}" cy="${-100+(i*31)%110}" r="${1.4+i%3*.5}" fill="#FFF3C4" opacity=".8"/>`).join('')}<circle cx="0" cy="${f(y)}" r="${f(r)}" fill="${col}" ${st('#C98A3B',3)}/><path d="M-125 56 Q-60 36 0 56 T125 50 V107 H-125Z" fill="#26492F" ${st(C.navy,3)}/>${o.v?'':`<path d="M92 50 V-56 m-10 14 l10 -16 l10 16" fill="none" ${st('#fff',5)} opacity=".7"/>`}`;
  return `<g>${_e121frame('mr'+(o.v||'a'),250,214,inner,22)}</g>`};
/* small glints in dark bushes (night sounds) — sparkles, not eyes */
P.e121_bushglints=(o,T,k)=>{const bush=(x,y,s)=>`<g transform="translate(${x},${y}) scale(${s})"><circle cx="-34" cy="0" r="34" fill="#1F3F2A" ${st(C.navy,3)}/><circle cx="34" cy="2" r="32" fill="#1F3F2A" ${st(C.navy,3)}/><circle cx="0" cy="-18" r="40" fill="#26492F" ${st(C.navy,3)}/></g>`;
  const gl=[[-96,40],[10,34],[80,60],[-30,66]].map(([x,y],i)=>`<g transform="translate(${x},${y}) scale(${f(.55+.35*Math.sin(T*3+i*1.7))})"><polygon points="0,-12 3,-3 12,0 3,3 0,12 -3,3 -12,0 -3,-3" fill="${C.gold}"/></g>`).join('');
  const inner=`<rect x="-125" y="-107" width="250" height="214" fill="#1B2547"/><circle cx="70" cy="-62" r="26" fill="#F7F3E0" ${st('#C9B260',3)}/>${[...Array(12).keys()].map(i=>`<circle cx="${(i*47)%240-120}" cy="${-100+(i*31)%70}" r="1.6" fill="#FFF3C4"/>`).join('')}<path d="M-125 36 H125 V107 H-125Z" fill="#26492F"/>${bush(-84,50,.9)}${bush(10,44,1)}${bush(96,58,.8)}${gl}`;
  return `<g>${_e121frame('bg',250,214,inner,22)}</g>`};
/* day vs night: frog hides by day, comes out at night */
P.e121_daynight=(o,T)=>{const inner=`<clipPath id="e121_dn"><rect x="-125" y="-107" width="125" height="214"/></clipPath><rect x="-125" y="-107" width="125" height="214" fill="#BFE3F4"/><rect x="0" y="-107" width="125" height="214" fill="#1B2547"/><circle cx="-62" cy="-66" r="24" fill="#FFD84A" ${st('#E5A93A',3)}/><circle cx="62" cy="-66" r="22" fill="#F7F3E0" ${st('#C9B260',3)}/>${[[20,-90],[96,-96],[100,-40],[40,-52]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="1.8" fill="#FFF3C4"/>`).join('')}<rect x="-125" y="40" width="125" height="67" fill="#8EC47A"/><rect x="0" y="40" width="125" height="67" fill="#2F5A3D"/><path d="M-125 40 H125" ${st(C.navy,3)}/><g transform="translate(-62,48)"><path d="M-40 30 Q-38 -4 0 -8 Q38 -4 40 30Z" fill="#B7C1C7" ${st()}/></g>${[0,1,2].map(i=>{const ph=(T*.6+i/3)%1;return `<text x="${f(-38+i*16+ph*8)}" y="${f(28-i*20-ph*10)}" font-family="Fraunces" font-weight="900" font-size="${18+i*5}" fill="${C.navy}" opacity="${f(Math.sin(ph*Math.PI))}">z</text>`}).join('')}<g transform="translate(64,${f(66-Math.max(0,Math.sin(T*3))*8)}) scale(.46)">${_e121frog(T,{})}</g><path d="M0 -107 V107" ${st(C.navy,4)}/>`;
  return `<g>${_e121frame('dn',250,214,inner,22)}</g>`};
/* frog hiding under a stone / in the ground when there is no rain */
P.e121_hide=(o,T)=>{const inner=`<rect x="-125" y="-107" width="250" height="214" fill="#BFE3F4"/><circle cx="76" cy="-66" r="26" fill="#FFD84A" ${st('#E5A93A',3)}/><rect x="-125" y="-8" width="250" height="115" fill="#9A7448"/><rect x="-125" y="-8" width="250" height="14" fill="#8EC47A" ${st(C.navy,3)}/><path d="M-84 -8 Q-80 -44 -30 -48 Q20 -46 30 -8Z" fill="#B7C1C7" ${st()}/><path d="M-12 -8 q4 -10 14 -10" opacity="0"/><ellipse cx="-26" cy="58" rx="60" ry="30" fill="#7A5A36" ${st(C.navy,3)}/><g transform="translate(-26,58) scale(.5)">${_e121frog(T*.3,{})}</g>${[[70,40],[96,70],[60,86]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5" fill="#7A5A36"/>`).join('')}`;
  return `<g>${_e121frame('hd',250,214,inner,22)}</g>`};

/* ================= GARDEN, KINDNESS, MISC ================= */
const _e121flower=(x,y,c,s)=>`<g transform="translate(${x},${y}) scale(${s||1})"><path d="M0 0 V54" ${st('#5C8F4C',5)}/><path d="M0 34 Q-20 30 -22 14 Q-2 16 0 34Z" fill="#6FB25A" ${st(C.navy,2.5)}/>${[0,72,144,216,288].map(a=>`<ellipse cx="0" cy="-16" rx="9" ry="14" fill="${c}" ${st(C.navy,2.5)} transform="rotate(${a})"/>`).join('')}<circle r="9" fill="#F6CE4B" ${st(C.navy,2.5)}/></g>`;
/* garden with bees on flowers */
P.e121_gardenbees=(o,T,k)=>{const fl=[[-86,0,'#E5493F'],[-30,10,'#F2994A'],[30,0,'#C46BAE'],[86,8,'#F6CE4B']].map(([x,y,c])=>_e121flower(x,y,c,1.1)).join('');
  const bees=[[-60,-48],[10,-64],[64,-40]].map(([x,y],i)=>`<g transform="translate(${f(x+Math.sin(T*2+i)*8)},${f(y+Math.cos(T*2.4+i)*6)}) scale(.26)">${_e121insect(T+i,{v:'bee'})}</g>`).join('');
  const inner=`<rect x="-125" y="-107" width="250" height="214" fill="#CDEBF7"/><circle cx="84" cy="-76" r="22" fill="#FFD84A" ${st('#E5A93A',3)}/><rect x="-125" y="40" width="250" height="67" fill="#8EC47A"/><path d="M-125 40 H125" ${st(C.navy,3)}/><g transform="translate(0,34)">${fl}</g>${bees}`;
  return `<g>${_e121frame('gb',250,214,inner,22)}</g>`};
/* each has a job on the farm: bee on a plant, spider with web catching a pest */
P.e121_plantjob=(o,T,k)=>{const pl=(x)=>`<g transform="translate(${x},40)"><path d="M0 66 V-30" ${st('#5C8F4C',6)}/><path d="M0 40 Q-42 36 -46 4 Q-6 6 0 40Z M0 14 Q44 10 48 -22 Q6 -20 0 14Z M0 -12 Q-30 -16 -32 -44 Q-2 -44 0 -12Z" fill="#6FB25A" ${st(C.navy,3.5)}/>${_e121flower(0,-36,'#F2994A',.7)}</g>`;
  const web=`<g fill="none" stroke="#fff" stroke-width="2.4" opacity=".9"><path d="M84 -80 L40 -20 M84 -80 L90 0 M84 -80 L124 -30 M84 -80 L130 -70"/><path d="M84 -56 Q60 -40 56 -50 M84 -34 Q64 -14 50 -30 M84 -34 Q110 -14 108 -26"/></g>`;
  const inner=`<rect x="-125" y="-107" width="250" height="214" fill="#CDEBF7"/><rect x="-125" y="62" width="250" height="45" fill="#8EC47A"/><path d="M-125 62 H125" ${st(C.navy,3)}/>${pl(-70)}${web}<g transform="translate(86,-46) scale(.28)">${_e121spider(T,{})}</g><g transform="translate(66,-20) scale(.16) rotate(30)">${_e121insect(T,{v:'fly'})}</g><g transform="translate(${f(-30+Math.sin(T*2)*10)},${f(-30+Math.cos(T*2.6)*6)}) scale(.26)">${_e121insect(T,{v:'bee'})}</g><g transform="translate(-40,66) scale(.26)">${_e121insect(T,{v:'ladybird'})}</g>`;
  return `<g>${_e121frame('pj',250,214,inner,22)}</g>`};
/* a cardboard box with a baby bird and a little frog (wild animals do not belong in boxes) */
P.e121_wildbox=(o,T)=>`<g>${_e121sh(0,100,100)}<g transform="translate(-34,-18) scale(.6)">${_e121frog(T,{})}</g><g transform="translate(46,-26) scale(.6)">${_e121bird(T,{c:'#F2C94C'})}</g><path d="M-96 6 H96 L84 98 H-84Z" fill="#C9954A" ${st()}/><path d="M-96 6 L-110 -18 H-84 M96 6 L110 -18 H84" fill="#B9823A" ${st()}/><path d="M-60 6 V98 M60 6 V98" ${st('#A06E2E',3)} opacity=".5"/><rect x="-26" y="46" width="52" height="16" rx="3" fill="#fff" opacity=".5"/></g>`;
/* frog back at the river in the evening */
P.e121_riverfrog=(o,T,k)=>{const inner=`<rect x="-125" y="-107" width="250" height="214" fill="#F7A97A"/><circle cx="50" cy="${f(-20+ease((k||0)/6)*14)}" r="30" fill="#FFE27A" ${st('#E5A93A',3)}/><rect x="-125" y="-10" width="250" height="28" fill="#F7C07A" opacity=".7"/><path d="M-125 14 Q-60 -8 0 14 T125 10 V107 H-125Z" fill="#8EC47A" ${st(C.navy,3)}/><path d="M-125 66 Q-60 50 0 66 T125 62 V107 H-125Z" fill="#5BB0DE" ${st(C.navy,3)}/><path d="M-80 84 q8 -4 16 0 M20 90 q8 -4 16 0 M70 78 q8 -4 16 0" fill="none" stroke="#fff" stroke-width="3" opacity=".7"/><g transform="translate(${f(-40+Math.min(k||0,3)*10)},${f(48-Math.max(0,Math.sin((k||0)*4))*(k<3?10:0))}) scale(.42)">${_e121frog(T,{})}</g>${[-100,100].map(x=>_e121tree(x,24,.45,0)).join('')}`;
  return `<g>${_e121frame('rf',250,214,inner,22)}</g>`};
/* open book of animal facts + bulb */
P.e121_learn=(o,T,k)=>`<g>${_e121sh(0,100,120)}<path d="M-120 -40 Q-60 -62 0 -36 V82 Q-60 58 -120 80Z" fill="#fff" ${st()}/><path d="M120 -40 Q60 -62 0 -36 V82 Q60 58 120 80Z" fill="#FFF8E6" ${st()}/><g transform="translate(-60,14) scale(.5)">${_e121spider(T,{shadow:0})}</g><g transform="translate(62,22) scale(.42)">${_e121frog(T,{})}</g><path d="M-100 -20 Q-70 -32 -30 -22 M-100 -6 Q-70 -18 -30 -8" fill="none" ${st('#9AA7B0',3)}/><path d="M100 -20 Q70 -32 30 -22 M100 -6 Q70 -18 30 -8" fill="none" ${st('#9AA7B0',3)}/><g transform="translate(0,-92) scale(.46)">${P.bulb({},T)}</g></g>`;
/* person trembling (shaking with fear) with little shake lines */
P.e121_shaker=(o,T,k)=>{const j=Math.sin(T*38)*3.5;let ln='';[[-1,-40],[1,-40],[-1,10],[1,10]].forEach(([d,y],i)=>{const sw=Math.sin(T*30+i)*3;ln+=`<path d="M${d*84} ${y+sw} q${d*14} -12 ${d*28} 0 M${d*84} ${y+22+sw} q${d*14} -12 ${d*28} 0" fill="none" ${st(C.navy,4)}/>`});
  return `<g><g transform="translate(${f(j)},0)">${P.person(o.p||{c:'#E2B653',hair:'bun',hc:'#2A1D18'},T)}</g>${ln}</g>`};
/* camera with the flash going off */
P.e121_flash=(o,T)=>{const on=Math.sin(T*6)>0;return `<g>${_e121sh(0,96,100)}<rect x="-90" y="-44" width="180" height="116" rx="20" fill="#B8C4CC" ${st()}/><rect x="-90" y="-44" width="180" height="40" rx="20" fill="#2B3D48" ${st()}/><rect x="-60" y="-62" width="44" height="22" rx="6" fill="#2B3D48" ${st()}/><circle cx="0" cy="22" r="42" fill="#2B3D48" ${st()}/><circle cx="0" cy="22" r="28" fill="#4DA3D8" ${st(C.navy,4)}/><circle cx="-8" cy="14" r="8" fill="#fff" opacity=".7"/><rect x="40" y="-34" width="36" height="26" rx="6" fill="${on?'#FFF3A0':'#FFF8E6'}" ${st(C.navy,4)}/>${on?`<g ${st('#F6CE4B',6)}><path d="M58 -50 v-18 M82 -42 l14 -14 M96 -22 h20 M30 -46 l-12 -12"/></g>`:''}</g>`};
/* a photo print: brother + monkey (background) or a monkey photo */
