 const bird=`<g transform="translate(-86,${f(-62+s(T*2.2)*1.2)})"><path d="M10,6 L36,-4 L34,10Z" fill="#2F7FD0" ${st(C.navy,3)}/><ellipse cx="0" cy="6" rx="22" ry="16" fill="#5BB6F2" ${st(C.navy,3.5)}/><ellipse cx="-6" cy="14" rx="13" ry="8" fill="#E8F6FF"/><path d="M-4,4 Q10,-4 18,8 Q6,14 -4,4Z" fill="#2F7FD0" ${st(C.navy,2.5)} transform="rotate(${f(s(T*2.2)*4)} 0 6)"/><circle cx="-18" cy="-10" r="12" fill="#5BB6F2" ${st(C.navy,3.5)}/><path d="M-29,-10 L-40,-6 L-29,-3Z" fill="#FFA42E" ${st(C.navy,2.5)}/><path d="M-20,-22 Q-18,-30 -12,-26" fill="none" stroke="${C.navy}" stroke-width="3" stroke-linecap="round"/></g>`;
