const _e126F={mum:{c:'#D96C8B',hair:'long',hc:'#3A2A22'},dad:{c:'#8E6BB5',hair:'short',hc:'#222'},bro:{c:'#F2994A',hair:'short',hc:'#3A2A22'},sis:{c:'#4F7A5A',hair:'long',hc:'#2A1D18'},gran:{c:'#B07AA1',hair:'bun',hc:'#D5D8DB'},adam:{c:'#4DA3D8',hair:'short',hc:'#222'},maya:{c:'#E2B653',hair:'bun',hc:'#2A1D18'},cou:{c:'#4F7A5A',hair:'short',hc:'#3A2A22'},oldm:{c:'#6A8FA8',hair:'short',hc:'#D5D8DB'},man:{c:'#C0603A',hair:'short',hc:'#3A2A22'},woman:{c:'#5E9B63',hair:'long',hc:'#6A3F26'}};
