 const plug2=`<g transform="translate(98,18)"><rect x="-20" y="-28" width="40" height="56" rx="10" fill="#EEF2F6" ${st(C.navy,4)}/><rect x="-14" y="-22" width="28" height="44" rx="7" fill="none" stroke="#B8C4D0" stroke-width="2"/><rect x="-10" y="-9" width="6" height="4" rx="1.500" fill="${C.navy}"/><rect x="-10" y="5" width="6" height="4" rx="1.500" fill="${C.navy}"/></g><g transform="translate(${f(58+gap*2)},${f(18-gap*.4)}) scale(-1,1)"><rect x="10" y="-14" width="30" height="28" rx="6" fill="#E85D5D" ${st(C.navy,4)}/><rect x="-6" y="-9" width="16" height="5" rx="1.500" fill="#C9D3DD" ${st(C.navy,2.500)}/><rect x="-6" y="4" width="16" height="5" rx="1.500" fill="#C9D3DD" ${st(C.navy,2.500)}/><path d="M40,0 C54,0 58,14 68,20" fill="none" stroke="${C.navy}" stroke-width="8" stroke-linecap="round"/><path d="M40,0 C54,0 58,14 68,20" fill="none" stroke="#E85D5D" stroke-width="4" stroke-linecap="round"/><path d="M14,-8 H34" stroke="#fff" stroke-opacity=".5" stroke-width="2.500" stroke-linecap="round"/></g>`;
