/* Episode 127 intro hero: habit checklist board - check marks tick in for water, apple, book and sleep, with a growing sprout and a sparkle */
const _e127iSp=(x,y,s,T,ph,col)=>{const a=.5+.5*Math.sin(T*2.4+ph),z=s*(.55+.45*a);return `<path transform="translate(${x},${y}) scale(${f(z)})" d="M0,-1 Q.14,-.14 1,0 Q.14,.14 0,1 Q-.14,.14 -1,0 Q-.14,-.14 0,-1Z" fill="${col||'#FFF1B0'}" opacity="${f(.45+.55*a)}"/>`};
P.e127_ihero=(o,T,k)=>{const s=Math.sin;
 const bob=s(T*1.3)*3;
 const rowY=[-60,-20,20,60];
 const colr=['#3FB6F0','#FF6B6B','#8F6BF0','#5B7FD8'];
 const icons=[
  `<path d="M0,-12 C8,-2 11,3 11,7 A11,11 0 0 1 -11,7 C-11,3 -8,-2 0,-12Z" fill="#8FD8FF" ${st(C.navy,2.800)}/><path d="M-5,4 Q-5,9 0,10" fill="none" stroke="#fff" stroke-width="2.200" stroke-linecap="round"/>`,
  `<path d="M0,-8 C10,-14 18,-2 11,10 C7,16 3,14 0,13 C-3,14 -7,16 -11,10 C-18,-2 -10,-14 0,-8Z" fill="#FF5C5C" ${st(C.navy,2.800)}/><path d="M0,-8 Q0,-14 4,-17" fill="none" ${st(C.navy,2.500)}/><path d="M2,-12 Q10,-18 14,-12 Q8,-8 2,-12Z" fill="#6CC885" ${st(C.navy,2)}/>`,
  `<path d="M-12,-10 H-1 Q0,-8 0,-6 V12 Q-4,9 -12,10Z M12,-10 H1 Q0,-8 0,-6 V12 Q4,9 12,10Z" fill="#fff" ${st(C.navy,2.800)}/><path d="M-13,-12 V9 M13,-12 V9" ${st(C.navy,2.800)}/><path d="M-9,-4 H-4 M-9,1 H-4 M4,-4 H9 M4,1 H9" stroke="#B7A8E8" stroke-width="1.800" stroke-linecap="round"/>`,
  `<path d="M6,-12 A13,13 0 1 0 14,8 A10,10 0 1 1 6,-12Z" fill="#FFE27A" ${st('#B7791F',2.500)}/><path d="M-10,-12 l0,5 m-2.500,-2.500 h5" stroke="#fff" stroke-width="2" stroke-linecap="round"/>`
 ];
 let rows='';
 for(let i=0;i<4;i++){
  const y=rowY[i];
  const t0=.15+i*.55, p=clamp((T-t0)/.4,0,1), pe=ease?ease(p):p;
  const done=i<2?1:pe; // first two already ticked at T=0
  const len=34;
  rows+=`<g transform="translate(0,${y})"><rect x="-72" y="-17" width="144" height="34" rx="10" fill="#fff" ${st(C.navy,3)}/><rect x="-66" y="-12" width="6" height="24" rx="3" fill="${colr[i]}"/>
  <g transform="translate(-34,0)"><circle r="17" fill="${colr[i]}" opacity=".18"/>${icons[i]}</g>
  <rect x="-10" y="-8" width="46" height="5.500" rx="2.800" fill="#D7DEE8"/><rect x="-10" y="2" width="30" height="5" rx="2.500" fill="#E6EBF2"/>
  <g transform="translate(52,0)"><rect x="-13" y="-13" width="26" height="26" rx="7" fill="${done>.05?'#DDF7E4':'#fff'}" ${st(C.navy,3)}/>
  <path d="M-7,0 L-2,6 L8,-7" fill="none" stroke="#2FB26B" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="${len}" stroke-dashoffset="${f(len*(1-done))}"/><path d="M-7,0 L-2,6 L8,-7" fill="none" stroke="${C.navy}" stroke-width="1.500" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="${len}" stroke-dashoffset="${f(len*(1-done))}" opacity="0"/></g></g>`;
 }
 const sg=1+.08*s(T*1.6);
 const sprout=`<g transform="translate(94,92) rotate(${f(s(T*1.5)*3)})"><path d="M-16,0 L-12,-18 H12 L16,0Z" fill="#E8884A" ${st(C.navy,3.500)} transform="translate(0,18)"/><path d="M0,0 V-26" stroke="#2E7A47" stroke-width="4" stroke-linecap="round"/><g transform="translate(0,-26) scale(${f(sg)})"><path d="M0,0 C-8,-6 -22,-4 -24,-12 C-14,-18 -4,-12 0,0Z" fill="#6CC885" ${st(C.navy,3)}/><path d="M0,0 C8,-8 22,-8 26,-18 C14,-24 4,-14 0,0Z" fill="#43B86A" ${st(C.navy,3)}/></g></g>`;
 const star=`<g transform="translate(-96,-92) rotate(${f(T*30)})"><path d="M0,-13 L3.800,-4 L13,-3.500 L6,3 L8,12.500 L0,7.500 L-8,12.500 L-6,3 L-13,-3.500 L-3.800,-4Z" fill="#FFE27A" ${st(C.navy,3)} stroke-linejoin="round"/></g>`;
 return `<g><defs><radialGradient id="e127i_p" cx="50%" cy="40%" r="65%"><stop offset="0" stop-color="#7FE0B5"/><stop offset="1" stop-color="#1F6F8A"/></radialGradient><linearGradient id="e127i_b" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFE9B8"/><stop offset="1" stop-color="#F2C97A"/></linearGradient></defs>
<circle r="136" fill="#7FE0B5" opacity="${f(.10+.04*s(T*1.5))}"/><circle r="126" fill="url(#e127i_p)"/><circle r="126" fill="none" stroke="#FFE08A" stroke-width="3" opacity=".75"/><circle r="136" fill="none" stroke="#FFE08A" stroke-width="2" stroke-dasharray="3 11" opacity=".55" transform="rotate(${f(T*8)})"/>
<g transform="translate(0,${f(bob)})">
<ellipse cx="0" cy="${f(112-bob)}" rx="70" ry="8" fill="#000" opacity=".25"/>
<rect x="-92" y="-104" width="184" height="206" rx="20" fill="url(#e127i_b)" ${st(C.navy,5)} transform="rotate(-2)"/>
<g transform="rotate(-2)"><rect x="-30" y="-116" width="60" height="22" rx="8" fill="#9AA6B2" ${st(C.navy,4)}/><rect x="-14" y="-110" width="28" height="8" rx="4" fill="${C.navy}" opacity=".35"/>
<g transform="translate(0,2)">${rows}</g>
<path d="M-70,86 H70" stroke="#fff" stroke-opacity="0"/></g>
</g>
${sprout}${star}
${_e127iSp(108,-70,8,T,0)}${_e127iSp(-112,30,6,T,2)}${_e127iSp(-100,100,6,T,3.5,'#BFEFFF')}${_e127iSp(112,0,5,T,1.3,'#BFEFFF')}</g>`};

/* A2 ep 27 props end */
/* A2 ep 18 props begin */
/* Episode 118 props (A2 ep18): when technology stops working. Devices, printer, data, power cut, inventions. Faceless. Uses C, st, f, ease, clamp, P. */
const _e118SK='#E3AE82';
const _e118sh=(x,y,rx)=>`<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${f(rx*.14)}" fill="#000" opacity=".14"/>`;
const _e118tx=(t,x,y,fs,col,w)=>`<text x="${x}" y="${y}" text-anchor="middle" font-family="Fraunces" font-weight="${w||800}" font-size="${fs}" fill="${col||C.navy}">${t}</text>`;
const _e118pill=(t,x,y,w,fs)=>`<g transform="translate(${x},${y})"><rect x="${-w/2}" y="-20" width="${w}" height="40" rx="20" fill="${C.cream}" ${st(C.navy,4)}/>${_e118tx(t,0,(fs||26)*.34,fs||26)}</g>`;
const _e118ph=(x,y,w,h,kind)=>{const sk=['#BFE3F2','#FFE3B0','#CFE9D6'][kind%3];let g='';
  if(kind%3===0)g=`<circle cx="${x+w*.72}" cy="${y+h*.3}" r="${h*.14}" fill="${C.gold}"/><path d="M${x} ${y+h} L${x+w*.3} ${y+h*.38} L${x+w*.52} ${y+h*.7} L${x+w*.7} ${y+h*.5} L${x+w} ${y+h}Z" fill="${C.leaf}"/>`;
  else if(kind%3===1)g=`<path d="M${x} ${y+h*.62} Q${x+w*.25} ${y+h*.5} ${x+w*.5} ${y+h*.62} T${x+w} ${y+h*.62} V${y+h} H${x}Z" fill="${C.blue}"/><circle cx="${x+w*.3}" cy="${y+h*.3}" r="${h*.13}" fill="${C.orange}"/>`;
  else g=`<rect x="${x+w*.46}" y="${y+h*.5}" width="${w*.08}" height="${h*.5}" fill="${C.brown}"/><circle cx="${x+w*.5}" cy="${y+h*.4}" r="${h*.26}" fill="${C.leaf}"/><rect x="${x}" y="${y+h*.86}" width="${w}" height="${h*.14}" fill="#8EBE7E"/>`;
  return `<g><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${sk}"/>${g}<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="none" ${st(C.navy,2.5)}/></g>`};
const _e118sheet=(x,y,w,h,mode)=>{let g='';
  if(mode==='report'){g=`<rect x="${x+w*.1}" y="${y+h*.08}" width="${w*.5}" height="${h*.06}" rx="3" fill="${C.navy}"/>`;for(let r=0;r<3;r++)for(let c=0;c<3;c++)g+=`<rect x="${x+w*.1+c*w*.27}" y="${y+h*.2+r*h*.09}" width="${w*.25}" height="${h*.08}" fill="${r?'#fff':C.gold}" ${st(C.navy,1.8)}/>`;g+=_e118ph(x+w*.1,y+h*.52,w*.8,h*.28,0)+`<path d="M${x+w*.1} ${y+h*.88} H${x+w*.9}" ${st('#9AA7B0',3)}/>`}
  else if(mode==='table'){for(let r=0;r<5;r++)for(let c=0;c<3;c++)g+=`<rect x="${x+w*.1+c*w*.27}" y="${y+h*.1+r*h*.14}" width="${w*.25}" height="${h*.12}" fill="${r?'#fff':C.gold}" ${st(C.navy,2)}/>`}
  else if(mode==='photo'){g=_e118ph(x+w*.1,y+h*.14,w*.8,h*.6,0)+`<path d="M${x+w*.1} ${y+h*.84} H${x+w*.6}" ${st('#9AA7B0',4)}/>`}
  else if(mode==='words'){for(let i=0;i<8;i++)g+=`<path d="M${x+w*.1} ${y+h*(.12+i*.1)} H${x+w*(i%3===2?.55:.9)}" ${st('#7B8A93',4)}/>`}
  return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="5" fill="#fff" ${st()}/>${g}`};

/* ---------- printer ---------- */
P.e118_printer=(o,T,k)=>{const s=o.s||'idle',bl=Math.sin(T*8)>0;
  const lc=s==='err'?(bl?C.red:'#8A3A36'):s==='idle'?'#7A8A93':C.leaf;
  let glow='';if(s==='press')for(let i=0;i<3;i++){const ph=(T*1.6+i/3)%1;glow+=`<circle cx="-66" cy="4" r="${f(14+ph*26)}" fill="none" ${st(C.leaf,4)} opacity="${f(1-ph)}"/>`}
  let out='';if(s==='work'){const ph=(T*.8)%1;out=`<g><rect x="-52" y="${f(52)}" width="104" height="${f(14+ph*44)}" rx="3" fill="#fff" ${st()}/><path d="M-36 ${f(62)} H36" ${st('#CBD3D8',3)}/></g>`}
  if(s==='ok')out=`<rect x="-52" y="52" width="104" height="30" rx="3" fill="#fff" ${st()}/><path d="M-36 62 H36 M-36 72 H20" ${st('#7B8A93',3)}/>`;
  const scr=s==='err'?`<rect x="6" y="-14" width="84" height="32" rx="6" fill="#FFF3D6" ${st(C.navy,3)}/><path d="M14 8 L24 -8 L34 8Z" fill="${C.red}" ${st(C.navy,2)}/>${_e118tx('404',62,10,24,C.red)}`:`<rect x="6" y="-14" width="84" height="32" rx="6" fill="${s==='idle'?'#3A4A54':'#BFE3F2'}" ${st(C.navy,3)}/>${s==='idle'?'':`<path d="M18 -2 H78 M18 8 H58" ${st(C.navy,3)}/>`}`;
  return `<g>${_e118sh(0,96,108)}<path d="M-56 -38 L-48 -92 H48 L56 -38Z" fill="#fff" ${st()}/><path d="M-34 -72 H34 M-36 -58 H36" fill="none" ${st('#CBD3D8',3)}/>
  <path d="M-104 -6 Q-104 -38 -84 -38 H84 Q104 -38 104 -6 V66 Q104 80 90 80 H-90 Q-104 80 -104 66Z" fill="#E4EAEE" ${st()}/><path d="M-96 -22 H96" ${st('#C3CDD3',4)}/><rect x="-96" y="-32" width="192" height="8" rx="4" fill="#fff" opacity=".7"/>
  <rect x="-76" y="34" width="152" height="14" rx="6" fill="${C.navy2}" ${st()}/>${out}${scr}
  <circle cx="-66" cy="4" r="17" fill="#2F7D45" ${st()}/><circle cx="-66" cy="2" r="12" fill="${s==='press'||s==='ok'||s==='work'?'#7BD88F':C.leaf}"/><path d="M-72 -4 q6 -6 12 -2" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" opacity=".8"/>${glow}
  <circle cx="-30" cy="4" r="6" fill="${lc}" ${st(C.navy,2.5)}/></g>`};

/* ---------- sheets of paper ---------- */
P.e118_sheet=(o,T)=>`<g>${_e118sh(0,114,80)}<g transform="rotate(${f(Math.sin(T*1.6)*1.5)})">${_e118sheet(-80,-108,160,216,o.mode||'blank')}${o.mode==='blank'?`<path d="M-60 -80 H20" fill="none" ${st('#EEF1F3',3)}/>`:''}</g></g>`;
P.e118_pages=(o,T)=>{const n=o.n||5,blank=o.blank!==0;let s='';
  for(let i=Math.min(n,6)-1;i>=0;i--)s+=`<g transform="translate(${-60+i*21},${f(30-i*13)}) rotate(${-7+i*3})">${_e118sheet(-60,-80,120,160,i===0?(blank?'blank':'report'):'blank')}</g>`;
  return `<g>${_e118sh(0,104,90)}${s}${o.n?_e118pill(String(o.n),0,-118,84,34):''}</g>`};
P.e118_blankone=(o,T)=>P.e118_sheet({mode:'blank'},T);

/* ---------- tablet ---------- */
const _e118apps=(x,y,w,h,cols,rows)=>{let s='';const cs=[C.red,C.blue,C.moss,C.orange,'#8E6BB5',C.gold,C.leaf,C.cold];for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){const cw=w/cols,ch=h/rows;s+=`<rect x="${x+c*cw+cw*.14}" y="${y+r*ch+ch*.12}" width="${cw*.72}" height="${ch*.7}" rx="${cw*.18}" fill="${cs[(r*cols+c)%8]}" ${st(C.navy,2)}/>`}return s};
P.e118_tablet=(o,T,k)=>{const s=o.s||'on';let scr='';
  if(s==='on')scr=`<rect x="-88" y="-60" width="176" height="120" rx="8" fill="#BFE3F2"/>${_e118apps(-80,-52,160,100,4,2)}`;
  else if(s==='black')scr=`<rect x="-88" y="-60" width="176" height="120" rx="8" fill="#0E1317"/><path d="M-60 60 L-10 -60 H20 L-30 60Z" fill="#fff" opacity=".07"/>`;
  else if(s==='report')scr=`<rect x="-88" y="-60" width="176" height="120" rx="8" fill="#EEF1F3"/>${_e118sheet(-44,-54,88,108,'report')}`;
  else if(s==='photos'){scr=`<rect x="-88" y="-60" width="176" height="120" rx="8" fill="#fff"/>`;for(let i=0;i<6;i++)scr+=_e118ph(-82+(i%3)*58,-54+Math.floor(i/3)*58,54,54,i)}
  else if(s==='big'){const z=1+.25*ease(k/.8);scr=`<rect x="-88" y="-60" width="176" height="120" rx="8" fill="#fff"/><g transform="scale(${f(z)})">${_e118ph(-60,-44,120,88,0)}</g><path d="M-82 -54 l16 16 M82 -54 l-16 16 M-82 54 l16 -16 M82 54 l-16 -16" ${st(C.red,5)}/>`}
  else if(s==='notes'){scr=`<rect x="-88" y="-60" width="176" height="120" rx="8" fill="#FFF3C4"/>`;for(let i=0;i<5;i++)scr+=`<path d="M-70 ${-34+i*20} H${i%2?40:66}" ${st('#B79B45',4)}/>`}
  return `<g>${_e118sh(0,86,104)}<rect x="-102" y="-74" width="204" height="148" rx="20" fill="#2B3D48" ${st()}/>${scr}<circle cx="-95" cy="0" r="2.6" fill="#7B8A93"/><path d="M-80 -54 L-56 -54" ${st('#fff',3)} opacity="${s==='black'?0:.5}"/></g>`};

/* ---------- laptop / computer ---------- */
P.e118_laptop=(o,T)=>{const s=o.s||'on';let scr='';
  if(s==='on')scr=`<rect x="-82" y="-86" width="164" height="96" fill="#BFE3F2"/>${_e118apps(-74,-78,148,78,5,2)}`;
  else if(s==='blank')scr=`<rect x="-82" y="-86" width="164" height="96" fill="#fff"/><rect x="-82" y="-86" width="164" height="14" fill="#DDE4E8"/>`;
  else if(s==='off')scr=`<rect x="-82" y="-86" width="164" height="96" fill="#0E1317"/>`;
  else if(s==='photos'){scr=`<rect x="-82" y="-86" width="164" height="96" fill="#fff"/>`;for(let i=0;i<6;i++)scr+=_e118ph(-76+(i%3)*53,-80+Math.floor(i/3)*44,50,40,i)}
  return `<g>${_e118sh(0,96,120)}<rect x="-94" y="-98" width="188" height="120" rx="12" fill="#2B3D48" ${st()}/>${scr}<path d="M-112 30 H112 L100 4 Q98 -2 90 -2 H-90 Q-98 -2 -100 4Z" fill="#CDD6DC" ${st()}/><path d="M-112 30 H112 Q112 42 98 42 H-98 Q-112 42 -112 30Z" fill="#AEBAC2" ${st()}/><rect x="-26" y="12" width="52" height="6" rx="3" fill="#9AA7B0"/></g>`};
