/* ---------- repair shop ---------- */
P.e118_shop=(o,T)=>`<g>${_e118sh(0,104,126)}<rect x="-112" y="-60" width="224" height="160" rx="8" fill="#E8D7B0" ${st()}/><path d="M-124 -60 L-108 -100 H108 L124 -60Z" fill="${C.blue}" ${st()}/>${[0,1,2,3,4,5,6].map(i=>`<path d="M${-124+i*35.4} -60 L${-108+i*30.9} -100 H${-108+(i+1)*30.9} L${-124+(i+1)*35.4} -60Z" fill="${i%2?C.blue:'#fff'}" ${st(C.navy,3)}/>`).join('')}<rect x="-70" y="-38" width="140" height="62" rx="10" fill="#fff" ${st()}/><g transform="translate(-34,-7) scale(.38) rotate(0)"><circle r="40" fill="${C.gold}" ${st()}/><circle r="16" fill="#fff" ${st(C.navy,5)}/>${[0,1,2,3,4,5].map(i=>`<rect x="-9" y="-56" width="18" height="22" rx="4" fill="${C.gold}" ${st()} transform="rotate(${i*60})"/>`).join('')}</g><g transform="translate(34,-7) rotate(-35)"><rect x="-6" y="-26" width="12" height="40" rx="5" fill="${C.red}" ${st(C.navy,3)}/><rect x="-2.5" y="14" width="5" height="22" fill="#CDD6DC" ${st(C.navy,2.5)}/></g><rect x="-96" y="40" width="192" height="60" rx="6" fill="#B07A45" ${st()}/><rect x="-80" y="48" width="70" height="44" rx="5" fill="#2B3D48" ${st(C.navy,3)}/><g transform="translate(40,24) scale(.55)">${P.person({c:'#4F7A5A',hair:'short',hc:'#222'},T)}</g></g>`;

