/* ---------- data kinds ---------- */
P.e118_data=(o,T,k)=>{const kd=o.k||'photos',many=kd==='all';
  const one=(kind)=>{if(kind==='photos')return `<g>${_e118ph(-70,-56,140,112,0)}<g transform="translate(18,18)">${_e118ph(-70,-56,140,112,1)}</g></g>`;
    if(kind==='notes')return `<g><rect x="-62" y="-84" width="124" height="168" rx="10" fill="#FFF3C4" ${st()}/><rect x="-62" y="-84" width="124" height="22" rx="10" fill="${C.orange}" ${st()}/>${[0,1,2,3,4].map(i=>`<path d="M-44 ${-40+i*24} H${i%2?30:44}" ${st('#B79B45',4)}/>`).join('')}</g>`;
    if(kind==='docs')return `<g><g transform="rotate(-8)">${_e118sheet(-60,-90,110,150,'words')}</g><g transform="translate(26,12) rotate(6)">${_e118sheet(-60,-90,110,150,'table')}</g></g>`;
    return `<g><rect x="-84" y="-76" width="168" height="152" rx="14" fill="#fff" ${st()}/><path d="M-84 -34 V-62 Q-84 -76 -70 -76 H70 Q84 -76 84 -62 V-34Z" fill="${C.red}" ${st()}/>${[0,1,2,3,4,5,6].map(i=>[0,1,2,3].map(j=>`<rect x="${-68+i*21}" y="${-24+j*24}" width="16" height="16" rx="3" fill="${(i+j)%5===0?C.gold:'#E8DFC8'}"/>`).join('')).join('')}</g>`};
  if(!many)return `<g>${_e118sh(0,100,86)}${one(kd)}</g>`;
  return `<g>${['photos','notes','docs','plans'].map((q,i)=>`<g transform="translate(${[-116,116,-116,116][i]},${[-100,-100,100,100][i]}) scale(.62)">${one(q)}</g>`).join('')}<g transform="scale(.95)"><rect x="-70" y="-62" width="140" height="124" rx="16" fill="#2B3D48" ${st()}/>${_e118ph(-56,-46,112,92,0)}</g></g>`};
P.e118_num=(o,T)=>`<g>${_e118sh(0,96,86)}<rect x="-100" y="-90" width="200" height="180" rx="26" fill="${C.cream}" ${st()}/><rect x="-100" y="-90" width="200" height="40" rx="26" fill="${C.red}" ${st()}/><rect x="-100" y="-66" width="200" height="16" fill="${C.red}"/>${_e118tx(o.n,0,38,(String(o.n).length>2?84:110),C.navy)}${_e118tx(o.u||'',0,72,36,C.goldD)}<circle cx="-56" cy="-92" r="7" fill="${C.navy}"/><circle cx="56" cy="-92" r="7" fill="${C.navy}"/></g>`;
P.e118_pct=(o,T,k)=>{const n=o.n,a=ease(k/.9)*n/100*Math.PI*2,R=92;const x=Math.sin(a)*R,y=-Math.cos(a)*R;
  const slice=n>=100?`<circle r="${R}" fill="${C.gold}" ${st()}/>`:`<path d="M0 0 L0 ${-R} A${R} ${R} 0 ${a>Math.PI?1:0} 1 ${f(x)} ${f(y)}Z" fill="${C.gold}" ${st()}/>`;
  return `<g>${_e118sh(0,104,90)}<circle r="${R}" fill="#E8DFC8" ${st()}/>${slice}<circle r="${R}" fill="none" ${st()}/><g><rect x="-62" y="-30" width="124" height="60" rx="30" fill="${C.cream}" ${st(C.navy,4)}/>${_e118tx(n+'%',0,16,46)}</g></g>`};

/* ---------- web / browser ---------- */
P.e118_browser=(o,T,k)=>{const s=o.s||'blank';let c='';
  if(s==='blank')c=`<rect x="-90" y="-44" width="180" height="104" fill="#fff"/>`;
  else if(s==='site')c=`<rect x="-90" y="-44" width="180" height="104" fill="#fff"/><rect x="-90" y="-44" width="180" height="28" fill="${C.blue}"/>${_e118ph(-80,-8,60,44,0)}<path d="M-8 -2 H80 M-8 12 H70 M-8 26 H76 M-80 46 H80" ${st('#9AA7B0',4)}/>`;
  else if(s==='learn')c=`<rect x="-90" y="-44" width="180" height="104" fill="#fff"/><path d="M-50 40 V-14 Q-26 -26 0 -14 Q26 -26 50 -14 V40 Q26 30 0 40 Q-26 30 -50 40Z" fill="${C.cream}" ${st()}/><path d="M0 -14 V40" ${st(C.navy,3)}/><path d="M-36 0 H-12 M-36 14 H-12 M12 0 H36 M12 14 H36" ${st('#9AA7B0',3)}/>`;
  else if(s==='bolt')c=`<rect x="-90" y="-44" width="180" height="104" fill="#fff"/><path d="M8 -36 L-24 14 H-2 L-12 52 L28 -6 H6Z" fill="${C.gold}" ${st()}/>`;
  const ex=o.x?`<path d="M-30 -10 L30 44 M30 -10 L-30 44" ${st(C.red,10)} opacity="${f(.55+.4*Math.sin(T*5))}"/>`:'';
  return `<g>${_e118sh(0,86,110)}<rect x="-100" y="-78" width="200" height="148" rx="14" fill="#fff" ${st()}/><path d="M-100 -62 V-64 Q-100 -78 -86 -78 H86 Q100 -78 100 -64 V-52 H-100Z" fill="#CDD6DC" ${st()}/><circle cx="-84" cy="-65" r="4.5" fill="${C.red}"/><circle cx="-70" cy="-65" r="4.5" fill="${C.gold}"/><circle cx="-56" cy="-65" r="4.5" fill="${C.leaf}"/><rect x="-96" y="-52" width="192" height="4" fill="#9AA7B0" opacity=".0"/><rect x="-40" y="-72" width="132" height="14" rx="7" fill="#fff" ${st(C.navy,2.5)}/>${c}<rect x="-100" y="-52" width="200" height="0"/>${ex}</g>`};
