P.e101_pilot=(o,T,k)=>{return `<g><g transform="translate(-48,8)">${P.person({c:'#3B4E78',hair:'short',hc:'#222'},T)}<path d="M-42 -78 Q-40 -112 0 -112 Q40 -112 42 -78 Z" fill="${C.navy}" ${st()}/><rect x="-46" y="-82" width="92" height="12" rx="6" fill="#0F1A20" ${st()}/><circle cx="0" cy="-96" r="9" fill="${C.gold}" ${st(C.navy,3)}/><path d="M-6 -96 h12 M0 -102 v12" ${st(C.navy,2.5)}/></g><g transform="translate(78,-48) rotate(-8) scale(.62)">${P.e14_plane?P.e14_plane({},T,k):''}</g></g>`};

