P.e101_livingroom=(o,T,k)=>`<g><rect x="-130" y="-100" width="260" height="170" rx="12" fill="#F1E3C3" ${st()}/><rect x="-130" y="52" width="260" height="18" fill="${C.brown}" ${st()}/><rect x="-100" y="-80" width="64" height="52" rx="4" fill="${C.sky}" ${st()}/><line x1="-68" y1="-80" x2="-68" y2="-28" ${st(C.navy,3)}/><path d="M-110 70 V26 Q-110 4 -88 4 H34 Q56 4 56 26 V70Z" fill="${C.moss}" ${st()}/><rect x="-96" y="24" width="140" height="30" rx="12" fill="${C.leaf}" ${st()}/><rect x="-118" y="20" width="26" height="50" rx="12" fill="${C.moss}" ${st()}/><rect x="34" y="20" width="26" height="50" rx="12" fill="${C.moss}" ${st()}/><rect x="80" y="14" width="46" height="56" rx="6" fill="${C.brown}" ${st()}/><g transform="translate(103,-6) rotate(-6)"><rect x="-11" y="-24" width="22" height="38" rx="5" fill="${C.navy}" ${st(C.navy,3)}/><rect x="-8" y="-20" width="16" height="29" rx="3" fill="#CFEAF7"/></g><path d="M103 14 q-8 10 -14 10" fill="none" ${st(C.navy,3)}/><g transform="translate(-70,-74)"><circle r="0"/></g></g>`;
