/* B1 ep 1 props begin */
/* Episode 201 props: Should Children Have Phones Before Twelve? (simple phone, smartphone, tablet, screen-time, family, school road, safety, rules). Faceless. Uses C, st, f, ease, clamp, P. */
const _e201tx=(t,x,y,fs,fill,w)=>`<text x="${x}" y="${y}" text-anchor="middle" font-family="Fraunces" font-weight="${w||800}" font-size="${fs}" fill="${fill||C.navy}">${t}</text>`;
const _e201sh=(rx,y)=>`<ellipse cx="0" cy="${y}" rx="${rx}" ry="${f(rx*.09)}" fill="#000" opacity=".13"/>`;
const _e201pr=(o,T,x,y,s)=>`<g transform="translate(${f(x)},${f(y)}) scale(${f(s)})">${P.person(o,T)}</g>`;
const _e201A={c:'#4DA3D8',hair:'short',hc:'#222'},_e201M={c:'#E2B653',hair:'bun',hc:'#2A1D18'},_e201MUM={c:'#D96C8B',hair:'long',hc:'#3A2A22'},_e201DAD={c:'#8E6BB5',hair:'short',hc:'#222'},_e201KID={c:'#F2994A',hair:'short',hc:'#3A2A22'},_e201GIRL={c:'#4F7A5A',hair:'long',hc:'#2A1D18'},_e201KID2={c:'#3FB8AF',hair:'bun',hc:'#3A2A22'};
const _e201SK='#E3AE82';
const _e201hand=(x,y,r)=>`<ellipse cx="${x}" cy="${y}" rx="${r}" ry="${f(r*.85)}" fill="${_e201SK}" ${st(C.navy,3.5)}/>`;
const _e201waves=(T,x,y,col,n,dir)=>{let s='';for(let i=0;i<(n||2);i++){const ph=(T*1.6+i*.5)%1;s+=`<path d="M${f(x+dir*(ph*22))} ${y-26} q${dir*14} 26 0 52" fill="none" ${st(col||C.goldD,5)} opacity="${f(1-ph)}"/>`}return s};
const _e201tab=(w,h,inner,cid,bg)=>{const sw=w-18,sh=h-18;return `<g><rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="14" fill="${C.navy}" ${st()}/><clipPath id="${cid}"><rect x="${-sw/2}" y="${-sh/2}" width="${sw}" height="${sh}" rx="5"/></clipPath><rect x="${-sw/2}" y="${-sh/2}" width="${sw}" height="${sh}" rx="5" fill="${bg||'#BFE3F2'}"/><g clip-path="url(#${cid})">${inner}</g></g>`};
const _e201cartoon=`<circle cx="-34" cy="-16" r="13" fill="${C.gold}"/><ellipse cx="26" cy="-18" rx="22" ry="10" fill="#fff"/><rect x="-80" y="16" width="160" height="40" fill="${C.leaf}"/><circle cx="0" cy="4" r="17" fill="${C.red}" ${st('#fff',3)}/><polygon points="-5,-5 9,4 -5,13" fill="#fff"/>`;
const _e201glow=(x,y,r,col,T)=>{const p=1+Math.sin((T||0)*3)*.05;return [1,.72,.46].map((q,i)=>`<circle cx="${x}" cy="${y}" r="${f(r*q*p)}" fill="${col}" opacity="${[.14,.2,.28][i]}"/>`).join('')};
const _e201smartBody=(inner,cid,o)=>{o=o||{};const w=o.w||100,h=o.h||200;return `<g><rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="20" fill="${C.navy}" ${st()}/><clipPath id="${cid}"><rect x="${-w/2+8}" y="${-h/2+16}" width="${w-16}" height="${h-30}" rx="9"/></clipPath><rect x="${-w/2+8}" y="${-h/2+16}" width="${w-16}" height="${h-30}" rx="9" fill="${o.bg||'#DDEBF3'}"/><g clip-path="url(#${cid})">${inner}</g><rect x="-12" y="${-h/2+6}" width="24" height="5" rx="2.5" fill="#41525c"/></g>`};
const _e201AC=[C.red,C.blue,C.moss,C.orange,'#8E6BB5',C.gold2,'#E07BA0','#3FB8AF'];

/* keypad phone: calls + messages only */
P.e201_simple=(o,T,k)=>{let keys='';for(let r=0;r<4;r++)for(let c=0;c<3;c++)keys+=`<rect x="${-37+c*26}" y="${4+r*21}" width="22" height="15" rx="5" fill="#E8EEF2" ${st(C.navy,2.5)}/>`;
  let scr;if(o.msg)scr=`<rect x="-20" y="-70" width="40" height="28" rx="4" fill="#fff" ${st(C.navy,3)}/><path d="M-20 -68 L0 -52 L20 -68" fill="none" ${st(C.navy,3)}/>`;else scr=`<path d="M-14 -62 q-4 -6 2 -9 l7 5 q2 2 0 5 l-3 3 q4 8 11 11 l3 -3 q3 -2 5 0 l5 7 q3 6 -3 9 q-26 -2 -27 -28Z" fill="${C.moss}" ${st(C.navy,2.5)} transform="translate(8,6) scale(.9)"/>`;
  return `<g><g transform="rotate(${f(Math.sin(T*2.2)*(o.ring?4:0.8))})">${_e201sh(60,104)}<rect x="-46" y="-96" width="92" height="192" rx="18" fill="#3E5260" ${st()}/><rect x="-10" y="-90" width="20" height="4" rx="2" fill="#1E2B33"/><rect x="-35" y="-80" width="70" height="50" rx="6" fill="#CFE9D8" ${st(C.navy,3)}/>${scr}<circle cx="-24" cy="-18" r="7" fill="${C.moss}" ${st(C.navy,2.5)}/><circle cx="24" cy="-18" r="7" fill="${C.red}" ${st(C.navy,2.5)}/><rect x="-9" y="-24" width="18" height="12" rx="6" fill="#E8EEF2" ${st(C.navy,2.5)}/>${keys}</g>${o.ring?_e201waves(T,58,0,C.goldD,2,1)+_e201waves(T,-58,0,C.goldD,2,-1):''}</g>`};

/* smartphone: apps + internet */
P.e201_smart=(o,T,k)=>{let g='';for(let i=0;i<12;i++){const a=i%3,b=Math.floor(i/3);g+=`<g transform="translate(${-28+a*28},${-52+b*30})"><rect x="-11" y="-11" width="22" height="22" rx="6" fill="${_e201AC[i%8]}" ${st(C.navy,2.5)}/><circle r="4" fill="#fff"/></g>`}
  const net=o.net?`<rect x="-36" y="62" width="72" height="22" rx="11" fill="#fff" ${st(C.navy,3)}/><circle cx="-24" cy="73" r="7" fill="${C.blue}"/><line x1="-12" y1="73" x2="22" y2="73" ${st('#9AA7B0',4)}/>`:'';
  const n=o.notif?`<g transform="translate(40,-92) scale(${f(1+Math.sin(T*6)*.05)})"><circle r="17" fill="${C.red}" ${st()}/>${_e201tx(o.notif,0,7,20,'#fff')}</g>`:'';
  return `<g><g transform="rotate(${f(o.tilt||0)})">${_e201sh(60,106)}${_e201smartBody(g+net,'e201_cs1')}${n}</g></g>`};

/* tablet showing cartoons */
P.e201_tablet=(o,T,k)=>`<g><g transform="rotate(-4)">${o.glow?_e201glow(0,0,120,'#7FC4F0',T):''}${_e201sh(86,62)}${_e201tab(160,112,_e201cartoon,'e201_ct1')}</g></g>`;

/* child holding a tablet */
P.e201_kidtab=(o,T,k)=>{const cry=o.cry;let tr='';if(cry)for(let i=0;i<4;i++){const ph=(T*1.4+i*.25)%1,s=i%2?1:-1;tr+=`<path d="M${s*34} ${f(-46+ph*40)} q5 8 0 13 q-5 -5 0 -13Z" fill="${C.blue}" ${st(C.navy,2)} opacity="${f(1-ph)}"/>`}
  return `<g>${_e201sh(78,104)}${_e201pr(o.kid||_e201GIRL,T,0,14,.82)}<g transform="translate(0,${f(-30)})">${tr}</g>${cry?_e201waves(T,62,-34,C.red,2,1)+_e201waves(T,-62,-34,C.red,2,-1):''}<g transform="translate(0,52) scale(.76)">${_e201tab(150,104,_e201cartoon,'e201_ct2')}</g>${_e201hand(-50,84,10)}${_e201hand(50,84,10)}</g>`};

/* restaurant table: adult + child with tablet */
P.e201_resto=(o,T,k)=>{const cry=o.cry;let others='';if(cry){others=`<g transform="translate(-100,-86) scale(.32)">${P.person({c:'#6A8FA8',hair:'short',hc:'#BDC3C7'},T)}</g><g transform="translate(104,-92) scale(.32)">${P.person({c:'#B07AA1',hair:'bun',hc:'#D5D8DB'},T)}</g><g transform="translate(-100,-124)">${[0,1].map(i=>`<path d="M${-14+i*10} 0 q8 8 0 16" fill="none" ${st(C.goldD,3)} opacity="${f(.5+.5*Math.sin(T*6+i))}"/>`).join('')}</g>`}
  let tr='';if(cry)for(let i=0;i<4;i++){const ph=(T*1.4+i*.25)%1,s=i%2?1:-1;tr+=`<path d="M${68+s*20} ${f(-30+ph*34)} q4 7 0 11 q-4 -4 0 -11Z" fill="${C.blue}" ${st(C.navy,2)} opacity="${f(1-ph)}"/>`}
  return `<g>${others}${_e201pr(_e201MUM,T,-66,-4,.6)}${_e201pr(_e201KID,T,70,10,.5)}${tr}${cry?_e201waves(T,100,-14,C.red,2,1):''}<rect x="-122" y="42" width="244" height="16" rx="7" fill="#B07A4A" ${st()}/><rect x="-108" y="58" width="12" height="52" fill="#8B5E3C" ${st(C.navy,4)}/><rect x="96" y="58" width="12" height="52" fill="#8B5E3C" ${st(C.navy,4)}/><ellipse cx="-62" cy="40" rx="30" ry="7" fill="#fff" ${st(C.navy,3)}/><ellipse cx="-62" cy="38" rx="17" ry="4" fill="#F2C48A"/><rect x="-14" y="22" width="14" height="20" rx="4" fill="#DCEEF7" ${st(C.navy,3)}/><g transform="translate(70,22) scale(.52)">${_e201tab(150,104,_e201cartoon,'e201_ct3')}</g></g>`};

/* car journey with a child watching cartoons */
P.e201_carkid=(o,T,k)=>{let road='';for(let i=0;i<5;i++){const x=((i*70-T*130)%350+350)%350-175;road+=`<rect x="${f(x)}" y="94" width="38" height="6" rx="3" fill="#fff"/>`}
  let lines='';for(let i=0;i<3;i++){const x=((i*80-T*200)%320+320)%320-160;lines+=`<line x1="${f(x+110)}" y1="${-10+i*26}" x2="${f(x+146)}" y2="${-10+i*26}" ${st('#fff',4)} opacity=".7"/>`}
  return `<g>${lines}<rect x="-165" y="76" width="330" height="40" rx="8" fill="#5B6B75" ${st()}/>${road}<g transform="translate(0,${f(Math.sin(T*9)*1.2)})"><path d="M-112 60 L-112 20 Q-112 4 -92 2 L-70 -2 L-46 -46 Q-42 -52 -34 -52 L46 -52 Q54 -52 60 -44 L80 -2 L100 4 Q114 8 114 24 L114 60Z" fill="${C.red}" ${st()}/><clipPath id="e201_cw"><path d="M-40 -42 L-58 -4 L72 -4 L54 -42Z"/></clipPath><path d="M-40 -42 L-58 -4 L72 -4 L54 -42Z" fill="#BFE3F2" ${st(C.navy,4)}/><g clip-path="url(#e201_cw)"><g transform="translate(14,12) scale(.42)">${P.person(_e201KID,T)}</g><g transform="translate(-30,-6) scale(.2)">${_e201tab(150,104,_e201cartoon,'e201_ct4')}</g></g><line x1="7" y1="-44" x2="7" y2="-4" ${st(C.navy,4)}/><rect x="-112" y="40" width="226" height="22" fill="#B83F3B" ${st(C.navy,4)}/><circle cx="-70" cy="62" r="22" fill="${C.navy}"/><circle cx="-70" cy="62" r="9" fill="${C.grey}"/><circle cx="74" cy="62" r="22" fill="${C.navy}"/><circle cx="74" cy="62" r="9" fill="${C.grey}"/><rect x="100" y="24" width="14" height="10" rx="4" fill="${C.gold}" ${st(C.navy,3)}/></g></g>`};

/* dinner table (tablet / talking / phone) */
P.e201_dinner=(o,T,k)=>{const steam=[0,1,2].map(i=>{const ph=(T*.9+i/3)%1;return `<path d="M${-12+i*12} ${f(14-ph*30)} q-6 -9 0 -18" fill="none" ${st('#9AA7B0',4)} opacity="${f(1-ph)}"/>`}).join('');
  let mid='';if(o.tab)mid=`<g transform="translate(84,20) scale(.42)">${_e201tab(150,104,_e201cartoon,'e201_ct5')}</g>`;
  if(o.phone)mid+=`<g transform="translate(-86,24) rotate(-8) scale(.3)">${_e201smartBody('','e201_cs2',{w:100,h:170})}<circle cx="30" cy="-70" r="20" fill="${C.red}"/></g>`;
  let bub='';if(o.talk)bub=`<g transform="translate(-58,-92) scale(.46)">${P.bubble({side:'R',w:96,icon:'sun',is:.7},T)}</g><g transform="translate(62,-96) scale(.46)">${P.bubble({side:'L',w:96,icon:'heart',is:.7},T)}</g>`;
  return `<g>${bub}${_e201pr(_e201MUM,T,-70,-10,.56)}${_e201pr(o.kid||_e201KID,T,76,6,.48)}<rect x="-122" y="42" width="244" height="16" rx="7" fill="#C98F55" ${st()}/><rect x="-106" y="58" width="12" height="52" fill="#8B5E3C" ${st(C.navy,4)}/><rect x="94" y="58" width="12" height="52" fill="#8B5E3C" ${st(C.navy,4)}/><ellipse cx="-40" cy="41" rx="26" ry="6" fill="#fff" ${st(C.navy,3)}/><ellipse cx="46" cy="41" rx="26" ry="6" fill="#fff" ${st(C.navy,3)}/><path d="M-22 22 L22 22 Q20 42 0 42 Q-20 42 -22 22Z" fill="#E7E1D3" ${st(C.navy,3.5)}/><ellipse cx="0" cy="22" rx="22" ry="5" fill="#C86B3C" ${st(C.navy,3)}/>${steam}${mid}</g>`};

/* child asleep under blanket with a blue tablet glow */
P.e201_covers=(o,T,k)=>{const pul=.55+.45*Math.sin(T*2.4);
  const door=o.door?`<path d="M112 -112 L112 70 L84 62 L84 -104Z" fill="#A9743F" ${st()}/><path d="M84 62 L30 80 L-4 70 Z" fill="#FFE9A8" opacity=".55"/><circle cx="92" cy="-20" r="4" fill="${C.gold}"/>`:'';
  return `<g><rect x="-118" y="-112" width="76" height="86" rx="8" fill="#1C2A55" ${st()}/><line x1="-80" y1="-112" x2="-80" y2="-26" ${st(C.navy,4)}/><line x1="-118" y1="-70" x2="-42" y2="-70" ${st(C.navy,4)}/><path d="M-96 -92 a14 14 0 1 0 12 22 a11 11 0 0 1 -12 -22Z" fill="#F7E7A8"/><circle cx="-60" cy="-96" r="2.5" fill="#FFF3C4"/><circle cx="-56" cy="-50" r="2" fill="#FFF3C4"/>
  <ellipse cx="20" cy="30" rx="${f(112+pul*8)}" ry="${f(50+pul*6)}" fill="#7FC4F0" opacity="${f(.16+pul*.1)}"/>
  <rect x="-122" y="-26" width="14" height="104" rx="4" fill="#8B5E3C" ${st()}/><rect x="-122" y="58" width="244" height="18" rx="5" fill="#8B5E3C" ${st()}/><rect x="-110" y="34" width="224" height="28" rx="8" fill="#fff" ${st()}/><ellipse cx="-80" cy="26" rx="26" ry="12" fill="#F4F0E4" ${st()}/>
  <path d="M-96 52 Q-92 -4 -34 -6 Q30 -10 100 36 L106 56 Z" fill="#6FAE8C" ${st()}/><g fill="${C.gold}"><circle cx="-50" cy="24" r="4"/><circle cx="0" cy="12" r="4"/><circle cx="48" cy="30" r="4"/></g>
  <rect x="-24" y="48" width="84" height="8" rx="4" fill="#DFF3FF" opacity="${f(.5+pul*.5)}"/>${door}</g>`};

/* tablet dropped on the floor */
P.e201_tabdrop=(o,T,k)=>{const ph=(T%2.2)/2.2,fall=ease(Math.min(1,ph/.55)),y=-80+fall*130,rot=-20+fall*38,bounce=ph>.55?Math.abs(Math.sin((ph-.55)*10))*Math.max(0,1-(ph-.55)*2.2)*22:0;
  return `<g><rect x="-130" y="64" width="260" height="14" rx="5" fill="#C98F55" ${st(C.navy,4)}/><ellipse cx="0" cy="62" rx="${f(40+fall*20)}" ry="6" fill="#000" opacity="${f(.1+fall*.12)}"/><g transform="translate(0,${f(y-bounce)}) rotate(${f(rot)})"><g transform="scale(.9)">${_e201tab(160,112,_e201cartoon,'e201_ct6')}</g></g>${ph>.5?`<g transform="translate(76,-60) scale(${f(1+Math.sin(T*8)*.06)})"><circle r="26" fill="${C.gold}" ${st()}/>${_e201tx('!',0,13,38)}</g>`:''}</g>`};

/* child walking to school / club */
P.e201_walkkid=(o,T,k)=>{let dash='';for(let i=0;i<6;i++){const x=((i*60-T*60)%360+360)%360-180;dash+=`<rect x="${f(x)}" y="92" width="30" height="5" rx="2.5" fill="#fff"/>`}
  const dest=o.club?P.e201_clubhouse({},T,k):P.e10_school({},T,k);
  return `<g><g transform="translate(78,-14) scale(.46)">${dest}</g>${o.rain?'':''}<g transform="translate(-32,${f(Math.sin(T*6)*2.5)})">${_e201pr(Object.assign({bag:C.blue},_e201KID),T,0,0,.86)}</g><rect x="-150" y="70" width="300" height="42" fill="#B7C0C6" ${st()}/>${dash}<path d="M-150 70 H150" ${st(C.navy,5)}/></g>`};

/* route map: home - two big roads - market - school */
P.e201_route=(o,T,k)=>{const off=-(T*26)%24;const zebra=(x,y,w,h,v)=>{let s='';for(let i=0;i<5;i++)s+=v?`<rect x="${x}" y="${y+i*(h/5)+2}" width="${w}" height="${h/5-4}" fill="#fff"/>`:`<rect x="${x+i*(w/5)+2}" y="${y}" width="${w/5-4}" height="${h}" fill="#fff"/>`;return s};
  const cx=((T*40)%300)-150;
  return `<g><rect x="-128" y="-118" width="256" height="236" rx="22" fill="#DDEBC8" ${st()}/><rect x="-128" y="28" width="256" height="26" fill="#7C8A92"/><rect x="-6" y="-118" width="26" height="236" fill="#7C8A92"/><line x1="-128" y1="41" x2="-6" y2="41" stroke="#fff" stroke-width="3" stroke-dasharray="14 10"/><line x1="20" y1="41" x2="128" y2="41" stroke="#fff" stroke-width="3" stroke-dasharray="14 10"/>${zebra(-78,28,36,26,0)}${zebra(-6,-48,26,36,1)}<rect x="${f(cx)}" y="32" width="30" height="14" rx="5" fill="${C.red}" ${st(C.navy,3)} opacity=".95"/><path d="M-60 90 L-60 -30 L66 -30 L66 -84" fill="none" stroke="${C.gold}" stroke-width="7" stroke-linecap="round" stroke-dasharray="14 12" stroke-dashoffset="${f(off)}"/><path d="M-60 90 L-60 -30 L66 -30 L66 -84" fill="none" ${st(C.goldD,2)} opacity=".0"/><g transform="translate(-60,96) scale(.34)">${P.house({},T)}</g><g transform="translate(70,-92) scale(.34)">${P.e10_school({},T,k)}</g><g transform="translate(-96,-6)"><rect x="-22" y="-2" width="44" height="26" fill="#F2D6A2" ${st(C.navy,3.5)}/><path d="M-26 -2 L-20 -22 H20 L26 -2Z" fill="${C.red}" ${st(C.navy,3.5)}/><path d="M-12 -2 L-10 -22 M0 -2 V-22 M12 -2 L10 -22" ${st('#fff',3)}/></g></g>`};

/* road blocked after an accident: barrier + siren light */
P.e201_barrier=(o,T,k)=>{const on=Math.sin(T*7)>0;let stripes='';for(let i=0;i<6;i++)stripes+=`<polygon points="${-112+i*40},-6 ${-92+i*40},-6 ${-112+i*40+20},26 ${-132+i*40+20},26" fill="${C.red}"/>`;
  return `<g><rect x="-150" y="62" width="300" height="52" fill="#6B7A83" ${st()}/><line x1="-130" y1="90" x2="130" y2="90" stroke="#fff" stroke-width="5" stroke-dasharray="26 18"/><rect x="-100" y="20" width="12" height="46" fill="${C.navy}"/><rect x="88" y="20" width="12" height="46" fill="${C.navy}"/><clipPath id="e201_bc"><rect x="-112" y="-6" width="224" height="32" rx="6"/></clipPath><rect x="-112" y="-6" width="224" height="32" rx="6" fill="#fff"/><g clip-path="url(#e201_bc)">${stripes}</g><rect x="-112" y="-6" width="224" height="32" rx="6" fill="none" ${st()}/><circle cx="-94" cy="-16" r="${on?17:12}" fill="${on?'#FFB300':'#C98F2B'}" ${st()} /><g opacity="${on?.8:0}"><path d="M-94 -40 v-14 M-118 -34 l-10 -9 M-70 -34 l10 -9" ${st('#FFB300',5)}/></g><g transform="translate(60,-70)"><path d="M0 -46 L48 34 H-48Z" fill="${C.gold}" ${st()}/>${_e201tx('!',0,22,46)}</g><g transform="translate(-52,-62)"><circle r="0"/></g></g>`};

/* lost, wet, cold, dark */
P.e201_lostkid=(o,T,k)=>{let rain='';for(let i=0;i<16;i++){const x=-120+((i*47)%240),y=((T*260+i*37)%240)-130;rain+=`<line x1="${x}" y1="${f(y)}" x2="${x-8}" y2="${f(y+26)}" ${st(C.blue,4)} opacity=".75"/>`}
  const qs=[[-92,-70,0],[88,-80,1.5],[0,-118,3]].map(([x,y,p])=>`<g transform="translate(${x},${f(y+Math.sin(T*2+p)*5)}) rotate(${f(Math.sin(T*1.7+p)*10)})">${_e201tx('?',0,0,50,C.goldD)}</g>`).join('');
  const shiver=`<path d="M-76 6 q-8 8 0 16 M-86 2 q-8 12 0 24 M76 6 q8 8 0 16 M86 2 q8 12 0 24" fill="none" ${st(C.cold,4)} opacity="${f(.5+.5*Math.sin(T*14))}"/>`;
  return `<g>${qs}${_e201pr(Object.assign({bag:C.blue},_e201KID),T,0,24,.98)}<g transform="translate(${f(Math.sin(T*14)*1.2)},0)">${shiver}</g>${[[-20,-30],[10,-40],[24,-20]].map(([x,y])=>`<ellipse cx="${x}" cy="${y+24}" rx="4" ry="6" fill="${C.blue}" opacity=".8"/>`).join('')}${rain}</g>`};

/* phone call between child and father */
P.e201_callpair=(o,T,k)=>{const ph=(x,flip)=>`<rect x="${x-7}" y="-38" width="14" height="28" rx="4" fill="#3E5260" ${st(C.navy,3)}/>`;
  let dots='';for(let i=0;i<7;i++){const t=((T*.7+i/7)%1),x=-62+124*t,y=-96-Math.sin(t*Math.PI)*34;dots+=`<circle cx="${f(x)}" cy="${f(y)}" r="${f(3+Math.sin(t*Math.PI)*3)}" fill="${C.gold}" ${st(C.goldD,2)}/>`}
  return `<g><path d="M-62 -88 Q0 -150 62 -88" fill="none" ${st('#C9D3D9',3)} stroke-dasharray="5 7"/>${dots}${_e201pr(Object.assign({bag:C.blue},_e201KID),T,-76,26,.74)}${_e201pr(_e201DAD,T,76,18,.8)}<g transform="translate(-50,-10)">${ph(0)}</g><g transform="translate(50,-2)">${ph(0)}</g></g>`};

/* bread shop */
P.e201_breadshop=(o,T,k)=>{let aw='';for(let i=0;i<8;i++)aw+=`<path d="M${-104+i*26} -42 h26 v26 a13 13 0 0 1 -26 0Z" fill="${i%2?'#fff':C.red}" ${st(C.navy,3)}/>`;
  const loaf=(x,y,r)=>`<ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r*.5}" fill="#C98F55" ${st(C.navy,3)}/><path d="M${x-r*.4} ${y-r*.2} l${r*.2} ${-r*.2} M${x} ${y-r*.3} l${r*.2} ${-r*.2}" ${st('#F2D6A2',3)} fill="none"/>`;
  return `<g>${_e201glow(0,10,150,'#FFE08A',T)}<rect x="-104" y="-44" width="208" height="150" fill="#F2D6A2" ${st()}/><rect x="-62" y="-110" width="124" height="42" rx="8" fill="${C.brown}" ${st()}/>${_e201tx('BREAD',0,-80,30,C.cream)}${aw}<rect x="-90" y="2" width="102" height="70" fill="#FFE9A8" ${st()}/>${loaf(-64,56,22)}${loaf(-18,56,22)}${loaf(-40,32,20)}<rect x="30" y="2" width="56" height="104" fill="${C.brown}" ${st()}/><rect x="38" y="12" width="40" height="40" fill="#FFE9A8" ${st(C.navy,3)}/><circle cx="74" cy="64" r="4" fill="${C.gold}"/></g>`};

/* father and child together again */
P.e201_reunion=(o,T,k)=>{const hp=1+Math.sin(T*3.4)*.06;
  return `<g>${_e201sh(110,108)}${_e201pr(_e201DAD,T,-30,0,.9)}${_e201pr(Object.assign({bag:C.blue},_e201KID),T,52,36,.66)}${_e201hand(24,24,11)}<g transform="translate(10,-100) scale(${f(hp*.8)})"><path d="M0 28 C-62 -18 -34 -62 0 -30 C34 -62 62 -18 0 28 Z" fill="${C.red}" ${st()}/></g></g>`};

/* family phone in the hall (old landline) */
P.e201_hallphone=(o,T,k)=>{const ring=o.ring?[0,1].map(i=>{const ph=(T*1.6+i*.5)%1;return `<path d="M${f(60+ph*20)} -34 q14 24 0 48 M${f(-60-ph*20)} -34 q-14 24 0 48" fill="none" ${st(C.goldD,5)} opacity="${f(1-ph)}"/>`}).join(''):'';
  return `<g><rect x="-120" y="-116" width="240" height="232" rx="16" fill="#F3E3C3" ${st()}/><rect x="-120" y="86" width="240" height="30" fill="#B07A4A" ${st()}/><rect x="-44" y="-108" width="88" height="66" rx="6" fill="#fff" ${st(C.brown,8)}/><path d="M-36 -52 l22 -26 l16 16 l12 -12 l24 22Z" fill="${C.leaf}" ${st(C.navy,3)}/><circle cx="-18" cy="-86" r="7" fill="${C.gold}"/><rect x="-74" y="36" width="148" height="12" rx="5" fill="#B07A4A" ${st()}/><rect x="-62" y="48" width="12" height="62" fill="#8B5E3C" ${st(C.navy,4)}/><rect x="50" y="48" width="12" height="62" fill="#8B5E3C" ${st(C.navy,4)}/><path d="M-50 36 q50 -12 100 0 l-6 6 h-88Z" fill="#fff" ${st(C.navy,3)}/><path d="M-50 36 C-44 6 -26 0 0 0 C26 0 44 6 50 36Z" fill="#2B3D48" ${st()}/><circle cx="0" cy="18" r="18" fill="${C.cream}" ${st(C.navy,3.5)}/>${[0,1,2,3,4,5].map(i=>`<circle cx="${f(Math.cos(i*1.05)*11)}" cy="${f(18+Math.sin(i*1.05)*11)}" r="2.6" fill="${C.navy}"/>`).join('')}<path d="M-56 -4 q56 -34 112 0 q4 8 -8 10 q-48 -22 -96 0 q-12 -2 -8 -10Z" fill="#3E5260" ${st()}/>${ring}</g>`};

/* city built from cardboard boxes in the garden */
P.e201_boxcity=(o,T,k)=>{const bx=(x,y,w,h,win)=>{let s=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#D9A566" ${st()}/><rect x="${x+w/2-5}" y="${y}" width="10" height="${h}" fill="#EFD3A0" opacity=".7"/>`;for(let i=0;i<win;i++)s+=`<rect x="${x+8+(i%2)*(w/2-4)}" y="${y+10+Math.floor(i/2)*20}" width="12" height="12" fill="#FFE9A8" ${st(C.navy,2.5)}/>`;return s};
  const fl=Math.sin(T*3)*4;
  return `<g><ellipse cx="0" cy="104" rx="140" ry="24" fill="${C.leaf}" ${st()}/><circle cx="96" cy="-82" r="28" fill="${C.gold}" ${st(C.goldD,5)}/>${bx(-110,50,64,54,2)}${bx(-40,26,56,78,4)}${bx(26,56,52,48,2)}${bx(80,36,44,68,2)}${bx(-30,-14,38,40,2)}<line x1="-12" y1="-14" x2="-12" y2="-48" ${st(C.navy,4)}/><path d="M-12 -48 l30 ${f(8+fl*.5)} l-30 12Z" fill="${C.red}" ${st(C.navy,3)}/><rect x="-92" y="76" width="16" height="28" fill="#8B5E3C" ${st(C.navy,3)}/><rect x="40" y="82" width="14" height="22" fill="#8B5E3C" ${st(C.navy,3)}/></g>`};

/* playing football in the street until dark */
P.e201_streetball=(o,T,k)=>{const h=(x,y,c,r)=>`<g transform="translate(${x},${y})"><rect x="-26" y="-6" width="52" height="46" fill="${c}" ${st(C.navy,4)}/><path d="M-32 -6 L0 -36 L32 -6Z" fill="${r}" ${st(C.navy,4)}/><rect x="-7" y="14" width="14" height="26" fill="${C.brown}" ${st(C.navy,3)}/><rect x="9" y="2" width="10" height="10" fill="#FFE9A8" ${st(C.navy,2.5)}/></g>`;
  const by=Math.abs(Math.sin(T*3.4))*46;
  return `<g>${h(-84,-56,'#F2D6A2',C.red)}${h(0,-62,'#E7C6B8','#4DA3D8')}${h(84,-56,'#DDEBC8','#8E6BB5')}<rect x="-150" y="-20" width="300" height="110" fill="#8E9AA1" ${st()}/><path d="M-130 36 H130" stroke="#fff" stroke-width="5" stroke-dasharray="24 16"/><g transform="translate(-72,${f(36+Math.sin(T*5)*3)})">${P.person({c:'#4DA3D8',hair:'short',hc:'#222',ph:0},T).replace(/^<g/,'<g transform="scale(.38)"')}</g><g transform="translate(76,${f(34+Math.sin(T*5+1.5)*3)})">${P.person({c:C.red,hair:'short',hc:'#3A2A22',ph:2},T).replace(/^<g/,'<g transform="scale(.38)"')}</g><ellipse cx="2" cy="86" rx="${f(20-by*.15)}" ry="5" fill="#000" opacity=".15"/><g transform="translate(2,${f(66-by)}) scale(.3) rotate(${f(T*140)})">${P.e20_football({},T)}</g></g>`};

/* mother calling the children from the window */
P.e201_windowmum=(o,T,k)=>{const w=[0,1,2].map(i=>{const ph=(T*1.5+i*.33)%1;return `<path d="M${f(74+ph*30)} ${-8-i*0} q${14+ph*8} 22 0 44" fill="none" ${st(C.goldD,5)} opacity="${f(1-ph)}"/>`}).join('');
  return `<g><rect x="-112" y="-116" width="224" height="232" rx="16" fill="#E8B9A0" ${st()}/><rect x="-66" y="-76" width="132" height="132" fill="#F08A6C" ${st(C.brown,10)}/><clipPath id="e201_wm"><rect x="-62" y="-72" width="124" height="124"/></clipPath><rect x="-62" y="-72" width="124" height="70" fill="#7A6AA5" clip-path="url(#e201_wm)"/><g clip-path="url(#e201_wm)">${_e201pr(_e201MUM,T,0,34,.74)}<path d="M-62 -72 L-34 -72 L-62 -30Z M62 -72 L34 -72 L62 -30Z" fill="${C.cream}"/></g>${_e201hand(30,-4,9)}<rect x="-76" y="52" width="152" height="14" rx="5" fill="${C.brown}" ${st()}/><g transform="translate(0,2)">${w}</g></g>`};

/* arguments at school follow the child home through the phone */
P.e201_followhome=(o,T,k)=>{let b='';for(let i=0;i<3;i++){const t=((T*.45+i/3)%1),x=96-t*196,y=20-Math.sin(t*Math.PI)*46;b+=`<g transform="translate(${f(x)},${f(y)}) scale(${f(.55+Math.sin(t*Math.PI)*.2)})" opacity="${f(Math.min(1,t*5)*Math.min(1,(1-t)*5))}"><path d="M-30 -22 h60 a10 10 0 0 1 10 10 v26 a10 10 0 0 1 -10 10 h-34 l-14 14 v-14 h-12 a10 10 0 0 1 -10 -10 v-26 a10 10 0 0 1 10 -10Z" fill="${C.red}" ${st()}/>${_e201tx('!',0,12,36,'#fff')}</g>`}
  return `<g><path d="M92 40 Q0 -34 -96 40" fill="none" ${st('#C9D3D9',3)} stroke-dasharray="6 8"/><g transform="translate(88,-18) scale(.46)">${P.e10_school({},T,k)}</g><g transform="translate(-86,0) scale(.56)">${P.house({},T)}</g><g transform="translate(-92,36) scale(.2)">${_e201smartBody('','e201_cs3',{w:100,h:170})}</g>${b}</g>`};

const _e201burst=(r,col,T,txt)=>{let p='';for(let i=0;i<12;i++){const a=i*Math.PI/6,rr=i%2?r*.68:r;p+=`${f(Math.cos(a)*rr)},${f(Math.sin(a)*rr)} `}return `<g transform="rotate(${f(Math.sin((T||0)*3)*4)})"><polygon points="${p}" fill="${col}" ${st()}/>${txt?_e201tx(txt,0,r*.3,r*.9,'#fff'):''}</g>`};

/* child alone in the dark at night with a message */
P.e201_nightkid=(o,T,k)=>{const pul=.6+.4*Math.sin(T*3);
  return `<g><rect x="-122" y="-112" width="244" height="228" rx="22" fill="#1B2348" ${st()}/><rect x="-104" y="-96" width="58" height="66" rx="6" fill="#2C3A78" ${st(C.navy,4)}/><path d="M-84 -84 a12 12 0 1 0 10 18 a9 9 0 0 1 -10 -18Z" fill="#F7E7A8"/><circle cx="-60" cy="-50" r="2" fill="#FFF3C4"/>${_e201tx(o.t||'11:00 PM',54,-66,24,C.gold)}${_e201glow(0,40,70,'#9FD6FF',T)}${_e201pr({c:'#5E6FBF',hair:'short',hc:'#3A2A22'},T,0,38,.74)}<g transform="translate(0,56) rotate(-6) scale(.3)">${_e201smartBody('','e201_cs4',{w:100,h:170,bg:'#E8F6FF'})}</g><g transform="translate(70,-14) scale(${f(.4+pul*.04)})">${_e201burst(40,C.red,T,'!')}</g></g>`};

/* top-down desk: phone face down */
P.e201_facedown=(o,T,k)=>`<g><rect x="-124" y="-104" width="248" height="210" rx="18" fill="#D9A566" ${st()}/><path d="M-124 -40 H124 M-124 20 H124 M-124 80 H124" stroke="#C48E4E" stroke-width="3" fill="none" opacity=".6"/><rect x="-104" y="-82" width="116" height="156" rx="6" fill="${C.paper}" ${st()} transform="rotate(-4)"/>${[-50,-30,-10,10,30,50].map(y=>`<line x1="-88" y1="${y}" x2="-6" y2="${y}" ${st('#9AA7B0',3)} transform="rotate(-4)"/>`).join('')}<rect x="-70" y="68" width="110" height="9" rx="4.5" fill="${C.gold}" ${st()} transform="rotate(-24 -14 70)"/><circle cx="72" cy="-62" r="26" fill="#fff" ${st()}/><circle cx="72" cy="-62" r="17" fill="#6B4226"/><path d="M98 -62 a14 14 0 0 1 0 20" fill="none" ${st(C.navy,5)}/><g transform="translate(${f(Math.sin(T*18)*(o.buzz?1.5:0))},0)"><rect x="32" y="-6" width="76" height="118" rx="16" fill="#3E5260" ${st()}/><rect x="40" y="2" width="30" height="30" rx="9" fill="#2B3D48" ${st(C.navy,3)}/><circle cx="55" cy="17" r="7" fill="#101820" ${st('#8EA1AD',3)}/><circle cx="70" cy="62" r="13" fill="#4C6272" ${st(C.navy,3)}/></g></g>`;

/* child at desk: homework + phone lighting up */
P.e201_hwdesk=(o,T,k)=>{const pu=1+Math.sin(T*6)*.07;
  return `<g>${_e201pr({c:'#4DA3D8',hair:'short',hc:'#222'},T,-30,-8,.7)}<rect x="-124" y="46" width="248" height="16" rx="7" fill="#C98F55" ${st()}/><rect x="-110" y="62" width="12" height="48" fill="#8B5E3C" ${st(C.navy,4)}/><rect x="98" y="62" width="12" height="48" fill="#8B5E3C" ${st(C.navy,4)}/><path d="M-90 46 L-70 12 H-6 L-6 46Z M-6 46 V12 H58 L38 46Z" fill="#fff" ${st(C.navy,4)}/>${[22,32].map(y=>`<line x1="-62" y1="${y}" x2="-14" y2="${y}" ${st('#9AA7B0',3)}/><line x1="4" y1="${y}" x2="48" y2="${y}" ${st('#9AA7B0',3)}/>`).join('')}<rect x="30" y="30" width="62" height="8" rx="4" fill="${C.gold}" ${st(C.navy,3)} transform="rotate(-14 60 34)"/><g transform="translate(92,6) scale(.4)">${_e201smartBody('<rect x="-40" y="-60" width="80" height="30" rx="8" fill="#fff"/><rect x="-40" y="-20" width="80" height="30" rx="8" fill="#fff"/>','e201_cs5',{w:100,h:170})}</g><g transform="translate(112,-34) scale(${f(pu*.9)})"><circle r="18" fill="${C.red}" ${st()}/>${_e201tx('1',0,8,24,'#fff')}</g></g>`};

/* waiting for the next video */
P.e201_nextvideo=(o,T,k)=>{const pr=(T*.35)%1;let th='';for(let i=0;i<3;i++){const x=-60+i*66-((T*30)%66);th+=`<rect x="${f(x)}" y="58" width="54" height="40" rx="8" fill="${_e201AC[(i+Math.floor(T*30/66))%8]}" ${st(C.navy,3.5)}/><polygon points="${f(x+22)},68 ${f(x+36)},78 ${f(x+22)},88" fill="#fff"/>`}
  return `<g><rect x="-112" y="-96" width="224" height="140" rx="16" fill="${C.navy}" ${st()}/><clipPath id="e201_nv"><rect x="-102" y="-86" width="204" height="106" rx="8"/></clipPath><rect x="-102" y="-86" width="204" height="106" rx="8" fill="#BFE3F2"/><g clip-path="url(#e201_nv)"><circle cx="-50" cy="-52" r="16" fill="${C.gold}"/><ellipse cx="40" cy="-56" rx="26" ry="11" fill="#fff"/><rect x="-110" y="-4" width="220" height="30" fill="${C.leaf}"/></g><circle cx="0" cy="-34" r="22" fill="${C.red}" ${st('#fff',4)}/><polygon points="-7,-46 14,-34 -7,-22" fill="#fff"/><rect x="-96" y="28" width="192" height="8" rx="4" fill="#5B6B75"/><rect x="-96" y="28" width="${f(192*pr)}" height="8" rx="4" fill="${C.red}"/><clipPath id="e201_nv2"><rect x="-112" y="52" width="224" height="52"/></clipPath><g clip-path="url(#e201_nv2)">${th}</g><g transform="translate(78,-102)"><rect x="-32" y="-14" width="64" height="28" rx="14" fill="${C.gold}" ${st()}/>${_e201tx('NEXT',0,7,19)}</g></g>`};

/* balance scale */
P.e201_scale=(o,T,k)=>{const ang=((o.tilt||0)+Math.sin(T*1.6)*3)*Math.PI/180,L=92,px=Math.cos(ang)*L,py=Math.sin(ang)*L;
  const pan=(x,y,inner)=>`<g transform="translate(${f(x)},${f(y)})"><path d="M0 0 L-34 54 M0 0 L34 54" ${st(C.navy,3)}/><path d="M-44 54 H44 Q38 76 0 76 Q-38 76 -44 54Z" fill="${C.gold2}" ${st()}/><g transform="translate(0,52)">${inner}</g></g>`;
  const left=`<g transform="translate(0,-46) scale(.34)">${_e201smartBody('','e201_cs6',{w:100,h:170})}</g>`;
  const right=o.work?`<g transform="translate(-16,-24)"><rect x="-26" y="-12" width="52" height="36" fill="#fff" ${st(C.navy,3.5)}/><line x1="0" y1="-12" x2="0" y2="24" ${st(C.navy,3)}/></g><g transform="translate(26,-18)"><circle r="17" fill="#fff" ${st(C.navy,3.5)}/><polygon points="0,-8 8,-2 5,8 -5,8 -8,-2" fill="${C.navy}"/></g>`:`<g transform="translate(-20,-20)"><rect x="-22" y="-14" width="44" height="30" fill="${C.red}" ${st(C.navy,3.5)}/><line x1="0" y1="-14" x2="0" y2="16" ${st('#fff',3)}/></g><g transform="translate(24,-18)"><circle r="19" fill="#fff" ${st(C.navy,3.5)}/><polygon points="0,-9 9,-3 5,9 -5,9 -9,-3" fill="${C.navy}"/></g><g transform="translate(2,-48)"><circle r="14" fill="${C.leaf}" ${st(C.navy,3.5)}/></g>`;
  return `<g><ellipse cx="0" cy="108" rx="52" ry="10" fill="${C.navy}" opacity=".85"/><rect x="-8" y="-40" width="16" height="148" rx="6" fill="${C.brown}" ${st()}/><line x1="${f(-px)}" y1="${f(-40+py)}" x2="${f(px)}" y2="${f(-40-py)}" ${st(C.navy,9)}/><circle cx="0" cy="-40" r="12" fill="${C.gold}" ${st()}/>${pan(-px,-40+py,left)}${pan(px,-40-py,right)}</g>`};

/* board game */
P.e201_boardgame=(o,T,k)=>{let sq='';for(let r=0;r<6;r++)for(let c=0;c<6;c++)sq+=`<rect x="${-72+c*24}" y="${-72+r*24}" width="24" height="24" fill="${(r+c)%2?'#6FAE8C':'#F4EFE0'}"/>`;
  const pawn=(x,y,col)=>`<g transform="translate(${x},${y})"><path d="M-9 14 Q-8 -4 0 -6 Q8 -4 9 14Z" fill="${col}" ${st(C.navy,3)}/><circle cy="-12" r="8" fill="${col}" ${st(C.navy,3)}/></g>`;
  return `<g><g transform="rotate(${f(Math.sin(T*1.2)*2)})">${_e201sh(86,96)}<rect x="-80" y="-80" width="160" height="160" rx="10" fill="${C.brown}" ${st()}/><g transform="translate(0,0)">${sq}</g><rect x="-72" y="-72" width="144" height="144" fill="none" ${st(C.navy,3)}/>${pawn(-36,-30,C.red)}${pawn(30,18,C.blue)}<g transform="translate(${f(56)},${f(-44+Math.sin(T*3)*2)}) rotate(14)"><rect x="-17" y="-17" width="34" height="34" rx="7" fill="#fff" ${st(C.navy,3.5)}/><circle cx="-7" cy="-7" r="3.5" fill="${C.navy}"/><circle cx="7" cy="7" r="3.5" fill="${C.navy}"/><circle cx="0" cy="0" r="3.5" fill="${C.navy}"/><circle cx="-7" cy="7" r="3.5" fill="${C.navy}"/><circle cx="7" cy="-7" r="3.5" fill="${C.navy}"/></g></g></g>`};

/* child tired at school desk */
P.e201_deskzzz=(o,T,k)=>{let z='';for(let i=0;i<3;i++){const ph=(T*.8+i/3)%1;z+=`<text x="${f(40+ph*40+i*8)}" y="${f(-20-ph*70)}" font-family="Fraunces" font-weight="800" font-size="${30+i*8}" fill="${C.goldD}" opacity="${f(1-ph)}">Z</text>`}
  return `<g>${z}<path d="M-70 60 Q-72 -6 -10 -8 Q56 -8 66 60Z" fill="#4DA3D8" ${st()}/><circle cx="-4" cy="-14" r="38" fill="${_e201SK}" ${st()}/><path d="M-42 -22 Q-40 -62 -2 -58 Q38 -58 36 -26 Q8 -36 -42 -22Z" fill="#222" ${st()}/><rect x="-100" y="46" width="200" height="18" rx="8" fill="#C98F55" ${st()}/><rect x="-84" y="64" width="12" height="46" fill="#8B5E3C" ${st(C.navy,4)}/><rect x="72" y="64" width="12" height="46" fill="#8B5E3C" ${st(C.navy,4)}/><rect x="-62" y="26" width="124" height="24" rx="12" fill="#4DA3D8" ${st()}/><rect x="-54" y="20" width="62" height="16" rx="8" fill="${_e201SK}" ${st(C.navy,3.5)}/></g>`};

/* holiday pictures on the phone */
P.e201_beachfeed=(o,T,k)=>{const inner=`<rect x="-42" y="-70" width="84" height="64" rx="6" fill="#BFE3F2" ${st(C.navy,3)}/><circle cx="-18" cy="-52" r="9" fill="${C.gold}"/><rect x="-42" y="-34" width="84" height="28" fill="${C.blue}"/><path d="M-42 -30 q10 -6 21 0 t21 0 t21 0 t21 0" fill="none" ${st('#fff',3)}/><path d="M14 -50 q14 -16 30 0Z" fill="${C.red}" ${st(C.navy,2.5)}/><line x1="29" y1="-50" x2="29" y2="-24" ${st(C.navy,3)}/><rect x="-42" y="2" width="84" height="64" rx="6" fill="#E7D3A6" ${st(C.navy,3)}/><rect x="-26" y="12" width="52" height="44" fill="#F4EFE0" ${st(C.navy,2.5)}/>${[0,1,2].map(r=>[0,1,2].map(c=>`<rect x="${-20+c*16}" y="${16+r*13}" width="9" height="8" fill="#FFE08A"/>`).join('')).join('')}<rect x="-42" y="56" width="84" height="10" fill="${C.blue}"/>`;
  const hs=[0,1,2].map(i=>{const ph=(T*.6+i/3)%1;return `<g transform="translate(${f(62+Math.sin(ph*6+i)*8)},${f(40-ph*130)}) scale(${f(.3+ph*.15)})" opacity="${f(1-ph)}"><path d="M0 28 C-62 -18 -34 -62 0 -30 C34 -62 62 -18 0 28 Z" fill="${C.red}" ${st()}/></g>`}).join('');
  return `<g>${_e201sh(60,108)}${_e201smartBody(inner,'e201_cs7')}${hs}</g>`};

/* car with a family arguing */
P.e201_carfam=(o,T,k)=>`<g>${_e201sh(100,92)}<g transform="translate(0,22) scale(.9)">${P.car({},T)}</g><g transform="translate(-56,-60) scale(.5)">${_e201burst(52,C.red,T,'!')}</g><g transform="translate(34,-84) scale(.42)">${_e201burst(52,C.orange,T+1,'!')}</g></g>`;

/* an expensive bill */
P.e201_bill=(o,T,k)=>`<g><g transform="translate(-44,0) rotate(-5)"><path d="M-60 -100 H60 V92 L48 84 L36 92 L24 84 L12 92 L0 84 L-12 92 L-24 84 L-36 92 L-48 84 L-60 92Z" fill="#fff" ${st()}/>${[-70,-50,-30,-10,10,30].map((y,i)=>`<line x1="-42" y1="${y}" x2="${i%2?14:30}" y2="${y}" ${st('#9AA7B0',4)}/><line x1="${i%2?30:40}" y1="${y}" x2="42" y2="${y}" ${st(C.navy,4)} opacity=".6"/>`).join('')}<rect x="-42" y="46" width="84" height="20" rx="6" fill="${C.gold}" ${st(C.navy,3)}/></g><g transform="translate(78,28) scale(.62)">${P.coins({},T)}</g></g>`;

/* a stranger online pretending to be a child */
P.e201_stranger=(o,T,k)=>{const bob=Math.sin(T*2)*3;
  return `<g><g transform="translate(-72,${f(-6)}) scale(.5)">${_e201smartBody(`<rect x="-34" y="-60" width="52" height="30" rx="10" fill="${C.blue}"/><rect x="-14" y="-18" width="52" height="30" rx="10" fill="#fff" ${st(C.navy,3)}/><circle cx="-4" cy="-3" r="3" fill="${C.navy}"/><circle cx="8" cy="-3" r="3" fill="${C.navy}"/><circle cx="20" cy="-3" r="3" fill="${C.navy}"/>`,'e201_cs8',{w:100,h:190})}</g><g transform="translate(58,${f(bob)})"><path d="M-60 100 L-60 36 Q-60 -2 0 -2 Q60 -2 60 36 L60 100Z" fill="#46535C" ${st()}/><circle cx="0" cy="-46" r="38" fill="#2F3B43" ${st()}/><path d="M-38 -50 Q-30 -92 0 -92 Q30 -92 38 -50 Q0 -70 -38 -50Z" fill="#46535C" ${st()}/><g transform="translate(0,22) scale(.52)"><path d="M-40 70 L-40 20 Q-40 -8 0 -8 Q40 -8 40 20 L40 70Z" fill="none" stroke="${C.gold}" stroke-width="6" stroke-dasharray="9 8"/><circle cx="0" cy="-42" r="28" fill="none" stroke="${C.gold}" stroke-width="6" stroke-dasharray="9 8"/></g><g transform="translate(36,-100)">${_e201tx('?',0,0,52,C.goldD)}</g></g></g>`};

/* boy climbs a high wall to copy a trend */
P.e201_wall=(o,T,k)=>{let br='';for(let r=0;r<6;r++){br+=`<line x1="-90" y1="${-20+r*20}" x2="90" y2="${-20+r*20}" ${st('#9E5A3A',3)}/>`;for(let c=0;c<5;c++)br+=`<line x1="${-90+c*36+(r%2?18:0)}" y1="${-20+r*20}" x2="${-90+c*36+(r%2?18:0)}" y2="${r<5?-20+(r+1)*20:100}" ${st('#9E5A3A',3)}/>`}
  const ph=(T%2.4)/2.4,fall=ease(clamp((ph-.35)/.55)),x=-10+fall*80,y=-96+fall*166;
  return `<g><rect x="-100" y="-30" width="200" height="130" fill="#C9744D" ${st()}/><g transform="translate(0,10)">${br}</g><rect x="-110" y="-38" width="220" height="14" rx="4" fill="#B3603B" ${st()}/><rect x="-130" y="100" width="260" height="12" fill="${C.leaf}" ${st()}/><g transform="translate(${f(x)},${f(y)}) rotate(${f(fall*70)})"><g transform="scale(.36)">${P.person({c:'#4DA3D8',hair:'short',hc:'#222'},0)}</g></g><path d="M20 -90 Q92 -80 96 40" fill="none" ${st(C.red,4)} stroke-dasharray="8 8"/><polygon points="96,52 86,34 106,36" fill="${C.red}"/></g>`};

/* viral video with hearts */
P.e201_viral=(o,T,k)=>{const hs=[0,1,2,3].map(i=>{const ph=(T*.7+i/4)%1;return `<g transform="translate(${f(-60+i*40+Math.sin(ph*7+i)*10)},${f(30-ph*140)}) scale(${f(.3+ph*.12)})" opacity="${f(1-ph)}"><path d="M0 28 C-62 -18 -34 -62 0 -30 C34 -62 62 -18 0 28 Z" fill="${i%2?C.red:'#E07BA0'}" ${st()}/></g>`}).join('');
  const inner=`<rect x="-44" y="-86" width="88" height="110" fill="#BFE3F2"/><rect x="-44" y="-10" width="88" height="34" fill="${C.leaf}"/><circle cx="-18" cy="-60" r="11" fill="${C.gold}"/><circle cx="0" cy="-34" r="20" fill="${C.red}" ${st('#fff',3)}/><polygon points="-6,-44 12,-34 -6,-24" fill="#fff"/><rect x="-34" y="46" width="68" height="8" rx="4" fill="#9AA7B0"/><rect x="-34" y="66" width="46" height="8" rx="4" fill="#9AA7B0"/><circle cx="30" cy="70" r="9" fill="${C.red}"/>`;
  return `<g>${_e201sh(60,108)}${_e201smartBody(inner,'e201_cs9')}${hs}</g>`};

/* child's poster with three reasons */
P.e201_poster=(o,T,k)=>{let r='';for(let i=0;i<3;i++){const p=ease((k-.35*i-.2)/.4);r+=`<g transform="translate(0,${-12+i*50})" opacity="${f(clamp(p+(k>9?1:0)))}"><circle cx="-62" cy="0" r="17" fill="${C.gold}" ${st()}/>${_e201tx(i+1,-62,8,22)}<line x1="-34" y1="-6" x2="${40+(i%2)*14}" y2="-6" ${st('#9AA7B0',5)}/><line x1="-34" y1="8" x2="${14+(i%2)*20}" y2="8" ${st('#9AA7B0',5)}/><path d="M60 0 l9 10 l18 -22" fill="none" ${st(C.moss,6)}/></g>`}
  return `<g><g transform="rotate(${f(Math.sin(T*1.4)*1.5)})"><rect x="-104" y="-116" width="208" height="232" rx="10" fill="${C.paper}" ${st()}/><circle cx="0" cy="-116" r="9" fill="${C.red}" ${st()}/><g transform="translate(0,-66) scale(.34)">${P.e201_smart({},0,9)}</g>${r}</g></g>`};

/* row of children (some with phones) */
P.e201_kids=(o,T,k)=>{const n=o.n||6,cols=[C.red,C.blue,C.moss,C.orange,'#8E6BB5','#E07BA0','#3FB8AF'],hs=['short','long','bun','short','long','bun','short'],hc=['#3A2A22','#1E2B33','#6A3F26','#222','#8B5E3C','#3A2A22','#2A1D18'];let s='';const gap=(o.w||250)/Math.max(1,n-1),sc=o.s||.46;
  for(let i=0;i<n;i++){const x=-(o.w||250)/2+i*gap,has=o.ph!=null&&i<o.ph,wk=o.walk?Math.sin(T*6+i)*3:0;s+=`<g transform="translate(${f(x)},${f(20+wk)})">${has?_e201glow(0,-10,40,'#9FD6FF',T):''}${_e201pr({c:cols[i%7],hair:hs[i%7],hc:hc[i%7],bag:o.bag?cols[(i+3)%7]:null,ph:i},T,0,0,sc)}${has?`<g transform="translate(14,22) rotate(10) scale(.17)">${_e201smartBody('','e201_ck'+i,{w:100,h:170})}</g>`:''}</g>`}
  return `<g>${s}</g>`};

/* prohibition sign over a device */
P.e201_ban=(o,T,k)=>{const w=o.what||'smart',pu=1+Math.sin(T*4)*.02;const dev=w==='tab'?`<g transform="scale(.7)">${_e201tab(160,112,_e201cartoon,'e201_ct7')}</g>`:w==='simple'?`<g transform="scale(.8)">${P.e201_simple({},0,9)}</g>`:`<g transform="scale(.82)">${_e201smartBody('<rect x="-30" y="-60" width="60" height="30" rx="8" fill="#fff"/><rect x="-30" y="-20" width="60" height="30" rx="8" fill="#fff"/>','e201_cs10')}</g>`;
  return `<g>${dev}<g transform="scale(${f(pu)})"><circle r="108" fill="none" stroke="${C.red}" stroke-width="16"/><line x1="-76" y1="-76" x2="76" y2="76" stroke="${C.red}" stroke-width="16" stroke-linecap="round"/></g></g>`};

/* phones charging in a basket in the kitchen */
P.e201_phonetray=(o,T,k)=>{const ph=(x,y,r,s,simple)=>`<g transform="translate(${x},${y}) rotate(${r}) scale(${s})">${simple?P.e201_simple({},0,9):_e201smartBody('<rect x="-30" y="-60" width="60" height="30" rx="8" fill="#fff"/><rect x="-30" y="-20" width="60" height="30" rx="8" fill="#fff"/>','e201_cs11')}</g>`;
  return `<g><rect x="-130" y="64" width="260" height="46" rx="8" fill="#C98F55" ${st()}/><rect x="-130" y="64" width="260" height="12" fill="#E3B27A" ${st()}/>${ph(-48,-4,-10,.62)}${ph(-6,-14,2,.62)}${ph(38,-8,10,.62)}${ph(78,2,16,.52,1)}<path d="M-84 40 H84 L72 92 H-72Z" fill="#D9A566" ${st()}/>${[48,62,76].map(y=>`<line x1="${-80+(y-40)*.2}" y1="${y}" x2="${80-(y-40)*.2}" y2="${y}" ${st('#B3803F',3)}/>`).join('')}<path d="M-30 92 q-20 20 -60 6 t-30 -20" fill="none" ${st(C.navy,4)}/><rect x="-124" y="64" width="18" height="24" rx="4" fill="#fff" ${st(C.navy,3)}/><path d="M-110 -80 a30 30 0 1 0 24 44 a24 24 0 0 1 -24 -44Z" fill="#F7E7A8" ${st()} transform="translate(210,-24) scale(.9)"/></g>`};

/* shield with phone */
P.e201_safephone=(o,T,k)=>`<g>${_e201glow(0,0,130,'#9FD6FF',T)}<path d="M0 -112 L92 -82 V-6 Q92 66 0 112 Q-92 66 -92 -6 V-82Z" fill="${C.blue}" ${st()}/><path d="M0 -112 L92 -82 V-6 Q92 66 0 112Z" fill="#6FB1D6" opacity=".6"/><g transform="translate(0,6) scale(.6)">${P.e201_simple({},T,9)}</g><g transform="translate(58,-70)"><circle r="22" fill="${C.moss}" ${st()}/><path d="M-10 0 l8 9 l14 -18" fill="none" ${st('#fff',6)}/></g></g>`;

const _e201arm=(x1,y1,x2,y2,col)=>`<path d="M${x1} ${y1} L${x2} ${y2}" stroke="${C.navy}" stroke-width="17" stroke-linecap="round" fill="none"/><path d="M${x1} ${y1} L${x2} ${y2}" stroke="${col}" stroke-width="10" stroke-linecap="round" fill="none"/>`;
const _e201heart=(s,col)=>`<g transform="scale(${f(s)})"><path d="M0 28 C-62 -18 -34 -62 0 -30 C34 -62 62 -18 0 28 Z" fill="${col||C.red}" ${st()}/></g>`;
const _e201lock=(s,col)=>`<g transform="scale(${f(s)})"><path d="M-22 -8 V-30 a22 22 0 0 1 44 0 V-8" fill="none" ${st(C.navy,9)}/><rect x="-34" y="-8" width="68" height="54" rx="10" fill="${col||C.gold}" ${st()}/><circle cx="0" cy="14" r="7" fill="${C.navy}"/><rect x="-3" y="16" width="6" height="16" rx="3" fill="${C.navy}"/></g>`;

/* adult and child holding hands */
P.e201_holdhands=(o,T,k)=>`<g>${_e201sh(110,108)}${_e201pr(_e201MUM,T,-48,-6,.82)}${_e201pr(Object.assign({bag:C.blue},_e201KID),T,58,32,.62)}${_e201arm(-12,58,18,70,_e201MUM.c)}${_e201arm(36,76,18,70,_e201KID.c)}${_e201hand(18,70,9)}<g transform="translate(6,-100) rotate(${f(Math.sin(T*2)*6)})">${_e201heart(.8+Math.sin(T*3.4)*.04)}</g></g>`;

/* adult and child looking at a phone together */
P.e201_sharephone=(o,T,k)=>`<g>${_e201sh(110,108)}${_e201pr(_e201MUM,T,-52,-6,.8)}${_e201pr(_e201KID,T,52,16,.66)}<g transform="translate(0,${f(34+Math.sin(T*2)*2)}) rotate(-6) scale(.52)">${P.e201_smart({},T,9)}</g>${_e201hand(-26,60,9)}${_e201hand(26,64,9)}</g>`;

/* a door left open */
P.e201_opendoor=(o,T,k)=>`<g><rect x="-122" y="-116" width="244" height="232" rx="16" fill="#E8D3B0" ${st()}/><rect x="-122" y="70" width="244" height="46" fill="#B07A4A" ${st()}/><rect x="-52" y="-96" width="104" height="170" fill="#FFE9A8" ${st(C.brown,9)}/><path d="M-52 74 L-110 110 H110 L52 74Z" fill="#FFE08A" opacity="${f(.55+.15*Math.sin(T*2))}"/><path d="M-52 -96 L-98 -80 V92 L-52 74Z" fill="#A9743F" ${st()}/><path d="M-78 -62 V54" ${st('#8B5E3C',4)}/><circle cx="-62" cy="-8" r="5" fill="${C.gold}"/><rect x="-40" y="88" width="80" height="16" rx="6" fill="${C.red}" ${st()} opacity=".0"/><g transform="translate(18,-18) rotate(${f(Math.sin(T*2.4)*5)})">${_e201heart(.7+Math.sin(T*3)*.04)}</g></g>`;

/* child hiding the phone behind their back */
P.e201_secret=(o,T,k)=>{const dr=[0,1].map(i=>{const ph=(T*1.3+i*.5)%1;return `<path d="M${-46+i*92} ${f(-60+ph*30)} q5 8 0 13 q-5 -5 0 -13Z" fill="${C.blue}" ${st(C.navy,2)} opacity="${f(1-ph)}"/>`}).join('');
  return `<g>${_e201sh(80,108)}<g transform="translate(58,50) rotate(18) scale(.4)">${_e201smartBody('<rect x="-30" y="-60" width="60" height="30" rx="8" fill="#fff"/>','e201_cs12',{w:100,h:170})}</g>${_e201pr(Object.assign({},_e201GIRL),T,0,14,.92)}${_e201hand(48,70,9)}${dr}<g transform="translate(-70,-84) scale(.4)">${_e201burst(52,C.red,T,'!')}</g></g>`};

/* smartphone locked until a certain age */
P.e201_agelock=(o,T,k)=>`<g>${_e201sh(60,108)}<g transform="scale(.9)">${P.e201_smart({},T,9)}</g><g transform="translate(46,58) scale(${f(.95+Math.sin(T*3)*.03)})">${_e201lock(.8)}</g><g transform="translate(-52,-82)"><circle r="36" fill="${C.gold}" ${st()}/><circle r="28" fill="none" ${st(C.goldD,3)}/>${_e201tx(o.n==null?12:o.n,0,13,38)}</g></g>`;

/* from a child with a simple phone to an older child with a smartphone */
P.e201_grow=(o,T,k)=>`<g><rect x="-140" y="94" width="280" height="10" rx="5" fill="${C.leaf}" ${st()}/>${_e201pr(Object.assign({bag:C.blue},_e201KID),T,-84,48,.5)}<g transform="translate(-52,52) rotate(12) scale(.26)">${P.e201_simple({},0,9)}</g>${_e201pr({c:'#3FB8AF',hair:'short',hc:'#222'},T,84,10,.78)}<g transform="translate(66,62) rotate(-8) scale(.3)">${P.e201_smart({},0,9)}</g><path d="M-28 -20 H34" ${st(C.gold,9)}/><polygon points="44,-20 24,-36 24,-4" fill="${C.gold}" ${st(C.goldD,3)}/></g>`;

/* football shirt */
P.e201_shirt=(o,T,k)=>`<g>${_e201sh(86,104)}<clipPath id="e201_sh1"><path d="M-42 -80 L-16 -94 Q0 -78 16 -94 L42 -80 L88 -38 L64 -6 L46 -24 V96 H-46 V-24 L-64 -6 L-88 -38Z"/></clipPath><path d="M-42 -80 L-16 -94 Q0 -78 16 -94 L42 -80 L88 -38 L64 -6 L46 -24 V96 H-46 V-24 L-64 -6 L-88 -38Z" fill="${C.red}"/><g clip-path="url(#e201_sh1)">${[-30,0,30].map(x=>`<rect x="${x-9}" y="-100" width="18" height="210" fill="#fff" opacity=".9"/>`).join('')}</g><path d="M-42 -80 L-16 -94 Q0 -78 16 -94 L42 -80 L88 -38 L64 -6 L46 -24 V96 H-46 V-24 L-64 -6 L-88 -38Z" fill="none" ${st()}/><path d="M-16 -94 Q0 -78 16 -94" fill="none" ${st(C.navy,7)}/></g>`;

/* parents together: group of adults + shield */
P.e201_parents=(o,T,k)=>{const cs=[_e201MUM,_e201DAD,{c:'#4F7A5A',hair:'bun',hc:'#2A1D18'},{c:'#B07AA1',hair:'short',hc:'#BDC3C7'}];let s='';cs.forEach((p,i)=>{s+=_e201pr(Object.assign({ph:i*1.2},p),T,-96+i*64,34+(i%2?-8:0),.56)});
  return `<g>${s}<g transform="translate(0,-76) scale(.5)">${P.e109_shield({},T,9)}</g></g>`};

/* tip label */
